function processFile(filepath: string) {
    const buf = fs.readFileSync(filepath);

    // File header: "BM", u32 size, u16 reserved, u16 reserved, u32 bfOffBits
    const bfOffBits = buf.readUInt32LE(10);

    // DIB header
    const dibSize = buf.readUInt32LE(14);
    const width = buf.readInt32LE(18);
    const height = buf.readInt32LE(22);
    const bpp = buf.readUInt16LE(28);
    const compression = buf.readUInt32LE(30);
    const colorsUsed = buf.readUInt32LE(46);

    const absHeight = Math.abs(height);
    const bottomUp = height > 0;

    // Check compression
    if (compression !== 0 && compression !== 3) {
        console.log(`error: unsupported compression ${compression}`);
        return;
    }

    // For BI_BITFIELDS, get masks at offset 14 + 40 = 54
    let redMask = 0, greenMask = 0, blueMask = 0;
    if (compression === 3) {
        redMask = buf.readUInt32LE(54);
        greenMask = buf.readUInt32LE(58);
        blueMask = buf.readUInt32LE(62);
    }

    // Color table for indexed formats
    let colorTable: number[][] = [];
    if (bpp <= 8) {
        const numColors = colorsUsed > 0 ? colorsUsed : (1 << bpp);
        const tableOffset = 14 + dibSize;
        for (let i = 0; i < numColors; i++) {
            const off = tableOffset + i * 4;
            const b = buf[off];
            const g = buf[off + 1];
            const r = buf[off + 2];
            colorTable.push([r, g, b]);
        }
    }

    // Row stride: padded to multiple of 4 bytes
    const rowStride = Math.ceil(width * bpp / 32) * 4;

    // Decode pixels and determine ink
    const ink: boolean[][] = [];
    for (let y = 0; y < absHeight; y++) {
        ink.push(new Array(width).fill(false));
    }

    for (let y = 0; y < absHeight; y++) {
        const storedY = bottomUp ? (absHeight - 1 - y) : y;
        const rowOffset = bfOffBits + storedY * rowStride;

        for (let x = 0; x < width; x++) {
            let r = 0, g = 0, b = 0;

            if (bpp === 1) {
                const byteIdx = Math.floor(x / 8);
                const bitIdx = 7 - (x % 8);
                const idx = (buf[rowOffset + byteIdx] >> bitIdx) & 1;
                if (idx < colorTable.length) {
                    [r, g, b] = colorTable[idx];
                }
            } else if (bpp === 4) {
                const byteIdx = Math.floor(x / 2);
                const nibbleShift = (x % 2 === 0) ? 4 : 0;
                const idx = (buf[rowOffset + byteIdx] >> nibbleShift) & 0xF;
                if (idx < colorTable.length) {
                    [r, g, b] = colorTable[idx];
                }
            } else if (bpp === 8) {
                const idx = buf[rowOffset + x];
                if (idx < colorTable.length) {
                    [r, g, b] = colorTable[idx];
                }
            } else if (bpp === 24) {
                const off = rowOffset + x * 3;
                b = buf[off];
                g = buf[off + 1];
                r = buf[off + 2];
            } else if (bpp === 32) {
                const off = rowOffset + x * 4;
                const pixel = buf.readUInt32LE(off);
                if (compression === 3) {
                    r = extractChannel(pixel, redMask);
                    g = extractChannel(pixel, greenMask);
                    b = extractChannel(pixel, blueMask);
                } else {
                    b = buf[off];
                    g = buf[off + 1];
                    r = buf[off + 2];
                }
            }

            const luminance = Math.floor((299 * r + 587 * g + 114 * b) / 1000);
            ink[y][x] = luminance < 128;
        }
    }

    // Count ink pixels
    let inkCount = 0;
    for (let y = 0; y < absHeight; y++) {
        for (let x = 0; x < width; x++) {
            if (ink[y][x]) inkCount++;
        }
    }

    const orientation = bottomUp ? "bottom-up" : "top-down";
    console.log(`size ${width}x${absHeight} bpp ${bpp} header ${dibSize} ${orientation} ink ${inkCount}`);

    // Find connected components using BFS with 8-connectivity
    const visited: boolean[][] = [];
    for (let y = 0; y < absHeight; y++) {
        visited.push(new Array(width).fill(false));
    }

    interface Component {
        firstX: number; firstY: number;
        minX: number; minY: number; maxX: number; maxY: number;
        count: number;
    }
    const components: Component[] = [];

    const dx8 = [-1, 0, 1, -1, 1, -1, 0, 1];
    const dy8 = [-1, -1, -1, 0, 0, 1, 1, 1];

    for (let y = 0; y < absHeight; y++) {
        for (let x = 0; x < width; x++) {
            if (ink[y][x] && !visited[y][x]) {
                const queue: number[] = [x, y];
                visited[y][x] = true;
                let minX = x, minY = y, maxX = x, maxY = y, count = 0;
                let head = 0;

                while (head < queue.length) {
                    const cx = queue[head++];
                    const cy = queue[head++];
                    count++;
                    if (cx < minX) minX = cx;
                    if (cx > maxX) maxX = cx;
                    if (cy < minY) minY = cy;
                    if (cy > maxY) maxY = cy;

                    for (let d = 0; d < 8; d++) {
                        const nx = cx + dx8[d];
                        const ny = cy + dy8[d];
                        if (nx >= 0 && nx < width && ny >= 0 && ny < absHeight && ink[ny][nx] && !visited[ny][nx]) {
                            visited[ny][nx] = true;
                            queue.push(nx, ny);
                        }
                    }
                }

                components.push({ firstX: x, firstY: y, minX, minY, maxX, maxY, count });
            }
        }
    }

    console.log(`components ${components.length}`);
    for (const comp of components) {
        console.log(`${comp.firstX},${comp.firstY} bbox ${comp.minX},${comp.minY}-${comp.maxX},${comp.maxY} pixels ${comp.count}`);
    }
}

function extractChannel(pixel: number, mask: number): number {
    if (mask === 0) return 0;
    const s = trailingZeros(mask);
    const n = popcount(mask);
    const m = (1 << n) - 1;
    const v = (pixel & mask) >>> s;
    return Math.floor((v * 255 + Math.floor(m / 2)) / m);
}

function trailingZeros(x: number): number {
    if (x === 0) return 32;
    let count = 0;
    while ((x & 1) === 0) {
        count++;
        x >>>= 1;
    }
    return count;
}

function popcount(x: number): number {
    let count = 0;
    while (x) {
        count += x & 1;
        x >>>= 1;
    }
    return count;
}

import Foundation

func readU16(_ data: [UInt8], _ offset: Int) -> UInt16 {
    return UInt16(data[offset]) | (UInt16(data[offset + 1]) << 8)
}

func readU32(_ data: [UInt8], _ offset: Int) -> UInt32 {
    return UInt32(data[offset]) |
           (UInt32(data[offset + 1]) << 8) |
           (UInt32(data[offset + 2]) << 16) |
           (UInt32(data[offset + 3]) << 24)
}

func readI32(_ data: [UInt8], _ offset: Int) -> Int32 {
    return Int32(bitPattern: readU32(data, offset))
}

func trailingZeros(_ mask: UInt32) -> Int {
    if mask == 0 { return 0 }
    var count = 0
    var m = mask
    while m & 1 == 0 {
        count += 1
        m >>= 1
    }
    return count
}

func popcount(_ mask: UInt32) -> Int {
    var count = 0
    var m = mask
    while m != 0 {
        count += Int(m & 1)
        m >>= 1
    }
    return count
}

func extractChannel(_ pixel: UInt32, mask: UInt32) -> Int {
    if mask == 0 { return 0 }
    let s = trailingZeros(mask)
    let n = popcount(mask)
    let m: UInt32 = (1 << UInt32(n)) - 1
    let v = (pixel & mask) >> UInt32(s)
    return Int((v &* 255 &+ m / 2) / m)
}

func processFile(path: String, name: String) {
    guard let fileData = FileManager.default.contents(atPath: path) else { return }
    let data = [UInt8](fileData)
    if data.count < 14 { return }

    let bfOffBits = Int(readU32(data, 10))

    let dibOffset = 14
    if data.count < dibOffset + 4 { return }
    let dibSize = Int(readU32(data, dibOffset))
    let width = Int(readI32(data, dibOffset + 4))
    let heightRaw = Int(readI32(data, dibOffset + 8))
    let height = abs(heightRaw)
    let bottomUp = heightRaw > 0
    let bpp = Int(readU16(data, dibOffset + 14))
    let compression = Int(readU32(data, dibOffset + 16))
    let colorsUsed = Int(readU32(data, dibOffset + 32))

    if compression != 0 && compression != 3 {
        print("== \(name)")
        print("error: unsupported compression \(compression)")
        return
    }

    var redMask: UInt32 = 0
    var greenMask: UInt32 = 0
    var blueMask: UInt32 = 0

    if compression == 3 {
        if dibSize == 40 {
            let maskOffset = dibOffset + dibSize
            redMask = readU32(data, maskOffset)
            greenMask = readU32(data, maskOffset + 4)
            blueMask = readU32(data, maskOffset + 8)
        } else {
            redMask = readU32(data, dibOffset + 40)
            greenMask = readU32(data, dibOffset + 44)
            blueMask = readU32(data, dibOffset + 48)
        }
    }

    var paletteR = [Int](), paletteG = [Int](), paletteB = [Int]()
    if bpp <= 8 {
        let paletteOffset = dibOffset + dibSize
        let numEntries = colorsUsed > 0 ? colorsUsed : (1 << bpp)
        paletteR.reserveCapacity(numEntries)
        paletteG.reserveCapacity(numEntries)
        paletteB.reserveCapacity(numEntries)
        for i in 0..<numEntries {
            let off = paletteOffset + i * 4
            paletteB.append(Int(data[off]))
            paletteG.append(Int(data[off + 1]))
            paletteR.append(Int(data[off + 2]))
        }
    }

    var rowBytes: Int
    switch bpp {
    case 1:  rowBytes = ((width + 7) / 8 + 3) / 4 * 4
    case 4:  rowBytes = ((width + 1) / 2 + 3) / 4 * 4
    case 8:  rowBytes = (width + 3) / 4 * 4
    case 24: rowBytes = (width * 3 + 3) / 4 * 4
    case 32: rowBytes = width * 4
    default: return
    }

    var ink = [Bool](repeating: false, count: width * height)
    var inkCount = 0

    for y in 0..<height {
        let storedRow = bottomUp ? (height - 1 - y) : y
        let rowOffset = bfOffBits + storedRow * rowBytes
        let rowBase = y * width

        for x in 0..<width {
            var r, g, b: Int

            switch bpp {
            case 1:
                let byteIdx = x / 8
                let bitIdx = 7 - (x % 8)
                let byte = data[rowOffset + byteIdx]
                let idx = Int((byte >> UInt8(bitIdx)) & 1)
                r = paletteR[idx]; g = paletteG[idx]; b = paletteB[idx]
            case 4:
                let byteIdx = x / 2
                let byte = data[rowOffset + byteIdx]
                let idx: Int
                if x % 2 == 0 {
                    idx = Int((byte >> 4) & 0xF)
                } else {
                    idx = Int(byte & 0xF)
                }
                r = paletteR[idx]; g = paletteG[idx]; b = paletteB[idx]
            case 8:
                let idx = Int(data[rowOffset + x])
                r = paletteR[idx]; g = paletteG[idx]; b = paletteB[idx]
            case 24:
                let off = rowOffset + x * 3
                b = Int(data[off]); g = Int(data[off + 1]); r = Int(data[off + 2])
            case 32:
                let off = rowOffset + x * 4
                let pixel = readU32(data, off)
                if compression == 3 {
                    r = extractChannel(pixel, mask: redMask)
                    g = extractChannel(pixel, mask: greenMask)
                    b = extractChannel(pixel, mask: blueMask)
                } else {
                    b = Int(data[off]); g = Int(data[off + 1]); r = Int(data[off + 2])
                }
            default:
                r = 0; g = 0; b = 0
            }

            let lum = (299 * r + 587 * g + 114 * b) / 1000
            if lum < 128 {
                ink[rowBase + x] = true
                inkCount += 1
            }
        }
    }

    var visited = [Bool](repeating: false, count: width * height)
    var components: [(fx: Int, fy: Int, minX: Int, minY: Int, maxX: Int, maxY: Int, count: Int)] = []

    let dx = [-1, 0, 1, -1, 1, -1, 0, 1]
    let dy = [-1, -1, -1, 0, 0, 1, 1, 1]

    for y in 0..<height {
        for x in 0..<width {
            let idx = y * width + x
            if ink[idx] && !visited[idx] {
                var queue = [Int]()
                var head = 0
                queue.append(idx)
                visited[idx] = true
                var minX = x, maxX = x, minY = y, maxY = y
                var count = 0

                while head < queue.count {
                    let ci = queue[head]
                    head += 1
                    let cx = ci % width
                    let cy = ci / width
                    count += 1
                    if cx < minX { minX = cx }
                    if cx > maxX { maxX = cx }
                    if cy < minY { minY = cy }
                    if cy > maxY { maxY = cy }

                    for d in 0..<8 {
                        let nx = cx + dx[d]
                        let ny = cy + dy[d]
                        if nx >= 0 && nx < width && ny >= 0 && ny < height {
                            let ni = ny * width + nx
                            if ink[ni] && !visited[ni] {
                                visited[ni] = true
                                queue.append(ni)
                            }
                        }
                    }
                }

                components.append((fx: x, fy: y, minX: minX, minY: minY, maxX: maxX, maxY: maxY, count: count))
            }
        }
    }

    let orientation = bottomUp ? "bottom-up" : "top-down"
    print("== \(name)")
    print("size \(width)x\(height) bpp \(bpp) header \(dibSize) \(orientation) ink \(inkCount)")
    print("components \(components.count)")
    for comp in components {
        print("\(comp.fx),\(comp.fy) bbox \(comp.minX),\(comp.minY)-\(comp.maxX),\(comp.maxY) pixels \(comp.count)")
    }
}

