fn main() {
    let args: Vec<String> = std::env::args().collect();
    let dir = &args[1];

    let mut files: Vec<String> = Vec::new();
    for entry in fs::read_dir(dir).unwrap() {
        let entry = entry.unwrap();
        let name = entry.file_name().to_str().unwrap().to_string();
        if name.ends_with(".bmp") {
