const dir = process.argv[2];

const config = JSON.parse(fs.readFileSync(path.join(dir, 'config.json'), 'utf-8'));
const tokensRaw = fs.readFileSync(path.join(dir, 'tokens.txt'), 'utf-8');

const now: number = config.now;
const leeway: number = config.leeway;
const issuer: string = config.issuer;
const audience: string = config.audience;

const keyMap: Map<string, { kid: string; kty: string; alg: string; k: string }> = new Map();
for (const key of config.keys) {
    keyMap.set(key.kid, key);
}

// Parse tokens: split by \n, trim each line, skip empty
const rawLines = tokensRaw.split('\n');
const tokens: string[] = [];
for (const line of rawLines) {
    const trimmed = line.trim();
    if (trimmed.length > 0) {
        tokens.push(trimmed);
    }
}

function isValidBase64url(s: string): boolean {
    if (s.length === 0) return false;
    if (s.length % 4 === 1) return false;
    for (let i = 0; i < s.length; i++) {
        const c = s.charCodeAt(i);
        const isUpper = c >= 65 && c <= 90;
        const isLower = c >= 97 && c <= 122;
        const isDigit = c >= 48 && c <= 57;
        const isDash = c === 45;
        const isUnderscore = c === 95;
        if (!isUpper && !isLower && !isDigit && !isDash && !isUnderscore) {
            return false;
        }
    }
    return true;
}

function base64urlDecode(s: string): Buffer {
    let b64 = s.replace(/-/g, '+').replace(/_/g, '/');
    const remainder = b64.length % 4;
    if (remainder === 2) b64 += '==';
    else if (remainder === 3) b64 += '=';
    return Buffer.from(b64, 'base64');
}

function algToHash(alg: string): string {
    if (alg === 'HS256') return 'sha256';
    if (alg === 'HS384') return 'sha384';
    if (alg === 'HS512') return 'sha512';
    return '';
}

function checkToken(token: string): string {
    // Rule 1: MALFORMED
    const dotCount = token.split('.').length - 1;
    if (dotCount !== 2) return 'MALFORMED';

    const parts = token.split('.');
    const [headerSeg, payloadSeg, sigSeg] = parts;

    if (!isValidBase64url(headerSeg) || !isValidBase64url(payloadSeg) || !isValidBase64url(sigSeg)) {
        return 'MALFORMED';
    }

    let header: any;
    let payload: any;
    try {
        const headerJson = base64urlDecode(headerSeg).toString('utf-8');
        header = JSON.parse(headerJson);
        if (typeof header !== 'object' || header === null || Array.isArray(header)) return 'MALFORMED';

        const payloadJson = base64urlDecode(payloadSeg).toString('utf-8');
        payload = JSON.parse(payloadJson);
        if (typeof payload !== 'object' || payload === null || Array.isArray(payload)) return 'MALFORMED';
    } catch {
        return 'MALFORMED';
    }

    // Rule 2: UNSUPPORTED_ALG
    if (typeof header.alg !== 'string' || !['HS256', 'HS384', 'HS512'].includes(header.alg)) {
        return 'UNSUPPORTED_ALG';
    }

    // Rule 3: UNKNOWN_KEY
    if (typeof header.kid !== 'string' || !keyMap.has(header.kid)) {
        return 'UNKNOWN_KEY';
    }

    const key = keyMap.get(header.kid)!;

    // Rule 4: ALG_MISMATCH
    if (key.alg !== header.alg) {
        return 'ALG_MISMATCH';
    }

    // Rule 5: BAD_SIGNATURE
    const signingInput = headerSeg + '.' + payloadSeg;
    const secret = base64urlDecode(key.k);
    const hashAlg = algToHash(header.alg);
    const expectedSig = crypto.createHmac(hashAlg, secret).update(signingInput, 'ascii').digest();
    const actualSig = base64urlDecode(sigSeg);

    if (expectedSig.length !== actualSig.length || !crypto.timingSafeEqual(expectedSig, actualSig)) {
        return 'BAD_SIGNATURE';
    }

    // Rule 6: EXPIRED
    if ('exp' in payload) {
        if (now >= payload.exp + leeway) {
            return 'EXPIRED';
        }
    }

    // Rule 7: NOT_YET_VALID
    if ('nbf' in payload) {
        if (now + leeway < payload.nbf) {
            return 'NOT_YET_VALID';
        }
    }

    // Rule 8: BAD_ISSUER
    if (!('iss' in payload) || payload.iss !== issuer) {
        return 'BAD_ISSUER';
    }

    // Rule 9: BAD_AUDIENCE
    if (!('aud' in payload)) {
        return 'BAD_AUDIENCE';
    }
    if (typeof payload.aud === 'string') {
        if (payload.aud !== audience) return 'BAD_AUDIENCE';
    } else if (Array.isArray(payload.aud)) {
        if (!payload.aud.some((a: any) => a === audience)) return 'BAD_AUDIENCE';
    } else {
        return 'BAD_AUDIENCE';
    }

    // VALID
    const sub: string = payload.sub;
    let scopes = '';
    if (typeof payload.scope === 'string') {
        const scopeParts = payload.scope.split(' ').filter(s => s.length > 0);
        const unique = [...new Set(scopeParts)];
        unique.sort((a, b) => {
            if (a < b) return -1;
            if (a > b) return 1;
            return 0;
        });
        scopes = unique.join(',');
    }

    return `VALID sub=${sub} scope=${scopes}`;
}

