        validCount++;
    } else {
        invalidCount++;
    }
}

console.log('');
console.log(`valid=${validCount} invalid=${invalidCount}`);

import Foundation
import CryptoKit

func isValidBase64url(_ s: String) -> Bool {
    for c in s.unicodeScalars {
        let v = c.value
        if (v >= 65 && v <= 90) || (v >= 97 && v <= 122) || (v >= 48 && v <= 57) || c == "-" || c == "_" {
            continue
        }
        return false
    }
    if s.unicodeScalars.count % 4 == 1 { return false }
    return true
}

func base64urlDecode(_ s: String) -> Data? {
    var base64 = s.replacingOccurrences(of: "-", with: "+")
                  .replacingOccurrences(of: "_", with: "/")
    let remainder = base64.count % 4
    if remainder > 0 {
        base64 += String(repeating: "=", count: 4 - remainder)
    }
    return Data(base64Encoded: base64)
}

func checkToken(_ token: String, keySet: [String: (alg: String, secret: Data)], now: Double, leeway: Double, issuer: String, audience: String) -> String {
    // Rule 1: MALFORMED
    let segments = token.components(separatedBy: ".")
    if segments.count != 3 { return "MALFORMED" }

    for seg in segments {
        if seg.isEmpty { return "MALFORMED" }
        if !isValidBase64url(seg) { return "MALFORMED" }
    }

    guard let headerData = base64urlDecode(segments[0]) else { return "MALFORMED" }
    guard let payloadData = base64urlDecode(segments[1]) else { return "MALFORMED" }
    guard let sigData = base64urlDecode(segments[2]) else { return "MALFORMED" }

    let h = try? JSONSerialization.jsonObject(with: headerData)
    guard let headerObj = h as? [String: Any] else { return "MALFORMED" }

    let p = try? JSONSerialization.jsonObject(with: payloadData)
    guard let payloadObj = p as? [String: Any] else { return "MALFORMED" }

    // Rule 2: UNSUPPORTED_ALG
    guard let alg = headerObj["alg"] as? String else { return "UNSUPPORTED_ALG" }
    if alg != "HS256" && alg != "HS384" && alg != "HS512" { return "UNSUPPORTED_ALG" }

    // Rule 3: UNKNOWN_KEY
    guard let kid = headerObj["kid"] as? String else { return "UNKNOWN_KEY" }
    guard let key = keySet[kid] else { return "UNKNOWN_KEY" }

    // Rule 4: ALG_MISMATCH
    if key.alg != alg { return "ALG_MISMATCH" }

    // Rule 5: BAD_SIGNATURE
    let signingInput = Data((segments[0] + "." + segments[1]).utf8)
    let symKey = SymmetricKey(data: key.secret)
    let expectedSig: Data
    switch alg {
    case "HS256":
        expectedSig = Data(HMAC<SHA256>.authenticationCode(for: signingInput, using: symKey))
    case "HS384":
        expectedSig = Data(HMAC<SHA384>.authenticationCode(for: signingInput, using: symKey))
    case "HS512":
        expectedSig = Data(HMAC<SHA512>.authenticationCode(for: signingInput, using: symKey))
    default:
        return "BAD_SIGNATURE"
    }
    if sigData != expectedSig { return "BAD_SIGNATURE" }

    // Rule 6: EXPIRED
    if let exp = payloadObj["exp"] as? NSNumber {
        if now >= exp.doubleValue + leeway { return "EXPIRED" }
    }

    // Rule 7: NOT_YET_VALID
    if let nbf = payloadObj["nbf"] as? NSNumber {
        if now + leeway < nbf.doubleValue { return "NOT_YET_VALID" }
    }

    // Rule 8: BAD_ISSUER
    guard let iss = payloadObj["iss"] as? String else { return "BAD_ISSUER" }
    if iss != issuer { return "BAD_ISSUER" }

    // Rule 9: BAD_AUDIENCE
    guard let aud = payloadObj["aud"] else { return "BAD_AUDIENCE" }
    if let audStr = aud as? String {
        if audStr != audience { return "BAD_AUDIENCE" }
    } else if let audArr = aud as? [Any] {
        var found = false
        for elem in audArr {
            if let s = elem as? String, s == audience {
                found = true
                break
            }
        }
        if !found { return "BAD_AUDIENCE" }
    } else {
        return "BAD_AUDIENCE"
    }

    // VALID
    let sub = payloadObj["sub"] as? String ?? ""
    let scopeStr = payloadObj["scope"] as? String ?? ""
    var scopes = scopeStr.split(separator: " ").map(String.init)
    scopes = Array(Set(scopes))
    scopes.sort { a, b in
        let ua = Array(a.unicodeScalars)
        let ub = Array(b.unicodeScalars)
        return ua.lexicographicallyPrecedes(ub)
    }
    let scopesJoined = scopes.joined(separator: ",")

    return "VALID sub=\(sub) scope=\(scopesJoined)"
}

