import Foundation

// BigUInt: non-negative integer, base 10, least significant digit first
struct BigUInt: Equatable, Comparable {
    var d: [UInt8] // LSD first, empty = zero

    init() { d = [] }
    init(_ v: UInt64) {
        d = []
        if v == 0 { return }
        var x = v
        while x > 0 { d.append(UInt8(x % 10)); x /= 10 }
    }
    init(digits: [UInt8]) { d = digits; normalize() }
    init(_ s: String) {
        d = []
        for c in s.reversed() { d.append(UInt8(c.asciiValue! - 48)) }
        normalize()
    }

    mutating func normalize() {
        while d.count > 1 && d.last == 0 { d.removeLast() }
        if d.count == 1 && d[0] == 0 { d = [] }
    }

    var isZero: Bool { d.isEmpty }

    static func == (a: BigUInt, b: BigUInt) -> Bool {
        if a.d.count != b.d.count { return false }
        for i in 0..<a.d.count { if a.d[i] != b.d[i] { return false } }
        return true
    }

    static func < (a: BigUInt, b: BigUInt) -> Bool {
        if a.d.count != b.d.count { return a.d.count < b.d.count }
        for i in stride(from: a.d.count - 1, through: 0, by: -1) {
            if a.d[i] != b.d[i] { return a.d[i] < b.d[i] }
        }
        return false
    }

    static func + (a: BigUInt, b: BigUInt) -> BigUInt {
        let n = max(a.d.count, b.d.count)
        var r = [UInt8](repeating: 0, count: n + 1)
        var carry: UInt16 = 0
        for i in 0..<n {
            let s = (i < a.d.count ? UInt16(a.d[i]) : 0) + (i < b.d.count ? UInt16(b.d[i]) : 0) + carry
            r[i] = UInt8(s % 10); carry = s / 10
        }
        r[n] = UInt8(carry)
        return BigUInt(digits: r)
    }

    static func - (a: BigUInt, b: BigUInt) -> BigUInt {
        var r = [UInt8](repeating: 0, count: a.d.count)
        var borrow: Int16 = 0
        for i in 0..<a.d.count {
            let av = Int16(a.d[i])
            let bv = i < b.d.count ? Int16(b.d[i]) : 0
            var diff = av - bv - borrow
            if diff < 0 { diff += 10; borrow = 1 } else { borrow = 0 }
            r[i] = UInt8(diff)
        }
        return BigUInt(digits: r)
    }

    static func * (a: BigUInt, b: BigUInt) -> BigUInt {
        if a.isZero || b.isZero { return BigUInt() }
        let n = a.d.count + b.d.count
        var r = [UInt16](repeating: 0, count: n)
        for i in 0..<a.d.count {
            var carry: UInt16 = 0
            for j in 0..<b.d.count {
                let prod = UInt16(a.d[i]) * UInt16(b.d[j]) + r[i + j] + carry
                r[i + j] = prod % 10; carry = prod / 10
            }
            r[i + b.d.count] += carry
        }
        return BigUInt(digits: r.map { UInt8($0) })
    }

    func timesPow10(_ k: Int) -> BigUInt {
        if isZero || k == 0 { return self }
        return BigUInt(digits: [UInt8](repeating: 0, count: k) + d)
    }

    func isOdd() -> Bool { !d.isEmpty && d[0] % 2 == 1 }

    func toString() -> String {
        if isZero { return "0" }
        return String(d.reversed().map { Character(UnicodeScalar($0 + 48)) })
    }

    func divPow10(_ k: Int) -> (BigUInt, BigUInt) {
        if k == 0 { return (self, BigUInt()) }
        if d.count <= k { return (BigUInt(), self) }
        return (BigUInt(digits: Array(d[k...])), BigUInt(digits: Array(d[0..<k])))
    }

    func divmod(_ divisor: BigUInt) -> (BigUInt, BigUInt) {
        if divisor.isZero { fatalError("div by zero") }
        if self < divisor { return (BigUInt(), self) }
        if divisor == BigUInt(1) { return (self, BigUInt()) }

        let aMS = Array(d.reversed())
        let bMS = Array(divisor.d.reversed())

        var quotient = [UInt8]()
        var remainder: [UInt8] = []

        for i in 0..<aMS.count {
            remainder.append(aMS[i])
            while remainder.count > 1 && remainder[0] == 0 { remainder.removeFirst() }
            if remainder.count == 1 && remainder[0] == 0 { quotient.append(0); continue }
            var q: UInt8 = 0
            while compareMS(remainder, bMS) >= 0 {
                remainder = subMS(remainder, bMS); q += 1
            }
            quotient.append(q)
        }

        while quotient.count > 1 && quotient[0] == 0 { quotient.removeFirst() }
        if quotient.count == 1 && quotient[0] == 0 { quotient = [] }

        var qBig = BigUInt()
        if !quotient.isEmpty { qBig.d = Array(quotient.reversed()); qBig.normalize() }
        var rBig = BigUInt()
        if !remainder.isEmpty && !(remainder.count == 1 && remainder[0] == 0) {
            rBig.d = Array(remainder.reversed()); rBig.normalize()
        }
        return (qBig, rBig)
    }
}

func compareMS(_ a: [UInt8], _ b: [UInt8]) -> Int {
    var aa = a, bb = b
    while aa.count > 1 && aa[0] == 0 { aa.removeFirst() }
    while bb.count > 1 && bb[0] == 0 { bb.removeFirst() }
    if aa.count != bb.count { return aa.count < bb.count ? -1 : 1 }
    for i in 0..<aa.count { if aa[i] != bb[i] { return aa[i] < bb[i] ? -1 : 1 } }
    return 0
}

func subMS(_ a: [UInt8], _ b: [UInt8]) -> [UInt8] {
    var result = [UInt8](repeating: 0, count: a.count)
    var borrow: Int8 = 0
    for i in stride(from: a.count - 1, through: 0, by: -1) {
        let bi = i < b.count ? Int8(b[i]) : 0
        var diff = Int8(a[i]) - bi - borrow
        if diff < 0 { diff += 10; borrow = 1 } else { borrow = 0 }
        result[i] = UInt8(diff)
    }
    while result.count > 1 && result[0] == 0 { result.removeFirst() }
    return result
}

// Decimal number: value = (-1)^neg * val / 10^scale
struct Dec {
    var neg: Bool
    var val: BigUInt
    var scale: Int
    var isZero: Bool { val.isZero }
    func normalized() -> Dec {
        if val.isZero { return Dec(neg: false, val: BigUInt(), scale: scale) }
        return self
    }
}

func decAdd(_ a: Dec, _ b: Dec) -> Dec {
    let s = max(a.scale, b.scale)
    let av = a.val.timesPow10(s - a.scale)
    let bv = b.val.timesPow10(s - b.scale)
    if a.neg == b.neg {
        let sum = av + bv
        return Dec(neg: a.neg && !sum.isZero, val: sum, scale: s).normalized()
    }
    if av >= bv {
        let diff = av - bv
        return Dec(neg: a.neg && !diff.isZero, val: diff, scale: s).normalized()
    } else {
        let diff = bv - av
        return Dec(neg: b.neg && !diff.isZero, val: diff, scale: s).normalized()
    }
}

func decSub(_ a: Dec, _ b: Dec) -> Dec {
    return decAdd(a, Dec(neg: !b.neg, val: b.val, scale: b.scale))
}

func decMul(_ a: Dec, _ b: Dec) -> Dec {
    let product = a.val * b.val
    return Dec(neg: (a.neg != b.neg) && !product.isZero, val: product, scale: a.scale + b.scale)
}

func decRound(_ d: Dec, to places: Int) -> Dec {
    if d.scale == places { return d.normalized() }
    if d.scale < places {
        return Dec(neg: d.neg, val: d.val.timesPow10(places - d.scale), scale: places).normalized()
    }
    let k = d.scale - places
    let (q, r) = d.val.divPow10(k)
    let half = BigUInt(5).timesPow10(k - 1)
    var result = q
    if r > half { result = q + BigUInt(1) }
    else if r == half && q.isOdd() { result = q + BigUInt(1) }
    return Dec(neg: d.neg && !result.isZero, val: result, scale: places).normalized()
}

func decCmp(_ a: Dec, _ b: Dec) -> Int {
    let s = max(a.scale, b.scale)
    let av = a.val.timesPow10(s - a.scale)
    let bv = b.val.timesPow10(s - b.scale)
    if a.neg && !b.neg { return -1 }
    if !a.neg && b.neg { return 1 }
    if a.neg && b.neg {
        if av < bv { return 1 }
        if av > bv { return -1 }
        return 0
    }
    if av < bv { return -1 }
    if av > bv { return 1 }
    return 0
}

func decParse(_ s: String) -> Dec {
    var neg = false
    var i = s.startIndex
    if i < s.endIndex && s[i] == "-" { neg = true; i = s.index(after: i) }
    var digits = ""
    var scale = 0
    var inFrac = false
    while i < s.endIndex {
        if s[i] == "." { inFrac = true }
        else {
            digits.append(s[i])
            if inFrac { scale += 1 }
        }
        i = s.index(after: i)
    }
    let val = BigUInt(digits.isEmpty ? "0" : digits)
    return Dec(neg: neg && !val.isZero, val: val, scale: scale)
}

func formatMoney(neg: Bool, val: BigUInt, minorUnits: Int) -> String {
    if val.isZero {
        if minorUnits == 0 { return "0" }
        return "0." + String(repeating: "0", count: minorUnits)
    }
    let prefix = neg ? "-" : ""
    if minorUnits == 0 {
        return prefix + formatCommas(val.toString())
    }
    let pow10 = BigUInt(1).timesPow10(minorUnits)
    let (intPart, fracPart) = val.divmod(pow10)
    let intStr = intPart.isZero ? "0" : intPart.toString()
    let fracStr = fracPart.isZero ? String(repeating: "0", count: minorUnits) : fracPart.toString()
    let padded = fracStr.count >= minorUnits ? fracStr : String(repeating: "0", count: minorUnits - fracStr.count) + fracStr
    return prefix + formatCommas(intStr) + "." + padded
}

func formatCommas(_ s: String) -> String {
    let chars = Array(s)
    var result = ""
    for (i, c) in chars.enumerated() {
        if i > 0 && (chars.count - i) % 3 == 0 { result.append(",") }
        result.append(c)
    }
    return result
}

// Main program
let args = CommandLine.arguments
let dir = args[1]
let path = dir + "/ledger.txt"
let content = try! String(contentsOfFile: path, encoding: .utf8)
let lines = content.components(separatedBy: "\n")

var currencies: [String: Int] = [:]
var accounts: [String: (code: String, bal: Dec, limit: Dec)] = [:]
var rejections: [(Int, String)] = []

for (lineNum, line) in lines.enumerated() {
    let ln = lineNum + 1
    let trimmed = line.trimmingCharacters(in: .whitespaces)
    if trimmed.isEmpty || trimmed.hasPrefix("#") { continue }

    let fields = trimmed.components(separatedBy: .whitespaces).filter { !$0.isEmpty }
    guard !fields.isEmpty else { continue }
    let cmd = fields[0]

    switch cmd {
    case "currency":
        let code = fields[1]
        let mu = Int(fields[2])!
        currencies[code] = mu

    case "open":
        let name = fields[1]
        let code = fields[2]
        if accounts[name] != nil {
            rejections.append((ln, "account exists \(name)"))
            continue
        }
        let mu = currencies[code]!
        var limit = Dec(neg: false, val: BigUInt(), scale: mu)
        if fields.count >= 4 {
            let rawLimit = decParse(fields[3])
            limit = decRound(rawLimit, to: mu)
        }
        accounts[name] = (code: code, bal: Dec(neg: false, val: BigUInt(), scale: mu), limit: limit)

    case "deposit":
        let name = fields[1]
        guard let acct = accounts[name] else {
            rejections.append((ln, "unknown account \(name)"))
            continue
        }
        let mu = currencies[acct.code]!
        let amount = decRound(decParse(fields[2]), to: mu)
        if amount.neg || amount.isZero {
            rejections.append((ln, "non-positive amount"))
            continue
        }
        var a = acct
        a.bal = decAdd(a.bal, amount)
        accounts[name] = a

    case "withdraw":
        let name = fields[1]
        guard let acct = accounts[name] else {
            rejections.append((ln, "unknown account \(name)"))
            continue
        }
        let mu = currencies[acct.code]!
        let amount = decRound(decParse(fields[2]), to: mu)
        if amount.neg || amount.isZero {
            rejections.append((ln, "non-positive amount"))
            continue
        }
        let sum = decAdd(acct.bal, acct.limit)
        if decCmp(sum, amount) < 0 {
            rejections.append((ln, "insufficient funds \(name)"))
            continue
        }
        var a = acct
        a.bal = decSub(a.bal, amount)
        accounts[name] = a

    case "transfer":
        let fromName = fields[1]
        let toName = fields[2]
        if accounts[fromName] == nil {
            rejections.append((ln, "unknown account \(fromName)"))
            continue
        }
        if accounts[toName] == nil {
            rejections.append((ln, "unknown account \(toName)"))
            continue
        }
        let fromAcct = accounts[fromName]!
        let toAcct = accounts[toName]!
        if fromAcct.code != toAcct.code {
            rejections.append((ln, "currency mismatch"))
            continue
        }
        let mu = currencies[fromAcct.code]!
        let amount = decRound(decParse(fields[3]), to: mu)
        if amount.neg || amount.isZero {
            rejections.append((ln, "non-positive amount"))
            continue
        }
        let sum = decAdd(fromAcct.bal, fromAcct.limit)
        if decCmp(sum, amount) < 0 {
            rejections.append((ln, "insufficient funds \(fromName)"))
            continue
        }
        var fa = fromAcct; fa.bal = decSub(fa.bal, amount)
        var ta = toAcct; ta.bal = decAdd(ta.bal, amount)
        accounts[fromName] = fa
        accounts[toName] = ta

    case "convert":
        let fromName = fields[1]
        let toName = fields[2]
        if accounts[fromName] == nil {
            rejections.append((ln, "unknown account \(fromName)"))
            continue
        }
        if accounts[toName] == nil {
            rejections.append((ln, "unknown account \(toName)"))
            continue
        }
        let fromAcct = accounts[fromName]!
        let toAcct = accounts[toName]!
        let fromMu = currencies[fromAcct.code]!
        let toMu = currencies[toAcct.code]!
        let amount = decRound(decParse(fields[3]), to: fromMu)
        if amount.neg || amount.isZero {
            rejections.append((ln, "non-positive amount"))
            continue
        }
        let sum = decAdd(fromAcct.bal, fromAcct.limit)
        if decCmp(sum, amount) < 0 {
            rejections.append((ln, "insufficient funds \(fromName)"))
            continue
        }
        let rate = decParse(fields[4])
        let converted = decRound(decMul(amount, rate), to: toMu)
        var fa = fromAcct; fa.bal = decSub(fa.bal, amount)
        var ta = toAcct; ta.bal = decAdd(ta.bal, converted)
        accounts[fromName] = fa
        accounts[toName] = ta

    case "interest":
        let name = fields[1]
        guard let acct = accounts[name] else {
            rejections.append((ln, "unknown account \(name)"))
            continue
        }
        let mu = currencies[acct.code]!
        let rate = decParse(fields[2])
        let interest = decRound(decMul(acct.bal, rate), to: mu)
        var a = acct
        a.bal = decAdd(a.bal, interest)
        accounts[name] = a

    case "split":
        let fromName = fields[1]
        // Parse targets: fields[3...] are "name:weight"
        var targetNames: [String] = []
        var targetWeights: [BigUInt] = []
        for i in 3..<fields.count {
            let parts = fields[i].components(separatedBy: ":")
            targetNames.append(parts[0])
            targetWeights.append(BigUInt(parts[1]))
        }
        // Check unknown accounts in order
        var unknownFound = false
        if accounts[fromName] == nil {
            rejections.append((ln, "unknown account \(fromName)"))
            unknownFound = true
        }
        if !unknownFound {
            for tn in targetNames {
                if accounts[tn] == nil {
                    rejections.append((ln, "unknown account \(tn)"))
                    unknownFound = true
                    break
                }
            }
        }
        if unknownFound { continue }

        let fromAcct = accounts[fromName]!
        let fromCode = fromAcct.code
        // Check currency mismatch
        var mismatch = false
        for tn in targetNames {
            if accounts[tn]!.code != fromCode {
                mismatch = true
                break
            }
        }
        if mismatch {
            rejections.append((ln, "currency mismatch"))
            continue
        }

        let mu = currencies[fromCode]!
        let amount = decRound(decParse(fields[2]), to: mu)
        if amount.neg || amount.isZero {
            rejections.append((ln, "non-positive amount"))
            continue
        }
        let sum = decAdd(fromAcct.bal, fromAcct.limit)
        if decCmp(sum, amount) < 0 {
            rejections.append((ln, "insufficient funds \(fromName)"))
            continue
        }

        // Distribute
        let A = amount.val // amount in minor units (positive)
        var W = BigUInt()
        for w in targetWeights { W = W + w }

        var shares: [BigUInt] = []
        var remainders: [BigUInt] = []
        for w in targetWeights {
            let product = A * w
            let (q, r) = product.divmod(W)
            shares.append(q)
            remainders.append(r)
        }

        // Compute leftover
        var totalGiven = BigUInt()
        for s in shares { totalGiven = totalGiven + s }
        let leftover = A - totalGiven
        let L = leftover.d.count == 0 ? 0 : Int(leftover.toString())!

        // Sort indices by remainder descending, then by index ascending
        var indices = Array(0..<targetNames.count)
        indices.sort { i, j in
            if remainders[i] != remainders[j] { return remainders[i] > remainders[j] }
            return i < j
        }

        // Give one extra unit to first L targets
        var finalShares = shares
        for i in 0..<L {
            finalShares[indices[i]] = finalShares[indices[i]] + BigUInt(1)
        }

        // Apply
        var fa = fromAcct
        fa.bal = decSub(fa.bal, amount)
        accounts[fromName] = fa

        for i in 0..<targetNames.count {
            let tn = targetNames[i]
            let share = finalShares[i]
            let shareDec = Dec(neg: false, val: share, scale: mu)
            var ta = accounts[tn]!
            ta.bal = decAdd(ta.bal, shareDec)
            accounts[tn] = ta
        }

    default:
        break
    }
}

// Output
for (ln, reason) in rejections {
    print("line \(ln): REJECT \(reason)")
}
print("")

let sortedAccounts = accounts.keys.sorted()
for name in sortedAccounts {
    let acct = accounts[name]!
    let mu = currencies[acct.code]!
    let balStr = formatMoney(neg: acct.bal.neg, val: acct.bal.val, minorUnits: mu)
    print("\(name) \(acct.code) \(balStr)")
}
print("")

// Currency totals
var currencyTotals: [String: (neg: Bool, val: BigUInt, count: Int)] = [:]
for name in sortedAccounts {
    let acct = accounts[name]!
    let code = acct.code
    if currencyTotals[code] == nil {
        currencyTotals[code] = (neg: false, val: BigUInt(), count: 0)
    }
    var ct = currencyTotals[code]!
    ct.count += 1
    // Add balance to total
    if acct.bal.neg == ct.neg {
        ct.val = ct.val + acct.bal.val
    } else {
        if acct.bal.val >= ct.val {
            ct.val = acct.bal.val - ct.val
            ct.neg = acct.bal.neg
        } else {
            ct.val = ct.val - acct.bal.val
        }
    }
    if ct.val.isZero { ct.neg = false }
    currencyTotals[code] = ct
}

let sortedCurrencies = currencyTotals.keys.sorted()
for code in sortedCurrencies {
    let ct = currencyTotals[code]!
    let mu = currencies[code]!
    let totalStr = formatMoney(neg: ct.neg, val: ct.val, minorUnits: mu)
    print("total \(code) \(totalStr) (\(ct.count) accounts)")
}

import Foundation

// BigUInt: non-negative integer, base 10, LSD first
struct BigUInt: Equatable, Comparable {
    var d: [UInt8] // LSD first, empty = zero

    init() { d = [] }
    init(_ v: UInt64) {
        d = []
        if v == 0 { return }
        var x = v
        while x > 0 { d.append(UInt8(x % 10)); x /= 10 }
    }
    init(digits: [UInt8]) { d = digits; normalize() }
    init(_ s: String) {
        d = []
        for c in s.reversed() { d.append(UInt8(c.asciiValue! - 48)) }
        normalize()
    }

    mutating func normalize() {
        while d.count > 1 && d.last == 0 { d.removeLast() }
        if d.count == 1 && d[0] == 0 { d = [] }
    }

    var isZero: Bool { d.isEmpty }

    static func == (a: BigUInt, b: BigUInt) -> Bool { a.d == b.d }

    static func < (a: BigUInt, b: BigUInt) -> Bool {
        if a.d.count != b.d.count { return a.d.count < b.d.count }
        for i in stride(from: a.d.count - 1, through: 0, by: -1) {
            if a.d[i] != b.d[i] { return a.d[i] < b.d[i] }
        }
        return false
    }

    static func + (a: BigUInt, b: BigUInt) -> BigUInt {
        let n = max(a.d.count, b.d.count)
        var r = [UInt8](repeating: 0, count: n + 1)
        var carry: UInt16 = 0
        for i in 0..<n {
            let s = (i < a.d.count ? UInt16(a.d[i]) : 0) + (i < b.d.count ? UInt16(b.d[i]) : 0) + carry
            r[i] = UInt8(s % 10); carry = s / 10
        }
        r[n] = UInt8(carry)
        return BigUInt(digits: r)
    }

    static func - (a: BigUInt, b: BigUInt) -> BigUInt {
        var r = [UInt8](repeating: 0, count: a.d.count)
        var borrow: Int16 = 0
        for i in 0..<a.d.count {
            let av = Int16(a.d[i])
            let bv = i < b.d.count ? Int16(b.d[i]) : 0
            var diff = av - bv - borrow
            if diff < 0 { diff += 10; borrow = 1 } else { borrow = 0 }
            r[i] = UInt8(diff)
        }
        return BigUInt(digits: r)
    }

    static func * (a: BigUInt, b: BigUInt) -> BigUInt {
        if a.isZero || b.isZero { return BigUInt() }
        let n = a.d.count + b.d.count
        var r = [UInt16](repeating: 0, count: n)
        for i in 0..<a.d.count {
            var carry: UInt16 = 0
            for j in 0..<b.d.count {
                let prod = UInt16(a.d[i]) * UInt16(b.d[j]) + r[i + j] + carry
                r[i + j] = prod % 10; carry = prod / 10
            }
            r[i + b.d.count] += carry
        }
        return BigUInt(digits: r.map { UInt8($0) })
    }

    func timesPow10(_ k: Int) -> BigUInt {
        if isZero || k == 0 { return self }
        return BigUInt(digits: [UInt8](repeating: 0, count: k) + d)
    }

    func divPow10(_ k: Int) -> (BigUInt, BigUInt) {
        if k == 0 { return (self, BigUInt()) }
        if d.count <= k { return (BigUInt(), self) }
        return (BigUInt(digits: Array(d[k...])), BigUInt(digits: Array(d[0..<k])))
    }

    func isOdd() -> Bool { !d.isEmpty && d[0] % 2 == 1 }

    func toString() -> String {
        if isZero { return "0" }
        return String(d.reversed().map { Character(UnicodeScalar($0 + 48)) })
    }

    // Proper long division
    func divmod(_ divisor: BigUInt) -> (BigUInt, BigUInt) {
        if divisor.isZero { fatalError("div by zero") }
        if self < divisor { return (BigUInt(), self) }
        if divisor == BigUInt(1) { return (self, BigUInt()) }

        let dividend = Array(d.reversed()) // MSD first
        let div = Array(divisor.d.reversed()) // MSD first

        var quotient = [UInt8]()
        var remainder: [UInt8] = []

        for i in 0..<dividend.count {
            remainder.append(dividend[i])
            while remainder.count > 1 && remainder[0] == 0 { remainder.removeFirst() }

            var q: UInt8 = 0
            for candidate in stride(from: UInt8(9), through: 0, by: -1) {
                let product = mulSingle(div, candidate)
                if compareMS(product, remainder) <= 0 {
                    q = candidate
                    break
                }
            }

            remainder = subMS(remainder, mulSingle(div, q))
            quotient.append(q)
        }

        while quotient.count > 1 && quotient[0] == 0 { quotient.removeFirst() }
        if quotient.count == 1 && quotient[0] == 0 { quotient = [] }

        var qBig = BigUInt()
        if !quotient.isEmpty { qBig.d = Array(quotient.reversed()); qBig.normalize() }

        var rBig = BigUInt()
        if !remainder.isEmpty {
            let rLSD = Array(remainder.reversed())
            rBig.d = rLSD
            rBig.normalize()
        }

        return (qBig, rBig)
    }
}

func compareMS(_ a: [UInt8], _ b: [UInt8]) -> Int {
    var aa = a, bb = b
    while aa.count > 1 && aa[0] == 0 { aa.removeFirst() }
    while bb.count > 1 && bb[0] == 0 { bb.removeFirst() }
    if aa.count != bb.count { return aa.count < bb.count ? -1 : 1 }
    for i in 0..<aa.count { if aa[i] != bb[i] { return aa[i] < bb[i] ? -1 : 1 } }
    return 0
}

func subMS(_ a: [UInt8], _ b: [UInt8]) -> [UInt8] {
    // a >= b, both MSD first
    let n = a.count
    let bb: [UInt8]
    if b.count < n {
        bb = [UInt8](repeating: 0, count: n - b.count) + b
    } else {
        bb = b
    }
    var result = [UInt8](repeating: 0, count: n)
    var borrow: Int8 = 0
    for i in stride(from: n - 1, through: 0, by: -1) {
        var diff = Int8(a[i]) - Int8(bb[i]) - borrow
        if diff < 0 { diff += 10; borrow = 1 } else { borrow = 0 }
        result[i] = UInt8(diff)
    }
    while result.count > 1 && result[0] == 0 { result.removeFirst() }
    return result
}

func mulSingle(_ a: [UInt8], _ d: UInt8) -> [UInt8] {
    if d == 0 { return [0] }
    var result = [UInt8](repeating: 0, count: a.count + 1)
    var carry: UInt16 = 0
    for i in stride(from: a.count - 1, through: 0, by: -1) {
        let prod = UInt16(a[i]) * UInt16(d) + carry
        result[i + 1] = UInt8(prod % 10)
        carry = prod / 10
    }
    result[0] = UInt8(carry)
    while result.count > 1 && result[0] == 0 { result.removeFirst() }
    return result
}

// Decimal: value = (-1)^neg * val / 10^scale
struct Dec {
    var neg: Bool
    var val: BigUInt
    var scale: Int
    var isZero: Bool { val.isZero }
    func normalized() -> Dec {
        if val.isZero { return Dec(neg: false, val: BigUInt(), scale: scale) }
        return self
    }
}

func decAdd(_ a: Dec, _ b: Dec) -> Dec {
    let s = max(a.scale, b.scale)
    let av = a.val.timesPow10(s - a.scale)
    let bv = b.val.timesPow10(s - b.scale)
    if a.neg == b.neg {
        let sum = av + bv
        return Dec(neg: a.neg && !sum.isZero, val: sum, scale: s).normalized()
    }
    if av >= bv {
        let diff = av - bv
        return Dec(neg: a.neg && !diff.isZero, val: diff, scale: s).normalized()
    } else {
        let diff = bv - av
        return Dec(neg: b.neg && !diff.isZero, val: diff, scale: s).normalized()
    }
}

func decSub(_ a: Dec, _ b: Dec) -> Dec {
    return decAdd(a, Dec(neg: !b.neg, val: b.val, scale: b.scale))
}

func decMul(_ a: Dec, _ b: Dec) -> Dec {
    let product = a.val * b.val
    return Dec(neg: (a.neg != b.neg) && !product.isZero, val: product, scale: a.scale + b.scale)
}

func decRound(_ d: Dec, to places: Int) -> Dec {
    if d.scale == places { return d.normalized() }
    if d.scale < places {
        return Dec(neg: d.neg, val: d.val.timesPow10(places - d.scale), scale: places).normalized()
    }
    let k = d.scale - places
    let (q, r) = d.val.divPow10(k)
    let half = BigUInt(5).timesPow10(k - 1)
    var result = q
    if r > half { result = q + BigUInt(1) }
    else if r == half && q.isOdd() { result = q + BigUInt(1) }
    return Dec(neg: d.neg && !result.isZero, val: result, scale: places).normalized()
}

func decCmp(_ a: Dec, _ b: Dec) -> Int {
    let s = max(a.scale, b.scale)
    let av = a.val.timesPow10(s - a.scale)
    let bv = b.val.timesPow10(s - b.scale)
    if a.neg && !b.neg { return -1 }
    if !a.neg && b.neg { return 1 }
    if a.neg && b.neg {
        if av < bv { return 1 }
        if av > bv { return -1 }
        return 0
    }
    if av < bv { return -1 }
    if av > bv { return 1 }
    return 0
}

func decParse(_ s: String) -> Dec {
    var neg = false
    var i = s.startIndex
    if i < s.endIndex && s[i] == "-" { neg = true; i = s.index(after: i) }
    var digits = ""
    var scale = 0
    var inFrac = false
    while i < s.endIndex {
        if s[i] == "." { inFrac = true }
        else {
            digits.append(s[i])
            if inFrac { scale += 1 }
        }
        i = s.index(after: i)
    }
    let val = BigUInt(digits.isEmpty ? "0" : digits)
    return Dec(neg: neg && !val.isZero, val: val, scale: scale)
}

func formatMoney(neg: Bool, val: BigUInt, minorUnits: Int) -> String {
    if val.isZero {
        if minorUnits == 0 { return "0" }
        return "0." + String(repeating: "0", count: minorUnits)
    }
    let prefix = neg ? "-" : ""
    if minorUnits == 0 {
        return prefix + formatCommas(val.toString())
    }
    let (intPart, fracPart) = val.divPow10(minorUnits)
    let intStr = intPart.isZero ? "0" : intPart.toString()
    let fracStr = fracPart.isZero ? String(repeating: "0", count: minorUnits) : fracPart.toString()
    let padded = fracStr.count >= minorUnits ? fracStr : String(repeating: "0", count: minorUnits - fracStr.count) + fracStr
    return prefix + formatCommas(intStr) + "." + padded
}

func formatCommas(_ s: String) -> String {
    let chars = Array(s)
    var result = ""
    for (i, c) in chars.enumerated() {
        if i > 0 && (chars.count - i) % 3 == 0 { result.append(",") }
        result.append(c)
    }
    return result
}

// Main program
let args = CommandLine.arguments
let dir = args[1]
let path = dir + "/ledger.txt"
let content = try! String(contentsOfFile: path, encoding: .utf8)
var lines = content.components(separatedBy: "\n")
// Remove trailing empty line if file ends with newline
if lines.last == "" { lines.removeLast() }

var currencies: [String: Int] = [:]
var accounts: [String: (code: String, bal: Dec, limit: Dec)] = [:]
var rejections: [(Int, String)] = []

for (lineNum, line) in lines.enumerated() {
    let ln = lineNum + 1
    let trimmed = line.trimmingCharacters(in: .whitespaces)
    if trimmed.isEmpty || trimmed.hasPrefix("#") { continue }

    let fields = trimmed.components(separatedBy: .whitespaces).filter { !$0.isEmpty }
    guard !fields.isEmpty else { continue }
    let cmd = fields[0]

    switch cmd {
    case "currency":
        let code = fields[1]
        let mu = Int(fields[2])!
        currencies[code] = mu

    case "open":
        let name = fields[1]
        let code = fields[2]
        if accounts[name] != nil {
            rejections.append((ln, "account exists \(name)"))
            continue
        }
        let mu = currencies[code]!
        var limit = Dec(neg: false, val: BigUInt(), scale: mu)
        if fields.count >= 4 {
            let rawLimit = decParse(fields[3])
            limit = decRound(rawLimit, to: mu)
        }
        accounts[name] = (code: code, bal: Dec(neg: false, val: BigUInt(), scale: mu), limit: limit)

    case "deposit":
        let name = fields[1]
        guard let acct = accounts[name] else {
            rejections.append((ln, "unknown account \(name)"))
            continue
        }
        let mu = currencies[acct.code]!
        let amount = decRound(decParse(fields[2]), to: mu)
        if amount.neg || amount.isZero {
            rejections.append((ln, "non-positive amount"))
            continue
        }
        var a = acct
        a.bal = decAdd(a.bal, amount)
        accounts[name] = a

    case "withdraw":
        let name = fields[1]
        guard let acct = accounts[name] else {
            rejections.append((ln, "unknown account \(name)"))
            continue
        }
        let mu = currencies[acct.code]!
        let amount = decRound(decParse(fields[2]), to: mu)
        if amount.neg || amount.isZero {
            rejections.append((ln, "non-positive amount"))
            continue
        }
        let sum = decAdd(acct.bal, acct.limit)
        if decCmp(sum, amount) < 0 {
            rejections.append((ln, "insufficient funds \(name)"))
            continue
        }
        var a = acct
        a.bal = decSub(a.bal, amount)
        accounts[name] = a

    case "transfer":
        let fromName = fields[1]
        let toName = fields[2]
        if accounts[fromName] == nil {
            rejections.append((ln, "unknown account \(fromName)"))
            continue
        }
        if accounts[toName] == nil {
            rejections.append((ln, "unknown account \(toName)"))
            continue
        }
        let fromAcct = accounts[fromName]!
        let toAcct = accounts[toName]!
        if fromAcct.code != toAcct.code {
            rejections.append((ln, "currency mismatch"))
            continue
        }
        let mu = currencies[fromAcct.code]!
        let amount = decRound(decParse(fields[3]), to: mu)
        if amount.neg || amount.isZero {
            rejections.append((ln, "non-positive amount"))
            continue
        }
        let sum = decAdd(fromAcct.bal, fromAcct.limit)
        if decCmp(sum, amount) < 0 {
            rejections.append((ln, "insufficient funds \(fromName)"))
            continue
        }
        var fa = fromAcct; fa.bal = decSub(fa.bal, amount)
        var ta = toAcct; ta.bal = decAdd(ta.bal, amount)
        accounts[fromName] = fa
        accounts[toName] = ta

    case "convert":
        let fromName = fields[1]
        let toName = fields[2]
        if accounts[fromName] == nil {
            rejections.append((ln, "unknown account \(fromName)"))
            continue
        }
        if accounts[toName] == nil {
            rejections.append((ln, "unknown account \(toName)"))
            continue
        }
        let fromAcct = accounts[fromName]!
        let toAcct = accounts[toName]!
        let fromMu = currencies[fromAcct.code]!
        let toMu = currencies[toAcct.code]!
        let amount = decRound(decParse(fields[3]), to: fromMu)
        if amount.neg || amount.isZero {
            rejections.append((ln, "non-positive amount"))
            continue
        }
        let sum = decAdd(fromAcct.bal, fromAcct.limit)
        if decCmp(sum, amount) < 0 {
            rejections.append((ln, "insufficient funds \(fromName)"))
            continue
        }
        let rate = decParse(fields[4])
        let converted = decRound(decMul(amount, rate), to: toMu)
        var fa = fromAcct; fa.bal = decSub(fa.bal, amount)
        var ta = toAcct; ta.bal = decAdd(ta.bal, converted)
        accounts[fromName] = fa
        accounts[toName] = ta

    case "interest":
        let name = fields[1]
        guard let acct = accounts[name] else {
            rejections.append((ln, "unknown account \(name)"))
            continue
        }
        let mu = currencies[acct.code]!
        let rate = decParse(fields[2])
        let interest = decRound(decMul(acct.bal, rate), to: mu)
        var a = acct
        a.bal = decAdd(a.bal, interest)
        accounts[name] = a

    case "split":
        let fromName = fields[1]
        var targetNames: [String] = []
        var targetWeights: [BigUInt] = []
        for i in 3..<fields.count {
            let colonIdx = fields[i].firstIndex(of: ":")!
            let name = String(fields[i][fields[i].startIndex..<colonIdx])
            let weightStr = String(fields[i][fields[i].index(after: colonIdx)...])
            targetNames.append(name)
            targetWeights.append(BigUInt(weightStr))
        }
        // Check unknown accounts in order of appearance
        var unknownFound = false
        if accounts[fromName] == nil {
            rejections.append((ln, "unknown account \(fromName)"))
            unknownFound = true
        }
        if !unknownFound {
            for tn in targetNames {
                if accounts[tn] == nil {
                    rejections.append((ln, "unknown account \(tn)"))
                    unknownFound = true
                    break
                }
            }
        }
        if unknownFound { continue }

        let fromAcct = accounts[fromName]!
        let fromCode = fromAcct.code
        var mismatch = false
        for tn in targetNames {
            if accounts[tn]!.code != fromCode {
                mismatch = true
                break
            }
        }
        if mismatch {
            rejections.append((ln, "currency mismatch"))
            continue
        }

        let mu = currencies[fromCode]!
        let amount = decRound(decParse(fields[2]), to: mu)
        if amount.neg || amount.isZero {
            rejections.append((ln, "non-positive amount"))
            continue
        }
        let sum = decAdd(fromAcct.bal, fromAcct.limit)
        if decCmp(sum, amount) < 0 {
            rejections.append((ln, "insufficient funds \(fromName)"))
            continue
        }

        // Distribute in minor units
        let A = amount.val // positive integer (minor units)
        var W = BigUInt()
        for w in targetWeights { W = W + w }

        var shares: [BigUInt] = []
        var remainders: [BigUInt] = []
        for w in targetWeights {
            let product = A * w
            let (q, r) = product.divmod(W)
            shares.append(q)
            remainders.append(r)
        }

        var totalGiven = BigUInt()
        for s in shares { totalGiven = totalGiven + s }
        let leftover = A - totalGiven

        // Sort indices by remainder descending, then by index ascending
        var indices = Array(0..<targetNames.count)
        indices.sort { i, j in
            if remainders[i] != remainders[j] { return remainders[i] > remainders[j] }
            return i < j
        }

        // Distribute leftover one by one
        var finalShares = shares
        var remaining = leftover
        var idx = 0
        while !remaining.isZero {
            finalShares[indices[idx]] = finalShares[indices[idx]] + BigUInt(1)
            remaining = remaining - BigUInt(1)
            idx += 1
        }

        // Apply
        var fa = fromAcct
        fa.bal = decSub(fa.bal, amount)
        accounts[fromName] = fa

        for i in 0..<targetNames.count {
            let tn = targetNames[i]
            let share = finalShares[i]
            let shareDec = Dec(neg: false, val: share, scale: mu)
            var ta = accounts[tn]!
            ta.bal = decAdd(ta.bal, shareDec)
            accounts[tn] = ta
        }

    default:
        break
    }
}

// Output
for (ln, reason) in rejections {
    print("line \(ln): REJECT \(reason)")
}
print("")

let sortedAccounts = accounts.keys.sorted()
for name in sortedAccounts {
    let acct = accounts[name]!
    let mu = currencies[acct.code]!
    let balStr = formatMoney(neg: acct.bal.neg, val: acct.bal.val, minorUnits: mu)
    print("\(name) \(acct.code) \(balStr)")
}
print("")

// Currency totals
var currencyTotals: [String: (neg: Bool, val: BigUInt, count: Int)] = [:]
for name in sortedAccounts {
    let acct = accounts[name]!
    let code = acct.code
    if currencyTotals[code] == nil {
        currencyTotals[code] = (neg: false, val: BigUInt(), count: 0)
    }
    var ct = currencyTotals[code]!
    ct.count += 1
    if acct.bal.neg == ct.neg {
        ct.val = ct.val + acct.bal.val
    } else {
        if acct.bal.val >= ct.val {
            ct.val = acct.bal.val - ct.val
            ct.neg = acct.bal.neg
        } else {
            ct.val = ct.val - acct.bal.val
        }
    }
    if ct.val.isZero { ct.neg = false }
    currencyTotals[code] = ct
}

let sortedCurrencies = currencyTotals.keys.sorted()
for code in sortedCurrencies {
    let ct = currencyTotals[code]!
    let mu = currencies[code]!
    let totalStr = formatMoney(neg: ct.neg, val: ct.val, minorUnits: mu)
    print("total \(code) \(totalStr) (\(ct.count) accounts)")
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>

#define BASE 1000000000ULL
#define BASE_DIGITS 9
#define MAX_LIMBS 40
#define MAX_ACCOUNTS 10000
#define MAX_CURRENCIES 1000
#define MAX_LINE 10000
#define MAX_REJECTIONS 10000
#define MAX_TOKENS 1000
#define MAX_TARGETS 256

typedef struct {
    int sign;
    int len;
    uint32_t d[MAX_LIMBS];
} BigInt;

typedef struct {
    char name[256];
    char code[16];
    BigInt balance;
    BigInt limit;
} Account;

typedef struct {
    char code[16];
    int minor;
} Currency;

typedef struct {
    int line;
    char reason[512];
} Rejection;

static Account accounts[MAX_ACCOUNTS];
static int num_accounts = 0;
static Currency currencies[MAX_CURRENCIES];
static int num_currencies = 0;
static Rejection rejections[MAX_REJECTIONS];
static int num_rejections = 0;

/* --- BigInt --- */

static void bigint_zero(BigInt *a) { a->sign = 0; a->len = 0; }

static int bigint_cmp_abs(const BigInt *a, const BigInt *b) {
    if (a->len != b->len) return a->len > b->len ? 1 : -1;
    for (int i = a->len - 1; i >= 0; i--)
        if (a->d[i] != b->d[i]) return a->d[i] > b->d[i] ? 1 : -1;
    return 0;
}

static int bigint_cmp(const BigInt *a, const BigInt *b) {
    if (a->sign != b->sign) return a->sign > b->sign ? 1 : -1;
    if (a->sign == 0) return 0;
    int c = bigint_cmp_abs(a, b);
    return a->sign > 0 ? c : -c;
}

static void bigint_add_abs(BigInt *r, const BigInt *a, const BigInt *b) {
    int maxlen = a->len > b->len ? a->len : b->len;
    __uint128_t carry = 0;
    for (int i = 0; i < maxlen; i++) {
        __uint128_t da = i < a->len ? a->d[i] : 0;
        __uint128_t db = i < b->len ? b->d[i] : 0;
        __uint128_t sum = da + db + carry;
        r->d[i] = (uint32_t)(sum % BASE);
        carry = sum / BASE;
    }
    if (carry) { r->d[maxlen] = (uint32_t)carry; r->len = maxlen + 1; }
    else r->len = maxlen;
    while (r->len > 0 && r->d[r->len-1] == 0) r->len--;
    r->sign = (r->len == 0) ? 0 : 1;
}

static void bigint_sub_abs(BigInt *r, const BigInt *a, const BigInt *b) {
    __uint128_t borrow = 0;
    for (int i = 0; i < a->len; i++) {
        __uint128_t da = a->d[i];
        __uint128_t db = i < b->len ? b->d[i] : 0;
        if (da < db + borrow) {
            r->d[i] = (uint32_t)(da + BASE - db - borrow);
            borrow = 1;
        } else {
            r->d[i] = (uint32_t)(da - db - borrow);
            borrow = 0;
        }
    }
    r->len = a->len;
    while (r->len > 0 && r->d[r->len-1] == 0) r->len--;
    r->sign = (r->len == 0) ? 0 : 1;
}

static void bigint_add(BigInt *r, const BigInt *a, const BigInt *b) {
    if (a->sign == 0) { *r = *b; return; }
    if (b->sign == 0) { *r = *a; return; }
    if (a->sign == b->sign) {
        bigint_add_abs(r, a, b);
        r->sign = a->sign;
    } else {
        int cmp = bigint_cmp_abs(a, b);
        if (cmp >= 0) {
            bigint_sub_abs(r, a, b);
            r->sign = (r->len == 0) ? 0 : a->sign;
        } else {
            bigint_sub_abs(r, b, a);
            r->sign = (r->len == 0) ? 0 : b->sign;
        }
    }
}

static void bigint_sub(BigInt *r, const BigInt *a, const BigInt *b) {
    BigInt nb = *b;
    nb.sign = -nb.sign;
    bigint_add(r, a, &nb);
}

static void bigint_mul(BigInt *r, const BigInt *a, const BigInt *b) {
    if (a->sign == 0 || b->sign == 0) { bigint_zero(r); return; }
    BigInt tmp;
    memset(&tmp, 0, sizeof(tmp));
    for (int i = 0; i < a->len; i++) {
        __uint128_t carry = 0;
        for (int j = 0; j < b->len; j++) {
            __uint128_t prod = (__uint128_t)a->d[i] * b->d[j] + tmp.d[i+j] + carry;
            tmp.d[i+j] = (uint32_t)(prod % BASE);
            carry = prod / BASE;
        }
        int pos = i + b->len;
        while (carry) {
            __uint128_t s = (__uint128_t)tmp.d[pos] + carry;
            tmp.d[pos] = (uint32_t)(s % BASE);
            carry = s / BASE;
            pos++;
        }
    }
    tmp.len = a->len + b->len;
    while (tmp.len > 0 && tmp.d[tmp.len-1] == 0) tmp.len--;
    tmp.sign = (tmp.len == 0) ? 0 : a->sign * b->sign;
    *r = tmp;
}

static void bigint_mul_small(BigInt *r, const BigInt *a, uint64_t b) {
    if (a->sign == 0 || b == 0) { bigint_zero(r); return; }
    BigInt tmp;
    memset(&tmp, 0, sizeof(tmp));
    __uint128_t carry = 0;
    for (int i = 0; i < a->len; i++) {
        __uint128_t prod = (__uint128_t)a->d[i] * b + carry;
        tmp.d[i] = (uint32_t)(prod % BASE);
        carry = prod / BASE;
    }
    int i = a->len;
    while (carry) { tmp.d[i] = (uint32_t)(carry % BASE); carry /= BASE; i++; }
    tmp.len = i;
    tmp.sign = a->sign;
    *r = tmp;
}

static uint64_t bigint_div_small(BigInt *a, uint64_t d) {
    if (a->len == 0) return 0;
    __uint128_t rem = 0;
    for (int i = a->len - 1; i >= 0; i--) {
        __uint128_t cur = rem * BASE + a->d[i];
        a->d[i] = (uint32_t)(cur / d);
        rem = cur % d;
    }
    while (a->len > 0 && a->d[a->len-1] == 0) a->len--;
    if (a->len == 0) a->sign = 0;
    return (uint64_t)rem;
}

static void bigint_add_small(BigInt *a, uint64_t v) {
    if (v == 0) return;
    __uint128_t carry = v;
    int i = 0;
    while (carry) {
        if (i >= a->len) { a->d[i] = 0; a->len = i + 1; }
        __uint128_t s = (__uint128_t)a->d[i] + carry;
        a->d[i] = (uint32_t)(s % BASE);
        carry = s / BASE;
        i++;
    }
    if (a->len > 0 && a->sign == 0) a->sign = 1;
}

/* --- Parsing --- */

static void parse_number(const char *s, BigInt *val, int *scale) {
    int sign = 1;
    if (*s == '-') { sign = -1; s++; }
    char digits[256];
    int ndigits = 0, dot_pos = -1;
    while (*s) {
        if (*s == '.') dot_pos = ndigits;
        else digits[ndigits++] = *s;
        s++;
    }
    *scale = (dot_pos >= 0) ? ndigits - dot_pos : 0;
    memset(val, 0, sizeof(*val));
    val->len = 0;
    int i = ndigits;
    while (i > 0) {
        int start = i - BASE_DIGITS;
        if (start < 0) start = 0;
        uint32_t limb = 0;
        for (int j = start; j < i; j++) limb = limb * 10 + (digits[j] - '0');
        val->d[val->len++] = limb;
        i = start;
    }
    while (val->len > 0 && val->d[val->len-1] == 0) val->len--;
    val->sign = (val->len == 0) ? 0 : sign;
}

/* --- Rounding --- */

static void round_to_scale(BigInt *val, int *scale, int target) {
    if (*scale == target) return;
    if (*scale < target) {
        int k = target - *scale;
        for (int i = 0; i < k; i++) bigint_mul_small(val, 10);
        *scale = target;
    } else {
        int k = *scale - target;
        int sign = val->sign;
        val->sign = 1;
        uint64_t divisor = 1;
        for (int i = 0; i < k; i++) divisor *= 10;
        uint64_t rem = bigint_div_small(val, divisor);
        uint64_t half = divisor / 2;
        if (rem > half || (rem == half && val->len > 0 && (val->d[0] & 1)))
            bigint_add_small(val, 1);
        val->sign = (val->len == 0) ? 0 : sign;
        *scale = target;
    }
}

/* --- Formatting --- */

static void bigint_to_digits(const BigInt *a, char *buf) {
    if (a->len == 0) { buf[0] = '0'; buf[1] = '\0'; return; }
    int pos = 0;
    pos += sprintf(buf + pos, "%u", a->d[a->len - 1]);
    for (int i = a->len - 2; i >= 0; i--)
        pos += sprintf(buf + pos, "%09u", a->d[i]);
    buf[pos] = '\0';
}

static void format_money(const BigInt *val, int minor, char *buf) {
    if (val->sign == 0) {
        int pos = 0;
        buf[pos++] = '0';
        if (minor > 0) { buf[pos++] = '.'; for (int i = 0; i < minor; i++) buf[pos++] = '0'; }
        buf[pos] = '\0';
        return;
    }
    BigInt av = *val; av.sign = 1;
    char digits[512];
    bigint_to_digits(&av, digits);
    int dlen = (int)strlen(digits), pos = 0;
    if (val->sign < 0) buf[pos++] = '-';
    if (minor > 0) {
        if (dlen > minor) {
            int il = dlen - minor;
            for (int i = 0; i < il; i++) {
                if (i > 0 && (il - i) % 3 == 0) buf[pos++] = ',';
                buf[pos++] = digits[i];
            }
            buf[pos++] = '.';
            for (int i = il; i < dlen; i++) buf[pos++] = digits[i];
        } else {
            buf[pos++] = '0'; buf[pos++] = '.';
            for (int i = 0; i < minor - dlen; i++) buf[pos++] = '0';
            for (int i = 0; i < dlen; i++) buf[pos++] = digits[i];
        }
    } else {
        for (int i = 0; i < dlen; i++) {
            if (i > 0 && (dlen - i) % 3 == 0) buf[pos++] = ',';
            buf[pos++] = digits[i];
        }
    }
    buf[pos] = '\0';
}

/* --- Lookup --- */

static Account *find_account(const char *name) {
    for (int i = 0; i < num_accounts; i++)
        if (strcmp(accounts[i].name, name) == 0) return &accounts[i];
    return NULL;
}

static Currency *find_currency(const char *code) {
    for (int i = 0; i < num_currencies; i++)
        if (strcmp(currencies[i].code, code) == 0) return &currencies[i];
    return NULL;
}

/* --- Tokenize --- */

static int tokenize(char *line, char **toks, int max) {
    int n = 0; char *p = line;
    while (*p && n < max) {
        while (*p == ' ' || *p == '\t') p++;
        if (!*p || *p == '\n') break;
        toks[n++] = p;
        while (*p && *p != ' ' && *p != '\t' && *p != '\n') p++;
        if (*p) { *p = '\0'; p++; }
    }
    return n;
}

/* --- Helpers --- */

static void reject(int line, const char *fmt, ...) {
    rejections[num_rejections].line = line;
    va_list ap;
    va_start(ap, fmt);
    vsnprintf(rejections[num_rejections].reason, 512, fmt, ap);
    va_end(ap);
    num_rejections++;
}

static void round_amount(BigInt *val, int *scale, int minor) {
    round_to_scale(val, scale, minor);
}

/* Round product/scale to integer (scale 0) */
static void round_product(BigInt *val, int scale) {
    if (scale > 0) {
        int sign = val->sign;
        val->sign = 1;
        uint64_t div = 1;
        for (int i = 0; i < scale; i++) div *= 10;
        uint64_t rem = bigint_div_small(val, div);
        uint64_t half = div / 2;
        if (rem > half || (rem == half && val->len > 0 && (val->d[0] & 1)))
            bigint_add_small(val, 1);
        val->sign = (val->len == 0) ? 0 : sign;
    } else if (scale < 0) {
        for (int i = 0; i < -scale; i++) bigint_mul_small(val, 10);
    }
}

static int cmp_acct(const void *a, const void *b) {
    return strcmp(((Account*)a)->name, ((Account*)b)->name);
}
static int cmp_curr(const void *a, const void *b) {
    return strcmp(((Currency*)a)->code, ((Currency*)b)->code);
}

/* --- Main --- */

int main(int argc, char *argv[]) {
    if (argc < 2) return 1;
    char path[1024];
    snprintf(path, sizeof(path), "%s/ledger.txt", argv[1]);
    FILE *f = fopen(path, "r");
    if (!f) return 1;

    char line[MAX_LINE];
    int line_num = 0;

    while (fgets(line, sizeof(line), f)) {
        line_num++;
        int len = (int)strlen(line);
        while (len > 0 && (line[len-1]=='\n'||line[len-1]=='\r')) line[--len]='\0';

        char *p = line;
        while (*p==' '||*p=='\t') p++;
        if (*p=='\0'||*p=='#') continue;

        char *toks[MAX_TOKENS];
        int nt = tokenize(line, toks, MAX_TOKENS);
        if (nt == 0) continue;

        if (strcmp(toks[0], "currency") == 0) {
            Currency c;
            strcpy(c.code, toks[1]);
            c.minor = atoi(toks[2]);
            currencies[num_currencies++] = c;
        }
        else if (strcmp(toks[0], "open") == 0) {
            char *name = toks[1];
            if (find_account(name)) {
                rejections[num_rejections].line = line_num;
                snprintf(rejections[num_rejections].reason, 512, "account exists %s", name);
                num_rejections++;
                continue;
            }
            Currency *cur = find_currency(toks[2]);
            Account *acc = &accounts[num_accounts++];
            strcpy(acc->name, name);
            strcpy(acc->code, toks[2]);
            bigint_zero(&acc->balance);
            bigint_zero(&acc->limit);
            if (nt >= 4) {
                BigInt lim; int ls;
                parse_number(toks[3], &lim, &ls);
                round_to_scale(&lim, &ls, cur->minor);
                acc->limit = lim;
            }
        }
        else if (strcmp(toks[0], "deposit") == 0) {
            Account *acc = find_account(toks[1]);
            if (!acc) {
                rejections[num_rejections].line = line_num;
                snprintf(rejections[num_rejections].reason,512,"unknown account %s",toks[1]);
                num_rejections++; continue;
            }
            Currency *cur = find_currency(acc->code);
            BigInt amt; int sc;
            parse_number(toks[2], &amt, &sc);
            round_to_scale(&amt, &sc, cur->minor);
            if (amt.sign <= 0) {
                rejections[num_rejections].line = line_num;
                snprintf(rejections[num_rejections].reason,512,"non-positive amount");
                num_rejections++; continue;
            }
            bigint_add(&acc->balance, &acc->balance, &amt);
        }
        else if (strcmp(toks[0], "withdraw") == 0) {
            Account *acc = find_account(toks[1]);
            if (!acc) {
                rejections[num_rejections].line = line_num;
                snprintf(rejections[num_rejections].reason,512,"unknown account %s",toks[1]);
                num_rejections++; continue;
            }
            Currency *cur = find_currency(acc->code);
            BigInt amt; int sc;
            parse_number(toks[2], &amt, &sc);
            round_to_scale(&amt, &sc, cur->minor);
            if (amt.sign <= 0) {
                rejections[num_rejections].line = line_num;
                snprintf(rejections[num_rejections].reason,512,"non-positive amount");
                num_rejections++; continue;
            }
            BigInt tmp;
            bigint_add(&tmp, &acc->balance, &acc->limit);
            if (bigint_cmp(&tmp, &amt) < 0) {
                rejections[num_rejections].line = line_num;
                snprintf(rejections[num_rejections].reason,512,"insufficient funds %s",toks[1]);
                num_rejections++; continue;
            }
            bigint_sub(&acc->balance, &acc->balance, &amt);
        }
        else if (strcmp(toks[0], "transfer") == 0) {
            Account *from = find_account(toks[1]);
            Account *to = find_account(toks[2]);
            if (!from) {
                rejections[num_rejections].line = line_num;
                snprintf(rejections[num_rejections].reason,512,"unknown account %s",toks[1]);
                num_rejections++; continue;
            }
            if (!to) {
                rejections[num_rejections].line = line_num;
                snprintf(rejections[num_rejections].reason,512,"unknown account %s",toks[2]);
                num_rejections++; continue;
            }
            if (strcmp(from->code, to->code) != 0) {
                rejections[num_rejections].line = line_num;
                snprintf(rejections[num_rejections].reason,512,"currency mismatch");
                num_rejections++; continue;
            }
            Currency *cur = find_currency(from->code);
            BigInt amt; int sc;
            parse_number(toks[3], &amt, &sc);
            round_to_scale(&amt, &sc, cur->minor);
            if (amt.sign <= 0) {
                rejections[num_rejections].line = line_num;
                snprintf(rejections[num_rejections].reason,512,"non-positive amount");
                num_rejections++; continue;
            }
            BigInt tmp;
            bigint_add(&tmp, &from->balance, &from->limit);
            if (bigint_cmp(&tmp, &amt) < 0) {
                rejections[num_rejections].line = line_num;
                snprintf(rejections[num_rejections].reason,512,"insufficient funds %s",toks[1]);
                num_rejections++; continue;
            }
            bigint_sub(&from->balance, &from->balance, &amt);
            bigint_add(&to->balance, &to->balance, &amt);
        }
        else if (strcmp(toks[0], "convert") == 0) {
            Account *from = find_account(toks[1]);
            Account *to = find_account(toks[2]);
            if (!from) {
                rejections[num_rejections].line = line_num;
                snprintf(rejections[num_rejections].reason,512,"unknown account %s",toks[1]);
                num_rejections++; continue;
            }
            if (!to) {
                rejections[num_rejections].line = line_num;
                snprintf(rejections[num_rejections].reason,512,"unknown account %s",toks[2]);
                num_rejections++; continue;
            }
            Currency *cf = find_currency(from->code);
            Currency *ct = find_currency(to->code);
            BigInt amt; int sc;
            parse_number(toks[3], &amt, &sc);
            round_to_scale(&amt, &sc, cf->minor);
            if (amt.sign <= 0) {
                rejections[num_rejections].line = line_num;
                snprintf(rejections[num_rejections].reason,512,"non-positive amount");
                num_rejections++; continue;
            }
            BigInt tmp;
            bigint_add(&tmp, &from->balance, &from->limit);
            if (bigint_cmp(&tmp, &amt) < 0) {
                rejections[num_rejections].line = line_num;
                snprintf(rejections[num_rejections].reason,512,"insufficient funds %s",toks[1]);
                num_rejections++; continue;
            }
            bigint_sub(&from->balance, &from->balance, &amt);
            BigInt rv; int rs;
            parse_number(toks[4], &rv, &rs);
            BigInt prod;
            bigint_mul(&prod, &amt, &rv);
            int s = cf->minor + rs - ct->minor;
            round_product(&prod, s);
            bigint_add(&to->balance, &to->balance, &prod);
        }
        else if (strcmp(toks[0], "interest") == 0) {
            Account *acc = find_account(toks[1]);
            if (!acc) {
                rejections[num_rejections].line = line_num;
                snprintf(rejections[num_rejections].reason,512,"unknown account %s",toks[1]);
                num_rejections++; continue;
            }
            BigInt rv; int rs;
            parse_number(toks[2], &rv, &rs);
            BigInt prod;
            bigint_mul(&prod, &acc->balance, &rv);
            round_product(&prod, rs);
            bigint_add(&acc->balance, &acc->balance, &prod);
        }
        else if (strcmp(toks[0], "split") == 0) {
            Account *from = find_account(toks[1]);
            if (!from) {
                rejections[num_rejections].line = line_num;
                snprintf(rejections[num_rejections].reason,512,"unknown account %s",toks[1]);
                num_rejections++; continue;
            }
            int ntargets = nt - 3;
            Account *targets[MAX_TARGETS];
            uint64_t weights[MAX_TARGETS];
            int unk = 0; char unk_name[256] = "";
            for (int i = 0; i < ntargets; i++) {
                char *colon = strchr(toks[3+i], ':');
                if (!colon) { targets[i]=NULL; weights[i]=0; continue; }
                *colon = '\0';
                targets[i] = find_account(toks[3+i]);
                if (!targets[i] && !unk) { strcpy(unk_name, toks[3+i]); unk = 1; }
                weights[i] = strtoull(colon+1, NULL, 10);
            }
            if (unk) {
                rejections[num_rejections].line = line_num;
                snprintf(rejections[num_rejections].reason,512,"unknown account %s",unk_name);
                num_rejections++; continue;
            }
            int mismatch = 0;
            for (int i = 0; i < ntargets; i++)
                if (strcmp(targets[i]->code, from->code) != 0) { mismatch = 1; break; }
            if (mismatch) {
                rejections[num_rejections].line = line_num;
                snprintf(rejections[num_rejections].reason,512,"currency mismatch");
                num_rejections++; continue;
            }
            Currency *cur = find_currency(from->code);
            BigInt amt; int sc;
            parse_number(toks[2], &amt, &sc);
            round_to_scale(&amt, &sc, cur->minor);
            if (amt.sign <= 0) {
                rejections[num_rejections].line = line_num;
                snprintf(rejections[num_rejections].reason,512,"non-positive amount");
                num_rejections++; continue;
            }
            BigInt tmp;
            bigint_add(&tmp, &from->balance, &from->limit);
            if (bigint_cmp(&tmp, &amt) < 0) {
                rejections[num_rejections].line = line_num;
                snprintf(rejections[num_rejections].reason,512,"insufficient funds %s",toks[1]);
                num_rejections++; continue;
            }
            /* Execute split */
            bigint_sub(&from->balance, &from->balance, &amt);
            uint64_t W = 0;
            for (int i = 0; i < ntargets; i++) W += weights[i];
            BigInt bases[MAX_TARGETS];
            uint64_t rems[MAX_TARGETS];
            BigInt total_base; bigint_zero(&total_base);
            for (int i = 0; i < ntargets; i++) {
                BigInt aw;
                bigint_mul_small(&aw, &amt, weights[i]);
                aw.sign = 1;
                rems[i] = bigint_div_small(&aw, W);
                bases[i] = aw;
                bigint_add(&total_base, &total_base, &bases[i]);
            }
            BigInt leftover_bi;
            bigint_sub(&leftover_bi, &amt, &total_base);
            uint64_t leftover = 0;
            if (leftover_bi.sign != 0) {
                for (int i = leftover_bi.len-1; i >= 0; i--)
                    leftover = leftover * BASE + leftover_bi.d[i];
            }
            int order[MAX_TARGETS];
            for (int i = 0; i < ntargets; i++) order[i] = i;
            /* stable sort desc by rems */
            for (int i = 1; i < ntargets; i++) {
                int key = order[i];
                int j = i - 1;
                while (j >= 0 && rems[order[j]] < rems[key]) {
                    order[j+1] = order[j]; j--;
                }
                order[j+1] = key;
            }
            for (uint64_t i = 0; i < leftover; i++)
                bigint_add_small(&bases[order[i]], 1);
            for (int i = 0; i < ntargets; i++)
                bigint_add(&targets[i]->balance, &targets[i]->balance, &bases[i]);
        }
    }
    fclose(f);

    /* Output */
    for (int i = 0; i < num_rejections; i++)
        printf("line %d: REJECT %s\n", rejections[i].line, rejections[i].reason);
    printf("\n");

    qsort(accounts, num_accounts, sizeof(Account), cmp_acct);
    for (int i = 0; i < num_accounts; i++) {
        char buf[512];
        Currency *cur = find_currency(accounts[i].code);
        format_money(&accounts[i].balance, cur->minor, buf);
        printf("%s %s %s\n", accounts[i].name, accounts[i].code, buf);
    }
    printf("\n");

    qsort(currencies, num_currencies, sizeof(Currency), cmp_curr);
    for (int i = 0; i < num_currencies; i++) {
        int cnt = 0;
        BigInt total; bigint_zero(&total);
        for (int j = 0; j < num_accounts; j++) {
            if (strcmp(accounts[j].code, currencies[i].code) == 0) {
                bigint_add(&total, &total, &accounts[j].balance);
                cnt++;
            }
        }
        if (cnt == 0) continue;
        char buf[512];
        format_money(&total, currencies[i].minor, buf);
        printf("total %s %s (%d accounts)\n", currencies[i].code, buf, cnt);
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>

#define BASE 1000000000ULL
#define BASE_DIGITS 9
#define MAX_LIMBS 80
#define MAX_ACCOUNTS 10000
#define MAX_CURRENCIES 1000
#define MAX_LINE 10000
#define MAX_REJECTIONS 10000
#define MAX_TOKENS 1024
#define MAX_TARGETS 512
#define STR_BUF 512

typedef struct {
    int sign;
    int len;
    uint32_t d[MAX_LIMBS];
} BigInt;

typedef struct {
    char name[256];
    char code[16];
    BigInt balance;
    BigInt limit;
} Account;

typedef struct {
    char code[16];
    int minor;
} Currency;

typedef struct {
    int line;
    char reason[512];
} Rejection;

static Account accounts[MAX_ACCOUNTS];
static int num_accounts = 0;
static Currency currencies[MAX_CURRENCIES];
static int num_currencies = 0;
static Rejection rejections[MAX_REJECTIONS];
static int num_rejections = 0;

/* --- BigInt --- */

static void bigint_zero(BigInt *a) { a->sign = 0; a->len = 0; memset(a->d, 0, sizeof(a->d)); }

static int bigint_cmp_abs(const BigInt *a, const BigInt *b) {
    if (a->len != b->len) return a->len > b->len ? 1 : -1;
    for (int i = a->len - 1; i >= 0; i--)
        if (a->d[i] != b->d[i]) return a->d[i] > b->d[i] ? 1 : -1;
    return 0;
}

static int bigint_cmp(const BigInt *a, const BigInt *b) {
    if (a->sign != b->sign) return a->sign > b->sign ? 1 : -1;
    if (a->sign == 0) return 0;
    int c = bigint_cmp_abs(a, b);
    return a->sign > 0 ? c : -c;
}

static void bigint_add_abs(BigInt *r, const BigInt *a, const BigInt *b) {
    int maxlen = a->len > b->len ? a->len : b->len;
    __uint128_t carry = 0;
    for (int i = 0; i < maxlen; i++) {
        __uint128_t da = i < a->len ? a->d[i] : 0;
        __uint128_t db = i < b->len ? b->d[i] : 0;
        __uint128_t sum = da + db + carry;
        r->d[i] = (uint32_t)(sum % BASE);
        carry = sum / BASE;
    }
    if (carry) { r->d[maxlen] = (uint32_t)carry; r->len = maxlen + 1; }
    else r->len = maxlen;
    while (r->len > 0 && r->d[r->len-1] == 0) r->len--;
    r->sign = (r->len == 0) ? 0 : 1;
}

static void bigint_sub_abs(BigInt *r, const BigInt *a, const BigInt *b) {
    __uint128_t borrow = 0;
    for (int i = 0; i < a->len; i++) {
        __uint128_t da = a->d[i];
        __uint128_t db = i < b->len ? b->d[i] : 0;
        if (da < db + borrow) {
            r->d[i] = (uint32_t)(da + BASE - db - borrow);
            borrow = 1;
        } else {
            r->d[i] = (uint32_t)(da - db - borrow);
            borrow = 0;
        }
    }
    r->len = a->len;
    while (r->len > 0 && r->d[r->len-1] == 0) r->len--;
    r->sign = (r->len == 0) ? 0 : 1;
}

static void bigint_add(BigInt *r, const BigInt *a, const BigInt *b) {
    if (a->sign == 0) { *r = *b; return; }
    if (b->sign == 0) { *r = *a; return; }
    if (a->sign == b->sign) {
        bigint_add_abs(r, a, b);
        r->sign = a->sign;
    } else {
        int cmp = bigint_cmp_abs(a, b);
        if (cmp >= 0) {
            bigint_sub_abs(r, a, b);
            r->sign = (r->len == 0) ? 0 : a->sign;
        } else {
            bigint_sub_abs(r, b, a);
            r->sign = (r->len == 0) ? 0 : b->sign;
        }
    }
}

static void bigint_sub(BigInt *r, const BigInt *a, const BigInt *b) {
    BigInt nb = *b;
    nb.sign = -nb.sign;
    bigint_add(r, a, &nb);
}

static void bigint_mul(BigInt *r, const BigInt *a, const BigInt *b) {
    if (a->sign == 0 || b->sign == 0) { bigint_zero(r); return; }
    BigInt tmp;
    memset(&tmp, 0, sizeof(tmp));
    for (int i = 0; i < a->len; i++) {
        __uint128_t carry = 0;
        for (int j = 0; j < b->len; j++) {
            __uint128_t prod = (__uint128_t)a->d[i] * b->d[j] + tmp.d[i+j] + carry;
            tmp.d[i+j] = (uint32_t)(prod % BASE);
            carry = prod / BASE;
        }
        int pos = i + b->len;
        while (carry) {
            __uint128_t s = (__uint128_t)tmp.d[pos] + carry;
            tmp.d[pos] = (uint32_t)(s % BASE);
            carry = s / BASE;
            pos++;
        }
    }
    tmp.len = a->len + b->len;
    while (tmp.len > 0 && tmp.d[tmp.len-1] == 0) tmp.len--;
    tmp.sign = (tmp.len == 0) ? 0 : a->sign * b->sign;
    *r = tmp;
}

static void bigint_mul_small(BigInt *r, const BigInt *a, uint64_t b) {
    if (a->sign == 0 || b == 0) { bigint_zero(r); return; }
    BigInt tmp;
    memset(&tmp, 0, sizeof(tmp));
    __uint128_t carry = 0;
    for (int i = 0; i < a->len; i++) {
        __uint128_t prod = (__uint128_t)a->d[i] * b + carry;
        tmp.d[i] = (uint32_t)(prod % BASE);
        carry = prod / BASE;
    }
    int i = a->len;
    while (carry) { tmp.d[i] = (uint32_t)(carry % BASE); carry /= BASE; i++; }
    tmp.len = i;
    tmp.sign = a->sign;
    *r = tmp;
}

static uint64_t bigint_div_small(BigInt *a, uint64_t d) {
    if (a->len == 0) return 0;
    __uint128_t rem = 0;
    for (int i = a->len - 1; i >= 0; i--) {
        __uint128_t cur = rem * BASE + a->d[i];
        a->d[i] = (uint32_t)(cur / d);
        rem = cur % d;
    }
    while (a->len > 0 && a->d[a->len-1] == 0) a->len--;
    if (a->len == 0) a->sign = 0;
    return (uint64_t)rem;
}

static void bigint_add_small(BigInt *a, uint64_t v) {
    if (v == 0) return;
    __uint128_t carry = v;
    int i = 0;
    while (carry) {
        if (i >= a->len) { a->d[i] = 0; a->len = i + 1; }
        __uint128_t s = (__uint128_t)a->d[i] + carry;
        a->d[i] = (uint32_t)(s % BASE);
        carry = s / BASE;
        i++;
    }
    if (a->len > 0 && a->sign == 0) a->sign = 1;
}

/* --- String arithmetic for split --- */

static void bigint_to_str(const BigInt *a, char *buf) {
    if (a->len == 0) { buf[0] = '0'; buf[1] = '\0'; return; }
    int pos = 0;
    pos += sprintf(buf + pos, "%u", a->d[a->len - 1]);
    for (int i = a->len - 2; i >= 0; i--)
        pos += sprintf(buf + pos, "%09u", a->d[i]);
    buf[pos] = '\0';
}

static void str_to_bigint(const char *s, BigInt *a) {
    memset(a, 0, sizeof(*a));
    a->len = 0;
    int n = (int)strlen(s);
    int i = n;
    while (i > 0) {
        int start = i - BASE_DIGITS;
        if (start < 0) start = 0;
        uint32_t limb = 0;
        for (int j = start; j < i; j++) limb = limb * 10 + (s[j] - '0');
        a->d[a->len++] = limb;
        i = start;
    }
    while (a->len > 0 && a->d[a->len-1] == 0) a->len--;
    a->sign = (a->len == 0) ? 0 : 1;
}

static void strip_leading_zeros(char *s) {
    int n = strlen(s);
    int start = 0;
    while (start < n - 1 && s[start] == '0') start++;
    if (start > 0) memmove(s, s + start, n - start + 1);
}

static int cmp_str(const char *a, const char *b) {
    int la = strlen(a), lb = strlen(b);
    if (la != lb) return la > lb ? 1 : -1;
    return strcmp(a, b);
}

static void add_str(const char *a, const char *b, char *result) {
    int la = strlen(a), lb = strlen(b);
    int maxl = la > lb ? la : lb;
    char tmp[STR_BUF];
    int carry = 0;
    for (int i = 0; i < maxl; i++) {
        int da = (i < la) ? a[la-1-i] - '0' : 0;
        int db = (i < lb) ? b[lb-1-i] - '0' : 0;
        int s = da + db + carry;
        tmp[i] = '0' + (s % 10);
        carry = s / 10;
    }
    if (carry) { tmp[maxl] = '0' + carry; maxl++; }
    for (int i = 0; i < maxl / 2; i++) {
        char t = tmp[i]; tmp[i] = tmp[maxl-1-i]; tmp[maxl-1-i] = t;
    }
    tmp[maxl] = '\0';
    strcpy(result, tmp);
}

static void sub_str(const char *a, const char *b, char *result) {
    int la = strlen(a), lb = strlen(b);
    char tmp[STR_BUF];
    int borrow = 0;
    int i = la - 1, j = lb - 1, k = 0;
    while (i >= 0) {
        int da = a[i] - '0' - borrow;
        int db = (j >= 0) ? b[j] - '0' : 0;
        if (da < db) { da += 10; borrow = 1; } else borrow = 0;
        tmp[k++] = '0' + (da - db);
        i--; j--;
    }
    while (k > 1 && tmp[k-1] == '0') k--;
    for (int x = 0; x < k / 2; x++) {
        char t = tmp[x]; tmp[x] = tmp[k-1-x]; tmp[k-1-x] = t;
    }
    tmp[k] = '\0';
    strcpy(result, tmp);
}

static void mul_str_small(const char *a, int d, char *result) {
    if (d == 0) { result[0] = '0'; result[1] = '\0'; return; }
    int n = strlen(a);
    char tmp[STR_BUF];
    int carry = 0;
    for (int i = n - 1; i >= 0; i--) {
        int prod = (a[i] - '0') * d + carry;
        tmp[n - 1 - i] = '0' + (prod % 10);
        carry = prod / 10;
    }
    int pos = n;
    while (carry) {
        tmp[pos] = '0' + (carry % 10);
        carry /= 10;
        pos++;
    }
    for (int i = 0; i < pos / 2; i++) {
        char t = tmp[i]; tmp[i] = tmp[pos-1-i]; tmp[pos-1-i] = t;
    }
    tmp[pos] = '\0';
    strcpy(result, tmp);
}

static void mul_str(const char *a, const char *b, char *result) {
    int la = strlen(a), lb = strlen(b);
    if ((la == 1 && a[0]=='0') || (lb == 1 && b[0]=='0')) { result[0]='0'; result[1]='\0'; return; }
    int tmp[STR_BUF];
    memset(tmp, 0, sizeof(tmp));
    for (int i = la - 1; i >= 0; i--) {
        for (int j = lb - 1; j >= 0; j--) {
            int prod = (a[i]-'0') * (b[j]-'0') + tmp[i+j+1];
            tmp[i+j+1] = prod % 10;
            tmp[i+j] += prod / 10;
        }
    }
    int start = 0;
    while (start < la + lb - 1 && tmp[start] == 0) start++;
    int pos = 0;
    for (int i = start; i < la + lb; i++)
        result[pos++] = '0' + tmp[i];
    result[pos] = '\0';
}

static void str_divmod(const char *a, const char *b, char *q, char *r) {
    if (strcmp(b, "0") == 0) { strcpy(q, "0"); strcpy(r, "0"); return; }
    if (cmp_str(a, b) < 0) { strcpy(q, "0"); strcpy(r, a); return; }
    int al = strlen(a);
    char cur[STR_BUF];
    strcpy(cur, "0");
    int qi = 0;
    for (int i = 0; i < al; i++) {
        /* cur = cur * 10 + a[i] */
        int cl = strlen(cur);
        /* shift left by one digit */
        if (strcmp(cur, "0") == 0) {
            cur[0] = a[i]; cur[1] = '\0';
        } else {
            cur[cl] = a[i]; cur[cl+1] = '\0';
        }
        strip_leading_zeros(cur);
        /* find largest d (0-9) such that d*b <= cur */
        int d = 0;
        for (int dd = 9; dd >= 1; dd--) {
            char prod[STR_BUF];
            mul_str_small(b, dd, prod);
            if (cmp_str(prod, cur) <= 0) { d = dd; break; }
        }
        char prod[STR_BUF];
        mul_str_small(b, d, prod);
        sub_str(cur, prod, cur);
        q[qi++] = '0' + d;
    }
    q[qi] = '\0';
    strip_leading_zeros(q);
    strcpy(r, cur);
}

/* --- Parsing --- */

static void parse_number(const char *s, BigInt *val, int *scale) {
    int sign = 1;
    if (*s == '-') { sign = -1; s++; }
    else if (*s == '+') { s++; }
    char digits[512];
    int ndigits = 0, dot_pos = -1;
    while (*s) {
        if (*s == '.') dot_pos = ndigits;
        else if (*s >= '0' && *s <= '9') digits[ndigits++] = *s;
        s++;
    }
    *scale = (dot_pos >= 0) ? ndigits - dot_pos : 0;
    memset(val, 0, sizeof(*val));
    val->len = 0;
    if (ndigits == 0) { val->sign = 0; return; }
    int i = ndigits;
    while (i > 0) {
        int start = i - BASE_DIGITS;
        if (start < 0) start = 0;
        uint32_t limb = 0;
        for (int j = start; j < i; j++) limb = limb * 10 + (digits[j] - '0');
        val->d[val->len++] = limb;
        i = start;
    }
    while (val->len > 0 && val->d[val->len-1] == 0) val->len--;
    val->sign = (val->len == 0) ? 0 : sign;
}

/* --- Rounding --- */

static void round_to_scale(BigInt *val, int *scale, int target) {
    if (*scale == target) return;
    if (*scale < target) {
        int k = target - *scale;
        for (int i = 0; i < k; i++) bigint_mul_small(val, val, 10);
        *scale = target;
    } else {
        int k = *scale - target;
        int sign = val->sign;
        val->sign = 1;
        uint64_t divisor = 1;
        for (int i = 0; i < k; i++) divisor *= 10;
        uint64_t rem = bigint_div_small(val, divisor);
        uint64_t half = divisor / 2;
        if (rem > half || (rem == half && val->len > 0 && (val->d[0] & 1)))
            bigint_add_small(val, 1);
        val->sign = (val->len == 0) ? 0 : sign;
        *scale = target;
    }
}

static void round_product(BigInt *val, int scale) {
    if (scale > 0) {
        int sign = val->sign;
        val->sign = 1;
        uint64_t div = 1;
        for (int i = 0; i < scale; i++) div *= 10;
        uint64_t rem = bigint_div_small(val, div);
        uint64_t half = div / 2;
        if (rem > half || (rem == half && val->len > 0 && (val->d[0] & 1)))
            bigint_add_small(val, 1);
        val->sign = (val->len == 0) ? 0 : sign;
    } else if (scale < 0) {
        for (int i = 0; i < -scale; i++) bigint_mul_small(val, val, 10);
    }
}

/* --- Formatting --- */

static void format_money(const BigInt *val, int minor, char *buf) {
    if (val->sign == 0) {
        int pos = 0;
        buf[pos++] = '0';
        if (minor > 0) { buf[pos++] = '.'; for (int i = 0; i < minor; i++) buf[pos++] = '0'; }
        buf[pos] = '\0';
        return;
    }
    BigInt av = *val; av.sign = 1;
    char digits[512];
    bigint_to_str(&av, digits);
    int dlen = (int)strlen(digits), pos = 0;
    if (val->sign < 0) buf[pos++] = '-';
    if (minor > 0) {
        if (dlen > minor) {
            int il = dlen - minor;
            for (int i = 0; i < il; i++) {
                if (i > 0 && (il - i) % 3 == 0) buf[pos++] = ',';
                buf[pos++] = digits[i];
            }
            buf[pos++] = '.';
            for (int i = il; i < dlen; i++) buf[pos++] = digits[i];
        } else {
            buf[pos++] = '0'; buf[pos++] = '.';
            for (int i = 0; i < minor - dlen; i++) buf[pos++] = '0';
            for (int i = 0; i < dlen; i++) buf[pos++] = digits[i];
        }
    } else {
        for (int i = 0; i < dlen; i++) {
            if (i > 0 && (dlen - i) % 3 == 0) buf[pos++] = ',';
            buf[pos++] = digits[i];
        }
    }
    buf[pos] = '\0';
}

/* --- Lookup --- */

static Account *find_account(const char *name) {
    for (int i = 0; i < num_accounts; i++)
        if (strcmp(accounts[i].name, name) == 0) return &accounts[i];
    return NULL;
}

static Currency *find_currency(const char *code) {
    for (int i = 0; i < num_currencies; i++)
        if (strcmp(currencies[i].code, code) == 0) return &currencies[i];
    return NULL;
}

/* --- Tokenize --- */

static int tokenize(char *line, char **toks, int max) {
    int n = 0; char *p = line;
    while (*p && n < max) {
        while (*p == ' ' || *p == '\t') p++;
        if (!*p || *p == '\n') break;
        toks[n++] = p;
        while (*p && *p != ' ' && *p != '\t' && *p != '\n') p++;
        if (*p) { *p = '\0'; p++; }
    }
    return n;
}

static int cmp_acct(const void *a, const void *b) {
    return strcmp(((Account*)a)->name, ((Account*)b)->name);
}
static int cmp_curr(const void *a, const void *b) {
    return strcmp(((Currency*)a)->code, ((Currency*)b)->code);
}

/* --- Main --- */

int main(int argc, char *argv[]) {
    if (argc < 2) return 1;
    char path[1024];
    snprintf(path, sizeof(path), "%s/ledger.txt", argv[1]);
    FILE *f = fopen(path, "r");
    if (!f) return 1;

    char line[MAX_LINE];
    int line_num = 0;

    while (fgets(line, sizeof(line), f)) {
        line_num++;
        int len = (int)strlen(line);
        while (len > 0 && (line[len-1]=='\n'||line[len-1]=='\r')) line[--len]='\0';

        char *p = line;
        while (*p==' '||*p=='\t') p++;
        if (*p=='\0'||*p=='#') continue;

        char *toks[MAX_TOKENS];
        int nt = tokenize(line, toks, MAX_TOKENS);
        if (nt == 0) continue;

        if (strcmp(toks[0], "currency") == 0) {
            Currency c;
            strcpy(c.code, toks[1]);
            c.minor = atoi(toks[2]);
            currencies[num_currencies++] = c;
        }
        else if (strcmp(toks[0], "open") == 0) {
            char *name = toks[1];
            if (find_account(name)) {
                rejections[num_rejections].line = line_num;
                snprintf(rejections[num_rejections].reason, 512, "account exists %s", name);
                num_rejections++;
                continue;
            }
            Currency *cur = find_currency(toks[2]);
            Account *acc = &accounts[num_accounts++];
            strcpy(acc->name, name);
            strcpy(acc->code, toks[2]);
            bigint_zero(&acc->balance);
            bigint_zero(&acc->limit);
            if (nt >= 4) {
                BigInt lim; int ls;
                parse_number(toks[3], &lim, &ls);
                round_to_scale(&lim, &ls, cur->minor);
                acc->limit = lim;
            }
        }
        else if (strcmp(toks[0], "deposit") == 0) {
            Account *acc = find_account(toks[1]);
            if (!acc) {
                rejections[num_rejections].line = line_num;
                snprintf(rejections[num_rejections].reason,512,"unknown account %s",toks[1]);
                num_rejections++; continue;
            }
            Currency *cur = find_currency(acc->code);
            BigInt amt; int sc;
            parse_number(toks[2], &amt, &sc);
            round_to_scale(&amt, &sc, cur->minor);
            if (amt.sign <= 0) {
                rejections[num_rejections].line = line_num;
                snprintf(rejections[num_rejections].reason,512,"non-positive amount");
                num_rejections++; continue;
            }
            bigint_add(&acc->balance, &acc->balance, &amt);
        }
        else if (strcmp(toks[0], "withdraw") == 0) {
            Account *acc = find_account(toks[1]);
            if (!acc) {
                rejections[num_rejections].line = line_num;
                snprintf(rejections[num_rejections].reason,512,"unknown account %s",toks[1]);
                num_rejections++; continue;
            }
            Currency *cur = find_currency(acc->code);
            BigInt amt; int sc;
            parse_number(toks[2], &amt, &sc);
            round_to_scale(&amt, &sc, cur->minor);
            if (amt.sign <= 0) {
                rejections[num_rejections].line = line_num;
                snprintf(rejections[num_rejections].reason,512,"non-positive amount");
                num_rejections++; continue;
            }
            BigInt tmp;
            bigint_add(&tmp, &acc->balance, &acc->limit);
            if (bigint_cmp(&tmp, &amt) < 0) {
                rejections[num_rejections].line = line_num;
                snprintf(rejections[num_rejections].reason,512,"insufficient funds %s",toks[1]);
                num_rejections++; continue;
            }
            bigint_sub(&acc->balance, &acc->balance, &amt);
        }
        else if (strcmp(toks[0], "transfer") == 0) {
            Account *from = find_account(toks[1]);
            Account *to = find_account(toks[2]);
            if (!from) {
                rejections[num_rejections].line = line_num;
                snprintf(rejections[num_rejections].reason,512,"unknown account %s",toks[1]);
                num_rejections++; continue;
            }
            if (!to) {
                rejections[num_rejections].line = line_num;
                snprintf(rejections[num_rejections].reason,512,"unknown account %s",toks[2]);
                num_rejections++; continue;
            }
            if (strcmp(from->code, to->code) != 0) {
                rejections[num_rejections].line = line_num;
                snprintf(rejections[num_rejections].reason,512,"currency mismatch");
                num_rejections++; continue;
            }
            Currency *cur = find_currency(from->code);
            BigInt amt; int sc;
            parse_number(toks[3], &amt, &sc);
            round_to_scale(&amt, &sc, cur->minor);
            if (amt.sign <= 0) {
                rejections[num_rejections].line = line_num;
                snprintf(rejections[num_rejections].reason,512,"non-positive amount");
                num_rejections++; continue;
            }
            BigInt tmp;
            bigint_add(&tmp, &from->balance, &from->limit);
            if (bigint_cmp(&tmp, &amt) < 0) {
                rejections[num_rejections].line = line_num;
                snprintf(rejections[num_rejections].reason,512,"insufficient funds %s",toks[1]);
                num_rejections++; continue;
            }
            bigint_sub(&from->balance, &from->balance, &amt);
            bigint_add(&to->balance, &to->balance, &amt);
        }
        else if (strcmp(toks[0], "convert") == 0) {
            Account *from = find_account(toks[1]);
            Account *to = find_account(toks[2]);
            if (!from) {
                rejections[num_rejections].line = line_num;
                snprintf(rejections[num_rejections].reason,512,"unknown account %s",toks[1]);
                num_rejections++; continue;
            }
            if (!to) {
                rejections[num_rejections].line = line_num;
                snprintf(rejections[num_rejections].reason,512,"unknown account %s",toks[2]);
                num_rejections++; continue;
            }
            Currency *cf = find_currency(from->code);
            Currency *ct = find_currency(to->code);
            BigInt amt; int sc;
            parse_number(toks[3], &amt, &sc);
            round_to_scale(&amt, &sc, cf->minor);
            if (amt.sign <= 0) {
                rejections[num_rejections].line = line_num;
                snprintf(rejections[num_rejections].reason,512,"non-positive amount");
                num_rejections++; continue;
            }
            BigInt tmp;
            bigint_add(&tmp, &from->balance, &from->limit);
            if (bigint_cmp(&tmp, &amt) < 0) {
                rejections[num_rejections].line = line_num;
                snprintf(rejections[num_rejections].reason,512,"insufficient funds %s",toks[1]);
                num_rejections++; continue;
            }
            bigint_sub(&from->balance, &from->balance, &amt);
            BigInt rv; int rs;
            parse_number(toks[4], &rv, &rs);
            BigInt prod;
            bigint_mul(&prod, &amt, &rv);
            int s = cf->minor + rs - ct->minor;
            round_product(&prod, s);
            bigint_add(&to->balance, &to->balance, &prod);
        }
        else if (strcmp(toks[0], "interest") == 0) {
            Account *acc = find_account(toks[1]);
            if (!acc) {
                rejections[num_rejections].line = line_num;
                snprintf(rejections[num_rejections].reason,512,"unknown account %s",toks[1]);
                num_rejections++; continue;
            }
            BigInt rv; int rs;
            parse_number(toks[2], &rv, &rs);
            BigInt prod;
            bigint_mul(&prod, &acc->balance, &rv);
            round_product(&prod, rs);
            bigint_add(&acc->balance, &acc->balance, &prod);
        }
        else if (strcmp(toks[0], "split") == 0) {
            Account *from = find_account(toks[1]);
            if (!from) {
                rejections[num_rejections].line = line_num;
                snprintf(rejections[num_rejections].reason,512,"unknown account %s",toks[1]);
                num_rejections++; continue;
            }
            int ntargets = nt - 3;
            Account *targets[MAX_TARGETS];
            char weight_str[MAX_TARGETS][STR_BUF];
            int unk = 0; char unk_name[256] = "";
            for (int i = 0; i < ntargets; i++) {
                char *colon = strchr(toks[3+i], ':');
                if (!colon) { targets[i]=NULL; weight_str[i][0]='0'; weight_str[i][1]='\0'; continue; }
                *colon = '\0';
                targets[i] = find_account(toks[3+i]);
                if (!targets[i] && !unk) { strcpy(unk_name, toks[3+i]); unk = 1; }
                strcpy(weight_str[i], colon+1);
                strip_leading_zeros(weight_str[i]);
            }
            if (unk) {
                rejections[num_rejections].line = line_num;
                snprintf(rejections[num_rejections].reason,512,"unknown account %s",unk_name);
                num_rejections++; continue;
            }
            int mismatch = 0;
            for (int i = 0; i < ntargets; i++)
                if (strcmp(targets[i]->code, from->code) != 0) { mismatch = 1; break; }
            if (mismatch) {
                rejections[num_rejections].line = line_num;
                snprintf(rejections[num_rejections].reason,512,"currency mismatch");
                num_rejections++; continue;
            }
            Currency *cur = find_currency(from->code);
            BigInt amt; int sc;
            parse_number(toks[2], &amt, &sc);
            round_to_scale(&amt, &sc, cur->minor);
            if (amt.sign <= 0) {
                rejections[num_rejections].line = line_num;
                snprintf(rejections[num_rejections].reason,512,"non-positive amount");
                num_rejections++; continue;
            }
            BigInt tmp;
            bigint_add(&tmp, &from->balance, &from->limit);
            if (bigint_cmp(&tmp, &amt) < 0) {
                rejections[num_rejections].line = line_num;
                snprintf(rejections[num_rejections].reason,512,"insufficient funds %s",toks[1]);
                num_rejections++; continue;
            }
            /* Execute split */
            bigint_sub(&from->balance, &from->balance, &amt);
            /* amt is positive, get its string representation */
            char amt_str[STR_BUF];
            bigint_to_str(&amt, amt_str);
            /* Compute W = sum of weights */
            char W_str[STR_BUF] = "0";
            for (int i = 0; i < ntargets; i++) {
                char tmpstr[STR_BUF];
                add_str(W_str, weight_str[i], tmpstr);
                strcpy(W_str, tmpstr);
            }
            /* For each target, compute base and remainder */
            char base_str[MAX_TARGETS][STR_BUF];
            char rem_str[MAX_TARGETS][STR_BUF];
            BigInt bases[MAX_TARGETS];
            for (int i = 0; i < ntargets; i++) {
                char aw_str[STR_BUF];
                mul_str(amt_str, weight_str[i], aw_str);
                str_divmod(aw_str, W_str, base_str[i], rem_str[i]);
                str_to_bigint(base_str[i], &bases[i]);
            }
            /* Compute leftover = amt - sum(bases) */
            BigInt total_base; bigint_zero(&total_base);
            for (int i = 0; i < ntargets; i++)
                bigint_add(&total_base, &total_base, &bases[i]);
            BigInt leftover_bi;
            bigint_sub(&leftover_bi, &amt, &total_base);
            /* leftover is a small non-negative integer */
            uint64_t leftover = 0;
            if (leftover_bi.sign != 0) {
                for (int i = leftover_bi.len-1; i >= 0; i--)
                    leftover = leftover * BASE + leftover_bi.d[i];
            }
            /* Sort targets by remainder descending, stable (ties by original order) */
            int order[MAX_TARGETS];
            for (int i = 0; i < ntargets; i++) order[i] = i;
            for (int i = 1; i < ntargets; i++) {
                int key = order[i];
                int j = i - 1;
                while (j >= 0 && cmp_str(rem_str[order[j]], rem_str[key]) < 0) {
                    order[j+1] = order[j]; j--;
                }
                order[j+1] = key;
            }
            for (uint64_t i = 0; i < leftover && i < (uint64_t)ntargets; i++)
                bigint_add_small(&bases[order[i]], 1);
            for (int i = 0; i < ntargets; i++)
                bigint_add(&targets[i]->balance, &targets[i]->balance, &bases[i]);
        }
    }
    fclose(f);

    /* Output */
    for (int i = 0; i < num_rejections; i++)
        printf("line %d: REJECT %s\n", rejections[i].line, rejections[i].reason);
    printf("\n");

    qsort(accounts, num_accounts, sizeof(Account), cmp_acct);
    for (int i = 0; i < num_accounts; i++) {
        char buf[512];
        Currency *cur = find_currency(accounts[i].code);
        format_money(&accounts[i].balance, cur->minor, buf);
        printf("%s %s %s\n", accounts[i].name, accounts[i].code, buf);
    }
    printf("\n");

    qsort(currencies, num_currencies, sizeof(Currency), cmp_curr);
    for (int i = 0; i < num_currencies; i++) {
        int cnt = 0;
        BigInt total; bigint_zero(&total);
        for (int j = 0; j < num_accounts; j++) {
            if (strcmp(accounts[j].code, currencies[i].code) == 0) {
                bigint_add(&total, &total, &accounts[j].balance);
                cnt++;
            }
        }
        if (cnt == 0) continue;
        char buf[512];
        format_money(&total, currencies[i].minor, buf);
        printf("total %s %s (%d accounts)\n", currencies[i].code, buf, cnt);
    }

    return 0;
}

use std::collections::HashMap;
use std::fs;

const BASE: u64 = 1_000_000_000;

#[derive(Clone, Debug)]
struct BigInt {
    neg: bool,
    digits: Vec<u32>,
}

impl BigInt {
    fn zero() -> Self { BigInt { neg: false, digits: vec![] } }
    fn one() -> Self { BigInt { neg: false, digits: vec![1] } }
    fn is_zero(&self) -> bool { self.digits.is_empty() }

    fn from_u64(n: u64) -> Self {
        if n == 0 { return Self::zero(); }
        let mut digits = vec![];
        let mut v = n;
        while v > 0 {
            digits.push((v % BASE) as u32);
            v /= BASE;
        }
        BigInt { neg: false, digits }
    }

    fn to_u64(&self) -> u64 {
        let mut result = 0u64;
        let mut mult = 1u64;
        for &d in &self.digits {
            result += (d as u64) * mult;
            mult *= BASE;
        }
        result
    }

    fn from_decimal_str(s: &str) -> Self {
        let mut result = Self::zero();
        for &ch in s.as_bytes() {
            if ch >= b'0' && ch <= b'9' {
                result = result.mul_small(10).add_small((ch - b'0') as u32);
            }
        }
        result
    }

    fn add_small(&self, d: u32) -> Self {
        if d == 0 { return self.clone(); }
        let mut digits = self.digits.clone();
        let mut carry = d as u64;
        let mut i = 0;
        while carry > 0 {
            if i >= digits.len() { digits.push(0); }
            let sum = digits[i] as u64 + carry;
            digits[i] = (sum % BASE) as u32;
            carry = sum / BASE;
            i += 1;
        }
        BigInt { neg: self.neg, digits }
    }

    fn mul_small(&self, d: u32) -> Self {
        if d == 0 || self.is_zero() { return Self::zero(); }
        let mut digits = Vec::with_capacity(self.digits.len() + 2);
        let mut carry = 0u64;
        for &dg in &self.digits {
            let prod = dg as u64 * d as u64 + carry;
            digits.push((prod % BASE) as u32);
            carry = prod / BASE;
        }
        while carry > 0 {
            digits.push((carry % BASE) as u32);
            carry /= BASE;
        }
        BigInt { neg: self.neg, digits }
    }

    fn cmp_mag(&self, other: &Self) -> std::cmp::Ordering {
        if self.digits.len() != other.digits.len() {
            return self.digits.len().cmp(&other.digits.len());
        }
        for i in (0..self.digits.len()).rev() {
            if self.digits[i] != other.digits[i] {
                return self.digits[i].cmp(&other.digits[i]);
            }
        }
        std::cmp::Ordering::Equal
    }

    fn add(&self, other: &Self) -> Self {
        if self.neg == other.neg {
            let digits = add_mags(&self.digits, &other.digits);
            BigInt { neg: self.neg, digits }
        } else {
            match self.cmp_mag(other) {
                std::cmp::Ordering::Equal => Self::zero(),
                std::cmp::Ordering::Greater => {
                    let digits = sub_mags(&self.digits, &other.digits);
                    BigInt { neg: self.neg, digits }
                }
                std::cmp::Ordering::Less => {
                    let digits = sub_mags(&other.digits, &self.digits);
                    BigInt { neg: other.neg, digits }
                }
            }
        }
    }

    fn sub(&self, other: &Self) -> Self {
        self.add(&BigInt { neg: !other.neg, digits: other.digits.clone() })
    }

    fn mul(&self, other: &Self) -> Self {
        if self.is_zero() || other.is_zero() { return Self::zero(); }
        let mut result = vec![0u64; self.digits.len() + other.digits.len()];
        for i in 0..self.digits.len() {
            let mut carry = 0u64;
            for j in 0..other.digits.len() {
                let cur = result[i + j] + self.digits[i] as u64 * other.digits[j] as u64 + carry;
                result[i + j] = cur % BASE;
                carry = cur / BASE;
            }
            let mut k = i + other.digits.len();
            while carry > 0 {
                let cur = result[k] + carry;
                result[k] = cur % BASE;
                carry = cur / BASE;
                k += 1;
            }
        }
        let digits: Vec<u32> = result.iter().map(|&x| x as u32).collect();
        let neg = self.neg != other.neg;
        let mut r = BigInt { neg, digits };
        r.normalize();
        r
    }

    fn normalize(&mut self) {
        while let Some(&last) = self.digits.last() {
            if last == 0 { self.digits.pop(); } else { break; }
        }
        if self.digits.is_empty() { self.neg = false; }
    }

    fn is_odd(&self) -> bool {
        if self.digits.is_empty() { return false; }
        self.digits[0] % 2 == 1
    }

    fn mul_pow10(&self, k: usize) -> BigInt {
        if k == 0 || self.is_zero() { return self.clone(); }
        let mut digits = self.to_decimal_digits();
        for _ in 0..k { digits.push(0); }
        let mut result = Self::from_decimal_digits(&digits);
        result.neg = self.neg;
        result
    }

    fn pow10(k: usize) -> BigInt {
        if k == 0 { return Self::one(); }
        let mut digits = vec![1u8];
        for _ in 0..k { digits.push(0); }
        Self::from_decimal_digits(&digits)
    }

    fn divmod_pow10(mag: &BigInt, k: usize) -> (BigInt, BigInt) {
        if k == 0 { return (mag.clone(), BigInt::zero()); }
        if mag.is_zero() { return (BigInt::zero(), BigInt::zero()); }
        let digits = mag.to_decimal_digits();
        if digits.len() <= k {
            return (BigInt::zero(), mag.clone());
        }
        let q_digits = &digits[..digits.len() - k];
        let r_digits = &digits[digits.len() - k..];
        (Self::from_decimal_digits(q_digits), Self::from_decimal_digits(r_digits))
    }

    fn divmod_mag(&self, other: &Self) -> (BigInt, BigInt) {
        if other.is_zero() { panic!("division by zero"); }
        if self.cmp_mag(other) == std::cmp::Ordering::Less {
            return (BigInt::zero(), self.clone());
        }
        let dividend = self.to_decimal_digits();
        let divisor = other.to_decimal_digits();
        let (q_digits, r_digits) = long_division(&dividend, &divisor);
        (Self::from_decimal_digits(&q_digits), Self::from_decimal_digits(&r_digits))
    }

    fn to_decimal_digits(&self) -> Vec<u8> {
        if self.digits.is_empty() { return vec![0]; }
        let top = self.digits.len() - 1;
        let mut s = format!("{}", self.digits[top]);
        for i in (0..top).rev() {
            s += &format!("{:09}", self.digits[i]);
        }
        s.bytes().map(|b| b - b'0').collect()
    }

    fn from_decimal_digits(digits: &[u8]) -> Self {
        let mut result = Self::zero();
        for &d in digits {
            result = result.mul_small(10).add_small(d as u32);
        }
        result
    }
}

fn add_mags(a: &[u32], b: &[u32]) -> Vec<u32> {
    let mut result = Vec::with_capacity(a.len().max(b.len()) + 1);
    let mut carry = 0u64;
    let len = a.len().max(b.len());
    for i in 0..len {
        let da = if i < a.len() { a[i] as u64 } else { 0 };
        let db = if i < b.len() { b[i] as u64 } else { 0 };
        let sum = da + db + carry;
        result.push((sum % BASE) as u32);
        carry = sum / BASE;
    }
    if carry > 0 { result.push(carry as u32); }
    result
}

fn sub_mags(a: &[u32], b: &[u32]) -> Vec<u32> {
    let mut result = Vec::with_capacity(a.len());
    let mut borrow = 0i64;
    for i in 0..a.len() {
        let da = a[i] as i64;
        let db = if i < b.len() { b[i] as i64 } else { 0 };
        let mut diff = da - db - borrow;
        if diff < 0 { diff += BASE as i64; borrow = 1; } else { borrow = 0; }
        result.push(diff as u32);
    }
    while let Some(&last) = result.last() {
        if last == 0 { result.pop(); } else { break; }
    }
    result
}

fn long_division(dividend: &[u8], divisor: &[u8]) -> (Vec<u8>, Vec<u8>) {
    if cmp_digit_arrays(dividend, divisor) == std::cmp::Ordering::Less {
        return (vec![0], dividend.to_vec());
    }
    let mut quotient = Vec::new();
    let mut remainder: Vec<u8> = vec![];
    for &digit in dividend {
        remainder.push(digit);
        while remainder.len() > 1 && remainder[0] == 0 {
            remainder.remove(0);
        }
        let mut count = 0u8;
        while cmp_digit_arrays(&remainder, divisor) != std::cmp::Ordering::Less {
            remainder = sub_digit_arrays(&remainder, divisor);
            count += 1;
        }
        quotient.push(count);
    }
    while quotient.len() > 1 && quotient[0] == 0 { quotient.remove(0); }
    (quotient, remainder)
}

fn cmp_digit_arrays(a: &[u8], b: &[u8]) -> std::cmp::Ordering {
    if a.len() != b.len() { return a.len().cmp(&b.len()); }
    for i in 0..a.len() {
        if a[i] != b[i] { return a[i].cmp(&b[i]); }
    }
    std::cmp::Ordering::Equal
}

fn sub_digit_arrays(a: &[u8], b: &[u8]) -> Vec<u8> {
    let mut result = vec![0u8; a.len()];
    let mut borrow = 0i8;
    for i in (0..a.len()).rev() {
        let da = a[i] as i8;
        let db = if i >= a.len() - b.len() { b[i - (a.len() - b.len())] as i8 } else { 0 };
        let mut diff = da - db - borrow;
        if diff < 0 { diff += 10; borrow = 1; } else { borrow = 0; }
        result[i] = diff as u8;
    }
    while result.len() > 1 && result[0] == 0 { result.remove(0); }
    result
}

#[derive(Clone, Debug)]
struct Decimal {
    neg: bool,
    mag: BigInt,
    scale: usize,
}

impl Decimal {
    fn zero(scale: usize) -> Self {
        Decimal { neg: false, mag: BigInt::zero(), scale }
    }

    fn is_zero(&self) -> bool { self.mag.is_zero() }

    fn from_str(s: &str) -> Self {
        let (neg, rest) = if s.starts_with('-') { (true, &s[1..]) } else { (false, s) };
        let (int_part, frac_part) = if let Some(pos) = rest.find('.') {
            (&rest[..pos], &rest[pos + 1..])
        } else {
            (rest, "")
        };
        let scale = frac_part.len();
        let digits_str = format!("{}{}", int_part, frac_part);
        let mag = BigInt::from_decimal_str(&digits_str);
        if mag.is_zero() {
            Decimal { neg: false, mag: BigInt::zero(), scale }
        } else {
            Decimal { neg, mag, scale }
        }
    }

    fn add(&self, other: &Decimal) -> Decimal {
        let scale = self.scale.max(other.scale);
        let sm = self.mag.mul_pow10(scale - self.scale);
        let om = other.mag.mul_pow10(scale - other.scale);
        if self.neg == other.neg {
            let mag = BigInt { neg: false, digits: add_mags(&sm.digits, &om.digits) };
            if mag.is_zero() {
                Decimal { neg: false, mag: BigInt::zero(), scale }
            } else {
                Decimal { neg: self.neg, mag, scale }
            }
        } else {
            match sm.cmp_mag(&om) {
                std::cmp::Ordering::Equal => Decimal { neg: false, mag: BigInt::zero(), scale },
                std::cmp::Ordering::Greater => {
                    let mag = BigInt { neg: false, digits: sub_mags(&sm.digits, &om.digits) };
                    Decimal { neg: self.neg, mag, scale }
                }
                std::cmp::Ordering::Less => {
                    let mag = BigInt { neg: false, digits: sub_mags(&om.digits, &sm.digits) };
                    Decimal { neg: other.neg, mag, scale }
                }
            }
        }
    }

    fn sub(&self, other: &Decimal) -> Decimal {
        self.add(&Decimal { neg: !other.neg, mag: other.mag.clone(), scale: other.scale })
    }

    fn mul(&self, other: &Decimal) -> Decimal {
        if self.is_zero() || other.is_zero() {
            return Decimal { neg: false, mag: BigInt::zero(), scale: self.scale + other.scale };
        }
        let neg = self.neg != other.neg;
        let mag = self.mag.mul(&other.mag);
        Decimal { neg, mag, scale: self.scale + other.scale }
    }

    fn round_to(&self, minor_units: usize) -> Decimal {
        if self.is_zero() {
            return Decimal { neg: false, mag: BigInt::zero(), scale: minor_units };
        }
        if self.scale <= minor_units {
            let mag = self.mag.mul_pow10(minor_units - self.scale);
            Decimal { neg: self.neg, mag, scale: minor_units }
        } else {
            let k = self.scale - minor_units;
            let (q, r) = BigInt::divmod_pow10(&self.mag, k);
            let two_r = r.mul_small(2);
            let divisor = BigInt::pow10(k);
            let mag = match two_r.cmp_mag(&divisor) {
                std::cmp::Ordering::Less => q,
                std::cmp::Ordering::Greater => q.add_small(1),
                std::cmp::Ordering::Equal => {
                    if q.is_odd() { q.add_small(1) } else { q }
                }
            };
            if mag.is_zero() {
                Decimal { neg: false, mag: BigInt::zero(), scale: minor_units }
            } else {
                Decimal { neg: self.neg, mag, scale: minor_units }
            }
        }
    }

    fn cmp_same_scale(&self, other: &Decimal) -> std::cmp::Ordering {
        if self.neg != other.neg {
            if self.is_zero() && other.is_zero() { return std::cmp::Ordering::Equal; }
            if self.neg { return std::cmp::Ordering::Less; }
            else { return std::cmp::Ordering::Greater; }
        }
        if self.neg {
            self.mag.cmp_mag(&other.mag).reverse()
        } else {
            self.mag.cmp_mag(&other.mag)
        }
    }

    fn format(&self, minor_units: usize) -> String {
        if self.is_zero() {
            if minor_units == 0 {
                return "0".to_string();
            } else {
                return format!("0.{}", "0".repeat(minor_units));
            }
        }
        let digits = self.mag.to_decimal_digits();
        let mut mag_str: String = digits.iter().map(|&d| (d + b'0') as char).collect();
        if mag_str.len() <= minor_units {
            mag_str = "0".repeat(minor_units - mag_str.len() + 1) + &mag_str;
        }
        let int_part = if minor_units == 0 { &mag_str[..] } else { &mag_str[..mag_str.len() - minor_units] };
        let frac_part = if minor_units > 0 { &mag_str[mag_str.len() - minor_units..] } else { "" };
        let int_with_commas = add_commas(int_part);
        let sign = if self.neg { "-" } else { "" };
        if minor_units > 0 {
            format!("{}{}.{}", sign, int_with_commas, frac_part)
        } else {
            format!("{}{}", sign, int_with_commas)
        }
    }
}

fn add_commas(s: &str) -> String {
    if s.len() <= 3 { return s.to_string(); }
    let mut result = String::new();
    let len = s.len();
    let first_group = len % 3;
    if first_group > 0 {
        result.push_str(&s[..first_group]);
    }
    let mut i = first_group;
    while i < len {
        if !result.is_empty() { result.push(','); }
        result.push_str(&s[i..i + 3]);
        i += 3;
    }
    result
}

struct AccountInfo {
    currency: String,
    balance: Decimal,
    limit: Decimal,
}

fn main() {
    let args: Vec<String> = std::env::args().collect();
    let dir = &args[1];
    let content = fs::read_to_string(format!("{}/ledger.txt", dir)).unwrap();
    let lines: Vec<&str> = content.lines().collect();

    let mut currencies: HashMap<String, usize> = HashMap::new();
    let mut accounts: HashMap<String, AccountInfo> = HashMap::new();
    let mut rejections: Vec<String> = Vec::new();

    for (i, line) in lines.iter().enumerate() {
        let line_num = i + 1;
        let trimmed = line.trim();
        if trimmed.is_empty() || trimmed.starts_with('#') {
            continue;
        }
        let fields: Vec<&str> = trimmed.split_whitespace().collect();
        if fields.is_empty() { continue; }
        let cmd = fields[0];

        match cmd {
            "currency" => {
                let code = fields[1].to_string();
                let minor: usize = fields[2].parse().unwrap();
                currencies.insert(code, minor);
            }
            "open" => {
                let name = fields[1].to_string();
                let code = fields[2].to_string();
                let minor = *currencies.get(&code).unwrap();
                if accounts.contains_key(&name) {
                    rejections.push(format!("line {}: REJECT account exists {}", line_num, name));
                    continue;
                }
                let limit = if fields.len() > 3 {
                    Decimal::from_str(fields[3]).round_to(minor)
                } else {
                    Decimal::zero(minor)
                };
                accounts.insert(name, AccountInfo {
                    currency: code,
                    balance: Decimal::zero(minor),
                    limit,
                });
            }
            "deposit" => {
                let name = fields[1].to_string();
                let amount_str = fields[2];
                if !accounts.contains_key(&name) {
                    rejections.push(format!("line {}: REJECT unknown account {}", line_num, name));
                    continue;
                }
                let minor = *currencies.get(&accounts[&name].currency).unwrap();
                let amount = Decimal::from_str(amount_str).round_to(minor);
                if amount.is_zero() || amount.neg {
                    rejections.push(format!("line {}: REJECT non-positive amount", line_num));
                    continue;
                }
                let acct = accounts.get_mut(&name).unwrap();
                acct.balance = acct.balance.add(&amount);
            }
            "withdraw" => {
                let name = fields[1].to_string();
                let amount_str = fields[2];
                if !accounts.contains_key(&name) {
                    rejections.push(format!("line {}: REJECT unknown account {}", line_num, name));
                    continue;
                }
                let minor = *currencies.get(&accounts[&name].currency).unwrap();
                let amount = Decimal::from_str(amount_str).round_to(minor);
                if amount.is_zero() || amount.neg {
                    rejections.push(format!("line {}: REJECT non-positive amount", line_num));
                    continue;
                }
                let acct = accounts.get(&name).unwrap();
                let new_bal = acct.balance.sub(&amount);
                let neg_limit = Decimal { neg: true, mag: acct.limit.mag.clone(), scale: acct.limit.scale };
                if new_bal.cmp_same_scale(&neg_limit) == std::cmp::Ordering::Less {
                    rejections.push(format!("line {}: REJECT insufficient funds {}", line_num, name));
                    continue;
                }
                let acct = accounts.get_mut(&name).unwrap();
                acct.balance = new_bal;
            }
            "transfer" => {
                let from = fields[1].to_string();
                let to = fields[2].to_string();
                let amount_str = fields[3];
                if !accounts.contains_key(&from) {
                    rejections.push(format!("line {}: REJECT unknown account {}", line_num, from));
                    continue;
                }
                if !accounts.contains_key(&to) {
                    rejections.push(format!("line {}: REJECT unknown account {}", line_num, to));
                    continue;
                }
                let from_cur = accounts[&from].currency.clone();
                let to_cur = accounts[&to].currency.clone();
                if from_cur != to_cur {
                    rejections.push(format!("line {}: REJECT currency mismatch", line_num));
                    continue;
                }
                let minor = *currencies.get(&from_cur).unwrap();
                let amount = Decimal::from_str(amount_str).round_to(minor);
                if amount.is_zero() || amount.neg {
                    rejections.push(format!("line {}: REJECT non-positive amount", line_num));
                    continue;
                }
                let acct = accounts.get(&from).unwrap();
                let new_bal = acct.balance.sub(&amount);
                let neg_limit = Decimal { neg: true, mag: acct.limit.mag.clone(), scale: acct.limit.scale };
                if new_bal.cmp_same_scale(&neg_limit) == std::cmp::Ordering::Less {
                    rejections.push(format!("line {}: REJECT insufficient funds {}", line_num, from));
                    continue;
                }
                let acct = accounts.get_mut(&from).unwrap();
                acct.balance = acct.balance.sub(&amount);
                let acct = accounts.get_mut(&to).unwrap();
                acct.balance = acct.balance.add(&amount);
            }
            "convert" => {
                let from = fields[1].to_string();
                let to = fields[2].to_string();
                let amount_str = fields[3];
                let rate_str = fields[4];
                if !accounts.contains_key(&from) {
                    rejections.push(format!("line {}: REJECT unknown account {}", line_num, from));
                    continue;
                }
                if !accounts.contains_key(&to) {
                    rejections.push(format!("line {}: REJECT unknown account {}", line_num, to));
                    continue;
                }
                let from_cur = accounts[&from].currency.clone();
                let to_cur = accounts[&to].currency.clone();
                let from_minor = *currencies.get(&from_cur).unwrap();
                let to_minor = *currencies.get(&to_cur).unwrap();
                let amount = Decimal::from_str(amount_str).round_to(from_minor);
                if amount.is_zero() || amount.neg {
                    rejections.push(format!("line {}: REJECT non-positive amount", line_num));
                    continue;
                }
                let acct = accounts.get(&from).unwrap();
                let new_bal = acct.balance.sub(&amount);
                let neg_limit = Decimal { neg: true, mag: acct.limit.mag.clone(), scale: acct.limit.scale };
                if new_bal.cmp_same_scale(&neg_limit) == std::cmp::Ordering::Less {
                    rejections.push(format!("line {}: REJECT insufficient funds {}", line_num, from));
                    continue;
                }
                let rate = Decimal::from_str(rate_str);
                let credit = amount.mul(&rate).round_to(to_minor);
                let acct = accounts.get_mut(&from).unwrap();
                acct.balance = acct.balance.sub(&amount);
                let acct = accounts.get_mut(&to).unwrap();
                acct.balance = acct.balance.add(&credit);
            }
            "interest" => {
                let name = fields[1].to_string();
                let rate_str = fields[2];
                if !accounts.contains_key(&name) {
                    rejections.push(format!("line {}: REJECT unknown account {}", line_num, name));
                    continue;
                }
                let acct = accounts.get(&name).unwrap();
                let minor = *currencies.get(&acct.currency).unwrap();
                let balance = acct.balance.clone();
                let rate = Decimal::from_str(rate_str);
                let interest = balance.mul(&rate).round_to(minor);
                let acct = accounts.get_mut(&name).unwrap();
                acct.balance = acct.balance.add(&interest);
            }
            "split" => {
                let from = fields[1].to_string();
                let amount_str = fields[2];
                let targets: Vec<(String, u64)> = fields[3..].iter().map(|s| {
                    let parts: Vec<&str> = s.splitn(2, ':').collect();
                    (parts[0].to_string(), parts[1].parse::<u64>().unwrap())
                }).collect();

                let all_names: Vec<String> = std::iter::once(from.clone())
                    .chain(targets.iter().map(|(n, _)| n.clone()))
                    .collect();
                let mut unknown_found = false;
                for name in &all_names {
                    if !accounts.contains_key(name) {
                        rejections.push(format!("line {}: REJECT unknown account {}", line_num, name));
                        unknown_found = true;
                        break;
                    }
                }
                if unknown_found { continue; }

                let from_cur = accounts[&from].currency.clone();
                let mut mismatch = false;
                for (name, _) in &targets {
                    if accounts[name].currency != from_cur {
                        mismatch = true;
                        break;
                    }
                }
                if mismatch {
                    rejections.push(format!("line {}: REJECT currency mismatch", line_num));
                    continue;
                }

                let minor = *currencies.get(&from_cur).unwrap();
                let amount = Decimal::from_str(amount_str).round_to(minor);
                if amount.is_zero() || amount.neg {
                    rejections.push(format!("line {}: REJECT non-positive amount", line_num));
                    continue;
                }

                let acct = accounts.get(&from).unwrap();
                let new_bal = acct.balance.sub(&amount);
                let neg_limit = Decimal { neg: true, mag: acct.limit.mag.clone(), scale: acct.limit.scale };
                if new_bal.cmp_same_scale(&neg_limit) == std::cmp::Ordering::Less {
                    rejections.push(format!("line {}: REJECT insufficient funds {}", line_num, from));
                    continue;
                }

                // Execute split
                let a_mag = amount.mag.clone();
                let w: u64 = targets.iter().map(|(_, wi)| *wi).sum();
                let w_big = BigInt::from_u64(w);

                struct ShareInfo { share: BigInt, remainder: BigInt, index: usize }
                let mut share_infos: Vec<ShareInfo> = Vec::new();
                let mut total_share = BigInt::zero();

                for (i, (_, wi)) in targets.iter().enumerate() {
                    let wi_big = BigInt::from_u64(*wi);
                    let product = a_mag.mul(&wi_big);
                    let (q, r) = product.divmod_mag(&w_big);
                    total_share = total_share.add(&q);
                    share_infos.push(ShareInfo { share: q, remainder: r, index: i });
                }

                let leftover = a_mag.sub(&total_share);
                let leftover_val = leftover.to_u64() as usize;

                share_infos.sort_by(|a, b| {
                    b.remainder.cmp_mag(&a.remainder).then(a.index.cmp(&b.index))
                });

                for i in 0..leftover_val {
                    share_infos[i].share = share_infos[i].share.add_small(1);
                }

                let acct = accounts.get_mut(&from).unwrap();
                acct.balance = acct.balance.sub(&amount);

                for info in &share_infos {
                    let target_name = &targets[info.index].0;
                    let share_minor = Decimal { neg: false, mag: info.share.clone(), scale: minor };
                    let acct = accounts.get_mut(target_name).unwrap();
                    acct.balance = acct.balance.add(&share_minor);
                }
            }
            _ => {}
        }
    }

    // Output
    for r in &rejections {
        println!("{}", r);
    }
    println!();

    let mut sorted_accounts: Vec<(&String, &AccountInfo)> = accounts.iter().collect();
    sorted_accounts.sort_by_key(|(name, _)| name.as_bytes().to_vec());

    for (name, acct) in &sorted_accounts {
        let minor = *currencies.get(&acct.currency).unwrap();
        println!("{} {} {}", name, acct.currency, acct.balance.format(minor));
    }

    println!();

    let mut totals: HashMap<String, (Decimal, usize)> = HashMap::new();
    for (_, acct) in &accounts {
        let minor = *currencies.get(&acct.currency).unwrap();
        let entry = totals.entry(acct.currency.clone()).or_insert_with(|| (Decimal::zero(minor), 0));
        entry.0 = entry.0.add(&acct.balance);
        entry.1 += 1;
    }

    let mut sorted_totals: Vec<(&String, &Decimal, usize)> = totals.iter().map(|(k, (v, c))| (k, v, *c)).collect();
    sorted_totals.sort_by_key(|(code, _, _)| code.as_bytes().to_vec());

    for (code, total, count) in &sorted_totals {
        let minor = *currencies.get(code).unwrap();
        println!("total {} {} ({} accounts)", code, total.format(minor), count);
    }
}

use std::collections::HashMap;
use std::fs;

const BASE: u64 = 1_000_000_000;

#[derive(Clone, Debug)]
struct BigInt {
    neg: bool,
    digits: Vec<u32>,
}

impl BigInt {
    fn zero() -> Self { BigInt { neg: false, digits: vec![] } }
    fn one() -> Self { BigInt { neg: false, digits: vec![1] } }
    fn is_zero(&self) -> bool { self.digits.is_empty() }

    fn from_u64(n: u64) -> Self {
        if n == 0 { return Self::zero(); }
        let mut digits = vec![];
        let mut v = n;
        while v > 0 {
            digits.push((v % BASE) as u32);
            v /= BASE;
        }
        BigInt { neg: false, digits }
    }

    fn to_u64(&self) -> u64 {
        let mut result = 0u64;
        let mut mult = 1u64;
        for &d in &self.digits {
            result += (d as u64) * mult;
            mult *= BASE;
        }
        result
    }

    fn from_decimal_str(s: &str) -> Self {
        let mut result = Self::zero();
        for &ch in s.as_bytes() {
            if ch >= b'0' && ch <= b'9' {
                result = result.mul_small(10).add_small((ch - b'0') as u32);
            }
        }
        result
    }

    fn add_small(&self, d: u32) -> Self {
        if d == 0 { return self.clone(); }
        let mut digits = self.digits.clone();
        let mut carry = d as u64;
        let mut i = 0;
        while carry > 0 {
            if i >= digits.len() { digits.push(0); }
            let sum = digits[i] as u64 + carry;
            digits[i] = (sum % BASE) as u32;
            carry = sum / BASE;
            i += 1;
        }
        BigInt { neg: self.neg, digits }
    }

    fn mul_small(&self, d: u32) -> Self {
        if d == 0 || self.is_zero() { return Self::zero(); }
        let mut digits = Vec::with_capacity(self.digits.len() + 2);
        let mut carry = 0u64;
        for &dg in &self.digits {
            let prod = dg as u64 * d as u64 + carry;
            digits.push((prod % BASE) as u32);
            carry = prod / BASE;
        }
        while carry > 0 {
            digits.push((carry % BASE) as u32);
            carry /= BASE;
        }
        BigInt { neg: self.neg, digits }
    }

    fn cmp_mag(&self, other: &Self) -> std::cmp::Ordering {
        if self.digits.len() != other.digits.len() {
            return self.digits.len().cmp(&other.digits.len());
        }
        for i in (0..self.digits.len()).rev() {
            if self.digits[i] != other.digits[i] {
                return self.digits[i].cmp(&other.digits[i]);
            }
        }
        std::cmp::Ordering::Equal
    }

    fn add(&self, other: &Self) -> Self {
        if self.neg == other.neg {
            let digits = add_mags(&self.digits, &other.digits);
            BigInt { neg: self.neg, digits }
        } else {
            match self.cmp_mag(other) {
                std::cmp::Ordering::Equal => Self::zero(),
                std::cmp::Ordering::Greater => {
                    let digits = sub_mags(&self.digits, &other.digits);
                    BigInt { neg: self.neg, digits }
                }
                std::cmp::Ordering::Less => {
                    let digits = sub_mags(&other.digits, &self.digits);
                    BigInt { neg: other.neg, digits }
                }
            }
        }
    }

    fn sub(&self, other: &Self) -> Self {
        self.add(&BigInt { neg: !other.neg, digits: other.digits.clone() })
    }

    fn mul(&self, other: &Self) -> Self {
        if self.is_zero() || other.is_zero() { return Self::zero(); }
        let mut result = vec![0u64; self.digits.len() + other.digits.len()];
        for i in 0..self.digits.len() {
            let mut carry = 0u64;
            for j in 0..other.digits.len() {
                let cur = result[i + j] + self.digits[i] as u64 * other.digits[j] as u64 + carry;
                result[i + j] = cur % BASE;
                carry = cur / BASE;
            }
            let mut k = i + other.digits.len();
            while carry > 0 {
                let cur = result[k] + carry;
                result[k] = cur % BASE;
                carry = cur / BASE;
                k += 1;
            }
        }
        let digits: Vec<u32> = result.iter().map(|&x| x as u32).collect();
        let neg = self.neg != other.neg;
        let mut r = BigInt { neg, digits };
        r.normalize();
        r
    }

    fn normalize(&mut self) {
        while let Some(&last) = self.digits.last() {
            if last == 0 { self.digits.pop(); } else { break; }
        }
        if self.digits.is_empty() { self.neg = false; }
    }

    fn is_odd(&self) -> bool {
        if self.digits.is_empty() { return false; }
        self.digits[0] % 2 == 1
    }

    fn mul_pow10(&self, k: usize) -> BigInt {
        if k == 0 || self.is_zero() { return self.clone(); }
        let mut digits = self.to_decimal_digits();
        for _ in 0..k { digits.push(0); }
        let mut result = Self::from_decimal_digits(&digits);
        result.neg = self.neg;
        result
    }

    fn pow10(k: usize) -> BigInt {
        if k == 0 { return Self::one(); }
        let mut digits = vec![1u8];
        for _ in 0..k { digits.push(0); }
        Self::from_decimal_digits(&digits)
    }

    fn divmod_pow10(mag: &BigInt, k: usize) -> (BigInt, BigInt) {
        if k == 0 { return (mag.clone(), BigInt::zero()); }
        if mag.is_zero() { return (BigInt::zero(), BigInt::zero()); }
        let digits = mag.to_decimal_digits();
        if digits.len() <= k {
            return (BigInt::zero(), mag.clone());
        }
        let q_digits = &digits[..digits.len() - k];
        let r_digits = &digits[digits.len() - k..];
        (Self::from_decimal_digits(q_digits), Self::from_decimal_digits(r_digits))
    }

    fn divmod_mag(&self, other: &Self) -> (BigInt, BigInt) {
        if other.is_zero() { panic!("division by zero"); }
        if self.cmp_mag(other) == std::cmp::Ordering::Less {
            return (BigInt::zero(), self.clone());
        }
        let dividend = self.to_decimal_digits();
        let divisor = other.to_decimal_digits();
        let (q_digits, r_digits) = long_division(&dividend, &divisor);
        (Self::from_decimal_digits(&q_digits), Self::from_decimal_digits(&r_digits))
    }

    fn to_decimal_digits(&self) -> Vec<u8> {
        if self.digits.is_empty() { return vec![0]; }
        let top = self.digits.len() - 1;
        let mut s = format!("{}", self.digits[top]);
        for i in (0..top).rev() {
            s += &format!("{:09}", self.digits[i]);
        }
        s.bytes().map(|b| b - b'0').collect()
    }

    fn from_decimal_digits(digits: &[u8]) -> Self {
        let mut result = Self::zero();
        for &d in digits {
            result = result.mul_small(10).add_small(d as u32);
        }
        result
    }
}

fn add_mags(a: &[u32], b: &[u32]) -> Vec<u32> {
    let mut result = Vec::with_capacity(a.len().max(b.len()) + 1);
    let mut carry = 0u64;
    let len = a.len().max(b.len());
    for i in 0..len {
        let da = if i < a.len() { a[i] as u64 } else { 0 };
        let db = if i < b.len() { b[i] as u64 } else { 0 };
        let sum = da + db + carry;
        result.push((sum % BASE) as u32);
        carry = sum / BASE;
    }
    if carry > 0 { result.push(carry as u32); }
    result
}

fn sub_mags(a: &[u32], b: &[u32]) -> Vec<u32> {
    let mut result = Vec::with_capacity(a.len());
    let mut borrow = 0i64;
    for i in 0..a.len() {
        let da = a[i] as i64;
        let db = if i < b.len() { b[i] as i64 } else { 0 };
        let mut diff = da - db - borrow;
        if diff < 0 { diff += BASE as i64; borrow = 1; } else { borrow = 0; }
        result.push(diff as u32);
    }
    while let Some(&last) = result.last() {
        if last == 0 { result.pop(); } else { break; }
    }
    result
}

fn long_division(dividend: &[u8], divisor: &[u8]) -> (Vec<u8>, Vec<u8>) {
    if cmp_digit_arrays(dividend, divisor) == std::cmp::Ordering::Less {
        return (vec![0], dividend.to_vec());
    }
    let mut quotient = Vec::new();
    let mut remainder: Vec<u8> = vec![];
    for &digit in dividend {
        remainder.push(digit);
        while remainder.len() > 1 && remainder[0] == 0 {
            remainder.remove(0);
        }
        let mut count = 0u8;
        while cmp_digit_arrays(&remainder, divisor) != std::cmp::Ordering::Less {
            remainder = sub_digit_arrays(&remainder, divisor);
            count += 1;
        }
        quotient.push(count);
    }
    while quotient.len() > 1 && quotient[0] == 0 { quotient.remove(0); }
    (quotient, remainder)
}

fn cmp_digit_arrays(a: &[u8], b: &[u8]) -> std::cmp::Ordering {
    if a.len() != b.len() { return a.len().cmp(&b.len()); }
    for i in 0..a.len() {
        if a[i] != b[i] { return a[i].cmp(&b[i]); }
    }
    std::cmp::Ordering::Equal
}

fn sub_digit_arrays(a: &[u8], b: &[u8]) -> Vec<u8> {
    let mut result = vec![0u8; a.len()];
    let mut borrow = 0i8;
    for i in (0..a.len()).rev() {
        let da = a[i] as i8;
        let db = if i >= a.len() - b.len() { b[i - (a.len() - b.len())] as i8 } else { 0 };
        let mut diff = da - db - borrow;
        if diff < 0 { diff += 10; borrow = 1; } else { borrow = 0; }
        result[i] = diff as u8;
    }
    while result.len() > 1 && result[0] == 0 { result.remove(0); }
    result
}

#[derive(Clone, Debug)]
struct Decimal {
    neg: bool,
    mag: BigInt,
    scale: usize,
}

impl Decimal {
    fn zero(scale: usize) -> Self {
        Decimal { neg: false, mag: BigInt::zero(), scale }
    }

    fn is_zero(&self) -> bool { self.mag.is_zero() }

    fn from_str(s: &str) -> Self {
        let (neg, rest) = if s.starts_with('-') { (true, &s[1..]) } else { (false, s) };
        let (int_part, frac_part) = if let Some(pos) = rest.find('.') {
            (&rest[..pos], &rest[pos + 1..])
        } else {
            (rest, "")
        };
        let scale = frac_part.len();
        let digits_str = format!("{}{}", int_part, frac_part);
        let mag = BigInt::from_decimal_str(&digits_str);
        if mag.is_zero() {
            Decimal { neg: false, mag: BigInt::zero(), scale }
        } else {
            Decimal { neg, mag, scale }
        }
    }

    fn add(&self, other: &Decimal) -> Decimal {
        let scale = self.scale.max(other.scale);
        let sm = self.mag.mul_pow10(scale - self.scale);
        let om = other.mag.mul_pow10(scale - other.scale);
        if self.neg == other.neg {
            let mag = BigInt { neg: false, digits: add_mags(&sm.digits, &om.digits) };
            if mag.is_zero() {
                Decimal { neg: false, mag: BigInt::zero(), scale }
            } else {
                Decimal { neg: self.neg, mag, scale }
            }
        } else {
            match sm.cmp_mag(&om) {
                std::cmp::Ordering::Equal => Decimal { neg: false, mag: BigInt::zero(), scale },
                std::cmp::Ordering::Greater => {
                    let mag = BigInt { neg: false, digits: sub_mags(&sm.digits, &om.digits) };
                    if mag.is_zero() {
                        Decimal { neg: false, mag: BigInt::zero(), scale }
                    } else {
                        Decimal { neg: self.neg, mag, scale }
                    }
                }
                std::cmp::Ordering::Less => {
                    let mag = BigInt { neg: false, digits: sub_mags(&om.digits, &sm.digits) };
                    if mag.is_zero() {
                        Decimal { neg: false, mag: BigInt::zero(), scale }
                    } else {
                        Decimal { neg: other.neg, mag, scale }
                    }
                }
            }
        }
    }

    fn sub(&self, other: &Decimal) -> Decimal {
        self.add(&Decimal { neg: !other.neg, mag: other.mag.clone(), scale: other.scale })
    }

    fn mul(&self, other: &Decimal) -> Decimal {
        if self.is_zero() || other.is_zero() {
            return Decimal { neg: false, mag: BigInt::zero(), scale: self.scale + other.scale };
        }
        let neg = self.neg != other.neg;
        let mag = self.mag.mul(&other.mag);
        Decimal { neg, mag, scale: self.scale + other.scale }
    }

    fn round_to(&self, minor_units: usize) -> Decimal {
        if self.is_zero() {
            return Decimal { neg: false, mag: BigInt::zero(), scale: minor_units };
        }
        if self.scale <= minor_units {
            let mag = self.mag.mul_pow10(minor_units - self.scale);
            Decimal { neg: self.neg, mag, scale: minor_units }
        } else {
            let k = self.scale - minor_units;
            let (q, r) = BigInt::divmod_pow10(&self.mag, k);
            let two_r = r.mul_small(2);
            let divisor = BigInt::pow10(k);
            let mag = match two_r.cmp_mag(&divisor) {
                std::cmp::Ordering::Less => q,
                std::cmp::Ordering::Greater => q.add_small(1),
                std::cmp::Ordering::Equal => {
                    if q.is_odd() { q.add_small(1) } else { q }
                }
            };
            if mag.is_zero() {
                Decimal { neg: false, mag: BigInt::zero(), scale: minor_units }
            } else {
                Decimal { neg: self.neg, mag, scale: minor_units }
            }
        }
    }

    fn cmp_same_scale(&self, other: &Decimal) -> std::cmp::Ordering {
        if self.is_zero() && other.is_zero() { return std::cmp::Ordering::Equal; }
        if self.neg != other.neg {
            if self.neg { return std::cmp::Ordering::Less; }
            else { return std::cmp::Ordering::Greater; }
        }
        if self.neg {
            self.mag.cmp_mag(&other.mag).reverse()
        } else {
            self.mag.cmp_mag(&other.mag)
        }
    }

    fn format(&self, minor_units: usize) -> String {
        if self.is_zero() {
            if minor_units == 0 {
                return "0".to_string();
            } else {
                return format!("0.{}", "0".repeat(minor_units));
            }
        }
        let digits = self.mag.to_decimal_digits();
        let mut mag_str: String = digits.iter().map(|&d| (d + b'0') as char).collect();
        if mag_str.len() <= minor_units {
            mag_str = "0".repeat(minor_units - mag_str.len() + 1) + &mag_str;
        }
        let int_part = if minor_units == 0 { &mag_str[..] } else { &mag_str[..mag_str.len() - minor_units] };
        let frac_part = if minor_units > 0 { &mag_str[mag_str.len() - minor_units..] } else { "" };
        let int_with_commas = add_commas(int_part);
        let sign = if self.neg { "-" } else { "" };
        if minor_units > 0 {
            format!("{}{}.{}", sign, int_with_commas, frac_part)
        } else {
            format!("{}{}", sign, int_with_commas)
        }
    }
}

fn add_commas(s: &str) -> String {
    if s.len() <= 3 { return s.to_string(); }
    let mut result = String::new();
    let len = s.len();
    let first_group = len % 3;
    if first_group > 0 {
        result.push_str(&s[..first_group]);
    }
    let mut i = first_group;
    while i < len {
        if !result.is_empty() { result.push(','); }
        result.push_str(&s[i..i + 3]);
        i += 3;
    }
    result
}

struct AccountInfo {
    currency: String,
    balance: Decimal,
    limit: Decimal,
}

fn main() {
    let args: Vec<String> = std::env::args().collect();
    let dir = &args[1];
    let content = fs::read_to_string(format!("{}/ledger.txt", dir)).unwrap();
    let lines: Vec<&str> = content.lines().collect();

    let mut currencies: HashMap<String, usize> = HashMap::new();
    let mut accounts: HashMap<String, AccountInfo> = HashMap::new();
    let mut rejections: Vec<String> = Vec::new();

    for (i, line) in lines.iter().enumerate() {
        let line_num = i + 1;
        let trimmed = line.trim();
        if trimmed.is_empty() || trimmed.starts_with('#') {
            continue;
        }
        let fields: Vec<&str> = trimmed.split_whitespace().collect();
        if fields.is_empty() { continue; }
        let cmd = fields[0];

        match cmd {
            "currency" => {
                let code = fields[1].to_string();
                let minor: usize = fields[2].parse().unwrap();
                currencies.insert(code, minor);
            }
            "open" => {
                let name = fields[1].to_string();
                let code = fields[2].to_string();
                let minor = *currencies.get(&code).unwrap();
                if accounts.contains_key(&name) {
                    rejections.push(format!("line {}: REJECT account exists {}", line_num, name));
                    continue;
                }
                let limit = if fields.len() > 3 {
                    Decimal::from_str(fields[3]).round_to(minor)
                } else {
                    Decimal::zero(minor)
                };
                accounts.insert(name, AccountInfo {
                    currency: code,
                    balance: Decimal::zero(minor),
                    limit,
                });
            }
            "deposit" => {
                let name = fields[1].to_string();
                let amount_str = fields[2];
                if !accounts.contains_key(&name) {
                    rejections.push(format!("line {}: REJECT unknown account {}", line_num, name));
                    continue;
                }
                let minor = *currencies.get(&accounts[&name].currency).unwrap();
                let amount = Decimal::from_str(amount_str).round_to(minor);
                if amount.is_zero() || amount.neg {
                    rejections.push(format!("line {}: REJECT non-positive amount", line_num));
                    continue;
                }
                let acct = accounts.get_mut(&name).unwrap();
                acct.balance = acct.balance.add(&amount);
            }
            "withdraw" => {
                let name = fields[1].to_string();
                let amount_str = fields[2];
                if !accounts.contains_key(&name) {
                    rejections.push(format!("line {}: REJECT unknown account {}", line_num, name));
                    continue;
                }
                let minor = *currencies.get(&accounts[&name].currency).unwrap();
                let amount = Decimal::from_str(amount_str).round_to(minor);
                if amount.is_zero() || amount.neg {
                    rejections.push(format!("line {}: REJECT non-positive amount", line_num));
                    continue;
                }
                let acct = accounts.get(&name).unwrap();
                let new_bal = acct.balance.sub(&amount);
                let neg_limit = Decimal { neg: !acct.limit.is_zero(), mag: acct.limit.mag.clone(), scale: acct.limit.scale };
                if new_bal.cmp_same_scale(&neg_limit) == std::cmp::Ordering::Less {
                    rejections.push(format!("line {}: REJECT insufficient funds {}", line_num, name));
                    continue;
                }
                let acct = accounts.get_mut(&name).unwrap();
                acct.balance = new_bal;
            }
            "transfer" => {
                let from = fields[1].to_string();
                let to = fields[2].to_string();
                let amount_str = fields[3];
                if !accounts.contains_key(&from) {
                    rejections.push(format!("line {}: REJECT unknown account {}", line_num, from));
                    continue;
                }
                if !accounts.contains_key(&to) {
                    rejections.push(format!("line {}: REJECT unknown account {}", line_num, to));
                    continue;
                }
                let from_cur = accounts[&from].currency.clone();
                let to_cur = accounts[&to].currency.clone();
                if from_cur != to_cur {
                    rejections.push(format!("line {}: REJECT currency mismatch", line_num));
                    continue;
                }
                let minor = *currencies.get(&from_cur).unwrap();
                let amount = Decimal::from_str(amount_str).round_to(minor);
                if amount.is_zero() || amount.neg {
                    rejections.push(format!("line {}: REJECT non-positive amount", line_num));
                    continue;
                }
                let acct = accounts.get(&from).unwrap();
                let new_bal = acct.balance.sub(&amount);
                let neg_limit = Decimal { neg: !acct.limit.is_zero(), mag: acct.limit.mag.clone(), scale: acct.limit.scale };
                if new_bal.cmp_same_scale(&neg_limit) == std::cmp::Ordering::Less {
                    rejections.push(format!("line {}: REJECT insufficient funds {}", line_num, from));
                    continue;
                }
                let acct = accounts.get_mut(&from).unwrap();
                acct.balance = acct.balance.sub(&amount);
                let acct = accounts.get_mut(&to).unwrap();
                acct.balance = acct.balance.add(&amount);
            }
            "convert" => {
                let from = fields[1].to_string();
                let to = fields[2].to_string();
                let amount_str = fields[3];
                let rate_str = fields[4];
                if !accounts.contains_key(&from) {
                    rejections.push(format!("line {}: REJECT unknown account {}", line_num, from));
                    continue;
                }
                if !accounts.contains_key(&to) {
                    rejections.push(format!("line {}: REJECT unknown account {}", line_num, to));
                    continue;
                }
                let from_cur = accounts[&from].currency.clone();
                let to_cur = accounts[&to].currency.clone();
                let from_minor = *currencies.get(&from_cur).unwrap();
                let to_minor = *currencies.get(&to_cur).unwrap();
                let amount = Decimal::from_str(amount_str).round_to(from_minor);
                if amount.is_zero() || amount.neg {
                    rejections.push(format!("line {}: REJECT non-positive amount", line_num));
                    continue;
                }
                let acct = accounts.get(&from).unwrap();
                let new_bal = acct.balance.sub(&amount);
                let neg_limit = Decimal { neg: !acct.limit.is_zero(), mag: acct.limit.mag.clone(), scale: acct.limit.scale };
                if new_bal.cmp_same_scale(&neg_limit) == std::cmp::Ordering::Less {
                    rejections.push(format!("line {}: REJECT insufficient funds {}", line_num, from));
                    continue;
                }
                let rate = Decimal::from_str(rate_str);
                let credit = amount.mul(&rate).round_to(to_minor);
                let acct = accounts.get_mut(&from).unwrap();
                acct.balance = acct.balance.sub(&amount);
                let acct = accounts.get_mut(&to).unwrap();
                acct.balance = acct.balance.add(&credit);
            }
            "interest" => {
                let name = fields[1].to_string();
                let rate_str = fields[2];
                if !accounts.contains_key(&name) {
                    rejections.push(format!("line {}: REJECT unknown account {}", line_num, name));
                    continue;
                }
                let acct = accounts.get(&name).unwrap();
                let minor = *currencies.get(&acct.currency).unwrap();
                let balance = acct.balance.clone();
                let rate = Decimal::from_str(rate_str);
                let interest = balance.mul(&rate).round_to(minor);
                let acct = accounts.get_mut(&name).unwrap();
                acct.balance = acct.balance.add(&interest);
            }
            "split" => {
                let from = fields[1].to_string();
                let amount_str = fields[2];
                let targets: Vec<(String, u64)> = fields[3..].iter().map(|s| {
                    let parts: Vec<&str> = s.splitn(2, ':').collect();
                    (parts[0].to_string(), parts[1].parse::<u64>().unwrap())
                }).collect();

                let all_names: Vec<String> = std::iter::once(from.clone())
                    .chain(targets.iter().map(|(n, _)| n.clone()))
                    .collect();
                let mut unknown_found = false;
                for name in &all_names {
                    if !accounts.contains_key(name) {
                        rejections.push(format!("line {}: REJECT unknown account {}", line_num, name));
                        unknown_found = true;
                        break;
                    }
                }
                if unknown_found { continue; }

                let from_cur = accounts[&from].currency.clone();
                let mut mismatch = false;
                for (name, _) in &targets {
                    if accounts[name].currency != from_cur {
                        mismatch = true;
                        break;
                    }
                }
                if mismatch {
                    rejections.push(format!("line {}: REJECT currency mismatch", line_num));
                    continue;
                }

                let minor = *currencies.get(&from_cur).unwrap();
                let amount = Decimal::from_str(amount_str).round_to(minor);
                if amount.is_zero() || amount.neg {
                    rejections.push(format!("line {}: REJECT non-positive amount", line_num));
                    continue;
                }

                let acct = accounts.get(&from).unwrap();
                let new_bal = acct.balance.sub(&amount);
                let neg_limit = Decimal { neg: !acct.limit.is_zero(), mag: acct.limit.mag.clone(), scale: acct.limit.scale };
                if new_bal.cmp_same_scale(&neg_limit) == std::cmp::Ordering::Less {
                    rejections.push(format!("line {}: REJECT insufficient funds {}", line_num, from));
                    continue;
                }

                // Execute split
                let a_mag = amount.mag.clone();
                let w: u64 = targets.iter().map(|(_, wi)| *wi).sum();
                let w_big = BigInt::from_u64(w);

                struct ShareInfo { share: BigInt, remainder: BigInt, index: usize }
                let mut share_infos: Vec<ShareInfo> = Vec::new();
                let mut total_share = BigInt::zero();

                for (i, (_, wi)) in targets.iter().enumerate() {
                    let wi_big = BigInt::from_u64(*wi);
                    let product = a_mag.mul(&wi_big);
                    let (q, r) = product.divmod_mag(&w_big);
                    total_share = total_share.add(&q);
                    share_infos.push(ShareInfo { share: q, remainder: r, index: i });
                }

                let leftover = a_mag.sub(&total_share);
                let leftover_val = leftover.to_u64() as usize;

                share_infos.sort_by(|a, b| {
                    b.remainder.cmp_mag(&a.remainder).then(a.index.cmp(&b.index))
                });

                for i in 0..leftover_val {
                    share_infos[i].share = share_infos[i].share.add_small(1);
                }

                let acct = accounts.get_mut(&from).unwrap();
                acct.balance = acct.balance.sub(&amount);

                for info in &share_infos {
                    let target_name = &targets[info.index].0;
                    let share_minor = Decimal { neg: false, mag: info.share.clone(), scale: minor };
                    let acct = accounts.get_mut(target_name).unwrap();
                    acct.balance = acct.balance.add(&share_minor);
                }
            }
            _ => {}
        }
    }

    // Output
    for r in &rejections {
        println!("{}", r);
    }
    println!();

    let mut sorted_accounts: Vec<(&String, &AccountInfo)> = accounts.iter().collect();
    sorted_accounts.sort_by_key(|(name, _)| name.as_bytes().to_vec());

    for (name, acct) in &sorted_accounts {
        let minor = *currencies.get(acct.currency.as_str()).unwrap();
        println!("{} {} {}", name, acct.currency, acct.balance.format(minor));
    }

    println!();

    let mut totals: HashMap<String, (Decimal, usize)> = HashMap::new();
    for (_, acct) in &accounts {
        let minor = *currencies.get(acct.currency.as_str()).unwrap();
        let entry = totals.entry(acct.currency.clone()).or_insert_with(|| (Decimal::zero(minor), 0));
        entry.0 = entry.0.add(&acct.balance);
        entry.1 += 1;
    }

    let mut sorted_totals: Vec<(String, Decimal, usize)> = totals.into_iter().collect();
    sorted_totals.sort_by_key(|(code, _, _)| code.as_bytes().to_vec());

    for (code, total, count) in &sorted_totals {
        let minor = *currencies.get(code.as_str()).unwrap();
        println!("total {} {} ({} accounts)", code, total.format(minor), count);
    }
}

import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;
import javax.crypto.Mac;
import javax.crypto.spec.SecretKeySpec;

public class Main {

    static class JsonParser {
        private final String json;
        private int pos;

        JsonParser(String json) {
            this.json = json;
            this.pos = 0;
        }

        Object parse() {
            skipWhitespace();
            Object result = parseValue();
            skipWhitespace();
            return result;
        }

        Object parseValue() {
            if (pos >= json.length()) return null;
            char c = json.charAt(pos);
            if (c == '{') return parseObject();
            if (c == '[') return parseArray();
            if (c == '"') return parseString();
            if (c == 't' || c == 'f') return parseBoolean();
            if (c == 'n') { pos += 4; return null; }
            return parseNumber();
        }

        Map<String, Object> parseObject() {
            Map<String, Object> map = new LinkedHashMap<>();
            pos++;
            skipWhitespace();
            if (pos < json.length() && json.charAt(pos) == '}') { pos++; return map; }
            while (true) {
                skipWhitespace();
                String key = parseString();
                skipWhitespace();
                pos++;
                skipWhitespace();
                Object value = parseValue();
                map.put(key, value);
                skipWhitespace();
                if (pos < json.length() && json.charAt(pos) == ',') { pos++; } else { break; }
            }
            pos++;
            return map;
        }

        List<Object> parseArray() {
            List<Object> list = new ArrayList<>();
            pos++;
            skipWhitespace();
            if (pos < json.length() && json.charAt(pos) == ']') { pos++; return list; }
            while (true) {
                skipWhitespace();
                list.add(parseValue());
                skipWhitespace();
                if (pos < json.length() && json.charAt(pos) == ',') { pos++; } else { break; }
            }
            pos++;
            return list;
        }

        String parseString() {
            pos++;
            StringBuilder sb = new StringBuilder();
            while (pos < json.length()) {
                char c = json.charAt(pos);
                if (c == '"') { pos++; return sb.toString(); }
                if (c == '\\') {
                    pos++;
                    char esc = json.charAt(pos);
                    switch (esc) {
                        case '"': sb.append('"'); break;
                        case '\\': sb.append('\\'); break;
                        case '/': sb.append('/'); break;
                        case 'b': sb.append('\b'); break;
                        case 'f': sb.append('\f'); break;
                        case 'n': sb.append('\n'); break;
                        case 'r': sb.append('\r'); break;
                        case 't': sb.append('\t'); break;
                        case 'u':
                            String hex = json.substring(pos + 1, pos + 5);
                            sb.append((char) Integer.parseInt(hex, 16));
                            pos += 4;
                            break;
                        default: sb.append(esc);
                    }
                } else {
                    sb.append(c);
                }
                pos++;
            }
            return sb.toString();
        }

        Double parseNumber() {
            int start = pos;
            if (pos < json.length() && json.charAt(pos) == '-') pos++;
            while (pos < json.length() && Character.isDigit(json.charAt(pos))) pos++;
            if (pos < json.length() && json.charAt(pos) == '.') {
                pos++;
                while (pos < json.length() && Character.isDigit(json.charAt(pos))) pos++;
            }
            if (pos < json.length() && (json.charAt(pos) == 'e' || json.charAt(pos) == 'E')) {
                pos++;
                if (pos < json.length() && (json.charAt(pos) == '+' || json.charAt(pos) == '-')) pos++;
                while (pos < json.length() && Character.isDigit(json.charAt(pos))) pos++;
            }
            return Double.parseDouble(json.substring(start, pos));
        }

        Boolean parseBoolean() {
            if (json.startsWith("true", pos)) { pos += 4; return Boolean.TRUE; }
            else { pos += 5; return Boolean.FALSE; }
        }

        void skipWhitespace() {
            while (pos < json.length() && Character.isWhitespace(json.charAt(pos))) pos++;
        }
    }

    static boolean isValidBase64url(String s) {
        if (s.length() % 4 == 1) return false;
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (!((c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z') ||
                  (c >= '0' && c <= '9') || c == '-' || c == '_')) {
                return false;
            }
        }
        return true;
    }

    static byte[] base64urlDecode(String s) {
        int pad = (4 - s.length() % 4) % 4;
        StringBuilder sb = new StringBuilder(s);
        for (int i = 0; i < pad; i++) sb.append('=');
        String std = sb.toString().replace('-', '+').replace('_', '/');
        return Base64.getDecoder().decode(std);
    }

    static byte[] hmac(String alg, byte[] key, byte[] data) throws Exception {
        String macAlg;
        switch (alg) {
            case "HS256": macAlg = "HmacSHA256"; break;
            case "HS384": macAlg = "HmacSHA384"; break;
            case "HS512": macAlg = "HmacSHA512"; break;
            default: throw new IllegalArgumentException(alg);
        }
        Mac mac = Mac.getInstance(macAlg);
        mac.init(new SecretKeySpec(key, macAlg));
        return mac.doFinal(data);
    }

    @SuppressWarnings("unchecked")
    public static void main(String[] args) throws Exception {
        String dir = args[0];

        String configStr = Files.readString(Path.of(dir, "config.json"), StandardCharsets.UTF_8);
        Map<String, Object> config = (Map<String, Object>) new JsonParser(configStr).parse();

        double now = ((Number) config.get("now")).doubleValue();
        double leeway = ((Number) config.get("leeway")).doubleValue();
        String issuer = (String) config.get("issuer");
        String audience = (String) config.get("audience");

        List<Object> keysList = (List<Object>) config.get("keys");
        Map<String, Map<String, Object>> keyMap = new HashMap<>();
        for (Object k : keysList) {
            Map<String, Object> key = (Map<String, Object>) k;
            keyMap.put((String) key.get("kid"), key);
        }

        String tokensStr = Files.readString(Path.of(dir, "tokens.txt"), StandardCharsets.UTF_8);
        String[] lines = tokensStr.split("\n", -1);

        List<String> tokens = new ArrayList<>();
        for (String line : lines) {
            String trimmed = line.trim();
            if (!trimmed.isEmpty()) tokens.add(trimmed);
        }

        int valid = 0, invalid = 0;
        List<String> results = new ArrayList<>();

        for (int i = 0; i < tokens.size(); i++) {
            String token = tokens.get(i);
            int n = i + 1;
            String result = verify(token, now, leeway, issuer, audience, keyMap);
            results.add(n + ": " + result);
            if (result.startsWith("VALID")) valid++; else invalid++;
        }

        for (String r : results) System.out.println(r);
        System.out.println();
        System.out.println("valid=" + valid + " invalid=" + invalid);
    }

    @SuppressWarnings("unchecked")
    static String verify(String token, double now, double leeway, String issuer,
                         String audience, Map<String, Map<String, Object>> keyMap) {
        // Rule 1: MALFORMED
        String[] parts = token.split("\\.", -1);
        if (parts.length != 3) return "MALFORMED";
        for (String part : parts) {
            if (part.isEmpty()) return "MALFORMED";
            if (!isValidBase64url(part)) return "MALFORMED";
        }

        byte[] headerBytes, payloadBytes, sigBytes;
        try {
            headerBytes = base64urlDecode(parts[0]);
            payloadBytes = base64urlDecode(parts[1]);
            sigBytes = base64urlDecode(parts[2]);
        } catch (Exception e) {
            return "MALFORMED";
        }

        Object headerObj, payloadObj;
        try {
            headerObj = new JsonParser(new String(headerBytes, StandardCharsets.UTF_8)).parse();
            payloadObj = new JsonParser(new String(payloadBytes, StandardCharsets.UTF_8)).parse();
        } catch (Exception e) {
            return "MALFORMED";
        }

        if (!(headerObj instanceof Map) || !(payloadObj instanceof Map)) return "MALFORMED";

        Map<String, Object> header = (Map<String, Object>) headerObj;
        Map<String, Object> payload = (Map<String, Object>) payloadObj;

        // Rule 2: UNSUPPORTED_ALG
        Object algObj = header.get("alg");
        if (!(algObj instanceof String)) return "UNSUPPORTED_ALG";
        String alg = (String) algObj;
        if (!alg.equals("HS256") && !alg.equals("HS384") && !alg.equals("HS512"))
            return "UNSUPPORTED_ALG";

        // Rule 3: UNKNOWN_KEY
        Object kidObj = header.get("kid");
        if (!(kidObj instanceof String)) return "UNKNOWN_KEY";
        String kid = (String) kidObj;
        Map<String, Object> key = keyMap.get(kid);
        if (key == null) return "UNKNOWN_KEY";

        // Rule 4: ALG_MISMATCH
        String keyAlg = (String) key.get("alg");
        if (!alg.equals(keyAlg)) return "ALG_MISMATCH";

        // Rule 5: BAD_SIGNATURE
        byte[] secret;
        try {
            secret = base64urlDecode((String) key.get("k"));
        } catch (Exception e) {
            return "BAD_SIGNATURE";
        }

        String signingInput = parts[0] + "." + parts[1];
        byte[] signingBytes = signingInput.getBytes(StandardCharsets.US_ASCII);

        try {
            byte[] expected = hmac(alg, secret, signingBytes);
            if (!Arrays.equals(sigBytes, expected)) return "BAD_SIGNATURE";
        } catch (Exception e) {
            return "BAD_SIGNATURE";
        }

        // Rule 6: EXPIRED
        if (payload.containsKey("exp")) {
            Object expObj = payload.get("exp");
            if (expObj instanceof Number) {
                double exp = ((Number) expObj).doubleValue();
                if (now >= exp + leeway) return "EXPIRED";
            }
        }

        // Rule 7: NOT_YET_VALID
        if (payload.containsKey("nbf")) {
            Object nbfObj = payload.get("nbf");
            if (nbfObj instanceof Number) {
                double nbf = ((Number) nbfObj).doubleValue();
                if (now + leeway < nbf) return "NOT_YET_VALID";
            }
        }

        // Rule 8: BAD_ISSUER
        Object issObj = payload.get("iss");
        if (!(issObj instanceof String) || !issuer.equals(issObj)) return "BAD_ISSUER";

        // Rule 9: BAD_AUDIENCE
        Object audObj = payload.get("aud");
        if (audObj == null) return "BAD_AUDIENCE";
        if (audObj instanceof String) {
            if (!audience.equals(audObj)) return "BAD_AUDIENCE";
        } else if (audObj instanceof List) {
            List<Object> audList = (List<Object>) audObj;
            boolean found = false;
            for (Object a : audList) {
                if (audience.equals(a)) { found = true; break; }
            }
            if (!found) return "BAD_AUDIENCE";
        } else {
            return "BAD_AUDIENCE";
        }

        // VALID
        String sub = (String) payload.get("sub");
        String scopeStr = payload.get("scope") instanceof String ? (String) payload.get("scope") : "";
        String[] scopeParts = scopeStr.split(" ");
        TreeSet<String> scopeSet = new TreeSet<>();
        for (String s : scopeParts) {
            if (!s.isEmpty()) scopeSet.add(s);
        }
        String scopes = String.join(",", scopeSet);

        return "VALID sub=" + sub + " scope=" + scopes;
    }
}

