        if (!(kidObj instanceof String)) return "UNKNOWN_KEY";
        String kid = (String) kidObj;
        Map<String, Object> key = keyMap.get(kid);
        if (key == null) return "UNKNOWN_KEY";

        // Rule 4: ALG_MISMATCH
        String keyAlg = (String) key.get("alg");
        if (!alg.equals(keyAlg)) return "ALG_MISMATCH";

        // Rule 5: BAD_SIGNATURE
        byte[] secret;
        try {
            secret = base64urlDecode((String) key.get("k"));
        } catch (Exception e) {
            return "BAD_SIGNATURE";
        }

        String signingInput = parts[0] + "." + parts[1];
        byte[] signingBytes = signingInput.getBytes(StandardCharsets.US_ASCII);

        try {
            byte[] expected = hmac(alg, secret, signingBytes);
            if (!Arrays.equals(sigBytes, expected)) return "BAD_SIGNATURE";
        } catch (Exception e) {
            return "BAD_SIGNATURE";
        }

        // Rule 6: EXPIRED
        if (payload.containsKey("exp")) {
            Object expObj = payload.get("exp");
            if (expObj instanceof Number) {
                double exp = ((Number) expObj).doubleValue();
                if (now >= exp + leeway) return "EXPIRED";
            }
        }

        // Rule 7: NOT_YET_VALID
        if (payload.containsKey("nbf")) {
            Object nbfObj = payload.get("nbf");
            if (nbfObj instanceof Number) {
                double nbf = ((Number) nbfObj).doubleValue();
                if (now + leeway < nbf) return "NOT_YET_VALID";
            }
        }

        // Rule 8: BAD_ISSUER
        Object issObj = payload.get("iss");
        if (!(issObj instanceof String) || !issuer.equals(issObj)) return "BAD_ISSUER";

        // Rule 9: BAD_AUDIENCE
        Object audObj = payload.get("aud");
        if (audObj == null) return "BAD_AUDIENCE";
        if (audObj instanceof String) {
            if (!audience.equals(audObj)) return "BAD_AUDIENCE";
        } else if (audObj instanceof List) {
            List<Object> audList = (List<Object>) audObj;
            boolean found = false;
            for (Object a : audList) {
                if (audience.equals(a)) { found = true; break; }
            }
            if (!found) return "BAD_AUDIENCE";
        } else {
            return "BAD_AUDIENCE";
        }

        // VALID
        String sub = (String) payload.get("sub");
        String scopeStr = payload.get("scope") instanceof String ? (String) payload.get("scope") : "";
        String[] scopeParts = scopeStr.split(" ");
        TreeSet<String> scopeSet = new TreeSet<>();
        for (String s : scopeParts) {
            if (!s.isEmpty()) scopeSet.add(s);
        }
        String scopes = String.join(",", scopeSet);

        return "VALID sub=" + sub + " scope=" + scopes;
    }
}

import sys
import json


def is_valid_id(x):
    if isinstance(x, str):
        return True
    if isinstance(x, int) and not isinstance(x, bool):
        return True
    return False


def is_integer(x):
    return isinstance(x, int) and not isinstance(x, bool)


def main():
    initialized = False
    store = {}

    TOOL_DEFS = [
        {
            "name": "kv_set",
            "title": "Set a value",
            "description": "Store a string value under a key, replacing any previous value.",
            "inputSchema": {
                "type": "object",
                "properties": {
                    "key": {"type": "string", "minLength": 1},
                    "value": {"type": "string"}
                },
                "required": ["key", "value"],
                "additionalProperties": False
            }
        },
        {
            "name": "kv_get",
            "title": "Get a value",
            "description": "Return the value stored under a key.",
            "inputSchema": {
                "type": "object",
                "properties": {
                    "key": {"type": "string", "minLength": 1}
                },
                "required": ["key"],
                "additionalProperties": False
            }
        },
        {
            "name": "kv_list",
            "title": "List keys",
            "description": "List the stored keys that start with a prefix, sorted by Unicode code point.",
            "inputSchema": {
                "type": "object",
                "properties": {
                    "prefix": {"type": "string"}
                },
                "additionalProperties": False
            },
            "outputSchema": {
                "type": "object",
                "properties": {
                    "keys": {"type": "array", "items": {"type": "string"}},
                    "count": {"type": "integer"}
                },
                "required": ["keys", "count"]
            }
        },
        {
            "name": "sum",
            "title": "Sum integers",
            "description": "Add up a non-empty list of integers.",
            "inputSchema": {
                "type": "object",
                "properties": {
                    "numbers": {
                        "type": "array",
                        "items": {"type": "integer"},
                        "minItems": 1
                    }
                },
                "required": ["numbers"],
                "additionalProperties": False
            },
            "outputSchema": {
                "type": "object",
                "properties": {
                    "sum": {"type": "integer"},
                    "count": {"type": "integer"}
                },
                "required": ["sum", "count"]
            },
            "annotations": {"readOnlyHint": True, "idempotentHint": True}
        },
        {
            "name": "text_stats",
            "title": "Text statistics",
            "description": "Count the words, Unicode code points and UTF-8 bytes of a text.",
            "inputSchema": {
                "type": "object",
                "properties": {
                    "text": {"type": "string"}
                },
                "required": ["text"],
                "additionalProperties": False
            },
            "outputSchema": {
                "type": "object",
                "properties": {
                    "words": {"type": "integer"},
                    "codepoints": {"type": "integer"},
                    "utf8_bytes": {"type": "integer"}
                },
                "required": ["words", "codepoints", "utf8_bytes"]
            },
            "annotations": {"readOnlyHint": True}
        }
    ]

    TOOL_NAMES = {"kv_set", "kv_get", "kv_list", "sum", "text_stats"}
    TOOL_SCHEMAS = {t["name"]: t["inputSchema"] for t in TOOL_DEFS}
    TOOL_HAS_OUTPUT = {t["name"]: "outputSchema" in t for t in TOOL_DEFS}

    def make_error(req_id, code, message):
        return {"jsonrpc": "2.0", "id": req_id, "error": {"code": code, "message": message}}

    def make_result(req_id, result):
        return {"jsonrpc": "2.0", "id": req_id, "result": result}

    def tool_failure(message):
        return {"content": [{"type": "text", "text": message}], "isError": True}

    def tool_success_text(text):
        return {"content": [{"type": "text", "text": text}], "isError": False}

    def tool_success_structured(structured):
        text = json.dumps(structured)
        return {"content": [{"type": "text", "text": text}], "structuredContent": structured, "isError": False}

    def validate_arguments(tool_name, arguments):
        schema = TOOL_SCHEMAS[tool_name]
        properties = schema["properties"]
        required = schema.get("required", [])

        # Step 1: arguments must be an object
        if not isinstance(arguments, dict):
            return "arguments must be an object"

        # Step 2: unknown arguments
        unknown = [k for k in arguments if k not in properties]
        if unknown:
            unknown.sort()
            return f"unknown argument: {unknown[0]}"

        # Step 3: check each property in schema order
        for prop_name in properties:
            prop_schema = properties[prop_name]
            prop_type = prop_schema["type"]

            if prop_name not in arguments:
                if prop_name in required:
                    return f"missing required argument: {prop_name}"
                continue

            value = arguments[prop_name]

            # Type check
            if prop_type == "string":
                if not isinstance(value, str):
                    return f"argument {prop_name} must be a string"
                if "minLength" in prop_schema and len(value) < prop_schema["minLength"]:
                    return f"argument {prop_name} must not be empty"
            elif prop_type == "array":
                if not isinstance(value, list):
                    return f"argument {prop_name} must be an array of integers"
                items_type = prop_schema.get("items", {}).get("type")
                if items_type == "integer":
                    for item in value:
                        if not is_integer(item):
                            return f"argument {prop_name} must be an array of integers"
                if "minItems" in prop_schema and len(value) < prop_schema["minItems"]:
                    return f"argument {prop_name} must not be empty"

        return None

    def execute_tool(tool_name, arguments):
        if tool_name == "kv_set":
            key = arguments["key"]
            value = arguments["value"]
            if key in store:
                store[key] = value
                return tool_success_text(f"updated {key}")
            else:
                store[key] = value
                return tool_success_text(f"created {key}")

        elif tool_name == "kv_get":
            key = arguments["key"]
            if key in store:
                return tool_success_text(store[key])
            else:
                return tool_failure(f"key not found: {key}")

        elif tool_name == "kv_list":
            prefix = arguments.get("prefix", "")
            keys = sorted(k for k in store if k.startswith(prefix))
            result = {"keys": keys, "count": len(keys)}
            return tool_success_structured(result)

        elif tool_name == "sum":
            numbers = arguments["numbers"]
            total = sum(numbers)
            result = {"sum": total, "count": len(numbers)}
            return tool_success_structured(result)

        elif tool_name == "text_stats":
            text = arguments["text"]
            separators = set(' \t\n\r')
            words = 0
            in_word = False
            for ch in text:
                if ch in separators:
                    in_word = False
                else:
                    if not in_word:
                        words += 1
                    in_word = True
            codepoints = len(text)
            utf8_bytes = len(text.encode('utf-8'))
            result = {"words": words, "codepoints": codepoints, "utf8_bytes": utf8_bytes}
            return tool_success_structured(result)

    for line in sys.stdin:
        line = line.rstrip('\r\n')
        if line.strip() == '':
            continue

        # Rule 1: parse JSON
        try:
            obj = json.loads(line)
        except (json.JSONDecodeError, ValueError):
            print(json.dumps(make_error(None, -32700, "Parse error")))
            continue

        # Rule 2: not an object
        if not isinstance(obj, dict):
            print(json.dumps(make_error(None, -32600, "Invalid Request")))
            continue

        # Rule 3: client response (no method, has result or error)
        if "method" not in obj and ("result" in obj or "error" in obj):
            continue

        # Rule 4: invalid request
        invalid = False
        if "jsonrpc" not in obj or obj["jsonrpc"] != "2.0":
            invalid = True
        if "method" not in obj or not isinstance(obj["method"], str):
            invalid = True
        if "id" in obj and not is_valid_id(obj["id"]):
            invalid = True

        if invalid:
            resp_id = obj["id"] if "id" in obj and is_valid_id(obj["id"]) else None
            print(json.dumps(make_error(resp_id, -32600, "Invalid Request")))
            continue

        # Rule 5: notification (valid object without id)
        if "id" not in obj:
            continue

        # Rule 6: request
        req_id = obj["id"]
        method = obj["method"]
        params = obj.get("params")

        # 6a: method not found
        if method not in ("initialize", "ping", "tools/list", "tools/call"):
            print(json.dumps(make_error(req_id, -32601, "Method not found")))
            continue

        # 6b: params present but not an object
        if "params" in obj and not isinstance(params, dict):
            print(json.dumps(make_error(req_id, -32602, "Invalid params")))
            continue

        # 6c: not initialized
        if not initialized and method not in ("initialize", "ping"):
            print(json.dumps(make_error(req_id, -32002, "Server not initialized")))
            continue

        # 6d: dispatch
        if method == "initialize":
            if initialized:
                print(json.dumps(make_error(req_id, -32600, "Already initialized")))
                continue
            if params is None or "protocolVersion" not in params or not isinstance(params["protocolVersion"], str):
                print(json.dumps(make_error(req_id, -32602, "Invalid params")))
                continue
            version = params["protocolVersion"]
            if version not in ("2025-06-18", "2025-03-26", "2024-11-05"):
                version = "2025-06-18"
            initialized = True
            result = {
                "protocolVersion": version,
                "capabilities": {"tools": {"listChanged": False}},
                "serverInfo": {"name": "cb2-kv", "title": "CB2 key-value server", "version": "1.4.2"}
            }
            print(json.dumps(make_result(req_id, result)))

        elif method == "ping":
            print(json.dumps(make_result(req_id, {})))

        elif method == "tools/list":
            print(json.dumps(make_result(req_id, {"tools": TOOL_DEFS})))

        elif method == "tools/call":
            if params is None or "name" not in params or not isinstance(params["name"], str):
                print(json.dumps(make_error(req_id, -32602, "Invalid params")))
                continue

            tool_name = params["name"]
            if tool_name not in TOOL_NAMES:
                print(json.dumps(make_error(req_id, -32602, f"Unknown tool: {tool_name}")))
                continue

            # Get arguments
            if "arguments" in params:
                arguments = params["arguments"]
            else:
                arguments = {}

            # Validate arguments
            err = validate_arguments(tool_name, arguments)
            if err is not None:
                print(json.dumps(make_result(req_id, tool_failure(err))))
                continue

            # Execute tool
            result = execute_tool(tool_name, arguments)
            print(json.dumps(make_result(req_id, result)))

    sys.exit(0)


if __name__ == "__main__":
    main()

import Foundation

// MARK: - JSON Value

enum JSONValue {
    case null
    case bool(Bool)
    case number(Double)
    case string(String)
    case array([JSONValue])
    case object([String: JSONValue])
}

// MARK: - JSON Parser

struct JSONParser {
    let bytes: [UInt8]
    var pos: Int = 0

    init(_ bytes: [UInt8]) {
        self.bytes = bytes
    }

    var current: UInt8? { pos < bytes.count ? bytes[pos] : nil }
    mutating func advance() { pos += 1 }

    mutating func skipWS() {
        while let c = current, c == 0x20 || c == 0x09 || c == 0x0A || c == 0x0D { advance() }
    }

    mutating func parse() -> JSONValue {
        skipWS()
        return parseValue()
    }

    mutating func parseValue() -> JSONValue {
        skipWS()
        guard let c = current else { fatalError("EOF") }
        switch c {
        case 0x6E: expectBytes("null"); return .null
        case 0x74: expectBytes("true"); return .bool(true)
        case 0x66: expectBytes("false"); return .bool(false)
        case 0x22: return .string(parseString())
        case 0x5B: return parseArray()
        case 0x7B: return parseObject()
        default: return .number(parseNumber())
        }
    }

    mutating func expectBytes(_ s: String) {
        for b in s.utf8 {
            guard current == b else { fatalError("Expected \(s)") }
            advance()
        }
    }

    mutating func parseString() -> String {
        advance() // skip "
        var result = ""
        while let c = current {
            if c == 0x22 { advance(); return result }
            if c == 0x5C {
                advance()
                guard let esc = current else { fatalError("EOF in string") }
                advance()
                switch esc {
                case 0x22: result.append("\"")
                case 0x5C: result.append("\\")
                case 0x2F: result.append("/")
                case 0x62: result.append("\u{08}")
                case 0x66: result.append("\u{0C}")
                case 0x6E: result.append("\n")
                case 0x72: result.append("\r")
                case 0x74: result.append("\t")
                case 0x75:
                    let sc = parseUnicodeEscape()
                    result.append(Character(sc))
                default: fatalError("Bad escape")
                }
            } else {
                result.append(decodeUTF8Char())
            }
        }
        fatalError("Unterminated string")
    }

    mutating func parseUnicodeEscape() -> Unicode.Scalar {
        let high = parseHex4()
        if high >= 0xD800 && high <= 0xDBFF {
            guard current == 0x5C else { fatalError("Expected \\") }
            advance()
            guard current == 0x75 else { fatalError("Expected u") }
            advance()
            let low = parseHex4()
            let cp = 0x10000 + ((high - 0xD800) << 10) + (low - 0xDC00)
            return Unicode.Scalar(cp)!
        }
        return Unicode.Scalar(high)!
    }

    mutating func parseHex4() -> UInt32 {
        var r: UInt32 = 0
        for _ in 0..<4 {
            guard let c = current else { fatalError("EOF") }
            advance()
            if c >= 0x30 && c <= 0x39 { r = r * 16 + UInt32(c - 0x30) }
            else if c >= 0x41 && c <= 0x46 { r = r * 16 + UInt32(c - 0x41 + 10) }
            else if c >= 0x61 && c <= 0x66 { r = r * 16 + UInt32(c - 0x61 + 10) }
            else { fatalError("Bad hex") }
        }
        return r
    }

    mutating func decodeUTF8Char() -> Character {
        let b = bytes[pos]
        if b < 0x80 { pos += 1; return Character(Unicode.Scalar(b)) }
        else if b < 0xE0 {
            let cp = (UInt32(b & 0x1F) << 6) | UInt32(bytes[pos+1] & 0x3F)
            pos += 2; return Character(Unicode.Scalar(cp)!)
        } else if b < 0xF0 {
            let cp = (UInt32(b & 0x0F) << 12) | (UInt32(bytes[pos+1] & 0x3F) << 6) | UInt32(bytes[pos+2] & 0x3F)
            pos += 3; return Character(Unicode.Scalar(cp)!)
        } else {
            let cp = (UInt32(b & 0x07) << 18) | (UInt32(bytes[pos+1] & 0x3F) << 12) | (UInt32(bytes[pos+2] & 0x3F) << 6) | UInt32(bytes[pos+3] & 0x3F)
            pos += 4; return Character(Unicode.Scalar(cp)!)
        }
    }

    mutating func parseNumber() -> Double {
        let start = pos
        if current == 0x2D { advance() }
        while let c = current, c >= 0x30 && c <= 0x39 { advance() }
        if current == 0x2E { advance(); while let c = current, c >= 0x30 && c <= 0x39 { advance() } }
        if current == 0x65 || current == 0x45 {
            advance()
            if current == 0x2B || current == 0x2D { advance() }
            while let c = current, c >= 0x30 && c <= 0x39 { advance() }
        }
        return Double(String(bytes: bytes[start..<pos], encoding: .ascii)!)!
    }

    mutating func parseArray() -> JSONValue {
        advance() // [
        var arr: [JSONValue] = []
        skipWS()
        if current == 0x5D { advance(); return .array(arr) }
        while true {
            arr.append(parseValue())
            skipWS()
            if current == 0x2C { advance(); continue }
            if current == 0x5D { advance(); break }
            fatalError("Expected , or ]")
        }
        return .array(arr)
    }

    mutating func parseObject() -> JSONValue {
        advance() // {
        var obj: [String: JSONValue] = [:]
        skipWS()
        if current == 0x7D { advance(); return .object(obj) }
        while true {
            skipWS()
            guard current == 0x22 else { fatalError("Expected \"") }
            let key = parseString()
            skipWS()
            guard current == 0x3A else { fatalError("Expected :") }
            advance()
            obj[key] = parseValue()
            skipWS()
            if current == 0x2C { advance(); continue }
            if current == 0x7D { advance(); break }
            fatalError("Expected , or }")
        }
        return .object(obj)
    }
}

// MARK: - Helpers

func deepEqual(_ a: JSONValue, _ b: JSONValue) -> Bool {
    switch (a, b) {
    case (.null, .null): return true
    case (.bool(let x), .bool(let y)): return x == y
    case (.number(let x), .number(let y)): return x == y
    case (.string(let x), .string(let y)): return x.unicodeScalars.elementsEqual(y.unicodeScalars)
    case (.array(let x), .array(let y)):
        guard x.count == y.count else { return false }
        for i in 0..<x.count { if !deepEqual(x[i], y[i]) { return false } }
        return true
    case (.object(let x), .object(let y)):
        guard x.count == y.count else { return false }
        for (k, v) in x { guard let w = y[k], deepEqual(v, w) else { return false } }
        return true
    default: return false
    }
}

func matchesType(_ v: JSONValue, _ t: String) -> Bool {
    switch t {
    case "null": if case .null = v { return true }
    case "boolean": if case .bool = v { return true }
    case "number": if case .number = v { return true }
    case "integer": if case .number(let n) = v { return n.truncatingRemainder(dividingBy: 1) == 0 }
    case "string": if case .string = v { return true }
    case "array": if case .array = v { return true }
    case "object": if case .object = v { return true }
    default: break
    }
    return false
}

func escapeToken(_ token: String) -> String {
    var r = ""
    for ch in token {
        if ch == "~" { r += "~0" }
        else if ch == "/" { r += "~1" }
        else { r.append(ch) }
    }
    return r
}

func unescapeToken(_ token: String) -> String {
    var r = ""
    var i = token.startIndex
    while i < token.endIndex {
        if token[i] == "~" {
            let next = token.index(after: i)
            if next < token.endIndex {
                if token[next] == "0" { r.append("~"); i = token.index(after: next); continue }
                else if token[next] == "1" { r.append("/"); i = token.index(after: next); continue }
            }
        }
        r.append(token[i])
        i = token.index(after: i)
    }
    return r
}

func resolveRef(_ ref: String, root: JSONValue) -> JSONValue? {
    guard ref.hasPrefix("#") else { return nil }
    let path = String(ref.dropFirst())
    if path.isEmpty { return root }
    guard path.hasPrefix("/") else { return nil }
    let pathStr = String(path.dropFirst())
    if pathStr.isEmpty { return root }
    let parts = pathStr.split(separator: "/", omittingEmptySubsequences: false).map { String($0) }
    var cur = root
    for part in parts {
        let key = unescapeToken(part)
        if case .object(let obj) = cur, let next = obj[key] { cur = next }
        else { return nil }
    }
    return cur
}

func hasDuplicates(_ arr: [JSONValue]) -> Bool {
    for i in 0..<arr.count {
        for j in (i+1)..<arr.count {
            if deepEqual(arr[i], arr[j]) { return true }
        }
    }
    return false
}

// MARK: - Validation

struct ValidationError: Hashable {
    let inst: String
    let sch: String
}

func validate(instance: JSONValue, schema: JSONValue, iPath: String, sPath: String, root: JSONValue) -> Set<ValidationError> {
    var errors = Set<ValidationError>()

    if case .bool(let b) = schema {
        if !b { errors.insert(ValidationError(inst: iPath, sch: sPath)) }
        return errors
    }

    guard case .object(let obj) = schema else { return errors }

    // type
    if let tv = obj["type"] {
        var names: [String]? = nil
        if case .string(let s) = tv { names = [s] }
        else if case .array(let arr) = tv {
            names = []
            for item in arr { if case .string(let s) = item { names!.append(s) } }
        }
        if let ns = names, !ns.contains(where: { matchesType(instance, $0) }) {
            errors.insert(ValidationError(inst: iPath, sch: sPath + "/type"))
        }
    }

    // enum
    if let ev = obj["enum"], case .array(let arr) = ev {
        if !arr.contains(where: { deepEqual(instance, $0) }) {
            errors.insert(ValidationError(inst: iPath, sch: sPath + "/enum"))
        }
    }

    // const
    if let cv = obj["const"] {
        if !deepEqual(instance, cv) {
            errors.insert(ValidationError(inst: iPath, sch: sPath + "/const"))
        }
    }

    // Number keywords
    if case .number(let n) = instance {
        if let v = obj["minimum"], case .number(let m) = v {
            if n < m { errors.insert(ValidationError(inst: iPath, sch: sPath + "/minimum")) }
        }
        if let v = obj["maximum"], case .number(let m) = v {
            if n > m { errors.insert(ValidationError(inst: iPath, sch: sPath + "/maximum")) }
        }
        if let v = obj["exclusiveMinimum"], case .number(let m) = v {
            if n <= m { errors.insert(ValidationError(inst: iPath, sch: sPath + "/exclusiveMinimum")) }
        }
        if let v = obj["exclusiveMaximum"], case .number(let m) = v {
            if n >= m { errors.insert(ValidationError(inst: iPath, sch: sPath + "/exclusiveMaximum")) }
        }
    }

    // String keywords
    if case .string(let s) = instance {
        let len = Double(s.unicodeScalars.count)
        if let v = obj["minLength"], case .number(let m) = v {
            if len < m { errors.insert(ValidationError(inst: iPath, sch: sPath + "/minLength")) }
        }
        if let v = obj["maxLength"], case .number(let m) = v {
            if len > m { errors.insert(ValidationError(inst: iPath, sch: sPath + "/maxLength")) }
        }
    }

    // Array keywords
    if case .array(let arr) = instance {
        if let v = obj["minItems"], case .number(let m) = v {
            if Double(arr.count) < m { errors.insert(ValidationError(inst: iPath, sch: sPath + "/minItems")) }
        }
        if let v = obj["maxItems"], case .number(let m) = v {
            if Double(arr.count) > m { errors.insert(ValidationError(inst: iPath, sch: sPath + "/maxItems")) }
        }
        if case .bool(true)? = obj["uniqueItems"] {
            if hasDuplicates(arr) { errors.insert(ValidationError(inst: iPath, sch: sPath + "/uniqueItems")) }
        }

        var prefixLen = 0
        var hasPrefix = false
        if let pv = obj["prefixItems"], case .array(let schemas) = pv {
            hasPrefix = true
            prefixLen = schemas.count
            for i in 0..<min(arr.count, schemas.count) {
                errors.formUnion(validate(instance: arr[i], schema: schemas[i],
                    iPath: iPath + "/" + String(i), sPath: sPath + "/prefixItems/" + String(i), root: root))
            }
        }
        if let isch = obj["items"] {
            let start = hasPrefix ? prefixLen : 0
            for i in start..<arr.count {
                errors.formUnion(validate(instance: arr[i], schema: isch,
                    iPath: iPath + "/" + String(i), sPath: sPath + "/items", root: root))
            }
        }
    }

    // Object keywords
    if case .object(let instObj) = instance {
        var propNames: Set<String> = []
        if let pv = obj["properties"], case .object(let props) = pv {
            propNames = Set(props.keys)
            for (name, psch) in props {
                if let mv = instObj[name] {
                    errors.formUnion(validate(instance: mv, schema: psch,
                        iPath: iPath + "/" + escapeToken(name), sPath: sPath + "/properties/" + escapeToken(name), root: root))
                }
            }
        }

        if let rv = obj["required"], case .array(let rarr) = rv {
            for (j, rv2) in rarr.enumerated() {
                if case .string(let name) = rv2 {
                    if instObj[name] == nil {
                        errors.insert(ValidationError(inst: iPath, sch: sPath + "/required/" + String(j)))
                    }
                }
            }
        }

        if let ap = obj["additionalProperties"] {
            for (name, mv) in instObj {
                if !propNames.contains(name) {
                    errors.formUnion(validate(instance: mv, schema: ap,
                        iPath: iPath + "/" + escapeToken(name), sPath: sPath + "/additionalProperties", root: root))
                }
            }
        }

        if let v = obj["minProperties"], case .number(let m) = v {
            if Double(instObj.count) < m { errors.insert(ValidationError(inst: iPath, sch: sPath + "/minProperties")) }
        }
        if let v = obj["maxProperties"], case .number(let m) = v {
            if Double(instObj.count) > m { errors.insert(ValidationError(inst: iPath, sch: sPath + "/maxProperties")) }
        }
    }

    // allOf
    if let av = obj["allOf"], case .array(let schemas) = av {
        for (i, sub) in schemas.enumerated() {
            errors.formUnion(validate(instance: instance, schema: sub,
                iPath: iPath, sPath: sPath + "/allOf/" + String(i), root: root))
        }
    }

    // anyOf
    if let av = obj["anyOf"], case .array(let schemas) = av {
        let ok = schemas.contains { sub in
            validate(instance: instance, schema: sub, iPath: iPath, sPath: "", root: root).isEmpty
        }
        if !ok { errors.insert(ValidationError(inst: iPath, sch: sPath + "/anyOf")) }
    }

    // oneOf
    if let ov = obj["oneOf"], case .array(let schemas) = ov {
        var cnt = 0
        for sub in schemas {
            if validate(instance: instance, schema: sub, iPath: iPath, sPath: "", root: root).isEmpty {
                cnt += 1
                if cnt > 1 { break }
            }
        }
        if cnt != 1 { errors.insert(ValidationError(inst: iPath, sch: sPath + "/oneOf")) }
    }

    // not
    if let ns = obj["not"] {
        if validate(instance: instance, schema: ns, iPath: iPath, sPath: "", root: root).isEmpty {
            errors.insert(ValidationError(inst: iPath, sch: sPath + "/not"))
        }
    }

    // if/then/else
    if let isch = obj["if"] {
        let ifErrs = validate(instance: instance, schema: isch, iPath: iPath, sPath: "", root: root)
        if ifErrs.isEmpty {
            if let ts = obj["then"] {
                errors.formUnion(validate(instance: instance, schema: ts, iPath: iPath, sPath: sPath + "/then", root: root))
            }
        } else {
            if let es = obj["else"] {
                errors.formUnion(validate(instance: instance, schema: es, iPath: iPath, sPath: sPath + "/else", root: root))
            }
        }
    }

    // $ref
    if let rv = obj["$ref"], case .string(let ref) = rv {
        if let resolved = resolveRef(ref, root: root) {
            errors.formUnion(validate(instance: instance, schema: resolved, iPath: iPath, sPath: ref, root: root))
        }
    }

    return errors
}

