#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <CommonCrypto/CommonHMAC.h>

/* ============ JSON Parser ============ */

typedef enum { JSON_NULL, JSON_BOOL, JSON_NUMBER, JSON_STRING, JSON_ARRAY, JSON_OBJECT } json_type;

typedef struct json_value {
    json_type type;
    int boolean;
    double number;
    char *string;
    struct json_value **items;
    int count;
    char **keys;
} json_value;

static json_value *json_new(json_type t) {
    json_value *v = (json_value*)calloc(1, sizeof(json_value));
    v->type = t;
    return v;
}

static void skip_ws(const char **p) {
    while (**p == ' ' || **p == '\t' || **p == '\n' || **p == '\r') (*p)++;
}

static json_value *parse_value(const char **p);

static unsigned int hex_val(char c) {
    if (c >= '0' && c <= '9') return c - '0';
    if (c >= 'a' && c <= 'f') return c - 'a' + 10;
    if (c >= 'A' && c <= 'F') return c - 'A' + 10;
    return 0;
}

static char *parse_string_raw(const char **p) {
    (*p)++; /* skip opening " */
    const char *start = *p;
    const char *q = start;
    while (*q != '"') {
        if (*q == '\\') q++;
        q++;
    }
    int raw_len = (int)(q - start);
    *p = q + 1; /* skip closing " */

    int has_escape = 0;
    for (int i = 0; i < raw_len; i++) {
        if (start[i] == '\\') { has_escape = 1; break; }
    }

    if (!has_escape) {
        char *s = (char*)malloc(raw_len + 1);
        memcpy(s, start, raw_len);
        s[raw_len] = '\0';
        return s;
    }

    char *s = (char*)malloc(raw_len * 3 + 1);
    int si = 0;
    q = start;
    while (q < start + raw_len) {
        if (*q == '\\') {
            q++;
            switch (*q) {
                case '"': s[si++] = '"'; q++; break;
                case '\\': s[si++] = '\\'; q++; break;
                case '/': s[si++] = '/'; q++; break;
                case 'b': s[si++] = '\b'; q++; break;
                case 'f': s[si++] = '\f'; q++; break;
                case 'n': s[si++] = '\n'; q++; break;
                case 'r': s[si++] = '\r'; q++; break;
                case 't': s[si++] = '\t'; q++; break;
                case 'u': {
                    q++;
                    unsigned int cp = 0;
                    for (int i = 0; i < 4; i++) cp = (cp << 4) | hex_val(*q++);
                    if (cp >= 0xD800 && cp <= 0xDBFF && q[0] == '\\' && q[1] == 'u') {
                        q += 2;
                        unsigned int lo = 0;
                        for (int i = 0; i < 4; i++) lo = (lo << 4) | hex_val(*q++);
                        cp = 0x10000 + ((cp - 0xD800) << 10) + (lo - 0xDC00);
                    }
                    if (cp < 0x80) {
                        s[si++] = (char)cp;
                    } else if (cp < 0x800) {
                        s[si++] = (char)(0xC0 | (cp >> 6));
                        s[si++] = (char)(0x80 | (cp & 0x3F));
                    } else if (cp < 0x10000) {
                        s[si++] = (char)(0xE0 | (cp >> 12));
                        s[si++] = (char)(0x80 | ((cp >> 6) & 0x3F));
                        s[si++] = (char)(0x80 | (cp & 0x3F));
                    } else {
                        s[si++] = (char)(0xF0 | (cp >> 18));
                        s[si++] = (char)(0x80 | ((cp >> 12) & 0x3F));
                        s[si++] = (char)(0x80 | ((cp >> 6) & 0x3F));
                        s[si++] = (char)(0x80 | (cp & 0x3F));
                    }
                    break;
                }
                default: s[si++] = *q; q++; break;
            }
        } else {
            s[si++] = *q++;
        }
    }
    s[si] = '\0';
    return s;
}

static json_value *parse_value(const char **p) {
    skip_ws(p);
    if (**p == '"') {
        json_value *v = json_new(JSON_STRING);
        v->string = parse_string_raw(p);
        return v;
    } else if (**p == '{') {
        json_value *v = json_new(JSON_OBJECT);
        (*p)++;
        skip_ws(p);
        if (**p == '}') { (*p)++; return v; }
        int cap = 8;
        v->keys = (char**)malloc(cap * sizeof(char*));
        v->items = (json_value**)malloc(cap * sizeof(json_value*));
        while (1) {
            skip_ws(p);
            char *key = parse_string_raw(p);
            skip_ws(p);
            (*p)++; /* skip : */
            json_value *val = parse_value(p);
            if (v->count >= cap) {
                cap *= 2;
                v->keys = (char**)realloc(v->keys, cap * sizeof(char*));
                v->items = (json_value**)realloc(v->items, cap * sizeof(json_value*));
            }
            v->keys[v->count] = key;
            v->items[v->count] = val;
            v->count++;
            skip_ws(p);
            if (**p == ',') { (*p)++; continue; }
            if (**p == '}') { (*p)++; break; }
            break;
        }
        return v;
    } else if (**p == '[') {
        json_value *v = json_new(JSON_ARRAY);
        (*p)++;
        skip_ws(p);
        if (**p == ']') { (*p)++; return v; }
        int cap = 8;
        v->items = (json_value**)malloc(cap * sizeof(json_value*));
        while (1) {
            json_value *val = parse_value(p);
            if (v->count >= cap) {
                cap *= 2;
                v->items = (json_value**)realloc(v->items, cap * sizeof(json_value*));
            }
            v->items[v->count++] = val;
            skip_ws(p);
            if (**p == ',') { (*p)++; continue; }
            if (**p == ']') { (*p)++; break; }
            break;
        }
        return v;
    } else if (**p == 't') {
        *p += 4;
        json_value *v = json_new(JSON_BOOL);
        v->boolean = 1;
        return v;
    } else if (**p == 'f') {
        *p += 5;
        json_value *v = json_new(JSON_BOOL);
        v->boolean = 0;
        return v;
    } else if (**p == 'n') {
        *p += 4;
        return json_new(JSON_NULL);
    } else {
        json_value *v = json_new(JSON_NUMBER);
        char *end;
        v->number = strtod(*p, &end);
        *p = end;
        return v;
    }
}

static json_value *json_get(json_value *obj, const char *key) {
    if (!obj || obj->type != JSON_OBJECT) return NULL;
    for (int i = 0; i < obj->count; i++) {
        if (strcmp(obj->keys[i], key) == 0) return obj->items[i];
    }
    return NULL;
}

/* ============ Base64url ============ */

static int b64_val(char c) {
    if (c >= 'A' && c <= 'Z') return c - 'A';
    if (c >= 'a' && c <= 'z') return c - 'a' + 26;
    if (c >= '0' && c <= '9') return c - '0' + 52;
    if (c == '-') return 62;
    if (c == '_') return 63;
    return -1;
}

static int is_valid_b64url(const char *s, int len) {
    if (len == 0) return 0;
    if (len % 4 == 1) return 0;
    for (int i = 0; i < len; i++) {
        if (b64_val(s[i]) < 0) return 0;
    }
    return 1;
}

static unsigned char *b64url_decode(const char *s, int len, int *out_len) {
    int full = len / 4;
    int rem = len % 4;
    int dlen = full * 3 + (rem == 2 ? 1 : rem == 3 ? 2 : 0);
    unsigned char *out = (unsigned char*)malloc(dlen > 0 ? dlen : 1);
    int oi = 0, i = 0;
    for (; i + 3 < len; i += 4) {
        int a = b64_val(s[i]), b = b64_val(s[i+1]), c = b64_val(s[i+2]), d = b64_val(s[i+3]);
        out[oi++] = (a << 2) | (b >> 4);
        out[oi++] = ((b & 0xF) << 4) | (c >> 2);
        out[oi++] = ((c & 0x3) << 6) | d;
    }
    if (rem == 2) {
        int a = b64_val(s[i]), b = b64_val(s[i+1]);
        out[oi++] = (a << 2) | (b >> 4);
    } else if (rem == 3) {
        int a = b64_val(s[i]), b = b64_val(s[i+1]), c = b64_val(s[i+2]);
        out[oi++] = (a << 2) | (b >> 4);
        out[oi++] = ((b & 0xF) << 4) | (c >> 2);
    }
    *out_len = oi;
    return out;
}

/* ============ File reading ============ */

static char *read_file(const char *path, int *out_len) {
    FILE *f = fopen(path, "rb");
    if (!f) { fprintf(stderr, "Cannot open %s\n", path); exit(1); }
    fseek(f, 0, SEEK_END);
    long sz = ftell(f);
    fseek(f, 0, SEEK_SET);
    char *buf = (char*)malloc(sz + 1);
    fread(buf, 1, sz, f);
    buf[sz] = '\0';
    fclose(f);
    if (out_len) *out_len = (int)sz;
    return buf;
}

/* ============ Main ============ */

typedef struct {
    char *kid;
    char *alg;
    unsigned char *key;
    int key_len;
} key_entry;

int main(int argc, char *argv[]) {
    if (argc < 2) { fprintf(stderr, "Usage: %s <dir>\n", argv[0]); return 1; }

    char path[4096];
    snprintf(path, sizeof(path), "%s/config.json", argv[1]);
    char *cfg_data = read_file(path, NULL);

    snprintf(path, sizeof(path), "%s/tokens.txt", argv[1]);
    char *tok_data = read_file(path, NULL);

    /* Parse config */
    const char *cp = cfg_data;
    json_value *cfg = parse_value(&cp);

    double now = 0, leeway = 0;
    char *issuer = NULL, *audience = NULL;
    key_entry keys[256];
    int num_keys = 0;

    json_value *jv;
    jv = json_get(cfg, "now");
    if (jv && jv->type == JSON_NUMBER) now = jv->number;
    jv = json_get(cfg, "leeway");
    if (jv && jv->type == JSON_NUMBER) leeway = jv->number;
    jv = json_get(cfg, "issuer");
    if (jv && jv->type == JSON_STRING) issuer = jv->string;
    jv = json_get(cfg, "audience");
    if (jv && jv->type == JSON_STRING) audience = jv->string;

    jv = json_get(cfg, "keys");
    if (jv && jv->type == JSON_ARRAY) {
        for (int i = 0; i < jv->count && num_keys < 256; i++) {
            json_value *ko = jv->items[i];
            if (ko->type != JSON_OBJECT) continue;
            json_value *jkid = json_get(ko, "kid");
            json_value *jalg = json_get(ko, "alg");
            json_value *jk = json_get(ko, "k");
            if (!jkid || jkid->type != JSON_STRING) continue;
            if (!jalg || jalg->type != JSON_STRING) continue;
            if (!jk || jk->type != JSON_STRING) continue;
            keys[num_keys].kid = jkid->string;
            keys[num_keys].alg = jalg->string;
            keys[num_keys].key = b64url_decode(jk->string, (int)strlen(jk->string), &keys[num_keys].key_len);
            num_keys++;
        }
    }

    /* Process tokens */
    int valid_count = 0, invalid_count = 0;
    int token_num = 0;

    /* Split tokens.txt into lines */
    char *tok_lines[10000];
    int num_tok_lines = 0;
    {
        char *p = tok_data;
        while (*p) {
            char *nl = strchr(p, '\n');
            if (nl) {
                *nl = '\0';
                tok_lines[num_tok_lines++] = p;
                p = nl + 1;
            } else {
                tok_lines[num_tok_lines++] = p;
                break;
            }
        }
    }

    for (int li = 0; li < num_tok_lines; li++) {
        char *line = tok_lines[li];
        /* Strip trailing \r */
        int llen = (int)strlen(line);
        while (llen > 0 && (line[llen-1] == '\r' || line[llen-1] == '\n')) line[--llen] = '\0';
        /* Trim leading spaces/tabs */
        while (*line == ' ' || *line == '\t') line++;
        /* Trim trailing spaces/tabs */
        llen = (int)strlen(line);
        while (llen > 0 && (line[llen-1] == ' ' || line[llen-1] == '\t')) line[--llen] = '\0';
        /* Skip empty */
        if (llen == 0) continue;

        token_num++;
        const char *result = NULL;
        json_value *header = NULL, *payload = NULL;

        /* Rule 1: MALFORMED */
        /* Check exactly 3 dot-separated segments */
        int dot_count = 0;
        for (int i = 0; line[i]; i++) if (line[i] == '.') dot_count++;
        if (dot_count != 2) { result = "MALFORMED"; goto report; }

        char *dot1 = strchr(line, '.');
        char *dot2 = strchr(dot1 + 1, '.');
        int seg1_len = (int)(dot1 - line);
        int seg2_len = (int)(dot2 - dot1 - 1);
        int seg3_len = (int)strlen(dot2 + 1);
        char *seg1 = line, *seg2 = dot1 + 1, *seg3 = dot2 + 1;

        if (seg1_len == 0 || seg2_len == 0 || seg3_len == 0) { result = "MALFORMED"; goto report; }
        if (!is_valid_b64url(seg1, seg1_len) || !is_valid_b64url(seg2, seg2_len) || !is_valid_b64url(seg3, seg3_len)) {
            result = "MALFORMED"; goto report;
        }

        {
            int hlen, plen;
            unsigned char *hdr_bytes = b64url_decode(seg1, seg1_len, &hlen);
            unsigned char *pld_bytes = b64url_decode(seg2, seg2_len, &plen);
            hdr_bytes[hlen] = '\0';
            pld_bytes[plen] = '\0';

            const char *hp = (char*)hdr_bytes;
            header = parse_value(&hp);
            if (!header || header->type != JSON_OBJECT) { result = "MALFORMED"; goto report; }

            const char *pp = (char*)pld_bytes;
            payload = parse_value(&pp);
            if (!payload || payload->type != JSON_OBJECT) { result = "MALFORMED"; goto report; }
        }

        /* Rule 2: UNSUPPORTED_ALG */
        {
            json_value *jalg = json_get(header, "alg");
            if (!jalg || jalg->type != JSON_STRING) { result = "UNSUPPORTED_ALG"; goto report; }
            if (strcmp(jalg->string, "HS256") != 0 && strcmp(jalg->string, "HS384") != 0 && strcmp(jalg->string, "HS512") != 0) {
                result = "UNSUPPORTED_ALG"; goto report;
            }
        }

        /* Rule 3: UNKNOWN_KEY */
        key_entry *matched_key = NULL;
        {
            json_value *jkid = json_get(header, "kid");
            if (!jkid || jkid->type != JSON_STRING) { result = "UNKNOWN_KEY"; goto report; }
            for (int i = 0; i < num_keys; i++) {
                if (strcmp(keys[i].kid, jkid->string) == 0) { matched_key = &keys[i]; break; }
            }
            if (!matched_key) { result = "UNKNOWN_KEY"; goto report; }
        }

        /* Rule 4: ALG_MISMATCH */
        {
            json_value *jalg = json_get(header, "alg");
            if (strcmp(matched_key->alg, jalg->string) != 0) { result = "ALG_MISMATCH"; goto report; }
        }

        /* Rule 5: BAD_SIGNATURE */
        {
            json_value *jalg = json_get(header, "alg");
            /* signing input = seg1.seg2 */
            int si_len = seg1_len + 1 + seg2_len;
            unsigned char *si = (unsigned char*)malloc(si_len);
            memcpy(si, seg1, seg1_len);
            si[seg1_len] = '.';
            memcpy(si + seg1_len + 1, seg2, seg2_len);

            unsigned char expected[64];
            int expected_len;
            CCHmacAlgorithm alg_id;
            if (strcmp(jalg->string, "HS256") == 0) { alg_id = kCCHmacAlgSHA256; expected_len = 32; }
            else if (strcmp(jalg->string, "HS384") == 0) { alg_id = kCCHmacAlgSHA384; expected_len = 48; }
            else { alg_id = kCCHmacAlgSHA512; expected_len = 64; }
            CCHmac(alg_id, matched_key->key, matched_key->key_len, si, si_len, expected);
            free(si);

            int sig_len;
            unsigned char *sig = b64url_decode(seg3, seg3_len, &sig_len);
            if (sig_len != expected_len || memcmp(sig, expected, expected_len) != 0) {
                result = "BAD_SIGNATURE"; goto report;
            }
        }

        /* Rule 6: EXPIRED */
        {
            json_value *jexp = json_get(payload, "exp");
            if (jexp && jexp->type == JSON_NUMBER) {
                if (now >= jexp->number + leeway) { result = "EXPIRED"; goto report; }
            }
        }

        /* Rule 7: NOT_YET_VALID */
        {
            json_value *jnbf = json_get(payload, "nbf");
            if (jnbf && jnbf->type == JSON_NUMBER) {
                if (now + leeway < jnbf->number) { result = "NOT_YET_VALID"; goto report; }
            }
        }

        /* Rule 8: BAD_ISSUER */
        {
            json_value *jiss = json_get(payload, "iss");
            if (!jiss || jiss->type != JSON_STRING || strcmp(jiss->string, issuer) != 0) {
                result = "BAD_ISSUER"; goto report;
            }
        }

        /* Rule 9: BAD_AUDIENCE */
        {
            json_value *jaud = json_get(payload, "aud");
            if (!jaud) { result = "BAD_AUDIENCE"; goto report; }
            if (jaud->type == JSON_STRING) {
                if (strcmp(jaud->string, audience) != 0) { result = "BAD_AUDIENCE"; goto report; }
            } else if (jaud->type == JSON_ARRAY) {
                int found = 0;
                for (int i = 0; i < jaud->count; i++) {
                    if (jand->items[i]->type == JSON_STRING && strcmp(jaud->items[i]->string, audience) == 0) {
                        found = 1; break;
                    }
                }
                if (!found) { result = "BAD_AUDIENCE"; goto report; }
            } else {
                result = "BAD_AUDIENCE"; goto report;
            }
        }

        /* VALID */
        {
            valid_count++;
            json_value *jsub = json_get(payload, "sub");
            const char *sub = (jsub && jsub->type == JSON_STRING) ? jsub->string : "";

            /* Process scope */
            json_value *jscope = json_get(payload, "scope");
            char *scope_str = (jscope && jscope->type == JSON_STRING) ? jscope->string : "";

            /* Split on spaces, filter empty */
            char *scopes[1024];
            int nscopes = 0;
            {
                char *tmp = strdup(scope_str);
                char *sp = tmp;
                while (*sp) {
                    while (*sp == ' ') sp++;
                    if (!*sp) break;
                    char *start = sp;
                    while (*sp && *sp != ' ') sp++;
                    int slen = (int)(sp - start);
                    char *piece = (char*)malloc(slen + 1);
                    memcpy(piece, start, slen);
                    piece[slen] = '\0';
                    scopes[nscopes++] = piece;
                }
                free(tmp);
            }

            /* Sort by code point (strcmp works for UTF-8) */
            for (int i = 0; i < nscopes - 1; i++) {
                for (int j = i + 1; j < nscopes; j++) {
                    if (strcmp(scopes[i], scopes[j]) > 0) {
                        char *t = scopes[i]; scopes[i] = scopes[j]; scopes[j] = t;
                    }
                }
            }

            /* Deduplicate */
            int uniq = 0;
            for (int i = 0; i < nscopes; i++) {
                if (uniq == 0 || strcmp(scopes[uniq-1], scopes[i]) != 0) {
                    scopes[uniq++] = scopes[i];
                }
            }

            /* Build output */
            printf("%d: VALID sub=%s scope=", token_num, sub);
            for (int i = 0; i < uniq; i++) {
                if (i > 0) printf(",");
                printf("%s", scopes[i]);
            }
            printf("\n");
            continue;
        }

    report:
        invalid_count++;
        printf("%d: %s\n", token_num, result);
    }

    printf("\nvalid=%d invalid=%d\n", valid_count, invalid_count);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <CommonCrypto/CommonHMAC.h>

/* ============ JSON Parser ============ */

typedef enum { JSON_NULL, JSON_BOOL, JSON_NUMBER, JSON_STRING, JSON_ARRAY, JSON_OBJECT } json_type;

typedef struct json_value {
    json_type type;
    int boolean;
    double number;
    char *string;
    struct json_value **items;
    int count;
    char **keys;
} json_value;

static json_value *json_new(json_type t) {
    json_value *v = (json_value*)calloc(1, sizeof(json_value));
    v->type = t;
    return v;
}

static void skip_ws(const char **p) {
    while (**p == ' ' || **p == '\t' || **p == '\n' || **p == '\r') (*p)++;
}

static json_value *parse_value(const char **p);

static unsigned int hex_val(char c) {
    if (c >= '0' && c <= '9') return c - '0';
    if (c >= 'a' && c <= 'f') return c - 'a' + 10;
    if (c >= 'A' && c <= 'F') return c - 'A' + 10;
    return 0;
}

static char *parse_string_raw(const char **p) {
    (*p)++; /* skip opening " */
    const char *start = *p;
    const char *q = start;
    while (*q != '"') {
        if (*q == '\\') q++;
        q++;
    }
    int raw_len = (int)(q - start);
    *p = q + 1; /* skip closing " */

    int has_escape = 0;
    for (int i = 0; i < raw_len; i++) {
        if (start[i] == '\\') { has_escape = 1; break; }
    }

    if (!has_escape) {
        char *s = (char*)malloc(raw_len + 1);
        memcpy(s, start, raw_len);
        s[raw_len] = '\0';
        return s;
    }

    char *s = (char*)malloc(raw_len * 3 + 1);
    int si = 0;
    q = start;
    while (q < start + raw_len) {
        if (*q == '\\') {
            q++;
            switch (*q) {
                case '"': s[si++] = '"'; q++; break;
                case '\\': s[si++] = '\\'; q++; break;
                case '/': s[si++] = '/'; q++; break;
                case 'b': s[si++] = '\b'; q++; break;
                case 'f': s[si++] = '\f'; q++; break;
                case 'n': s[si++] = '\n'; q++; break;
                case 'r': s[si++] = '\r'; q++; break;
                case 't': s[si++] = '\t'; q++; break;
                case 'u': {
                    q++;
                    unsigned int cp = 0;
                    for (int i = 0; i < 4; i++) cp = (cp << 4) | hex_val(*q++);
                    if (cp >= 0xD800 && cp <= 0xDBFF && q[0] == '\\' && q[1] == 'u') {
                        q += 2;
                        unsigned int lo = 0;
                        for (int i = 0; i < 4; i++) lo = (lo << 4) | hex_val(*q++);
                        cp = 0x10000 + ((cp - 0xD800) << 10) + (lo - 0xDC00);
                    }
                    if (cp < 0x80) {
                        s[si++] = (char)cp;
                    } else if (cp < 0x800) {
                        s[si++] = (char)(0xC0 | (cp >> 6));
                        s[si++] = (char)(0x80 | (cp & 0x3F));
                    } else if (cp < 0x10000) {
                        s[si++] = (char)(0xE0 | (cp >> 12));
                        s[si++] = (char)(0x80 | ((cp >> 6) & 0x3F));
                        s[si++] = (char)(0x80 | (cp & 0x3F));
                    } else {
                        s[si++] = (char)(0xF0 | (cp >> 18));
                        s[si++] = (char)(0x80 | ((cp >> 12) & 0x3F));
                        s[si++] = (char)(0x80 | ((cp >> 6) & 0x3F));
                        s[si++] = (char)(0x80 | (cp & 0x3F));
                    }
                    break;
                }
                default: s[si++] = *q; q++; break;
            }
        } else {
            s[si++] = *q++;
        }
    }
    s[si] = '\0';
    return s;
}

static json_value *parse_value(const char **p) {
    skip_ws(p);
    if (**p == '"') {
        json_value *v = json_new(JSON_STRING);
        v->string = parse_string_raw(p);
        return v;
    } else if (**p == '{') {
        json_value *v = json_new(JSON_OBJECT);
        (*p)++;
        skip_ws(p);
        if (**p == '}') { (*p)++; return v; }
        int cap = 8;
        v->keys = (char**)malloc(cap * sizeof(char*));
        v->items = (json_value**)malloc(cap * sizeof(json_value*));
        while (1) {
            skip_ws(p);
            char *key = parse_string_raw(p);
            skip_ws(p);
            (*p)++; /* skip : */
            json_value *val = parse_value(p);
            if (v->count >= cap) {
                cap *= 2;
                v->keys = (char**)realloc(v->keys, cap * sizeof(char*));
                v->items = (json_value**)realloc(v->items, cap * sizeof(json_value*));
            }
            v->keys[v->count] = key;
            v->items[v->count] = val;
            v->count++;
            skip_ws(p);
            if (**p == ',') { (*p)++; continue; }
            if (**p == '}') { (*p)++; break; }
            break;
        }
        return v;
    } else if (**p == '[') {
        json_value *v = json_new(JSON_ARRAY);
        (*p)++;
        skip_ws(p);
        if (**p == ']') { (*p)++; return v; }
        int cap = 8;
        v->items = (json_value**)malloc(cap * sizeof(json_value*));
        while (1) {
            json_value *val = parse_value(p);
            if (v->count >= cap) {
                cap *= 2;
                v->items = (json_value**)realloc(v->items, cap * sizeof(json_value*));
            }
            v->items[v->count++] = val;
            skip_ws(p);
            if (**p == ',') { (*p)++; continue; }
            if (**p == ']') { (*p)++; break; }
            break;
        }
        return v;
    } else if (**p == 't') {
        *p += 4;
        json_value *v = json_new(JSON_BOOL);
        v->boolean = 1;
        return v;
    } else if (**p == 'f') {
        *p += 5;
        json_value *v = json_new(JSON_BOOL);
        v->boolean = 0;
        return v;
    } else if (**p == 'n') {
        *p += 4;
        return json_new(JSON_NULL);
    } else {
        json_value *v = json_new(JSON_NUMBER);
        char *end;
        v->number = strtod(*p, &end);
        *p = end;
        return v;
    }
}

static json_value *json_get(json_value *obj, const char *key) {
    if (!obj || obj->type != JSON_OBJECT) return NULL;
    for (int i = 0; i < obj->count; i++) {
        if (strcmp(obj->keys[i], key) == 0) return obj->items[i];
    }
    return NULL;
}

/* ============ Base64url ============ */

static int b64_val(char c) {
    if (c >= 'A' && c <= 'Z') return c - 'A';
    if (c >= 'a' && c <= 'z') return c - 'a' + 26;
    if (c >= '0' && c <= '9') return c - '0' + 52;
    if (c == '-') return 62;
    if (c == '_') return 63;
    return -1;
}

static int is_valid_b64url(const char *s, int len) {
    if (len == 0) return 0;
    if (len % 4 == 1) return 0;
    for (int i = 0; i < len; i++) {
        if (b64_val(s[i]) < 0) return 0;
    }
    return 1;
}

static unsigned char *b64url_decode(const char *s, int len, int *out_len) {
    int full = len / 4;
    int rem = len % 4;
    int dlen = full * 3 + (rem == 2 ? 1 : rem == 3 ? 2 : 0);
    unsigned char *out = (unsigned char*)malloc(dlen > 0 ? dlen : 1);
    int oi = 0, i = 0;
    for (; i + 3 < len; i += 4) {
        int a = b64_val(s[i]), b = b64_val(s[i+1]), c = b64_val(s[i+2]), d = b64_val(s[i+3]);
        out[oi++] = (a << 2) | (b >> 4);
        out[oi++] = ((b & 0xF) << 4) | (c >> 2);
        out[oi++] = ((c & 0x3) << 6) | d;
    }
    if (rem == 2) {
        int a = b64_val(s[i]), b = b64_val(s[i+1]);
        out[oi++] = (a << 2) | (b >> 4);
    } else if (rem == 3) {
        int a = b64_val(s[i]), b = b64_val(s[i+1]), c = b64_val(s[i+2]);
        out[oi++] = (a << 2) | (b >> 4);
        out[oi++] = ((b & 0xF) << 4) | (c >> 2);
    }
    *out_len = oi;
    return out;
}

/* ============ File reading ============ */

static char *read_file(const char *path, int *out_len) {
    FILE *f = fopen(path, "rb");
    if (!f) { fprintf(stderr, "Cannot open %s\n", path); exit(1); }
    fseek(f, 0, SEEK_END);
    long sz = ftell(f);
    fseek(f, 0, SEEK_SET);
    char *buf = (char*)malloc(sz + 1);
    fread(buf, 1, sz, f);
    buf[sz] = '\0';
    fclose(f);
    if (out_len) *out_len = (int)sz;
    return buf;
}

/* ============ Main ============ */

typedef struct {
    char *kid;
    char *alg;
    unsigned char *key;
    int key_len;
} key_entry;

int main(int argc, char *argv[]) {
    if (argc < 2) { fprintf(stderr, "Usage: %s <dir>\n", argv[0]); return 1; }

    char path[4096];
    snprintf(path, sizeof(path), "%s/config.json", argv[1]);
    char *cfg_data = read_file(path, NULL);

    snprintf(path, sizeof(path), "%s/tokens.txt", argv[1]);
    char *tok_data = read_file(path, NULL);

    /* Parse config */
    const char *cp = cfg_data;
    json_value *cfg = parse_value(&cp);

    double now = 0, leeway = 0;
    char *issuer = NULL, *audience = NULL;
    key_entry keys[256];
    int num_keys = 0;

    json_value *jv;
    jv = json_get(cfg, "now");
    if (jv && jv->type == JSON_NUMBER) now = jv->number;
    jv = json_get(cfg, "leeway");
    if (jv && jv->type == JSON_NUMBER) leeway = jv->number;
    jv = json_get(cfg, "issuer");
    if (jv && jv->type == JSON_STRING) issuer = jv->string;
    jv = json_get(cfg, "audience");
    if (jv && jv->type == JSON_STRING) audience = jv->string;

    jv = json_get(cfg, "keys");
    if (jv && jv->type == JSON_ARRAY) {
        for (int i = 0; i < jv->count && num_keys < 256; i++) {
            json_value *ko = jv->items[i];
            if (ko->type != JSON_OBJECT) continue;
            json_value *jkid = json_get(ko, "kid");
            json_value *jalg = json_get(ko, "alg");
            json_value *jk = json_get(ko, "k");
            if (!jkid || jkid->type != JSON_STRING) continue;
            if (!jalg || jalg->type != JSON_STRING) continue;
            if (!jk || jk->type != JSON_STRING) continue;
            keys[num_keys].kid = jkid->string;
            keys[num_keys].alg = jalg->string;
            keys[num_keys].key = b64url_decode(jk->string, (int)strlen(jk->string), &keys[num_keys].key_len);
            num_keys++;
        }
    }

    /* Process tokens */
    int valid_count = 0, invalid_count = 0;
    int token_num = 0;

    /* Split tokens.txt into lines */
    char *tok_lines[10000];
    int num_tok_lines = 0;
    {
        char *p = tok_data;
        while (*p) {
            char *nl = strchr(p, '\n');
            if (nl) {
                *nl = '\0';
                tok_lines[num_tok_lines++] = p;
                p = nl + 1;
            } else {
                tok_lines[num_tok_lines++] = p;
                break;
            }
        }
    }

    for (int li = 0; li < num_tok_lines; li++) {
        char *line = tok_lines[li];
        /* Strip trailing \r */
        int llen = (int)strlen(line);
        while (llen > 0 && (line[llen-1] == '\r' || line[llen-1] == '\n')) line[--llen] = '\0';
        /* Trim leading spaces/tabs */
        while (*line == ' ' || *line == '\t') line++;
        /* Trim trailing spaces/tabs */
        llen = (int)strlen(line);
        while (llen > 0 && (line[llen-1] == ' ' || line[llen-1] == '\t')) line[--llen] = '\0';
        /* Skip empty */
        if (llen == 0) continue;

        token_num++;
        const char *result = NULL;
        json_value *header = NULL, *payload = NULL;

        /* Rule 1: MALFORMED */
        /* Check exactly 3 dot-separated segments */
        int dot_count = 0;
        for (int i = 0; line[i]; i++) if (line[i] == '.') dot_count++;
        if (dot_count != 2) { result = "MALFORMED"; goto report; }

        char *dot1 = strchr(line, '.');
        char *dot2 = strchr(dot1 + 1, '.');
        int seg1_len = (int)(dot1 - line);
        int seg2_len = (int)(dot2 - dot1 - 1);
        int seg3_len = (int)strlen(dot2 + 1);
        char *seg1 = line, *seg2 = dot1 + 1, *seg3 = dot2 + 1;

        if (seg1_len == 0 || seg2_len == 0 || seg3_len == 0) { result = "MALFORMED"; goto report; }
        if (!is_valid_b64url(seg1, seg1_len) || !is_valid_b64url(seg2, seg2_len) || !is_valid_b64url(seg3, seg3_len)) {
            result = "MALFORMED"; goto report;
        }

        {
            int hlen, plen;
            unsigned char *hdr_bytes = b64url_decode(seg1, seg1_len, &hlen);
            unsigned char *pld_bytes = b64url_decode(seg2, seg2_len, &plen);
            hdr_bytes = (unsigned char*)realloc(hdr_bytes, hlen + 1);
            pld_bytes = (unsigned char*)realloc(pld_bytes, plen + 1);
            hdr_bytes[hlen] = '\0';
            pld_bytes[plen] = '\0';

            const char *hp = (char*)hdr_bytes;
            header = parse_value(&hp);
            if (!header || header->type != JSON_OBJECT) { result = "MALFORMED"; goto report; }

            const char *pp = (char*)pld_bytes;
            payload = parse_value(&pp);
            if (!payload || payload->type != JSON_OBJECT) { result = "MALFORMED"; goto report; }
        }

        /* Rule 2: UNSUPPORTED_ALG */
        {
            json_value *jalg = json_get(header, "alg");
            if (!jalg || jalg->type != JSON_STRING) { result = "UNSUPPORTED_ALG"; goto report; }
            if (strcmp(jalg->string, "HS256") != 0 && strcmp(jalg->string, "HS384") != 0 && strcmp(jalg->string, "HS512") != 0) {
                result = "UNSUPPORTED_ALG"; goto report;
            }
        }

        /* Rule 3: UNKNOWN_KEY */
        key_entry *matched_key = NULL;
        {
            json_value *jkid = json_get(header, "kid");
            if (!jkid || jkid->type != JSON_STRING) { result = "UNKNOWN_KEY"; goto report; }
            for (int i = 0; i < num_keys; i++) {
                if (strcmp(keys[i].kid, jkid->string) == 0) { matched_key = &keys[i]; break; }
            }
            if (!matched_key) { result = "UNKNOWN_KEY"; goto report; }
        }

        /* Rule 4: ALG_MISMATCH */
        {
            json_value *jalg = json_get(header, "alg");
            if (strcmp(matched_key->alg, jalg->string) != 0) { result = "ALG_MISMATCH"; goto report; }
        }

        /* Rule 5: BAD_SIGNATURE */
        {
            json_value *jalg = json_get(header, "alg");
            /* signing input = seg1.seg2 */
            int si_len = seg1_len + 1 + seg2_len;
            unsigned char *si = (unsigned char*)malloc(si_len);
            memcpy(si, seg1, seg1_len);
            si[seg1_len] = '.';
            memcpy(si + seg1_len + 1, seg2, seg2_len);

            unsigned char expected[64];
            int expected_len;
            CCHmacAlgorithm alg_id;
            if (strcmp(jalg->string, "HS256") == 0) { alg_id = kCCHmacAlgSHA256; expected_len = 32; }
            else if (strcmp(jalg->string, "HS384") == 0) { alg_id = kCCHmacAlgSHA384; expected_len = 48; }
            else { alg_id = kCCHmacAlgSHA512; expected_len = 64; }
            CCHmac(alg_id, matched_key->key, matched_key->key_len, si, si_len, expected);
            free(si);

            int sig_len;
            unsigned char *sig = b64url_decode(seg3, seg3_len, &sig_len);
            if (sig_len != expected_len || memcmp(sig, expected, expected_len) != 0) {
                result = "BAD_SIGNATURE"; goto report;
            }
        }

        /* Rule 6: EXPIRED */
        {
            json_value *jexp = json_get(payload, "exp");
            if (jexp && jexp->type == JSON_NUMBER) {
                if (now >= jexp->number + leeway) { result = "EXPIRED"; goto report; }
            }
        }

        /* Rule 7: NOT_YET_VALID */
        {
            json_value *jnbf = json_get(payload, "nbf");
            if (jnbf && jnbf->type == JSON_NUMBER) {
                if (now + leeway < jnbf->number) { result = "NOT_YET_VALID"; goto report; }
            }
        }

        /* Rule 8: BAD_ISSUER */
        {
            json_value *jiss = json_get(payload, "iss");
            if (!jiss || jiss->type != JSON_STRING || strcmp(jiss->string, issuer) != 0) {
                result = "BAD_ISSUER"; goto report;
            }
        }

        /* Rule 9: BAD_AUDIENCE */
        {
            json_value *jaud = json_get(payload, "aud");
            if (!jaud) { result = "BAD_AUDIENCE"; goto report; }
            if (jaud->type == JSON_STRING) {
                if (strcmp(jaud->string, audience) != 0) { result = "BAD_AUDIENCE"; goto report; }
            } else if (jaud->type == JSON_ARRAY) {
                int found = 0;
                for (int i = 0; i < jaud->count; i++) {
                    if (jaud->items[i]->type == JSON_STRING && strcmp(jaud->items[i]->string, audience) == 0) {
                        found = 1; break;
                    }
                }
                if (!found) { result = "BAD_AUDIENCE"; goto report; }
            } else {
                result = "BAD_AUDIENCE"; goto report;
            }
        }

        /* VALID */
        {
            valid_count++;
            json_value *jsub = json_get(payload, "sub");
            const char *sub = (jsub && jsub->type == JSON_STRING) ? jsub->string : "";

            /* Process scope */
            json_value *jscope = json_get(payload, "scope");
            char *scope_str = (jscope && jscope->type == JSON_STRING) ? jscope->string : "";

            /* Split on spaces, filter empty */
            char *scopes[1024];
            int nscopes = 0;
            {
                char *tmp = strdup(scope_str);
                char *sp = tmp;
                while (*sp) {
                    while (*sp == ' ') sp++;
                    if (!*sp) break;
                    char *start = sp;
                    while (*sp && *sp != ' ') sp++;
                    int slen = (int)(sp - start);
                    char *piece = (char*)malloc(slen + 1);
                    memcpy(piece, start, slen);
                    piece[slen] = '\0';
                    scopes[nscopes++] = piece;
                }
                free(tmp);
            }

            /* Sort by code point (strcmp works for UTF-8) */
            for (int i = 0; i < nscopes - 1; i++) {
                for (int j = i + 1; j < nscopes; j++) {
                    if (strcmp(scopes[i], scopes[j]) > 0) {
                        char *t = scopes[i]; scopes[i] = scopes[j]; scopes[j] = t;
                    }
                }
            }

            /* Deduplicate */
            int uniq = 0;
            for (int i = 0; i < nscopes; i++) {
                if (uniq == 0 || strcmp(scopes[uniq-1], scopes[i]) != 0) {
                    scopes[uniq++] = scopes[i];
                }
            }

            /* Build output */
            printf("%d: VALID sub=%s scope=", token_num, sub);
            for (int i = 0; i < uniq; i++) {
                if (i > 0) printf(",");
                printf("%s", scopes[i]);
            }
            printf("\n");
            continue;
        }

    report:
        invalid_count++;
        printf("%d: %s\n", token_num, result);
    }

    printf("\nvalid=%d invalid=%d\n", valid_count, invalid_count);
    return 0;
}

import java.io.*;
import java.nio.charset.StandardCharsets;
import java.util.*;

public class Main {

    static class JsonNum {
        String raw;
        double value;
        boolean isInteger;
        JsonNum(String raw, double value, boolean isInteger) {
            this.raw = raw;
            this.value = value;
            this.isInteger = isInteger;
        }
    }

    // --- JSON Parser ---
    static class JsonParser {
        String input;
        int pos;
        JsonParser(String input) { this.input = input; this.pos = 0; }

        Object parse() {
            skipWs();
            Object r = parseValue();
            skipWs();
            if (pos < input.length()) throw new RuntimeException("trailing");
            return r;
        }

        void skipWs() {
            while (pos < input.length()) {
                char c = input.charAt(pos);
                if (c == ' ' || c == '\t' || c == '\n' || c == '\r') pos++;
                else break;
            }
        }

        Object parseValue() {
            if (pos >= input.length()) throw new RuntimeException("eof");
            char c = input.charAt(pos);
            if (c == '{') return parseObject();
            if (c == '[') return parseArray();
            if (c == '"') return parseString();
            if (c == 't') { expect("true"); return Boolean.TRUE; }
            if (c == 'f') { expect("false"); return Boolean.FALSE; }
            if (c == 'n') { expect("null"); return null; }
            if (c == '-' || (c >= '0' && c <= '9')) return parseNumber();
            throw new RuntimeException("unexpected char");
        }

        void expect(String s) {
            if (!input.startsWith(s, pos)) throw new RuntimeException("expected " + s);
            pos += s.length();
        }

        Map<String, Object> parseObject() {
            Map<String, Object> map = new LinkedHashMap<>();
            pos++;
            skipWs();
            if (pos < input.length() && input.charAt(pos) == '}') { pos++; return map; }
            while (true) {
                skipWs();
                if (pos >= input.length() || input.charAt(pos) != '"') throw new RuntimeException("expected key");
                String key = parseString();
                skipWs();
                if (pos >= input.length() || input.charAt(pos) != ':') throw new RuntimeException("expected :");
                pos++;
                skipWs();
                Object val = parseValue();
                map.put(key, val);
                skipWs();
                if (pos >= input.length()) throw new RuntimeException("expected , or }");
                if (input.charAt(pos) == '}') { pos++; return map; }
                if (input.charAt(pos) == ',') { pos++; }
                else throw new RuntimeException("expected , or }");
            }
        }

        List<Object> parseArray() {
            List<Object> list = new ArrayList<>();
            pos++;
            skipWs();
            if (pos < input.length() && input.charAt(pos) == ']') { pos++; return list; }
            while (true) {
                skipWs();
                list.add(parseValue());
                skipWs();
                if (pos >= input.length()) throw new RuntimeException("expected , or ]");
                if (input.charAt(pos) == ']') { pos++; return list; }
                if (input.charAt(pos) == ',') { pos++; }
                else throw new RuntimeException("expected , or ]");
            }
        }

        String parseString() {
            pos++;
            StringBuilder sb = new StringBuilder();
            while (pos < input.length()) {
                char c = input.charAt(pos);
                if (c == '"') { pos++; return sb.toString(); }
                if (c == '\\') {
                    pos++;
                    if (pos >= input.length()) throw new RuntimeException("eof in string");
                    char e = input.charAt(pos);
                    switch (e) {
                        case '"': sb.append('"'); break;
                        case '\\': sb.append('\\'); break;
                        case '/': sb.append('/'); break;
                        case 'b': sb.append('\b'); break;
                        case 'f': sb.append('\f'); break;
                        case 'n': sb.append('\n'); break;
                        case 'r': sb.append('\r'); break;
                        case 't': sb.append('\t'); break;
                        case 'u':
                            if (pos + 4 >= input.length()) throw new RuntimeException("bad unicode");
                            String hex = input.substring(pos + 1, pos + 5);
                            int cp;
                            try { cp = Integer.parseInt(hex, 16); } catch (Exception ex) { throw new RuntimeException("bad unicode"); }
                            sb.append((char) cp);
                            pos += 4;
                            break;
                        default: throw new RuntimeException("bad escape");
                    }
                    pos++;
                } else {
                    sb.append(c);
                    pos++;
                }
            }
            throw new RuntimeException("unterminated string");
        }

        JsonNum parseNumber() {
            int start = pos;
            boolean isInt = true;
            if (pos < input.length() && input.charAt(pos) == '-') pos++;
            if (pos < input.length() && input.charAt(pos) == '0') {
                pos++;
            } else if (pos < input.length() && input.charAt(pos) >= '1' && input.charAt(pos) <= '9') {
                while (pos < input.length() && input.charAt(pos) >= '0' && input.charAt(pos) <= '9') pos++;
            } else {
                throw new RuntimeException("bad number");
            }
            if (pos < input.length() && input.charAt(pos) == '.') {
                isInt = false;
                pos++;
                if (pos >= input.length() || input.charAt(pos) < '0' || input.charAt(pos) > '9') throw new RuntimeException("bad number");
                while (pos < input.length() && input.charAt(pos) >= '0' && input.charAt(pos) <= '9') pos++;
            }
            if (pos < input.length() && (input.charAt(pos) == 'e' || input.charAt(pos) == 'E')) {
                isInt = false;
                pos++;
                if (pos < input.length() && (input.charAt(pos) == '+' || input.charAt(pos) == '-')) pos++;
                if (pos >= input.length() || input.charAt(pos) < '0' || input.charAt(pos) > '9') throw new RuntimeException("bad number");
                while (pos < input.length() && input.charAt(pos) >= '0' && input.charAt(pos) <= '9') pos++;
            }
            String raw = input.substring(start, pos);
            return new JsonNum(raw, Double.parseDouble(raw), isInt);
        }
    }

    // --- JSON Serializer ---
    static String ser(Object obj) {
        if (obj == null) return "null";
        if (obj instanceof Boolean) return obj.toString();
        if (obj instanceof JsonNum) {
            JsonNum n = (JsonNum) obj;
            if (n.isInteger) return String.valueOf((long) n.value);
            return n.raw;
        }
        if (obj instanceof String) return escStr((String) obj);
        if (obj instanceof Map) {
            @SuppressWarnings("unchecked")
            Map<String, Object> m = (Map<String, Object>) obj;
            StringBuilder sb = new StringBuilder("{");
            boolean first = true;
            for (Map.Entry<String, Object> e : m.entrySet()) {
                if (!first) sb.append(',');
                sb.append(escStr(e.getKey()));
                sb.append(':');
                sb.append(ser(e.getValue()));
                first = false;
            }
            sb.append('}');
            return sb.toString();
        }
        if (obj instanceof List) {
            @SuppressWarnings("unchecked")
            List<Object> l = (List<Object>) obj;
            StringBuilder sb = new StringBuilder("[");
            for (int i = 0; i < l.size(); i++) {
                if (i > 0) sb.append(',');
                sb.append(ser(l.get(i)));
            }
            sb.append(']');
            return sb.toString();
        }
        return obj.toString();
    }

    static String escStr(String s) {
        StringBuilder sb = new StringBuilder("\"");
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            switch (c) {
                case '"': sb.append("\\\""); break;
                case '\\': sb.append("\\\\"); break;
                case '\b': sb.append("\\b"); break;
                case '\f': sb.append("\\f"); break;
                case '\n': sb.append("\\n"); break;
                case '\r': sb.append("\\r"); break;
                case '\t': sb.append("\\t"); break;
                default:
                    if (c < 0x20) sb.append(String.format("\\u%04x", (int) c));
                    else sb.append(c);
            }
        }
        sb.append('"');
        return sb.toString();
    }

    // --- Helpers ---
    static Map<String, Object> obj(Object... kv) {
        Map<String, Object> m = new LinkedHashMap<>();
        for (int i = 0; i < kv.length; i += 2) m.put((String) kv[i], kv[i + 1]);
        return m;
    }

    static List<Object> arr(Object... items) { return new ArrayList<>(Arrays.asList(items)); }
    static JsonNum intNum(long v) { return new JsonNum(String.valueOf(v), (double) v, true); }

    static boolean isValidId(Object id) {
        if (id instanceof String) return true;
        if (id instanceof JsonNum) return ((JsonNum) id).isInteger;
        return false;
    }

    // --- Server State ---
    static boolean initialized = false;
    static Map<String, String> kvStore = new LinkedHashMap<>();

    public static void main(String[] args) throws Exception {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in, StandardCharsets.UTF_8));
        PrintWriter writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out, StandardCharsets.UTF_8)));
        String line;
        while ((line = reader.readLine()) != null) {
            if (line.trim().isEmpty()) continue;
            String resp = processLine(line);
            if (resp != null) writer.println(resp);
        }
        writer.flush();
        System.exit(0);
    }

    @SuppressWarnings("unchecked")
    static String processLine(String line) {
        Object parsed;
        try {
            parsed = new JsonParser(line).parse();
        } catch (Exception e) {
            return ser(obj("jsonrpc", "2.0", "id", null, "error", obj("code", intNum(-32700), "message", "Parse error")));
        }

        if (!(parsed instanceof Map)) {
            return ser(obj("jsonrpc", "2.0", "id", null, "error", obj("code", intNum(-32600), "message", "Invalid Request")));
        }

        Map<String, Object> msg = (Map<String, Object>) parsed;

        // Rule 3: response from client
        if (!msg.containsKey("method") && (msg.containsKey("result") || msg.containsKey("error"))) {
            return null;
        }

        // Rule 4: invalid request
        boolean jsonrpcOk = msg.containsKey("jsonrpc") && "2.0".equals(msg.get("jsonrpc"));
        boolean methodOk = msg.containsKey("method") && msg.get("method") instanceof String;
        boolean idOk = true;
        if (msg.containsKey("id")) {
            idOk = isValidId(msg.get("id"));
        }
        if (!jsonrpcOk || !methodOk || !idOk) {
            Object id = null;
            if (msg.containsKey("id") && isValidId(msg.get("id"))) id = msg.get("id");
            return ser(obj("jsonrpc", "2.0", "id", id, "error", obj("code", intNum(-32600), "message", "Invalid Request")));
        }

        // Rule 5: notification
        if (!msg.containsKey("id")) return null;

        // Rule 6: request
        Object id = msg.get("id");
        String method = (String) msg.get("method");

        // 6a
        if (!method.equals("initialize") && !method.equals("ping") && !method.equals("tools/list") && !method.equals("tools/call")) {
            return ser(obj("jsonrpc", "2.0", "id", id, "error", obj("code", intNum(-32601), "message", "Method not found")));
        }

        // 6b
        if (msg.containsKey("params") && !(msg.get("params") instanceof Map)) {
            return ser(obj("jsonrpc", "2.0", "id", id, "error", obj("code", intNum(-32602), "message", "Invalid params")));
        }
        Map<String, Object> params = (Map<String, Object>) msg.get("params");

        // 6c
        if (!initialized && !method.equals("initialize") && !method.equals("ping")) {
            return ser(obj("jsonrpc", "2.0", "id", id, "error", obj("code", intNum(-32002), "message", "Server not initialized")));
        }

        // 6d
        switch (method) {
            case "initialize": return handleInit(id, params);
            case "ping": return ser(obj("jsonrpc", "2.0", "id", id, "result", obj()));
            case "tools/list": return handleToolsList(id);
            case "tools/call": return handleToolsCall(id, params);
        }
        return null;
    }

    static String handleInit(Object id, Map<String, Object> params) {
        if (initialized) {
            return ser(obj("jsonrpc", "2.0", "id", id, "error", obj("code", intNum(-32600), "message", "Already initialized")));
        }
        if (params == null || !params.containsKey("protocolVersion") || !(params.get("protocolVersion") instanceof String)) {
            return ser(obj("jsonrpc", "2.0", "id", id, "error", obj("code", intNum(-32602), "message", "Invalid params")));
        }
        String cv = (String) params.get("protocolVersion");
        String ver;
        if (cv.equals("2025-06-18") || cv.equals("2025-03-26") || cv.equals("2024-11-05")) ver = cv;
        else ver = "2025-06-18";
        initialized = true;
        Map<String, Object> result = obj(
            "protocolVersion", ver,
            "capabilities", obj("tools", obj("listChanged", false)),
            "serverInfo", obj("name", "cb2-kv", "title", "CB2 key-value server", "version", "1.4.2")
        );
        return ser(obj("jsonrpc", "2.0", "id", id, "result", result));
    }

    static String handleToolsList(Object id) {
        List<Object> tools = new ArrayList<>();
        tools.add(obj("name", "kv_set", "title", "Set a value",
            "description", "Store a string value under a key, replacing any previous value.",
            "inputSchema", obj("type", "object",
                "properties", obj("key", obj("type", "string", "minLength", intNum(1)), "value", obj("type", "string")),
                "required", arr("key", "value"), "additionalProperties", false)));
        tools.add(obj("name", "kv_get", "title", "Get a value",
            "description", "Return the value stored under a key.",
            "inputSchema", obj("type", "object",
                "properties", obj("key", obj("type", "string", "minLength", intNum(1))),
                "required", arr("key"), "additionalProperties", false)));
        tools.add(obj("name", "kv_list", "title", "List keys",
            "description", "List the stored keys that start with a prefix, sorted by Unicode code point.",
            "inputSchema", obj("type", "object",
                "properties", obj("prefix", obj("type", "string")),
                "additionalProperties", false),
            "outputSchema", obj("type", "object",
                "properties", obj("keys", obj("type", "array", "items", obj("type", "string")), "count", obj("type", "integer")),
                "required", arr("keys", "count"))));
        tools.add(obj("name", "sum", "title", "Sum integers",
            "description", "Add up a non-empty list of integers.",
            "inputSchema", obj("type", "object",
                "properties", obj("numbers", obj("type", "array", "items", obj("type", "integer"), "minItems", intNum(1))),
                "required", arr("numbers"), "additionalProperties", false),
            "outputSchema", obj("type", "object",
                "properties", obj("sum", obj("type", "integer"), "count", obj("type", "integer")),
                "required", arr("sum", "count")),
            "annotations", obj("readOnlyHint", true, "idempotentHint", true)));
        tools.add(obj("name", "text_stats", "title", "Text statistics",
            "description", "Count the words, Unicode code points and UTF-8 bytes of a text.",
            "inputSchema", obj("type", "object",
                "properties", obj("text", obj("type", "string")),
                "required", arr("text"), "additionalProperties", false),
            "outputSchema", obj("type", "object",
                "properties", obj("words", obj("type", "integer"), "codepoints", obj("type", "integer"), "utf8_bytes", obj("type", "integer")),
                "required", arr("words", "codepoints", "utf8_bytes")),
            "annotations", obj("readOnlyHint", true)));
        return ser(obj("jsonrpc", "2.0", "id", id, "result", obj("tools", tools)));
    }

    @SuppressWarnings("unchecked")
    static String handleToolsCall(Object id, Map<String, Object> params) {
        if (params == null || !params.containsKey("name") || !(params.get("name") instanceof String)) {
            return ser(obj("jsonrpc", "2.0", "id", id, "error", obj("code", intNum(-32602), "message", "Invalid params")));
        }
        String name = (String) params.get("name");
        if (!name.equals("kv_set") && !name.equals("kv_get") && !name.equals("kv_list") && !name.equals("sum") && !name.equals("text_stats")) {
            return ser(obj("jsonrpc", "2.0", "id", id, "error", obj("code", intNum(-32602), "message", "Unknown tool: " + name)));
        }

        Map<String, Object> args;
        if (!params.containsKey("arguments")) {
            args = new LinkedHashMap<>();
        } else {
            Object ao = params.get("arguments");
            if (ao instanceof Map) {
                args = (Map<String, Object>) ao;
            } else {
                return toolFail(id, "arguments must be an object");
            }
        }

        List<String> propNames = getPropNames(name);
        List<String> required = getRequired(name);

        // Check unknown arguments
        String smallestUnknown = null;
        for (String k : args.keySet()) {
            if (!propNames.contains(k)) {
                if (smallestUnknown == null || cmpCp(k, smallestUnknown) < 0) smallestUnknown = k;
            }
        }
        if (smallestUnknown != null) return toolFail(id, "unknown argument: " + smallestUnknown);

        // Check each property in schema order
        for (String pn : propNames) {
            if (!args.containsKey(pn)) {
                if (required.contains(pn)) return toolFail(id, "missing required argument: " + pn);
                continue;
            }
            Object val = args.get(pn);
            String type = getPropType(name, pn);
            if ("string".equals(type)) {
                if (!(val instanceof String)) return toolFail(id, "argument " + pn + " must be a string");
                int ml = getMinLength(name, pn);
                if (ml > 0 && ((String) val).length() < ml) return toolFail(id, "argument " + pn + " must not be empty");
            } else if ("array".equals(type)) {
                if (!(val instanceof List)) return toolFail(id, "argument " + pn + " must be an array of integers");
                List<Object> list = (List<Object>) val;
                for (Object elem : list) {
                    if (!(elem instanceof JsonNum) || !((JsonNum) elem).isInteger)
                        return toolFail(id, "argument " + pn + " must be an array of integers");
                }
                int mi = getMinItems(name, pn);
                if (mi > 0 && list.size() < mi) return toolFail(id, "argument " + pn + " must not be empty");
            }
        }

        switch (name) {
            case "kv_set": {
                String key = (String) args.get("key");
                String value = (String) args.get("value");
                boolean existed = kvStore.containsKey(key);
                kvStore.put(key, value);
                return toolOk(id, existed ? "updated " + key : "created " + key);
            }
            case "kv_get": {
                String key = (String) args.get("key");
                if (!kvStore.containsKey(key)) return toolFail(id, "key not found: " + key);
                return toolOk(id, kvStore.get(key));
            }
            case "kv_list": {
                String prefix = args.containsKey("prefix") ? (String) args.get("prefix") : "";
                List<String> keys = new ArrayList<>();
                for (String k : kvStore.keySet()) {
                    if (k.startsWith(prefix)) keys.add(k);
                }
                keys.sort(Main::cmpCp);
                Map<String, Object> sc = obj("keys", new ArrayList<Object>(keys), "count", intNum(keys.size()));
                return toolOkStructured(id, sc);
            }
            case "sum": {
                List<Object> nums = (List<Object>) args.get("numbers");
                long sum = 0;
                for (Object n : nums) sum += (long) ((JsonNum) n).value;
                Map<String, Object> sc = obj("sum", intNum(sum), "count", intNum(nums.size()));
                return toolOkStructured(id, sc);
            }
            case "text_stats": {
                String text = (String) args.get("text");
                int words = 0;
                boolean inWord = false;
                for (int i = 0; i < text.length(); ) {
                    int cp = text.codePointAt(i);
                    if (cp == 0x20 || cp == 0x09 || cp == 0x0A || cp == 0x0D) {
                        inWord = false;
                    } else {
                        if (!inWord) { words++; inWord = true; }
                    }
                    i += Character.charCount(cp);
                }
                int cps = text.codePointCount(0, text.length());
                int bytes = text.getBytes(StandardCharsets.UTF_8).length;
                Map<String, Object> sc = obj("words", intNum(words), "codepoints", intNum(cps), "utf8_bytes", intNum(bytes));
                return toolOkStructured(id, sc);
            }
        }
        return null;
    }

    static int cmpCp(String a, String b) {
        int len = Math.min(a.length(), b.length());
        int i = 0;
        while (i < len) {
            int ca = a.codePointAt(i);
            int cb = b.codePointAt(i);
            if (ca != cb) return Integer.compare(ca, cb);
            i += Character.charCount(ca);
        }
        return Integer.compare(a.length(), b.length());
    }

    static List<String> getPropNames(String tool) {
        switch (tool) {
            case "kv_set": return Arrays.asList("key", "value");
            case "kv_get": return Arrays.asList("key");
            case "kv_list": return Arrays.asList("prefix");
            case "sum": return Arrays.asList("numbers");
            case "text_stats": return Arrays.asList("text");
        }
        return Collections.emptyList();
    }

    static List<String> getRequired(String tool) {
        switch (tool) {
            case "kv_set": return Arrays.asList("key", "value");
            case "kv_get": return Arrays.asList("key");
            case "kv_list": return Collections.emptyList();
            case "sum": return Arrays.asList("numbers");
            case "text_stats": return Arrays.asList("text");
        }
        return Collections.emptyList();
    }

    static String getPropType(String tool, String prop) {
        switch (tool) {
            case "kv_set":
                if (prop.equals("key") || prop.equals("value")) return "string";
                break;
            case "kv_get":
                if (prop.equals("key")) return "string";
                break;
            case "kv_list":
                if (prop.equals("prefix")) return "string";
                break;
            case "sum":
                if (prop.equals("numbers")) return "array";
                break;
            case "text_stats":
                if (prop.equals("text")) return "string";
                break;
        }
        return null;
    }

    static int getMinLength(String tool, String prop) {
        if ((tool.equals("kv_set") || tool.equals("kv_get")) && prop.equals("key")) return 1;
        return 0;
    }

    static int getMinItems(String tool, String prop) {
        if (tool.equals("sum") && prop.equals("numbers")) return 1;
        return 0;
    }

    static String toolFail(Object id, String msg) {
        return ser(obj("jsonrpc", "2.0", "id", id, "result",
            obj("content", arr(obj("type", "text", "text", msg)), "isError", true)));
    }

    static String toolOk(Object id, String text) {
        return ser(obj("jsonrpc", "2.0", "id", id, "result",
            obj("content", arr(obj("type", "text", "text", text)), "isError", false)));
    }

    static String toolOkStructured(Object id, Map<String, Object> structured) {
        String text = ser(structured);
        return ser(obj("jsonrpc", "2.0", "id", id, "result",
            obj("content", arr(obj("type", "text", "text", text)), "structuredContent", structured, "isError", false)));
    }
}

use std::collections::HashSet;
use std::env;
use std::fs;

#[derive(Debug, Clone)]
enum Value {
    Null,
    Bool(bool),
    Num(f64),
    Str(String),
    Arr(Vec<Value>),
    Obj(Vec<(String, Value)>),
}

struct Parser {
    input: Vec<char>,
    pos: usize,
}

impl Parser {
    fn new(s: &str) -> Self {
        Parser { input: s.chars().collect(), pos: 0 }
    }

    fn parse_value(&mut self) -> Value {
        self.skip_ws();
        match self.input[self.pos] {
            'n' => { self.expect("null"); Value::Null }
            't' => { self.expect("true"); Value::Bool(true) }
            'f' => { self.expect("false"); Value::Bool(false) }
            '"' => Value::Str(self.parse_string()),
            '[' => self.parse_array(),
            '{' => self.parse_object(),
            _ => self.parse_number(),
        }
    }

    fn skip_ws(&mut self) {
        while self.pos < self.input.len() {
            let c = self.input[self.pos];
            if c == ' ' || c == '\t' || c == '\n' || c == '\r' {
                self.pos += 1;
            } else {
                break;
            }
        }
    }

    fn expect(&mut self, s: &str) {
        for c in s.chars() {
            assert_eq!(self.input[self.pos], c);
            self.pos += 1;
        }
    }

    fn parse_string(&mut self) -> String {
        assert_eq!(self.input[self.pos], '"');
        self.pos += 1;
        let mut result = String::new();
        loop {
            let c = self.input[self.pos];
            self.pos += 1;
            if c == '"' { break; }
            if c == '\\' {
                let e = self.input[self.pos];
                self.pos += 1;
                match e {
                    '"' => result.push('"'),
                    '\\' => result.push('\\'),
                    '/' => result.push('/'),
                    'b' => result.push('\u{0008}'),
                    'f' => result.push('\u{000C}'),
                    'n' => result.push('\n'),
                    'r' => result.push('\r'),
                    't' => result.push('\t'),
                    'u' => {
                        let cp = self.parse_hex4();
                        if cp >= 0xD800 && cp <= 0xDBFF {
                            assert_eq!(self.input[self.pos], '\\');
                            self.pos += 1;
                            assert_eq!(self.input[self.pos], 'u');
                            self.pos += 1;
                            let lo = self.parse_hex4();
                            let code = 0x10000 + ((cp - 0xD800) << 10) + (lo - 0xDC00);
                            result.push(char::from_u32(code).unwrap());
                        } else {
                            result.push(char::from_u32(cp).unwrap());
                        }
                    }
                    _ => unreachable!(),
                }
            } else {
                result.push(c);
            }
        }
        result
    }

    fn parse_hex4(&mut self) -> u32 {
        let mut val = 0u32;
        for _ in 0..4 {
            let c = self.input[self.pos];
            self.pos += 1;
            let d = match c {
                '0'..='9' => (c as u32) - ('0' as u32),
                'a'..='f' => 10 + (c as u32) - ('a' as u32),
                'A'..='F' => 10 + (c as u32) - ('A' as u32),
                _ => unreachable!(),
            };
            val = val * 16 + d;
        }
        val
    }

    fn parse_number(&mut self) -> Value {
        let start = self.pos;
        if self.input[self.pos] == '-' { self.pos += 1; }
        while self.pos < self.input.len() && self.input[self.pos].is_ascii_digit() { self.pos += 1; }
        if self.pos < self.input.len() && self.input[self.pos] == '.' {
            self.pos += 1;
            while self.pos < self.input.len() && self.input[self.pos].is_ascii_digit() { self.pos += 1; }
        }
        if self.pos < self.input.len() && (self.input[self.pos] == 'e' || self.input[self.pos] == 'E') {
            self.pos += 1;
            if self.pos < self.input.len() && (self.input[self.pos] == '+' || self.input[self.pos] == '-') { self.pos += 1; }
            while self.pos < self.input.len() && self.input[self.pos].is_ascii_digit() { self.pos += 1; }
        }
        let s: String = self.input[start..self.pos].iter().collect();
        Value::Num(s.parse::<f64>().unwrap())
    }

    fn parse_array(&mut self) -> Value {
        assert_eq!(self.input[self.pos], '[');
        self.pos += 1;
        let mut arr = Vec::new();
        self.skip_ws();
        if self.pos < self.input.len() && self.input[self.pos] == ']' {
            self.pos += 1;
            return Value::Arr(arr);
        }
        loop {
            arr.push(self.parse_value());
            self.skip_ws();
            if self.input[self.pos] == ',' { self.pos += 1; continue; }
            if self.input[self.pos] == ']' { self.pos += 1; break; }
            unreachable!();
        }
        Value::Arr(arr)
    }

    fn parse_object(&mut self) -> Value {
        assert_eq!(self.input[self.pos], '{');
        self.pos += 1;
        let mut obj = Vec::new();
        self.skip_ws();
        if self.pos < self.input.len() && self.input[self.pos] == '}' {
            self.pos += 1;
            return Value::Obj(obj);
        }
        loop {
            self.skip_ws();
            let key = self.parse_string();
            self.skip_ws();
            assert_eq!(self.input[self.pos], ':');
            self.pos += 1;
            let val = self.parse_value();
            obj.push((key, val));
            self.skip_ws();
            if self.input[self.pos] == ',' { self.pos += 1; continue; }
            if self.input[self.pos] == '}' { self.pos += 1; break; }
            unreachable!();
        }
        Value::Obj(obj)
    }
}

fn deep_eq(a: &Value, b: &Value) -> bool {
    match (a, b) {
        (Value::Null, Value::Null) => true,
        (Value::Bool(a), Value::Bool(b)) => a == b,
        (Value::Num(a), Value::Num(b)) => a == b,
        (Value::Str(a), Value::Str(b)) => a == b,
        (Value::Arr(a), Value::Arr(b)) => {
            a.len() == b.len() && a.iter().zip(b.iter()).all(|(x, y)| deep_eq(x, y))
        }
        (Value::Obj(a), Value::Obj(b)) => {
            if a.len() != b.len() { return false; }
            for (k, va) in a {
                match b.iter().find(|(kb, _)| kb == k) {
                    Some((_, vb)) => if !deep_eq(va, vb) { return false; },
                    None => return false,
                }
            }
            true
        }
        _ => false,
    }
}

fn encode_token(s: &str) -> String {
    s.replace('~', "~0").replace('/', "~1")
}

fn decode_token(s: &str) -> String {
    s.replace("~1", "/").replace("~0", "~")
}

fn resolve_ref<'a>(ref_str: &str, root: &'a Value) -> (&'a Value, String) {
    assert!(ref_str.starts_with('#'));
    let pointer = &ref_str[1..];
    if pointer.is_empty() {
        return (root, "#".to_string());
    }
    let mut current = root;
    let mut loc = String::from("#");
    for token in pointer[1..].split('/') {
        let key = decode_token(token);
        loc.push('/');
        loc.push_str(token);
        match current {
            Value::Obj(obj) => {
                current = &obj.iter().find(|(k, _)| *k == key).unwrap().1;
            }
            _ => panic!("cannot navigate into non-object via $ref"),
        }
    }
    (current, loc)
}

fn type_matches(instance: &Value, type_name: &str) -> bool {
    match (instance, type_name) {
        (Value::Null, "null") => true,
        (Value::Bool(_), "boolean") => true,
        (Value::Num(_), "number") => true,
        (Value::Num(n), "integer") => n.fract() == 0.0,
        (Value::Str(_), "string") => true,
        (Value::Arr(_), "array") => true,
        (Value::Obj(_), "object") => true,
        _ => false,
    }
}

fn check_unique(arr: &[Value]) -> bool {
    for i in 0..arr.len() {
        for j in i + 1..arr.len() {
            if deep_eq(&arr[i], &arr[j]) {
                return false;
            }
        }
    }
    true
}

fn validate(
    instance: &Value,
    schema: &Value,
    inst_loc: &str,
    schema_loc: &str,
    root: &Value,
    errors: &mut HashSet<(String, String)>,
) {
    match schema {
        Value::Bool(true) => return,
        Value::Bool(false) => {
            errors.insert((inst_loc.to_string(), schema_loc.to_string()));
            return;
        }
        Value::Obj(obj) => {
            let get = |key: &str| -> Option<&Value> {
                obj.iter().find(|(k, _)| k == key).map(|(_, v)| v)
            };

            // type
            if let Some(type_val) = get("type") {
                let type_names: Vec<&str> = match type_val {
                    Value::Str(s) => vec![s.as_str()],
                    Value::Arr(arr) => arr.iter().filter_map(|v| match v { Value::Str(s) => Some(s.as_str()), _ => None }).collect(),
                    _ => vec![],
                };
                let matches = type_names.iter().any(|t| type_matches(instance, t));
                if !matches {
                    errors.insert((inst_loc.to_string(), format!("{}/type", schema_loc)));
                }
            }

            // enum
            if let Some(enum_val) = get("enum") {
                if let Value::Arr(arr) = enum_val {
                    if !arr.iter().any(|e| deep_eq(instance, e)) {
                        errors.insert((inst_loc.to_string(), format!("{}/enum", schema_loc)));
                    }
                }
            }

            // const
            if let Some(const_val) = get("const") {
                if !deep_eq(instance, const_val) {
                    errors.insert((inst_loc.to_string(), format!("{}/const", schema_loc)));
                }
            }

            // Number keywords
            if let Value::Num(n) = instance {
                if let Some(Value::Num(m)) = get("minimum") {
                    if !(n >= *m) {
                        errors.insert((inst_loc.to_string(), format!("{}/minimum", schema_loc)));
                    }
                }
                if let Some(Value::Num(m)) = get("maximum") {
                    if !(n <= *m) {
                        errors.insert((inst_loc.to_string(), format!("{}/maximum", schema_loc)));
                    }
                }
                if let Some(Value::Num(m)) = get("exclusiveMinimum") {
                    if !(n > *m) {
                        errors.insert((inst_loc.to_string(), format!("{}/exclusiveMinimum", schema_loc)));
                    }
                }
                if let Some(Value::Num(m)) = get("exclusiveMaximum") {
                    if !(n < *m) {
                        errors.insert((inst_loc.to_string(), format!("{}/exclusiveMaximum", schema_loc)));
                    }
                }
            }

            // String keywords
            if let Value::Str(s) = instance {
                let len = s.chars().count();
                if let Some(Value::Num(m)) = get("minLength") {
                    if (len as f64) < *m {
                        errors.insert((inst_loc.to_string(), format!("{}/minLength", schema_loc)));
                    }
                }
                if let Some(Value::Num(m)) = get("maxLength") {
                    if (len as f64) > *m {
                        errors.insert((inst_loc.to_string(), format!("{}/maxLength", schema_loc)));
                    }
                }
            }

            // Array keywords
            if let Value::Arr(arr) = instance {
                if let Some(Value::Num(m)) = get("minItems") {
                    if (arr.len() as f64) < *m {
                        errors.insert((inst_loc.to_string(), format!("{}/minItems", schema_loc)));
                    }
                }
                if let Some(Value::Num(m)) = get("maxItems") {
                    if (arr.len() as f64) > *m {
                        errors.insert((inst_loc.to_string(), format!("{}/maxItems", schema_loc)));
                    }
                }
                if let Some(Value::Bool(true)) = get("uniqueItems") {
                    if !check_unique(arr) {
                        errors.insert((inst_loc.to_string(), format!("{}/uniqueItems", schema_loc)));
                    }
                }

                // prefixItems
                let prefix_len = if let Some(Value::Arr(pi)) = get("prefixItems") {
                    for (i, sub) in pi.iter().enumerate() {
                        if i < arr.len() {
                            validate(&arr[i], sub,
                                &format!("{}/{}", inst_loc, i),
                                &format!("{}/prefixItems/{}", schema_loc, i),
                                root, errors);
                        }
                    }
                    pi.len()
                } else {
                    0
                };

                // items
                if let Some(items_schema) = get("items") {
                    for i in prefix_len..arr.len() {
                        validate(&arr[i], items_schema,
                            &format!("{}/{}", inst_loc, i),
                            &format!("{}/items", schema_loc),
                            root, errors);
                    }
                }
            }

            // Object keywords
            if let Value::Obj(inst_obj) = instance {
                // properties
                if let Some(Value::Obj(props)) = get("properties") {
                    for (key, val) in inst_obj {
                        if let Some((_, sub)) = props.iter().find(|(k, _)| k == key) {
                            validate(val, sub,
                                &format!("{}/{}", inst_loc, encode_token(key)),
                                &format!("{}/properties/{}", schema_loc, encode_token(key)),
                                root, errors);
                        }
                    }
                }

                // required
                if let Some(Value::Arr(req)) = get("required") {
                    for (j, name) in req.iter().enumerate() {
                        if let Value::Str(name_str) = name {
                            if !inst_obj.iter().any(|(k, _)| k == name_str) {
                                errors.insert((inst_loc.to_string(), format!("{}/required/{}", schema_loc, j)));
                            }
                        }
                    }
                }

                // additionalProperties
                if let Some(add_prop) = get("additionalProperties") {
                    let prop_keys: Vec<&String> = if let Some(Value::Obj(props)) = get("properties") {
                        props.iter().map(|(k, _)| k).collect()
                    } else {
                        vec![]
                    };
                    for (key, val) in inst_obj {
                        if !prop_keys.iter().any(|k| *k == key) {
                            validate(val, add_prop,
                                &format!("{}/{}", inst_loc, encode_token(key)),
                                &format!("{}/additionalProperties", schema_loc),
                                root, errors);
                        }
                    }
                }

                // minProperties, maxProperties
                if let Some(Value::Num(m)) = get("minProperties") {
                    if (inst_obj.len() as f64) < *m {
                        errors.insert((inst_loc.to_string(), format!("{}/minProperties", schema_loc)));
                    }
                }
                if let Some(Value::Num(m)) = get("maxProperties") {
                    if (inst_obj.len() as f64) > *m {
                        errors.insert((inst_loc.to_string(), format!("{}/maxProperties", schema_loc)));
                    }
                }
            }

            // $ref
            if let Some(Value::Str(ref_str)) = get("$ref") {
                let (ref_schema, ref_loc) = resolve_ref(ref_str, root);
                validate(instance, ref_schema, inst_loc, &ref_loc, root, errors);
            }

            // allOf
            if let Some(Value::Arr(subs)) = get("allOf") {
                for (i, sub) in subs.iter().enumerate() {
                    validate(instance, sub, inst_loc,
                        &format!("{}/allOf/{}", schema_loc, i), root, errors);
                }
            }

            // anyOf
            if let Some(Value::Arr(subs)) = get("anyOf") {
                let any_valid = subs.iter().any(|sub| {
                    let mut temp = HashSet::new();
                    validate(instance, sub, inst_loc, schema_loc, root, &mut temp);
                    temp.is_empty()
                });
                if !any_valid {
                    errors.insert((inst_loc.to_string(), format!("{}/anyOf", schema_loc)));
                }
            }

            // oneOf
            if let Some(Value::Arr(subs)) = get("oneOf") {
                let count = subs.iter().filter(|sub| {
                    let mut temp = HashSet::new();
                    validate(instance, sub, inst_loc, schema_loc, root, &mut temp);
                    temp.is_empty()
                }).count();
                if count != 1 {
                    errors.insert((inst_loc.to_string(), format!("{}/oneOf", schema_loc)));
                }
            }

            // not
            if let Some(sub) = get("not") {
                let mut temp = HashSet::new();
                validate(instance, sub, inst_loc, schema_loc, root, &mut temp);
                if temp.is_empty() {
                    errors.insert((inst_loc.to_string(), format!("{}/not", schema_loc)));
                }
            }

            // if/then/else
            if let Some(if_schema) = get("if") {
                let mut temp = HashSet::new();
                validate(instance, if_schema, inst_loc, schema_loc, root, &mut temp);
                if temp.is_empty() {
                    if let Some(then_schema) = get("then") {
                        validate(instance, then_schema, inst_loc,
                            &format!("{}/then", schema_loc), root, errors);
                    }
                } else {
                    if let Some(else_schema) = get("else") {
                        validate(instance, else_schema, inst_loc,
                            &format!("{}/else", schema_loc), root, errors);
                    }
                }
            }
        }
        _ => {}
    }
}

fn main() {
    let args: Vec<String> = env::args().collect();
    let dir = &args[1];

    let schema_str = fs::read_to_string(format!("{}/schema.json", dir)).unwrap();
    let instances_str = fs::read_to_string(format!("{}/instances.json", dir)).unwrap();

    let mut parser = Parser::new(&schema_str);
    let schema = parser.parse_value();

    let mut parser = Parser::new(&instances_str);
    let instances = parser.parse_value();

    let inst_arr = match instances {
        Value::Arr(a) => a,
        _ => panic!("instances must be an array"),
    };

    let mut valid_count = 0;
    let mut invalid_count = 0;

    for (i, inst) in inst_arr.iter().enumerate() {
        let mut errors = HashSet::new();
        validate(inst, &schema, "#", "#", &schema, &mut errors);

        if errors.is_empty() {
            println!("{}: valid", i);
            valid_count += 1;
        } else {
            let mut sorted: Vec<(String, String)> = errors.into_iter().collect();
            sorted.sort();
            println!("{}: invalid ({})", i, sorted.len());
            for (inst_loc, schema_loc) in &sorted {
                println!("  {} {}", inst_loc, schema_loc);
            }
            invalid_count += 1;
        }
    }

    println!("valid={} invalid={}", valid_count, invalid_count);
}

use std::collections::HashSet;
use std::env;
use std::fs;

#[derive(Debug, Clone)]
enum Value {
    Null,
    Bool(bool),
    Num(f64),
    Str(String),
    Arr(Vec<Value>),
    Obj(Vec<(String, Value)>),
}

struct Parser {
    input: Vec<char>,
    pos: usize,
}

impl Parser {
    fn new(s: &str) -> Self {
        Parser { input: s.chars().collect(), pos: 0 }
    }

    fn parse_value(&mut self) -> Value {
        self.skip_ws();
        match self.input[self.pos] {
            'n' => { self.expect("null"); Value::Null }
            't' => { self.expect("true"); Value::Bool(true) }
            'f' => { self.expect("false"); Value::Bool(false) }
            '"' => Value::Str(self.parse_string()),
            '[' => self.parse_array(),
            '{' => self.parse_object(),
            _ => self.parse_number(),
        }
    }

    fn skip_ws(&mut self) {
        while self.pos < self.input.len() {
            let c = self.input[self.pos];
            if c == ' ' || c == '\t' || c == '\n' || c == '\r' {
                self.pos += 1;
            } else {
                break;
            }
        }
    }

    fn expect(&mut self, s: &str) {
        for c in s.chars() {
            assert_eq!(self.input[self.pos], c);
            self.pos += 1;
        }
    }

    fn parse_string(&mut self) -> String {
        assert_eq!(self.input[self.pos], '"');
        self.pos += 1;
        let mut result = String::new();
        loop {
            let c = self.input[self.pos];
            self.pos += 1;
            if c == '"' { break; }
            if c == '\\' {
                let e = self.input[self.pos];
                self.pos += 1;
                match e {
                    '"' => result.push('"'),
                    '\\' => result.push('\\'),
                    '/' => result.push('/'),
                    'b' => result.push('\u{0008}'),
                    'f' => result.push('\u{000C}'),
                    'n' => result.push('\n'),
                    'r' => result.push('\r'),
                    't' => result.push('\t'),
                    'u' => {
                        let cp = self.parse_hex4();
                        if cp >= 0xD800 && cp <= 0xDBFF {
                            assert_eq!(self.input[self.pos], '\\');
                            self.pos += 1;
                            assert_eq!(self.input[self.pos], 'u');
                            self.pos += 1;
                            let lo = self.parse_hex4();
                            let code = 0x10000 + ((cp - 0xD800) << 10) + (lo - 0xDC00);
                            result.push(char::from_u32(code).unwrap());
                        } else {
                            result.push(char::from_u32(cp).unwrap());
                        }
                    }
                    _ => unreachable!(),
                }
            } else {
                result.push(c);
            }
        }
        result
    }

    fn parse_hex4(&mut self) -> u32 {
        let mut val = 0u32;
        for _ in 0..4 {
            let c = self.input[self.pos];
            self.pos += 1;
            let d = match c {
                '0'..='9' => (c as u32) - ('0' as u32),
                'a'..='f' => 10 + (c as u32) - ('a' as u32),
                'A'..='F' => 10 + (c as u32) - ('A' as u32),
                _ => unreachable!(),
            };
            val = val * 16 + d;
        }
        val
    }

    fn parse_number(&mut self) -> Value {
        let start = self.pos;
        if self.input[self.pos] == '-' { self.pos += 1; }
        while self.pos < self.input.len() && self.input[self.pos].is_ascii_digit() { self.pos += 1; }
        if self.pos < self.input.len() && self.input[self.pos] == '.' {
            self.pos += 1;
            while self.pos < self.input.len() && self.input[self.pos].is_ascii_digit() { self.pos += 1; }
        }
        if self.pos < self.input.len() && (self.input[self.pos] == 'e' || self.input[self.pos] == 'E') {
            self.pos += 1;
            if self.pos < self.input.len() && (self.input[self.pos] == '+' || self.input[self.pos] == '-') { self.pos += 1; }
            while self.pos < self.input.len() && self.input[self.pos].is_ascii_digit() { self.pos += 1; }
        }
        let s: String = self.input[start..self.pos].iter().collect();
        Value::Num(s.parse::<f64>().unwrap())
    }

    fn parse_array(&mut self) -> Value {
        assert_eq!(self.input[self.pos], '[');
        self.pos += 1;
        let mut arr = Vec::new();
        self.skip_ws();
        if self.pos < self.input.len() && self.input[self.pos] == ']' {
            self.pos += 1;
            return Value::Arr(arr);
        }
        loop {
            arr.push(self.parse_value());
            self.skip_ws();
            if self.input[self.pos] == ',' { self.pos += 1; continue; }
            if self.input[self.pos] == ']' { self.pos += 1; break; }
            unreachable!();
        }
        Value::Arr(arr)
    }

    fn parse_object(&mut self) -> Value {
        assert_eq!(self.input[self.pos], '{');
        self.pos += 1;
        let mut obj = Vec::new();
        self.skip_ws();
        if self.pos < self.input.len() && self.input[self.pos] == '}' {
            self.pos += 1;
            return Value::Obj(obj);
        }
        loop {
            self.skip_ws();
            let key = self.parse_string();
            self.skip_ws();
            assert_eq!(self.input[self.pos], ':');
            self.pos += 1;
            let val = self.parse_value();
            obj.push((key, val));
            self.skip_ws();
            if self.input[self.pos] == ',' { self.pos += 1; continue; }
            if self.input[self.pos] == '}' { self.pos += 1; break; }
            unreachable!();
        }
        Value::Obj(obj)
    }
}

fn deep_eq(a: &Value, b: &Value) -> bool {
    match (a, b) {
        (Value::Null, Value::Null) => true,
        (Value::Bool(a), Value::Bool(b)) => a == b,
        (Value::Num(a), Value::Num(b)) => a == b,
        (Value::Str(a), Value::Str(b)) => a == b,
        (Value::Arr(a), Value::Arr(b)) => {
            a.len() == b.len() && a.iter().zip(b.iter()).all(|(x, y)| deep_eq(x, y))
        }
        (Value::Obj(a), Value::Obj(b)) => {
            if a.len() != b.len() { return false; }
            for (k, va) in a {
                match b.iter().find(|(kb, _)| kb == k) {
                    Some((_, vb)) => if !deep_eq(va, vb) { return false; },
                    None => return false,
                }
            }
            true
        }
        _ => false,
    }
}

fn encode_token(s: &str) -> String {
    s.replace('~', "~0").replace('/', "~1")
}

fn decode_token(s: &str) -> String {
    s.replace("~1", "/").replace("~0", "~")
}

fn resolve_ref<'a>(ref_str: &str, root: &'a Value) -> (&'a Value, String) {
    assert!(ref_str.starts_with('#'));
    let pointer = &ref_str[1..];
    if pointer.is_empty() {
        return (root, "#".to_string());
    }
    let mut current = root;
    let mut loc = String::from("#");
    for token in pointer[1..].split('/') {
        let key = decode_token(token);
        loc.push('/');
        loc.push_str(token);
        match current {
            Value::Obj(obj) => {
                current = &obj.iter().find(|(k, _)| *k == key).unwrap().1;
            }
            _ => panic!("cannot navigate into non-object via $ref"),
        }
    }
    (current, loc)
}

fn type_matches(instance: &Value, type_name: &str) -> bool {
    match (instance, type_name) {
        (Value::Null, "null") => true,
        (Value::Bool(_), "boolean") => true,
        (Value::Num(_), "number") => true,
        (Value::Num(n), "integer") => n.fract() == 0.0,
        (Value::Str(_), "string") => true,
        (Value::Arr(_), "array") => true,
        (Value::Obj(_), "object") => true,
        _ => false,
    }
}

fn check_unique(arr: &[Value]) -> bool {
    for i in 0..arr.len() {
        for j in i + 1..arr.len() {
            if deep_eq(&arr[i], &arr[j]) {
                return false;
            }
        }
    }
    true
}

fn validate(
    instance: &Value,
    schema: &Value,
    inst_loc: &str,
    schema_loc: &str,
    root: &Value,
    errors: &mut HashSet<(String, String)>,
) {
    match schema {
        Value::Bool(true) => return,
        Value::Bool(false) => {
            errors.insert((inst_loc.to_string(), schema_loc.to_string()));
            return;
        }
        Value::Obj(obj) => {
            let get = |key: &str| -> Option<&Value> {
                obj.iter().find(|(k, _)| k == key).map(|(_, v)| v)
            };

            // type
            if let Some(type_val) = get("type") {
                let type_names: Vec<&str> = match type_val {
                    Value::Str(s) => vec![s.as_str()],
                    Value::Arr(arr) => arr.iter().filter_map(|v| match v { Value::Str(s) => Some(s.as_str()), _ => None }).collect(),
                    _ => vec![],
                };
                let matches = type_names.iter().any(|t| type_matches(instance, t));
                if !matches {
                    errors.insert((inst_loc.to_string(), format!("{}/type", schema_loc)));
                }
            }

            // enum
            if let Some(enum_val) = get("enum") {
                if let Value::Arr(arr) = enum_val {
                    if !arr.iter().any(|e| deep_eq(instance, e)) {
                        errors.insert((inst_loc.to_string(), format!("{}/enum", schema_loc)));
                    }
                }
            }

            // const
            if let Some(const_val) = get("const") {
                if !deep_eq(instance, const_val) {
                    errors.insert((inst_loc.to_string(), format!("{}/const", schema_loc)));
                }
            }

            // Number keywords
            if let Value::Num(n) = instance {
                if let Some(Value::Num(m)) = get("minimum") {
                    if !(*n >= *m) {
                        errors.insert((inst_loc.to_string(), format!("{}/minimum", schema_loc)));
                    }
                }
                if let Some(Value::Num(m)) = get("maximum") {
                    if !(*n <= *m) {
                        errors.insert((inst_loc.to_string(), format!("{}/maximum", schema_loc)));
                    }
                }
                if let Some(Value::Num(m)) = get("exclusiveMinimum") {
                    if !(*n > *m) {
                        errors.insert((inst_loc.to_string(), format!("{}/exclusiveMinimum", schema_loc)));
                    }
                }
                if let Some(Value::Num(m)) = get("exclusiveMaximum") {
                    if !(*n < *m) {
                        errors.insert((inst_loc.to_string(), format!("{}/exclusiveMaximum", schema_loc)));
                    }
                }
            }

            // String keywords
            if let Value::Str(s) = instance {
                let len = s.chars().count();
                if let Some(Value::Num(m)) = get("minLength") {
                    if (len as f64) < *m {
                        errors.insert((inst_loc.to_string(), format!("{}/minLength", schema_loc)));
                    }
                }
                if let Some(Value::Num(m)) = get("maxLength") {
                    if (len as f64) > *m {
                        errors.insert((inst_loc.to_string(), format!("{}/maxLength", schema_loc)));
                    }
                }
            }

            // Array keywords
            if let Value::Arr(arr) = instance {
                if let Some(Value::Num(m)) = get("minItems") {
                    if (arr.len() as f64) < *m {
                        errors.insert((inst_loc.to_string(), format!("{}/minItems", schema_loc)));
                    }
                }
                if let Some(Value::Num(m)) = get("maxItems") {
                    if (arr.len() as f64) > *m {
                        errors.insert((inst_loc.to_string(), format!("{}/maxItems", schema_loc)));
                    }
                }
                if let Some(Value::Bool(true)) = get("uniqueItems") {
                    if !check_unique(arr) {
                        errors.insert((inst_loc.to_string(), format!("{}/uniqueItems", schema_loc)));
                    }
                }

                // prefixItems
                let prefix_len = if let Some(Value::Arr(pi)) = get("prefixItems") {
                    for (i, sub) in pi.iter().enumerate() {
                        if i < arr.len() {
                            validate(&arr[i], sub,
                                &format!("{}/{}", inst_loc, i),
                                &format!("{}/prefixItems/{}", schema_loc, i),
                                root, errors);
                        }
                    }
                    pi.len()
                } else {
                    0
                };

                // items
                if let Some(items_schema) = get("items") {
                    for i in prefix_len..arr.len() {
                        validate(&arr[i], items_schema,
                            &format!("{}/{}", inst_loc, i),
                            &format!("{}/items", schema_loc),
                            root, errors);
                    }
                }
            }

            // Object keywords
            if let Value::Obj(inst_obj) = instance {
                // properties
                if let Some(Value::Obj(props)) = get("properties") {
                    for (key, val) in inst_obj {
                        if let Some((_, sub)) = props.iter().find(|(k, _)| k == key) {
                            validate(val, sub,
                                &format!("{}/{}", inst_loc, encode_token(key)),
                                &format!("{}/properties/{}", schema_loc, encode_token(key)),
                                root, errors);
                        }
                    }
                }

                // required
                if let Some(Value::Arr(req)) = get("required") {
                    for (j, name) in req.iter().enumerate() {
                        if let Value::Str(name_str) = name {
                            if !inst_obj.iter().any(|(k, _)| k == name_str) {
                                errors.insert((inst_loc.to_string(), format!("{}/required/{}", schema_loc, j)));
                            }
                        }
                    }
                }

                // additionalProperties
                if let Some(add_prop) = get("additionalProperties") {
                    let prop_keys: Vec<&String> = if let Some(Value::Obj(props)) = get("properties") {
                        props.iter().map(|(k, _)| k).collect()
                    } else {
                        vec![]
                    };
                    for (key, val) in inst_obj {
                        if !prop_keys.iter().any(|k| *k == key) {
                            validate(val, add_prop,
                                &format!("{}/{}", inst_loc, encode_token(key)),
                                &format!("{}/additionalProperties", schema_loc),
                                root, errors);
                        }
                    }
                }

                // minProperties, maxProperties
                if let Some(Value::Num(m)) = get("minProperties") {
                    if (inst_obj.len() as f64) < *m {
                        errors.insert((inst_loc.to_string(), format!("{}/minProperties", schema_loc)));
                    }
                }
                if let Some(Value::Num(m)) = get("maxProperties") {
                    if (inst_obj.len() as f64) > *m {
                        errors.insert((inst_loc.to_string(), format!("{}/maxProperties", schema_loc)));
                    }
                }
            }

            // $ref
            if let Some(Value::Str(ref_str)) = get("$ref") {
                let (ref_schema, ref_loc) = resolve_ref(ref_str, root);
                validate(instance, ref_schema, inst_loc, &ref_loc, root, errors);
            }

            // allOf
            if let Some(Value::Arr(subs)) = get("allOf") {
                for (i, sub) in subs.iter().enumerate() {
                    validate(instance, sub, inst_loc,
                        &format!("{}/allOf/{}", schema_loc, i), root, errors);
                }
            }

            // anyOf
            if let Some(Value::Arr(subs)) = get("anyOf") {
                let any_valid = subs.iter().any(|sub| {
                    let mut temp = HashSet::new();
                    validate(instance, sub, inst_loc, schema_loc, root, &mut temp);
                    temp.is_empty()
                });
                if !any_valid {
                    errors.insert((inst_loc.to_string(), format!("{}/anyOf", schema_loc)));
                }
            }

            // oneOf
            if let Some(Value::Arr(subs)) = get("oneOf") {
                let count = subs.iter().filter(|sub| {
                    let mut temp = HashSet::new();
                    validate(instance, sub, inst_loc, schema_loc, root, &mut temp);
                    temp.is_empty()
                }).count();
                if count != 1 {
                    errors.insert((inst_loc.to_string(), format!("{}/oneOf", schema_loc)));
                }
            }

            // not
            if let Some(sub) = get("not") {
                let mut temp = HashSet::new();
                validate(instance, sub, inst_loc, schema_loc, root, &mut temp);
                if temp.is_empty() {
                    errors.insert((inst_loc.to_string(), format!("{}/not", schema_loc)));
                }
            }

            // if/then/else
            if let Some(if_schema) = get("if") {
                let mut temp = HashSet::new();
                validate(instance, if_schema, inst_loc, schema_loc, root, &mut temp);
                if temp.is_empty() {
                    if let Some(then_schema) = get("then") {
                        validate(instance, then_schema, inst_loc,
                            &format!("{}/then", schema_loc), root, errors);
                    }
                } else {
                    if let Some(else_schema) = get("else") {
                        validate(instance, else_schema, inst_loc,
                            &format!("{}/else", schema_loc), root, errors);
                    }
                }
            }
        }
        _ => {}
    }
}

fn main() {
    let args: Vec<String> = env::args().collect();
    let dir = &args[1];

    let schema_str = fs::read_to_string(format!("{}/schema.json", dir)).unwrap();
    let instances_str = fs::read_to_string(format!("{}/instances.json", dir)).unwrap();

    let mut parser = Parser::new(&schema_str);
    let schema = parser.parse_value();

    let mut parser = Parser::new(&instances_str);
    let instances = parser.parse_value();

    let inst_arr = match instances {
        Value::Arr(a) => a,
        _ => panic!("instances must be an array"),
    };

    let mut valid_count = 0;
    let mut invalid_count = 0;

    for (i, inst) in inst_arr.iter().enumerate() {
        let mut errors = HashSet::new();
        validate(inst, &schema, "#", "#", &schema, &mut errors);

        if errors.is_empty() {
            println!("{}: valid", i);
            valid_count += 1;
        } else {
            let mut sorted: Vec<(String, String)> = errors.into_iter().collect();
            sorted.sort();
            println!("{}: invalid ({})", i, sorted.len());
            for (inst_loc, schema_loc) in &sorted {
                println!("  {} {}", inst_loc, schema_loc);
            }
            invalid_count += 1;
        }
    }

    println!("valid={} invalid={}", valid_count, invalid_count);
}

