fn sha512_generic(data: &[u8], h_init: [u64; 8], output_len: usize) -> Vec<u8> {
    let mut h = h_init;
    let msg_len = data.len();
    let bit_len = (msg_len as u128) * 8;
    let mut padded = data.to_vec();
    padded.push(0x80);
    while padded.len() % 128 != 112 {
        padded.push(0);
    }
    padded.extend_from_slice(&bit_len.to_be_bytes());
    for block in padded.chunks(128) {
        let mut w = [0u64; 80];
        for i in 0..16 {
            w[i] = u64::from_be_bytes([
                block[i*8], block[i*8+1], block[i*8+2], block[i*8+3],
                block[i*8+4], block[i*8+5], block[i*8+6], block[i*8+7],
            ]);
        }
        for i in 16..80 {
            let s0 = w[i-15].rotate_right(1) ^ w[i-15].rotate_right(8) ^ (w[i-15] >> 7);
            let s1 = w[i-2].rotate_right(19) ^ w[i-2].rotate_right(61) ^ (w[i-2] >> 6);
            w[i] = w[i-16].wrapping_add(s0).wrapping_add(w[i-7]).wrapping_add(s1);
        }
        let mut a = h[0]; let mut b = h[1]; let mut c = h[2]; let mut d = h[3];
        let mut e = h[4]; let mut f = h[5]; let mut g = h[6]; let mut hh = h[7];
        for i in 0..80 {
            let s1 = e.rotate_right(14) ^ e.rotate_right(18) ^ e.rotate_right(41);
            let ch = (e & f) ^ ((!e) & g);
            let temp1 = hh.wrapping_add(s1).wrapping_add(ch).wrapping_add(SHA512_K[i]).wrapping_add(w[i]);
            let s0 = a.rotate_right(28) ^ a.rotate_right(34) ^ a.rotate_right(39);
            let maj = (a & b) ^ (a & c) ^ (b & c);
            let temp2 = s0.wrapping_add(maj);
            hh = g; g = f; f = e; e = d.wrapping_add(temp1);
            d = c; c = b; b = a; a = temp1.wrapping_add(temp2);
        }
        h[0] = h[0].wrapping_add(a); h[1] = h[1].wrapping_add(b);
        h[2] = h[2].wrapping_add(c); h[3] = h[3].wrapping_add(d);
        h[4] = h[4].wrapping_add(e); h[5] = h[5].wrapping_add(f);
        h[6] = h[6].wrapping_add(g); h[7] = h[7].wrapping_add(hh);
    }
    let mut result = Vec::new();
    for i in 0..8 {
        result.extend_from_slice(&h[i].to_be_bytes());
    }
    result.truncate(output_len);
    result
}

fn sha384(data: &[u8]) -> Vec<u8> {
    let h_init: [u64; 8] = [
        0xcbbb9d5dc1059ed8, 0x629a292a367cd507, 0x9159015a3070dd17, 0x152fecd8f70e5939,
        0x67332667ffc00b31, 0x8eb44a8768581511, 0xdb0c2e0d64f98fa7, 0x47b5481dbefa4fa4,
    ];
    sha512_generic(data, h_init, 48)
}

fn sha512(data: &[u8]) -> Vec<u8> {
    let h_init: [u64; 8] = [
        0x6a09e667f3bcc908, 0xbb67ae8584caa73b, 0x3c6ef372fe94f82b, 0xa54ff53a5f1d36f1,
        0x510e527fade682d1, 0x9b05688c2b3e6c1f, 0x1f83d9abfb41bd6b, 0x5be0cd19137e2179,
    ];
    sha512_generic(data, h_init, 64)
}

// ============ HMAC ============

fn hmac(key: &[u8], data: &[u8], alg: &str) -> Vec<u8> {
    let (block_size, hash_fn): (usize, fn(&[u8]) -> Vec<u8>) = match alg {
        "HS256" => (64, |d| sha256(d).to_vec()),
        "HS384" => (128, |d| sha384(d)),
        "HS512" => (128, |d| sha512(d)),
        _ => unreachable!(),
    };

    let mut key_block = vec![0u8; block_size];
    if key.len() > block_size {
        let h = hash_fn(key);
        key_block[..h.len()].copy_from_slice(&h);
    } else {
        key_block[..key.len()].copy_from_slice(key);
    }

    let mut ipad = vec![0u8; block_size];
    let mut opad = vec![0u8; block_size];
    for i in 0..block_size {
        ipad[i] = key_block[i] ^ 0x36;
        opad[i] = key_block[i] ^ 0x5c;
    }

    let mut inner = Vec::with_capacity(block_size + data.len());
    inner.extend_from_slice(&ipad);
    inner.extend_from_slice(data);
    let inner_hash = hash_fn(&inner);

    let mut outer = Vec::with_capacity(block_size + inner_hash.len());
    outer.extend_from_slice(&opad);
    outer.extend_from_slice(&inner_hash);
    hash_fn(&outer)
}

// ============ Main ============

fn main() {
    let args: Vec<String> = env::args().collect();
    let dir = &args[1];

    let config_str = fs::read_to_string(format!("{}/config.json", dir)).unwrap();
    let config = parse_json(config_str.as_bytes()).unwrap();

    let now = config.get("now").and_then(|v| v.as_num()).unwrap();
    let leeway = config.get("leeway").and_then(|v| v.as_num()).unwrap();
    let issuer = config.get("issuer").and_then(|v| v.as_str()).unwrap_or("").to_string();
    let audience = config.get("audience").and_then(|v| v.as_str()).unwrap_or("").to_string();

    struct KeyInfo {
        kid: String,
        alg: String,
        secret: Vec<u8>,
    }
    let mut keys: Vec<KeyInfo> = Vec::new();
    if let Some(JsonValue::Array(key_arr)) = config.get("keys") {
        for kv in key_arr {
            let kid = kv.get("kid").and_then(|v| v.as_str()).unwrap_or("").to_string();
            let alg = kv.get("alg").and_then(|v| v.as_str()).unwrap_or("").to_string();
            let k_str = kv.get("k").and_then(|v| v.as_str()).unwrap_or("");
            let secret = base64url_decode(k_str).unwrap_or_default();
            keys.push(KeyInfo { kid, alg, secret });
        }
    }

    let tokens_str = fs::read_to_string(format!("{}/tokens.txt", dir)).unwrap();
    let mut valid_count = 0usize;
    let mut invalid_count = 0usize;
    let mut line_num = 0usize;

    for raw_line in tokens_str.split('\n') {
        let line = raw_line.trim_matches(|c: char| c == ' ' || c == '\t');
        if line.is_empty() {
            continue;
        }
        line_num += 1;
        let result = verify_token(line, &keys, now, leeway, &issuer, &audience);
        match &result {
            Ok((sub, scopes)) => {
                println!("{}: VALID sub={} scope={}", line_num, sub, scopes);
                valid_count += 1;
            }
            Err(err) => {
                println!("{}: {}", line_num, err);
                invalid_count += 1;
            }
        }
    }

    println!();
    println!("valid={} invalid={}", valid_count, invalid_count);
}

fn verify_token(
    token: &str,
    keys: &[KeyInfo],
    now: f64,
    leeway: f64,
    issuer: &str,
    audience: &str,
) -> Result<(String, String), String> {
    // Rule 1: MALFORMED
    let segments: Vec<&str> = token.split('.').collect();
    if segments.len() != 3 {
        return Err("MALFORMED".into());
    }
    for seg in &segments {
        if seg.is_empty() {
            return Err("MALFORMED".into());
        }
        // Validate base64url
        if seg.len() % 4 == 1 {
            return Err("MALFORMED".into());
        }
        for &b in seg.as_bytes() {
            match b {
                b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'_' => {}
                _ => return Err("MALFORMED".into()),
            }
        }
    }

    let header_bytes = match base64url_decode(segments[0]) {
        Some(b) => b,
        None => return Err("MALFORMED".into()),
    };
    let payload_bytes = match base64url_decode(segments[1]) {
        Some(b) => b,
        None => return Err("MALFORMED".into()),
    };
    let sig_bytes = match base64url_decode(segments[2]) {
        Some(b) => b,
        None => return Err("MALFORMED".into()),
    };

    let header = match parse_json(&header_bytes) {
        Ok(JsonValue::Object(_)) => { /* ok */ }
        _ => return Err("MALFORMED".into()),
    };
    let header = match parse_json(&header_bytes) {
        Ok(v) => v,
        Err(_) => return Err("MALFORMED".into()),
    };
    // Re-parse to get the object
    let header = match parse_json(&header_bytes) {
        Ok(v @ JsonValue::Object(_)) => v,
        _ => return Err("MALFORMED".into()),
    };
    let payload = match parse_json(&payload_bytes) {
        Ok(v @ JsonValue::Object(_)) => v,
        _ => return Err("MALFORMED".into()),
    };

    // Rule 2: UNSUPPORTED_ALG
    let alg = match header.get("alg") {
        Some(JsonValue::Str(s)) => {
            if s == "HS256" || s == "HS384" || s == "HS512" {
                s.clone()
            } else {
                return Err("UNSUPPORTED_ALG".into());
            }
        }
        _ => return Err("UNSUPPORTED_ALG".into()),
    };

    // Rule 3: UNKNOWN_KEY
    let kid = match header.get("kid") {
        Some(JsonValue::Str(s)) => s.clone(),
        _ => return Err("UNKNOWN_KEY".into()),
    };
    let key = match keys.iter().find(|k| k.kid == kid) {
        Some(k) => k,
        None => return Err("UNKNOWN_KEY".into()),
    };

    // Rule 4: ALG_MISMATCH
    if key.alg != alg {
        return Err("ALG_MISMATCH".into());
    }

    // Rule 5: BAD_SIGNATURE
    let signing_input = format!("{}.{}", segments[0], segments[1]);
    let expected_sig = hmac(&key.secret, signing_input.as_bytes(), &alg);
    if sig_bytes != expected_sig {
        return Err("BAD_SIGNATURE".into());
    }

    // Rule 6: EXPIRED
    if let Some(exp_val) = payload.get("exp").and_then(|v| v.as_num()) {
        if now >= exp_val + leeway {
            return Err("EXPIRED".into());
        }
    }

    // Rule 7: NOT_YET_VALID
    if let Some(nbf_val) = payload.get("nbf").and_then(|v| v.as_num()) {
        if now + leeway < nbf_val {
            return Err("NOT_YET_VALID".into());
        }
    }

    // Rule 8: BAD_ISSUER
    match payload.get("iss") {
        Some(JsonValue::Str(s)) if s == issuer => {}
        _ => return Err("BAD_ISSUER".into()),
    }

    // Rule 9: BAD_AUDIENCE
    match payload.get("aud") {
        Some(JsonValue::Str(s)) => {
            if s != audience {
                return Err("BAD_AUDIENCE".into());
            }
        }
        Some(JsonValue::Array(arr)) => {
            let found = arr.iter().any(|v| v.as_str() == Some(audience));
            if !found {
                return Err("BAD_AUDIENCE".into());
            }
        }
        _ => return Err("BAD_AUDIENCE".into()),
    }

    // VALID
    let sub = payload.get("sub").and_then(|v| v.as_str()).unwrap_or("").to_string();
    let scope_str = payload.get("scope").and_then(|v| v.as_str()).unwrap_or("");
    let scopes = if scope_str.is_empty() {
        String::new()
    } else {
        let mut set: BTreeSet<String> = BTreeSet::new();
        for part in scope_str.split(' ') {
            if !part.is_empty() {
                set.insert(part.to_string());
            }
        }
        set.into_iter().collect::<Vec<_>>().join(",")
    };

    Ok((sub, scopes))
}

