// ============ UTF-8 helper ============

fn push_utf8(buf: &mut Vec<u8>, cp: u32) {
    if cp < 0x80 {
        buf.push(cp as u8);
    } else if cp < 0x800 {
        buf.push((0xC0 | (cp >> 6)) as u8);
        buf.push((0x80 | (cp & 0x3F)) as u8);
    } else if cp < 0x10000 {
        buf.push((0xE0 | (cp >> 12)) as u8);
        buf.push((0x80 | ((cp >> 6) & 0x3F)) as u8);
        buf.push((0x80 | (cp & 0x3F)) as u8);
    } else {
        buf.push((0xF0 | (cp >> 18)) as u8);
        buf.push((0x80 | ((cp >> 12) & 0x3F)) as u8);
        buf.push((0x80 | ((cp >> 6) & 0x3F)) as u8);
        buf.push((0x80 | (cp & 0x3F)) as u8);
    }
}

// ============ Base64url ============

fn base64url_decode(s: &str) -> Option<Vec<u8>> {
    if s.len() % 4 == 1 {
        return None;
    }
    for &b in s.as_bytes() {
        match b {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'_' => {}
            _ => return None,
        }
    }
    let mut result = Vec::new();
    let mut buf: u32 = 0;
    let mut bits: u32 = 0;
    for &b in s.as_bytes() {
        let val: u32 = match b {
            b'A'..=b'Z' => (b - b'A') as u32,
            b'a'..=b'z' => (b - b'a' + 26) as u32,
            b'0'..=b'9' => (b - b'0' + 52) as u32,
            b'-' => 62,
            b'_' => 63,
            _ => return None,
        };
        buf = (buf << 6) | val;
        bits += 6;
        if bits >= 8 {
            bits -= 8;
            result.push((buf >> bits) as u8);
        }
    }
    Some(result)
}

// ============ JSON ============

#[derive(Debug, Clone)]
enum JsonValue {
    Null,
    Bool(bool),
    Num(f64),
    Str(String),
    Array(Vec<JsonValue>),
    Object(Vec<(String, JsonValue)>),
}

impl JsonValue {
    fn as_str(&self) -> Option<&str> {
        if let JsonValue::Str(s) = self { Some(s) } else { None }
    }
    fn as_num(&self) -> Option<f64> {
        if let JsonValue::Num(n) = self { Some(*n) } else { None }
    }
    fn get(&self, key: &str) -> Option<&JsonValue> {
        if let JsonValue::Object(pairs) = self {
            for (k, v) in pairs {
                if k == key { return Some(v); }
            }
        }
        None
    }
}

struct JsonParser<'a> {
    input: &'a [u8],
    pos: usize,
}

impl<'a> JsonParser<'a> {
    fn new(input: &'a [u8]) -> Self {
        JsonParser { input, pos: 0 }
    }

    fn skip_ws(&mut self) {
        while self.pos < self.input.len() {
            match self.input[self.pos] {
                b' ' | b'\t' | b'\n' | b'\r' => self.pos += 1,
                _ => break,
            }
        }
    }

    fn parse_value(&mut self) -> Result<JsonValue, String> {
        self.skip_ws();
        if self.pos >= self.input.len() {
            return Err("unexpected end".into());
        }
        match self.input[self.pos] {
            b'{' => self.parse_object(),
            b'[' => self.parse_array(),
            b'"' => self.parse_string().map(JsonValue::Str),
            b't' => self.parse_literal(b"true", JsonValue::Bool(true)),
            b'f' => self.parse_literal(b"false", JsonValue::Bool(false)),
            b'n' => self.parse_literal(b"null", JsonValue::Null),
            _ => self.parse_number(),
        }
    }

    fn parse_literal(&mut self, lit: &[u8], val: JsonValue) -> Result<JsonValue, String> {
        if self.input.len() - self.pos >= lit.len() && &self.input[self.pos..self.pos + lit.len()] == lit {
            self.pos += lit.len();
            Ok(val)
        } else {
            Err("invalid literal".into())
        }
    }

    fn parse_object(&mut self) -> Result<JsonValue, String> {
        self.pos += 1;
        let mut pairs = Vec::new();
        self.skip_ws();
        if self.pos < self.input.len() && self.input[self.pos] == b'}' {
            self.pos += 1;
            return Ok(JsonValue::Object(pairs));
        }
        loop {
            self.skip_ws();
            if self.pos >= self.input.len() || self.input[self.pos] != b'"' {
                return Err("expected string key".into());
            }
            let key = self.parse_string()?;
            self.skip_ws();
            if self.pos >= self.input.len() || self.input[self.pos] != b':' {
                return Err("expected :".into());
            }
            self.pos += 1;
            let value = self.parse_value()?;
            pairs.push((key, value));
            self.skip_ws();
            if self.pos >= self.input.len() {
                return Err("unexpected end".into());
            }
            match self.input[self.pos] {
                b',' => { self.pos += 1; }
                b'}' => { self.pos += 1; return Ok(JsonValue::Object(pairs)); }
                _ => return Err("expected , or }".into()),
            }
        }
    }

    fn parse_array(&mut self) -> Result<JsonValue, String> {
        self.pos += 1;
        let mut items = Vec::new();
        self.skip_ws();
        if self.pos < self.input.len() && self.input[self.pos] == b']' {
            self.pos += 1;
            return Ok(JsonValue::Array(items));
        }
        loop {
            let value = self.parse_value()?;
            items.push(value);
            self.skip_ws();
            if self.pos >= self.input.len() {
                return Err("unexpected end".into());
            }
            match self.input[self.pos] {
                b',' => { self.pos += 1; }
                b']' => { self.pos += 1; return Ok(JsonValue::Array(items)); }
                _ => return Err("expected , or ]".into()),
            }
        }
    }

    fn parse_string(&mut self) -> Result<String, String> {
        self.pos += 1;
        let mut bytes: Vec<u8> = Vec::new();
        loop {
            if self.pos >= self.input.len() { return Err("unterminated string".into()); }
            let c = self.input[self.pos];
            if c == b'"' { self.pos += 1; break; }
            if c == b'\\' {
                self.pos += 1;
                if self.pos >= self.input.len() { return Err("unexpected end".into()); }
                let esc = self.input[self.pos];
                self.pos += 1;
                match esc {
                    b'"' => bytes.push(b'"'),
                    b'\\' => bytes.push(b'\\'),
                    b'/' => bytes.push(b'/'),
                    b'b' => bytes.push(0x08),
                    b'f' => bytes.push(0x0C),
                    b'n' => bytes.push(b'\n'),
                    b'r' => bytes.push(b'\r'),
                    b't' => bytes.push(b'\t'),
                    b'u' => {
                        let cp = self.parse_hex4()? as u32;
                        if cp >= 0xD800 && cp <= 0xDBFF {
                            if self.pos + 1 < self.input.len()
                                && self.input[self.pos] == b'\\'
                                && self.input[self.pos + 1] == b'u'
                            {
                                self.pos += 2;
                                let lo = self.parse_hex4()? as u32;
                                if lo >= 0xDC00 && lo <= 0xDFFF {
                                    let combined = 0x10000 + ((cp - 0xD800) << 10) + (lo - 0xDC00);
                                    push_utf8(&mut bytes, combined);
                                } else {
                                    push_utf8(&mut bytes, 0xFFFD);
                                    push_utf8(&mut bytes, 0xFFFD);
                                }
                            } else {
                                push_utf8(&mut bytes, 0xFFFD);
                            }
                        } else if cp >= 0xDC00 && cp <= 0xDFFF {
                            push_utf8(&mut bytes, 0xFFFD);
                        } else {
                            push_utf8(&mut bytes, cp);
                        }
                    }
                    _ => return Err("invalid escape".into()),
                }
            } else {
                bytes.push(c);
                self.pos += 1;
            }
        }
        String::from_utf8(bytes).map_err(|e| e.to_string())
    }

    fn parse_hex4(&mut self) -> Result<u16, String> {
        if self.pos + 4 > self.input.len() { return Err("unexpected end".into()); }
        let mut val: u16 = 0;
        for i in 0..4 {
            let c = self.input[self.pos + i];
            let d: u16 = match c {
                b'0'..=b'9' => (c - b'0') as u16,
                b'a'..=b'f' => (c - b'a' + 10) as u16,
                b'A'..=b'F' => (c - b'A' + 10) as u16,
                _ => return Err("invalid hex".into()),
            };
            val = val * 16 + d;
        }
        self.pos += 4;
        Ok(val)
    }

    fn parse_number(&mut self) -> Result<JsonValue, String> {
        let start = self.pos;
        if self.pos < self.input.len() && self.input[self.pos] == b'-' {
            self.pos += 1;
        }
        if self.pos >= self.input.len() { return Err("invalid number".into()); }
        if self.input[self.pos] == b'0' {
            self.pos += 1;
        } else if self.input[self.pos] >= b'1' && self.input[self.pos] <= b'9' {
            while self.pos < self.input.len() && self.input[self.pos] >= b'0' && self.input[self.pos] <= b'9' {
                self.pos += 1;
            }
        } else {
            return Err("invalid number".into());
        }
        if self.pos < self.input.len() && self.input[self.pos] == b'.' {
            self.pos += 1;
            if self.pos >= self.input.len() || self.input[self.pos] < b'0' || self.input[self.pos] > b'9' {
                return Err("invalid number".into());
            }
            while self.pos < self.input.len() && self.input[self.pos] >= b'0' && self.input[self.pos] <= b'9' {
                self.pos += 1;
            }
        }
        if self.pos < self.input.len() && (self.input[self.pos] == b'e' || self.input[self.pos] == b'E') {
            self.pos += 1;
            if self.pos < self.input.len() && (self.input[self.pos] == b'+' || self.input[self.pos] == b'-') {
                self.pos += 1;
            }
            if self.pos >= self.input.len() || self.input[self.pos] < b'0' || self.input[self.pos] > b'9' {
                return Err("invalid number".into());
            }
            while self.pos < self.input.len() && self.input[self.pos] >= b'0' && self.input[self.pos] <= b'9' {
                self.pos += 1;
            }
        }
        let s = std::str::from_utf8(&self.input[start..self.pos]).unwrap();
        let n: f64 = s.parse().map_err(|_| "invalid number".to_string())?;
        Ok(JsonValue::Num(n))
    }
}

fn parse_json(input: &[u8]) -> Result<JsonValue, String> {
    let mut parser = JsonParser::new(input);
    let val = parser.parse_value()?;
    parser.skip_ws();
    Ok(val)
}

