int main(void) {
    char *line=NULL;size_t bufsize=0;ssize_t nread;
    while((nread=getline(&line,&bufsize,stdin))!=-1){
        while(nread>0&&(line[nread-1]=='\n'||line[nread-1]=='\r'))nread--;
        /* Check empty/whitespace */
        int all_ws=1;
        for(ssize_t i=0;i<nread;i++){if(line[i]!=' '&&line[i]!='\t'&&line[i]!='\r'){all_ws=0;break;}}
        if(all_ws)continue;

        jval *msg=parse_json(line,(size_t)nread);
        if(!msg){send_error_id_null(-32700,"Parse error");continue;}

        /* Rule 2: not an object */
        if(msg->type!=JV_OBJECT){send_error_id_null(-32600,"Invalid Request");jval_free(msg);continue;}

        /* Rule 3: response from client */
        jval *method=obj_get(msg,"method");
        jval *result_m=obj_get(msg,"result");
        jval *error_m=obj_get(msg,"error");
        if(!method&&(result_m||error_m)){jval_free(msg);continue;}

        /* Rule 4: invalid request check */
        jval *jsonrpc=obj_get(msg,"jsonrpc");
        jval *id=obj_get(msg,"id");
        int has_id=obj_has(msg,"id");
        int valid_id=0;
        if(has_id){valid_id=(id->type==JV_STRING||id->type==JV_INT);}

        int invalid=0;
        if(!jsonrpc||jsonrpc->type!=JV_STRING||strcmp(jsonrpc->str_val,"2.0")!=0)invalid=1;
        if(!method||method->type!=JV_STRING)invalid=1;
        if(has_id&&!valid_id)invalid=1;

        if(invalid){
            printf("{\"jsonrpc\":\"2.0\",\"id\":");
            if(has_id&&valid_id)write_id(id);else printf("null");
            printf(",\"error\":{\"code\":-32600,\"message\":\"Invalid Request\"}}\n");
            jval_free(msg);continue;
        }

        /* Rule 5: notification */
        if(!has_id){jval_free(msg);continue;}

        /* Rule 6: request */
        const char *mname=method->str_val;
        jval *params=obj_get(msg,"params");

        /* 6a: method not found */
        int known=(strcmp(mname,"initialize")==0||strcmp(mname,"ping")==0||strcmp(mname,"tools/list")==0||strcmp(mname,"tools/call")==0);
        if(!known){send_error(id,-32601,"Method not found");jval_free(msg);continue;}

        /* 6b: params not object */
        if(obj_has(msg,"params")&&(!params||params->type!=JV_OBJECT)){send_error(id,-32602,"Invalid params");jval_free(msg);continue;}

        /* 6c: not initialized */
        if(!g_initialized&&strcmp(mname,"initialize")!=0&&strcmp(mname,"ping")!=0){
            send_error(id,-32002,"Server not initialized");jval_free(msg);continue;
        }

        /* 6d: dispatch */
        if(strcmp(mname,"initialize")==0){
            if(g_initialized){send_error(id,-32600,"Already initialized");jval_free(msg);continue;}
            if(!params){send_error(id,-32602,"Invalid params");jval_free(msg);continue;}
            jval *pv=obj_get(params,"protocolVersion");
            if(!pv||pv->type!=JV_STRING){send_error(id,-32602,"Invalid params");jval_free(msg);continue;}
            const char *ver=pv->str_val;
            if(strcmp(ver,"2025-06-18")!=0&&strcmp(ver,"2025-03-26")!=0&&strcmp(ver,"2024-11-05")!=0)ver="2025-06-18";
            g_initialized=1;
            printf("{\"jsonrpc\":\"2.0\",\"id\":");write_id(id);
            printf(",\"result\":{\"protocolVersion\":\"%s\",\"capabilities\":{\"tools\":{\"listChanged\":false}},\"serverInfo\":{\"name\":\"cb2-kv\",\"title\":\"CB2 key-value server\",\"version\":\"1.4.2\"}}}\n",ver);
        } else if(strcmp(mname,"ping")==0){
            printf("{\"jsonrpc\":\"2.0\",\"id\":");write_id(id);
            printf(",\"result\":{}}\n");
        } else if(strcmp(mname,"tools/list")==0){
            printf("{\"jsonrpc\":\"2.0\",\"id\":");write_id(id);
            printf(",\"result\":%s\n",TOOLS_LIST_RESULT);
        } else if(strcmp(mname,"tools/call")==0){
            handle_tools_call(msg,id);
        }

        jval_free(msg);
    }
    free(line);
    return 0;
}

import * as fs from 'fs';

// --- State ---
let initialized = false;
const store = new Map<string, string>();

// --- Tools definition ---
const TOOLS = [
  {
    name: "kv_set",
    title: "Set a value",
    description: "Store a string value under a key, replacing any previous value.",
    inputSchema: {
      type: "object",
      properties: {
        key: { type: "string", minLength: 1 },
        value: { type: "string" }
      },
      required: ["key", "value"],
      additionalProperties: false
    }
  },
  {
    name: "kv_get",
    title: "Get a value",
    description: "Return the value stored under a key.",
    inputSchema: {
      type: "object",
      properties: {
        key: { type: "string", minLength: 1 }
      },
      required: ["key"],
      additionalProperties: false
    }
  },
  {
    name: "kv_list",
    title: "List keys",
    description: "List the stored keys that start with a prefix, sorted by Unicode code point.",
    inputSchema: {
      type: "object",
      properties: {
        prefix: { type: "string" }
      },
      additionalProperties: false
    },
    outputSchema: {
      type: "object",
      properties: {
        keys: { type: "array", items: { type: "string" } },
        count: { type: "integer" }
      },
      required: ["keys", "count"]
    }
  },
  {
    name: "sum",
    title: "Sum integers",
    description: "Add up a non-empty list of integers.",
    inputSchema: {
      type: "object",
      properties: {
        numbers: { type: "array", items: { type: "integer" }, minItems: 1 }
      },
      required: ["numbers"],
      additionalProperties: false
    },
    outputSchema: {
      type: "object",
      properties: {
        sum: { type: "integer" },
        count: { type: "integer" }
      },
      required: ["sum", "count"]
    },
    annotations: { readOnlyHint: true, idempotentHint: true }
  },
  {
    name: "text_stats",
    title: "Text statistics",
    description: "Count the words, Unicode code points and UTF-8 bytes of a text.",
    inputSchema: {
      type: "object",
      properties: {
        text: { type: "string" }
      },
      required: ["text"],
      additionalProperties: false
    },
    outputSchema: {
      type: "object",
      properties: {
        words: { type: "integer" },
        codepoints: { type: "integer" },
        utf8_bytes: { type: "integer" }
      },
      required: ["words", "codepoints", "utf8_bytes"]
    },
    annotations: { readOnlyHint: true }
  }
];

// --- JSON scanning helpers ---
function isWS(c: string): boolean {
  return c === ' ' || c === '\t' || c === '\n' || c === '\r';
}

function skipValue(raw: string, i: number): number {
  const len = raw.length;
  if (i >= len) return i;
  const c = raw[i];
  if (c === '"') {
    i++;
    while (i < len && raw[i] !== '"') {
      if (raw[i] === '\\') i++;
      i++;
    }
    return i + 1;
  }
  if (c === '{') {
    let d = 1; i++;
    while (i < len && d > 0) {
      if (raw[i] === '"') { i++; while (i < len && raw[i] !== '"') { if (raw[i] === '\\') i++; i++; } i++; }
      else if (raw[i] === '{') { d++; i++; }
      else if (raw[i] === '}') { d--; i++; }
      else i++;
    }
    return i;
  }
  if (c === '[') {
    let d = 1; i++;
    while (i < len && d > 0) {
      if (raw[i] === '"') { i++; while (i < len && raw[i] !== '"') { if (raw[i] === '\\') i++; i++; } i++; }
      else if (raw[i] === '[') { d++; i++; }
      else if (raw[i] === ']') { d--; i++; }
      else i++;
    }
    return i;
  }
  if (c === 't') return i + 4;
  if (c === 'f') return i + 5;
  if (c === 'n') return i + 4;
  while (i < len && '-+0123456789.eE'.includes(raw[i])) i++;
  return i;
}

function findRawIdValue(raw: string): string | null {
  let i = 0;
  const len = raw.length;
  while (i < len && isWS(raw[i])) i++;
  if (i >= len || raw[i] !== '{') return null;
  i++;
  while (i < len) {
    while (i < len && isWS(raw[i])) i++;
    if (i >= len) return null;
    if (raw[i] === '}') return null;
    if (raw[i] === ',') { i++; continue; }
    if (raw[i] !== '"') return null;
    i++;
    const keyStart = i;
    while (i < len && raw[i] !== '"') {
      if (raw[i] === '\\') i++;
      i++;
    }
    const key = raw.slice(keyStart, i);
    i++;
    while (i < len && isWS(raw[i])) i++;
    if (i < len && raw[i] === ':') i++;
    while (i < len && isWS(raw[i])) i++;
    const valStart = i;
    i = skipValue(raw, i);
    if (key === 'id') return raw.slice(valStart, i);
  }
  return null;
}

function isValidId(parsed: any, rawLine: string): boolean {
  if (!('id' in parsed)) return false;
  const id = parsed.id;
  if (typeof id === 'string') return true;
  if (typeof id === 'number') {
    const raw = findRawIdValue(rawLine);
    if (raw === null) return false;
    return !raw.includes('.') && !raw.includes('e') && !raw.includes('E');
  }
  return false;
}

// --- Validation ---
function validateArguments(args: any, schema: any): string | null {
  if (args !== undefined) {
    if (args === null || typeof args !== 'object' || Array.isArray(args)) {
      return "arguments must be an object";
    }
  }
  const actualArgs = args || {};
  const props = schema.properties || {};
  const required: string[] = schema.required || [];
  const propNames: string[] = Object.keys(props);

  const argKeys = Object.keys(actualArgs);
  const unknownKeys = argKeys.filter(k => !(k in props));
  if (unknownKeys.length > 0) {
    unknownKeys.sort((a, b) => {
      const ac = [...a];
      const bc = [...b];
      const len = Math.min(ac.length, bc.length);
      for (let i = 0; i < len; i++) {
        const ca = ac[i].codePointAt(0)!;
        const cb = bc[i].codePointAt(0)!;
        if (ca !== cb) return ca - cb;
      }
      return ac.length - bc.length;
    });
    return `unknown argument: ${unknownKeys[0]}`;
  }

  for (const name of propNames) {
    const propSchema = props[name];
    const isRequired = required.includes(name);
    const isPresent = name in actualArgs;
    if (!isPresent) {
      if (isRequired) return `missing required argument: ${name}`;
      continue;
    }
    const value = actualArgs[name];
    if (propSchema.type === 'string') {
      if (typeof value !== 'string') {
        return `argument ${name} must be a string`;
      }
      if (propSchema.minLength && value.length < propSchema.minLength) {
        return `argument ${name} must not be empty`;
      }
    } else if (propSchema.type === 'array') {
      if (!Array.isArray(value)) {
        return `argument ${name} must be an array of integers`;
      }
      for (const item of value) {
        if (typeof item !== 'number' || !Number.isInteger(item)) {
          return `argument ${name} must be an array of integers`;
        }
      }
      if (propSchema.minItems && value.length < propSchema.minItems) {
        return `argument ${name} must not be empty`;
      }
    }
  }
  return null;
}

// --- Helpers ---
function compareByCodePoint(a: string, b: string): number {
  const ac = [...a];
  const bc = [...b];
  const len = Math.min(ac.length, bc.length);
  for (let i = 0; i < len; i++) {
    const ca = ac[i].codePointAt(0)!;
    const cb = bc[i].codePointAt(0)!;
    if (ca !== cb) return ca - cb;
  }
  return ac.length - bc.length;
}

function countWords(text: string): number {
  if (text.length === 0) return 0;
  const parts = text.split(/[\x20\x09\x0A\x0D]+/);
  return parts.filter(p => p.length > 0).length;
}

// --- Handlers ---
function handleInitialize(id: any, params: any): object {
  if (initialized) {
    return { jsonrpc: "2.0", id, error: { code: -32600, message: "Already initialized" } };
  }
  if (!params || typeof params.protocolVersion !== 'string') {
    return { jsonrpc: "2.0", id, error: { code: -32602, message: "Invalid params" } };
  }
  const supported = ["2025-06-18", "2025-03-26", "2024-11-05"];
  const version = supported.includes(params.protocolVersion) ? params.protocolVersion : "2025-06-18";
  initialized = true;
  return {
    jsonrpc: "2.0",
    id,
    result: {
      protocolVersion: version,
      capabilities: { tools: { listChanged: false } },
      serverInfo: { name: "cb2-kv", title: "CB2 key-value server", version: "1.4.2" }
    }
  };
}

function handleToolsCall(id: any, params: any): object {
  if (!params || typeof params.name !== 'string') {
    return { jsonrpc: "2.0", id, error: { code: -32602, message: "Invalid params" } };
  }
  const toolName = params.name;
  const tool = TOOLS.find(t => t.name === toolName);
  if (!tool) {
    return { jsonrpc: "2.0", id, error: { code: -32602, message: `Unknown tool: ${toolName}` } };
  }

  const args = params.arguments;
  const validationError = validateArguments(args, tool.inputSchema);
  if (validationError) {
    return { jsonrpc: "2.0", id, result: { content: [{ type: "text", text: validationError }], isError: true } };
  }

  const actualArgs = args || {};

  switch (toolName) {
    case 'kv_set': {
      const key = actualArgs.key as string;
      const value = actualArgs.value as string;
      const existed = store.has(key);
      store.set(key, value);
      const text = existed ? `updated ${key}` : `created ${key}`;
      return { jsonrpc: "2.0", id, result: { content: [{ type: "text", text }], isError: false } };
    }
    case 'kv_get': {
      const key = actualArgs.key as string;
      if (!store.has(key)) {
        return { jsonrpc: "2.0", id, result: { content: [{ type: "text", text: `key not found: ${key}` }], isError: true } };
      }
      const value = store.get(key)!;
      return { jsonrpc: "2.0", id, result: { content: [{ type: "text", text: value }], isError: false } };
    }
    case 'kv_list': {
      const prefix = (typeof actualArgs.prefix === 'string') ? actualArgs.prefix : '';
      const keys = [...store.keys()].filter(k => k.startsWith(prefix)).sort(compareByCodePoint);
      const structured = { keys, count: keys.length };
      return {
        jsonrpc: "2.0", id,
        result: {
          content: [{ type: "text", text: JSON.stringify(structured) }],
          structuredContent: structured,
          isError: false
        }
      };
    }
    case 'sum': {
      const numbers = actualArgs.numbers as number[];
      const sum = numbers.reduce((a, b) => a + b, 0);
      const structured = { sum, count: numbers.length };
      return {
        jsonrpc: "2.0", id,
        result: {
          content: [{ type: "text", text: JSON.stringify(structured) }],
          structuredContent: structured,
          isError: false
        }
      };
    }
    case 'text_stats': {
      const text = actualArgs.text as string;
      const words = countWords(text);
      const codepoints = [...text].length;
      const utf8Bytes = Buffer.byteLength(text, 'utf8');
      const structured = { words, codepoints, utf8_bytes: utf8Bytes };
      return {
        jsonrpc: "2.0", id,
        result: {
          content: [{ type: "text", text: JSON.stringify(structured) }],
          structuredContent: structured,
          isError: false
        }
      };
    }
    default:
      return { jsonrpc: "2.0", id, error: { code: -32602, message: "Unknown tool" } };
  }
}

// --- Main processing ---
function processLine(line: string): object | null {
  let parsed: any;
  try {
    parsed = JSON.parse(line);
  } catch {
    return { jsonrpc: "2.0", id: null, error: { code: -32700, message: "Parse error" } };
  }

  if (typeof parsed !== 'object' || parsed === null || Array.isArray(parsed)) {
    return { jsonrpc: "2.0", id: null, error: { code: -32600, message: "Invalid Request" } };
  }

  if (!('method' in parsed) && ('result' in parsed || 'error' in parsed)) {
    return null;
  }

  const jsonrpcOk = parsed.jsonrpc === "2.0";
  const methodOk = typeof parsed.method === 'string';
  const hasId = 'id' in parsed;
  const idValid = hasId ? isValidId(parsed, line) : false;
  const idOk = !hasId || idValid;

  if (!jsonrpcOk || !methodOk || !idOk) {
    const id = idValid ? parsed.id : null;
    return { jsonrpc: "2.0", id, error: { code: -32600, message: "Invalid Request" } };
  }

  if (!hasId) return null;

  const id = parsed.id;
  const method: string = parsed.method;
  const params = parsed.params;

  const validMethods = ['initialize', 'ping', 'tools/list', 'tools/call'];
  if (!validMethods.includes(method)) {
    return { jsonrpc: "2.0", id, error: { code: -32601, message: "Method not found" } };
  }

  if ('params' in parsed) {
    if (params === null || typeof params !== 'object' || Array.isArray(params)) {
      return { jsonrpc: "2.0", id, error: { code: -32602, message: "Invalid params" } };
    }
  }

  if (!initialized && method !== 'initialize' && method !== 'ping') {
    return { jsonrpc: "2.0", id, error: { code: -32002, message: "Server not initialized" } };
  }

  switch (method) {
    case 'initialize': return handleInitialize(id, params);
    case 'ping': return { jsonrpc: "2.0", id, result: {} };
    case 'tools/list': return { jsonrpc: "2.0", id, result: { tools: TOOLS } };
    case 'tools/call': return handleToolsCall(id, params);
    default: return { jsonrpc: "2.0", id, error: { code: -32601, message: "Method not found" } };
  }
}

// --- Entry point ---
const input = fs.readFileSync(0, 'utf-8');
const lines = input.split('\n');
const outputLines: string[] = [];

for (const rawLine of lines) {
  const line = rawLine.replace(/\r$/, '');
  if (/^[\s\t\r]*$/.test(line)) continue;
  const response = processLine(line);
  if (response !== null) {
    outputLines.push(JSON.stringify(response));
  }
}

process.stdout.write(outputLines.map(l => l + '\n').join(''));
process.exit(0);

#!/usr/bin/env python3
import sys
import os
import re
import zlib
import base64


def main():
    if len(sys.argv) < 2:
        sys.exit(1)
    directory = sys.argv[1]
    files = sorted([f for f in os.listdir(directory) if f.endswith('.eml')])
    first = True
    for fname in files:
        if not first:
            print()
        first = False
        filepath = os.path.join(directory, fname)
        with open(filepath, 'rb') as f:
            raw = f.read()
        process_message(fname, raw)


def detect_line_break(raw):
    if b'\r\n' in raw:
        return b'\r\n'
    return b'\n'


def split_lines_keep_breaks(data, lb):
    if not data:
        return []
    lines = []
    i = 0
    while i < len(data):
        idx = data.find(lb, i)
        if idx == -1:
            lines.append(data[i:])
            break
        lines.append(data[i:idx + len(lb)])
        i = idx + len(lb)
    return lines


def parse_entity(raw, lb):
    if not raw:
        return {}, b''
    if raw.startswith(lb):
        return {}, raw[len(lb):]
    sep = lb + lb
    idx = raw.find(sep)
    if idx == -1:
        return parse_headers(raw, lb), b''
    headers_raw = raw[:idx]
    body = raw[idx + len(lb):]
    headers = parse_headers(headers_raw, lb)
    return headers, body


def parse_headers(raw, lb):
    if not raw:
        return {}
    lines = raw.split(lb)
    unfolded = []
    for line in lines:
        if line and (line[0:1] == b' ' or line[0:1] == b'\t'):
            if unfolded:
                unfolded[-1] = unfolded[-1] + line
        else:
            unfolded.append(line)
    headers = {}
    for line in unfolded:
        if not line:
            continue
        idx = line.find(b':')
        if idx == -1:
            continue
        name = line[:idx].decode('ascii').lower()
        value = line[idx + 1:].decode('ascii').strip(' \t')
        headers[name] = value
    return headers


def split_params(value):
    parts = []
    current = []
    in_quote = False
    escape_next = False
    for ch in value:
        if escape_next:
            current.append(ch)
            escape_next = False
        elif in_quote:
            current.append(ch)
            if ch == '\\':
                escape_next = True
            elif ch == '"':
                in_quote = False
        else:
            if ch == '"':
                current.append(ch)
                in_quote = True
            elif ch == ';':
                parts.append(''.join(current))
                current = []
            else:
                current.append(ch)
    parts.append(''.join(current))
    return parts


def find_eq(s):
    in_quote = False
    escape_next = False
    for i, ch in enumerate(s):
        if escape_next:
            escape_next = False
        elif in_quote:
            if ch == '\\':
                escape_next = True
            elif ch == '"':
                in_quote = False
        else:
            if ch == '"':
                in_quote = True
            elif ch == '=':
                return i
    return -1


def parse_param_value(val):
    val = val.lstrip(' \t')
    if val.startswith('"'):
        result = []
        i = 1
        while i < len(val):
            if val[i] == '\\' and i + 1 < len(val):
                result.append(val[i + 1])
                i += 2
            elif val[i] == '"':
                break
            else:
                result.append(val[i])
                i += 1
        return ''.join(result)
    else:
        end = len(val)
        for i, ch in enumerate(val):
            if ch in ' \t':
                end = i
                break
        return val[:end]


def parse_content_type(value):
    parts = split_params(value)
    if not parts:
        return ('text', 'plain', {})
    main = parts[0].strip(' \t')
    slash_idx = main.find('/')
    if slash_idx == -1:
        return ('text', 'plain', {})
    type_part = main[:slash_idx].strip(' \t').lower()
    subtype_part = main[slash_idx + 1:].strip(' \t').lower()
    params = {}
    for p in parts[1:]:
        p = p.strip(' \t')
        if not p:
            continue
        eq = find_eq(p)
        if eq == -1:
            continue
        attr = p[:eq].strip(' \t').lower()
        val = p[eq + 1:]
        params[attr] = val
    return (type_part, subtype_part, params)


def parse_content_disposition(value):
    parts = split_params(value)
    if not parts:
        return (None, {})
    disp_type = parts[0].strip(' \t').lower()
    params = {}
    for p in parts[1:]:
        p = p.strip(' \t')
        if not p:
            continue
        eq = find_eq(p)
        if eq == -1:
            continue
        attr = p[:eq].strip(' \t').lower()
        val = p[eq + 1:]
        params[attr] = val
    return (disp_type, params)


def decode_base64_data(data):
    alphabet = set(b'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/')
    filtered = bytearray()
    for b in data:
        if b == ord('='):
            break
        if b in alphabet:
            filtered.append(b)
    remainder = len(filtered) % 4
    if remainder:
        filtered.extend(b'=' * (4 - remainder))
    try:
        return base64.b64decode(bytes(filtered))
    except Exception:
        return b''


def decode_quoted_printable(data, lb):
    lines = split_lines_keep_breaks(data, lb)
    result = bytearray()
    i = 0
    while i < len(lines):
        line = lines[i]
        if line.endswith(lb):
            content = line[:-len(lb)]
            has_break = True
        else:
            content = line
            has_break = False
        while content and content[-1:] in (b' ', b'\t'):
            content = content[:-1]
        if content.endswith(b'=') and has_break:
            content = content[:-1]
            result.extend(content)
            i += 1
        else:
            result.extend(content)
            if has_break:
                result.extend(lb)
            i += 1
    decoded = bytearray()
    i = 0
    while i < len(result):
        if result[i:i + 1] == b'=' and i + 2 < len(result):
            hex_str = result[i + 1:i + 3]
            try:
                byte_val = int(hex_str, 16)
                decoded.append(byte_val)
                i += 3
            except ValueError:
                decoded.append(ord('='))
                i += 1
        else:
            decoded.append(result[i])
            i += 1
    return bytes(decoded)


def decode_cte(body, encoding, lb):
    encoding = encoding.lower().strip()
    if encoding in ('7bit', '8bit', 'binary'):
        return body
    elif encoding == 'base64':
        return decode_base64_data(body)
    elif encoding == 'quoted-printable':
        return decode_quoted_printable(body, lb)
    else:
        return body


CP1252_MAP = {
    0x80: 0x20AC, 0x81: 0x0081, 0x82: 0x201A, 0x83: 0x0192,
    0x84: 0x201E, 0x85: 0x2026, 0x86: 0x2020, 0x87: 0x2021,
    0x88: 0x02C6, 0x89: 0x2030, 0x8A: 0x0160, 0x8B: 0x2039,
    0x8C: 0x0152, 0x8D: 0x008D, 0x8E: 0x017D, 0x8F: 0x008F,
    0x90: 0x0090, 0x91: 0x2018, 0x92: 0x2019, 0x93: 0x201C,
    0x94: 0x201D, 0x95: 0x2022, 0x96: 0x2013, 0x97: 0x2014,
    0x98: 0x02DC, 0x99: 0x2122, 0x9A: 0x0161, 0x9B: 0x203A,
    0x9C: 0x0153, 0x9D: 0x009D, 0x9E: 0x017E, 0x9F: 0x0178,
}


def decode_charset(data, charset):
    charset = charset.lower().strip()
    if charset in ('us-ascii', 'ascii'):
        return data.decode('latin-1')
    elif charset == 'utf-8':
        return data.decode('utf-8')
    elif charset == 'iso-8859-1':
        return data.decode('latin-1')
    elif charset == 'windows-1252':
        result = []
        for b in data:
            if 0x80 <= b <= 0x9F:
                result.append(chr(CP1252_MAP[b]))
            else:
                result.append(chr(b))
        return ''.join(result)
    else:
        return data.decode('latin-1')


def decode_rfc2047(value):
    pattern = re.compile(r'=\?([^ \t?]+)\?([BbQq])\?([^ \t?]*)\?=')
    matches = list(pattern.finditer(value))
    if not matches:
        return value
    groups = []
    current_group = [matches[0]]
    for i in range(1, len(matches)):
        prev = current_group[-1]
        curr = matches[i]
        between = value[prev.end():curr.start()]
        if all(c in ' \t' for c in between):
            prev_charset = prev.group(1).lower().split('*')[0]
            curr_charset = curr.group(1).lower().split('*')[0]
            if prev_charset == curr_charset:
                current_group.append(curr)
            else:
                groups.append(current_group)
                current_group = [curr]
        else:
            groups.append(current_group)
            current_group = [curr]
    groups.append(current_group)
    result = []
    pos = 0
    for group in groups:
        result.append(value[pos:group[0].start()])
        decoded = decode_encoded_word_run(group)
        result.append(decoded)
        pos = group[-1].end()
    result.append(value[pos:])
    return ''.join(result)


def decode_encoded_word_run(run):
    charset = run[0].group(1).lower().split('*')[0]
    all_bytes = bytearray()
    for m in run:
        encoding = m.group(2).upper()
        encoded_text = m.group(3)
        if encoding == 'B':
            try:
                s = encoded_text
                while len(s) % 4 != 0:
                    s += '='
                all_bytes.extend(base64.b64decode(s))
            except Exception:
                pass
        elif encoding == 'Q':
            i = 0
            while i < len(encoded_text):
                if encoded_text[i] == '_':
                    all_bytes.append(0x20)
                    i += 1
                elif encoded_text[i] == '=' and i + 2 < len(encoded_text):
                    hex_str = encoded_text[i + 1:i + 3]
                    try:
                        all_bytes.append(int(hex_str, 16))
                        i += 3
                    except ValueError:
                        all_bytes.append(ord('='))
                        i += 1
                else:
                    all_bytes.append(ord(encoded_text[i]))
                    i += 1
    return decode_charset(bytes(all_bytes), charset)


def percent_decode(s):
    result = bytearray()
    i = 0
    while i < len(s):
        if s[i] == '%' and i + 2 < len(s):
            hex_str = s[i + 1:i + 3]
            try:
                result.append(int(hex_str, 16))
                i += 3
            except ValueError:
                result.append(ord('%'))
                i += 1
        else:
            result.append(ord(s[i]))
            i += 1
    return bytes(result)


def decode_rfc2231_value(params, attr_name):
    key = attr_name + '*'
    if key in params:
        val = params[key].strip(' \t')
        parts = val.split("'", 2)
        if len(parts) == 3:
            charset, language, encoded_value = parts
            decoded_bytes = percent_decode(encoded_value)
            if charset:
                return decode_charset(decoded_bytes, charset)
            else:
                return decoded_bytes.decode('ascii')
        else:
            decoded_bytes = percent_decode(val)
            return decoded_bytes.decode('ascii')

    segments = {}
    for pkey in params:
        if pkey.startswith(attr_name + '*'):
            rest = pkey[len(attr_name) + 1:]
            if not rest:
                continue
            if rest.endswith('*'):
                n_str = rest[:-1]
                is_encoded = True
            else:
                n_str = rest
                is_encoded = False
            try:
                n = int(n_str)
            except ValueError:
                continue
            segments[n] = (params[pkey], is_encoded)

    if segments:
        charset = None
        all_bytes = bytearray()
        for n in sorted(segments.keys()):
            val, is_enc = segments[n]
            val = val.strip(' \t')
            if is_enc:
                if n == 0:
                    parts = val.split("'", 2)
                    if len(parts) == 3:
                        charset = parts[0]
                        val = parts[2]
                    elif len(parts) == 2:
                        charset = parts[0]
                        val = parts[1]
                decoded = percent_decode(val)
                all_bytes.extend(decoded)
            else:
                val_parsed = parse_param_value(val)
                all_bytes.extend(val_parsed.encode('latin-1'))
        if charset:
            return decode_charset(bytes(all_bytes), charset)
        else:
            return bytes(all_bytes).decode('ascii')
    return None


def get_file_name(headers):
    cd_value = headers.get('content-disposition')
    if cd_value:
        _, cd_params = parse_content_disposition(cd_value)
        result = decode_rfc2231_value(cd_params, 'filename')
        if result is not None:
            return decode_rfc2047(result)
        if 'filename' in cd_params:
            return decode_rfc2047(parse_param_value(cd_params['filename']))
    ct_value = headers.get('content-type')
    if ct_value:
        _, _, ct_params = parse_content_type(ct_value)
        result = decode_rfc2231_value(ct_params, 'name')
        if result is not None:
            return decode_rfc2047(result)
        if 'name' in ct_params:
            return decode_rfc2047(parse_param_value(ct_params['name']))
    return None


def is_delimiter(line_content, boundary):
    delim = '--' + boundary
    close = '--' + boundary + '--'
    if line_content.startswith(close):
        rest = line_content[len(close):]
        if all(c in ' \t' for c in rest):
            return 'close'
    if line_content.startswith(delim):
        rest = line_content[len(delim):]
        if all(c in ' \t' for c in rest):
            return 'delim'
    return None


def parse_multipart(body, boundary, lb):
    lines = split_lines_keep_breaks(body, lb)
    delim_indices = []
    for i, line in enumerate(lines):
        content = line
        if content.endswith(lb):
            content = content[:-len(lb)]
        content = content.rstrip(b'\r\n')
        try:
            content_str = content.decode('ascii')
        except UnicodeDecodeError:
            content_str = ''
        dtype = is_delimiter(content_str, boundary)
        if dtype:
            delim_indices.append((i, dtype))
    parts = []
    for i in range(len(delim_indices) - 1):
        j = delim_indices[i + 1][0]
        part_lines = lines[i + 1:j]
        if part_lines:
            last = part_lines[-1]
            if last.endswith(lb):
                part_lines[-1] = last[:-len(lb)]
        part_data = b''.join(part_lines)
        parts.append(part_data)
    return parts


def quoted_string(s):
    result = ['"']
    for ch in s:
        if ch == '\\':
            result.append('\\\\')
        elif ch == '"':
            result.append('\\"')
        elif ch == '\n':
            result.append('\\n')
        elif ch == '\t':
            result.append('\\t')
        elif ord(ch) < 0x20 or (0x7F <= ord(ch) <= 0x9F):
            result.append('\\u{:04x}'.format(ord(ch)))
        else:
            result.append(ch)
    result.append('"')
    return ''.join(result)


def process_entity(headers, body, lb, indent, output):
    ct_value = headers.get('content-type', 'text/plain')
    type_part, subtype, ct_params = parse_content_type(ct_value)
    cte = headers.get('content-transfer-encoding', '7bit').lower().strip()
    cd_value = headers.get('content-disposition')
    disp_type = None
    if cd_value:
        disp_type, _ = parse_content_disposition(cd_value)

    if type_part == 'multipart':
        boundary = ct_params.get('boundary', '')
        boundary = parse_param_value(boundary)
        parts = parse_multipart(body, boundary, lb)
        output.append('  ' * indent + f'multipart/{subtype} parts={len(parts)}')
        for part_data in parts:
            part_headers, part_body = parse_entity(part_data, lb)
            process_entity(part_headers, part_body, lb, indent + 1, output)
    elif type_part == 'text' and disp_type != 'attachment':
        charset_raw = ct_params.get('charset', 'us-ascii')
        charset = parse_param_value(charset_raw).lower()
        decoded_bytes = decode_cte(body, cte, lb)
        text = decode_charset(decoded_bytes, charset)
        text = text.replace('\r\n', '\n').replace('\r', '\n')
        chars = len(text)
        output.append('  ' * indent + f'text/{subtype} charset={charset} cte={cte} chars={chars}')
        output.append('  ' * (indent + 1) + quoted_string(text))
    else:
        decoded_bytes = decode_cte(body, cte, lb)
        size = len(decoded_bytes)
        crc = zlib.crc32(decoded_bytes) & 0xFFFFFFFF
        name = get_file_name(headers)
        name_str = quoted_string(name) if name is not None else '-'
        disp_str = disp_type if disp_type else '-'
        output.append(
            '  ' * indent +
            f'{type_part}/{subtype} cte={cte} disposition={disp_str} name={name_str} size={size} crc32={crc:08x}'
        )


def process_message(fname, raw):
    lb = detect_line_break(raw)
    headers, body = parse_entity(raw, lb)
    print(f'== {fname}')
    from_val = headers.get('from')
    subject_val = headers.get('subject')
    if from_val:
        print(f'From: {quoted_string(decode_rfc2047(from_val))}')
    else:
        print('From: -')
    if subject_val:
        print(f'Subject: {quoted_string(decode_rfc2047(subject_val))}')
    else:
        print('Subject: -')
    output = []
    process_entity(headers, body, lb, 0, output)
    for line in output:
        print(line)


