import java.io.*;
import java.nio.file.*;
import java.util.*;
import java.util.zip.CRC32;

public class Main {
    static String lineEnd;
    static byte[] leBytes;

    public static void main(String[] args) throws Exception {
        Path dir = Paths.get(args[0]);
        List<Path> files = new ArrayList<>();
        try (DirectoryStream<Path> ds = Files.newDirectoryStream(dir)) {
            for (Path p : ds) {
                if (Files.isRegularFile(p) && p.getFileName().toString().endsWith(".eml")) {
                    files.add(p);
                }
            }
        }
        files.sort(Comparator.comparing(p -> p.getFileName().toString()));

        boolean first = true;
        for (Path f : files) {
            if (!first) System.out.println();
            first = false;
            processFile(f);
        }
    }

    static void processFile(Path file) throws Exception {
        byte[] data = Files.readAllBytes(file);
        lineEnd = detectLineEnding(data);
        leBytes = lineEnd.getBytes("US-ASCII");

        System.out.println("== " + file.getFileName().toString());

        Entity msg = parseEntity(data);

        String from = msg.headers.get("from");
        String subject = msg.headers.get("subject");

        System.out.println("From: " + (from != null ? quotedString(decodeEncodedWords(from)) : "-"));
        System.out.println("Subject: " + (subject != null ? quotedString(decodeEncodedWords(subject)) : "-"));

        printEntity(msg, 0);
    }

    // --- Entity ---
    static class Entity {
        Map<String, String> headers = new LinkedHashMap<>();
        byte[] body = new byte[0];
        List<Entity> parts; // null if not multipart
        String type = "text", subtype = "plain";
        String charset = "us-ascii";
        String cte = "7bit";
        String dispType; // null if no Content-Disposition
        Map<String, String> ctParams = new LinkedHashMap<>();
        Map<String, String> cdParams = new LinkedHashMap<>();
    }

    // --- Line ending detection ---
    static String detectLineEnding(byte[] data) {
        for (int i = 0; i < data.length; i++) {
            if (data[i] == '\n') {
                if (i > 0 && data[i - 1] == '\r') return "\r\n";
                return "\n";
            }
        }
        return "\n";
    }

    // --- Entity parsing ---
    static Entity parseEntity(byte[] data) {
        Entity e = new Entity();

        int sepPos = findFirstEmptyLine(data);
        if (sepPos < 0) {
            e.headers = parseHeaders(data);
            e.body = new byte[0];
        } else {
            byte[] headerData = Arrays.copyOfRange(data, 0, sepPos);
            e.headers = parseHeaders(headerData);
            int bodyStart = sepPos + leBytes.length;
            if (bodyStart <= data.length)
                e.body = Arrays.copyOfRange(data, bodyStart, data.length);
            else
                e.body = new byte[0];
        }

        // Parse Content-Type
        String ctVal = e.headers.get("content-type");
        if (ctVal != null) {
            ParsedHeader ph = parseStructured(ctVal);
            e.type = ph.type.toLowerCase();
            e.subtype = ph.subtype.toLowerCase();
            e.ctParams = ph.params;
            String cs = ph.params.get("charset");
            if (cs != null) e.charset = cs.toLowerCase();
        }

        // Parse Content-Transfer-Encoding
        String cteVal = e.headers.get("content-transfer-encoding");
        if (cteVal != null) e.cte = cteVal.trim().toLowerCase();

        // Parse Content-Disposition
        String cdVal = e.headers.get("content-disposition");
        if (cdVal != null) {
            ParsedHeader ph = parseDisposition(cdVal);
            e.dispType = ph.type.isEmpty() ? null : ph.type.toLowerCase();
            e.cdParams = ph.params;
        }

        // Multipart
        if (e.type.equals("multipart") && !"7bit".equals(e.cte) || e.type.equals("multipart")) {
            String boundary = e.ctParams.get("boundary");
            if (boundary != null && !boundary.isEmpty()) {
                e.parts = parseMultipart(e.body, boundary);
            }
        }

        return e;
    }

    // --- Find first empty line ---
    static int findFirstEmptyLine(byte[] data) {
        int pos = 0;
        while (pos <= data.length) {
            int idx = indexOf(data, leBytes, pos);
            int lineEndPos;
            if (idx < 0) {
                lineEndPos = data.length;
            } else {
                lineEndPos = idx;
            }
            if (lineEndPos == pos) {
                return pos;
            }
            if (idx < 0) break;
            pos = idx + leBytes.length;
        }
        return -1;
    }

    // --- Header parsing ---
    static Map<String, String> parseHeaders(byte[] data) {
        Map<String, String> headers = new LinkedHashMap<>();
        if (data.length == 0) return headers;

        List<byte[]> rawLines = splitBytes(data, leBytes);
        List<String> unfolded = new ArrayList<>();
        for (byte[] raw : rawLines) {
            String line = new String(raw, java.nio.charset.StandardCharsets.US_ASCII);
            if (line.isEmpty()) continue;
            if (line.charAt(0) == ' ' || line.charAt(0) == '\t') {
                if (!unfolded.isEmpty()) {
                    unfolded.set(unfolded.size() - 1, unfolded.get(unfolded.size() - 1) + line);
                }
            } else {
                unfolded.add(line);
            }
        }

        for (String line : unfolded) {
            int colon = line.indexOf(':');
            if (colon < 0) continue;
            String name = line.substring(0, colon).trim().toLowerCase();
            String value = line.substring(colon + 1);
            value = stripSpacesTabs(value);
            headers.put(name, value);
        }
        return headers;
    }

    static String stripSpacesTabs(String s) {
        int start = 0, end = s.length();
        while (start < end && (s.charAt(start) == ' ' || s.charAt(start) == '\t')) start++;
        while (end > start && (s.charAt(end - 1) == ' ' || s.charAt(end - 1) == '\t')) end--;
        return s.substring(start, end);
    }

    // --- Structured header parsing ---
    static class ParsedHeader {
        String type = "";
        String subtype = "";
        Map<String, String> params = new LinkedHashMap<>();
    }

    static int pPos;
    static String pInput;

    static ParsedHeader parseStructured(String value) {
        ParsedHeader ph = new ParsedHeader();
        pPos = 0;
        pInput = value;
        skipSpaces();
        ph.type = readToken().toLowerCase();
        skipSpaces();
        if (pPos < pInput.length() && pInput.charAt(pPos) == '/') {
            pPos++;
            skipSpaces();
            ph.subtype = readToken().toLowerCase();
        }
        parseParams(ph.params);
        return ph;
    }

    static ParsedHeader parseDisposition(String value) {
        ParsedHeader ph = new ParsedHeader();
        pPos = 0;
        pInput = value;
        skipSpaces();
        ph.type = readToken().toLowerCase();
        parseParams(ph.params);
        return ph;
    }

    static void parseParams(Map<String, String> params) {
        while (pPos < pInput.length()) {
            skipSpaces();
            if (pPos >= pInput.length()) break;
            if (pInput.charAt(pPos) != ';') break;
            pPos++;
            skipSpaces();
            String attr = readToken().toLowerCase();
            if (attr.isEmpty()) break;
            skipSpaces();
            if (pPos < pInput.length() && pInput.charAt(pPos) == '=') {
                pPos++;
                String val = readValue();
                params.put(attr, val);
            } else {
                params.put(attr, "");
            }
        }
    }

    static void skipSpaces() {
        while (pPos < pInput.length() && (pInput.charAt(pPos) == ' ' || pInput.charAt(pPos) == '\t'))
            pPos++;
    }

    static String readToken() {
        int start = pPos;
        while (pPos < pInput.length()) {
            char c = pInput.charAt(pPos);
            if (c == ' ' || c == '\t' || c == ';' || c == '=' || c == '/') break;
            pPos++;
        }
        return pInput.substring(start, pPos);
    }

    static String readValue() {
        skipSpaces();
        if (pPos < pInput.length() && pInput.charAt(pPos) == '"') {
            return readQuotedString();
        } else {
            return readToken();
        }
    }

    static String readQuotedString() {
        pPos++; // skip opening "
        StringBuilder sb = new StringBuilder();
        while (pPos < pInput.length()) {
            char c = pInput.charAt(pPos);
            if (c == '\\') {
                pPos++;
                if (pPos < pInput.length()) {
                    sb.append(pInput.charAt(pPos));
                    pPos++;
                }
            } else if (c == '"') {
                pPos++;
                break;
            } else {
                sb.append(c);
                pPos++;
            }
        }
        return sb.toString();
    }

    // --- Multipart parsing ---
    static List<Entity> parseMultipart(byte[] body, String boundary) {
        List<byte[]> lines = splitBytes(body, leBytes);
        byte[] delim = ("--" + boundary).getBytes(java.nio.charset.StandardCharsets.US_ASCII);
        byte[] closeDelim = ("--" + boundary + "--").getBytes(java.nio.charset.StandardCharsets.US_ASCII);

        List<Integer> delimIndices = new ArrayList<>();
        List<Boolean> isClose = new ArrayList<>();
        for (int i = 0; i < lines.size(); i++) {
            if (isDelimLine(lines.get(i), closeDelim)) {
                delimIndices.add(i);
                isClose.add(true);
            } else if (isDelimLine(lines.get(i), delim)) {
                delimIndices.add(i);
                isClose.add(false);
            }
        }

        int firstDelim = -1;
        int closeDelimIdx = -1;
        for (int i = 0; i < delimIndices.size(); i++) {
            if (firstDelim < 0) firstDelim = i;
            if (isClose.get(i)) {
                closeDelimIdx = i;
                break;
            }
        }

        List<Entity> parts = new ArrayList<>();
        if (firstDelim < 0 || closeDelimIdx < 0) return parts;

        for (int i = firstDelim; i < closeDelimIdx; i++) {
            int start = delimIndices.get(i) + 1;
            int end = delimIndices.get(i + 1);
            List<byte[]> partLines = new ArrayList<>();
            for (int j = start; j < end; j++) {
                partLines.add(lines.get(j));
            }
            byte[] partData = joinBytes(partLines, leBytes);
            parts.add(parseEntity(partData));
        }
        return parts;
    }

    static boolean isDelimLine(byte[] line, byte[] prefix) {
        if (line.length < prefix.length) return false;
        for (int i = 0; i < prefix.length; i++) {
            if (line[i] != prefix[i]) return false;
        }
        for (int i = prefix.length; i < line.length; i++) {
            if (line[i] != ' ' && line[i] != '\t') return false;
        }
        return true;
    }

    // --- Transfer decoding ---
    static byte[] transferDecode(byte[] data, String encoding) {
        switch (encoding) {
            case "base64":
                return base64DecodeBytes(data);
            case "quoted-printable":
                return qpDecode(data);
            default:
                return data;
        }
    }

    static byte[] base64DecodeBytes(byte[] data) {
        StringBuilder sb = new StringBuilder();
        for (byte b : data) {
            char c = (char) (b & 0xFF);
            if (c == '=') break;
            if ((c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z') ||
                (c >= '0' && c <= '9') || c == '+' || c == '/') {
                sb.append(c);
            }
        }
        return base64DecodeString(sb.toString());
    }

    static byte[] base64DecodeString(String s) {
        int len = s.length();
        int outLen = len * 3 / 4;
        byte[] result = new byte[outLen + 3];
        int pos = 0;
        int i = 0;
        while (i < len) {
            int b0 = b64val(s.charAt(i++));
            int b1 = i < len ? b64val(s.charAt(i++)) : 0;
            int b2 = i < len ? b64val(s.charAt(i++)) : 0;
            int b3 = i < len ? b64val(s.charAt(i++)) : 0;
            int val = (b0 << 18) | (b1 << 12) | (b2 << 6) | b3;
            result[pos++] = (byte) ((val >> 16) & 0xFF);
            if (pos <= outLen) result[pos++] = (byte) ((val >> 8) & 0xFF);
            if (pos <= outLen) result[pos++] = (byte) (val & 0xFF);
        }
        // Trim to actual length
        int actual = len * 3 / 4;
        if (len % 4 == 2) actual = (len / 4) * 3 + 1;
        else if (len % 4 == 3) actual = (len / 4) * 3 + 2;
        else if (len % 4 == 1) actual = (len / 4) * 3; // malformed
        return Arrays.copyOf(result, Math.min(pos, actual));
    }

    static int b64val(char c) {
        if (c >= 'A' && c <= 'Z') return c - 'A';
        if (c >= 'a' && c <= 'z') return c - 'a' + 26;
        if (c >= '0' && c <= '9') return c - '0' + 52;
        if (c == '+') return 62;
        if (c == '/') return 63;
        return 0;
    }

    static byte[] qpDecode(byte[] data) {
        List<byte[]> lines = splitBytes(data, leBytes);

        // Remove trailing spaces/tabs from each line
        for (int i = 0; i < lines.size(); i++) {
            byte[] line = lines.get(i);
            int end = line.length;
            while (end > 0 && (line[end - 1] == ' ' || line[end - 1] == '\t')) end--;
            lines.set(i, Arrays.copyOf(line, end));
        }

        // Handle soft line breaks
        ByteArrayOutputStream joined = new ByteArrayOutputStream();
        for (int i = 0; i < lines.size(); i++) {
            byte[] line = lines.get(i);
            if (line.length > 0 && line[line.length - 1] == '=' && i < lines.size() - 1) {
                joined.write(line, 0, line.length - 1);
            } else {
                joined.write(line, 0, line.length);
                if (i < lines.size() - 1) {
                    joined.write(leBytes, 0, leBytes.length);
                }
            }
        }

        // Process =XY
        byte[] jb = joined.toByteArray();
        ByteArrayOutputStream result = new ByteArrayOutputStream();
        int i = 0;
        while (i < jb.length) {
            if (jb[i] == '=' && i + 2 < jb.length && isHex(jb[i + 1]) && isHex(jb[i + 2])) {
                int val = (hexVal(jb[i + 1]) << 4) | hexVal(jb[i + 2]);
                result.write(val);
                i += 3;
            } else {
                result.write(jb[i]);
                i++;
            }
        }
        return result.toByteArray();
    }

    // --- Charset decoding ---
    static final int[] CP1252_MAP = {
        0x20AC, 0x0081, 0x201A, 0x0192, 0x201E, 0x2026, 0x2020, 0x2021,
        0x02C6, 0x2030, 0x0160, 0x2039, 0x0152, 0x008D, 0x017D, 0x008F,
        0x0090, 0x2018, 0x2019, 0x201C, 0x201D, 0x2022, 0x2013, 0x2014,
        0x02DC, 0x2122, 0x0161, 0x203A, 0x0153, 0x009D, 0x017E, 0x0178
    };

    static String decodeCharset(byte[] data, String charset) {
        charset = charset.toLowerCase();
        int star = charset.indexOf('*');
        if (star >= 0) charset = charset.substring(0, star);

        switch (charset) {
            case "us-ascii":
            case "ascii":
            case "iso-8859-1":
            case "latin1":
            case "iso8859-1":
            case "iso_8859-1":
                return new String(data, java.nio.charset.StandardCharsets.ISO_8859_1);
            case "utf-8":
            case "utf8":
                return new String(data, java.nio.charset.StandardCharsets.UTF_8);
            case "windows-1252":
            case "cp1252":
                return decodeCP1252(data);
            default:
                try {
                    return new String(data, java.nio.charset.Charset.forName(charset));
                } catch (Exception e) {
                    return new String(data, java.nio.charset.StandardCharsets.ISO_8859_1);
                }
        }
    }

    static String decodeCP1252(byte[] data) {
        char[] result = new char[data.length];
        for (int i = 0; i < data.length; i++) {
            int b = data[i] & 0xFF;
            if (b >= 0x80 && b <= 0x9F) {
                result[i] = (char) CP1252_MAP[b - 0x80];
            } else {
                result[i] = (char) b;
            }
        }
        return new String(result);
    }

    // --- RFC 2047 Encoded Words ---
    static String decodeEncodedWords(String text) {
        if (text == null || !text.contains("=?")) return text;

        List<EncWord> words = findEncodedWords(text);
        if (words.isEmpty()) return text;

        // Group into adjacency groups
        List<List<EncWord>> groups = new ArrayList<>();
        List<EncWord> cur = new ArrayList<>();
        cur.add(words.get(0));
        for (int i = 1; i < words.size(); i++) {
            boolean adj = true;
            for (int k = words.get(i - 1).end; k < words.get(i).start; k++) {
                if (text.charAt(k) != ' ' && text.charAt(k) != '\t') {
                    adj = false;
                    break;
                }
            }
            if (adj) {
                cur.add(words.get(i));
            } else {
                groups.add(cur);
                cur = new ArrayList<>();
                cur.add(words.get(i));
            }
        }
        groups.add(cur);

        StringBuilder result = new StringBuilder();
        int lastEnd = 0;

        for (List<EncWord> group : groups) {
            result.append(text, lastEnd, group.get(0).start);

            int gi = 0;
            while (gi < group.size()) {
                String cs = normCharset(group.get(gi).charset);
                ByteArrayOutputStream baos = new ByteArrayOutputStream();
                int gj = gi;
                while (gj < group.size() && normCharset(group.get(gj).charset).equals(cs)) {
                    byte[] bytes = decodeWordBytes(group.get(gj).encoding, group.get(gj).encText);
                    baos.write(bytes, 0, bytes.length);
                    gj++;
                }
                result.append(decodeCharset(baos.toByteArray(), cs));
                gi = gj;
            }

            lastEnd = group.get(group.size() - 1).end;
        }

        result.append(text, lastEnd, text.length());
        return result.toString();
    }

    static class EncWord {
        int start, end;
        String charset, encoding, encText;
    }

    static List<EncWord> findEncodedWords(String text) {
        List<EncWord> words = new ArrayList<>();
        int i = 0;
        while (i < text.length()) {
            int pos = text.indexOf("=?", i);
            if (pos < 0) break;

            int q1 = pos + 2;
            int csStart = q1;
            int csEnd = csStart;
            while (csEnd < text.length() && text.charAt(csEnd) != '?' && text.charAt(csEnd) != ' ' && text.charAt(csEnd) != '\t')
                csEnd++;
            if (csEnd == csStart || csEnd >= text.length() || text.charAt(csEnd) != '?') {
                i = pos + 2;
                continue;
            }

            int encPos = csEnd + 1;
            if (encPos >= text.length()) { i = pos + 2; continue; }
            char enc = text.charAt(encPos);
            if (enc != 'B' && enc != 'b' && enc != 'Q' && enc != 'q') {
                i = pos + 2;
                continue;
            }

            int encEnd = encPos + 1;
            if (encEnd >= text.length() || text.charAt(encEnd) != '?') {
                i = pos + 2;
                continue;
            }

            int tStart = encEnd + 1;
            int tEnd = tStart;
            while (tEnd < text.length() && text.charAt(tEnd) != '?' && text.charAt(tEnd) != ' ' && text.charAt(tEnd) != '\t')
                tEnd++;
            if (tEnd >= text.length() || text.charAt(tEnd) != '?' || tEnd + 1 >= text.length() || text.charAt(tEnd + 1) != '=') {
                i = pos + 2;
                continue;
            }

            int end = tEnd + 2;
            EncWord ew = new EncWord();
            ew.start = pos;
            ew.end = end;
            ew.charset = text.substring(csStart, csEnd);
            ew.encoding = String.valueOf(enc);
            ew.encText = text.substring(tStart, tEnd);
            words.add(ew);
            i = end;
        }
        return words;
    }

    static String normCharset(String cs) {
        cs = cs.toLowerCase();
        int star = cs.indexOf('*');
        if (star >= 0) cs = cs.substring(0, star);
        return cs;
    }

    static byte[] decodeWordBytes(String encoding, String encText) {
        if (encoding.equalsIgnoreCase("B")) {
            return base64DecodeString(encText);
        } else {
            ByteArrayOutputStream baos = new ByteArrayOutputStream();
            int i = 0;
            while (i < encText.length()) {
                char c = encText.charAt(i);
                if (c == '_') {
                    baos.write(0x20);
                    i++;
                } else if (c == '=' && i + 2 < encText.length()) {
                    char h1 = encText.charAt(i + 1);
                    char h2 = encText.charAt(i + 2);
                    if (isHexChar(h1) && isHexChar(h2)) {
                        baos.write((hexValChar(h1) << 4) | hexValChar(h2));
                        i += 3;
                    } else {
                        baos.write('=');
                        i++;
                    }
                } else {
                    baos.write(c);
                    i++;
                }
            }
            return baos.toByteArray();
        }
    }

    // --- RFC 2231 ---
    static String getFileName(Map<String, String> cdParams, Map<String, String> ctParams) {
        String r = getRfc2231(cdParams, "filename");
        if (r != null) return r;
        r = getPlainParam(cdParams, "filename");
        if (r != null) return r;
        r = getRfc2231(ctParams, "name");
        if (r != null) return r;
        r = getPlainParam(ctParams, "name");
        if (r != null) return r;
        return null;
    }

    static String getPlainParam(Map<String, String> params, String attr) {
        String val = params.get(attr);
        if (val == null) return null;
        return decodeEncodedWords(val);
    }

    static String getRfc2231(Map<String, String> params, String attr) {
        TreeMap<Integer, Object[]> segs = new TreeMap<>(); // num -> [value, percentEncoded]

        String single = params.get(attr + "*");
        if (single != null) {
            segs.put(0, new Object[]{single, true});
        }

        for (String key : params.keySet()) {
            if (key.equals(attr + "*")) continue;
            if (key.startsWith(attr + "*")) {
                String rest = key.substring(attr.length() + 1);
                boolean pe = rest.endsWith("*");
                String numStr = pe ? rest.substring(0, rest.length() - 1) : rest;
                if (numStr.matches("\\d+")) {
                    int num = Integer.parseInt(numStr);
                    segs.put(num, new Object[]{params.get(key), pe});
                }
            }
        }

        if (segs.isEmpty()) return null;

        String charset = null;
        if (segs.containsKey(0) && (Boolean) segs.get(0)[1]) {
            String val = (String) segs.get(0)[0];
            int q1 = val.indexOf('\'');
            if (q1 >= 0) {
                int q2 = val.indexOf('\'', q1 + 1);
                if (q2 >= 0) {
                    charset = val.substring(0, q1);
                    segs.put(0, new Object[]{val.substring(q2 + 1), true});
                }
            }
        }

        ByteArrayOutputStream baos = new ByteArrayOutputStream();
        for (Map.Entry<Integer, Object[]> entry : segs.entrySet()) {
            String val = (String) entry.getValue()[0];
            boolean pe = (Boolean) entry.getValue()[1];
            if (pe) {
                byte[] decoded = percentDecode(val);
                baos.write(decoded, 0, decoded.length);
            } else {
                byte[] bytes = val.getBytes(java.nio.charset.StandardCharsets.US_ASCII);
                baos.write(bytes, 0, bytes.length);
            }
        }

        String cs = (charset != null && !charset.isEmpty()) ? charset : "us-ascii";
        return decodeCharset(baos.toByteArray(), cs);
    }

    static byte[] percentDecode(String s) {
        ByteArrayOutputStream baos = new ByteArrayOutputStream();
        int i = 0;
        while (i < s.length()) {
            char c = s.charAt(i);
            if (c == '%' && i + 2 < s.length()) {
                char h1 = s.charAt(i + 1);
                char h2 = s.charAt(i + 2);
                if (isHexChar(h1) && isHexChar(h2)) {
                    baos.write((hexValChar(h1) << 4) | hexValChar(h2));
                    i += 3;
                } else {
                    baos.write(c);
                    i++;
                }
            } else {
                baos.write(c);
                i++;
            }
        }
        return baos.toByteArray();
    }

    // --- Output ---
    static void printEntity(Entity e, int indent) {
        String prefix = "  ".repeat(indent);

        if (e.parts != null) {
            System.out.println(prefix + "multipart/" + e.subtype + " parts=" + e.parts.size());
            for (Entity part : e.parts) {
                printEntity(part, indent + 1);
            }
        } else if (e.type.equals("text") && !"attachment".equals(e.dispType)) {
            byte[] decoded = transferDecode(e.body, e.cte);
            String text = decodeCharset(decoded, e.charset);
            text = text.replace("\r\n", "\n").replace("\r", "\n");
            int chars = text.codePointCount(0, text.length());
            System.out.println(prefix + "text/" + e.subtype + " charset=" + e.charset + " cte=" + e.cte + " chars=" + chars);
            System.out.println("  ".repeat(indent + 1) + quotedString(text));
        } else {
            byte[] decoded = transferDecode(e.body, e.cte);
            String name = getFileName(e.cdParams, e.ctParams);
            CRC32 crc = new CRC32();
            crc.update(decoded);
            String crcHex = String.format("%08x", crc.getValue());
            String disp = e.dispType != null ? e.dispType : "-";
            String nameStr = name != null ? quotedString(name) : "-";
            System.out.println(prefix + e.type + "/" + e.subtype + " cte=" + e.cte +
                    " disposition=" + disp + " name=" + nameStr +
                    " size=" + decoded.length + " crc32=" + crcHex);
        }
    }

    static String quotedString(String s) {
        StringBuilder sb = new StringBuilder();
        sb.append('"');
        for (int i = 0; i < s.length(); ) {
            int cp = s.codePointAt(i);
            if (cp == '\\') sb.append("\\\\");
            else if (cp == '"') sb.append("\\\"");
            else if (cp == '\n') sb.append("\\n");
            else if (cp == '\t') sb.append("\\t");
            else if (cp < 0x20 || (cp >= 0x7F && cp <= 0x9F)) {
                sb.append(String.format("\\u%04x", cp));
            } else {
                sb.appendCodePoint(cp);
            }
            i += Character.charCount(cp);
        }
        sb.append('"');
        return sb.toString();
    }

    // --- Utilities ---
    static List<byte[]> splitBytes(byte[] data, byte[] le) {
        List<byte[]> lines = new ArrayList<>();
        int start = 0;
        while (start < data.length) {
            int idx = indexOf(data, le, start);
            if (idx < 0) {
                lines.add(Arrays.copyOfRange(data, start, data.length));
                break;
            }
            lines.add(Arrays.copyOfRange(data, start, idx));
            start = idx + le.length;
        }
        if (data.length == 0) lines.add(new byte[0]);
        return lines;
    }

    static byte[] joinBytes(List<byte[]> lines, byte[] le) {
        if (lines.isEmpty()) return new byte[0];
        ByteArrayOutputStream baos = new ByteArrayOutputStream();
        for (int i = 0; i < lines.size(); i++) {
            baos.write(lines.get(i), 0, lines.get(i).length);
            if (i < lines.size() - 1) {
                baos.write(le, 0, le.length);
            }
        }
        return baos.toByteArray();
    }

    static int indexOf(byte[] data, byte[] pattern, int from) {
        outer:
        for (int i = from; i <= data.length - pattern.length; i++) {
            for (int j = 0; j < pattern.length; j++) {
                if (data[i + j] != pattern[j]) continue outer;
            }
            return i;
        }
        return -1;
    }

    static boolean isHex(byte b) {
        return (b >= '0' && b <= '9') || (b >= 'a' && b <= 'f') || (b >= 'A' && b <= 'F');
    }

    static int hexVal(byte b) {
        if (b >= '0' && b <= '9') return b - '0';
        if (b >= 'a' && b <= 'f') return b - 'a' + 10;
        if (b >= 'A' && b <= 'F') return b - 'A' + 10;
        return 0;
    }

    static boolean isHexChar(char c) {
        return (c >= '0' && c <= '9') || (c >= 'a' && c <= 'f') || (c >= 'A' && c <= 'F');
    }

    static int hexValChar(char c) {
        if (c >= '0' && c <= '9') return c - '0';
        if (c >= 'a' && c <= 'f') return c - 'a' + 10;
        if (c >= 'A' && c <= 'F') return c - 'A' + 10;
        return 0;
    }
}

import Foundation

// MARK: - CRC-32

let crc32Table: [UInt32] = {
    var table = [UInt32](repeating: 0, count: 256)
    for i in 0..<256 {
        var c = UInt32(i)
        for _ in 0..<8 {
            if c & 1 != 0 { c = 0xEDB88320 ^ (c >> 1) }
            else { c >>= 1 }
        }
        table[i] = c
    }
    return table
}()

func crc32(_ data: [UInt8]) -> UInt32 {
    var crc: UInt32 = 0xFFFFFFFF
    for b in data {
        crc = (crc >> 8) ^ crc32Table[Int((crc ^ UInt32(b)) & 0xFF)]
    }
    return crc ^ 0xFFFFFFFF
}

// MARK: - Helpers

func hexVal(_ b: UInt8) -> Int {
    if b >= 48 && b <= 57 { return Int(b - 48) }
    if b >= 65 && b <= 70 { return Int(b - 55) }
    if b >= 97 && b <= 102 { return Int(b - 87) }
    return -1
}

func hexChar(_ c: Character) -> Int {
    return hexVal(UInt8(ascii: String(c)))
}

// MARK: - Charset Decoding

let windows1252Map: [UInt8: UInt32] = [
    0x80: 0x20AC, 0x81: 0x0081, 0x82: 0x201A, 0x83: 0x0192,
    0x84: 0x201E, 0x85: 0x2026, 0x86: 0x2020, 0x87: 0x2021,
    0x88: 0x02C6, 0x89: 0x2030, 0x8A: 0x0160, 0x8B: 0x2039,
    0x8C: 0x0152, 0x8D: 0x008D, 0x8E: 0x017D, 0x8F: 0x008F,
    0x90: 0x0090, 0x91: 0x2018, 0x92: 0x2019, 0x93: 0x201C,
    0x94: 0x201D, 0x95: 0x2022, 0x96: 0x2013, 0x97: 0x2014,
    0x98: 0x02DC, 0x99: 0x2122, 0x9A: 0x0161, 0x9B: 0x203A,
    0x9C: 0x0153, 0x9D: 0x009D, 0x9E: 0x017E, 0x9F: 0x0178
]

func decodeCharset(_ bytes: [UInt8], _ charset: String) -> String {
    let cs = charset.lowercased()
    switch cs {
    case "utf-8":
        return String(decoding: bytes, as: UTF8.self)
    case "windows-1252":
        var scalars: [Unicode.Scalar] = []
        for b in bytes {
            if let mapped = windows1252Map[b] {
                scalars.append(Unicode.Scalar(mapped)!)
            } else {
                scalars.append(Unicode.Scalar(b))
            }
        }
        return String(String.UnicodeScalarView(scalars))
    default:
        var scalars: [Unicode.Scalar] = []
        for b in bytes {
            scalars.append(Unicode.Scalar(b))
        }
        return String(String.UnicodeScalarView(scalars))
    }
}

// MARK: - Base64 Decoding

func base64Decode(_ input: [UInt8]) -> [UInt8] {
    let lookup: [UInt8: UInt8] = {
        let alpha = Array("ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/".utf8)
        var m = [UInt8: UInt8]()
        for (i, b) in alpha.enumerated() { m[b] = UInt8(i) }
        return m
    }()
    var vals: [UInt8] = []
    for b in input {
        if b == UInt8(ascii: "=") { break }
        if let v = lookup[b] { vals.append(v) }
    }
    var result: [UInt8] = []
    var i = 0
    while i < vals.count {
        let n = vals.count - i
        if n >= 4 {
            result.append((vals[i] << 2) | (vals[i+1] >> 4))
            result.append(((vals[i+1] & 0xF) << 4) | (vals[i+2] >> 2))
            result.append(((vals[i+2] & 0x3) << 6) | vals[i+3])
            i += 4
        } else if n == 3 {
            result.append((vals[i] << 2) | (vals[i+1] >> 4))
            result.append(((vals[i+1] & 0xF) << 4) | (vals[i+2] >> 2))
            i += 3
        } else if n == 2 {
            result.append((vals[i] << 2) | (vals[i+1] >> 4))
            i += 2
        } else {
            break
        }
    }
    return result
}

// MARK: - Quoted-Printable Decoding

func qpDecode(_ input: [UInt8], lineBreak: [UInt8]) -> [UInt8] {
    let eq: UInt8 = 61
    let sp: UInt8 = 32
    let tab: UInt8 = 9

    struct QPLine { var content: [UInt8]; var lb: [UInt8] }
    var lines: [QPLine] = []
    var current: [UInt8] = []
    var i = 0

    while i < input.count {
        if lineBreak.count == 2 && i + 1 < input.count && input[i] == 13 && input[i+1] == 10 {
            lines.append(QPLine(content: current, lb: [13, 10]))
            current = []
            i += 2
        } else if lineBreak.count == 1 && input[i] == 10 {
            lines.append(QPLine(content: current, lb: [10]))
            current = []
            i += 1
        } else {
            current.append(input[i])
            i += 1
        }
    }
    if !current.isEmpty || lines.isEmpty {
        lines.append(QPLine(content: current, lb: []))
    }

    for j in 0..<lines.count {
        while let last = lines[j].content.last, last == sp || last == tab {
            lines[j].content.removeLast()
        }
    }

    var joined: [UInt8] = []
    for j in 0..<lines.count {
        if j > 0 {
            if let last = lines[j-1].content.last, last == eq, !lines[j-1].lb.isEmpty {
                lines[j-1].content.removeLast()
            } else {
                joined.append(contentsOf: lines[j-1].lb)
            }
        }
        joined.append(contentsOf: lines[j].content)
    }

    var result: [UInt8] = []
    i = 0
    while i < joined.count {
        if joined[i] == eq && i + 2 < joined.count {
            let h1 = hexVal(joined[i+1])
            let h2 = hexVal(joined[i+2])
            if h1 >= 0 && h2 >= 0 {
                result.append(UInt8(h1 * 16 + h2))
                i += 3
            } else {
                result.append(eq)
                i += 1
            }
        } else {
            result.append(joined[i])
            i += 1
        }
    }
    return result
}

// MARK: - RFC 2047 Decoding

func qDecodeQ(_ input: [UInt8]) -> [UInt8] {
    var result: [UInt8] = []
    var i = 0
    while i < input.count {
        if input[i] == UInt8(ascii: "_") {
            result.append(0x20)
            i += 1
        } else if input[i] == UInt8(ascii: "=") && i + 2 < input.count {
            let h1 = hexVal(input[i+1])
            let h2 = hexVal(input[i+2])
            if h1 >= 0 && h2 >= 0 {
                result.append(UInt8(h1 * 16 + h2))
                i += 3
            } else {
                result.append(UInt8(ascii: "="))
                i += 1
            }
        } else {
            result.append(input[i])
            i += 1
        }
    }
    return result
}

func matchEW(_ chars: [Character], _ pos: Int) -> (start: Int, end: Int, charset: String, bytes: [UInt8])? {
    let n = chars.count
    guard pos + 1 < n, chars[pos] == "=", chars[pos+1] == "?" else { return nil }
    var i = pos + 2
    let csStart = i
    while i < n && chars[i] != "?" && chars[i] != " " && chars[i] != "\t" { i += 1 }
    if i == csStart || i >= n || chars[i] != "?" { return nil }
    let charset = String(chars[csStart..<i])
    i += 1
    guard i < n, chars[i] == "B" || chars[i] == "b" || chars[i] == "Q" || chars[i] == "q" else { return nil }
    let enc = chars[i]
    i += 1
    guard i < n, chars[i] == "?" else { return nil }
    i += 1
    let etStart = i
    while i < n && chars[i] != "?" && chars[i] != " " && chars[i] != "\t" { i += 1 }
    let et = String(chars[etStart..<i])
    guard i + 1 < n, chars[i] == "?", chars[i+1] == "=" else { return nil }
    i += 2
    let bytes: [UInt8]
    if enc == "B" || enc == "b" {
        bytes = base64Decode(Array(et.utf8))
    } else {
        bytes = qDecodeQ(Array(et.utf8))
    }
    var cs = charset.lowercased()
    if let starIdx = cs.firstIndex(of: "*") {
        cs = String(cs[cs.startIndex..<starIdx])
    }
    return (pos, i, cs, bytes)
}

func decodeRFC2047(_ input: String) -> String {
    let chars = Array(input)
    let n = chars.count
    struct EW { let start: Int; let end: Int; let charset: String; let bytes: [UInt8] }
    var words: [EW] = []
    var pos = 0
    while pos < n {
        if let ew = matchEW(chars, pos) {
            words.append(EW(start: ew.start, end: ew.end, charset: ew.charset, bytes: ew.bytes))
            pos = ew.end
        } else {
            pos += 1
        }
    }
    if words.isEmpty { return input }
    struct Group { var words: [EW] }
    var groups: [Group] = []
    for w in words {
        if groups.count > 0 {
            let lastW = groups[groups.count - 1].words.last!
            let between = Array(chars[lastW.end..<w.start])
            if between.allSatisfy({ $0 == " " || $0 == "\t" }) && lastW.charset == w.charset {
                groups[groups.count - 1].words.append(w)
                continue
            }
        }
        groups.append(Group(words: [w]))
    }
    var result = ""
    var prevEnd = 0
    for group in groups {
        result += String(chars[prevEnd..<group.words[0].start])
        var allBytes: [UInt8] = []
        for w in group.words { allBytes.append(contentsOf: w.bytes) }
        result += decodeCharset(allBytes, group.words[0].charset)
        prevEnd = group.words.last!.end
    }
    result += String(chars[prevEnd..<n])
    return result
}

// MARK: - RFC 2231 Decoding

func percentDecode(_ s: String) -> [UInt8] {
    var result: [UInt8] = []
    let bytes = Array(s.utf8)
    var i = 0
    while i < bytes.count {
        if bytes[i] == UInt8(ascii: "%") && i + 2 < bytes.count {
            let h1 = hexVal(bytes[i+1])
            let h2 = hexVal(bytes[i+2])
            if h1 >= 0 && h2 >= 0 {
                result.append(UInt8(h1 * 16 + h2))
                i += 3
            } else {
                result.append(bytes[i])
                i += 1
            }
        } else {
            result.append(bytes[i])
            i += 1
        }
    }
    return result
}

func rfc2231Decode(_ attr: String, _ params: [(name: String, value: String)]) -> String? {
    // Single segment: attr*
    if let (_, val) = params.first(where: { $0.name == attr + "*" }) {
        return decodeRFC2231Single(val)
    }
    // Continuation segments
    var segments: [(index: Int, percentEncoded: Bool, value: String)] = []
    for (name, value) in params {
        guard name.hasPrefix(attr + "*") else { continue }
        let suffix = String(name.dropFirst(attr.count + 1))
        if suffix.isEmpty { continue }
        var idxStr = suffix
        var pct = false
        if idxStr.hasSuffix("*") {
            pct = true
            idxStr = String(idxStr.dropLast())
        }
        if let idx = Int(idxStr) {
            segments.append((idx, pct, value))
        }
    }
    if segments.isEmpty { return nil }
    segments.sort { $0.index < $1.index }
    var charset = "us-ascii"
    var allBytes: [UInt8] = []
    for (i, seg) in segments.enumerated() {
        var val = seg.value
        if seg.percentEncoded {
            if i == 0 {
                if let fq = val.firstIndex(of: "'") {
                    charset = String(val[val.startIndex..<fq])
                    let afterFirst = val.index(after: fq)
                    if let sq = val[afterFirst...].firstIndex(of: "'") {
                        val = String(val[val.index(after: sq)...])
                    } else {
                        val = ""
                    }
                }
            }
            allBytes.append(contentsOf: percentDecode(val))
        } else {
            allBytes.append(contentsOf: Array(val.utf8))
        }
    }
    return decodeCharset(allBytes, charset)
}

func decodeRFC2231Single(_ value: String) -> String {
    var charset = "us-ascii"
    var val = value
    if let fq = val.firstIndex(of: "'") {
        charset = String(val[val.startIndex..<fq])
        let afterFirst = val.index(after: fq)
        if let sq = val[afterFirst...].firstIndex(of: "'") {
            val = String(val[val.index(after: sq)...])
        } else {
            val = ""
        }
    }
    let bytes = percentDecode(val)
    return decodeCharset(bytes, charset)
}

func extractFileName(ctParams: [(name: String, value: String)], cdParams: [(name: String, value: String)]) -> String? {
    if let name = rfc2231Decode("filename", cdParams) { return name }
    if let (_, val) = cdParams.first(where: { $0.name == "filename" }) {
        return decodeRFC2047(val)
    }
    if let name = rfc2231Decode("name", ctParams) { return name }
    if let (_, val) = ctParams.first(where: { $0.name == "name" }) {
        return decodeRFC2047(val)
    }
    return nil
}

// MARK: - Header Parameter Parsing

struct ParsedHeader {
    var type: String
    var subtype: String?
    var params: [(name: String, value: String)]
}

func parseHeaderParams(_ value: String, hasSubtype: Bool) -> ParsedHeader {
    let chars = Array(value)
    var pos = 0
    let n = chars.count

    func skipWS() {
        while pos < n && (chars[pos] == " " || chars[pos] == "\t") { pos += 1 }
    }

    func readToken(_ stopChars: Set<Character>) -> String {
        var tok = ""
        while pos < n && !stopChars.contains(chars[pos]) {
            tok.append(chars[pos])
            pos += 1
        }
        return tok
    }

    func readQuoted() -> String {
        pos += 1
        var result = ""
        while pos < n {
            if chars[pos] == "\\" && pos + 1 < n {
                result.append(chars[pos + 1])
                pos += 2
            } else if chars[pos] == "\"" {
                pos += 1
                break
            } else {
                result.append(chars[pos])
                pos += 1
            }
        }
        return result
    }

    skipWS()
    let mainType = readToken([" ", "\t", "/", ";", "="]).lowercased()
    var subType: String? = nil
    if hasSubtype {
        skipWS()
        if pos < n && chars[pos] == "/" {
            pos += 1
            skipWS()
            subType = readToken([" ", "\t", ";", "="]).lowercased()
        }
    }
    var params: [(name: String, value: String)] = []
    while pos < n {
        skipWS()
        if pos < n && chars[pos] == ";" {
            pos += 1
            skipWS()
            let name = readToken([" ", "\t", "=", ";"]).lowercased()
            skipWS()
            if pos < n && chars[pos] == "=" {
                pos += 1
                skipWS()
                let val: String
                if pos < n && chars[pos] == "\"" {
                    val = readQuoted()
                } else {
                    val = readToken([" ", "\t", ";"])
                }
                params.append((name, val))
            }
        } else {
            break
        }
    }
    return ParsedHeader(type: mainType, subtype: subType, params: params)
}

// MARK: - Entity Structure

struct Entity {
    var headers: [String: String]
    var body: [UInt8]
    var parts: [Entity]
    var lineBreak: [UInt8]
    var ctType: String
    var ctSubtype: String
    var ctParams: [(name: String, value: String)]
    var cdType: String?
    var cdParams: [(name: String, value: String)]
    var cte: String
}

// MARK: - Entity Parsing

func findSubseq(_ data: [UInt8], _ pattern: [UInt8]) -> Int? {
    if pattern.isEmpty { return 0 }
    if pattern.count > data.count { return nil }
    for i in 0...(data.count - pattern.count) {
        var match = true
        for j in 0..<pattern.count {
            if data[i+j] != pattern[j] { match = false; break }
        }
        if match { return i }
    }
    return nil
}

func unfoldHeaders(_ data: [UInt8], lineBreak: [UInt8]) -> [UInt8] {
    var result: [UInt8] = []
    var i = 0
    while i < data.count {
        if i + lineBreak.count < data.count {
            var isLB = true
            for j in 0..<lineBreak.count {
                if data[i+j] != lineBreak[j] { isLB = false; break }
            }
            if isLB {
                let next = data[i + lineBreak.count]
                if next == 32 || next == 9 {
                    i += lineBreak.count
                    continue
                }
            }
        }
        result.append(data[i])
        i += 1
    }
    return result
}

func splitLines(_ data: [UInt8], lineBreak: [UInt8]) -> [[UInt8]] {
    var lines: [[UInt8]] = []
    var current: [UInt8] = []
    var i = 0
    while i < data.count {
        if lineBreak.count == 2 && i + 1 < data.count && data[i] == 13 && data[i+1] == 10 {
            lines.append(current)
            current = []
            i += 2
        } else if lineBreak.count == 1 && data[i] == 10 {
            lines.append(current)
            current = []
            i += 1
        } else {
            current.append(data[i])
            i += 1
        }
    }
    lines.append(current)
    return lines
}

func parseEntity(_ data: [UInt8], lineBreak: [UInt8]) -> Entity {
    // Find header/body split
    let sep = lineBreak + lineBreak
    var headerEnd = -1
    var bodyStart = -1

    if data.count >= lineBreak.count {
        var isLB = true
        for j in 0..<lineBreak.count {
            if data[j] != lineBreak[j] { isLB = false; break }
        }
        if isLB {
            headerEnd = 0
            bodyStart = lineBreak.count
        }
    }

    if headerEnd == -1 {
        if let pos = findSubseq(data, sep) {
            headerEnd = pos
            bodyStart = pos + sep.count
        } else {
            headerEnd = data.count
            bodyStart = data.count
        }
    }

    let headerData = Array(data[0..<headerEnd])
    let body = Array(data[bodyStart...])

    // Unfold headers
    let unfolded = unfoldHeaders(headerData, lineBreak: lineBreak)
    let headerLines = splitLines(unfolded, lineBreak: lineBreak)

    var headers: [String: String] = [:]
    for line in headerLines {
        if let colonPos = line.firstIndex(of: 58) { // ':'
            let name = String(bytes: line[0..<colonPos], encoding: .ascii)?.lowercased() ?? ""
            var valueBytes = Array(line[(colonPos+1)...])
            // Trim leading and trailing spaces/tabs
            while let first = valueBytes.first, first == 32 || first == 9 { valueBytes.removeFirst() }
            while let last = valueBytes.last, last == 32 || last == 9 { valueBytes.removeLast() }
            let value = String(bytes: valueBytes, encoding: .ascii) ?? ""
            headers[name] = value
        }
    }

    // Parse Content-Type
    var ctType = "text"
    var ctSubtype = "plain"
    var ctParams: [(name: String, value: String)] = []
    if let ctValue = headers["content-type"] {
        let parsed = parseHeaderParams(ctValue, hasSubtype: true)
        ctType = parsed.type
        ctSubtype = parsed.subtype ?? ""
        ctParams = parsed.params
    }

    // Parse Content-Disposition
    var cdType: String? = nil
    var cdParams: [(name: String, value: String)] = []
    if let cdValue = headers["content-disposition"] {
        let parsed = parseHeaderParams(cdValue, hasSubtype: false)
        cdType = parsed.type
        cdParams = parsed.params
    }

    // CTE
    let cte = (headers["content-transfer-encoding"] ?? "7bit").lowercased()

    // Parse parts if multipart
    var parts: [Entity] = []
    if ctType == "multipart" {
        var boundary = ""
        for (name, value) in ctParams {
            if name == "boundary" { boundary = value; break }
        }
        if !boundary.isEmpty {
            parts = parseMultipartBody(body, boundary: boundary, lineBreak: lineBreak)
        }
    }

    return Entity(headers: headers, body: body, parts: parts, lineBreak: lineBreak,
                  ctType: ctType, ctSubtype: ctSubtype, ctParams: ctParams,
                  cdType: cdType, cdParams: cdParams, cte: cte)
}

func parseMultipartBody(_ body: [UInt8], boundary: String, lineBreak: [UInt8]) -> [Entity] {
    let delims = findDelimiters(body: body, boundary: boundary, lineBreak: lineBreak)
    var parts: [Entity] = []
    for i in 0..<(delims.count - 1) {
        let start = delims[i].end
        let end = delims[i+1].start
        if start > end { continue }
        var partBytes = Array(body[start..<end])
        if partBytes.count >= lineBreak.count {
            let suffix = Array(partBytes[(partBytes.count - lineBreak.count)...])
            if suffix == lineBreak {
                partBytes.removeLast(lineBreak.count)
            }
        }
        parts.append(parseEntity(partBytes, lineBreak: lineBreak))
    }
    return parts
}

func findDelimiters(body: [UInt8], boundary: String, lineBreak: [UInt8]) -> [(start: Int, end: Int, isClose: Bool)] {
    var result: [(start: Int, end: Int, isClose: Bool)] = []
    let boundaryBytes = Array(boundary.utf8)
    let dd: [UInt8] = [0x2D, 0x2D]

    var lineStart = 0
    while lineStart <= body.count {
        var lineEnd = lineStart
        while lineEnd < body.count {
            if lineBreak.count == 2 && lineEnd + 1 < body.count && body[lineEnd] == 13 && body[lineEnd+1] == 10 {
                break
            }
            if lineBreak.count == 1 && body[lineEnd] == 10 {
                break
            }
            lineEnd += 1
        }

        let lineContent = Array(body[lineStart..<lineEnd])
        let closePrefix = dd + boundaryBytes + dd
        let delimPrefix = dd + boundaryBytes
        var isDelim = false

        if lineContent.count >= closePrefix.count && Array(lineContent[0..<closePrefix.count]) == closePrefix {
            let rest = Array(lineContent[closePrefix.count...])
            if rest.allSatisfy({ $0 == 32 || $0 == 9 }) {
                let end = (lineEnd < body.count) ? lineEnd + lineBreak.count : lineEnd
                result.append((start: lineStart, end: end, isClose: true))
                isDelim = true
            }
        }

        if !isDelim && lineContent.count >= delimPrefix.count && Array(lineContent[0..<delimPrefix.count]) == delimPrefix {
            let rest = Array(lineContent[delimPrefix.count...])
            if rest.allSatisfy({ $0 == 32 || $0 == 9 }) {
                let end = (lineEnd < body.count) ? lineEnd + lineBreak.count : lineEnd
                result.append((start: lineStart, end: end, isClose: false))
                isDelim = true
            }
        }

        if lineEnd >= body.count { break }
        lineStart = lineEnd + lineBreak.count
    }
    return result
}

// MARK: - Transfer Decoding

func transferDecode(_ body: [UInt8], cte: String, lineBreak: [UInt8]) -> [UInt8] {
    switch cte {
    case "base64":
        return base64Decode(body)
    case "quoted-printable":
        return qpDecode(body, lineBreak: lineBreak)
    default:
        return body
    }
}

// MARK: - Text Decoding

func decodeTextPart(_ body: [UInt8], cte: String, charset: String, lineBreak: [UInt8]) -> String {
    let decoded = transferDecode(body, cte: cte, lineBreak: lineBreak)
    var text = decodeCharset(decoded, charset)
    text = text.replacingOccurrences(of: "\r\n", with: "\n")
    text = text.replacingOccurrences(of: "\r", with: "\n")
    return text
}

// MARK: - Quoted String Output

func quoteString(_ s: String) -> String {
    var result = "\""
    for scalar in s.unicodeScalars {
        let v = scalar.value
        if v == 0x5C { result += "\\\\" }
        else if v == 0x22 { result += "\\\"" }
        else if v == 0x0A { result += "\\n" }
        else if v == 0x09 { result += "\\t" }
        else if v < 0x20 || (v >= 0x7F && v <= 0x9F) {
            result += String(format: "\\u%04x", v)
        } else {
            result.unicodeScalars.append(scalar)
        }
    }
    result += "\""
    return result
}

// MARK: - Tree Printing

func printEntity(_ entity: Entity, indent: Int, output: inout String) {
    let prefix = String(repeating: "  ", count: indent)
    let ctType = entity.ctType
    let ctSubtype = entity.ctSubtype
    let cte = entity.cte

    if ctType == "multipart" {
        output += "\(prefix)multipart/\(ctSubtype) parts=\(entity.parts.count)\n"
        for part in entity.parts {
            printEntity(part, indent: indent + 1, output: &output)
        }
    } else if ctType == "text" && entity.cdType != "attachment" {
        var charset = "us-ascii"
        for (name, value) in entity.ctParams {
            if name == "charset" { charset = value.lowercased(); break }
        }
        let decoded = decodeTextPart(entity.body, cte: cte, charset: charset, lineBreak: entity.lineBreak)
        let charCount = decoded.unicodeScalars.count
        let quoted = quoteString(decoded)
        output += "\(prefix)text/\(ctSubtype) charset=\(charset) cte=\(cte) chars=\(charCount)\n"
        output += "\(prefix)  \(quoted)\n"
    } else {
        let decoded = transferDecode(entity.body, cte: cte, lineBreak: entity.lineBreak)
        let size = decoded.count
        let crc = crc32(decoded)
        let disposition = entity.cdType ?? "-"
        let fileName = extractFileName(ctParams: entity.ctParams, cdParams: entity.cdParams)
        let nameStr = fileName != nil ? quoteString(fileName!) : "-"
        output += "\(prefix)\(ctType)/\(ctSubtype) cte=\(cte) disposition=\(disposition) name=\(nameStr) size=\(size) crc32=\(String(format: "%08x", crc))\n"
    }
}

// MARK: - Main

let args = CommandLine.arguments
guard args.count >= 2 else { exit(1) }
let dir = args[1]

let fm = FileManager.default
guard let files = try? fm.contentsOfDirectory(atPath: dir) else { exit(1) }
let emlFiles = files.filter { $0.hasSuffix(".eml") }.sorted { $0 < $1 }

var first = true
for fileName in emlFiles {
    if !first { print("") }
    first = false

    let path = dir + "/" + fileName
    guard let data = fm.contents(atPath: path) else { continue }
    var fileBytes = [UInt8](data)

    // Detect line break
    let lineBreak: [UInt8]
    if findSubseq(fileBytes, [13, 10]) != nil {
        lineBreak = [13, 10]
    } else {
        lineBreak = [10]
    }

    // Parse entity
    let entity = parseEntity(fileBytes, lineBreak: lineBreak)

    // Print header
    print("== \(fileName)")
    let fromVal = entity.headers["from"]
    let subjVal = entity.headers["subject"]
    print("From: \(fromVal != nil ? quoteString(decodeRFC2047(fromVal!)) : "-")")
    print("Subject: \(subjVal != nil ? quoteString(decodeRFC2047(subjVal!)) : "-")")

    // Print tree
    var treeOutput = ""
    printEntity(entity, indent: 0, output: &treeOutput)
    // Remove trailing newline for print
    if treeOutput.hasSuffix("\n") {
        treeOutput.removeLast()
    }
    print(treeOutput)
}

exit(0)

import * as fs from 'fs';
import * as path from 'path';

// ============ CRC-32 ============
const crcTable: number[] = [];
for (let i = 0; i < 256; i++) {
  let c = i;
  for (let j = 0; j < 8; j++) {
    c = (c & 1) ? (0xEDB88320 ^ (c >>> 1)) : (c >>> 1);
  }
  crcTable[i] = c >>> 0;
}

function crc32(data: Buffer): number {
  let crc = 0xFFFFFFFF;
  for (let i = 0; i < data.length; i++) {
    crc = (crc >>> 8) ^ crcTable[(crc ^ data[i]) & 0xFF];
  }
  return (crc ^ 0xFFFFFFFF) >>> 0;
}

// ============ Charset Decoding ============
const windows1252Map: Map<number, number> = new Map([
  [0x80, 0x20AC], [0x81, 0x0081], [0x82, 0x201A], [0x83, 0x0192],
  [0x84, 0x201E], [0x85, 0x2026], [0x86, 0x2020], [0x87, 0x2021],
  [0x88, 0x02C6], [0x89, 0x2030], [0x8A, 0x0160], [0x8B, 0x2039],
  [0x8C, 0x0152], [0x8D, 0x008D], [0x8E, 0x017D], [0x8F, 0x008F],
  [0x90, 0x0090], [0x91, 0x2018], [0x92, 0x2019], [0x93, 0x201C],
  [0x94, 0x201D], [0x95, 0x2022], [0x96, 0x2013], [0x97, 0x2014],
  [0x98, 0x02DC], [0x99, 0x2122], [0x9A, 0x0161], [0x9B, 0x203A],
  [0x9C, 0x0153], [0x9D, 0x009D], [0x9E, 0x017E], [0x9F, 0x0178],
]);

function decodeCharset(data: Buffer, charset: string): string {
  const cs = charset.toLowerCase().trim();
  if (cs === 'utf-8' || cs === 'utf8') {
    return data.toString('utf-8');
  } else if (cs === 'iso-8859-1' || cs === 'latin1' || cs === 'us-ascii' || cs === 'ascii') {
    if (cs === 'us-ascii' || cs === 'ascii' || cs === 'iso-8859-1' || cs === 'latin1') {
      return data.toString('latin1');
    }
  }
  if (cs === 'windows-1252' || cs === 'cp1252') {
    let result = '';
    for (let i = 0; i < data.length; i++) {
      const b = data[i];
      if (b >= 0x80 && b <= 0x9F) {
        result += String.fromCodePoint(windows1252Map.get(b)!);
      } else {
        result += String.fromCharCode(b);
      }
    }
    return result;
  }
  // Default: latin1
  return data.toString('latin1');
}

// ============ Base64 Decoding ============
function base64Decode(input: string): Buffer {
  const chars: number[] = [];
  for (let i = 0; i < input.length; i++) {
    const c = input.charCodeAt(i);
    if (c === 61) break; // '='
    if ((c >= 65 && c <= 90) || (c >= 97 && c <= 122) || (c >= 48 && c <= 57) || c === 43 || c === 47) {
      chars.push(c);
    }
  }
  const bytes: number[] = [];
  for (let i = 0; i < chars.length; i += 4) {
    const n = Math.min(4, chars.length - i);
    let val = 0;
    for (let j = 0; j < 4; j++) {
      val <<= 6;
      if (j < n) {
        const c = chars[i + j];
        if (c >= 65 && c <= 90) val += c - 65;
        else if (c >= 97 && c <= 122) val += c - 71;
        else if (c >= 48 && c <= 57) val += c - 4;
        else if (c === 43) val += 62;
        else if (c === 47) val += 63;
      }
    }
    if (n >= 2) bytes.push((val >> 16) & 0xFF);
    if (n >= 3) bytes.push((val >> 8) & 0xFF);
    if (n >= 4) bytes.push(val & 0xFF);
  }
  return Buffer.from(bytes);
}

// ============ Quoted-Printable Decoding ============
function qpDecode(data: Buffer, lineBreak: string): Buffer {
  const text = data.toString('latin1');
  const lines = text.split(lineBreak);

  // Step 1: Remove trailing spaces/tabs from each line
  const cleaned: string[] = [];
  for (let i = 0; i < lines.length; i++) {
    let end = lines[i].length;
    while (end > 0 && (lines[i][end - 1] === ' ' || lines[i][end - 1] === '\t')) end--;
    cleaned.push(lines[i].substring(0, end));
  }

  // Step 2: Join soft line breaks
  let joined = '';
  let i = 0;
  while (i < cleaned.length) {
    if (cleaned[i].endsWith('=')) {
      joined += cleaned[i].slice(0, -1);
    } else {
      joined += cleaned[i];
      if (i < cleaned.length - 1) {
        joined += lineBreak;
      }
    }
    i++;
  }

  // Step 3: Decode =XY sequences
  const bytes: number[] = [];
  i = 0;
  while (i < joined.length) {
    if (joined[i] === '=' && i + 2 < joined.length) {
      const hex = joined.substring(i + 1, i + 3);
      if (/^[0-9a-fA-F]{2}$/.test(hex)) {
        bytes.push(parseInt(hex, 16));
        i += 3;
      } else {
        bytes.push(joined.charCodeAt(i));
        i++;
      }
    } else {
      bytes.push(joined.charCodeAt(i));
      i++;
    }
  }

  return Buffer.from(bytes);
}

// ============ CTE Decoding ============
function decodeCTE(data: Buffer, encoding: string, lineBreak: string): Buffer {
  const enc = encoding.toLowerCase();
  if (enc === 'base64') {
    return base64Decode(data.toString('latin1'));
  } else if (enc === 'quoted-printable') {
    return qpDecode(data, lineBreak);
  }
  return data;
}

// ============ RFC 2047 Encoded Words ============
function decodeEncodedWords(value: string): string {
  const ewRegex = /=\?([^? \t]+)\?([BbQq])\?([^? \t]*)\?=/g;

  interface EWMatch {
    start: number;
    end: number;
    charset: string;
    encoding: string;
    text: string;
  }

  const matches: EWMatch[] = [];
  let m: RegExpExecArray | null;
  while ((m = ewRegex.exec(value)) !== null) {
    matches.push({
      start: m.index,
      end: m.index + m[0].length,
      charset: m[1],
      encoding: m[2],
      text: m[3],
    });
  }

  if (matches.length === 0) return value;

  function normCharset(cs: string): string {
    const star = cs.indexOf('*');
    if (star >= 0) return cs.substring(0, star).toLowerCase();
    return cs.toLowerCase();
  }

  // Group into runs of adjacent encoded-words with same charset
  interface Run {
    matches: EWMatch[];
    start: number;
    end: number;
    charset: string;
  }

  const runs: Run[] = [];
  let currentRun: Run | null = null;

  for (const match of matches) {
    const nc = normCharset(match.charset);
    if (currentRun && currentRun.charset === nc) {
      const between = value.substring(currentRun.end, match.start);
      if (/^[ \t]*$/.test(between)) {
        currentRun.matches.push(match);
        currentRun.end = match.end;
        continue;
      }
    }
    currentRun = { matches: [match], start: match.start, end: match.end, charset: nc };
    runs.push(currentRun);
  }

  // Build output
  let result = '';
  let pos = 0;
  for (const run of runs) {
    result += value.substring(pos, run.start);

    // Decode all words in the run
    const bytes: number[] = [];
    for (const mw of run.matches) {
      if (mw.encoding === 'B' || mw.encoding === 'b') {
        const decoded = base64Decode(mw.text);
        for (let j = 0; j < decoded.length; j++) bytes.push(decoded[j]);
      } else {
        // Q encoding
        let j = 0;
        while (j < mw.text.length) {
          if (mw.text[j] === '_') {
            bytes.push(0x20);
            j++;
          } else if (mw.text[j] === '=' && j + 2 < mw.text.length) {
            const hex = mw.text.substring(j + 1, j + 3);
            if (/^[0-9a-fA-F]{2}$/.test(hex)) {
              bytes.push(parseInt(hex, 16));
              j += 3;
            } else {
              bytes.push(mw.text.charCodeAt(j));
              j++;
            }
          } else {
            bytes.push(mw.text.charCodeAt(j));
            j++;
          }
        }
      }
    }

    // Decode with charset
    const charset = run.matches[0].charset;
    const star = charset.indexOf('*');
    const actualCharset = star >= 0 ? charset.substring(0, star) : charset;
    result += decodeCharset(Buffer.from(bytes), actualCharset);

    pos = run.end;
  }
  result += value.substring(pos);
  return result;
}

// ============ Quoted String Output ============
function quotedString(s: string): string {
  let result = '"';
  for (const ch of s) {
    const cp = ch.codePointAt(0)!;
    if (ch === '\\') result += '\\\\';
    else if (ch === '"') result += '\\"';
    else if (ch === '\n') result += '\\n';
    else if (ch === '\t') result += '\\t';
    else if (cp < 0x20 || (cp >= 0x7F && cp <= 0x9F)) {
      result += '\\u' + cp.toString(16).padStart(4, '0');
    } else {
      result += ch;
    }
  }
  result += '"';
  return result;
}

// ============ Entity ============
interface Entity {
  headers: Map<string, string>;
  body: Buffer;
}

function parseEntity(data: Buffer, lineBreak: string): Entity {
  const lb = Buffer.from(lineBreak);
  const doubleLb = Buffer.from(lineBreak + lineBreak);

  let headerEnd: number;
  let bodyStart: number;

  if (data.length >= lb.length && data.slice(0, lb.length).equals(lb)) {
    headerEnd = 0;
    bodyStart = lb.length;
  } else {
    const idx = data.indexOf(doubleLb);
    if (idx >= 0) {
      headerEnd = idx;
      bodyStart = idx + doubleLb.length;
    } else {
      headerEnd = data.length;
      bodyStart = data.length;
    }
  }

  const headerBlock = data.slice(0, headerEnd);
  const body = data.slice(bodyStart);
  const headers = parseHeaders(headerBlock, lineBreak);

  return { headers, body };
}

function parseHeaders(headerBlock: Buffer, lineBreak: string): Map<string, string> {
  const headers = new Map<string, string>();
  if (headerBlock.length === 0) return headers;

  const text = headerBlock.toString('latin1');
  const lines = text.split(lineBreak);

  // Unfold
  const unfolded: string[] = [];
  for (const line of lines) {
    if (line.length > 0 && (line[0] === ' ' || line[0] === '\t')) {
      if (unfolded.length > 0) {
        unfolded[unfolded.length - 1] += line;
      }
    } else {
      unfolded.push(line);
    }
  }

  for (const line of unfolded) {
    const colonIdx = line.indexOf(':');
    if (colonIdx < 0) continue;
    const name = line.substring(0, colonIdx).toLowerCase();
    let value = line.substring(colonIdx + 1);
    value = value.replace(/^[ \t]+/, '').replace(/[ \t]+$/, '');
    headers.set(name, value);
  }

  return headers;
}

// ============ Parameter Header Parsing ============
interface ParsedHeader {
  main: string;
  params: Map<string, string>;
}

function parseParamHeader(value: string): ParsedHeader {
  const params = new Map<string, string>();

  // Find first ; not inside quotes
  let mainEnd = value.length;
  let inQuote = false;
  for (let i = 0; i < value.length; i++) {
    if (value[i] === '\\') { i++; continue; }
    if (value[i] === '"') { inQuote = !inQuote; continue; }
    if (value[i] === ';' && !inQuote) { mainEnd = i; break; }
  }

  const main = value.substring(0, mainEnd).trim();

  let pos = mainEnd;
  while (pos < value.length) {
    while (pos < value.length && (value[pos] === ' ' || value[pos] === '\t' || value[pos] === ';')) pos++;
    if (pos >= value.length) break;

    let nameStart = pos;
    while (pos < value.length && value[pos] !== '=' && value[pos] !== ' ' && value[pos] !== '\t' && value[pos] !== ';') pos++;
    const name = value.substring(nameStart, pos).toLowerCase();

    while (pos < value.length && (value[pos] === ' ' || value[pos] === '\t')) pos++;
    if (pos < value.length && value[pos] === '=') pos++;
    while (pos < value.length && (value[pos] === ' ' || value[pos] === '\t')) pos++;

    let paramValue: string;
    if (pos < value.length && value[pos] === '"') {
      pos++;
      let val = '';
      while (pos < value.length && value[pos] !== '"') {
        if (value[pos] === '\\' && pos + 1 < value.length) {
          val += value[pos + 1];
          pos += 2;
        } else {
          val += value[pos];
          pos++;
        }
      }
      if (pos < value.length) pos++;
      paramValue = val;
    } else {
      let val = '';
      while (pos < value.length && value[pos] !== ';' && value[pos] !== ' ' && value[pos] !== '\t') {
        val += value[pos];
        pos++;
      }
      paramValue = val;
    }

    params.set(name, paramValue);
  }

  return { main, params };
}

function parseContentType(value: string): { type: string; subtype: string; params: Map<string, string> } {
  const parsed = parseParamHeader(value);
  const slashIdx = parsed.main.indexOf('/');
  let type: string, subtype: string;
  if (slashIdx >= 0) {
    type = parsed.main.substring(0, slashIdx).trim().toLowerCase();
    subtype = parsed.main.substring(slashIdx + 1).trim().toLowerCase();
  } else {
    type = parsed.main.toLowerCase();
    subtype = '';
  }
  return { type, subtype, params: parsed.params };
}

function parseContentDisposition(value: string): { type: string; params: Map<string, string> } {
  const parsed = parseParamHeader(value);
  return { type: parsed.main.toLowerCase(), params: parsed.params };
}

// ============ RFC 2231 ============
function percentDecodeBytes(value: string): number[] {
  const bytes: number[] = [];
  for (let i = 0; i < value.length; i++) {
    if (value[i] === '%' && i + 2 < value.length) {
      const hex = value.substring(i + 1, i + 3);
      if (/^[0-9a-fA-F]{2}$/.test(hex)) {
        bytes.push(parseInt(hex, 16));
        i += 2;
      } else {
        bytes.push(value.charCodeAt(i));
      }
    } else {
      bytes.push(value.charCodeAt(i));
    }
  }
  return bytes;
}

function getRfc2231Param(params: Map<string, string>, attr: string): string | null {
  // Check single form: attr*
  const single = params.get(attr + '*');
  if (single !== undefined) {
    // charset'language'percent-encoded
    let charset = 'us-ascii';
    let data = single;
    const q1 = single.indexOf("'");
    if (q1 >= 0) {
      const q2 = single.indexOf("'", q1 + 1);
      if (q2 >= 0) {
        charset = single.substring(0, q1) || 'us-ascii';
        data = single.substring(q2 + 1);
      }
    }
    const bytes = percentDecodeBytes(data);
    return decodeCharset(Buffer.from(bytes), charset);
  }

  // Check continuation segments
  const segments: { index: number; value: string; percentEncoded: boolean }[] = [];
  const prefix = attr + '*';
  for (const [key, value] of params) {
    if (key.startsWith(prefix)) {
      const rest = key.substring(prefix.length);
      if (rest === '') continue;
      let idxStr = rest;
      let percentEncoded = false;
      if (rest.endsWith('*')) {
        idxStr = rest.slice(0, -1);
        percentEncoded = true;
      }
      const idx = parseInt(idxStr, 10);
      if (!isNaN(idx)) {
        segments.push({ index: idx, value, percentEncoded });
      }
    }
  }

  if (segments.length === 0) return null;

  segments.sort((a, b) => a.index - b.index);

  let charset = 'us-ascii';
  const bytes: number[] = [];

  for (const seg of segments) {
    if (seg.percentEncoded) {
      let val = seg.value;
      if (seg.index === 0) {
        const q1 = val.indexOf("'");
        if (q1 >= 0) {
          const q2 = val.indexOf("'", q1 + 1);
          if (q2 >= 0) {
            charset = val.substring(0, q1) || 'us-ascii';
            val = val.substring(q2 + 1);
          }
        }
      }
      const segBytes = percentDecodeBytes(val);
      for (const b of segBytes) bytes.push(b);
    } else {
      for (let i = 0; i < seg.value.length; i++) {
        bytes.push(seg.value.charCodeAt(i));
      }
    }
  }

  return decodeCharset(Buffer.from(bytes), charset);
}

function getFileName(headers: Map<string, string>): string | null {
  const cd = headers.get('content-disposition');
  if (cd) {
    const cdParsed = parseContentDisposition(cd);
    const rfc2231 = getRfc2231Param(cdParsed.params, 'filename');
    if (rfc2231 !== null) return rfc2231;
    const regular = cdParsed.params.get('filename');
    if (regular !== undefined) return decodeEncodedWords(regular);
  }

  const ct = headers.get('content-type');
  if (ct) {
    const ctParsed = parseContentType(ct);
    const rfc2231 = getRfc2231Param(ctParsed.params, 'name');
    if (rfc2231 !== null) return rfc2231;
    const regular = ctParsed.params.get('name');
    if (regular !== undefined) return decodeEncodedWords(regular);
  }

  return null;
}

// ============ Multipart Parsing ============
function isDelimiterLine(line: string, boundary: string): boolean {
  const prefix = '--' + boundary;
  if (!line.startsWith(prefix)) return false;
  const rest = line.substring(prefix.length);
  return /^[ \t]*$/.test(rest);
}

function isCloseDelimiterLine(line: string, boundary: string): boolean {
  const prefix = '--' + boundary + '--';
  if (!line.startsWith(prefix)) return false;
  const rest = line.substring(prefix.length);
  return /^[ \t]*$/.test(rest);
}

function parseMultipart(body: Buffer, boundary: string, lineBreak: string): Entity[] {
  const parts: Entity[] = [];
  const lb = Buffer.from(lineBreak);
  let pos = 0;
  let inPart = false;
  let partStart = 0;

  while (pos <= body.length) {
    let lineEnd = body.indexOf(lb, pos);
    let lineBreakLen = lb.length;
    if (lineEnd === -1) {
      lineEnd = body.length;
      lineBreakLen = 0;
    }

    const line = body.slice(pos, lineEnd).toString('latin1');

    if (!inPart) {
      if (isDelimiterLine(line, boundary)) {
        inPart = true;
        partStart = lineEnd + lineBreakLen;
      }
    } else {
      if (isCloseDelimiterLine(line, boundary)) {
        let partEnd = pos;
        if (partEnd > partStart && partEnd >= lb.length) {
          if (body.slice(partEnd - lb.length, partEnd).equals(lb)) {
            partEnd -= lb.length;
          }
        }
        if (partEnd < partStart) partEnd = partStart;
        parts.push(parseEntity(body.slice(partStart, partEnd), lineBreak));
        inPart = false;
        break;
      } else if (isDelimiterLine(line, boundary)) {
        let partEnd = pos;
        if (partEnd > partStart && partEnd >= lb.length) {
          if (body.slice(partEnd - lb.length, partEnd).equals(lb)) {
            partEnd -= lb.length;
          }
        }
        if (partEnd < partStart) partEnd = partStart;
        parts.push(parseEntity(body.slice(partStart, partEnd), lineBreak));
        partStart = lineEnd + lineBreakLen;
      }
    }

    pos = lineEnd + lineBreakLen;
  }

  return parts;
}

// ============ Tree Printing ============
function printTree(entity: Entity, indent: number, lineBreak: string): void {
  const prefix = '  '.repeat(indent);
  const ct = entity.headers.get('content-type');
  const cd = entity.headers.get('content-disposition');
  const cte = (entity.headers.get('content-transfer-encoding') || '7bit').toLowerCase();

  let type = 'text';
  let subtype = 'plain';
  let charset = 'us-ascii';
  let ctParams: Map<string, string> = new Map();

  if (ct) {
    const parsed = parseContentType(ct);
    type = parsed.type;
    subtype = parsed.subtype;
    ctParams = parsed.params;
    if (type === 'text') {
      charset = (parsed.params.get('charset') || 'us-ascii').toLowerCase();
    }
  }

  let dispType: string | null = null;
  if (cd) {
    const parsed = parseContentDisposition(cd);
    dispType = parsed.type;
  }

  if (type === 'multipart') {
    const boundary = ctParams.get('boundary');
    let parts: Entity[] = [];
    if (boundary) {
      parts = parseMultipart(entity.body, boundary, lineBreak);
    }
    console.log(`${prefix}multipart/${subtype} parts=${parts.length}`);
    for (const part of parts) {
      printTree(part, indent + 1, lineBreak);
    }
  } else if (type === 'text' && dispType !== 'attachment') {
    const decoded = decodeCTE(entity.body, cte, lineBreak);
    let text = decodeCharset(decoded, charset);
    text = text.replace(/\r\n/g, '\n').replace(/\r/g, '\n');
    const charCount = Array.from(text).length;
    console.log(`${prefix}text/${subtype} charset=${charset} cte=${cte} chars=${charCount}`);
    console.log(`${prefix}  ${quotedString(text)}`);
  } else {
    const decoded = decodeCTE(entity.body, cte, lineBreak);
    const size = decoded.length;
    const crc = crc32(decoded);
    const name = getFileName(entity.headers);
    const nameStr = name !== null ? quotedString(name) : '-';
    const dispStr = dispType || '-';
    console.log(`${prefix}${type}/${subtype} cte=${cte} disposition=${dispStr} name=${nameStr} size=${size} crc32=${crc.toString(16).padStart(8, '0')}`);
  }
}

// ============ File Processing ============
function processFile(filePath: string, fileName: string): void {
  const content = fs.readFileSync(filePath);

  let hasCRLF = false;
  for (let i = 0; i < content.length - 1; i++) {
    if (content[i] === 0x0D && content[i + 1] === 0x0A) { hasCRLF = true; break; }
  }
  const lb = hasCRLF ? '\r\n' : '\n';

  const message = parseEntity(content, lb);

  const from = message.headers.get('from');
  const subject = message.headers.get('subject');
  console.log(`From: ${from !== undefined ? quotedString(decodeEncodedWords(from)) : '-'}`);
  console.log(`Subject: ${subject !== undefined ? quotedString(decodeEncodedWords(subject)) : '-'}`);

  printTree(message, 0, lb);
}

// ============ Entry Point ============
function main(): void {
  const dir = process.argv[2];
  const files = fs.readdirSync(dir).filter(f => f.endsWith('.eml'));
  files.sort((a, b) => Buffer.from(a).compare(Buffer.from(b)));

  let first = true;
  for (const file of files) {
    if (!first) console.log('');
    first = false;
    processFile(path.join(dir, file), file);
  }
}

main();

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include <dirent.h>
#include <stdint.h>
#include <sys/stat.h>

/* ============ Dynamic Buffer ============ */
typedef struct { unsigned char *d; size_t len, cap; } Buf;
static void buf_init(Buf *b){b->d=NULL;b->len=b->cap=0;}
static void buf_res(Buf *b,size_t n){if(b->len+n>b->cap){b->cap=(b->len+n)*2+64;b->d=realloc(b->d,b->cap);}}
static void buf_ap(Buf *b,const void *d,size_t n){buf_res(b,n);memcpy(b->d+b->len,d,n);b->len+=n;}
static void buf_ap1(Buf *b,unsigned char c){buf_res(b,1);b->d[b->len++]=c;}
static void buf_apstr(Buf *b,const char *s){buf_ap(b,s,strlen(s));}

/* ============ Utilities ============ */
static char *xstrdup(const char *s){char*r=malloc(strlen(s)+1);strcpy(r,s);return r;}
static char *xstrndup(const char *s,size_t n){char*r=malloc(n+1);memcpy(r,s,n);r[n]=0;return r;}
static int scasecmp(const char*a,const char*b){while(*a&&*b){int d=tolower((unsigned char)*a)-tolower((unsigned char)*b);if(d)return d;a++;b++;}return(unsigned char)*a-(unsigned char)*b;}
static int is_hex(char c){return(c>='0'&&c<='9')||(c>='a'&&c<='f')||(c>='A'&&c<='F');}
static int hex_val(char c){if(c>='0'&&c<='9')return c-'0';if(c>='a'&&c<='f')return c-'a'+10;return c-'A'+10;}
static int is_b64(char c){return(c>='A'&&c<='Z')||(c>='a'&&c<='z')||(c>='0'&&c<='9')||c=='+'||c=='/';}
static int b64_val(char c){if(c>='A'&&c<='Z')return c-'A';if(c>='a'&&c<='z')return c-'a'+26;if(c>='0'&&c<='9')return c-'0'+52;if(c=='+')return 62;return 63;}

/* ============ CRC-32 ============ */
static uint32_t crct[256];
static void init_crc(void){for(uint32_t i=0;i<256;i++){uint32_t c=i;for(int j=0;j<8;j++)c=(c&1)?(c>>1)^0xEDB88320:c>>1;crct[i]=c;}}
static uint32_t crc32(const unsigned char*d,size_t n){uint32_t c=0xFFFFFFFF;for(size_t i=0;i<n;i++)c=crct[(c^d[i])&0xFF]^(c>>8);return c^0xFFFFFFFF;}

/* ============ Base64 decode ============ */
static void decode_b64(Buf *out,const unsigned char*data,size_t len){
    int vals[4],n=0;
    for(size_t i=0;i<len;i++){
        if(data[i]=='=')break;
        if(!is_b64(data[i]))continue;
        vals[n++]=b64_val(data[i]);
        if(n==4){buf_ap1(out,(vals[0]<<2)|(vals[1]>>4));buf_ap1(out,((vals[1]&0xF)<<4)|(vals[2]>>2));buf_ap1(out,((vals[2]&3)<<6)|vals[3]);n=0;}
    }
    if(n>=2){buf_ap1(out,(vals[0]<<2)|(vals[1]>>4));if(n>=3){buf_ap1(out,((vals[1]&0xF)<<4)|(vals[2]>>2));if(n>=4)buf_ap1(out,((vals[2]&3)<<6)|vals[3]);}}
}

/* ============ Quoted-Printable decode ============ */
static void decode_qp(Buf *out,const unsigned char*data,size_t len,int lb_len){
    /* First pass: split into lines, strip trailing ws, handle soft line breaks */
    Buf joined; buf_init(&joined);
    size_t pos=0;
    while(pos<len){
        size_t lb_pos=pos;
        while(lb_pos<len){if(lb_len==2&&lb_pos+1<len&&data[lb_pos]=='\r'&&data[lb_pos+1]=='\n')break;if(lb_len==1&&data[lb_pos]=='\n')break;lb_pos++;}
        size_t line_len=lb_pos-pos;
        /* strip trailing spaces/tabs */
        while(line_len>0&&(data[pos+line_len-1]==' '||data[pos+line_len-1]=='\t'))line_len--;
        int soft=0;
        if(line_len>0&&data[pos+line_len-1]=='='){soft=1;line_len--;}
        buf_ap(&joined,data+pos,line_len);
        if(!soft&&lb_pos<len){buf_ap(&joined,data+lb_pos,lb_len);}
        pos=(lb_pos<len)?lb_pos+lb_len:len;
    }
    /* Second pass: decode =XY */
    for(size_t i=0;i<joined.len;i++){
        if(joined.d[i]=='='&&i+2<joined.len&&is_hex(joined.d[i+1])&&is_hex(joined.d[i+2])){
            buf_ap1(out,(unsigned char)(hex_val(joined.d[i+1])*16+hex_val(joined.d[i+2])));
            i+=2;
        } else {
            buf_ap1(out,joined.d[i]);
        }
    }
    free(joined.d);
}

/* ============ Charset decode to UTF-8 ============ */
static void encode_cp(Buf *out,unsigned int cp){
    if(cp<0x80){buf_ap1(out,cp);}
    else if(cp<0x800){buf_ap1(out,0xC0|(cp>>6));buf_ap1(out,0x80|(cp&0x3F));}
    else if(cp<0x10000){buf_ap1(out,0xE0|(cp>>12));buf_ap1(out,0x80|((cp>>6)&0x3F));buf_ap1(out,0x80|(cp&0x3F));}
    else{buf_ap1(out,0xF0|(cp>>18));buf_ap1(out,0x80|((cp>>12)&0x3F));buf_ap1(out,0x80|((cp>>6)&0x3F));buf_ap1(out,0x80|(cp&0x3F));}
}
static const unsigned int cp1252[32]={0x20AC,0x0081,0x201A,0x0192,0x201E,0x2026,0x2020,0x2021,0x02C6,0x2030,0x0160,0x2039,0x0152,0x008D,0x017D,0x008F,0x0090,0x2018,0x2019,0x201C,0x201D,0x2022,0x2013,0x2014,0x02DC,0x2122,0x0161,0x203A,0x0153,0x009D,0x017E,0x0178};
static void decode_charset(Buf *out,const unsigned char*data,size_t len,const char*cs){
    if(!cs||!strcasecmp_(cs,"us-ascii")||!strcasecmp_(cs,"utf-8")){
        /* us-ascii: treat bytes as code points (same as iso-8859-1 for safety) */
        if(!cs||!strcasecmp_(cs,"us-ascii")){
            for(size_t i=0;i<len;i++) encode_cp(out,data[i]);
        } else {
            buf_ap(out,data,len); /* utf-8: pass through */
        }
    } else if(!strcasecmp_(cs,"iso-8859-1")){
        for(size_t i=0;i<len;i++) encode_cp(out,data[i]);
    } else if(!strcasecmp_(cs,"windows-1252")){
        for(size_t i=0;i<len;i++){
            if(data[i]>=0x80&&data[i]<=0x9F) encode_cp(out,cp1252[data[i]-0x80]);
            else encode_cp(out,data[i]);
        }
    } else {
        /* unknown charset: treat as iso-8859-1 */
        for(size_t i=0;i<len;i++) encode_cp(out,data[i]);
    }
}

/* ============ UTF-8 utilities ============ */
static size_t count_cp(const unsigned char*d,size_t len){
    size_t n=0;
    for(size_t i=0;i<len;i++){if((d[i]&0xC0)!=0x80)n++;}
    return n;
}
static unsigned int utf8_decode(const unsigned char*d,size_t len,size_t*used){
    if(len==0){*used=0;return 0;}
    if(d[0]<0x80){*used=1;return d[0];}
    if(d[0]<0xC0){*used=1;return 0xFFFD;}
    if(d[0]<0xE0){if(len<2){*used=1;return 0xFFFD;}*used=2;return((d[0]&0x1F)<<6)|(d[1]&0x3F);}
    if(d[0]<0xF0){if(len<3){*used=1;return 0xFFFD;}*used=3;return((d[0]&0x0F)<<12)|((d[1]&0x3F)<<6)|(d[2]&0x3F);}
    if(len<4){*used=1;return 0xFFFD;}*used=4;return((d[0]&0x07)<<18)|((d[1]&0x3F)<<12)|((d[2]&0x3F)<<6)|(d[3]&0x3F);
}

/* ============ RFC 2047 Encoded Words ============ */
typedef struct{size_t start,end;char*charset;char enc;char*etext;} EWord;
static int try_parse_ew(const char*s,size_t len,size_t pos,EWord*ew){
    if(pos+2>len||s[pos]!='='||s[pos+1]!='?')return 0;
    size_t p=pos+2;
    size_t cs_start=p;
    while(p<len&&s[p]!='?'&&s[p]!=' '&&s[p]!='\t')p++;
    if(p==cs_start||p>=len||s[p]!='?')return 0;
    size_t cs_end=p; p++;
    if(p>=len)return 0;
    char enc=s[p];
    if(enc!='B'&&enc!='b'&&enc!='Q'&&enc!='q')return 0;
    p++;
    if(p>=len||s[p]!='?')return 0;
    p++;
    size_t et_start=p;
    while(p<len&&s[p]!='?'&&s[p]!=' '&&s[p]!='\t')p++;
    if(p+1>=len||s[p]!='?'||s[p+1]!='=')return 0;
    size_t et_end=p;
    ew->start=pos; ew->end=p+2;
    ew->charset=xstrndup(s+cs_start,cs_end-cs_start);
    ew->enc=enc;
    ew->etext=xstrndup(s+et_start,et_end-et_start);
    return 1;
}
static void normalize_charset(char*cs){
    /* lowercase and strip *language */
    char*star=strchr(cs,'*');
    if(star)*star=0;
    for(char*p=cs;*p;p++)*p=tolower((unsigned char)*p);
}
static void decode_ew_bytes(Buf*out,const EWord*ew){
    if(ew->enc=='B'||ew->enc=='b'){
        decode_b64(out,(unsigned char*)ew->etext,strlen(ew->etext));
    } else {
        const char*s=ew->etext;size_t len=strlen(s);
        for(size_t i=0;i<len;i++){
            if(s[i]=='_') buf_ap1(out,0x20);
            else if(s[i]=='='&&i+2<len&&is_hex(s[i+1])&&is_hex(s[i+2])){
                buf_ap1(out,(unsigned char)(hex_val(s[i+1])*16+hex_val(s[i+2])));i+=2;
            } else buf_ap1(out,(unsigned char)s[i]);
        }
    }
}
static char*decode_ew(const char*input){
    if(!input)return NULL;
    size_t len=strlen(input);
    /* Find all encoded words */
    EWord *ews=NULL; int new=0,cap=0;
    size_t pos=0;
    while(pos<len){
        size_t p=pos;
        int found=0;
        while(p+1<len){
            if(s[p]=='='&&s[p+1]=='?'){
                EWord ew;
                if(try_parse_ew(input,len,p,&ew)){
                    if(new==cap){cap=cap?cap*2:8;ews=realloc(ews,cap*sizeof(EWord));}
                    ews[new++]=ew;
                    p=ew.end;found=1;break;
                }
            }
            p++;
        }
        if(!found)break;
        pos=p;
    }
    if(new==0)return xstrdup(input);
    /* Build output */
    Buf out; buf_init(&out);
    int ei=0;
    size_t ipos=0;
    while(ipos<len){
        if(ei<new&&ipos==ews[ei].start){
            /* Collect run of adjacent same-charset ew */
            char*cs=normalize_charset(ews[ei].charset);
            char cs_norm[256]; strncpy(cs_norm,ews[ei].charset,255);cs_norm[255]=0;
            normalize_charset(cs_norm);
            Buf bytes; buf_init(&bytes);
            decode_ew_bytes(&bytes,&ews[ei]);
            size_t cur_end=ews[ei].end;
            ei++;
            while(ei<new){
                /* Check if adjacent: only spaces/tabs between cur_end and ews[ei].start */
                int adj=1;
                for(size_t k=cur_end;k<ews[ei].start;k++){
                    if(input[k]!=' '&&input[k]!='\t'){adj=0;break;}
                }
                if(!adj)break;
                /* Check same charset */
                char cs2[256];strncpy(cs2,ews[ei].charset,255);cs2[255]=0;normalize_charset(cs2);
                if(scasecmp(cs_norm,cs2)!=0)break;
                decode_ew_bytes(&bytes,&ews[ei]);
                cur_end=ews[ei].end;
                ei++;
            }
            /* Decode bytes with charset */
            Buf decoded; buf_init(&decoded);
            decode_charset(&decoded,bytes.d,bytes.len,cs_norm);
            buf_ap(&out,decoded.d,decoded.len);
            free(bytes.d);free(decoded.d);
            ipos=cur_end;
            /* Skip whitespace between adjacent ew with different charset */
            while(ei<new&&ipos==ews[ei].start){
                /* adjacent with different charset: skip whitespace before it */
                /* Actually we already handled this: if not same charset, we broke out.
                   But the whitespace between them should still be removed. */
                break;
            }
            /* Skip whitespace between adjacent ew (different charset) */
            while(ei<new){
                int adj=1;
                for(size_t k=cur_end;k<ews[ei].start;k++){if(input[k]!=' '&&input[k]!='\t'){adj=0;break;}}
                if(!adj)break;
                /* Different charset adjacent: skip whitespace, decode separately */
                ipos=ews[ei].start;
                break;
            }
        } else if(ei<new&&ipos<ews[ei].start){
            /* Literal text before next ew */
            /* Check if this literal is whitespace between two adjacent ew */
            int skip=0;
            if(ei>0){
                size_t prev_end=ews[ei-1].end;
                if(ipos==prev_end){
                    /* This literal is between two ew */
                    int all_ws=1;
                    for(size_t k=ipos;k<ews[ei].start;k++){if(input[k]!=' '&&input[k]!='\t'){all_ws=0;break;}}
                    if(all_ws)skip=1;
                }
            }
            if(!skip) buf_ap(&out,input+ipos,ews[ei].start-ipos);
            ipos=ews[ei].start;
        } else {
            buf_ap1(&out,(unsigned char)input[ipos]);
            ipos++;
        }
    }
    buf_ap1(&out,0);
    for(int i=0;i<new;i++){free(ews[i].charset);free(ews[i].etext);}
    free(ews);
    return (char*)out.d;
}

/* ============ Parameter parsing ============ */
typedef struct{char*name;char*value;} Param;
typedef struct{char*type;char*subtype;Param*params;int nparams;} CT;

static char*parse_token_or_qstring(const char*s,size_t len,size_t*pos){
    while(*pos<len&&(s[*pos]==' '||s[*pos]=='\t'))(*pos)++;
    if(*pos>=len)return xstrdup("");
    if(s[*pos]=='"'){
        (*pos)++;
        Buf b;buf_init(&b);
        while(*pos<len&&s[*pos]!='"'){
            if(s[*pos]=='\\'&&*pos+1<len){(*pos)++;buf_ap1(&b,s[*pos]);(*pos)++;}
            else{buf_ap1(&b,s[*pos]);(*pos)++;}
        }
        if(*pos<len)(*pos)++; /* skip closing quote */
        buf_ap1(&b,0);
        return (char*)b.d;
    } else {
        size_t start=*pos;
        while(*pos<len&&s[*pos]!=';'&&s[*pos]!=' '&&s[*pos]!='\t')(*pos)++;
        return xstrndup(s+start,*pos-start);
    }
}

static CT parse_ct(const char*val){
    CT ct={0};
    ct.params=NULL;ct.nparams=0;
    if(!val||!*val){ct.type=xstrdup("text");ct.subtype=xstrdup("plain");return ct;}
    size_t len=strlen(val),pos=0;
    /* parse type */
    while(pos<len&&(val[pos]==' '||val[pos]=='\t'))pos++;
    size_t ts=pos;
    while(pos<len&&val[pos]!='/')pos++;
    ct.type=xstrndup(val+ts,pos-ts);
    for(char*p=ct.type;*p;p++)*p=tolower((unsigned char)*p);
    if(pos<len)pos++; /* skip / */
    while(pos<len&&(val[pos]==' '||val[pos]=='\t'))pos++;
    ts=pos;
    while(pos<len&&val[pos]!=';')pos++;
    /* trim trailing spaces/tabs from subtype */
    size_t te=pos;
    while(te>ts&&(val[te-1]==' '||val[te-1]=='\t'))te--;
    ct.subtype=xstrndup(val+ts,te-ts);
    for(char*p=ct.subtype;*p;p++)*p=tolower((unsigned char)*p);
    /* parse parameters */
    int pcap=0;
    while(pos<len){
        while(pos<len&&(val[pos]==' '||val[pos]=='\t'))pos++;
        if(pos>=len||val[pos]!=';')break;
        pos++; /* skip ; */
        while(pos<len&&(val[pos]==' '||val[pos]=='\t'))pos++;
        /* attr name */
        size_t as=pos;
        while(pos<len&&val[pos]!='='&&val[pos]!=' '&&val[pos]!='\t')pos++;
        size_t ae=pos;
        while(ae>as&&(val[ae-1]==' '||val[ae-1]=='\t'))ae--;
        char*aname=xstrndup(val+as,ae-as);
        for(char*p=aname;*p;p++)*p=tolower((unsigned char)*p);
        /* skip spaces/tabs before = */
        while(pos<len&&(val[pos]==' '||val[pos]=='\t'))pos++;
        if(pos<len&&val[pos]=='=')pos++;
        while(pos<len&&(val[pos]==' '||val[pos]=='\t'))pos++;
        char*avalue=parse_token_or_qstring(val,len,&pos);
        if(ct.nparams==pcap){pcap=pcap?pcap*2:8;ct.params=realloc(ct.params,pcap*sizeof(Param));}
        ct.params[ct.nparams].name=aname;
        ct.params[ct.nparams].value=avalue;
        ct.nparams++;
    }
    return ct;
}

static char*find_param(CT*ct,const char*name){
    for(int i=0;i<ct->nparams;i++)
        if(scasecmp(ct->params[i].name,name)==0)return ct->params[i].value;
    return NULL;
}

/* ============ RFC 2231 decode ============ */
static void percent_decode(Buf*out,const char*s,size_t len){
    for(size_t i=0;i<len;i++){
        if(s[i]=='%'&&i+2<len&&is_hex(s[i+1])&&is_hex(s[i+2])){
            buf_ap1(out,(unsigned char)(hex_val(s[i+1])*16+hex_val(s[i+2])));
            i+=2;
        } else buf_ap1(out,(unsigned char)s[i]);
    }
}
static char*decode_rfc2231(CT*ct,const char*attr){
    /* Check for single form: attr* */
    char sname[256];
    snprintf(sname,sizeof(sname),"%s*",attr);
    char*sv=find_param(ct,sname);
    if(sv){
        /* percent-encoded with charset'language' prefix */
        char*q1=strchr(sv,'\'');
        if(!q1)return xstrdup(sv);
        char*q2=strchr(q1+1,'\'');
        if(!q2)return xstrdup(sv);
        char*cs=xstrndup(sv,q1-sv);
        for(char*p=cs;*p;p++)*p=tolower((unsigned char)*p);
        const char*vstart=q2+1;
        Buf bytes;buf_init(&bytes);
        percent_decode(&bytes,vstart,strlen(vstart));
        Buf out;buf_init(&out);
        decode_charset(&out,bytes.d,bytes.len,cs);
        buf_ap1(&out,0);
        free(cs);free(bytes.d);
        return (char*)out.d;
    }
    /* Check for continuation segments: attr*0, attr*1, ... or attr*0*, attr*1*, ... */
    int segs[64];char*segvals[64];int segpct[64];int nsegs=0;
    for(int i=0;i<ct->nparams;i++){
        const char*pn=ct->params[i].name;
        size_t alen=strlen(attr);
        if(strncmp(pn,attr,alen)!=0)continue;
        if(pn[alen]!='*')continue;
        const char*np=pn+alen+1;
        int pct=0;
        int num=atoi(np);
        const char*ep=np;
        while(*ep&&isdigit(*ep))ep++;
        if(*ep=='*'){pct=1;ep++;}
        if(*ep!=0)continue;
        if(nsegs<64){segs[nsegs]=num;segvals[nsegs]=ct->params[i].value;segpct[nsegs]=pct;nsegs++;}
    }
    if(nsegs==0)return NULL;
    /* Sort by segment number */
    for(int i=0;i<nsegs-1;i++)for(int j=i+1;j<nsegs;j++){
        if(segs[j]<segs[i]){int t=segs[i];segs[i]=segs[j];segs[j]=t;
            char*tv=segvals[i];segvals[i]=segvals[j];segvals[j]=tv;
            int tp=segpct[i];segpct[i]=segpct[j];segpct[j]=tp;}
    }
    /* Find charset from first percent-encoded segment */
    char*cs=NULL;
    for(int i=0;i<nsegs;i++){
        if(segpct[i]){
            char*q1=strchr(segvals[i],'\'');
            if(q1){char*q2=strchr(q1+1,'\'');
                if(q2){cs=xstrndup(segvals[i],q1-segvals[i]);for(char*p=cs;*p;p++)*p=tolower((unsigned char)*p);
                    /* Adjust: skip charset'language' from this segment */
                    segvals[i]=q2+1;
                }
            }
            break;
        }
    }
    if(!cs)cs=xstrdup("us-ascii");
    /* Concatenate bytes */
    Buf bytes;buf_init(&bytes);
    for(int i=0;i<nsegs;i++){
        if(segpct[i]) percent_decode(&bytes,segvals[i],strlen(segvals[i]));
        else buf_apstr(&bytes,segvals[i]);
    }
    Buf out;buf_init(&out);
    decode_charset(&out,bytes.d,bytes.len,cs);
    buf_ap1(&out,0);
    free(cs);free(bytes.d);
    return (char*)out.d;
}

/* ============ Header parsing ============ */
typedef struct{char*name;char*value;} Header;
static Header*find_header(Header*hs,int n,const char*name){
    for(int i=0;i<n;i++)if(scasecmp(hs[i].name,name)==0)return &hs[i];
    return NULL;
}

/* ============ Entity structure ============ */
typedef struct Entity{
    Header*headers;int nheaders;
    unsigned char*body;size_t body_len;
    struct Entity**parts;int nparts;
    CT ct;
    char*cte;
    char*disp_type; /* "inline","attachment", or NULL */
    CT disp;
} Entity;

/* ============ Line utilities ============ */
static size_t find_lb(const unsigned char*d,size_t len,size_t pos,int lb_len){
    while(pos<len){
        if(lb_len==2){if(pos+1<len&&d[pos]=='\r'&&d[pos+1]=='\n')return pos;}
        else{if(d[pos]=='\n')return pos;}
        pos++;
    }
    return len;
}

/* ============ Parse entity ============ */
static Entity*parse_entity(const unsigned char*data,size_t len,int lb_len);

static Entity*parse_entity(const unsigned char*data,size_t len,int lb_len){
    Entity*e=calloc(1,sizeof(Entity));
    /* Find header/body separator (first empty line) */
    size_t pos=0;
    int hdr_end=-1;
    while(pos<=len){
        size_t lb=find_lb(data,len,pos,lb_len);
        if(lb==pos){/* empty line found */hdr_end=pos;break;}
        if(lb>=len)break;
        pos=lb+lb_len;
    }
    if(hdr_end<0){
        /* No empty line: no headers, body is everything */
        e->body=(unsigned char*)data;e->body_len=len;
    } else {
        /* Parse headers from data[0..hdr_end) */
        size_t hp=0;
        int hcap=0;
        while(hp<hdr_end){
            size_t lb=find_lb(data,hdr_end,hp,lb_len);
            size_t line_len=lb-hp;
            /* Unfold: check if next line starts with space/tab */
            size_t next=lb+lb_len;
            while(next<hdr_end&&(data[next]==' '||data[next]=='\t')){
                size_t lb2=find_lb(data,hdr_end,next,lb_len);
                /* Append the continuation (including the leading space/tab) */
                line_len=lb2-hp;
                next=lb2+lb_len;
                lb=lb2;
            }
            /* Parse Name: value */
            size_t colon=hp;
            while(colon<hp+line_len&&data[colon]!=':')colon++;
            if(colon<hp+line_len){
                char*name=xstrndup((char*)data+hp,colon-hp);
                for(char*p=name;*p;p++)*p=tolower((unsigned char)*p);
                /* value: after colon, trim spaces/tabs */
                size_t vs=colon+1;
                while(vs<hp+line_len&&(data[vs]==' '||data[vs]=='\t'))vs++;
                size_t ve=hp+line_len;
                while(ve>vs&&(data[ve-1]==' '||data[ve-1]=='\t'))ve--;
                char*value=xstrndup((char*)data+vs,ve-vs);
                if(e->nheaders==hcap){hcap=hcap?hcap*2:8;e->headers=realloc(e->headers,hcap*sizeof(Header));}
                e->headers[e->nheaders].name=name;
                e->headers[e->nheaders].value=value;
                e->nheaders++;
            }
            hp=next;
        }
        /* Body starts after the empty line */
        size_t body_start=hdr_end+lb_len;
        e->body=(unsigned char*)data+body_start;
        e->body_len=(body_start<=len)?len-body_start:0;
    }
    /* Parse Content-Type */
    Header*h=find_header(e->headers,e->nheaders,"content-type");
    if(h)e->ct=parse_ct(h->value);
    else{e->ct.type=xstrdup("text");e->ct.subtype=xstrdup("plain");e->ct.params=NULL;e->ct.nparams=0;}
    /* Parse CTE */
    h=find_header(e->headers,e->nheaders,"content-transfer-encoding");
    if(h){e->cte=xstrdup(h->value);for(char*p=e->cte;*p;p++)*p=tolower((unsigned char)*p);}
    else e->cte=xstrdup("7bit");
    /* Parse Content-Disposition */
    h=find_header(e->headers,e->nheaders,"content-disposition");
    if(h){
        e->disp=parse_ct(h->value);
        /* The "type" field of disp is the disposition type */
        e->disp_type=e->disp.type;
    } else {
        e->disp.type=NULL;e->disp.subtype=NULL;e->disp.params=NULL;e->disp.nparams=0;
        e->disp_type=NULL;
    }
    /* If multipart, split into parts */
    if(scasecmp(e->ct.type,"multipart")==0){
        char*boundary=find_param(&e->ct,"boundary");
        if(boundary){
            /* Find delimiters in body */
            size_t blen=strlen(boundary);
            size_t bpos=0;
            int in_parts=0;
            size_t part_start=0;
            int pcap=0;
            while(bpos<e->body_len){
                size_t lb=find_lb(e->body,e->body_len,bpos,lb_len);
                size_t line_len=lb-bpos;
                /* Check if this line is a delimiter */
                int is_delim=0,is_close=0;
                if(line_len>=2+blen&&e->body[bpos]=='-'&&e->body[bpos+1]=='-'){
                    if(line_len>=2+blen+2&&memcmp(e->body+bpos+2,boundary,blen)==0&&e->body[bpos+2+blen]=='-'){
                        /* Check --B-- followed by only spaces/tabs */
                        size_t k=bpos+2+blen+2;
                        int ok=1;
                        while(k<lb){if(e->body[k]!=' '&&e->body[k]!='\t'){ok=0;break;}k++;}
                        if(ok)is_close=1;
                    }
                    if(!is_close&&line_len>=2+blen&&memcmp(e->body+bpos+2,boundary,blen)==0){
                        size_t k=bpos+2+blen;
                        int ok=1;
                        while(k<lb){if(e->body[k]!=' '&&e->body[k]!='\t'){ok=0;break;}k++;}
                        if(ok)is_delim=1;
                    }
                }
                if(is_delim||is_close){
                    if(in_parts){
                        /* Part content is from part_start to lb (minus trailing line break) */
                        size_t pl=lb-part_start;
                        /* Remove trailing line break */
                        if(pl>=2&&(size_t)lb_len==2&&part_start+pl-2<e->body_len&&e->body[part_start+pl-2]=='\r'&&e->body[part_start+pl-1]=='\n')pl-=2;
                        else if(pl>=1&&(size_t)lb_len==1&&part_start+pl-1<e->body_len&&e->body[part_start+pl-1]=='\n')pl-=1;
                        Entity*pe=parse_entity(e->body+part_start,pl,lb_len);
                        if(e->nparts==pcap){pcap=pcap?pcap*2:8;e->parts=realloc(e->parts,pcap*sizeof(Entity*));}
                        e->parts[e->nparts++]=pe;
                    }
                    if(is_close)break;
                    in_parts=1;
                    part_start=lb+lb_len;
                }
                bpos=(lb<e->body_len)?lb+lb_len:e->body_len;
            }
        }
    }
    return e;
}

/* ============ Quoted string output ============ */
static void print_quoted(FILE*f,const unsigned char*data,size_t len){
    fputc('"',f);
    size_t i=0;
    while(i<len){
        size_t used;
        unsigned int cp=utf8_decode(data+i,len-i,&used);
        if(cp=='\\')fputs("\\\\",f);
        else if(cp=='"')fputs("\\\"",f);
        else if(cp=='\n')fputs("\\n",f);
        else if(cp=='\t')fputs("\\t",f);
        else if(cp<0x20||(cp>=0x7F&&cp<=0x9F))fprintf(f,"\\u%04x",cp);
        else{
            /* output UTF-8 as-is */
            for(size_t j=0;j<used;j++)fputc(data[i+j],f);
        }
        i+=used;
    }
    fputc('"',f);
}

/* ============ Decode body ============ */
static void decode_body_cte(Buf*out,const unsigned char*body,size_t len,const char*cte,int lb_len){
    if(!strcmp(cte,"base64")){
        decode_b64(out,body,len);
    } else if(!strcmp(cte,"quoted-printable")){
        decode_qp(out,body,len,lb_len);
    } else {
        /* 7bit, 8bit, binary: pass through */
        buf_ap(out,body,len);
    }
}

/* ============ Get filename ============ */
static char*get_filename(Entity*e){
    /* 1. Content-Disposition filename in RFC 2231 form */
    char*r;
    r=decode_rfc2231(&e->disp,"filename");
    if(r)return r;
    /* 2. Content-Disposition filename (regular) */
    char*v=find_param(&e->disp,"filename");
    if(v)return decode_ew(v);
    /* 3. Content-Type name in RFC 2231 form */
    r=decode_rfc2231(&e->ct,"name");
    if(r)return r;
    /* 4. Content-Type name (regular) */
    v=find_param(&e->ct,"name");
    if(v)return decode_ew(v);
    return NULL;
}

/* ============ Print tree ============ */
static void print_tree(FILE*f,Entity*e,int indent,int lb_len){
    for(int i=0;i<indent;i++)fputs("  ",f);
    if(scasecmp(e->ct.type,"multipart")==0){
        fprintf(f,"multipart/%s parts=%d\n",e->ct.subtype,e->nparts);
        for(int i=0;i<e->nparts;i++)
            print_tree(f,e->parts[i],indent+1,lb_len);
    } else {
        int is_text=!scasecmp(e->ct.type,"text")&&(!e->disp_type||scasecmp(e->disp_type,"attachment")!=0);
        if(is_text){
            char*charset=find_param(&e->ct,"charset");
            char cs_buf[256];
            if(charset){strncpy(cs_buf,charset,255);cs_buf[255]=0;for(char*p=cs_buf;*p;p++)*p=tolower((unsigned char)*p);}
            else strcpy(cs_buf,"us-ascii");
            /* Decode body */
            Buf raw;buf_init(&raw);
            decode_body_cte(&raw,e->body,e->body_len,e->cte,lb_len);
            /* Decode charset */
            Buf utf8;buf_init(&utf8);
            decode_charset(&utf8,raw.d,raw.len,cs_buf);
            free(raw.d);
            /* Normalize line endings: CRLF->LF, lone CR->LF */
            Buf norm;buf_init(&norm);
            for(size_t i=0;i<utf8.len;i++){
                if(utf8.d[i]=='\r'){
                    if(i+1<utf8.len&&utf8.d[i+1]=='\n'){buf_ap1(&norm,'\n');i++;}
                    else buf_ap1(&norm,'\n');
                } else buf_ap1(&norm,utf8.d[i]);
            }
            free(utf8.d);
            size_t ncp=count_cp(norm.d,norm.len);
            fprintf(f,"text/%s charset=%s cte=%s chars=%zu\n",e->ct.subtype,cs_buf,e->cte,ncp);
            for(int i=0;i<indent+1;i++)fputs("  ",f);
            print_quoted(f,norm.d,norm.len);
            fputc('\n',f);
            free(norm.d);
        } else {
            /* Non-text part */
            Buf raw;buf_init(&raw);
            decode_body_cte(&raw,e->body,e->body_len,e->cte,lb_len);
            uint32_t c=crc32(raw.d,raw.len);
            char*fname=get_filename(e);
            char*fname_dec=NULL;
            if(fname)fname_dec=fname; /* already decoded */
            const char*disp=e->disp_type?e->disp_type:"-";
            fprintf(f,"%s/%s cte=%s disposition=%s name=",e->ct.type,e->ct.subtype,e->cte,disp);
            if(fname_dec)print_quoted(f,(unsigned char*)fname_dec,strlen(fname_dec));
            else fputc('-',f);
            fprintf(f," size=%zu crc32=%08x\n",raw.len,c);
            free(raw.d);
        }
    }
}

/* ============ Main ============ */
static int cmp_str(const void*a,const void*b){return strcmp(*(const char**)a,*(const char**)b);}

int main(int argc,char*argv[]){
    init_crc();
    if(argc<2){fprintf(stderr,"Usage: %s <dir>\n",argv[0]);return 1;}
    DIR*d=opendir(argv[1]);
    if(!d){perror("opendir");return 1;}
    char**files=NULL;int nf=0,fcap=0;
    struct dirent*de;
    while((de=readdir(d))){
        size_t nlen=strlen(de->d_name);
        if(nlen>4&&strcmp(de->d_name+nlen-4,".eml")==0){
            if(nf==fcap){fcap=fcap?fcap*2:16;files=realloc(files,fcap*sizeof(char*));}
            files[nf++]=xstrdup(de->d_name);
        }
    }
    closedir(d);
    qsort(files,nf,sizeof(char*),cmp_str);
    for(int fi=0;fi<nf;fi++){
        if(fi>0)fputc('\n',stdout);
        /* Read file */
        char path[4096];
        snprintf(path,sizeof(path),"%s/%s",argv[1],files[fi]);
        FILE*fp=fopen(path,"rb");
        if(!fp){perror(path);continue;}
        fseek(fp,0,SEEK_END);
        long fsz=ftell(fp);
        fseek(fp,0,SEEK_SET);
        unsigned char*fdata=malloc(fsz+1);
        size_t frd=fread(fdata,1,fsz,fp);
        fclose(fp);
        /* Detect line ending */
        int lb_len=1;
        for(size_t i=0;i+1<frd;i++){if(fdata[i]=='\r'&&fdata[i+1]=='\n'){lb_len=2;break;}}
        /* Parse */
        Entity*msg=parse_entity(fdata,frd,lb_len);
        /* Output */
        printf("== %s\n",files[fi]);
        Header*h=find_header(msg->headers,msg->nheaders,"from");
        if(h){char*dec=decode_ew(h->value);printf("From: ");print_quoted(stdout,(unsigned char*)dec,strlen(dec));printf("\n");free(dec);}
        else printf("From: -\n");
        h=find_header(msg->headers,msg->nheaders,"subject");
        if(h){char*dec=decode_ew(h->value);printf("Subject: ");print_quoted(stdout,(unsigned char*)dec,strlen(dec));printf("\n");free(dec);}
        else printf("Subject: -\n");
        print_tree(stdout,msg,0,lb_len);
        free(fdata);
    }
    for(int i=0;i<nf;i++)free(files[i]);
    free(files);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include <dirent.h>
#include <stdint.h>
#include <sys/stat.h>

/* ============ Dynamic Buffer ============ */
typedef struct { unsigned char *d; size_t len, cap; } Buf;
static void buf_init(Buf *b){b->d=NULL;b->len=b->cap=0;}
static void buf_res(Buf *b,size_t n){if(b->len+n>b->cap){b->cap=(b->len+n)*2+64;b->d=realloc(b->d,b->cap);}}
static void buf_ap(Buf *b,const void *d,size_t n){buf_res(b,n);memcpy(b->d+b->len,d,n);b->len+=n;}
static void buf_ap1(Buf *b,unsigned char c){buf_res(b,1);b->d[b->len++]=c;}
static void buf_apstr(Buf *b,const char *s){buf_ap(b,s,strlen(s));}

/* ============ Utilities ============ */
static char *xstrdup(const char *s){char*r=malloc(strlen(s)+1);strcpy(r,s);return r;}
static char *xstrndup(const char *s,size_t n){char*r=malloc(n+1);memcpy(r,s,n);r[n]=0;return r;}
static int scasecmp(const char*a,const char*b){while(*a&&*b){int d=tolower((unsigned char)*a)-tolower((unsigned char)*b);if(d)return d;a++;b++;}return(unsigned char)*a-(unsigned char)*b;}
static int is_hex(char c){return(c>='0'&&c<='9')||(c>='a'&&c<='f')||(c>='A'&&c<='F');}
static int hex_val(char c){if(c>='0'&&c<='9')return c-'0';if(c>='a'&&c<='f')return c-'a'+10;return c-'A'+10;}
static int is_b64(char c){return(c>='A'&&c<='Z')||(c>='a'&&c<='z')||(c>='0'&&c<='9')||c=='+'||c=='/';}
static int b64_val(char c){if(c>='A'&&c<='Z')return c-'A';if(c>='a'&&c<='z')return c-'a'+26;if(c>='0'&&c<='9')return c-'0'+52;if(c=='+')return 62;return 63;}

/* ============ CRC-32 ============ */
static uint32_t crct[256];
static void init_crc(void){for(uint32_t i=0;i<256;i++){uint32_t c=i;for(int j=0;j<8;j++)c=(c&1)?(c>>1)^0xEDB88320:c>>1;crct[i]=c;}}
static uint32_t crc32(const unsigned char*d,size_t n){uint32_t c=0xFFFFFFFF;for(size_t i=0;i<n;i++)c=crct[(c^d[i])&0xFF]^(c>>8);return c^0xFFFFFFFF;}

/* ============ Base64 decode ============ */
static void decode_b64(Buf *out,const unsigned char*data,size_t len){
    int vals[4],n=0;
    for(size_t i=0;i<len;i++){
        if(data[i]=='=')break;
        if(!is_b64((char)data[i]))continue;
        vals[n++]=b64_val((char)data[i]);
        if(n==4){buf_ap1(out,(vals[0]<<2)|(vals[1]>>4));buf_ap1(out,((vals[1]&0xF)<<4)|(vals[2]>>2));buf_ap1(out,((vals[2]&3)<<6)|vals[3]);n=0;}
    }
    if(n>=2){buf_ap1(out,(vals[0]<<2)|(vals[1]>>4));if(n>=3){buf_ap1(out,((vals[1]&0xF)<<4)|(vals[2]>>2));}}
}

/* ============ Quoted-Printable decode ============ */
static void decode_qp(Buf *out,const unsigned char*data,size_t len,int lb_len){
    Buf joined; buf_init(&joined);
    size_t pos=0;
    while(pos<len){
        size_t lb_pos=pos;
        while(lb_pos<len){
            if(lb_len==2&&lb_pos+1<len&&data[lb_pos]=='\r'&&data[lb_pos+1]=='\n')break;
            if(lb_len==1&&data[lb_pos]=='\n')break;
            lb_pos++;
        }
        size_t line_len=lb_pos-pos;
        /* strip trailing spaces/tabs */
        while(line_len>0&&(data[pos+line_len-1]==' '||data[pos+line_len-1]=='\t'))line_len--;
        int soft=0;
        if(line_len>0&&data[pos+line_len-1]=='='){soft=1;line_len--;}
        buf_ap(&joined,data+pos,line_len);
        if(!soft&&lb_pos<len){buf_ap(&joined,data+lb_pos,lb_len);}
        pos=(lb_pos<len)?lb_pos+lb_len:len;
    }
    /* Second pass: decode =XY */
    for(size_t i=0;i<joined.len;i++){
        if(joined.d[i]=='='&&i+2<joined.len&&is_hex((char)joined.d[i+1])&&is_hex((char)joined.d[i+2])){
            buf_ap1(out,(unsigned char)(hex_val((char)joined.d[i+1])*16+hex_val((char)joined.d[i+2])));
            i+=2;
        } else {
            buf_ap1(out,joined.d[i]);
        }
    }
    free(joined.d);
}

/* ============ Charset decode to UTF-8 ============ */
static void encode_cp(Buf *out,unsigned int cp){
    if(cp<0x80){buf_ap1(out,(unsigned char)cp);}
    else if(cp<0x800){buf_ap1(out,0xC0|(cp>>6));buf_ap1(out,0x80|(cp&0x3F));}
    else if(cp<0x10000){buf_ap1(out,0xE0|(cp>>12));buf_ap1(out,0x80|((cp>>6)&0x3F));buf_ap1(out,0x80|(cp&0x3F));}
    else{buf_ap1(out,0xF0|(cp>>18));buf_ap1(out,0x80|((cp>>12)&0x3F));buf_ap1(out,0x80|((cp>>6)&0x3F));buf_ap1(out,0x80|(cp&0x3F));}
}
static const unsigned int cp1252[32]={0x20AC,0x0081,0x201A,0x0192,0x201E,0x2026,0x2020,0x2021,0x02C6,0x2030,0x0160,0x2039,0x0152,0x008D,0x017D,0x008F,0x0090,0x2018,0x2019,0x201C,0x201D,0x2022,0x2013,0x2014,0x02DC,0x2122,0x0161,0x203A,0x0153,0x009D,0x017E,0x0178};
static void decode_charset(Buf *out,const unsigned char*data,size_t len,const char*cs){
    if(!cs||scasecmp(cs,"us-ascii")==0){
        for(size_t i=0;i<len;i++) encode_cp(out,data[i]);
    } else if(scasecmp(cs,"utf-8")==0){
        buf_ap(out,data,len);
    } else if(scasecmp(cs,"iso-8859-1")==0){
        for(size_t i=0;i<len;i++) encode_cp(out,data[i]);
    } else if(scasecmp(cs,"windows-1252")==0){
        for(size_t i=0;i<len;i++){
            if(data[i]>=0x80&&data[i]<=0x9F) encode_cp(out,cp1252[data[i]-0x80]);
            else encode_cp(out,data[i]);
        }
    } else {
        for(size_t i=0;i<len;i++) encode_cp(out,data[i]);
    }
}

/* ============ UTF-8 utilities ============ */
static size_t count_cp(const unsigned char*d,size_t len){
    size_t n=0;
    for(size_t i=0;i<len;i++){if((d[i]&0xC0)!=0x80)n++;}
    return n;
}
static unsigned int utf8_decode(const unsigned char*d,size_t len,size_t*used){
    if(len==0){*used=0;return 0;}
    if(d[0]<0x80){*used=1;return d[0];}
    if(d[0]<0xC0){*used=1;return 0xFFFD;}
    if(d[0]<0xE0){if(len<2){*used=1;return 0xFFFD;}*used=2;return((unsigned)(d[0]&0x1F)<<6)|(d[1]&0x3F);}
    if(d[0]<0xF0){if(len<3){*used=1;return 0xFFFD;}*used=3;return((unsigned)(d[0]&0x0F)<<12)|((unsigned)(d[1]&0x3F)<<6)|(d[2]&0x3F);}
    if(len<4){*used=1;return 0xFFFD;}*used=4;return((unsigned)(d[0]&0x07)<<18)|((unsigned)(d[1]&0x3F)<<12)|((unsigned)(d[2]&0x3F)<<6)|(d[3]&0x3F);
}

/* ============ RFC 2047 Encoded Words ============ */
typedef struct{size_t start,end;char*charset;char enc;char*etext;} EWord;

static int try_parse_ew(const char*s,size_t len,size_t pos,EWord*ew){
    if(pos+2>len||s[pos]!='='||s[pos+1]!='?')return 0;
    size_t p=pos+2;
    size_t cs_start=p;
    while(p<len&&s[p]!='?'&&s[p]!=' '&&s[p]!='\t')p++;
    if(p==cs_start||p>=len||s[p]!='?')return 0;
    size_t cs_end=p; p++;
    if(p>=len)return 0;
    char enc=s[p];
    if(enc!='B'&&enc!='b'&&enc!='Q'&&enc!='q')return 0;
    p++;
    if(p>=len||s[p]!='?')return 0;
    p++;
    size_t et_start=p;
    while(p<len&&s[p]!='?'&&s[p]!=' '&&s[p]!='\t')p++;
    if(p+1>=len||s[p]!='?'||s[p+1]!='=')return 0;
    size_t et_end=p;
    ew->start=pos; ew->end=p+2;
    ew->charset=xstrndup(s+cs_start,cs_end-cs_start);
    ew->enc=enc;
    ew->etext=xstrndup(s+et_start,et_end-et_start);
    return 1;
}

static void normalize_charset(char*cs){
    char*star=strchr(cs,'*');
    if(star)*star=0;
    for(char*p=cs;*p;p++)*p=tolower((unsigned char)*p);
}

static void decode_ew_bytes(Buf*out,const EWord*ew){
    if(ew->enc=='B'||ew->enc=='b'){
        decode_b64(out,(unsigned char*)ew->etext,strlen(ew->etext));
    } else {
        const char*s=ew->etext;size_t len=strlen(s);
        for(size_t i=0;i<len;i++){
            if(s[i]=='_') buf_ap1(out,0x20);
            else if(s[i]=='='&&i+2<len&&is_hex(s[i+1])&&is_hex(s[i+2])){
                buf_ap1(out,(unsigned char)(hex_val(s[i+1])*16+hex_val(s[i+2])));i+=2;
            } else buf_ap1(out,(unsigned char)s[i]);
        }
    }
}

static char*decode_ew(const char*input){
    if(!input)return xstrdup("");
    size_t len=strlen(input);
    /* Find all encoded words */
    EWord *ews=NULL; int new=0,cap=0;
    size_t pos=0;
    while(pos<len){
        if(pos+1<len&&input[pos]=='='&&input[pos+1]=='?'){
            EWord ew;
            if(try_parse_ew(input,len,pos,&ew)){
                if(new==cap){cap=cap?cap*2:8;ews=realloc(ews,cap*sizeof(EWord));}
                ews[new++]=ew;
                pos=ew.end;
                continue;
            }
        }
        pos++;
    }
    if(new==0)return xstrdup(input);
    /* Build output */
    Buf out; buf_init(&out);
    int ei=0;
    size_t ipos=0;
    while(ipos<len){
        if(ei<new&&ipos==ews[ei].start){
            /* Collect maximal run of adjacent same-charset ew */
            char cs_norm[256];
            strncpy(cs_norm,ews[ei].charset,255);cs_norm[255]=0;
            normalize_charset(cs_norm);
            Buf bytes; buf_init(&bytes);
            decode_ew_bytes(&bytes,&ews[ei]);
            size_t cur_end=ews[ei].end;
            ei++;
            while(ei<new){
                int adj=1;
                for(size_t k=cur_end;k<ews[ei].start;k++){
                    if(input[k]!=' '&&input[k]!='\t'){adj=0;break;}
                }
                if(!adj)break;
                char cs2[256];strncpy(cs2,ews[ei].charset,255);cs2[255]=0;normalize_charset(cs2);
                if(scasecmp(cs_norm,cs2)!=0)break;
                decode_ew_bytes(&bytes,&ews[ei]);
                cur_end=ews[ei].end;
                ei++;
            }
            /* Decode bytes with charset */
            Buf decoded; buf_init(&decoded);
            decode_charset(&decoded,bytes.d,bytes.len,cs_norm);
            buf_ap(&out,decoded.d,decoded.len);
            free(bytes.d);free(decoded.d);
            ipos=cur_end;
            /* Skip whitespace between this run and next adjacent ew (different charset) */
            while(ei<new){
                int adj=1;
                for(size_t k=cur_end;k<ews[ei].start;k++){if(input[k]!=' '&&input[k]!='\t'){adj=0;break;}}
                if(!adj)break;
                ipos=ews[ei].start;
                break;
            }
        } else {
            /* Check if this is whitespace between two adjacent ew */
            if(ei>0&&ei<new&&ipos>=ews[ei-1].end&&ipos<ews[ei].start){
                int all_ws=1;
                for(size_t k=ipos;k<ews[ei].start;k++){if(input[k]!=' '&&input[k]!='\t'){all_ws=0;break;}}
                if(all_ws){ipos=ews[ei].start;continue;}
            }
            buf_ap1(&out,(unsigned char)input[ipos]);
            ipos++;
        }
    }
    buf_ap1(&out,0);
    for(int i=0;i<new;i++){free(ews[i].charset);free(ews[i].etext);}
    free(ews);
    return (char*)out.d;
}

/* ============ Parameter parsing ============ */
typedef struct{char*name;char*value;} Param;
typedef struct{char*type;char*subtype;Param*params;int nparams;} CT;

static char*parse_token_or_qstring(const char*s,size_t len,size_t*pos){
    while(*pos<len&&(s[*pos]==' '||s[*pos]=='\t'))(*pos)++;
    if(*pos>=len)return xstrdup("");
    if(s[*pos]=='"'){
        (*pos)++;
        Buf b;buf_init(&b);
        while(*pos<len&&s[*pos]!='"'){
            if(s[*pos]=='\\'&&*pos+1<len){(*pos)++;buf_ap1(&b,(unsigned char)s[*pos]);(*pos)++;}
            else{buf_ap1(&b,(unsigned char)s[*pos]);(*pos)++;}
        }
        if(*pos<len)(*pos)++;
        buf_ap1(&b,0);
        return (char*)b.d;
    } else {
        size_t start=*pos;
        while(*pos<len&&s[*pos]!=';'&&s[*pos]!=' '&&s[*pos]!='\t')(*pos)++;
        return xstrndup(s+start,*pos-start);
    }
}

static CT parse_ct(const char*val){
    CT ct={0};
    ct.params=NULL;ct.nparams=0;
    if(!val||!*val){ct.type=xstrdup("text");ct.subtype=xstrdup("plain");return ct;}
    size_t len=strlen(val),pos=0;
    while(pos<len&&(val[pos]==' '||val[pos]=='\t'))pos++;
    size_t ts=pos;
    while(pos<len&&val[pos]!='/')pos++;
    ct.type=xstrndup(val+ts,pos-ts);
    for(char*p=ct.type;*p;p++)*p=tolower((unsigned char)*p);
    if(pos<len)pos++;
    while(pos<len&&(val[pos]==' '||val[pos]=='\t'))pos++;
    ts=pos;
    while(pos<len&&val[pos]!=';')pos++;
    size_t te=pos;
    while(te>ts&&(val[te-1]==' '||val[te-1]=='\t'))te--;
    ct.subtype=xstrndup(val+ts,te-ts);
    for(char*p=ct.subtype;*p;p++)*p=tolower((unsigned char)*p);
    int pcap=0;
    while(pos<len){
        while(pos<len&&(val[pos]==' '||val[pos]=='\t'))pos++;
        if(pos>=len||val[pos]!=';')break;
        pos++;
        while(pos<len&&(val[pos]==' '||val[pos]=='\t'))pos++;
        size_t as=pos;
        while(pos<len&&val[pos]!='='&&val[pos]!=' '&&val[pos]!='\t')pos++;
        size_t ae=pos;
        while(ae>as&&(val[ae-1]==' '||val[ae-1]=='\t'))ae--;
        char*aname=xstrndup(val+as,ae-as);
        for(char*p=aname;*p;p++)*p=tolower((unsigned char)*p);
        while(pos<len&&(val[pos]==' '||val[pos]=='\t'))pos++;
        if(pos<len&&val[pos]=='=')pos++;
        while(pos<len&&(val[pos]==' '||val[pos]=='\t'))pos++;
        char*avalue=parse_token_or_qstring(val,len,&pos);
        if(ct.nparams==pcap){pcap=pcap?pcap*2:8;ct.params=realloc(ct.params,pcap*sizeof(Param));}
        ct.params[ct.nparams].name=aname;
        ct.params[ct.nparams].value=avalue;
        ct.nparams++;
    }
    return ct;
}

static char*find_param(CT*ct,const char*name){
    for(int i=0;i<ct->nparams;i++)
        if(scasecmp(ct->params[i].name,name)==0)return ct->params[i].value;
    return NULL;
}

/* ============ RFC 2231 decode ============ */
static void percent_decode(Buf*out,const char*s,size_t len){
    for(size_t i=0;i<len;i++){
        if(s[i]=='%'&&i+2<len&&is_hex(s[i+1])&&is_hex(s[i+2])){
            buf_ap1(out,(unsigned char)(hex_val(s[i+1])*16+hex_val(s[i+2])));
            i+=2;
        } else buf_ap1(out,(unsigned char)s[i]);
    }
}

static char*decode_rfc2231(CT*ct,const char*attr){
    /* Check for single form: attr* */
    char sname[256];
    snprintf(sname,sizeof(sname),"%s*",attr);
    char*sv=find_param(ct,sname);
    if(sv){
        char*q1=strchr(sv,'\'');
        if(!q1)return xstrdup(sv);
        char*q2=strchr(q1+1,'\'');
        if(!q2)return xstrdup(sv);
        char*cs=xstrndup(sv,q1-sv);
        for(char*p=cs;*p;p++)*p=tolower((unsigned char)*p);
        const char*vstart=q2+1;
        Buf bytes;buf_init(&bytes);
        percent_decode(&bytes,vstart,strlen(vstart));
        Buf out;buf_init(&out);
        decode_charset(&out,bytes.d,bytes.len,cs);
        buf_ap1(&out,0);
        free(cs);free(bytes.d);
        return (char*)out.d;
    }
    /* Check for continuation segments */
    int max_segs=64;
    int *segs=malloc(max_segs*sizeof(int));
    char **segvals=malloc(max_segs*sizeof(char*));
    int *segpct=malloc(max_segs*sizeof(int));
    int nsegs=0;
    size_t alen=strlen(attr);
    for(int i=0;i<ct->nparams;i++){
        const char*pn=ct->params[i].name;
        if(strncmp(pn,attr,alen)!=0)continue;
        if(pn[alen]!='*')continue;
        const char*np=pn+alen+1;
        int pct=0;
        if(!isdigit((unsigned char)*np))continue;
        int num=atoi(np);
        const char*ep=np;
        while(*ep&&isdigit((unsigned char)*ep))ep++;
        if(*ep=='*'){pct=1;ep++;}
        if(*ep!=0)continue;
        if(nsegs>=max_segs){max_segs*=2;segs=realloc(segs,max_segs*sizeof(int));segvals=realloc(segvals,max_segs*sizeof(char*));segpct=realloc(segpct,max_segs*sizeof(int));}
        segs[nsegs]=num;segvals[nsegs]=ct->params[i].value;segpct[nsegs]=pct;nsegs++;
    }
    if(nsegs==0){free(segs);free(segvals);free(segpct);return NULL;}
    /* Sort by segment number */
    for(int i=0;i<nsegs-1;i++)for(int j=i+1;j<nsegs;j++){
        if(segs[j]<segs[i]){int t=segs[i];segs[i]=segs[j];segs[j]=t;
            char*tv=segvals[i];segvals[i]=segvals[j];segvals[j]=tv;
            int tp=segpct[i];segpct[i]=segpct[j];segpct[j]=tp;}
    }
    /* Find charset from first percent-encoded segment */
    char*cs=NULL;
    for(int i=0;i<nsegs;i++){
        if(segpct[i]){
            char*q1=strchr(segvals[i],'\'');
            if(q1){char*q2=strchr(q1+1,'\'');
                if(q2){cs=xstrndup(segvals[i],q1-segvals[i]);for(char*p=cs;*p;p++)*p=tolower((unsigned char)*p);
                    segvals[i]=q2+1;
                }
            }
            break;
        }
    }
    if(!cs)cs=xstrdup("us-ascii");
    /* Concatenate bytes */
    Buf bytes;buf_init(&bytes);
    for(int i=0;i<nsegs;i++){
        if(segpct[i]) percent_decode(&bytes,segvals[i],strlen(segvals[i]));
        else buf_apstr(&bytes,segvals[i]);
    }
    Buf out;buf_init(&out);
    decode_charset(&out,bytes.d,bytes.len,cs);
    buf_ap1(&out,0);
    free(cs);free(bytes.d);free(segs);free(segvals);free(segpct);
    return (char*)out.d;
}

/* ============ Header parsing ============ */
typedef struct{char*name;char*value;} Header;
static Header*find_header(Header*hs,int n,const char*name){
    for(int i=0;i<n;i++)if(scasecmp(hs[i].name,name)==0)return &hs[i];
    return NULL;
}

/* ============ Entity structure ============ */
typedef struct Entity{
    Header*headers;int nheaders;
    unsigned char*body;size_t body_len;
    struct Entity**parts;int nparts;
    CT ct;
    char*cte;
    char*disp_type;
    CT disp;
} Entity;

/* ============ Line utilities ============ */
static size_t find_lb(const unsigned char*d,size_t len,size_t pos,int lb_len){
    while(pos<len){
        if(lb_len==2){if(pos+1<len&&d[pos]=='\r'&&d[pos+1]=='\n')return pos;}
        else{if(d[pos]=='\n')return pos;}
        pos++;
    }
    return len;
}

/* ============ Parse entity ============ */
static Entity*parse_entity(const unsigned char*data,size_t len,int lb_len){
    Entity*e=calloc(1,sizeof(Entity));
    size_t pos=0;
    int hdr_end=-1;
    while(pos<=len){
        size_t lb=find_lb(data,len,pos,lb_len);
        if(lb==pos){hdr_end=pos;break;}
        if(lb>=len)break;
        pos=lb+lb_len;
    }
    if(hdr_end<0){
        e->body=(unsigned char*)data;e->body_len=len;
    } else {
        size_t hp=0;
        int hcap=0;
        while(hp<hdr_end){
            size_t lb=find_lb(data,hdr_end,hp,lb_len);
            size_t line_end=lb;
            size_t next=lb+lb_len;
            /* Unfold */
            while(next<hdr_end&&(data[next]==' '||data[next]=='\t')){
                size_t lb2=find_lb(data,hdr_end,next,lb_len);
                line_end=lb2;
                next=lb2+lb_len;
            }
            size_t line_len=line_end-hp;
            size_t colon=hp;
            while(colon<hp+line_len&&data[colon]!=':')colon++;
            if(colon<hp+line_len){
                char*name=xstrndup((char*)data+hp,colon-hp);
                for(char*p=name;*p;p++)*p=tolower((unsigned char)*p);
                size_t vs=colon+1;
                while(vs<hp+line_len&&(data[vs]==' '||data[vs]=='\t'))vs++;
                size_t ve=hp+line_len;
                while(ve>vs&&(data[ve-1]==' '||data[ve-1]=='\t'))ve--;
                char*value=xstrndup((char*)data+vs,ve-vs);
                if(e->nheaders==hcap){hcap=hcap?hcap*2:8;e->headers=realloc(e->headers,hcap*sizeof(Header));}
                e->headers[e->nheaders].name=name;
                e->headers[e->nheaders].value=value;
                e->nheaders++;
            }
            hp=next;
        }
        size_t body_start=hdr_end+lb_len;
        e->body=(unsigned char*)data+body_start;
        e->body_len=(body_start<=len)?len-body_start:0;
    }
    /* Parse Content-Type */
    Header*h=find_header(e->headers,e->nheaders,"content-type");
    if(h)e->ct=parse_ct(h->value);
    else{e->ct.type=xstrdup("text");e->ct.subtype=xstrdup("plain");e->ct.params=NULL;e->ct.nparams=0;}
    /* Parse CTE */
    h=find_header(e->headers,e->nheaders,"content-transfer-encoding");
    if(h){e->cte=xstrdup(h->value);for(char*p=e->cte;*p;p++)*p=tolower((unsigned char)*p);}
    else e->cte=xstrdup("7bit");
    /* Parse Content-Disposition */
    h=find_header(e->headers,e->nheaders,"content-disposition");
    if(h){
        e->disp=parse_ct(h->value);
        e->disp_type=e->disp.type;
    } else {
        e->disp.type=NULL;e->disp.subtype=NULL;e->disp.params=NULL;e->disp.nparams=0;
        e->disp_type=NULL;
    }
    /* If multipart, split into parts */
    if(scasecmp(e->ct.type,"multipart")==0){
        char*boundary=find_param(&e->ct,"boundary");
        if(boundary){
            size_t blen=strlen(boundary);
            size_t bpos=0;
            int in_parts=0;
            size_t part_start=0;
            int pcap=0;
            while(bpos<=e->body_len){
                size_t lb=find_lb(e->body,e->body_len,bpos,lb_len);
                size_t line_len=lb-bpos;
                int is_delim=0,is_close=0;
                if(line_len>=2+blen&&e->body[bpos]=='-'&&e->body[bpos+1]=='-'){
                    if(line_len>=2+blen+2&&memcmp(e->body+bpos+2,boundary,blen)==0&&e->body[bpos+2+blen]=='-'){
                        size_t k=bpos+2+blen+2;
                        int ok=1;
                        while(k<lb){if(e->body[k]!=' '&&e->body[k]!='\t'){ok=0;break;}k++;}
                        if(ok)is_close=1;
                    }
                    if(!is_close&&line_len>=2+blen&&memcmp(e->body+bpos+2,boundary,blen)==0){
                        size_t k=bpos+2+blen;
                        int ok=1;
                        while(k<lb){if(e->body[k]!=' '&&e->body[k]!='\t'){ok=0;break;}k++;}
                        if(ok)is_delim=1;
                    }
                }
                if(is_delim||is_close){
                    if(in_parts){
                        size_t pl=lb-part_start;
                        /* Remove trailing line break before delimiter */
                        if(pl>=2&&lb_len==2&&e->body[part_start+pl-2]=='\r'&&e->body[part_start+pl-1]=='\n')pl-=2;
                        else if(pl>=1&&lb_len==1&&e->body[part_start+pl-1]=='\n')pl-=1;
                        Entity*pe=parse_entity(e->body+part_start,pl,lb_len);
                        if(e->nparts==pcap){pcap=pcap?pcap*2:8;e->parts=realloc(e->parts,pcap*sizeof(Entity*));}
                        e->parts[e->nparts++]=pe;
                    }
                    if(is_close)break;
                    in_parts=1;
                    part_start=lb+lb_len;
                }
                if(lb>=e->body_len)break;
                bpos=lb+lb_len;
            }
            /* If we never found a close delimiter, add the last part */
            if(in_parts){
                size_t pl=e->body_len-part_start;
                if(pl>=2&&lb_len==2&&e->body[part_start+pl-2]=='\r'&&e->body[part_start+pl-1]=='\n')pl-=2;
                else if(pl>=1&&lb_len==1&&e->body[part_start+pl-1]=='\n')pl-=1;
                Entity*pe=parse_entity(e->body+part_start,pl,lb_len);
                if(e->nparts==pcap){pcap=pcap?pcap*2:8;e->parts=realloc(e->parts,pcap*sizeof(Entity*));}
                e->parts[e->nparts++]=pe;
            }
        }
    }
    return e;
}

/* ============ Quoted string output ============ */
static void print_quoted(FILE*f,const unsigned char*data,size_t len){
    fputc('"',f);
    size_t i=0;
    while(i<len){
        size_t used;
        unsigned int cp=utf8_decode(data+i,len-i,&used);
        if(cp=='\\')fputs("\\\\",f);
        else if(cp=='"')fputs("\\\"",f);
        else if(cp=='\n')fputs("\\n",f);
        else if(cp=='\t')fputs("\\t",f);
        else if(cp<0x20||(cp>=0x7F&&cp<=0x9F))fprintf(f,"\\u%04x",cp);
        else{
            for(size_t j=0;j<used;j++)fputc(data[i+j],f);
        }
        i+=used;
    }
    fputc('"',f);
}

/* ============ Decode body ============ */
static void decode_body_cte(Buf*out,const unsigned char*body,size_t len,const char*cte,int lb_len){
    if(!strcmp(cte,"base64")){
        decode_b64(out,body,len);
    } else if(!strcmp(cte,"quoted-printable")){
        decode_qp(out,body,len,lb_len);
    } else {
        buf_ap(out,body,len);
    }
}

/* ============ Get filename ============ */
static char*get_filename(Entity*e){
    char*r;
    r=decode_rfc2231(&e->disp,"filename");
    if(r)return r;
    char*v=find_param(&e->disp,"filename");
    if(v)return decode_ew(v);
    r=decode_rfc2231(&e->ct,"name");
    if(r)return r;
    v=find_param(&e->ct,"name");
    if(v)return decode_ew(v);
    return NULL;
}

/* ============ Print tree ============ */
static void print_tree(FILE*f,Entity*e,int indent,int lb_len){
    for(int i=0;i<indent;i++)fputs("  ",f);
    if(scasecmp(e->ct.type,"multipart")==0){
        fprintf(f,"multipart/%s parts=%d\n",e->ct.subtype,e->nparts);
        for(int i=0;i<e->nparts;i++)
            print_tree(f,e->parts[i],indent+1,lb_len);
    } else {
        int is_text=(scasecmp(e->ct.type,"text")==0)&&(!e->disp_type||scasecmp(e->disp_type,"attachment")!=0);
        if(is_text){
            char*charset=find_param(&e->ct,"charset");
            char cs_buf[256];
            if(charset){strncpy(cs_buf,charset,255);cs_buf[255]=0;for(char*p=cs_buf;*p;p++)*p=tolower((unsigned char)*p);}
            else strcpy(cs_buf,"us-ascii");
            Buf raw;buf_init(&raw);
            decode_body_cte(&raw,e->body,e->body_len,e->cte,lb_len);
            Buf utf8;buf_init(&utf8);
            decode_charset(&utf8,raw.d,raw.len,cs_buf);
            free(raw.d);
            /* Normalize line endings */
            Buf norm;buf_init(&norm);
            for(size_t i=0;i<utf8.len;i++){
                if(utf8.d[i]=='\r'){
                    if(i+1<utf8.len&&utf8.d[i+1]=='\n'){buf_ap1(&norm,'\n');i++;}
                    else buf_ap1(&norm,'\n');
                } else buf_ap1(&norm,utf8.d[i]);
            }
            free(utf8.d);
            size_t ncp=count_cp(norm.d,norm.len);
            fprintf(f,"text/%s charset=%s cte=%s chars=%zu\n",e->ct.subtype,cs_buf,e->cte,ncp);
            for(int i=0;i<indent+1;i++)fputs("  ",f);
            print_quoted(f,norm.d,norm.len);
            fputc('\n',f);
            free(norm.d);
        } else {
            Buf raw;buf_init(&raw);
            decode_body_cte(&raw,e->body,e->body_len,e->cte,lb_len);
            uint32_t c=crc32(raw.d,raw.len);
            char*fname=get_filename(e);
            const char*disp=e->disp_type?e->disp_type:"-";
            fprintf(f,"%s/%s cte=%s disposition=%s name=",e->ct.type,e->ct.subtype,e->cte,disp);
            if(fname)print_quoted(f,(unsigned char*)fname,strlen(fname));
            else fputc('-',f);
            fprintf(f," size=%zu crc32=%08x\n",raw.len,c);
            free(raw.d);
        }
    }
}

/* ============ Main ============ */
static int cmp_str(const void*a,const void*b){return strcmp(*(const char**)a,*(const char**)b);}

int main(int argc,char*argv[]){
    init_crc();
    if(argc<2){fprintf(stderr,"Usage: %s <dir>\n",argv[0]);return 1;}
    DIR*d=opendir(argv[1]);
    if(!d){perror("opendir");return 1;}
    char**files=NULL;int nf=0,fcap=0;
    struct dirent*de;
    while((de=readdir(d))){
        size_t nlen=strlen(de->d_name);
        if(nlen>4&&strcmp(de->d_name+nlen-4,".eml")==0){
            if(nf==fcap){fcap=fcap?fcap*2:16;files=realloc(files,fcap*sizeof(char*));}
            files[nf++]=xstrdup(de->d_name);
        }
    }
    closedir(d);
    qsort(files,nf,sizeof(char*),cmp_str);
    for(int fi=0;fi<nf;fi++){
        if(fi>0)fputc('\n',stdout);
        char path[4096];
        snprintf(path,sizeof(path),"%s/%s",argv[1],files[fi]);
        FILE*fp=fopen(path,"rb");
        if(!fp){perror(path);continue;}
        fseek(fp,0,SEEK_END);
        long fsz=ftell(fp);
        fseek(fp,0,SEEK_SET);
        unsigned char*fdata=malloc(fsz+1);
        size_t frd=fread(fdata,1,fsz,fp);
        fclose(fp);
        /* Detect line ending */
        int lb_len=1;
        for(size_t i=0;i+1<frd;i++){if(fdata[i]=='\r'&&fdata[i+1]=='\n'){lb_len=2;break;}}
        /* Parse */
        Entity*msg=parse_entity(fdata,frd,lb_len);
        /* Output */
        printf("== %s\n",files[fi]);
        Header*h=find_header(msg->headers,msg->nheaders,"from");
        if(h){char*dec=decode_ew(h->value);printf("From: ");print_quoted(stdout,(unsigned char*)dec,strlen(dec));printf("\n");free(dec);}
        else printf("From: -\n");
        h=find_header(msg->headers,msg->nheaders,"subject");
        if(h){char*dec=decode_ew(h->value);printf("Subject: ");print_quoted(stdout,(unsigned char*)dec,strlen(dec));printf("\n");free(dec);}
        else printf("Subject: -\n");
        print_tree(stdout,msg,0,lb_len);
        free(fdata);
    }
    for(int i=0;i<nf;i++)free(files[i]);
    free(files);
    return 0;
}

import * as fs from 'fs';
import * as path from 'path';

// ===== TYPES =====
type Val = bigint | boolean | string | Val[] | FuncVal | null;

interface UserFunc {
  kind: 'user';
  params: string[];
  body: Stmt[];
  scope: Scope;
}

interface BuiltinFunc {
  kind: 'builtin';
  name: string;
  arity: number; // -1 for variadic
  fn: (args: Val[], line: number) => Val;
}

type FuncVal = UserFunc | BuiltinFunc;

class Scope {
  vars: Map<string, Val> = new Map();
  parent: Scope | null;
  constructor(parent: Scope | null = null) { this.parent = parent; }
  get(name: string): Val | undefined {
    let s: Scope | null = this;
    while (s) { if (s.vars.has(name)) return s.vars.get(name)!; s = s.parent; }
    return undefined;
  }
  has(name: string): boolean {
    let s: Scope | null = this;
    while (s) { if (s.vars.has(name)) return true; s = s.parent; }
    return false;
  }
  set(name: string, val: Val): boolean {
    let s: Scope | null = this;
    while (s) { if (s.vars.has(name)) { s.vars.set(name, val); return true; } s = s.parent; }
    return false;
  }
  declare(name: string, val: Val): void { this.vars.set(name, val); }
}

// ===== LEXER =====
enum TT {
  INT, STR, IDENT,
  LET, FN, IF, ELSE, WHILE, FOR, IN, RETURN, BREAK, CONTINUE,
  AND, OR, NOT, TRUE, FALSE, NIL,
  EQ, NEQ, LTE, GTE, LT, GT, ASSIGN,
  PLUS, MINUS, STAR, SLASH, PERCENT,
  LPAREN, RPAREN, LBRACKET, RBRACKET, LBRACE, RBRACE,
  COMMA, SEMI, EOF
}

interface Token { type: TT; str: string; intVal?: bigint; line: number; }

const KW: Record<string, TT> = {
  let: TT.LET, fn: TT.FN, if: TT.IF, else: TT.ELSE, while: TT.WHILE,
  for: TT.FOR, in: TT.IN, return: TT.RETURN, break: TT.BREAK,
  continue: TT.CONTINUE, and: TT.AND, or: TT.OR, not: TT.NOT,
  true: TT.TRUE, false: TT.FALSE, nil: TT.NIL
};

function lex(src: string): Token[] {
  const tokens: Token[] = [];
  let pos = 0, line = 1;
  while (pos < src.length) {
    const c = src[pos];
    if (c === ' ' || c === '\t' || c === '\r') { pos++; continue; }
    if (c === '\n') { pos++; line++; continue; }
    if (c === '#') { while (pos < src.length && src[pos] !== '\n') pos++; continue; }
    if (c >= '0' && c <= '9') {
      let s = pos;
      while (pos < src.length && src[pos] >= '0' && src[pos] <= '9') pos++;
      tokens.push({ type: TT.INT, str: src.slice(s, pos), intVal: BigInt(src.slice(s, pos)), line });
      continue;
    }
    if (c === '"') {
      pos++; let s = '';
      while (pos < src.length && src[pos] !== '"') {
        if (src[pos] === '\\') {
          pos++;
          if (src[pos] === 'n') s += '\n';
          else if (src[pos] === 't') s += '\t';
          else if (src[pos] === '"') s += '"';
          else if (src[pos] === '\\') s += '\\';
          else s += src[pos];
          pos++;
        } else { s += src[pos]; pos++; }
      }
      pos++;
      tokens.push({ type: TT.STR, str: s, line });
      continue;
    }
    if ((c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z') || c === '_') {
      let s = pos;
      while (pos < src.length && ((src[pos] >= 'A' && src[pos] <= 'Z') || (src[pos] >= 'a' && src[pos] <= 'z') || (src[pos] >= '0' && src[pos] <= '9') || src[pos] === '_')) pos++;
      const w = src.slice(s, pos);
      tokens.push({ type: KW[w] ?? TT.IDENT, str: w, line });
      continue;
    }
    const two = src.slice(pos, pos + 2);
    if (two === '==') { tokens.push({ type: TT.EQ, str: '==', line }); pos += 2; continue; }
    if (two === '!=') { tokens.push({ type: TT.NEQ, str: '!=', line }); pos += 2; continue; }
    if (two === '<=') { tokens.push({ type: TT.LTE, str: '<=', line }); pos += 2; continue; }
    if (two === '>=') { tokens.push({ type: TT.GTE, str: '>=', line }); pos += 2; continue; }
    let tt: TT;
    switch (c) {
      case '<': tt = TT.LT; break; case '>': tt = TT.GT; break;
      case '=': tt = TT.ASSIGN; break; case '+': tt = TT.PLUS; break;
      case '-': tt = TT.MINUS; break; case '*': tt = TT.STAR; break;
      case '/': tt = TT.SLASH; break; case '%': tt = TT.PERCENT; break;
      case '(': tt = TT.LPAREN; break; case ')': tt = TT.RPAREN; break;
      case '[': tt = TT.LBRACKET; break; case ']': tt = TT.RBRACKET; break;
      case '{': tt = TT.LBRACE; break; case '}': tt = TT.RBRACE; break;
      case ',': tt = TT.COMMA; break; case ';': tt = TT.SEMI; break;
      default: throw new Error(`Unexpected char '${c}' at line ${line}`);
    }
    tokens.push({ type: tt, str: c, line }); pos++;
  }
  tokens.push({ type: TT.EOF, str: '', line });
  return tokens;
}

// ===== AST =====
type Expr =
  | { kind: 'int'; value: bigint; line: number }
  | { kind: 'str'; value: string; line: number }
  | { kind: 'bool'; value: boolean; line: number }
  | { kind: 'nil'; line: number }
  | { kind: 'ident'; name: string; line: number }
  | { kind: 'list'; elements: Expr[]; line: number }
  | { kind: 'fn'; params: string[]; body: Stmt[]; line: number }
  | { kind: 'binary'; op: string; left: Expr; right: Expr; line: number }
  | { kind: 'neg'; operand: Expr; line: number }
  | { kind: 'not'; operand: Expr; line: number }
  | { kind: 'call'; callee: Expr; args: Expr[]; line: number }
  | { kind: 'index'; obj: Expr; index: Expr; line: number };

type ElseBranch = { kind: 'block'; body: Stmt[] } | { kind: 'if'; stmt: Stmt };

type Stmt =
  | { kind: 'let'; name: string; expr: Expr; line: number }
  | { kind: 'fnDecl'; name: string; params: string[]; body: Stmt[]; line: number }
  | { kind: 'if'; cond: Expr; then: Stmt[]; elseBranch: ElseBranch | null; line: number }
  | { kind: 'while'; cond: Expr; body: Stmt[]; line: number }
  | { kind: 'for'; varName: string; iterable: Expr; body: Stmt[]; line: number }
  | { kind: 'return'; expr: Expr | null; line: number }
  | { kind: 'break'; line: number }
  | { kind: 'continue'; line: number }
  | { kind: 'assign'; name: string; expr: Expr; line: number }
  | { kind: 'indexAssign'; obj: Expr; index: Expr; value: Expr; line: number }
  | { kind: 'expr'; expr: Expr; line: number };

// ===== PARSER =====
class Parser {
  tokens: Token[]; pos = 0;
  constructor(tokens: Token[]) { this.tokens = tokens; }
  peek(): Token { return this.tokens[this.pos]; }
  advance(): Token { return this.tokens[this.pos++]; }
  expect(type: TT): Token {
    const t = this.advance();
    if (t.type !== type) throw new Error(`Expected ${type} but got ${t.type} at line ${t.line}`);
    return t;
  }
  match(type: TT): boolean {
    if (this.peek().type === type) { this.pos++; return true; }
    return false;
  }

  parseProgram(): Stmt[] {
    const stmts: Stmt[] = [];
    while (this.peek().type !== TT.EOF) stmts.push(this.parseStmt());
    return stmts;
  }

  parseStmt(): Stmt {
    const t = this.peek();
    switch (t.type) {
      case TT.LET: return this.parseLet();
      case TT.FN: return this.parseFnDecl();
      case TT.IF: return this.parseIf();
      case TT.WHILE: return this.parseWhile();
      case TT.FOR: return this.parseFor();
      case TT.RETURN: return this.parseReturn();
      case TT.BREAK: this.advance(); this.expect(TT.SEMI); return { kind: 'break', line: t.line };
      case TT.CONTINUE: this.advance(); this.expect(TT.SEMI); return { kind: 'continue', line: t.line };
      case TT.IDENT: {
        // Could be assignment or expression statement
        if (this.tokens[this.pos + 1]?.type === TT.ASSIGN) {
          const name = this.advance().str; this.advance(); // skip =
          const expr = this.parseExpr(); this.expect(TT.SEMI);
          return { kind: 'assign', name, expr, line: t.line };
        }
        if (this.tokens[this.pos + 1]?.type === TT.LBRACKET) {
          // Could be index assignment: IDENT "[" expr "]" "=" expr ";"
          // We need to parse postfix first, then check for =
          const expr = this.parseExpr();
          if (this.peek().type === TT.ASSIGN) {
            // expr should be an index expression
            this.advance(); // skip =
            const value = this.parseExpr(); this.expect(TT.SEMI);
            if (expr.kind !== 'index') throw new Error('Invalid index assignment target');
            return { kind: 'indexAssign', obj: expr.obj, index: expr.index, value, line: expr.line };
          }
          this.expect(TT.SEMI);
          return { kind: 'expr', expr, line: t.line };
        }
        const expr = this.parseExpr(); this.expect(TT.SEMI);
        return { kind: 'expr', expr, line: t.line };
      }
      default: {
        // Could be a postfix expression statement (e.g., function call)
        const expr = this.parseExpr(); this.expect(TT.SEMI);
        return { kind: 'expr', expr, line: t.line };
      }
    }
  }

  parseLet(): Stmt {
    const t = this.advance(); // let
    const name = this.expect(TT.IDENT).str;
    this.expect(TT.ASSIGN);
    const expr = this.parseExpr();
    this.expect(TT.SEMI);
    return { kind: 'let', name, expr, line: t.line };
  }

  parseFnDecl(): Stmt {
    const t = this.advance(); // fn
    const name = this.expect(TT.IDENT).str;
    this.expect(TT.LPAREN);
    const params = this.parseParams();
    this.expect(TT.RPAREN);
    const body = this.parseBlock();
    return { kind: 'fnDecl', name, params, body, line: t.line };
  }

  parseIf(): Stmt {
    const t = this.advance(); // if
    const cond = this.parseExpr();
    const then = this.parseBlock();
    let elseBranch: ElseBranch | null = null;
    if (this.peek().type === TT.ELSE) {
      this.advance();
      if (this.peek().type === TT.IF) {
        elseBranch = { kind: 'if', stmt: this.parseIf() };
      } else {
        elseBranch = { kind: 'block', body: this.parseBlock() };
      }
    }
    return { kind: 'if', cond, then, elseBranch, line: t.line };
  }

  parseWhile(): Stmt {
    const t = this.advance(); // while
    const cond = this.parseExpr();
    const body = this.parseBlock();
    return { kind: 'while', cond, body, line: t.line };
  }

  parseFor(): Stmt {
    const t = this.advance(); // for
    const varName = this.expect(TT.IDENT).str;
    this.expect(TT.IN);
    const iterable = this.parseExpr();
    const body = this.parseBlock();
    return { kind: 'for', varName, iterable, body, line: t.line };
  }

  parseReturn(): Stmt {
    const t = this.advance(); // return
    let expr: Expr | null = null;
    if (this.peek().type !== TT.SEMI) expr = this.parseExpr();
    this.expect(TT.SEMI);
    return { kind: 'return', expr, line: t.line };
  }

  parseBlock(): Stmt[] {
    this.expect(TT.LBRACE);
    const stmts: Stmt[] = [];
    while (this.peek().type !== TT.RBRACE) stmts.push(this.parseStmt());
    this.expect(TT.RBRACE);
    return stmts;
  }

  parseParams(): string[] {
    const params: string[] = [];
    if (this.peek().type === TT.RPAREN) return params;
    params.push(this.expect(TT.IDENT).str);
    while (this.match(TT.COMMA)) params.push(this.expect(TT.IDENT).str);
    return params;
  }

  // Expression parsing with precedence
  parseExpr(): Expr { return this.parseOr(); }

  parseOr(): Expr {
    let left = this.parseAnd();
    while (this.peek().type === TT.OR) {
      const t = this.advance();
      const right = this.parseAnd();
      left = { kind: 'binary', op: 'or', left, right, line: t.line };
    }
    return left;
  }

  parseAnd(): Expr {
    let left = this.parseNot();
    while (this.peek().type === TT.AND) {
      const t = this.advance();
      const right = this.parseNot();
      left = { kind: 'binary', op: 'and', left, right, line: t.line };
    }
    return left;
  }

  parseNot(): Expr {
    if (this.peek().type === TT.NOT) {
      const t = this.advance();
      const operand = this.parseNot();
      return { kind: 'not', operand, line: t.line };
    }
    return this.parseComparison();
  }

  parseComparison(): Expr {
    let left = this.parseAdd();
    while (this.peek().type === TT.EQ || this.peek().type === TT.NEQ ||
           this.peek().type === TT.LT || this.peek().type === TT.LTE ||
           this.peek().type === TT.GT || this.peek().type === TT.GTE) {
      const t = this.advance();
      const right = this.parseAdd();
      left = { kind: 'binary', op: t.str, left, right, line: t.line };
    }
    return left;
  }

  parseAdd(): Expr {
    let left = this.parseMul();
    while (this.peek().type === TT.PLUS || this.peek().type === TT.MINUS) {
      const t = this.advance();
      const right = this.parseMul();
      left = { kind: 'binary', op: t.str, left, right, line: t.line };
    }
    return left;
  }

  parseMul(): Expr {
    let left = this.parseUnary();
    while (this.peek().type === TT.STAR || this.peek().type === TT.SLASH || this.peek().type === TT.PERCENT) {
      const t = this.advance();
      const right = this.parseUnary();
      left = { kind: 'binary', op: t.str, left, right, line: t.line };
    }
    return left;
  }

  parseUnary(): Expr {
    if (this.peek().type === TT.MINUS) {
      const t = this.advance();
      const operand = this.parseUnary();
      return { kind: 'neg', operand, line: t.line };
    }
    return this.parsePostfix();
  }

  parsePostfix(): Expr {
    let expr = this.parsePrimary();
    while (true) {
      if (this.peek().type === TT.LPAREN) {
        const t = this.advance();
        const args: Expr[] = [];
        if (this.peek().type !== TT.RPAREN) {
          args.push(this.parseExpr());
          while (this.match(TT.COMMA)) args.push(this.parseExpr());
        }
        this.expect(TT.RPAREN);
        expr = { kind: 'call', callee: expr, args, line: t.line };
      } else if (this.peek().type === TT.LBRACKET) {
        const t = this.advance();
        const index = this.parseExpr();
        this.expect(TT.RBRACKET);
        expr = { kind: 'index', obj: expr, index, line: t.line };
      } else break;
    }
    return expr;
  }

  parsePrimary(): Expr {
    const t = this.peek();
    switch (t.type) {
      case TT.INT: this.advance(); return { kind: 'int', value: t.intVal!, line: t.line };
      case TT.STR: this.advance(); return { kind: 'str', value: t.str, line: t.line };
      case TT.TRUE: this.advance(); return { kind: 'bool', value: true, line: t.line };
      case TT.FALSE: this.advance(); return { kind: 'bool', value: false, line: t.line };
      case TT.NIL: this.advance(); return { kind: 'nil', line: t.line };
      case TT.IDENT: this.advance(); return { kind: 'ident', name: t.str, line: t.line };
      case TT.LPAREN: {
        this.advance();
        const expr = this.parseExpr();
        this.expect(TT.RPAREN);
        return expr;
      }
      case TT.LBRACKET: {
        this.advance();
        const elements: Expr[] = [];
        if (this.peek().type !== TT.RBRACKET) {
          elements.push(this.parseExpr());
          while (this.match(TT.COMMA)) elements.push(this.parseExpr());
        }
        this.expect(TT.RBRACKET);
        return { kind: 'list', elements, line: t.line };
      }
      case TT.FN: {
        this.advance();
        this.expect(TT.LPAREN);
        const params = this.parseParams();
        this.expect(TT.RPAREN);
        const body = this.parseBlock();
        return { kind: 'fn', params, body, line: t.line };
      }
      default:
        throw new Error(`Unexpected token ${t.type} at line ${t.line}`);
    }
  }
}

// ===== RUNTIME =====
const INT_MIN = -(1n << 63n);
const INT_MAX = (1n << 63n) - 1n;

class RuntimeError {
  constructor(public line: number, public msg: string) {}
}
class BreakSignal {}
class ContinueSignal {}
class ReturnSignal { constructor(public value: Val) {} }

function typeOf(v: Val): string {
  if (v === null) return 'nil';
  if (typeof v === 'boolean') return 'bool';
  if (typeof v === 'bigint') return 'int';
  if (typeof v === 'string') return 'string';
  if (Array.isArray(v)) return 'list';
  return 'function';
}

function truthy(v: Val): boolean {
  if (v === null) return false;
  if (typeof v === 'boolean') return v;
  if (typeof v === 'bigint') return v !== 0n;
  if (typeof v === 'string') return v !== '';
  if (Array.isArray(v)) return v.length > 0;
  return true;
}

function checkInt(v: bigint, line: number): bigint {
  if (v < INT_MIN || v > INT_MAX) throw new RuntimeError(line, 'integer overflow');
  return v;
}

function valuesEqual(a: Val, b: Val): boolean {
  const ta = typeOf(a), tb = typeOf(b);
  if (ta !== tb) return false;
  if (ta === 'nil') return true;
  if (ta === 'int') return (a as bigint) === (b as bigint);
  if (ta === 'bool') return (a as boolean) === (b as boolean);
  if (ta === 'string') return (a as string) === (b as string);
  if (ta === 'list') {
    const aa = a as Val[], bb = b as Val[];
    if (aa.length !== bb.length) return false;
    for (let i = 0; i < aa.length; i++) if (!valuesEqual(aa[i], bb[i])) return false;
    return true;
  }
  return a === b;
}

function displayVal(v: Val, inList: boolean, ancestors: Set<Val[]>): string {
  if (v === null) return 'nil';
  if (typeof v === 'boolean') return v ? 'true' : 'false';
  if (typeof v === 'bigint') return v.toString();
  if (typeof v === 'string') {
    if (!inList) return v;
    let s = '"';
    for (const ch of v) {
      if (ch === '\\') s += '\\\\';
      else if (ch === '"') s += '\\"';
      else if (ch === '\n') s += '\\n';
      else if (ch === '\t') s += '\\t';
      else s += ch;
    }
    return s + '"';
  }
  if (Array.isArray(v)) {
    if (ancestors.has(v)) return '[...]';
    ancestors.add(v);
    const parts = v.map(e => displayVal(e, true, ancestors));
    ancestors.delete(v);
    return '[' + parts.join(', ') + ']';
  }
  return '<fn>';
}

function displayStr(v: Val): string {
  return displayVal(v, false, new Set());
}

// ===== INTERPRETER =====
class Interpreter {
  output: string[] = [];
  globalScope: Scope;

  constructor() {
    this.globalScope = new Scope(this.makeBuiltinScope());
  }

  makeBuiltinScope(): Scope {
    const s = new Scope(null);
    s.declare('print', { kind: 'builtin', name: 'print', arity: -1, fn: (args, line) => {
      const parts = args.map(a => displayVal(a, false, new Set()));
      this.output.push(parts.join(' ') + '\n');
      return null;
    }} as BuiltinFunc);
    s.declare('str', { kind: 'builtin', name: 'str', arity: 1, fn: (args, line) => {
      return displayStr(args[0]);
    }} as BuiltinFunc);
    s.declare('type', { kind: 'builtin', name: 'type', arity: 1, fn: (args, line) => {
      return typeOf(args[0]);
    }} as BuiltinFunc);
    s.declare('len', { kind: 'builtin', name: 'len', arity: 1, fn: (args, line) => {
      const v = args[0];
      if (typeof v === 'string') return BigInt(v.length);
      if (Array.isArray(v)) return BigInt(v.length);
      throw new RuntimeError(line, 'bad argument to len');
    }} as BuiltinFunc);
    s.declare('push', { kind: 'builtin', name: 'push', arity: 2, fn: (args, line) => {
      const lst = args[0];
      if (!Array.isArray(lst)) throw new RuntimeError(line, 'bad argument to push');
      lst.push(args[1]);
      return null;
    }} as BuiltinFunc);
    s.declare('pop', { kind: 'builtin', name: 'pop', arity: 1, fn: (args, line) => {
      const lst = args[0];
      if (!Array.isArray(lst) || lst.length === 0) throw new RuntimeError(line, 'bad argument to pop');
      return lst.pop()!;
    }} as BuiltinFunc);
    s.declare('range', { kind: 'builtin', name: 'range', arity: 2, fn: (args, line) => {
      const a = args[0], b = args[1];
      if (typeof a !== 'bigint' || typeof b !== 'bigint') throw new RuntimeError(line, 'bad argument to range');
      const result: Val[] = [];
      for (let i = a; i < b; i++) result.push(i);
      return result;
    }} as BuiltinFunc);
    s.declare('slice', { kind: 'builtin', name: 'slice', arity: 3, fn: (args, line) => {
      const x = args[0], a = args[1], b = args[2];
      if (typeof a !== 'bigint' || typeof b !== 'bigint') throw new RuntimeError(line, 'bad argument to slice');
      if (typeof x === 'string') {
        const ai = Number(a), bi = Number(b);
        if (ai < 0 || bi > x.length || ai > bi) throw new RuntimeError(line, 'bad argument to slice');
        return x.slice(ai, bi);
      }
      if (Array.isArray(x)) {
        const ai = Number(a), bi = Number(b);
        if (ai < 0 || bi > x.length || ai > bi) throw new RuntimeError(line, 'bad argument to slice');
        return x.slice(ai, bi);
      }
      throw new RuntimeError(line, 'bad argument to slice');
    }} as BuiltinFunc);
    return s;
  }

  run(stmts: Stmt[], scope: Scope): void {
    for (const stmt of stmts) this.execStmt(stmt, scope);
  }

  execStmt(stmt: Stmt, scope: Scope): void {
    switch (stmt.kind) {
      case 'let': {
        const val = this.eval(stmt.expr, scope);
        scope.declare(stmt.name, val);
        break;
      }
      case 'fnDecl': {
        const fn: UserFunc = { kind: 'user', params: stmt.params, body: stmt.body, scope };
        scope.declare(stmt.name, fn);
        break;
      }
      case 'if': {
        if (truthy(this.eval(stmt.cond, scope))) {
          const s = new Scope(scope);
          this.run(stmt.then, s);
        } else if (stmt.elseBranch) {
          if (stmt.elseBranch.kind === 'block') {
            const s = new Scope(scope);
            this.run(stmt.elseBranch.body, s);
          } else {
            this.execStmt(stmt.elseBranch.stmt, scope);
          }
        }
        break;
      }
      case 'while': {
        while (truthy(this.eval(stmt.cond, scope))) {
          const s = new Scope(scope);
          try {
            this.run(stmt.body, s);
          } catch (e) {
            if (e instanceof BreakSignal) break;
            if (e instanceof ContinueSignal) continue;
            throw e;
          }
        }
        break;
      }
      case 'for': {
        const list = this.eval(stmt.iterable, scope);
        if (!Array.isArray(list)) throw new RuntimeError(stmt.line, `cannot iterate ${typeOf(list)}`);
        let i = 0;
        while (i < list.length) {
          const s = new Scope(scope);
          s.declare(stmt.varName, list[i]);
          try {
            this.run(stmt.body, s);
          } catch (e) {
            if (e instanceof BreakSignal) break;
            if (e instanceof ContinueSignal) { i++; continue; }
            throw e;
          }
          i++;
        }
        break;
      }
      case 'return': {
        const val = stmt.expr ? this.eval(stmt.expr, scope) : null;
        throw new ReturnSignal(val);
      }
      case 'break': throw new BreakSignal();
      case 'continue': throw new ContinueSignal();
      case 'assign': {
        const val = this.eval(stmt.expr, scope);
        if (!scope.set(stmt.name, val)) throw new RuntimeError(stmt.line, `undefined variable ${stmt.name}`);
        break;
      }
      case 'indexAssign': {
        const obj = this.eval(stmt.obj, scope);
        const idx = this.eval(stmt.index, scope);
        const val = this.eval(stmt.value, scope);
        if (!Array.isArray(obj)) throw new RuntimeError(stmt.line, `cannot assign into ${typeOf(obj)}`);
        if (typeof idx !== 'bigint') throw new RuntimeError(stmt.line, `cannot index list with ${typeOf(idx)}`);
        const i = Number(idx);
        if (i < 0 || i >= obj.length) throw new RuntimeError(stmt.line, `index ${idx} out of range for length ${obj.length}`);
        obj[i] = val;
        break;
      }
      case 'expr': {
        this.eval(stmt.expr, scope);
        break;
      }
    }
  }

  eval(expr: Expr, scope: Scope): Val {
    switch (expr.kind) {
      case 'int': return expr.value;
      case 'str': return expr.value;
      case 'bool': return expr.value;
      case 'nil': return null;
      case 'ident': {
        const v = scope.get(expr.name);
        if (v === undefined) throw new RuntimeError(expr.line, `undefined variable ${expr.name}`);
        return v;
      }
      case 'list': {
        return expr.elements.map(e => this.eval(e, scope));
      }
      case 'fn': {
        return { kind: 'user', params: expr.params, body: expr.body, scope } as UserFunc;
      }
      case 'not': {
        return !truthy(this.eval(expr.operand, scope));
      }
      case 'neg': {
        const v = this.eval(expr.operand, scope);
        if (typeof v !== 'bigint') throw new RuntimeError(expr.line, `cannot apply - to ${typeOf(v)}`);
        return checkInt(-v, expr.line);
      }
      case 'binary': return this.evalBinary(expr, scope);
      case 'call': return this.evalCall(expr, scope);
      case 'index': return this.evalIndex(expr, scope);
    }
  }

  evalBinary(expr: { op: string; left: Expr; right: Expr; line: number }, scope: Scope): Val {
    const op = expr.op;
    if (op === 'and') {
      const l = this.eval(expr.left, scope);
      if (!truthy(l)) return l;
      return this.eval(expr.right, scope);
    }
    if (op === 'or') {
      const l = this.eval(expr.left, scope);
      if (truthy(l)) return l;
      return this.eval(expr.right, scope);
    }
    const l = this.eval(expr.left, scope);
    const r = this.eval(expr.right, scope);

    if (op === '==') return valuesEqual(l, r);
    if (op === '!=') return !valuesEqual(l, r);

    if (op === '+' ) {
      if (typeof l === 'bigint' && typeof r === 'bigint') return checkInt(l + r, expr.line);
      if (typeof l === 'string' && typeof r === 'string') return l + r;
      if (Array.isArray(l) && Array.isArray(r)) return [...l, ...r];
      throw new RuntimeError(expr.line, `cannot apply + to ${typeOf(l)} and ${typeOf(r)}`);
    }
    if (op === '-' || op === '*' || op === '/' || op === '%') {
      if (typeof l !== 'bigint' || typeof r !== 'bigint')
        throw new RuntimeError(expr.line, `cannot apply ${op} to ${typeOf(l)} and ${typeOf(r)}`);
      if ((op === '/' || op === '%') && r === 0n)
        throw new RuntimeError(expr.line, 'division by zero');
      let res: bigint;
      if (op === '-') res = l - r;
      else if (op === '*') res = l * r;
      else if (op === '/') res = l / r;
      else res = l % r;
      return checkInt(res, expr.line);
    }
    if (op === '<' || op === '<=' || op === '>' || op === '>=') {
      if (typeof l === 'bigint' && typeof r === 'bigint') {
        if (op === '<') return l < r;
        if (op === '<=') return l <= r;
        if (op === '>') return l > r;
        return l >= r;
      }
      if (typeof l === 'string' && typeof r === 'string') {
        if (op === '<') return l < r;
        if (op === '<=') return l <= r;
        if (op === '>') return l > r;
        return l >= r;
      }
      throw new RuntimeError(expr.line, `cannot apply ${op} to ${typeOf(l)} and ${typeOf(r)}`);
    }
    throw new RuntimeError(expr.line, `unknown operator ${op}`);
  }

  evalCall(expr: { callee: Expr; args: Expr[]; line: number }, scope: Scope): Val {
    const callee = this.eval(expr.callee, scope);
    const args = expr.args.map(a => this.eval(a, scope));

    if (callee === null || typeof callee !== 'object' || !('kind' in callee)) {
      throw new RuntimeError(expr.line, `cannot call ${typeOf(callee)}`);
    }
    const fn = callee as FuncVal;

    if (fn.kind === 'builtin') {
      if (fn.arity >= 0 && args.length !== fn.arity) {
        throw new RuntimeError(expr.line, `expected ${fn.arity} arguments, got ${args.length}`);
      }
      return fn.fn(args, expr.line);
    }

    // user function
    if (args.length !== fn.params.length) {
      throw new RuntimeError(expr.line, `expected ${fn.params.length} arguments, got ${args.length}`);
    }
    const callScope = new Scope(fn.scope);
    for (let i = 0; i < fn.params.length; i++) {
      callScope.declare(fn.params[i], args[i]);
    }
    try {
      this.run(fn.body, callScope);
    } catch (e) {
      if (e instanceof ReturnSignal) return e.value;
      throw e;
    }
    return null;
  }

  evalIndex(expr: { obj: Expr; index: Expr; line: number }, scope: Scope): Val {
    const obj = this.eval(expr.obj, scope);
    const idx = this.eval(expr.index, scope);
    if ((!Array.isArray(obj) && typeof obj !== 'string') || typeof idx !== 'bigint') {
      throw new RuntimeError(expr.line, `cannot index ${typeOf(obj)} with ${typeOf(idx)}`);
    }
    const i = Number(idx);
    const len = Array.isArray(obj) ? obj.length : (obj as string).length;
    if (i < 0 || i >= len) {
      throw new RuntimeError(expr.line, `index ${idx} out of range for length ${len}`);
    }
    if (Array.isArray(obj)) return obj[i];
    return (obj as string)[i];
  }
}

// ===== MAIN =====
const dir = process.argv[2];
const src = fs.readFileSync(path.join(dir, 'program.tern'), 'utf-8');
const tokens = lex(src);
const parser = new Parser(tokens);
const program = parser.parseProgram();
const interp = new Interpreter();

try {
  interp.run(program, interp.globalScope);
} catch (e) {
  if (e instanceof RuntimeError) {
    process.stdout.write(interp.output.join(''));
    process.stdout.write(`error at line ${e.line}: ${e.msg}\n`);
    process.exit(0);
  }
  if (e instanceof BreakSignal || e instanceof ContinueSignal || e instanceof ReturnSignal) {
    // shouldn't happen at top level
  }
  throw e;
}

process.stdout.write(interp.output.join(''));
process.exit(0);

import sys, os

INT_MIN = -(1 << 63)
INT_MAX = (1 << 63) - 1

KEYWORDS = frozenset(['let','fn','if','else','while','for','in','return',
                       'break','continue','and','or','not','true','false','nil'])

def tokenize(source):
    tokens = []
    i = 0
    line = 1
    n = len(source)
    while i < n:
        c = source[i]
        if c == '\n':
            line += 1; i += 1; continue
        if c in ' \t\r':
            i += 1; continue
        if c == '#':
            while i < n and source[i] != '\n': i += 1
            continue
        if c.isdigit():
            j = i
            while j < n and source[j].isdigit(): j += 1
            tokens.append(('INT', int(source[i:j]), line))
            i = j; continue
        if c == '"':
            i += 1; s = []
            while i < n and source[i] != '"':
                if source[i] == '\\':
                    i += 1; nc = source[i]
                    if nc == 'n': s.append('\n')
                    elif nc == 't': s.append('\t')
                    elif nc == '"': s.append('"')
                    elif nc == '\\': s.append('\\')
                    else: s.append(nc)
                else:
                    s.append(source[i])
                i += 1
            i += 1
            tokens.append(('STR', ''.join(s), line)); continue
        if c.isalpha() or c == '_':
            j = i
            while j < n and (source[j].isalnum() or source[j] == '_'): j += 1
            word = source[i:j]
            tokens.append(('KW' if word in KEYWORDS else 'IDENT', word, line))
            i = j; continue
        if i + 1 < n and source[i:i+2] in ('==','!=','<=','>='):
            tokens.append(('OP', source[i:i+2], line)); i += 2; continue
        if c in '<>+-*/%=':
            tokens.append(('OP', c, line)); i += 1; continue
        if c in '()[]{},;':
            tokens.append((c, c, line)); i += 1; continue
        i += 1
    tokens.append(('EOF', None, line))
    return tokens

class Parser:
    def __init__(self, tokens):
        self.tokens = tokens; self.pos = 0
    def peek(self): return self.tokens[self.pos]
    def advance(self):
        t = self.tokens[self.pos]; self.pos += 1; return t
    def expect(self, tt, tv=None):
        t = self.advance()
        if t[0] != tt or (tv is not None and t[1] != tv):
            raise SyntaxError(f"Expected {tt} {tv}, got {t}")
        return t
    def is_index_assign(self):
        depth = 0; i = self.pos
        while i < len(self.tokens):
            if self.tokens[i][0] == '[': depth += 1
            elif self.tokens[i][0] == ']':
                depth -= 1
                if depth == 0:
                    return i+1 < len(self.tokens) and self.tokens[i+1][0] == 'OP' and self.tokens[i+1][1] == '='
            i += 1
        return False
    def parse_program(self):
        stmts = []
        while self.peek()[0] != 'EOF': stmts.append(self.parse_stmt())
        return stmts
    def parse_stmt(self):
        t = self.peek()
        if t[0] == 'KW':
            kw = t[1]
            if kw == 'let': return self.parse_let()
            if kw == 'fn': return self.parse_fn_decl()
            if kw == 'if': return self.parse_if()
            if kw == 'while': return self.parse_while()
            if kw == 'for': return self.parse_for()
            if kw == 'return': return self.parse_return()
            if kw == 'break': self.advance(); self.expect(';'); return ('break', t[2])
            if kw == 'continue': self.advance(); self.expect(';'); return ('continue', t[2])
        if t[0] == 'IDENT':
            nt = self.tokens[self.pos + 1]
            if nt[0] == 'OP' and nt[1] == '=': return self.parse_assign()
        return self.parse_expr_or_index_assign()
    def parse_let(self):
        self.advance(); name = self.expect('IDENT'); self.expect('OP','=')
        expr = self.parse_expr(); self.expect(';')
        return ('let', name[1], expr, name[2])
    def parse_fn_decl(self):
        self.advance(); name = self.expect('IDENT'); self.expect('(')
        params = self.parse_params(); self.expect(')'); body = self.parse_block()
        return ('fn_decl', name[1], params, body, name[2])
    def parse_params(self):
        params = []
        if self.peek()[0] != ')':
            params.append(self.expect('IDENT')[1])
            while self.peek()[0] == ',':
                self.advance(); params.append(self.expect('IDENT')[1])
        return params
    def parse_block(self):
        self.expect('{'); stmts = []
        while self.peek()[0] != '}': stmts.append(self.parse_stmt())
        self.expect('}'); return stmts
    def parse_if(self):
        t = self.advance(); cond = self.parse_expr(); then_b = self.parse_block()
        else_b = None
        if self.peek()[0] == 'KW' and self.peek()[1] == 'else':
            self.advance()
            if self.peek()[0] == 'KW' and self.peek()[1] == 'if':
                else_b = ('if_else', self.parse_if())
            else:
                else_b = ('block', self.parse_block())
        return ('if', cond, then_b, else_b, t[2])
    def parse_while(self):
        t = self.advance(); cond = self.parse_expr(); body = self.parse_block()
        return ('while', cond, body, t[2])
    def parse_for(self):
        t = self.advance(); name = self.expect('IDENT'); self.expect('KW','in')
        expr = self.parse_expr(); body = self.parse_block()
        return ('for', name[1], expr, body, t[2])
    def parse_return(self):
        t = self.advance()
        if self.peek()[0] == ';': self.advance(); return ('return', None, t[2])
        expr = self.parse_expr(); self.expect(';')
        return ('return', expr, t[2])
    def parse_assign(self):
        name = self.expect('IDENT'); self.expect('OP','=')
        expr = self.parse_expr(); self.expect(';')
        return ('assign', name[1], expr, name[2])
    def parse_expr_or_index_assign(self):
        expr = self.parse_expr()
        if self.peek()[0] == '[':
            line = self.peek()[2]; self.advance()
            idx = self.parse_expr(); self.expect(']'); self.expect('OP','=')
            val = self.parse_expr(); self.expect(';')
            return ('index_assign', expr, idx, val, line)
        self.expect(';')
        return ('expr_stmt', expr, expr[2] if len(expr) > 2 else 0)
    def parse_expr(self): return self.parse_or()
    def parse_or(self):
        left = self.parse_and()
        while self.peek()[0] == 'KW' and self.peek()[1] == 'or':
            t = self.advance(); right = self.parse_and()
            left = ('binary','or',left,right,t[2])
        return left
    def parse_and(self):
        left = self.parse_not()
        while self.peek()[0] == 'KW' and self.peek()[1] == 'and':
            t = self.advance(); right = self.parse_not()
            left = ('binary','and',left,right,t[2])
        return left
    def parse_not(self):
        if self.peek()[0] == 'KW' and self.peek()[1] == 'not':
            t = self.advance(); return ('not', self.parse_not(), t[2])
        return self.parse_comparison()
    def parse_comparison(self):
        left = self.parse_add()
        while self.peek()[0] == 'OP' and self.peek()[1] in ('==','!=','<','<=','>','>='):
            t = self.advance(); right = self.parse_add()
            left = ('binary',t[1],left,right,t[2])
        return left
    def parse_add(self):
        left = self.parse_mul()
        while self.peek()[0] == 'OP' and self.peek()[1] in ('+','-'):
            t = self.advance(); right = self.parse_mul()
            left = ('binary',t[1],left,right,t[2])
        return left
    def parse_mul(self):
        left = self.parse_unary()
        while self.peek()[0] == 'OP' and self.peek()[1] in ('*','/','%'):
            t = self.advance(); right = self.parse_unary()
            left = ('binary',t[1],left,right,t[2])
        return left
    def parse_unary(self):
        if self.peek()[0] == 'OP' and self.peek()[1] == '-':
            t = self.advance(); return ('neg', self.parse_postfix(), t[2])
        return self.parse_postfix()
    def parse_postfix(self):
        expr = self.parse_primary()
        while True:
            t = self.peek()
            if t[0] == '(':
                t = self.advance(); args = []
                if self.peek()[0] != ')':
                    args.append(self.parse_expr())
                    while self.peek()[0] == ',':
                        self.advance(); args.append(self.parse_expr())
                self.expect(')')
                expr = ('call', expr, args, t[2])
            elif t[0] == '[':
                if self.is_index_assign(): break
                t = self.advance(); idx = self.parse_expr(); self.expect(']')
                expr = ('index', expr, idx, t[2])
            else: break
        return expr
    def parse_primary(self):
        t = self.peek()
        if t[0] == 'INT': self.advance(); return ('int', t[1], t[2])
        if t[0] == 'STR': self.advance(); return ('str', t[1], t[2])
        if t[0] == 'KW':
            if t[1] == 'true': self.advance(); return ('bool', True, t[2])
            if t[1] == 'false': self.advance(); return ('bool', False, t[2])
            if t[1] == 'nil': self.advance(); return ('nil', None, t[2])
            if t[1] == 'fn': return self.parse_fn_expr()
        if t[0] == 'IDENT': self.advance(); return ('ident', t[1], t[2])
        if t[0] == '(':
            self.advance(); expr = self.parse_expr(); self.expect(')'); return expr
        if t[0] == '[':
            self.advance(); elems = []
            if self.peek()[0] != ']':
                elems.append(self.parse_expr())
                while self.peek()[0] == ',':
                    self.advance(); elems.append(self.parse_expr())
            self.expect(']'); return ('list', elems, t[2])
        raise SyntaxError(f"Unexpected token: {t}")
    def parse_fn_expr(self):
        t = self.advance(); self.expect('(')
        params = self.parse_params(); self.expect(')'); body = self.parse_block()
        return ('fn', params, body, t[2])

class TernError(Exception):
    def __init__(self, line, message): self.line = line; self.message = message
class BreakSignal(Exception): pass
class ContinueSignal(Exception): pass
class ReturnSignal(Exception):
    def __init__(self, value): self.value = value

class TernFn:
    __slots__ = ('params','body','closure')
    def __init__(self, params, body, closure):
        self.params = params; self.body = body; self.closure = closure

class BuiltinFn:
    __slots__ = ('name','func','arity')
    def __init__(self, name, func, arity):
        self.name = name; self.func = func; self.arity = arity

class Scope:
    __slots__ = ('vars','parent')
    def __init__(self, parent=None):
        self.vars = {}; self.parent = parent

_NOT_FOUND = object()

def scope_get(scope, name):
    s = scope
    while s is not None:
        v = s.vars.get(name, _NOT_FOUND)
        if v is not _NOT_FOUND: return v
        s = s.parent
    return _NOT_FOUND

def scope_set(scope, name, val):
    s = scope
    while s is not None:
        if name in s.vars: s.vars[name] = val; return True
        s = s.parent
    return False

def type_name(v):
    if isinstance(v, bool): return 'bool'
    if isinstance(v, int): return 'int'
    if isinstance(v, str): return 'string'
    if isinstance(v, list): return 'list'
    if isinstance(v, (TernFn, BuiltinFn)): return 'function'
    if v is None: return 'nil'
    return 'unknown'

def is_int(v): return isinstance(v, int) and not isinstance(v, bool)

def is_truthy(v):
    if v is None: return False
    if isinstance(v, bool): return v
    if isinstance(v, int): return v != 0
    if isinstance(v, str): return len(v) > 0
    if isinstance(v, list): return len(v) > 0
    return True

def tern_eq(a, b):
    ta = type_name(a); tb = type_name(b)
    if ta != tb: return False
    if ta in ('int','bool','string'): return a == b
    if ta == 'nil': return True
    if ta == 'list':
        if len(a) != len(b): return False
        for i in range(len(a)):
            if not tern_eq(a[i], b[i]): return False
        return True
    if ta == 'function': return a is b
    return False

def int_div(a, b):
    q = abs(a) // abs(b)
    if (a < 0) ^ (b < 0): return -q
    return q

def check_int(v, line):
    if v < INT_MIN or v > INT_MAX: raise TernError(line, 'integer overflow')

output_parts = []
def write(s): output_parts.append(s)

def display(v, in_list=False, seen=None):
    if seen is None: seen = set()
    if isinstance(v, bool): return 'true' if v else 'false'
    if isinstance(v, int): return str(v)
    if isinstance(v, str):
        if in_list:
            return '"' + v.replace('\\','\\\\').replace('"','\\"').replace('\n','\\n').replace('\t','\\t') + '"'
        return v
    if v is None: return 'nil'
    if isinstance(v, list):
        if id(v) in seen: return '[...]'
        seen.add(id(v))
        parts = [display(e, True, seen) for e in v]
        seen.discard(id(v))
        return '[' + ', '.join(parts) + ']'
    if isinstance(v, (TernFn, BuiltinFn)): return '<fn>'
    return '<unknown>'

def builtin_print(args, line):
    write(' '.join(display(a) for a in args) + '\n')
    return None

def builtin_str(args, line): return display(args[0])
def builtin_type(args, line): return type_name(args[0])

def builtin_len(args, line):
    v = args[0]
    if isinstance(v, str) or isinstance(v, list): return len(v)
    raise TernError(line, 'bad argument to len')

def builtin_push(args, line):
    lst, val = args
    if not isinstance(lst, list): raise TernError(line, 'bad argument to push')
    lst.append(val); return None

def builtin_pop(args, line):
    lst = args[0]
    if not isinstance(lst, list) or len(lst) == 0: raise TernError(line, 'bad argument to pop')
    return lst.pop()

def builtin_range(args, line):
    a, b = args
    if not is_int(a) or not is_int(b): raise TernError(line, 'bad argument to range')
    return list(range(a, b))

def builtin_slice(args, line):
    x, a, b = args
    if not is_int(a) or not is_int(b): raise TernError(line, 'bad argument to slice')
    if isinstance(x, str):
        if not (0 <= a <= b <= len(x)): raise TernError(line, 'bad argument to slice')
        return x[a:b]
    if isinstance(x, list):
        if not (0 <= a <= b <= len(x)): raise TernError(line, 'bad argument to slice')
        return x[a:b]
    raise TernError(line, 'bad argument to slice')

def make_builtins():
    b = {}
    b['print'] = BuiltinFn('print', builtin_print, None)
    b['str'] = BuiltinFn('str', builtin_str, 1)
    b['type'] = BuiltinFn('type', builtin_type, 1)
    b['len'] = BuiltinFn('len', builtin_len, 1)
    b['push'] = BuiltinFn('push', builtin_push, 2)
    b['pop'] = BuiltinFn('pop', builtin_pop, 1)
    b['range'] = BuiltinFn('range', builtin_range, 2)
    b['slice'] = BuiltinFn('slice', builtin_slice, 3)
    return b

def eval_binary(op, left, right, line):
    if op == '==': return tern_eq(left, right)
    if op == '!=': return not tern_eq(left, right)
    if op in ('<','<=','>','>='):
        if isinstance(left, bool) or isinstance(right, bool):
            raise TernError(line, f'cannot apply {op} to {type_name(left)} and {type_name(right)}')
        if is_int(left) and is_int(right): pass
        elif isinstance(left, str) and isinstance(right, str): pass
        else: raise TernError(line, f'cannot apply {op} to {type_name(left)} and {type_name(right)}')
        if op == '<': return left < right
        if op == '<=': return left <= right
        if op == '>': return left > right
        return left >= right
    if op == '+':
        if isinstance(left, bool) or isinstance(right, bool):
            raise TernError(line, f'cannot apply + to {type_name(left)} and {type_name(right)}')
        if is_int(left) and is_int(right):
            r = left + right; check_int(r, line); return r
        if isinstance(left, str) and isinstance(right, str): return left + right
        if isinstance(left, list) and isinstance(right, list): return left + right
        raise TernError(line, f'cannot apply + to {type_name(left)} and {type_name(right)}')
    if op in ('-','*','/','%'):
        if not is_int(left) or not is_int(right):
            raise TernError(line, f'cannot apply {op} to {type_name(left)} and {type_name(right)}')
        if op == '-': r = left - right; check_int(r, line); return r
        if op == '*': r = left * right; check_int(r, line); return r
        if op == '/':
            if right == 0: raise TernError(line, 'division by zero')
            r = int_div(left, right); check_int(r, line); return r
        if op == '%':
            if right == 0: raise TernError(line, 'division by zero')
            r = left - int_div(left, right) * right; check_int(r, line); return r
    raise RuntimeError(f'Unknown operator: {op}')

def eval_index(obj, idx, line):
    if isinstance(obj, list):
        if not is_int(idx): raise TernError(line, f'cannot index list with {type_name(idx)}')
        if idx < 0 or idx >= len(obj): raise TernError(line, f'index {idx} out of range for length {len(obj)}')
        return obj[idx]
    if isinstance(obj, str):
        if not is_int(idx): raise TernError(line, f'cannot index string with {type_name(idx)}')
        if idx < 0 or idx >= len(obj): raise TernError(line, f'index {idx} out of range for length {len(obj)}')
        return obj[idx]
    raise TernError(line, f'cannot index {type_name(obj)} with {type_name(idx)}')

def call_fn(fn, args, line):
    if isinstance(fn, BuiltinFn):
        if fn.arity is not None and len(args) != fn.arity:
            raise TernError(line, f'expected {fn.arity} arguments, got {len(args)}')
        return fn.func(args, line)
    if isinstance(fn, TernFn):
        if len(args) != len(fn.params):
            raise TernError(line, f'expected {len(fn.params)} arguments, got {len(args)}')
        call_scope = Scope(fn.closure)
        for i in range(len(fn.params)):
            call_scope.vars[fn.params[i]] = args[i]
        try:
            exec_stmts(fn.body, call_scope)
        except ReturnSignal as r:
            return r.value
        return None
    raise TernError(line, f'cannot call {type_name(fn)}')

def eval_expr(node, scope):
    tag = node[0]
    if tag == 'int': return node[1]
    if tag == 'str': return node[1]
    if tag == 'bool': return node[1]
    if tag == 'nil': return None
    if tag == 'ident':
        val = scope_get(scope, node[1])
        if val is _NOT_FOUND: raise TernError(node[2], f'undefined variable {node[1]}')
        return val
    if tag == 'list':
        return [eval_expr(e, scope) for e in node[1]]
    if tag == 'fn':
        return TernFn(node[1], node[2], scope)
    if tag == 'binary':
        op = node[1]
        if op == 'and':
            left = eval_expr(node[2], scope)
            if not is_truthy(left): return left
            return eval_expr(node[3], scope)
        if op == 'or':
            left = eval_expr(node[2], scope)
            if is_truthy(left): return left
            return eval_expr(node[3], scope)
        left = eval_expr(node[2], scope)
        right = eval_expr(node[3], scope)
        return eval_binary(op, left, right, node[4])
    if tag == 'not':
        return not is_truthy(eval_expr(node[1], scope))
    if tag == 'neg':
        v = eval_expr(node[1], scope)
        if not is_int(v): raise TernError(node[2], f'cannot apply - to {type_name(v)}')
        r = -v; check_int(r, node[2]); return r
    if tag == 'call':
        callee = eval_expr(node[1], scope)
        args = [eval_expr(a, scope) for a in node[2]]
        return call_fn(callee, args, node[3])
    if tag == 'index':
        obj = eval_expr(node[1], scope)
        idx = eval_expr(node[2], scope)
        return eval_index(obj, idx, node[3])
    raise RuntimeError(f'Unknown expression tag: {tag}')

def exec_stmts(stmts, scope):
    for stmt in stmts:
        exec_stmt(stmt, scope)

def exec_stmt(node, scope):
    tag = node[0]
    if tag == 'let':
        scope.vars[node[1]] = eval_expr(node[2], scope)
    elif tag == 'fn_decl':
        scope.vars[node[1]] = TernFn(node[2], node[3], scope)
    elif tag == 'if':
        if is_truthy(eval_expr(node[1], scope)):
            bs = Scope(scope); exec_stmts(node[2], bs)
        elif node[3] is not None:
            if node[3][0] == 'if_else': exec_stmt(node[3][1], scope)
            else: bs = Scope(scope); exec_stmts(node[3][1], bs)
    elif tag == 'while':
        while True:
            if not is_truthy(eval_expr(node[1], scope)): break
            ls = Scope(scope)
            try: exec_stmts(node[2], ls)
            except BreakSignal: break
            except ContinueSignal: continue
    elif tag == 'for':
        iterable = eval_expr(node[2], scope)
        if not isinstance(iterable, list):
            raise TernError(node[4], f'cannot iterate {type_name(iterable)}')
        i = 0
        while i < len(iterable):
            ls = Scope(scope)
            ls.vars[node[1]] = iterable[i]
            try: exec_stmts(node[3], ls)
            except BreakSignal: break
            except ContinueSignal: pass
            i += 1
    elif tag == 'return':
        if node[1] is not None: raise ReturnSignal(eval_expr(node[1], scope))
        raise ReturnSignal(None)
    elif tag == 'break': raise BreakSignal()
    elif tag == 'continue': raise ContinueSignal()
    elif tag == 'assign':
        val = eval_expr(node[2], scope)
        if not scope_set(scope, node[1], val):
            raise TernError(node[3], f'undefined variable {node[1]}')
    elif tag == 'index_assign':
        obj = eval_expr(node[1], scope)
        idx = eval_expr(node[2], scope)
        val = eval_expr(node[3], scope)
        if not isinstance(obj, list):
            raise TernError(node[4], f'cannot assign into {type_name(obj)}')
        if not is_int(idx):
            raise TernError(node[4], f'cannot index list with {type_name(idx)}')
        if idx < 0 or idx >= len(obj):
            raise TernError(node[4], f'index {idx} out of range for length {len(obj)}')
        obj[idx] = val
    elif tag == 'expr_stmt':
        eval_expr(node[1], scope)

def main():
    directory = sys.argv[1]
    with open(os.path.join(directory, 'program.tern'), 'r') as f:
        source = f.read()
    tokens = tokenize(source)
    parser = Parser(tokens)
    ast = parser.parse_program()
    builtins = make_builtins()
    gs = Scope()
    for name, fn in builtins.items(): gs.vars[name] = fn
    try:
        exec_stmts(ast, gs)
    except TernError as e:
        write(f'error at line {e.line}: {e.message}\n')
    sys.stdout.write(''.join(output_parts))

if __name__ == '__main__':
    main()

import java.io.*;
import java.nio.file.*;
import java.util.*;

public class Main {

    // ==================== TOKENS ====================
    enum TT { INT, STR, IDENT, LET, FN, IF, ELSE, WHILE, FOR, IN, RETURN, BREAK, CONTINUE,
              AND, OR, NOT, TRUE, FALSE, NIL,
              EQ, NEQ, LTE, GTE, LT, GT, ASSIGN, PLUS, MINUS, STAR, SLASH, PERCENT,
              LPAREN, RPAREN, LBRACKET, RBRACKET, LBRACE, RBRACE, COMMA, SEMI, EOF }

    static class Token {
        TT type; String text; int line; long intVal; String strVal;
        Token(TT type, String text, int line) { this.type = type; this.text = text; this.line = line; }
    }

    // ==================== LEXER ====================
    static final Map<String, TT> KEYWORDS = new HashMap<>();
    static final Map<String, TT> TWO_OPS = new HashMap<>();
    static final Map<Character, TT> ONE_OPS = new HashMap<>();
    static {
        KEYWORDS.put("let", TT.LET); KEYWORDS.put("fn", TT.FN); KEYWORDS.put("if", TT.IF);
        KEYWORDS.put("else", TT.ELSE); KEYWORDS.put("while", TT.WHILE); KEYWORDS.put("for", TT.FOR);
        KEYWORDS.put("in", TT.IN); KEYWORDS.put("return", TT.RETURN); KEYWORDS.put("break", TT.BREAK);
        KEYWORDS.put("continue", TT.CONTINUE); KEYWORDS.put("and", TT.AND); KEYWORDS.put("or", TT.OR);
        KEYWORDS.put("not", TT.NOT); KEYWORDS.put("true", TT.TRUE); KEYWORDS.put("false", TT.FALSE);
        KEYWORDS.put("nil", TT.NIL);
        TWO_OPS.put("==", TT.EQ); TWO_OPS.put("!=", TT.NEQ); TWO_OPS.put("<=", TT.LTE); TWO_OPS.put(">=", TT.GTE);
        ONE_OPS.put('<', TT.LT); ONE_OPS.put('>', TT.GT); ONE_OPS.put('=', TT.ASSIGN);
        ONE_OPS.put('+', TT.PLUS); ONE_OPS.put('-', TT.MINUS); ONE_OPS.put('*', TT.STAR);
        ONE_OPS.put('/', TT.SLASH); ONE_OPS.put('%', TT.PERCENT);
        ONE_OPS.put('(', TT.LPAREN); ONE_OPS.put(')', TT.RPAREN);
        ONE_OPS.put('[', TT.LBRACKET); ONE_OPS.put(']', TT.RBRACKET);
        ONE_OPS.put('{', TT.LBRACE); ONE_OPS.put('}', TT.RBRACE);
        ONE_OPS.put(',', TT.COMMA); ONE_OPS.put(';', TT.SEMI);
    }

    static List<Token> lex(String src) {
        List<Token> tokens = new ArrayList<>();
        int i = 0, line = 1, n = src.length();
        while (i < n) {
            char c = src.charAt(i);
            if (c == '\n') { line++; i++; continue; }
            if (c == ' ' || c == '\t' || c == '\r') { i++; continue; }
            if (c == '#') { while (i < n && src.charAt(i) != '\n') i++; continue; }
            if (c >= '0' && c <= '9') {
                int start = i;
                while (i < n && src.charAt(i) >= '0' && src.charAt(i) <= '9') i++;
                Token t = new Token(TT.INT, src.substring(start, i), line);
                t.intVal = Long.parseLong(t.text);
                tokens.add(t); continue;
            }
            if (c == '"') {
                i++;
                StringBuilder sb = new StringBuilder();
                while (i < n && src.charAt(i) != '"') {
                    if (src.charAt(i) == '\\') {
                        i++;
                        switch (src.charAt(i)) {
                            case 'n': sb.append('\n'); break;
                            case 't': sb.append('\t'); break;
                            case '"': sb.append('"'); break;
                            case '\\': sb.append('\\'); break;
                        }
                    } else { sb.append(src.charAt(i)); }
                    i++;
                }
                i++;
                Token t = new Token(TT.STR, sb.toString(), line);
                t.strVal = sb.toString();
                tokens.add(t); continue;
            }
            if ((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || c == '_') {
                int start = i;
                while (i < n) {
                    char ch = src.charAt(i);
                    if ((ch >= 'a' && ch <= 'z') || (ch >= 'A' && ch <= 'Z') || (ch >= '0' && ch <= '9') || ch == '_') i++;
                    else break;
                }
                String word = src.substring(start, i);
                tokens.add(new Token(KEYWORDS.getOrDefault(word, TT.IDENT), word, line));
                continue;
            }
            if (i + 1 < n) {
                TT tt = TWO_OPS.get(src.substring(i, i + 2));
                if (tt != null) { tokens.add(new Token(tt, src.substring(i, i + 2), line)); i += 2; continue; }
            }
            TT ot = ONE_OPS.get(c);
            if (ot != null) { tokens.add(new Token(ot, String.valueOf(c), line)); i++; continue; }
            i++;
        }
        tokens.add(new Token(TT.EOF, "", line));
        return tokens;
    }

    // ==================== AST ====================
    abstract static class Stmt {}
    static class LetStmt extends Stmt { String name; Expr value; int line; }
    static class FnDeclStmt extends Stmt { String name; List<String> params; List<Stmt> body; int line; }
    static class IfStmt extends Stmt { Expr cond; List<Stmt> thenBody; List<Stmt> elseBody; int line; }
    static class WhileStmt extends Stmt { Expr cond; List<Stmt> body; int line; }
    static class ForStmt extends Stmt { String varName; Expr iterable; List<Stmt> body; int line; }
    static class ReturnStmt extends Stmt { Expr value; int line; }
    static class BreakStmt extends Stmt {}
    static class ContinueStmt extends Stmt {}
    static class AssignStmt extends Stmt { String name; Expr value; int line; }
    static class IndexAssignStmt extends Stmt { Expr obj; Expr index; Expr value; int line; }
    static class ExprStmt extends Stmt { Expr expr; }

    abstract static class Expr { int line; }
    static class IntLit extends Expr { long value; }
    static class StrLit extends Expr { String value; }
    static class BoolLit extends Expr { boolean value; }
    static class NilLit extends Expr {}
    static class IdentExpr extends Expr { String name; }
    static class BinaryExpr extends Expr { String op; Expr left, right; }
    static class NotExpr extends Expr { Expr operand; }
    static class NegExpr extends Expr { Expr operand; }
    static class CallExpr extends Expr { Expr callee; List<Expr> args; }
    static class IndexExpr extends Expr { Expr obj; Expr index; }
    static class ListLit extends Expr { List<Expr> elements; }
    static class FnExpr extends Expr { List<String> params; List<Stmt> body; }

    // ==================== PARSER ====================
    static class Parser {
        List<Token> tokens; int pos;
        Parser(List<Token> tokens) { this.tokens = tokens; this.pos = 0; }
        Token peek() { return tokens.get(pos); }
        Token advance() { return tokens.get(pos++); }
        boolean check(TT t) { return peek().type == t; }
        boolean match(TT t) { if (check(t)) { advance(); return true; } return false; }
        Token expect(TT t) { Token tk = peek(); if (tk.type == t) { advance(); return tk; } throw new RuntimeException("Expected " + t + " got " + tk.type + " line " + tk.line); }

        List<Stmt> parseProgram() { List<Stmt> s = new ArrayList<>(); while (!check(TT.EOF)) s.add(parseStmt()); return s; }

        List<Stmt> parseBlock() {
            expect(TT.LBRACE); List<Stmt> s = new ArrayList<>();
            while (!check(TT.RBRACE) && !check(TT.EOF)) s.add(parseStmt());
            expect(TT.RBRACE); return s;
        }

        Stmt parseStmt() {
            Token t = peek();
            switch (t.type) {
                case LET: return parseLet();
                case FN:
                    if (tokens.get(pos + 1).type == TT.IDENT) return parseFnDecl();
                    return parseExprStmt();
                case IF: return parseIf();
                case WHILE: return parseWhile();
                case FOR: return parseFor();
                case RETURN: return parseReturn();
                case BREAK: advance(); expect(TT.SEMI); return new BreakStmt();
                case CONTINUE: advance(); expect(TT.SEMI); return new ContinueStmt();
                case IDENT:
                    if (tokens.get(pos + 1).type == TT.ASSIGN) return parseAssign();
                    return parseExprStmt();
                default: return parseExprStmt();
            }
        }

        Stmt parseLet() {
            Token tk = advance(); String name = expect(TT.IDENT).text; expect(TT.ASSIGN);
            Expr val = parseExpr(); expect(TT.SEMI);
            LetStmt s = new LetStmt(); s.name = name; s.value = val; s.line = tk.line; return s;
        }
        Stmt parseFnDecl() {
            Token tk = advance(); String name = expect(TT.IDENT).text; expect(TT.LPAREN);
            List<String> params = parseParams(); expect(TT.RPAREN); List<Stmt> body = parseBlock();
            FnDeclStmt s = new FnDeclStmt(); s.name = name; s.params = params; s.body = body; s.line = tk.line; return s;
        }
        Stmt parseIf() {
            Token tk = advance(); Expr cond = parseExpr(); List<Stmt> thenB = parseBlock();
            List<Stmt> elseB = null;
            if (check(TT.ELSE)) { advance(); if (check(TT.IF)) { elseB = new ArrayList<>(); elseB.add(parseIf()); } else { elseB = parseBlock(); } }
            IfStmt s = new IfStmt(); s.cond = cond; s.thenBody = thenB; s.elseBody = elseB; s.line = tk.line; return s;
        }
        Stmt parseWhile() {
            Token tk = advance(); Expr cond = parseExpr(); List<Stmt> body = parseBlock();
            WhileStmt s = new WhileStmt(); s.cond = cond; s.body = body; s.line = tk.line; return s;
        }
        Stmt parseFor() {
            Token tk = advance(); String var = expect(TT.IDENT).text; expect(TT.IN);
            Expr iter = parseExpr(); List<Stmt> body = parseBlock();
            ForStmt s = new ForStmt(); s.varName = var; s.iterable = iter; s.body = body; s.line = tk.line; return s;
        }
        Stmt parseReturn() {
            Token tk = advance(); Expr val = null;
            if (!check(TT.SEMI)) val = parseExpr();
            expect(TT.SEMI);
            ReturnStmt s = new ReturnStmt(); s.value = val; s.line = tk.line; return s;
        }
        Stmt parseAssign() {
            Token tk = advance(); expect(TT.ASSIGN); Expr val = parseExpr(); expect(TT.SEMI);
            AssignStmt s = new AssignStmt(); s.name = tk.text; s.value = val; s.line = tk.line; return s;
        }
        Stmt parseExprStmt() {
            Expr expr = parseExpr();
            if (check(TT.ASSIGN) && expr instanceof IndexExpr) {
                advance(); Expr val = parseExpr(); expect(TT.SEMI);
                IndexExpr ie = (IndexExpr) expr;
                IndexAssignStmt s = new IndexAssignStmt(); s.obj = ie.obj; s.index = ie.index; s.value = val; s.line = ie.line; return s;
            }
            expect(TT.SEMI);
            ExprStmt s = new ExprStmt(); s.expr = expr; return s;
        }
        List<String> parseParams() {
            List<String> p = new ArrayList<>();
            if (!check(TT.RPAREN)) { p.add(expect(TT.IDENT).text); while (match(TT.COMMA)) p.add(expect(TT.IDENT).text); }
            return p;
        }

        Expr parseExpr() { return parseOr(); }
        Expr parseOr() {
            Expr l = parseAnd();
            while (check(TT.OR)) { Token op = advance(); Expr r = parseAnd(); BinaryExpr e = new BinaryExpr(); e.op = "or"; e.left = l; e.right = r; e.line = op.line; l = e; }
            return l;
        }
        Expr parseAnd() {
            Expr l = parseNot();
            while (check(TT.AND)) { Token op = advance(); Expr r = parseNot(); BinaryExpr e = new BinaryExpr(); e.op = "and"; e.left = l; e.right = r; e.line = op.line; l = e; }
            return l;
        }
        Expr parseNot() {
            if (check(TT.NOT)) { Token op = advance(); NotExpr e = new NotExpr(); e.operand = parseNot(); e.line = op.line; return e; }
            return parseComparison();
        }
        Expr parseComparison() {
            Expr l = parseAdd();
            while (check(TT.EQ) || check(TT.NEQ) || check(TT.LT) || check(TT.LTE) || check(TT.GT) || check(TT.GTE)) {
                Token op = advance(); Expr r = parseAdd();
                BinaryExpr e = new BinaryExpr(); e.op = op.text; e.left = l; e.right = r; e.line = op.line; l = e;
            }
            return l;
        }
        Expr parseAdd() {
            Expr l = parseMul();
            while (check(TT.PLUS) || check(TT.MINUS)) {
                Token op = advance(); Expr r = parseMul();
                BinaryExpr e = new BinaryExpr(); e.op = op.text; e.left = l; e.right = r; e.line = op.line; l = e;
            }
            return l;
        }
        Expr parseMul() {
            Expr l = parseNeg();
            while (check(TT.STAR) || check(TT.SLASH) || check(TT.PERCENT)) {
                Token op = advance(); Expr r = parseNeg();
                BinaryExpr e = new BinaryExpr(); e.op = op.text; e.left = l; e.right = r; e.line = op.line; l = e;
            }
            return l;
        }
        Expr parseNeg() {
            if (check(TT.MINUS)) { Token op = advance(); NegExpr e = new NegExpr(); e.operand = parseNeg(); e.line = op.line; return e; }
            return parsePostfix();
        }
        Expr parsePostfix() {
            Expr e = parsePrimary();
            while (true) {
                if (check(TT.LPAREN)) {
                    Token lp = advance(); List<Expr> args = new ArrayList<>();
                    if (!check(TT.RPAREN)) { args.add(parseExpr()); while (match(TT.COMMA)) args.add(parseExpr()); }
                    expect(TT.RPAREN);
                    CallExpr ce = new CallExpr(); ce.callee = e; ce.args = args; ce.line = lp.line; e = ce;
                } else if (check(TT.LBRACKET)) {
                    Token lb = advance(); Expr idx = parseExpr(); expect(TT.RBRACKET);
                    IndexExpr ie = new IndexExpr(); ie.obj = e; ie.index = idx; ie.line = lb.line; e = ie;
                } else break;
            }
            return e;
        }
        Expr parsePrimary() {
            Token t = peek();
            switch (t.type) {
                case INT: { advance(); IntLit e = new IntLit(); e.value = t.intVal; e.line = t.line; return e; }
                case STR: { advance(); StrLit e = new StrLit(); e.value = t.strVal; e.line = t.line; return e; }
                case TRUE: { advance(); BoolLit e = new BoolLit(); e.value = true; e.line = t.line; return e; }
                case FALSE: { advance(); BoolLit e = new BoolLit(); e.value = false; e.line = t.line; return e; }
                case NIL: { advance(); NilLit e = new NilLit(); e.line = t.line; return e; }
                case IDENT: { advance(); IdentExpr e = new IdentExpr(); e.name = t.text; e.line = t.line; return e; }
                case LPAREN: { advance(); Expr inner = parseExpr(); expect(TT.RPAREN); return inner; }
                case LBRACKET: {
                    advance(); List<Expr> elems = new ArrayList<>();
                    if (!check(TT.RBRACKET)) { elems.add(parseExpr()); while (match(TT.COMMA)) elems.add(parseExpr()); }
                    expect(TT.RBRACKET);
                    ListLit e = new ListLit(); e.elements = elems; e.line = t.line; return e;
                }
                case FN: {
                    advance(); expect(TT.LPAREN); List<String> params = parseParams(); expect(TT.RPAREN);
                    List<Stmt> body = parseBlock();
                    FnExpr e = new FnExpr(); e.params = params; e.body = body; e.line = t.line; return e;
                }
                default: throw new RuntimeException("Unexpected token " + t.type + " at line " + t.line);
            }
        }
    }

    // ==================== VALUES ====================
    abstract static class Value {
        abstract String typeName();
        abstract boolean truthy();
        abstract String display(boolean inList, Set<ListVal> anc);
    }
    static class IntVal extends Value {
        long v; IntVal(long v) { this.v = v; }
        String typeName() { return "int"; }
        boolean truthy() { return v != 0; }
        String display(boolean il, Set<ListVal> a) { return Long.toString(v); }
    }
    static class BoolVal extends Value {
        boolean v; BoolVal(boolean v) { this.v = v; }
        static final BoolVal TRUE = new BoolVal(true), FALSE = new BoolVal(false);
        String typeName() { return "bool"; }
        boolean truthy() { return v; }
        String display(boolean il, Set<ListVal> a) { return v ? "true" : "false"; }
    }
    static class StrVal extends Value {
        String v; StrVal(String v) { this.v = v; }
        String typeName() { return "string"; }
        boolean truthy() { return !v.isEmpty(); }
        String display(boolean il, Set<ListVal> a) {
            if (!il) return v;
            StringBuilder sb = new StringBuilder("\"");
            for (int i = 0; i < v.length(); i++) {
                char c = v.charAt(i);
                if (c == '\\') sb.append("\\\\");
                else if (c == '"') sb.append("\\\"");
                else if (c == '\n') sb.append("\\n");
                else if (c == '\t') sb.append("\\t");
                else sb.append(c);
            }
            sb.append('"'); return sb.toString();
        }
    }
    static class NilVal extends Value {
        static final NilVal INSTANCE = new NilVal();
        String typeName() { return "nil"; }
        boolean truthy() { return false; }
        String display(boolean il, Set<ListVal> a) { return "nil"; }
    }
    static class ListVal extends Value {
        List<Value> elements;
        ListVal(List<Value> e) { elements = e; }
        String typeName() { return "list"; }
        boolean truthy() { return !elements.isEmpty(); }
        String display(boolean il, Set<ListVal> anc) {
            if (anc.contains(this)) return "[...]";
            anc.add(this);
            StringBuilder sb = new StringBuilder("[");
            for (int i = 0; i < elements.size(); i++) {
                if (i > 0) sb.append(", ");
                sb.append(elements.get(i).display(true, anc));
            }
            sb.append(']'); anc.remove(this); return sb.toString();
        }
    }
    static class FnVal extends Value {
        List<String> params; List<Stmt> body; Scope captured; String name;
        FnVal(List<String> p, List<Stmt> b, Scope c, String n) { params = p; body = b; captured = c; name = n; }
        String typeName() { return "function"; }
        boolean truthy() { return true; }
        String display(boolean il, Set<ListVal> a) { return "<fn>"; }
    }
    static class BuiltinVal extends Value {
        String name; int arity; BuiltinFunc func;
        BuiltinVal(String n, int a, BuiltinFunc f) { name = n; arity = a; func = f; }
        String typeName() { return "function"; }
        boolean truthy() { return true; }
        String display(boolean il, Set<ListVal> a) { return "<fn>"; }
    }
    interface BuiltinFunc { Value call(List<Value> args, int line) throws TernError; }

    // ==================== SCOPE ====================
    static class Scope {
        Scope parent; HashMap<String, Value> vars;
        Scope(Scope p) { parent = p; vars = new HashMap<>(); }
        Value lookup(String name) {
            for (Scope s = this; s != null; s = s.parent)
                if (s.vars.containsKey(name)) return s.vars.get(name);
            return null;
        }
        void define(String name, Value v) { vars.put(name, v); }
        boolean assign(String name, Value v) {
            for (Scope s = this; s != null; s = s.parent)
                if (s.vars.containsKey(name)) { s.vars.put(name, v); return true; }
            return false;
        }
    }

    // ==================== EXCEPTIONS ====================
    static class TernError extends Exception {
        int line; String msg;
        TernError(int line, String msg) { this.line = line; this.msg = msg; }
    }
    static class BreakSignal extends RuntimeException {}
    static class ContinueSignal extends RuntimeException {}
    static class ReturnSignal extends RuntimeException {
        Value value; ReturnSignal(Value v) { value = v; }
    }

    // ==================== INTERPRETER ====================
    static class Interp {
        Scope global;

        Interp() {
            Scope bs = new Scope(null);
            global = new Scope(bs);
            setupBuiltins(bs);
        }

        void setupBuiltins(Scope sc) {
            sc.define("print", new BuiltinVal("print", -1, (args, line) -> {
                StringBuilder sb = new StringBuilder();
                for (int i = 0; i < args.size(); i++) {
                    if (i > 0) sb.append(' ');
                    sb.append(args.get(i).display(false, new HashSet<>()));
                }
                sb.append('\n');
                System.out.print(sb.toString());
                return NilVal.INSTANCE;
            }));
            sc.define("str", new BuiltinVal("str", 1, (args, line) ->
                new StrVal(args.get(0).display(false, new HashSet<>()))));
            sc.define("type", new BuiltinVal("type", 1, (args, line) ->
                new StrVal(args.get(0).typeName())));
            sc.define("len", new BuiltinVal("len", 1, (args, line) -> {
                Value v = args.get(0);
                if (v instanceof StrVal) return new IntVal(((StrVal) v).v.length());
                if (v instanceof ListVal) return new IntVal(((ListVal) v).elements.size());
                throw new TernError(line, "bad argument to len");
            }));
            sc.define("push", new BuiltinVal("push", 2, (args, line) -> {
                if (!(args.get(0) instanceof ListVal)) throw new TernError(line, "bad argument to push");
                ((ListVal) args.get(0)).elements.add(args.get(1));
                return NilVal.INSTANCE;
            }));
            sc.define("pop", new BuiltinVal("pop", 1, (args, line) -> {
                if (!(args.get(0) instanceof ListVal)) throw new TernError(line, "bad argument to pop");
                ListVal l = (ListVal) args.get(0);
                if (l.elements.isEmpty()) throw new TernError(line, "bad argument to pop");
                return l.elements.remove(l.elements.size() - 1);
            }));
            sc.define("range", new BuiltinVal("range", 2, (args, line) -> {
                if (!(args.get(0) instanceof IntVal) || !(args.get(1) instanceof IntVal))
                    throw new TernError(line, "bad argument to range");
                long a = ((IntVal) args.get(0)).v, b = ((IntVal) args.get(1)).v;
                List<Value> elems = new ArrayList<>();
                for (long i = a; i < b; i++) elems.add(new IntVal(i));
                return new ListVal(elems);
            }));
            sc.define("slice", new BuiltinVal("slice", 3, (args, line) -> {
                Value x = args.get(0);
                if (!(args.get(1) instanceof IntVal) || !(args.get(2) instanceof IntVal))
                    throw new TernError(line, "bad argument to slice");
                long a = ((IntVal) args.get(1)).v, b = ((IntVal) args.get(2)).v;
                if (x instanceof StrVal) {
                    String s = ((StrVal) x).v;
                    if (a < 0 || b > s.length() || a > b) throw new TernError(line, "bad argument to slice");
                    return new StrVal(s.substring((int) a, (int) b));
                } else if (x instanceof ListVal) {
                    List<Value> l = ((ListVal) x).elements;
                    if (a < 0 || b > l.size() || a > b) throw new TernError(line, "bad argument to slice");
                    return new ListVal(new ArrayList<>(l.subList((int) a, (int) b)));
                }
                throw new TernError(line, "bad argument to slice");
            }));
        }

        void run(List<Stmt> prog) {
            try { execList(prog, global); }
            catch (TernError e) { System.out.println("error at line " + e.line + ": " + e.msg); }
        }

        void execList(List<Stmt> stmts, Scope sc) throws TernError {
            for (int i = 0; i < stmts.size(); i++) exec(stmts.get(i), sc);
        }

        void exec(Stmt stmt, Scope sc) throws TernError {
            if (stmt instanceof LetStmt) {
                LetStmt s = (LetStmt) stmt;
                sc.define(s.name, eval(s.value, sc));
            } else if (stmt instanceof FnDeclStmt) {
                FnDeclStmt s = (FnDeclStmt) stmt;
                sc.define(s.name, new FnVal(s.params, s.body, sc, s.name));
            } else if (stmt instanceof IfStmt) {
                IfStmt s = (IfStmt) stmt;
                if (eval(s.cond, sc).truthy()) execList(s.thenBody, new Scope(sc));
                else if (s.elseBody != null) execList(s.elseBody, new Scope(sc));
            } else if (stmt instanceof WhileStmt) {
                WhileStmt s = (WhileStmt) stmt;
                while (eval(s.cond, sc).truthy()) {
                    try { execList(s.body, new Scope(sc)); }
                    catch (BreakSignal e) { break; }
                    catch (ContinueSignal e) { /* continue */ }
                }
            } else if (stmt instanceof ForStmt) {
                ForStmt s = (ForStmt) stmt;
                Value iter = eval(s.iterable, sc);
                if (!(iter instanceof ListVal)) throw new TernError(s.line, "cannot iterate " + iter.typeName());
                ListVal list = (ListVal) iter;
                int i = 0;
                while (i < list.elements.size()) {
                    Scope ls = new Scope(sc);
                    ls.define(s.varName, list.elements.get(i));
                    try { execList(s.body, ls); }
                    catch (BreakSignal e) { break; }
                    catch (ContinueSignal e) { /* fall through */ }
                    i++;
                }
            } else if (stmt instanceof ReturnStmt) {
                ReturnStmt s = (ReturnStmt) stmt;
