                Value obj = eval(s.obj, sc);
                Value idx = eval(s.index, sc);
                Value val = eval(s.value, sc);
                if (!(obj instanceof ListVal)) throw new TernError(s.line, "cannot assign into " + obj.typeName());
                if (!(idx instanceof IntVal)) throw new TernError(s.line, "cannot index list with " + idx.typeName());
