            if (expr instanceof NegExpr) {
                NegExpr e = (NegExpr) expr;
                Value v = eval(e.operand, sc);
                if (!(v instanceof IntVal)) throw new TernError(e.line, "cannot apply - to " + v.typeName());
                long val = ((IntVal) v).v;
                if (val == Long.MIN_VALUE) throw new TernError(e.line, "integer overflow");
                return new IntVal(-val);
            }
            if (expr instanceof CallExpr) {
                CallExpr e = (CallExpr) expr;
                Value callee = eval(e.callee, sc);
