                for (Expr a : e.args) args.add(eval(a, sc));
                return doCall(callee, args, e.line);
            }
            if (expr instanceof IndexExpr) {
                IndexExpr e = (IndexExpr) expr;
                Value obj = eval(e.obj, sc);
                Value idx = eval(e.index, sc);
                if (!(obj instanceof ListVal) && !(obj instanceof StrVal))
                    throw new TernError(e.line, "cannot index " + obj.typeName() + " with " + idx.typeName());
                if (!(idx instanceof IntVal))
                    throw new TernError(e.line, "cannot index " + obj.typeName() + " with " + idx.typeName());
                long i = ((IntVal) idx).v;
                if (obj instanceof ListVal) {
                    ListVal l = (ListVal) obj;
                    if (i < 0 || i >= l.elements.size())
                        throw new TernError(e.line, "index " + i + " out of range for length " + l.elements.size());
                    return l.elements.get((int) i);
                } else {
                    String s = ((StrVal) obj).v;
                    if (i < 0 || i >= s.length())
                        throw new TernError(e.line, "index " + i + " out of range for length " + s.length());
