            if (callee instanceof FnVal) {
                FnVal f = (FnVal) callee;
                if (args.size() != f.params.size())
                    throw new TernError(line, "expected " + f.params.size() + " arguments, got " + args.size());
                Scope cs = new Scope(f.captured);
                for (int i = 0; i < f.params.size(); i++) cs.define(f.params.get(i), args.get(i));
                try { execList(f.body, cs); }
                catch (ReturnSignal r) { return r.value; }
                return NilVal.INSTANCE;
            }
            throw new TernError(line, "cannot call " + callee.typeName());
        }

        Value evalBin(String op, Value l, Value r, int line) throws TernError {
