                    if (l instanceof ListVal && r instanceof ListVal) {
                        List<Value> ne = new ArrayList<>(((ListVal) l).elements);
                        ne.addAll(((ListVal) r).elements);
                        return new ListVal(ne);
                    }
                    throw new TernError(line, "cannot apply + to " + l.typeName() + " and " + r.typeName());
                case "-":
                    if (l instanceof IntVal && r instanceof IntVal) {
                        try { return new IntVal(Math.subtractExact(((IntVal) l).v, ((IntVal) r).v)); }
                        catch (ArithmeticException e) { throw new TernError(line, "integer overflow"); }
                    }
                    throw new TernError(line, "cannot apply - to " + l.typeName() + " and " + r.typeName());
                case "*":
                    if (l instanceof IntVal && r instanceof IntVal) {
                        try { return new IntVal(Math.multiplyExact(((IntVal) l).v, ((IntVal) r).v)); }
                        catch (ArithmeticException e) { throw new TernError(line, "integer overflow"); }
                    }
                    throw new TernError(line, "cannot apply * to " + l.typeName() + " and " + r.typeName());
                case "/":
                    if (l instanceof IntVal && r instanceof IntVal) {
                        long a = ((IntVal) l).v, b = ((IntVal) r).v;
                        if (b == 0) throw new TernError(line, "division by zero");
                        if (a == Long.MIN_VALUE && b == -1) throw new TernError(line, "integer overflow");
                        return new IntVal(a / b);
                    }
                    throw new TernError(line, "cannot apply / to " + l.typeName() + " and " + r.typeName());
                case "%":
                    if (l instanceof IntVal && r instanceof IntVal) {
                        long a = ((IntVal) l).v, b = ((IntVal) r).v;
                        if (b == 0) throw new TernError(line, "division by zero");
                        return new IntVal(a % b);
                    }
                    throw new TernError(line, "cannot apply % to " + l.typeName() + " and " + r.typeName());
                case "==": return valEq(l, r) ? BoolVal.TRUE : BoolVal.FALSE;
                case "!=": return valEq(l, r) ? BoolVal.FALSE : BoolVal.TRUE;
                case "<": case "<=": case ">": case ">=":
                    if (l instanceof IntVal && r instanceof IntVal) {
                        long a = ((IntVal) l).v, b = ((IntVal) r).v;
                        boolean res = op.equals("<") ? a < b : op.equals("<=") ? a <= b : op.equals(">") ? a > b : a >= b;
                        return res ? BoolVal.TRUE : BoolVal.FALSE;
                    }
                    if (l instanceof StrVal && r instanceof StrVal) {
                        int c = ((StrVal) l).v.compareTo(((StrVal) r).v);
                        boolean res = op.equals("<") ? c < 0 : op.equals("<=") ? c <= 0 : op.equals(">") ? c > 0 : c >= 0;
                        return res ? BoolVal.TRUE : BoolVal.FALSE;
                    }
                    throw new TernError(line, "cannot apply " + op + " to " + l.typeName() + " and " + r.typeName());
            }
            throw new RuntimeException("Unknown op " + op);
        }

        boolean valEq(Value a, Value b) {
            String ta = a.typeName(), tb = b.typeName();
            if (!ta.equals(tb)) return false;
            if (a instanceof IntVal) return ((IntVal) a).v == ((IntVal) b).v;
            if (a instanceof BoolVal) return ((BoolVal) a).v == ((BoolVal) b).v;
