enum TK {
    case intLit, strLit, ident, keyword
    case plus, minus, star, slash, percent
    case eq, neq, lt, lte, gt, gte, assign
    case lparen, rparen, lbracket, rbracket, lbrace, rbrace
    case comma, semicolon, eof
}
struct Token { let kind: TK; let text: String; let intVal: Int64; let line: Int }
let kws: Set<String> = ["let","fn","if","else","while","for","in","return","break","continue","and","or","not","true","false","nil"]

func tokenize(_ src: String) -> [Token] {
    var toks: [Token] = []
    let c = Array(src); var p = 0, ln = 1
    while p < c.count {
        let ch = c[p]
        if ch == " " || ch == "\t" || ch == "\r" { p += 1; continue }
        if ch == "\n" { ln += 1; p += 1; continue }
        if ch == "#" { while p < c.count && c[p] != "\n" { p += 1 }; continue }
        if ch.isNumber {
            var s = ""; while p < c.count && c[p].isNumber { s.append(c[p]); p += 1 }
            toks.append(Token(kind: .intLit, text: s, intVal: Int64(s)!, line: ln)); continue
        }
        if ch == "\"" {
            p += 1; var s = ""
            while p < c.count && c[p] != "\"" {
