                    case "\"": s.append("\""); case "\\": s.append("\\"); default: s.append(c[p]) }; }}
                else { s.append(c[p]) }; p += 1 }
            p += 1; toks.append(Token(kind: .strLit, text: s, intVal: 0, line: ln)); continue
        }
        if ch.isLetter || ch == "_" {
            var s = ""; while p < c.count && (c[p].isLetter || c[p].isNumber || c[p] == "_") { s.append(c[p]); p += 1 }
            toks.append(Token(kind: kws.contains(s) ? .keyword : .ident, text: s, intVal: 0, line: ln)); continue
