            let two = String(c[p...p+1])
            if two == "==" { toks.append(Token(kind: .eq, text: "==", intVal: 0, line: ln)); p += 2; continue }
            if two == "!=" { toks.append(Token(kind: .neq, text: "!=", intVal: 0, line: ln)); p += 2; continue }
            if two == "<=" { toks.append(Token(kind: .lte, text: "<=", intVal: 0, line: ln)); p += 2; continue }
            if two == ">=" { toks.append(Token(kind: .gte, text: ">=", intVal: 0, line: ln)); p += 2; continue }
        }
        switch ch {
        case "+": toks.append(Token(kind: .plus, text: "+", intVal: 0, line: ln))
        case "-": toks.append(Token(kind: .minus, text: "-", intVal: 0, line: ln))
        case "*": toks.append(Token(kind: .star, text: "*", intVal: 0, line: ln))
        case "/": toks.append(Token(kind: .slash, text: "/", intVal: 0, line: ln))
        case "%": toks.append(Token(kind: .percent, text: "%", intVal: 0, line: ln))
        case "<": toks.append(Token(kind: .lt, text: "<", intVal: 0, line: ln))
        case ">": toks.append(Token(kind: .gt, text: ">", intVal: 0, line: ln))
        case "=": toks.append(Token(kind: .assign, text: "=", intVal: 0, line: ln))
        case "(": toks.append(Token(kind: .lparen, text: "(", intVal: 0, line: ln))
        case ")": toks.append(Token(kind: .rparen, text: ")", intVal: 0, line: ln))
        case "[": toks.append(Token(kind: .lbracket, text: "[", intVal: 0, line: ln))
        case "]": toks.append(Token(kind: .rbracket, text: "]", intVal: 0, line: ln))
        case "{": toks.append(Token(kind: .lbrace, text: "{", intVal: 0, line: ln))
        case "}": toks.append(Token(kind: .rbrace, text: "}", intVal: 0, line: ln))
        case ",": toks.append(Token(kind: .comma, text: ",", intVal: 0, line: ln))
        case ";": toks.append(Token(kind: .semicolon, text: ";", intVal: 0, line: ln))
        default: break }
        p += 1 }
    toks.append(Token(kind: .eof, text: "", intVal: 0, line: ln))
    return toks
}

// ============ AST ============
indirect enum Expr {
    case intLit(Int64, Int), strLit(String, Int), boolLit(Bool, Int), nilLit(Int)
    case ident(String, Int), listLit([Expr], Int), fnLit([String], [Stmt], Int)
    case notE(Expr, Int), negE(Expr, Int), bin(String, Expr, Expr, Int)
    case andE(Expr, Expr, Int), orE(Expr, Expr, Int)
    case call(Expr, [Expr], Int), index(Expr, Expr, Int)
}
indirect enum Stmt {
    case letS(String, Expr, Int), fnD(String, [String], [Stmt], Int)
    case ifS(Expr, [Stmt], [Stmt]?, Int)
    case whileS(Expr, [Stmt], Int), forS(String, Expr, [Stmt], Int)
    case retS(Expr?, Int), breakS(Int), contS(Int)
    case assignS(String, Expr, Int), idxAssign(Expr, Expr, Expr, Int), exprS(Expr, Int)
}

// ============ Values ============
final class ListVal { var elems: [Val]; init(_ e: [Val] = []) { elems = e } }
final class FuncVal {
    let params: [String]; let body: [Stmt]; let captured: Scope; let name: String?
    let builtin: (([Val], Int) throws -> Val)?; let bcount: Int?
    init(_ p: [String], _ b: [Stmt], _ c: Scope, name: String? = nil) {
        params = p; body = b; captured = c; self.name = name; builtin = nil; bcount = nil }
    init(name: String, count: Int?, _ f: @escaping ([Val], Int) throws -> Val) {
        params = []; body = []; captured = Scope(); self.name = name; builtin = f; bcount = count }
}
enum Val { case int(Int64), bool(Bool), str(String), list(ListVal), funcVal(FuncVal), nilV }
final class Scope {
    var vars: [String: Val]; var parent: Scope?
    init(_ p: Scope? = nil) { vars = [:]; parent = p }
    func get(_ n: String) -> Val? {
        var s: Scope? = self; while let c = s { if let v = c.vars[n] { return v }; s = c.parent }; return nil }
    func set(_ n: String, _ v: Val) -> Bool {
        var s: Scope? = self; while let c = s { if c.vars[n] != nil { c.vars[n] = v; return true }; s = c.parent }; return false }
    func declare(_ n: String, _ v: Val) { vars[n] = v }
}
enum CF { case normal, breakLoop, contLoop, retVal(Val) }
struct TernError: Error { let line: Int; let msg: String }

// ============ Parser ============
final class Parser {
    let toks: [Token]; var p = 0
    init(_ t: [Token]) { toks = t }
    func pk() -> Token { toks[p] }
    func adv() -> Token { let t = toks[p]; p += 1; return t }
    func expect(_ k: TK) { p += 1 }
    func parseProgram() -> [Stmt] { var s: [Stmt] = []; while pk().kind != .eof { s.append(parseStmt()) }; return s }
    func parseBlock() -> [Stmt] { expect(.lbrace); var s: [Stmt] = []; while pk().kind != .rbrace { s.append(parseStmt()) }; expect(.rbrace); return s }
    func parseParams() -> [String] {
        var ps: [String] = []; if pk().kind == .ident { ps.append(adv().text); while pk().kind == .comma { adv(); ps.append(adv().text) } }; return ps }
    func parseStmt() -> Stmt {
        let t = pk()
        if t.kind == .keyword {
            switch t.text {
            case "let": adv(); let nm = adv().text; expect(.assign); let v = parseExpr(); expect(.semicolon); return .letS(nm, v, t.line)
            case "fn":
                if p + 1 < toks.count && toks[p + 1].kind == .ident {
                    adv(); let nm = adv().text; expect(.lparen); let ps = parseParams(); expect(.rparen)
                    let body = parseBlock(); return .fnD(nm, ps, body, t.line) }
                break
            case "if": return parseIf()
            case "while": adv(); let c = parseExpr(); let b = parseBlock(); return .whileS(c, b, t.line)
            case "for": adv(); let vn = adv().text; adv(); let it = parseExpr(); let b = parseBlock(); return .forS(vn, it, b, t.line)
            case "return": adv(); if pk().kind == .semicolon { adv(); return .retS(nil, t.line) }; let v = parseExpr(); expect(.semicolon); return .retS(v, t.line)
            case "break": adv(); expect(.semicolon); return .breakS(t.line)
            case "continue": adv(); expect(.semicolon); return .contS(t.line)
            default: break } }
        let expr = parsePostfix()
        if pk().kind == .assign {
            adv(); let v = parseExpr(); expect(.semicolon)
            if case .ident(let nm, let ln) = expr { return .assignS(nm, v, ln) }
            if case .index(let o, let i, let ln) = expr { return .idxAssign(o, i, v, ln) }
        }
        expect(.semicolon); return .exprS(expr, t.line) }
    func parseIf() -> Stmt {
        let t = adv(); let c = parseExpr(); let tb = parseBlock(); var eb: [Stmt]? = nil
        if pk().kind == .keyword && pk().text == "else" { adv(); if pk().kind == .keyword && pk().text == "if" { eb = [parseIf()] } else { eb = parseBlock() } }
        return .ifS(c, tb, eb, t.line) }
    func parseExpr() -> Expr { parseOr() }
    func parseOr() -> Expr { var l = parseAnd(); while pk().kind == .keyword && pk().text == "or" { let t = adv(); l = .orE(l, parseAnd(), t.line) }; return l }
    func parseAnd() -> Expr { var l = parseNot(); while pk().kind == .keyword && pk().text == "and" { let t = adv(); l = .andE(l, parseNot(), t.line) }; return l }
    func parseNot() -> Expr { if pk().kind == .keyword && pk().text == "not" { let t = adv(); return .notE(parseNot(), t.line) }; return parseComp() }
    func parseComp() -> Expr {
        var l = parseAdd()
        while true { let t = pk(); let op: String; switch t.kind {
            case .eq: op = "=="; case .neq: op = "!="; case .lt: op = "<"; case .lte: op = "<="; case .gt: op = ">"; case .gte: op = ">="; default: return l }
            adv(); l = .bin(op, l, parseAdd(), t.line) } }
    func parseAdd() -> Expr {
        var l = parseMul()
        while true { let t = pk(); let op: String; switch t.kind { case .plus: op = "+"; case .minus: op = "-"; default: return l }
            adv(); l = .bin(op, l, parseMul(), t.line) } }
    func parseMul() -> Expr {
        var l = parseUnary()
        while true { let t = pk(); let op: String; switch t.kind { case .star: op = "*"; case .slash: op = "/"; case .percent: op = "%"; default: return l }
            adv(); l = .bin(op, l, parseUnary(), t.line) } }
    func parseUnary() -> Expr { if pk().kind == .minus { let t = adv(); return .negE(parseUnary(), t.line) }; return parsePostfix() }
    func parsePostfix() -> Expr {
        var e = parsePrimary()
        while true {
            if pk().kind == .lparen { let t = adv(); var args: [Expr] = []; if pk().kind != .rparen { args.append(parseExpr()); while pk().kind == .comma { adv(); args.append(parseExpr()) } }; expect(.rparen); e = .call(e, args, t.line) }
            else if pk().kind == .lbracket { let t = adv(); let idx = parseExpr(); expect(.rbracket); e = .index(e, idx, t.line) }
            else { break } }
        return e }
    func parsePrimary() -> Expr {
        let t = pk()
        switch t.kind {
        case .intLit: adv(); return .intLit(t.intVal, t.line)
        case .strLit: adv(); return .strLit(t.text, t.line)
        case .keyword:
            switch t.text {
            case "true": adv(); return .boolLit(true, t.line)
            case "false": adv(); return .boolLit(false, t.line)
            case "nil": adv(); return .nilLit(t.line)
            case "fn": adv(); expect(.lparen); let ps = parseParams(); expect(.rparen); let b = parseBlock(); return .fnLit(ps, b, t.line)
            default: fatalError("unexpected keyword \(t.text)") }
        case .ident: adv(); return .ident(t.text, t.line)
        case .lparen: adv(); let e = parseExpr(); expect(.rparen); return e
        case .lbracket: adv(); var es: [Expr] = []; if pk().kind != .rbracket { es.append(parseExpr()); while pk().kind == .comma { adv(); es.append(parseExpr()) } }; expect(.rbracket); return .listLit(es, t.line)
        default: fatalError("unexpected token \(t.text)") } } }

// ============ Interpreter ============
func typeName(_ v: Val) -> String {
    switch v { case .int: return "int"; case .bool: return "bool"; case .str: return "string"
    case .list: return "list"; case .funcVal: return "function"; case .nilV: return "nil" } }
func isTruthy(_ v: Val) -> Bool {
    switch v { case .int(let n): return n != 0; case .bool(let b): return b; case .str(let s): return !s.isEmpty
    case .list(let lv): return !lv.elems.isEmpty; case .funcVal: return true; case .nilV: return false } }
func ternEq(_ a: Val, _ b: Val) -> Bool {
    switch (a, b) {
    case (.int(let x), .int(let y)): return x == y
    case (.bool(let x), .bool(let y)): return x == y
    case (.str(let x), .str(let y)): return x == y
    case (.nilV, .nilV): return true
    case (.list(let x), .list(let y)):
        if x.elems.count != y.elems.count { return false }
        for i in 0..<x.elems.count { if !ternEq(x.elems[i], y.elems[i]) { return false } }; return true
    case (.funcVal(let x), .funcVal(let y)): return x === y
    default: return false } }

final class Interp {
    var out = ""
    func run(_ prog: [Stmt]) {
        let bs = Scope(); setupBuiltins(bs); let gs = Scope(bs)
        do { _ = try execBlock(prog, gs) }
        catch let e as TernError { out += "error at line \(e.line): \(e.msg)\n" }
        print(out, terminator: "") }

    func setupBuiltins(_ sc: Scope) {
        sc.declare("print", .funcVal(FuncVal(name: "print", count: nil) { [unowned self] args, _ in
            var ps: [String] = []; for a in args { ps.append(self.displayTop(a)) }
            self.out += ps.joined(separator: " ") + "\n"; return .nilV }))
        sc.declare("str", .funcVal(FuncVal(name: "str", count: 1) { [unowned self] args, _ in .str(self.displayTop(args[0])) }))
        sc.declare("type", .funcVal(FuncVal(name: "type", count: 1) { args, _ in .str(typeName(args[0])) }))
        sc.declare("len", .funcVal(FuncVal(name: "len", count: 1) { args, line in
            switch args[0] { case .str(let s): return .int(Int64(s.count)); case .list(let lv): return .int(Int64(lv.elems.count))
            default: throw TernError(line: line, msg: "bad argument to len") } }))
        sc.declare("push", .funcVal(FuncVal(name: "push", count: 2) { args, line in
            guard case .list(let lv) = args[0] else { throw TernError(line: line, msg: "bad argument to push") }
            lv.elems.append(args[1]); return .nilV }))
        sc.declare("pop", .funcVal(FuncVal(name: "pop", count: 1) { args, line in
            guard case .list(let lv) = args[0] else { throw TernError(line: line, msg: "bad argument to pop") }
            if lv.elems.isEmpty { throw TernError(line: line, msg: "bad argument to pop") }
            return lv.elems.removeLast() }))
        sc.declare("range", .funcVal(FuncVal(name: "range", count: 2) { args, line in
            guard case .int(let a) = args[0], case .int(let b) = args[1] else { throw TernError(line: line, msg: "bad argument to range") }
            if b <= a { return .list(ListVal()) }
            var es: [Val] = []; for i in a..<b { es.append(.int(i)) }; return .list(ListVal(es)) }))
        sc.declare("slice", .funcVal(FuncVal(name: "slice", count: 3) { args, line in
            guard case .int(let a) = args[1], case .int(let b) = args[2] else { throw TernError(line: line, msg: "bad argument to slice") }
            switch args[0] {
            case .str(let s): let ch = Array(s); guard a >= 0, b <= Int64(ch.count), a <= b else { throw TernError(line: line, msg: "bad argument to slice") }; return .str(String(ch[Int(a)..<Int(b)]))
            case .list(let lv): guard a >= 0, b <= Int64(lv.elems.count), a <= b else { throw TernError(line: line, msg: "bad argument to slice") }; return .list(ListVal(Array(lv.elems[Int(a)..<Int(b)])))
            default: throw TernError(line: line, msg: "bad argument to slice") } })) }

    func displayTop(_ v: Val) -> String { var seen = Set<ObjectIdentifier>(); return disp(v, true, &seen) }
    func disp(_ v: Val, _ top: Bool, _ seen: inout Set<ObjectIdentifier>) -> String {
        switch v {
        case .int(let n): return String(n)
        case .bool(let b): return b ? "true" : "false"
        case .str(let s): if top { return s }; var r = "\""; for c in s { switch c { case "\\": r += "\\\\"; case "\"": r += "\\\""; case "\n": r += "\\n"; case "\t": r += "\\t"; default: r.append(c) } }; r += "\""; return r
        case .nilV: return "nil"
        case .funcVal: return "<fn>"
        case .list(let lv): let id = ObjectIdentifier(lv); if seen.contains(id) { return "[...]" }; seen.insert(id); var r = "["; for (i, e) in lv.elems.enumerated() { if i > 0 { r += ", " }; r += disp(e, false, &seen) }; r += "]"; seen.remove(id); return r } }

    func execBlock(_ stmts: [Stmt], _ sc: Scope) throws -> CF {
        for s in stmts { let cf = try execStmt(s, sc); switch cf { case .normal: continue; default: return cf } }; return .normal }

    func execStmt(_ s: Stmt, _ sc: Scope) throws -> CF {
        switch s {
        case .letS(let nm, let v, _): let val = try evalExpr(v, sc); sc.declare(nm, val); return .normal
        case .fnD(let nm, let ps, let body, _): sc.declare(nm, .funcVal(FuncVal(ps, body, sc, name: nm))); return .normal
        case .ifS(let c, let tb, let eb, _):
            let cv = try evalExpr(c, sc)
            if isTruthy(cv) { return try execBlock(tb, Scope(sc)) }
            else if let eb = eb { return try execBlock(eb, Scope(sc)) }
            return .normal
        case .whileS(let c, let body, _):
            while true { let cv = try evalExpr(c, sc); if !isTruthy(cv) { break }; let cf = try execBlock(body, Scope(sc))
                switch cf { case .breakLoop: return .normal; case .retVal(let v): return .retVal(v); default: continue } }; return .normal
        case .forS(let vn, let it, let body, let line):
            let iv = try evalExpr(it, sc)
            guard case .list(let lv) = iv else { throw TernError(line: line, msg: "cannot iterate \(typeName(iv))") }
            var i = 0
            while i < lv.elems.count {
                let is = Scope(sc); is.declare(vn, lv.elems[i])
                let cf = try execBlock(body, is)
                switch cf { case .breakLoop: return .normal; case .retVal(let v): return .retVal(v); default: break }
                i += 1 }
            return .normal
        case .retS(let v, _): if let v = v { return .retVal(try evalExpr(v, sc)) }; return .retVal(.nilV)
        case .breakS: return .breakLoop
        case .contS: return .contLoop
        case .assignS(let nm, let v, let line):
            let val = try evalExpr(v, sc)
            if !sc.set(nm, val) { throw TernError(line: line, msg: "undefined variable \(nm)") }
            return .normal
        case .idxAssign(let obj, let idx, let val, let line):
            let ov = try evalExpr(obj, sc); let iv = try evalExpr(idx, sc); let vv = try evalExpr(val, sc)
            guard case .list(let lv) = ov else { throw TernError(line: line, msg: "cannot assign into \(typeName(ov))") }
            guard case .int(let i) = iv else { throw TernError(line: line, msg: "cannot index list with \(typeName(iv))") }
            if i < 0 || i >= lv.elems.count { throw TernError(line: line, msg: "index \(i) out of range for length \(lv.elems.count)") }
            lv.elems[Int(i)] = vv; return .normal
        case .exprS(let e, _): _ = try evalExpr(e, sc); return .normal } }

    func evalExpr(_ e: Expr, _ sc: Scope) throws -> Val {
        switch e {
        case .intLit(let n, _): return .int(n)
        case .strLit(let s, _): return .str(s)
        case .boolLit(let b, _): return .bool(b)
        case .nilLit: return .nilV
        case .ident(let nm, let line): guard let v = sc.get(nm) else { throw TernError(line: line, msg: "undefined variable \(nm)") }; return v
        case .listLit(let es, _): var vs: [Val] = []; for e in es { vs.append(try evalExpr(e, sc)) }; return .list(ListVal(vs))
        case .fnLit(let ps, let body, _): return .funcVal(FuncVal(ps, body, sc))
        case .notE(let op, _): return .bool(!isTruthy(try evalExpr(op, sc)))
        case .negE(let op, let line):
            let v = try evalExpr(op, sc)
            guard case .int(let x) = v else { throw TernError(line: line, msg: "cannot apply - to \(typeName(v))") }
            if x == Int64.min { throw TernError(line: line, msg: "integer overflow") }
            return .int(-x)
        case .bin(let op, let l, let r, let line):
            let lv = try evalExpr(l, sc); let rv = try evalExpr(r, sc); return try applyBin(op, lv, rv, line)
        case .andE(let l, let r, _): let lv = try evalExpr(l, sc); if !isTruthy(lv) { return lv }; return try evalExpr(r, sc)
        case .orE(let l, let r, _): let lv = try evalExpr(l, sc); if isTruthy(lv) { return lv }; return try evalExpr(r, sc)
        case .call(let callee, let argEs, let line):
            let cv = try evalExpr(callee, sc); var args: [Val] = []; for ae in argEs { args.append(try evalExpr(ae, sc)) }
            guard case .funcVal(let fv) = cv else { throw TernError(line: line, msg: "cannot call \(typeName(cv))") }
            return try callFunc(fv, args, line)
        case .index(let obj, let idx, let line):
            let ov = try evalExpr(obj, sc); let iv = try evalExpr(idx, sc)
            let isList = ov is ListVal; let isStr: Bool; if case .str = ov { isStr = true } else { isStr = false }
            let isInt: Bool; if case .int = iv { isInt = true } else { isInt = false }
            if (!isList && !isStr) || !isInt { throw TernError(line: line, msg: "cannot index \(typeName(ov)) with \(typeName(iv))") }
            if case .list(let lv) = ov, case .int(let i) = iv {
                if i < 0 || i >= lv.elems.count { throw TernError(line: line, msg: "index \(i) out of range for length \(lv.elems.count)") }
                return lv.elems[Int(i)] }
            if case .str(let s) = ov, case .int(let i) = iv {
                let ch = Array(s)
                if i < 0 || i >= ch.count { throw TernError(line: line, msg: "index \(i) out of range for length \(ch.count)") }
                return .str(String(ch[Int(i)])) }
            throw TernError(line: line, msg: "cannot index \(typeName(ov)) with \(typeName(iv))")
        } }

    func applyBin(_ op: String, _ a: Val, _ b: Val, _ line: Int) throws -> Val {
        switch op {
        case "+":
            switch (a, b) {
            case (.int(let x), .int(let y)): let (r, ov) = x.addingReportingOverflow(y); if ov { throw TernError(line: line, msg: "integer overflow") }; return .int(r)
            case (.str(let x), .str(let y)): return .str(x + y)
            case (.list(let x), .list(let y)): return .list(ListVal(x.elems + y.elems))
            default: throw TernError(line: line, msg: "cannot apply + to \(typeName(a)) and \(typeName(b))") }
        case "-":
            guard case .int(let x) = a, case .int(let y) = b else { throw TernError(line: line, msg: "cannot apply - to \(typeName(a)) and \(typeName(b))") }
            let (r, ov) = x.subtractingReportingOverflow(y); if ov { throw TernError(line: line, msg: "integer overflow") }; return .int(r)
        case "*":
            guard case .int(let x) = a, case .int(let y) = b else { throw TernError(line: line, msg: "cannot apply * to \(typeName(a)) and \(typeName(b))") }
            let (r, ov) = x.multipliedReportingOverflow(by: y); if ov { throw TernError(line: line, msg: "integer overflow") }; return .int(r)
        case "/":
            guard case .int(let x) = a, case .int(let y) = b else { throw TernError(line: line, msg: "cannot apply / to \(typeName(a)) and \(typeName(b))") }
            if y == 0 { throw TernError(line: line, msg: "division by zero") }
            if y == -1 { if x == Int64.min { throw TernError(line: line, msg: "integer overflow") }; return .int(-x) }
            return .int(x / y)
        case "%":
            guard case .int(let x) = a, case .int(let y) = b else { throw TernError(line: line, msg: "cannot apply % to \(typeName(a)) and \(typeName(b))") }
            if y == 0 { throw TernError(line: line, msg: "division by zero") }
            if y == -1 { return .int(0) }
            return .int(x % y)
        case "==": return .bool(ternEq(a, b))
        case "!=": return .bool(!ternEq(a, b))
        case "<", "<=", ">", ">=":
            switch (a, b) {
            case (.int(let x), .int(let y)):
                switch op { case "<": return .bool(x < y); case "<=": return .bool(x <= y); case ">": return .bool(x > y); default: return .bool(x >= y) }
            case (.str(let x), .str(let y)):
                switch op { case "<": return .bool(x < y); case "<=": return .bool(x <= y); case ">": return .bool(x > y); default: return .bool(x >= y) }
            default: throw TernError(line: line, msg: "cannot apply \(op) to \(typeName(a)) and \(typeName(b))") }
        default: fatalError("unknown op \(op)") } }

    func callFunc(_ fv: FuncVal, _ args: [Val], _ line: Int) throws -> Val {
        if let bi = fv.builtin {
            if let ec = fv.bcount, args.count != ec { throw TernError(line: line, msg: "expected \(ec) arguments, got \(args.count)") }
            return try bi(args, line) }
        if args.count != fv.params.count { throw TernError(line: line, msg: "expected \(fv.params.count) arguments, got \(args.count)") }
        let cs = Scope(fv.captured)
