            if x == Int64.min { throw TernError(line: line, msg: "integer overflow") }
            return .int(-x)
        case .bin(let op, let l, let r, let line):
            let lv = try evalExpr(l, sc); let rv = try evalExpr(r, sc); return try applyBin(op, lv, rv, line)
        case .andE(let l, let r, _): let lv = try evalExpr(l, sc); if !isTruthy(lv) { return lv }; return try evalExpr(r, sc)
        case .orE(let l, let r, _): let lv = try evalExpr(l, sc); if isTruthy(lv) { return lv }; return try evalExpr(r, sc)
        case .call(let callee, let argEs, let line):
            let cv = try evalExpr(callee, sc); var args: [Val] = []; for ae in argEs { args.append(try evalExpr(ae, sc)) }
            guard case .funcVal(let fv) = cv else { throw TernError(line: line, msg: "cannot call \(typeName(cv))") }
            return try callFunc(fv, args, line)
        case .index(let obj, let idx, let line):
            let ov = try evalExpr(obj, sc); let iv = try evalExpr(idx, sc)
            let isList: Bool; if case .list = ov { isList = true } else { isList = false }
            let isStr: Bool; if case .str = ov { isStr = true } else { isStr = false }
            let isInt: Bool; if case .int = iv { isInt = true } else { isInt = false }
            if (!isList && !isStr) || !isInt { throw TernError(line: line, msg: "cannot index \(typeName(ov)) with \(typeName(iv))") }
            if case .list(let lv) = ov, case .int(let i) = iv {
                if i < 0 || i >= lv.elems.count { throw TernError(line: line, msg: "index \(i) out of range for length \(lv.elems.count)") }
                return lv.elems[Int(i)] }
            if case .str(let s) = ov, case .int(let i) = iv {
                let ch = Array(s)
                if i < 0 || i >= ch.count { throw TernError(line: line, msg: "index \(i) out of range for length \(ch.count)") }
                return .str(String(ch[Int(i)])) }
            throw TernError(line: line, msg: "cannot index \(typeName(ov)) with \(typeName(iv))")
        } }

    func applyBin(_ op: String, _ a: Val, _ b: Val, _ line: Int) throws -> Val {
        switch op {
        case "+":
            switch (a, b) {
            case (.int(let x), .int(let y)): let (r, ov) = x.addingReportingOverflow(y); if ov { throw TernError(line: line, msg: "integer overflow") }; return .int(r)
            case (.str(let x), .str(let y)): return .str(x + y)
            case (.list(let x), .list(let y)): return .list(ListVal(x.elems + y.elems))
            default: throw TernError(line: line, msg: "cannot apply + to \(typeName(a)) and \(typeName(b))") }
        case "-":
            guard case .int(let x) = a, case .int(let y) = b else { throw TernError(line: line, msg: "cannot apply - to \(typeName(a)) and \(typeName(b))") }
            let (r, ov) = x.subtractingReportingOverflow(y); if ov { throw TernError(line: line, msg: "integer overflow") }; return .int(r)
        case "*":
            guard case .int(let x) = a, case .int(let y) = b else { throw TernError(line: line, msg: "cannot apply * to \(typeName(a)) and \(typeName(b))") }
            let (r, ov) = x.multipliedReportingOverflow(by: y); if ov { throw TernError(line: line, msg: "integer overflow") }; return .int(r)
        case "/":
            guard case .int(let x) = a, case .int(let y) = b else { throw TernError(line: line, msg: "cannot apply / to \(typeName(a)) and \(typeName(b))") }
            if y == 0 { throw TernError(line: line, msg: "division by zero") }
            if y == -1 { if x == Int64.min { throw TernError(line: line, msg: "integer overflow") }; return .int(-x) }
            return .int(x / y)
        case "%":
            guard case .int(let x) = a, case .int(let y) = b else { throw TernError(line: line, msg: "cannot apply % to \(typeName(a)) and \(typeName(b))") }
            if y == 0 { throw TernError(line: line, msg: "division by zero") }
            if y == -1 { return .int(0) }
            return .int(x % y)
        case "==": return .bool(ternEq(a, b))
        case "!=": return .bool(!ternEq(a, b))
        case "<", "<=", ">", ">=":
            switch (a, b) {
            case (.int(let x), .int(let y)):
                switch op { case "<": return .bool(x < y); case "<=": return .bool(x <= y); case ">": return .bool(x > y); default: return .bool(x >= y) }
            case (.str(let x), .str(let y)):
                switch op { case "<": return .bool(x < y); case "<=": return .bool(x <= y); case ">": return .bool(x > y); default: return .bool(x >= y) }
            default: throw TernError(line: line, msg: "cannot apply \(op) to \(typeName(a)) and \(typeName(b))") }
        default: fatalError("unknown op \(op)") } }

    func callFunc(_ fv: FuncVal, _ args: [Val], _ line: Int) throws -> Val {
        if let bi = fv.builtin {
            if let ec = fv.bcount, args.count != ec { throw TernError(line: line, msg: "expected \(ec) arguments, got \(args.count)") }
            return try bi(args, line) }
        if args.count != fv.params.count { throw TernError(line: line, msg: "expected \(fv.params.count) arguments, got \(args.count)") }
        let cs = Scope(fv.captured)
        for (i, p) in fv.params.enumerated() { cs.declare(p, args[i]) }
        let cf = try execBlock(fv.body, cs)
        if case .retVal(let v) = cf { return v }
        return .nilV } }

// ============ Main ============
let args = CommandLine.arguments
guard args.count >= 2 else { exit(1) }
let path = args[1] + "/program.tern"
guard let content = try? String(contentsOfFile: path, encoding: .utf8) else { exit(1) }
let toks = tokenize(content)
let parser = Parser(toks)
let prog = parser.parseProgram()
let interp = Interp()
interp.run(prog)

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <ctype.h>
#include <stdarg.h>
#include <setjmp.h>
#include <limits.h>

/* ============ UTILITIES ============ */

static void *xmalloc(size_t n) { void *p = malloc(n); if (!p) { fprintf(stderr, "OOM\n"); exit(1); } return p; }
static void *xrealloc(void *p, size_t n) { void *q = realloc(p, n); if (!q) { fprintf(stderr, "OOM\n"); exit(1); } return q; }

typedef struct { char *data; int len, cap; } Buf;
static void buf_init(Buf *b) { b->cap = 64; b->data = xmalloc(b->cap); b->len = 0; }
static void buf_putc(Buf *b, char c) { if (b->len >= b->cap) { b->cap *= 2; b->data = xrealloc(b->data, b->cap); } b->data[b->len++] = c; }
static void buf_puts(Buf *b, const char *s) { while (*s) buf_putc(b, *s++); }
static void buf_putn(Buf *b, const char *s, int n) { for (int i = 0; i < n; i++) buf_putc(b, s[i]); }

/* ============ LEXER ============ */

typedef enum {
    TOK_EOF, TOK_INT, TOK_STR, TOK_IDENT,
    TOK_LET, TOK_FN, TOK_IF, TOK_ELSE, TOK_WHILE, TOK_FOR, TOK_IN,
    TOK_RETURN, TOK_BREAK, TOK_CONTINUE, TOK_AND, TOK_OR, TOK_NOT,
    TOK_TRUE, TOK_FALSE, TOK_NIL,
    TOK_EQ, TOK_NE, TOK_LE, TOK_GE, TOK_LT, TOK_GT, TOK_ASSIGN,
    TOK_PLUS, TOK_MINUS, TOK_STAR, TOK_SLASH, TOK_PERCENT,
    TOK_LPAREN, TOK_RPAREN, TOK_LBRACKET, TOK_RBRACKET,
    TOK_LBRACE, TOK_RBRACE, TOK_COMMA, TOK_SEMI
} TokType;

typedef struct {
    TokType type;
    int line;
    int64_t ival;
    char *sval;
    int slen;
    const char *name;
} Token;

static Token *tokens;
static int ntok, tokpos;

static const char *keywords[] = {"let","fn","if","else","while","for","in","return","break","continue","and","or","not","true","false","nil",NULL};
static TokType kw_types[] = {TOK_LET,TOK_FN,TOK_IF,TOK_ELSE,TOK_WHILE,TOK_FOR,TOK_IN,TOK_RETURN,TOK_BREAK,TOK_CONTINUE,TOK_AND,TOK_OR,TOK_NOT,TOK_TRUE,TOK_FALSE,TOK_NIL};

static void lex(const char *src) {
    int cap = 256; tokens = xmalloc(cap * sizeof(Token)); ntok = 0;
    int line = 1; const char *p = src;
    while (*p) {
        while (*p==' '||*p=='\t'||*p=='\r') p++;
        if (*p=='#') { while (*p && *p!='\n') p++; continue; }
        if (*p=='\n') { line++; p++; continue; }
        if (ntok >= cap) { cap *= 2; tokens = xrealloc(tokens, cap * sizeof(Token)); }
        Token *t = &tokens[ntok];
        memset(t, 0, sizeof(Token));
        t->line = line;
        if (isdigit(*p)) {
            int64_t v = 0;
            while (isdigit(*p)) { v = v*10 + (*p-'0'); p++; }
            t->type = TOK_INT; t->ival = v; ntok++;
        } else if (*p=='"') {
            p++; Buf b; buf_init(&b);
            while (*p && *p != '"') {
                if (*p=='\\') { p++;
                    if (*p=='n') buf_putc(&b,'\n');
                    else if (*p=='t') buf_putc(&b,'\t');
                    else if (*p=='"') buf_putc(&b,'"');
                    else if (*p=='\\') buf_putc(&b,'\\');
                    p++;
                } else { buf_putc(&b, *p); p++; }
            }
            p++; // skip closing "
            t->type = TOK_STR; t->sval = b.data; t->slen = b.len; ntok++;
        } else if (isalpha(*p) || *p=='_') {
            const char *start = p;
            while (isalnum(*p) || *p=='_') p++;
            int len = p - start;
            char *name = xmalloc(len+1); memcpy(name, start, len); name[len]=0;
            t->type = TOK_IDENT; t->name = name;
            for (int i = 0; keywords[i]; i++) {
                if (strcmp(name, keywords[i])==0) { t->type = kw_types[i]; break; }
            }
            ntok++;
        } else {
            switch (*p) {
                case '(': t->type=TOK_LPAREN; p++; break;
                case ')': t->type=TOK_RPAREN; p++; break;
                case '[': t->type=TOK_LBRACKET; p++; break;
                case ']': t->type=TOK_RBRACKET; p++; break;
                case '{': t->type=TOK_LBRACE; p++; break;
                case '}': t->type=TOK_RBRACE; p++; break;
                case ',': t->type=TOK_COMMA; p++; break;
                case ';': t->type=TOK_SEMI; p++; break;
                case '+': t->type=TOK_PLUS; p++; break;
                case '-': t->type=TOK_MINUS; p++; break;
                case '*': t->type=TOK_STAR; p++; break;
                case '/': t->type=TOK_SLASH; p++; break;
                case '%': t->type=TOK_PERCENT; p++; break;
                case '=': if (p[1]=='=') { t->type=TOK_EQ; p+=2; } else { t->type=TOK_ASSIGN; p++; } break;
                case '!': if (p[1]=='=') { t->type=TOK_NE; p+=2; } else { t->type=TOK_NOT; p++; } break;
                case '<': if (p[1]=='=') { t->type=TOK_LE; p+=2; } else { t->type=TOK_LT; p++; } break;
                case '>': if (p[1]=='=') { t->type=TOK_GE; p+=2; } else { t->type=TOK_GT; p++; } break;
                default: p++; continue;
            }
            ntok++;
        }
    }
    if (ntok >= cap) { cap++; tokens = xrealloc(tokens, cap * sizeof(Token)); }
    memset(&tokens[ntok], 0, sizeof(Token));
    tokens[ntok].type = TOK_EOF; tokens[ntok].line = line; ntok++;
}

/* ============ AST ============ */

enum { OP_ADD,OP_SUB,OP_MUL,OP_DIV,OP_MOD,OP_EQ,OP_NE,OP_LT,OP_LE,OP_GT,OP_GE,OP_AND,OP_OR,OP_NOT,OP_NEG };

typedef enum {
    STMT_LET, STMT_FN, STMT_IF, STMT_WHILE, STMT_FOR,
    STMT_RETURN, STMT_BREAK, STMT_CONTINUE,
    STMT_ASSIGN, STMT_IDX_ASSIGN, STMT_EXPR,
    EXPR_INT, EXPR_STR, EXPR_BOOL, EXPR_NIL, EXPR_IDENT,
    EXPR_BINOP, EXPR_UNOP, EXPR_CALL, EXPR_INDEX,
    EXPR_LIST, EXPR_FN
} NodeType;

typedef struct Node {
    int type;
    int line;
    union {
        int64_t ival;
        struct { char *data; int len; } sval;
        int bval;
        struct { const char *name; } ident;
        struct { int op; struct Node *left, *right; } binop;
        struct { int op; struct Node *operand; } unop;
        struct { struct Node *callee; struct Node **args; int nargs; } call;
        struct { struct Node *obj, *index; } idx;
        struct { struct Node **elems; int nelems; } list;
        struct { const char **params; int nparams; struct Node **body; int nbody; } fn_expr;
        struct { const char *name; struct Node *expr; } let;
        struct { const char *name; const char **params; int nparams; struct Node **body; int nbody; } fn;
        struct { struct Node *cond; struct Node **then_b; int n_then; struct Node **else_b; int n_else; int else_blk; } ifst;
        struct { struct Node *cond; struct Node **body; int nbody; } whilest;
        struct { const char *var; struct Node *iter; struct Node **body; int nbody; } forst;
        struct { struct Node *expr; } ret;
        struct { const char *name; struct Node *expr; } assign;
        struct { struct Node *obj, *index, *value; } idxas;
        struct { struct Node *expr; } exprst;
    };
} Node;

static Node *mknode(int type, int line) { Node *n = xmalloc(sizeof(Node)); memset(n,0,sizeof(Node)); n->type=type; n->line=line; return n; }

/* ============ PARSER ============ */

static Token *peek() { return &tokens[tokpos]; }
static Token *advance() { return &tokens[tokpos++]; }
static int match(TokType t) { if (peek()->type==t) { tokpos++; return 1; } return 0; }
static void expect(TokType t) { if (!match(t)) { fprintf(stderr,"Parse error at line %d\n",peek()->line); exit(1); } }

static Node *parse_expr();
static Node *parse_block(int *n);
static Node *parse_stmt();

static Node **parse_block_list(int *n) {
    expect(TOK_LBRACE);
    int cap = 8; *n = 0;
    Node **stmts = xmalloc(cap * sizeof(Node*));
    while (peek()->type != TOK_RBRACE && peek()->type != TOK_EOF) {
        if (*n >= cap) { cap*=2; stmts=xrealloc(stmts,cap*sizeof(Node*)); }
        stmts[(*n)++] = parse_stmt();
    }
    expect(TOK_RBRACE);
    return stmts;
}

static Node *parse_primary() {
    Token *t = peek();
    if (t->type == TOK_INT) { advance(); Node *n=mknode(EXPR_INT,t->line); n->ival=t->ival; return n; }
    if (t->type == TOK_STR) { advance(); Node *n=mknode(EXPR_STR,t->line); n->sval.data=t->sval; n->sval.len=t->slen; return n; }
    if (t->type == TOK_TRUE) { advance(); Node *n=mknode(EXPR_BOOL,t->line); n->bval=1; return n; }
    if (t->type == TOK_FALSE) { advance(); Node *n=mknode(EXPR_BOOL,t->line); n->bval=0; return n; }
    if (t->type == TOK_NIL) { advance(); Node *n=mknode(EXPR_NIL,t->line); return n; }
    if (t->type == TOK_IDENT) { advance(); Node *n=mknode(EXPR_IDENT,t->line); n->ident.name=t->name; return n; }
    if (t->type == TOK_LPAREN) { advance(); Node *e=parse_expr(); expect(TOK_RPAREN); return e; }
    if (t->type == TOK_LBRACKET) {
        advance(); int cap=8,n=0; Node **elems=xmalloc(cap*sizeof(Node*));
        if (peek()->type != TOK_RBRACKET) {
            do { if(n>=cap){cap*=2;elems=xrealloc(elems,cap*sizeof(Node*));} elems[n++]=parse_expr(); } while(match(TOK_COMMA));
        }
        expect(TOK_RBRACKET);
        Node *nd=mknode(EXPR_LIST,t->line); nd->list.elems=elems; nd->list.nelems=n; return nd;
    }
    if (t->type == TOK_FN) {
        advance(); expect(TOK_LPAREN);
        int cap=8,np=0; const char **params=NULL;
        if (peek()->type != TOK_RPAREN) {
            do { if(np>=cap){cap*=2;params=xrealloc(params,cap*sizeof(const char*));} params[np++]=advance()->name; } while(match(TOK_COMMA));
        }
        expect(TOK_RPAREN);
        int nb; Node **body=parse_block_list(&nb);
        Node *nd=mknode(EXPR_FN,t->line); nd->fn_expr.params=params; nd->fn_expr.nparams=np; nd->fn_expr.body=body; nd->fn_expr.nbody=nb; return nd;
    }
    fprintf(stderr,"Parse error at line %d\n",t->line); exit(1); return NULL;
}

static Node *parse_postfix() {
    Node *n = parse_primary();
    while (peek()->type==TOK_LPAREN || peek()->type==TOK_LBRACKET) {
        if (peek()->type==TOK_LPAREN) {
            int line=peek()->line; advance();
            int cap=8,na=0; Node **args=NULL;
            if (peek()->type!=TOK_RPAREN) {
                do { if(na>=cap){cap*=2;args=xrealloc(args,cap*sizeof(Node*));} args[na++]=parse_expr(); } while(match(TOK_COMMA));
            }
            expect(TOK_RPAREN);
            Node *nd=mknode(EXPR_CALL,line); nd->call.callee=n; nd->call.args=args; nd->call.nargs=na; n=nd;
        } else {
            int line=peek()->line; advance();
            Node *idx=parse_expr(); expect(TOK_RBRACKET);
            Node *nd=mknode(EXPR_INDEX,line); nd->idx.obj=n; nd->idx.index=idx; n=nd;
        }
    }
    return n;
}

static Node *parse_unary() {
    if (peek()->type==TOK_MINUS) {
        int line=peek()->line; advance();
        Node *nd=mknode(EXPR_UNOP,line); nd->unop.op=OP_NEG; nd->unop.operand=parse_unary(); return nd;
    }
    return parse_postfix();
}

static Node *parse_mul() {
    Node *n=parse_unary();
    while (peek()->type==TOK_STAR||peek()->type==TOK_SLASH||peek()->type==TOK_PERCENT) {
        int line=peek()->line; int op;
        if(peek()->type==TOK_STAR)op=OP_MUL; else if(peek()->type==TOK_SLASH)op=OP_DIV; else op=OP_MOD;
        advance(); Node *r=parse_unary();
        Node *nd=mknode(EXPR_BINOP,line); nd->binop.op=op; nd->binop.left=n; nd->binop.right=r; n=nd;
    }
    return n;
}

static Node *parse_add() {
    Node *n=parse_mul();
    while (peek()->type==TOK_PLUS||peek()->type==TOK_MINUS) {
        int line=peek()->line; int op=peek()->type==TOK_PLUS?OP_ADD:OP_SUB; advance();
        Node *r=parse_mul();
        Node *nd=mknode(EXPR_BINOP,line); nd->binop.op=op; nd->binop.left=n; nd->binop.right=r; n=nd;
    }
    return n;
}

static Node *parse_comp() {
    Node *n=parse_add();
    while (peek()->type==TOK_EQ||peek()->type==TOK_NE||peek()->type==TOK_LT||peek()->type==TOK_LE||peek()->type==TOK_GT||peek()->type==TOK_GE) {
        int line=peek()->line; int op;
        switch(peek()->type){case TOK_EQ:op=OP_EQ;break;case TOK_NE:op=OP_NE;break;case TOK_LT:op=OP_LT;break;case TOK_LE:op=OP_LE;break;case TOK_GT:op=OP_GT;break;default:op=OP_GE;break;}
        advance(); Node *r=parse_add();
        Node *nd=mknode(EXPR_BINOP,line); nd->binop.op=op; nd->binop.left=n; nd->binop.right=r; n=nd;
    }
    return n;
}

static Node *parse_not() {
    if (peek()->type==TOK_NOT) {
        int line=peek()->line; advance();
        Node *nd=mknode(EXPR_UNOP,line); nd->unop.op=OP_NOT; nd->unop.operand=parse_not(); return nd;
    }
    return parse_comp();
}

static Node *parse_and() {
    Node *n=parse_not();
    while (peek()->type==TOK_AND) {
        int line=peek()->line; advance();
        Node *r=parse_not();
        Node *nd=mknode(EXPR_BINOP,line); nd->binop.op=OP_AND; nd->binop.left=n; nd->binop.right=r; n=nd;
    }
    return n;
}

static Node *parse_or() {
    Node *n=parse_and();
    while (peek()->type==TOK_OR) {
        int line=peek()->line; advance();
        Node *r=parse_and();
        Node *nd=mknode(EXPR_BINOP,line); nd->binop.op=OP_OR; nd->binop.left=n; nd->binop.right=r; n=nd;
    }
    return n;
}

static Node *parse_expr() { return parse_or(); }

static Node *parse_stmt() {
    Token *t=peek();
    if (t->type==TOK_LET) {
        advance(); const char *name=advance()->name; expect(TOK_ASSIGN);
        Node *e=parse_expr(); expect(TOK_SEMI);
        Node *n=mknode(STMT_LET,t->line); n->let.name=name; n->let.expr=e; return n;
    }
    if (t->type==TOK_FN && tokens[tokpos+1].type==TOK_IDENT) {
        advance(); const char *name=advance()->name; expect(TOK_LPAREN);
        int cap=8,np=0; const char **params=NULL;
        if (peek()->type!=TOK_RPAREN) {
            do { if(np>=cap){cap*=2;params=xrealloc(params,cap*sizeof(const char*));} params[np++]=advance()->name; } while(match(TOK_COMMA));
        }
        expect(TOK_RPAREN);
        int nb; Node **body=parse_block_list(&nb);
        Node *n=mknode(STMT_FN,t->line); n->fn.name=name; n->fn.params=params; n->fn.nparams=np; n->fn.body=body; n->fn.nbody=nb; return n;
    }
    if (t->type==TOK_IF) {
        advance(); Node *cond=parse_expr();
        int nt; Node **tb=parse_block_list(&nt);
        Node **eb=NULL; int ne=0, eb_blk=0;
        if (peek()->type==TOK_ELSE) {
            advance();
            if (peek()->type==TOK_IF) {
                eb=xmalloc(sizeof(Node*)); eb[0]=parse_stmt(); ne=1; eb_blk=0;
            } else {
                eb=parse_block_list(&ne); eb_blk=1;
            }
        }
        Node *n=mknode(STMT_IF,t->line); n->ifst.cond=cond; n->ifst.then_b=tb; n->ifst.n_then=nt; n->ifst.else_b=eb; n->ifst.n_else=ne; n->ifst.else_blk=eb_blk; return n;
    }
    if (t->type==TOK_WHILE) {
        advance(); Node *cond=parse_expr();
        int nb; Node **body=parse_block_list(&nb);
        Node *n=mknode(STMT_WHILE,t->line); n->whilest.cond=cond; n->whilest.body=body; n->whilest.nbody=nb; return n;
    }
    if (t->type==TOK_FOR) {
        advance(); const char *var=advance()->name; expect(TOK_IN);
        Node *iter=parse_expr();
        int nb; Node **body=parse_block_list(&nb);
        Node *n=mknode(STMT_FOR,t->line); n->forst.var=var; n->forst.iter=iter; n->forst.body=body; n->forst.nbody=nb; return n;
    }
    if (t->type==TOK_RETURN) {
        advance(); Node *e=NULL;
        if (peek()->type!=TOK_SEMI) e=parse_expr();
        expect(TOK_SEMI);
        Node *n=mknode(STMT_RETURN,t->line); n->ret.expr=e; return n;
    }
    if (t->type==TOK_BREAK) { advance(); expect(TOK_SEMI); return mknode(STMT_BREAK,t->line); }
    if (t->type==TOK_CONTINUE) { advance(); expect(TOK_SEMI); return mknode(STMT_CONTINUE,t->line); }
    // expression or assignment
    Node *e=parse_expr();
    if (peek()->type==TOK_ASSIGN) {
        advance(); Node *val=parse_expr(); expect(TOK_SEMI);
        if (e->type==EXPR_IDENT) {
            Node *n=mknode(STMT_ASSIGN,t->line); n->assign.name=e->ident.name; n->assign.expr=val; return n;
        } else if (e->type==EXPR_INDEX) {
            Node *n=mknode(STMT_IDX_ASSIGN,t->line); n->idxas.obj=e->idx.obj; n->idxas.index=e->idx.index; n->idxas.value=val; n->line=e->line; return n;
        }
    }
    expect(TOK_SEMI);
    Node *n=mknode(STMT_EXPR,t->line); n->exprst.expr=e; return n;
}

/* ============ VALUES ============ */

typedef enum { T_NIL, T_INT, T_BOOL, T_STRING, T_LIST, T_FUNCTION } Type;

typedef struct Value Value;
typedef struct Scope Scope;
typedef struct Node Node;

typedef struct { char *data; int len; } Str;
typedef struct { Value *items; int len, cap; } List;
typedef struct {
    const char **params; int nparams;
    Node **body; int nbody;
    Scope *captured;
    int is_builtin; int builtin_id; int nargs;
} Func;

struct Value {
    int type;
    union {
        int64_t ival;
        int bval;
        Str *sval;
        List *lval;
        Func *fval;
    };
};

static Value nil_val() { Value v; v.type=T_NIL; v.ival=0; return v; }
static Value int_val(int64_t x) { Value v; v.type=T_INT; v.ival=x; return v; }
static Value bool_val(int x) { Value v; v.type=T_BOOL; v.bval=x; return v; }
static Value str_val(const char *s, int len) { Value v; v.type=T_STRING; Str *st=xmalloc(sizeof(Str)); st->data=xmalloc(len); memcpy(st->data,s,len); st->len=len; v.sval=st; return v; }
static Value str_val_raw(char *data, int len) { Value v; v.type=T_STRING; Str *st=xmalloc(sizeof(Str)); st->data=data; st->len=len; v.sval=st; return v; }
static Value list_val(List *l) { Value v; v.type=T_LIST; v.lval=l; return v; }
static Value func_val(Func *f) { Value v; v.type=T_FUNCTION; v.fval=f; return v; }

static List *new_list() { List *l=xmalloc(sizeof(List)); l->cap=4; l->len=0; l->items=xmalloc(l->cap*sizeof(Value)); return l; }
static void list_push(List *l, Value v) { if(l->len>=l->cap){l->cap*=2;l->items=xrealloc(l->items,l->cap*sizeof(Value));} l->items[l->len++]=v; }

/* ============ SCOPE ============ */

struct Scope {
    Scope *parent;
    const char **names;
    Value *vals;
    int count, cap;
};

static Scope *new_scope(Scope *parent) {
    Scope *s=xmalloc(sizeof(Scope));
    s->parent=parent; s->cap=8; s->count=0;
    s->names=xmalloc(s->cap*sizeof(const char*));
    s->vals=xmalloc(s->cap*sizeof(Value));
    return s;
}

static void scope_declare(Scope *s, const char *name, Value v) {
    if(s->count>=s->cap){s->cap*=2;s->names=xrealloc(s->names,s->cap*sizeof(const char*));s->vals=xrealloc(s->vals,s->cap*sizeof(Value));}
    s->names[s->count]=name; s->vals[s->count]=v; s->count++;
}

static Value *scope_lookup(Scope *s, const char *name) {
    while(s) {
        for(int i=s->count-1;i>=0;i--) if(strcmp(s->names[i],name)==0) return &s->vals[i];
        s=s->parent;
    }
    return NULL;
}

/* ============ ERROR HANDLING ============ */

static jmp_buf err_jmp;
static int err_line;
static char err_msg[512];

static void error_at(int line, const char *fmt, ...) {
    err_line=line;
    va_list ap; va_start(ap,fmt); vsnprintf(err_msg,sizeof(err_msg),fmt,ap); va_end(ap);
    longjmp(err_jmp,1);
}

/* ============ DISPLAY ============ */

static void display_val(Value v, Buf *b, int in_list, List **stack, int *slen, int scap) {
    switch(v.type) {
        case T_NIL: buf_puts(b,"nil"); break;
        case T_INT: { char tmp[32]; snprintf(tmp,sizeof(tmp),"%lld",(long long)v.ival); buf_puts(b,tmp); } break;
        case T_BOOL: buf_puts(b,v.bval?"true":"false"); break;
        case T_STRING:
            if (in_list) {
                buf_putc(b,'"');
                for(int i=0;i<v.sval->len;i++){
                    char c=v.sval->data[i];
                    if(c=='\\')buf_puts(b,"\\\\");
                    else if(c=='"')buf_puts(b,"\\\"");
                    else if(c=='\n')buf_puts(b,"\\n");
                    else if(c=='\t')buf_puts(b,"\\t");
                    else buf_putc(b,c);
                }
                buf_putc(b,'"');
            } else {
                buf_putn(b,v.sval->data,v.sval->len);
            }
            break;
        case T_LIST:
            for(int i=0;i<*slen;i++) if(stack[i]==v.lval){buf_puts(b,"[...]");return;}
            if(*slen>=scap){/* shouldn't happen in practice */}
            stack[(*slen)++]=v.lval;
            buf_putc(b,'[');
            for(int i=0;i<v.lval->len;i++){
                if(i)buf_puts(b,", ");
                display_val(v.lval->items[i],b,1,stack,slen,scap);
            }
            buf_putc(b,']');
            (*slen)--;
            break;
        case T_FUNCTION: buf_puts(b,"<fn>"); break;
    }
}

static const char *type_name(int t) {
    switch(t){case T_NIL:return"nil";case T_INT:return"int";case T_BOOL:return"bool";case T_STRING:return"string";case T_LIST:return"list";case T_FUNCTION:return"function";}
    return "?";
}

static int is_truthy(Value v) {
    switch(v.type){
        case T_NIL: return 0;
        case T_INT: return v.ival!=0;
        case T_BOOL: return v.bval;
        case T_STRING: return v.sval->len!=0;
        case T_LIST: return v.lval->len!=0;
        case T_FUNCTION: return 1;
    }
    return 0;
}

static int values_equal(Value a, Value b) {
    if(a.type!=b.type) return 0;
    switch(a.type){
        case T_NIL: return 1;
        case T_INT: return a.ival==b.ival;
        case T_BOOL: return a.bval==b.bval;
        case T_STRING: return a.sval->len==b.sval->len && memcmp(a.sval->data,b.sval->data,a.sval->len)==0;
        case T_LIST:
            if(a.lval->len!=b.lval->len) return 0;
            for(int i=0;i<a.lval->len;i++) if(!values_equal(a.lval->items[i],b.lval->items[i])) return 0;
            return 1;
        case T_FUNCTION: return a.fval==b.fval;
    }
    return 0;
}

/* ============ INTERPRETER ============ */

enum { CF_NORMAL, CF_BREAK, CF_CONTINUE, CF_RETURN };
static Value return_value;

static Value eval(Node *n, Scope *sc);
static int exec_stmts(Node **stmts, int n, Scope *sc);
static Value call_func(Value fn, Value *args, int nargs, int line);

static int64_t checked_add(int64_t a, int64_t b, int line) {
    __int128 r=(__int128)a+b;
    if(r>INT64_MAX||r<INT64_MIN) error_at(line,"integer overflow");
    return (int64_t)r;
}
static int64_t checked_sub(int64_t a, int64_t b, int line) {
    __int128 r=(__int128)a-b;
    if(r>INT64_MAX||r<INT64_MIN) error_at(line,"integer overflow");
    return (int64_t)r;
}
static int64_t checked_mul(int64_t a, int64_t b, int line) {
    __int128 r=(__int128)a*b;
    if(r>INT64_MAX||r<INT64_MIN) error_at(line,"integer overflow");
    return (int64_t)r;
}
static int64_t checked_neg(int64_t a, int line) {
    if(a==INT64_MIN) error_at(line,"integer overflow");
    return -a;
}
static int64_t checked_div(int64_t a, int64_t b, int line) {
    if(b==0) error_at(line,"division by zero");
    if(a==INT64_MIN&&b==-1) error_at(line,"integer overflow");
    return a/b;
}
static int64_t checked_mod(int64_t a, int64_t b, int line) {
    if(b==0) error_at(line,"division by zero");
    if(b==-1) return 0;
    return a%b;
}

static Value eval(Node *n, Scope *sc) {
    switch(n->type) {
        case EXPR_INT: return int_val(n->ival);
        case EXPR_STR: return str_val(n->sval.data,n->sval.len);
        case EXPR_BOOL: return bool_val(n->bval);
        case EXPR_NIL: return nil_val();
        case EXPR_IDENT: {
            Value *v=scope_lookup(sc,n->ident.name);
            if(!v) error_at(n->line,"undefined variable %s",n->ident.name);
            return *v;
        }
        case EXPR_BINOP: {
            int op=n->binop.op;
            if(op==OP_AND){Value l=eval(n->binop.left,sc);if(!is_truthy(l))return l;return eval(n->binop.right,sc);}
            if(op==OP_OR){Value l=eval(n->binop.left,sc);if(is_truthy(l))return l;return eval(n->binop.right,sc);}
            Value l=eval(n->binop.left,sc);
            Value r=eval(n->binop.right,sc);
            if(op==OP_EQ) return bool_val(values_equal(l,r));
            if(op==OP_NE) return bool_val(!values_equal(l,r));
            if(op==OP_ADD){
                if(l.type==T_INT&&r.type==T_INT) return int_val(checked_add(l.ival,r.ival,n->line));
                if(l.type==T_STRING&&r.type==T_STRING){
                    int nl=l.sval->len+r.sval->len; char *d=xmalloc(nl);
                    memcpy(d,l.sval->data,l.sval->len);memcpy(d+l.sval->len,r.sval->data,r.sval->len);
                    return str_val_raw(d,nl);
                }
                if(l.type==T_LIST&&r.type==T_LIST){
                    List *nl=new_list();
                    for(int i=0;i<l.lval->len;i++)list_push(nl,l.lval->items[i]);
                    for(int i=0;i<r.lval->len;i++)list_push(nl,r.lval->items[i]);
                    return list_val(nl);
                }
                error_at(n->line,"cannot apply + to %s and %s",type_name(l.type),type_name(r.type));
            }
            if(op==OP_SUB){
                if(l.type==T_INT&&r.type==T_INT) return int_val(checked_sub(l.ival,r.ival,n->line));
                error_at(n->line,"cannot apply - to %s and %s",type_name(l.type),type_name(r.type));
            }
            if(op==OP_MUL){
                if(l.type==T_INT&&r.type==T_INT) return int_val(checked_mul(l.ival,r.ival,n->line));
                error_at(n->line,"cannot apply * to %s and %s",type_name(l.type),type_name(r.type));
            }
            if(op==OP_DIV){
                if(l.type==T_INT&&r.type==T_INT) return int_val(checked_div(l.ival,r.ival,n->line));
                error_at(n->line,"cannot apply / to %s and %s",type_name(l.type),type_name(r.type));
            }
            if(op==OP_MOD){
                if(l.type==T_INT&&r.type==T_INT) return int_val(checked_mod(l.ival,r.ival,n->line));
                error_at(n->line,"cannot apply %% to %s and %s",type_name(l.type),type_name(r.type));
            }
            if(op==OP_LT||op==OP_LE||op==OP_GT||op==OP_GE){
                if(l.type==T_INT&&r.type==T_INT){
                    int c=l.ival<r.ival?(-1):(l.ival>r.ival?1:0);
                    if(op==OP_LT)return bool_val(c<0);
                    if(op==OP_LE)return bool_val(c<=0);
                    if(op==OP_GT)return bool_val(c>0);
                    return bool_val(c>=0);
                }
                if(l.type==T_STRING&&r.type==T_STRING){
                    int ml=l.sval->len<r.sval->len?l.sval->len:r.sval->len;
                    int c=memcmp(l.sval->data,r.sval->data,ml);
                    if(c==0) c=l.sval->len<r.sval->len?(-1):(l.sval->len>r.sval->len?1:0);
                    else c=c<0?(-1):1;
                    if(op==OP_LT)return bool_val(c<0);
                    if(op==OP_LE)return bool_val(c<=0);
                    if(op==OP_GT)return bool_val(c>0);
                    return bool_val(c>=0);
                }
                error_at(n->line,"cannot apply %s to %s and %s",op==OP_LT?"<":op==OP_LE?"<=":op==OP_GT?">":">=",type_name(l.type),type_name(r.type));
            }
            error_at(n->line,"cannot apply op to %s and %s",type_name(l.type),type_name(r.type));
            break;
        }
        case EXPR_UNOP: {
            Value v=eval(n->unop.operand,sc);
            if(n->unop.op==OP_NOT) return bool_val(!is_truthy(v));
            if(n->unop.op==OP_NEG){
                if(v.type!=T_INT) error_at(n->line,"cannot apply - to %s",type_name(v.type));
                return int_val(checked_neg(v.ival,n->line));
            }
            break;
        }
        case EXPR_CALL: {
            Value callee=eval(n->call.callee,sc);
            Value *args=NULL;
            if(n->call.nargs>0){
                args=xmalloc(n->call.nargs*sizeof(Value));
                for(int i=0;i<n->call.nargs;i++) args[i]=eval(n->call.args[i],sc);
            }
            return call_func(callee,args,n->call.nargs,n->line);
        }
        case EXPR_INDEX: {
            Value obj=eval(n->idx.obj,sc);
            Value idx=eval(n->idx.index,sc);
            if((obj.type!=T_LIST&&obj.type!=T_STRING)||idx.type!=T_INT)
                error_at(n->line,"cannot index %s with %s",type_name(obj.type),type_name(idx.type));
            int64_t i=idx.ival;
            if(obj.type==T_LIST){
                if(i<0||i>=obj.lval->len) error_at(n->line,"index %lld out of range for length %d",(long long)i,obj.lval->len);
                return obj.lval->items[i];
            } else {
                if(i<0||i>=obj.sval->len) error_at(n->line,"index %lld out of range for length %d",(long long)i,obj.sval->len);
                return str_val(&obj.sval->data[i],1);
            }
            break;
        }
        case EXPR_LIST: {
            List *l=new_list();
            for(int i=0;i<n->list.nelems;i++) list_push(l,eval(n->list.elems[i],sc));
            return list_val(l);
        }
        case EXPR_FN: {
            Func *f=xmalloc(sizeof(Func));
            f->params=n->fn_expr.params; f->nparams=n->fn_expr.nparams;
            f->body=n->fn_expr.body; f->nbody=n->fn_expr.nbody;
            f->captured=sc; f->is_builtin=0;
            return func_val(f);
        }
    }
    return nil_val();
}

/* Builtins */
enum { BI_PRINT, BI_STR, BI_TYPE, BI_LEN, BI_PUSH, BI_POP, BI_RANGE, BI_SLICE };

static Value call_builtin(int id, Value *args, int nargs, int line) {
    switch(id) {
        case BI_PRINT: {
            Buf b; buf_init(&b);
            List *stack=xmalloc(64*sizeof(List*)); int slen=0;
            for(int i=0;i<nargs;i++){
                if(i)buf_putc(&b,' ');
                display_val(args[i],&b,0,stack,&slen,64);
            }
            buf_putc(&b,'\n');
            fwrite(b.data,1,b.len,stdout);
            free(stack);
            return nil_val();
        }
        case BI_STR: {
            if(nargs!=1) error_at(line,"expected 1 arguments, got %d",nargs);
            Buf b; buf_init(&b);
            List *stack=xmalloc(64*sizeof(List*)); int slen=0;
            display_val(args[0],&b,0,stack,&slen,64);
            free(stack);
            return str_val_raw(b.data,b.len);
        }
        case BI_TYPE: {
            if(nargs!=1) error_at(line,"expected 1 arguments, got %d",nargs);
            const char *tn=type_name(args[0].type);
            return str_val(tn,strlen(tn));
        }
        case BI_LEN: {
            if(nargs!=1) error_at(line,"expected 1 arguments, got %d",nargs);
            if(args[0].type==T_STRING) return int_val(args[0].sval->len);
            if(args[0].type==T_LIST) return int_val(args[0].lval->len);
            error_at(line,"bad argument to len");
            break;
        }
        case BI_PUSH: {
            if(nargs!=2) error_at(line,"expected 2 arguments, got %d",nargs);
            if(args[0].type!=T_LIST) error_at(line,"bad argument to push");
            list_push(args[0].lval,args[1]);
            return nil_val();
        }
        case BI_POP: {
            if(nargs!=1) error_at(line,"expected 1 arguments, got %d",nargs);
            if(args[0].type!=T_LIST||args[0].lval->len==0) error_at(line,"bad argument to pop");
            return args[0].lval->items[--args[0].lval->len];
        }
        case BI_RANGE: {
            if(nargs!=2) error_at(line,"expected 2 arguments, got %d",nargs);
            if(args[0].type!=T_INT||args[1].type!=T_INT) error_at(line,"bad argument to range");
            int64_t a=args[0].ival,b=args[1].ival;
            List *l=new_list();
            for(int64_t i=a;i<b;i++) list_push(l,int_val(i));
            return list_val(l);
        }
        case BI_SLICE: {
            if(nargs!=3) error_at(line,"expected 3 arguments, got %d",nargs);
            if(args[0].type!=T_STRING&&args[0].type!=T_LIST) error_at(line,"bad argument to slice");
            if(args[1].type!=T_INT||args[2].type!=T_INT) error_at(line,"bad argument to slice");
            int64_t a=args[1].ival,b=args[2].ival;
            int len;
            if(args[0].type==T_STRING) len=args[0].sval->len; else len=args[0].lval->len;
            if(a<0||b>len||a>b) error_at(line,"bad argument to slice");
            if(args[0].type==T_STRING){
                int nl=b-a; char *d=xmalloc(nl);
                memcpy(d,args[0].sval->data+a,nl);
                return str_val_raw(d,nl);
            } else {
                List *l=new_list();
                for(int64_t i=a;i<b;i++) list_push(l,args[0].lval->items[i]);
                return list_val(l);
            }
        }
    }
    return nil_val();
}

static Value call_func(Value fn, Value *args, int nargs, int line) {
    if(fn.type!=T_FUNCTION) error_at(line,"cannot call %s",type_name(fn.type));
    Func *f=fn.fval;
    if(f->is_builtin) return call_builtin(f->builtin_id,args,nargs,line);
    if(nargs!=f->nparams) error_at(line,"expected %d arguments, got %d",f->nparams,nargs);
    Scope *sc=new_scope(f->captured);
    for(int i=0;i<f->nparams;i++) scope_declare(sc,f->params[i],args[i]);
    int cf=exec_stmts(f->body,f->nbody,sc);
    if(cf==CF_RETURN) return return_value;
    return nil_val();
}

static int exec_block(Node **stmts, int n, Scope *sc) {
    Scope *bs=new_scope(sc);
    return exec_stmts(stmts,n,bs);
}

static int exec_stmts(Node **stmts, int n, Scope *sc) {
    for(int i=0;i<n;i++){
        int cf=0;
        Node *s=stmts[i];
        switch(s->type){
            case STMT_LET: {
                Value v=eval(s->let.expr,sc);
                scope_declare(sc,s->let.name,v);
                break;
            }
            case STMT_FN: {
                scope_declare(sc,s->fn.name,nil_val());
                Func *f=xmalloc(sizeof(Func));
                f->params=s->fn.params; f->nparams=s->fn.nparams;
                f->body=s->fn.body; f->nbody=s->fn.nbody;
                f->captured=sc; f->is_builtin=0;
                Value fv=func_val(f);
                Value *slot=scope_lookup(sc,s->fn.name);
                *slot=fv;
                break;
            }
            case STMT_IF: {
                Value c=eval(s->ifst.cond,sc);
                if(is_truthy(c)){
                    cf=exec_block(s->ifst.then_b,s->ifst.n_then,sc);
                } else if(s->ifst.else_b){
                    if(s->ifst.else_blk) cf=exec_block(s->ifst.else_b,s->ifst.n_else,sc);
                    else cf=exec_stmts(s->ifst.else_b,s->ifst.n_else,sc);
                }
                if(cf!=CF_NORMAL) return cf;
                break;
            }
            case STMT_WHILE: {
                while(1){
                    Value c=eval(s->whilest.cond,sc);
                    if(!is_truthy(c)) break;
                    cf=exec_block(s->whilest.body,s->whilest.nbody,sc);
                    if(cf==CF_BREAK) break;
                    if(cf==CF_CONTINUE) continue;
                    if(cf==CF_RETURN) return cf;
                }
                break;
            }
            case STMT_FOR: {
                Value iter=eval(s->forst.iter,sc);
                if(iter.type!=T_LIST) error_at(s->line,"cannot iterate %s",type_name(iter.type));
                List *lst=iter.lval;
                int64_t i=0;
                while(i<lst->len){
                    Scope *ls=new_scope(sc);
                    scope_declare(ls,s->forst.var,lst->items[i]);
                    cf=exec_stmts(s->forst.body,s->forst.nbody,ls);
                    if(cf==CF_BREAK) break;
                    if(cf==CF_RETURN) return cf;
                    i++;
                }
                break;
            }
            case STMT_RETURN: {
                return_value=s->ret.expr?eval(s->ret.expr,sc):nil_val();
                return CF_RETURN;
            }
            case STMT_BREAK: return CF_BREAK;
            case STMT_CONTINUE: return CF_CONTINUE;
            case STMT_ASSIGN: {
                Value v=eval(s->assign.expr,sc);
                Value *slot=scope_lookup(sc,s->assign.name);
                if(!slot) error_at(s->line,"undefined variable %s",s->assign.name);
                *slot=v;
                break;
            }
            case STMT_IDX_ASSIGN: {
                Value obj=eval(s->idxas.obj,sc);
                Value idx=eval(s->idxas.index,sc);
                Value val=eval(s->idxas.value,sc);
                if(obj.type!=T_LIST) error_at(s->line,"cannot assign into %s",type_name(obj.type));
                if(idx.type!=T_INT) error_at(s->line,"cannot index list with %s",type_name(idx.type));
                int64_t i=idx.ival;
                if(i<0||i>=obj.lval->len) error_at(s->line,"index %lld out of range for length %d",(long long)i,obj.lval->len);
                obj.lval->items[i]=val;
                break;
            }
            case STMT_EXPR: eval(s->exprst.expr,sc); break;
        }
    }
    return CF_NORMAL;
}

/* ============ MAIN ============ */

int main(int argc, char **argv) {
    if(argc<2){fprintf(stderr,"Usage: %s <dir>\n",argv[0]);return 1;}
    char path[4096];
    snprintf(path,sizeof(path),"%s/program.tern",argv[1]);
    FILE *f=fopen(path,"r");
    if(!f){fprintf(stderr,"Cannot open %s\n",path);return 1;}
    fseek(f,0,SEEK_END); long sz=ftell(f); fseek(f,0,SEEK_SET);
    char *src=xmalloc(sz+1); fread(src,1,sz,f); src[sz]=0; fclose(f);

    lex(src);

    /* Parse */
    int pc=8; int pn=0; Node **prog=xmalloc(pc*sizeof(Node*));
    while(peek()->type!=TOK_EOF){
        if(pn>=pc){pc*=2;prog=xrealloc(prog,pc*sizeof(Node*));}
        prog[pn++]=parse_stmt();
    }

    /* Set up global scope with builtins */
    Scope *global=new_scope(NULL);
    struct { const char *name; int id; int nargs; } builtins[]={
        {"print",BI_PRINT,-1},{"str",BI_STR,1},{"type",BI_TYPE,1},
        {"len",BI_LEN,1},{"push",BI_PUSH,2},{"pop",BI_POP,1},
        {"range",BI_RANGE,2},{"slice",BI_SLICE,3},{NULL,0,0}
    };
    for(int i=0;builtins[i].name;i++){
        Func *f=xmalloc(sizeof(Func));
        memset(f,0,sizeof(Func));
        f->is_builtin=1; f->builtin_id=builtins[i].id; f->nargs=builtins[i].nargs;
        scope_declare(global,builtins[i].name,func_val(f));
    }

    /* Run */
    if(setjmp(err_jmp)==0){
        exec_stmts(prog,pn,global);
    } else {
        fflush(stdout);
        printf("error at line %d: %s\n",err_line,err_msg);
    }
    fflush(stdout);
    return 0;
}

use std::fs;
use std::path::Path;

fn crc32(data: &[u8]) -> u32 {
    let mut crc = 0xFFFFFFFFu32;
    for &byte in data {
        crc ^= byte as u32;
        for _ in 0..8 {
            if crc & 1 != 0 {
                crc = (crc >> 1) ^ 0xEDB88320;
            } else {
                crc >>= 1;
            }
        }
    }
    crc ^ 0xFFFFFFFF
}

fn split_lines(content: &[u8]) -> Vec<Vec<u8>> {
    if content.is_empty() {
        return vec![];
    }
    let mut lines = Vec::new();
    let mut start = 0;
    for i in 0..content.len() {
        if content[i] == b'\n' {
            lines.push(content[start..=i].to_vec());
            start = i + 1;
        }
    }
    if start < content.len() {
        lines.push(content[start..].to_vec());
    }
    lines
}

fn lines_to_bytes(lines: &[Vec<u8>]) -> Vec<u8> {
    let mut result = Vec::new();
    for line in lines {
        result.extend_from_slice(line);
    }
    result
}

#[derive(Clone)]
struct Hunk {
    a: usize,
    b: usize,
    d: usize,
    old_lines: Vec<Vec<u8>>,
    new_lines: Vec<Vec<u8>>,
}

#[derive(Clone, PartialEq)]
enum Kind {
    Create,
    Delete,
    Modify,
}

struct Section {
    path: String,
    kind: Kind,
    hunks: Vec<Hunk>,
}

enum HunkResult {
    Applied { position: usize, offset: i64 },
    Rejected,
    Malformed,
}

enum SectionResult {
    Error(String),
    Ok {
        hunk_results: Vec<HunkResult>,
        deleted: bool,
        final_lines: usize,
        crc: u32,
    },
}

fn parse_diff(diff_content: &[u8]) -> Vec<Section> {
    let diff_lines = split_lines(diff_content);
    let mut sections: Vec<Section> = Vec::new();
    let mut i = 0;

    while i < diff_lines.len() {
        let line_cow = String::from_utf8_lossy(&diff_lines[i]);
        let line_str: &str = line_cow.strip_suffix('\n').unwrap_or(&line_cow);

        if line_str.starts_with("diff --git a/") {
            let rest = &line_str["diff --git a/".len()..];
            let path = rest.split(" b/").next().unwrap_or(rest).to_string();

            let mut section = Section {
                path,
                kind: Kind::Modify,
                hunks: Vec::new(),
            };

            i += 1;
            let mut in_hunks = false;

            while i < diff_lines.len() {
                let line_cow = String::from_utf8_lossy(&diff_lines[i]);
                let line_str: &str = line_cow.strip_suffix('\n').unwrap_or(&line_cow);

                if line_str.starts_with("diff --git ") {
                    break;
                }

                if !in_hunks {
                    if line_str.starts_with("new file mode") {
                        section.kind = Kind::Create;
                    } else if line_str.starts_with("deleted file mode") {
                        section.kind = Kind::Delete;
                    } else if line_str.starts_with("--- ") || line_str.starts_with("+++ ") {
                        in_hunks = true;
                    }
                    i += 1;
                } else {
                    if line_str.starts_with("@@ ") {
                        let (hunk, new_i) = parse_hunk(&diff_lines, i);
                        section.hunks.push(hunk);
                        i = new_i;
                    } else {
                        i += 1;
                    }
                }
            }

            sections.push(section);
        } else {
            i += 1;
        }
    }

    sections
}

fn parse_hunk(diff_lines: &[Vec<u8>], start: usize) -> (Hunk, usize) {
    let header_cow = String::from_utf8_lossy(&diff_lines[start]);
    let header: &str = header_cow.strip_suffix('\n').unwrap_or(&header_cow);

    let rest = &header[3..]; // skip "@@ "
    let rb = rest.as_bytes();
    let mut pos = 0;

    // Parse -a[,b]
    pos += 1; // skip '-'
    let a_start = pos;
    while pos < rb.len() && rb[pos] != b',' && rb[pos] != b' ' {
        pos += 1;
    }
    let a: usize = rest[a_start..pos].parse().unwrap_or(0);
    let b: usize;
    if pos < rb.len() && rb[pos] == b',' {
        pos += 1;
        let b_start = pos;
        while pos < rb.len() && rb[pos] != b' ' {
            pos += 1;
        }
        b = rest[b_start..pos].parse().unwrap_or(0);
    } else {
        b = 1;
    }

    // Skip space
    if pos < rb.len() && rb[pos] == b' ' {
        pos += 1;
    }

    // Parse +c[,d]
    pos += 1; // skip '+'
    let c_start = pos;
    while pos < rb.len() && rb[pos] != b',' && rb[pos] != b' ' {
        pos += 1;
    }
    let _c: usize = rest[c_start..pos].parse().unwrap_or(0);
    let d: usize;
    if pos < rb.len() && rb[pos] == b',' {
        pos += 1;
        let d_start = pos;
        while pos < rb.len() && rb[pos] != b' ' {
            pos += 1;
        }
        d = rest[d_start..pos].parse().unwrap_or(0);
    } else {
        d = 1;
    }

    // Parse body
    let mut i = start + 1;
    let mut old_lines: Vec<Vec<u8>> = Vec::new();
    let mut new_lines: Vec<Vec<u8>> = Vec::new();
    let mut last_to_old = false;
    let mut last_to_new = false;

    while i < diff_lines.len() {
        let line = &diff_lines[i];
        if line.is_empty() {
            break;
        }
        let marker = line[0];

        // Check for next hunk or section
        let line_cow = String::from_utf8_lossy(line);
        let line_str: &str = line_cow.strip_suffix('\n').unwrap_or(&line_cow);
        if line_str.starts_with("@@ ") || line_str.starts_with("diff --git ") {
            break;
        }

        if marker == b'\\' {
            // No newline at end of file
            if last_to_old && !old_lines.is_empty() {
                let last = old_lines.last_mut().unwrap();
                if last.last() == Some(&b'\n') {
                    last.pop();
                }
            }
            if last_to_new && !new_lines.is_empty() {
                let last = new_lines.last_mut().unwrap();
                if last.last() == Some(&b'\n') {
                    last.pop();
                }
            }
            i += 1;
            continue;
        }

        let content = line[1..].to_vec();

        match marker {
            b' ' => {
                old_lines.push(content.clone());
                new_lines.push(content);
                last_to_old = true;
                last_to_new = true;
            }
            b'-' => {
                old_lines.push(content);
                last_to_old = true;
                last_to_new = false;
            }
            b'+' => {
                new_lines.push(content);
                last_to_old = false;
                last_to_new = true;
            }
            _ => {}
        }

        i += 1;
    }

    (Hunk { a, b, d, old_lines, new_lines }, i)
}

fn apply_section(section: &Section, tree_dir: &Path) -> SectionResult {
    let file_path = tree_dir.join(&section.path);
    let file_exists = file_path.exists();

    let content: Vec<u8> = match &section.kind {
        Kind::Create => {
            if file_exists {
                return SectionResult::Error("already exists".to_string());
            }
            Vec::new()
        }
        Kind::Delete | Kind::Modify => {
            if !file_exists {
                return SectionResult::Error("not found".to_string());
            }
            fs::read(&file_path).unwrap_or_default()
        }
    };

    let mut lines = split_lines(&content);
    let mut delta: i64 = 0;
    let mut hunk_results = Vec::new();
    let mut all_applied = true;

    for hunk in &section.hunks {
        if hunk.old_lines.len() != hunk.b || hunk.new_lines.len() != hunk.d {
            hunk_results.push(HunkResult::Malformed);
            all_applied = false;
            continue;
        }

        let p_expected = hunk.a as i64 + delta;

        if hunk.b == 0 {
            if p_expected >= 0 && p_expected <= lines.len() as i64 {
                let pos = p_expected as usize;
                for (i, new_line) in hunk.new_lines.iter().enumerate() {
                    lines.insert(pos + i, new_line.clone());
                }
                delta += hunk.d as i64;
                hunk_results.push(HunkResult::Applied {
                    position: p_expected as usize,
                    offset: 0,
                });
            } else {
                hunk_results.push(HunkResult::Rejected);
                all_applied = false;
            }
        } else {
            let max_pos = lines.len() as i64 - hunk.b as i64 + 1;
            let mut found = false;

            if max_pos >= 1 {
                let mut k: i64 = 0;
                loop {
                    let mut any_valid = false;

                    // Try p = P - k
                    let p1 = p_expected - k;
                    if p1 >= 1 && p1 <= max_pos {
                        any_valid = true;
                        let idx = (p1 - 1) as usize;
                        if lines[idx..idx + hunk.b] == hunk.old_lines[..] {
                            lines.splice(idx..idx + hunk.b, hunk.new_lines.iter().cloned());
                            delta += hunk.d as i64 - hunk.b as i64;
                            hunk_results.push(HunkResult::Applied {
                                position: p1 as usize,
                                offset: p1 - p_expected,
                            });
                            found = true;
                            break;
                        }
                    }

                    if k > 0 {
                        let p2 = p_expected + k;
                        if p2 >= 1 && p2 <= max_pos {
                            any_valid = true;
                            let idx = (p2 - 1) as usize;
                            if lines[idx..idx + hunk.b] == hunk.old_lines[..] {
                                lines.splice(idx..idx + hunk.b, hunk.new_lines.iter().cloned());
                                delta += hunk.d as i64 - hunk.b as i64;
                                hunk_results.push(HunkResult::Applied {
                                    position: p2 as usize,
                                    offset: p2 - p_expected,
                                });
                                found = true;
                                break;
                            }
                        }
                    }

                    if !any_valid {
                        break;
                    }
                    k += 1;
                }
            }

            if !found {
                hunk_results.push(HunkResult::Rejected);
                all_applied = false;
            }
        }
    }

    if section.kind == Kind::Delete && all_applied && lines.is_empty() {
        return SectionResult::Ok {
            hunk_results,
            deleted: true,
            final_lines: 0,
            crc: 0,
        };
    }

    let final_content = lines_to_bytes(&lines);
    let final_lines = lines.len();
    let crc = crc32(&final_content);

    SectionResult::Ok {
        hunk_results,
        deleted: false,
        final_lines,
        crc,
    }
}

fn main() {
    let args: Vec<String> = std::env::args().collect();
    let dir = &args[1];
    let diff_path = Path::new(dir).join("changes.diff");
    let tree_dir = Path::new(dir).join("tree");

    let diff_content = fs::read(&diff_path).expect("Failed to read changes.diff");
    let mut sections = parse_diff(&diff_content);

    sections.sort_by(|a, b| a.path.as_bytes().cmp(b.path.as_bytes()));

    let mut output = String::new();

    for section in &sections {
        let result = apply_section(section, &tree_dir);

        let kind_str = match &section.kind {
            Kind::Create => "create",
            Kind::Delete => "delete",
            Kind::Modify => "modify",
        };

        output.push_str(&format!("{}: {}\n", section.path, kind_str));

        match &result {
            SectionResult::Error(err) => {
                output.push_str(&format!("  error: {}\n", err));
            }
            SectionResult::Ok {
                hunk_results,
                deleted,
                final_lines,
                crc,
            } => {
                for (i, hr) in hunk_results.iter().enumerate() {
                    match hr {
                        HunkResult::Applied { position, offset } => {
                            let offset_str = if *offset > 0 {
                                format!("+{}", offset)
                            } else {
                                format!("{}", offset)
                            };
                            output.push_str(&format!(
                                "  hunk {}: applied at {} (offset {})\n",
                                i + 1,
                                position,
                                offset_str
                            ));
                        }
                        HunkResult::Rejected => {
                            output.push_str(&format!("  hunk {}: rejected\n", i + 1));
                        }
                        HunkResult::Malformed => {
                            output.push_str(&format!("  hunk {}: malformed\n", i + 1));
                        }
                    }
                }

                if *deleted {
                    output.push_str("  result: deleted\n");
                } else {
                    output.push_str(&format!(
                        "  result: {} lines, crc32 {:08x}\n",
                        final_lines, crc
                    ));
                }
            }
        }
    }

    print!("{}", output);
}

use std::collections::{HashMap, HashSet};
use std::rc::Rc;
use std::cell::RefCell;
use std::io::Write;
use std::process;

// ==================== TOKENS ====================

#[derive(Clone, Debug, PartialEq)]
enum Tok {
    Int(i64), Str(String), Ident(String),
    Let, Fn, If, Else, While, For, In, Return, Break, Continue,
    And, Or, Not, True, False, Nil,
    Eq, Neq, Le, Ge, Lt, Gt, Assign,
    Plus, Minus, Star, Slash, Percent,
    LParen, RParen, LBracket, RBracket, LBrace, RBrace,
    Comma, Semi, Eof,
}

#[derive(Clone)]
struct Token { kind: Tok, line: usize }

// ==================== LEXER ====================

fn lex(src: &str) -> Vec<Token> {
    let mut tokens = Vec::new();
    let b = src.as_bytes();
    let mut i = 0usize;
    let mut line = 1usize;
    while i < b.len() {
        match b[i] {
            b'\n' => { line += 1; i += 1; }
            b' ' | b'\t' | b'\r' => { i += 1; }
            b'#' => { while i < b.len() && b[i] != b'\n' { i += 1; } }
            b'0'..=b'9' => {
                let s = i;
                while i < b.len() && b[i].is_ascii_digit() { i += 1; }
                tokens.push(Token { kind: Tok::Int(src[s..i].parse().unwrap()), line });
            }
            b'"' => {
                i += 1;
                let mut s = String::new();
                while i < b.len() && b[i] != b'"' {
                    if b[i] == b'\\' {
                        i += 1;
                        match b[i] {
                            b'n' => s.push('\n'),
                            b't' => s.push('\t'),
                            b'"' => s.push('"'),
                            b'\\' => s.push('\\'),
                            c => s.push(c as char),
                        }
                    } else { s.push(b[i] as char); }
                    i += 1;
                }
                i += 1;
                tokens.push(Token { kind: Tok::Str(s), line });
            }
            c if c.is_ascii_alphabetic() || c == b'_' => {
                let s = i;
                while i < b.len() && (b[i].is_ascii_alphanumeric() || b[i] == b'_') { i += 1; }
                let w = &src[s..i];
                let kind = match w {
                    "let" => Tok::Let, "fn" => Tok::Fn, "if" => Tok::If,
                    "else" => Tok::Else, "while" => Tok::While, "for" => Tok::For,
                    "in" => Tok::In, "return" => Tok::Return, "break" => Tok::Break,
                    "continue" => Tok::Continue, "and" => Tok::And, "or" => Tok::Or,
                    "not" => Tok::Not, "true" => Tok::True, "false" => Tok::False,
                    "nil" => Tok::Nil,
                    _ => Tok::Ident(w.to_string()),
                };
                tokens.push(Token { kind, line });
            }
            b'=' if i + 1 < b.len() && b[i+1] == b'=' => { i += 2; tokens.push(Token{kind:Tok::Eq,line}); }
            b'!' if i + 1 < b.len() && b[i+1] == b'=' => { i += 2; tokens.push(Token{kind:Tok::Neq,line}); }
            b'<' if i + 1 < b.len() && b[i+1] == b'=' => { i += 2; tokens.push(Token{kind:Tok::Le,line}); }
            b'>' if i + 1 < b.len() && b[i+1] == b'=' => { i += 2; tokens.push(Token{kind:Tok::Ge,line}); }
            b'<' => { i += 1; tokens.push(Token{kind:Tok::Lt,line}); }
            b'>' => { i += 1; tokens.push(Token{kind:Tok::Gt,line}); }
            b'=' => { i += 1; tokens.push(Token{kind:Tok::Assign,line}); }
            b'+' => { i += 1; tokens.push(Token{kind:Tok::Plus,line}); }
            b'-' => { i += 1; tokens.push(Token{kind:Tok::Minus,line}); }
            b'*' => { i += 1; tokens.push(Token{kind:Tok::Star,line}); }
            b'/' => { i += 1; tokens.push(Token{kind:Tok::Slash,line}); }
            b'%' => { i += 1; tokens.push(Token{kind:Tok::Percent,line}); }
            b'(' => { i += 1; tokens.push(Token{kind:Tok::LParen,line}); }
            b')' => { i += 1; tokens.push(Token{kind:Tok::RParen,line}); }
            b'[' => { i += 1; tokens.push(Token{kind:Tok::LBracket,line}); }
            b']' => { i += 1; tokens.push(Token{kind:Tok::RBracket,line}); }
            b'{' => { i += 1; tokens.push(Token{kind:Tok::LBrace,line}); }
            b'}' => { i += 1; tokens.push(Token{kind:Tok::RBrace,line}); }
            b',' => { i += 1; tokens.push(Token{kind:Tok::Comma,line}); }
            b';' => { i += 1; tokens.push(Token{kind:Tok::Semi,line}); }
            _ => { i += 1; }
        }
    }
    tokens.push(Token { kind: Tok::Eof, line });
    tokens
}

// ==================== AST ====================

#[derive(Clone)]
struct Expr { kind: ExprKind, line: usize }

#[derive(Clone)]
enum ExprKind {
    Int(i64), Str(String), Bool(bool), Nil,
    Ident(String),
    Neg(Box<Expr>),
    Not(Box<Expr>),
    Bin(BinOp, Box<Expr>, Box<Expr>),
    Index(Box<Expr>, Box<Expr>),
    Call(Box<Expr>, Vec<Expr>),
    ListLit(Vec<Expr>),
    FnLit(Vec<String>, Vec<Stmt>),
}

#[derive(Clone, Copy, PartialEq)]
enum BinOp { Add, Sub, Mul, Div, Mod, Eq, Ne, Lt, Le, Gt, Ge, And, Or }

#[derive(Clone)]
struct Stmt { kind: StmtKind, line: usize }

#[derive(Clone)]
enum StmtKind {
    Let(String, Expr),
    FnDecl(String, Vec<String>, Vec<Stmt>),
    If(Expr, Vec<Stmt>, Option<ElseBr>),
    While(Expr, Vec<Stmt>),
    For(String, Expr, Vec<Stmt>),
    Return(Option<Expr>),
    Break, Continue,
    Assign(String, Expr),
    IndexAssign(Expr, Expr, Expr),
    ExprStmt(Expr),
}

#[derive(Clone)]
enum ElseBr { Block(Vec<Stmt>), IfStmt(Box<Stmt>) }

// ==================== PARSER ====================

struct Parser { t: Vec<Token>, p: usize }

impl Parser {
    fn new(t: Vec<Token>) -> Self { Parser { t, p: 0 } }
    fn peek(&self) -> &Tok { &self.t[self.p].kind }
    fn peek_line(&self) -> usize { self.t[self.p].line }
    fn advance(&mut self) -> &Token { let t = &self.t[self.p]; self.p += 1; t }
    fn expect(&mut self, k: &Tok) { if self.peek() != k { panic!("expected {:?}", k); } self.p += 1; }
    fn at(&self, k: &Tok) -> bool { self.peek() == k }

    fn parse_program(&mut self) -> Vec<Stmt> {
        let mut stmts = Vec::new();
        while !self.at(&Tok::Eof) { stmts.push(self.parse_stmt()); }
        stmts
    }

    fn parse_block(&mut self) -> Vec<Stmt> {
        self.expect(&Tok::LBrace);
        let mut stmts = Vec::new();
        while !self.at(&Tok::RBrace) && !self.at(&Tok::Eof) { stmts.push(self.parse_stmt()); }
        self.expect(&Tok::RBrace);
        stmts
    }

    fn parse_params(&mut self) -> Vec<String> {
        let mut ps = Vec::new();
        if !self.at(&Tok::RParen) {
            loop {
                if let Tok::Ident(s) = self.advance().kind.clone() { ps.push(s); } else { panic!("expected ident"); }
                if self.at(&Tok::Comma) { self.p += 1; } else { break; }
            }
        }
        ps
    }

    fn parse_stmt(&mut self) -> Stmt {
        let line = self.peek_line();
        match self.peek().clone() {
            Tok::Let => {
                self.p += 1;
                let name = self.expect_ident();
                self.expect(&Tok::Assign);
                let e = self.parse_expr();
                self.expect(&Tok::Semi);
                Stmt { kind: StmtKind::Let(name, e), line }
            }
            Tok::Fn => {
                self.p += 1;
                let name = self.expect_ident();
                self.expect(&Tok::LParen);
                let params = self.parse_params();
                self.expect(&Tok::RParen);
                let body = self.parse_block();
                Stmt { kind: StmtKind::FnDecl(name, params, body), line }
            }
            Tok::If => { self.parse_if() }
            Tok::While => {
                self.p += 1;
                let cond = self.parse_expr();
                let body = self.parse_block();
                Stmt { kind: StmtKind::While(cond, body), line }
            }
            Tok::For => {
                self.p += 1;
                let var = self.expect_ident();
                self.expect(&Tok::In);
                let e = self.parse_expr();
                let body = self.parse_block();
                Stmt { kind: StmtKind::For(var, e, body), line }
            }
            Tok::Return => {
                self.p += 1;
                let e = if self.at(&Tok::Semi) { None } else { Some(self.parse_expr()) };
                self.expect(&Tok::Semi);
                Stmt { kind: StmtKind::Return(e), line }
            }
            Tok::Break => { self.p += 1; self.expect(&Tok::Semi); Stmt { kind: StmtKind::Break, line } }
            Tok::Continue => { self.p += 1; self.expect(&Tok::Semi); Stmt { kind: StmtKind::Continue, line } }
            Tok::Ident(ref name) => {
                let name = name.clone();
                self.p += 1;
                if self.at(&Tok::Assign) {
                    self.p += 1;
                    let e = self.parse_expr();
                    self.expect(&Tok::Semi);
                    Stmt { kind: StmtKind::Assign(name, e), line }
                } else {
                    // It's an expression statement starting with an identifier
                    // We need to continue parsing as postfix
                    let mut expr = Expr { kind: ExprKind::Ident(name), line };
                    expr = self.parse_postfix_rest(expr);
                    if self.at(&Tok::Assign) {
                        self.p += 1;
                        let val = self.parse_expr();
                        self.expect(&Tok::Semi);
                        if let ExprKind::Index(obj, idx) = expr.kind {
                            Stmt { kind: StmtKind::IndexAssign(*obj, *idx, val), line }
                        } else {
                            panic!("invalid assignment target");
                        }
                    } else {
                        self.expect(&Tok::Semi);
                        Stmt { kind: StmtKind::ExprStmt(expr), line }
                    }
                }
            }
            _ => {
                let e = self.parse_expr();
                if self.at(&Tok::Assign) {
                    self.p += 1;
                    let val = self.parse_expr();
                    self.expect(&Tok::Semi);
                    if let ExprKind::Index(obj, idx) = e.kind {
                        Stmt { kind: StmtKind::IndexAssign(*obj, *idx, val), line }
                    } else {
                        panic!("invalid assignment target");
                    }
                } else {
                    self.expect(&Tok::Semi);
                    Stmt { kind: StmtKind::ExprStmt(e), line }
                }
            }
        }
    }

    fn parse_if(&mut self) -> Stmt {
        let line = self.peek_line();
        self.p += 1; // if
        let cond = self.parse_expr();
        let body = self.parse_block();
        let els = if self.at(&Tok::Else) {
            self.p += 1;
            if self.at(&Tok::If) {
                Some(ElseBr::IfStmt(Box::new(self.parse_if())))
            } else {
                Some(ElseBr::Block(self.parse_block()))
            }
        } else { None };
        Stmt { kind: StmtKind::If(cond, body, els), line }
    }

    fn expect_ident(&mut self) -> String {
        if let Tok::Ident(s) = self.advance().kind.clone() { s } else { panic!("expected ident"); }
    }

    fn parse_postfix_rest(&mut self, mut expr: Expr) -> Expr {
        loop {
            let line = self.peek_line();
            if self.at(&Tok::LParen) {
                self.p += 1;
                let mut args = Vec::new();
                if !self.at(&Tok::RParen) {
                    loop {
                        args.push(self.parse_expr());
                        if self.at(&Tok::Comma) { self.p += 1; } else { break; }
                    }
                }
                self.expect(&Tok::RParen);
                expr = Expr { kind: ExprKind::Call(Box::new(expr), args), line };
            } else if self.at(&Tok::LBracket) {
                self.p += 1;
                let idx = self.parse_expr();
                self.expect(&Tok::RBracket);
                expr = Expr { kind: ExprKind::Index(Box::new(expr), Box::new(idx)), line };
            } else { break; }
        }
        expr
    }

    fn parse_expr(&mut self) -> Expr { self.parse_or() }

    fn parse_or(&mut self) -> Expr {
        let mut left = self.parse_and();
        while self.at(&Tok::Or) {
            let line = self.peek_line();
            self.p += 1;
            let right = self.parse_and();
            left = Expr { kind: ExprKind::Bin(BinOp::Or, Box::new(left), Box::new(right)), line };
        }
        left
    }

    fn parse_and(&mut self) -> Expr {
        let mut left = self.parse_not();
        while self.at(&Tok::And) {
            let line = self.peek_line();
            self.p += 1;
            let right = self.parse_not();
            left = Expr { kind: ExprKind::Bin(BinOp::And, Box::new(left), Box::new(right)), line };
        }
        left
    }

    fn parse_not(&mut self) -> Expr {
        if self.at(&Tok::Not) {
            let line = self.peek_line();
            self.p += 1;
            let e = self.parse_not();
            Expr { kind: ExprKind::Not(Box::new(e)), line }
        } else {
            self.parse_comparison()
        }
    }

    fn parse_comparison(&mut self) -> Expr {
        let mut left = self.parse_addition();
        loop {
            let op = match self.peek() {
                Tok::Eq => BinOp::Eq, Tok::Neq => BinOp::Ne,
                Tok::Lt => BinOp::Lt, Tok::Le => BinOp::Le,
                Tok::Gt => BinOp::Gt, Tok::Ge => BinOp::Ge,
                _ => break,
            };
            let line = self.peek_line();
            self.p += 1;
            let right = self.parse_addition();
            left = Expr { kind: ExprKind::Bin(op, Box::new(left), Box::new(right)), line };
        }
        left
    }

    fn parse_addition(&mut self) -> Expr {
        let mut left = self.parse_multiplication();
        loop {
            let op = match self.peek() {
                Tok::Plus => BinOp::Add, Tok::Minus => BinOp::Sub,
                _ => break,
            };
            let line = self.peek_line();
            self.p += 1;
            let right = self.parse_multiplication();
            left = Expr { kind: ExprKind::Bin(op, Box::new(left), Box::new(right)), line };
        }
        left
    }

    fn parse_multiplication(&mut self) -> Expr {
        let mut left = self.parse_unary();
        loop {
            let op = match self.peek() {
                Tok::Star => BinOp::Mul, Tok::Slash => BinOp::Div, Tok::Percent => BinOp::Mod,
                _ => break,
            };
            let line = self.peek_line();
            self.p += 1;
            let right = self.parse_unary();
            left = Expr { kind: ExprKind::Bin(op, Box::new(left), Box::new(right)), line };
        }
        left
    }

    fn parse_unary(&mut self) -> Expr {
        if self.at(&Tok::Minus) {
            let line = self.peek_line();
            self.p += 1;
            let e = self.parse_unary();
            Expr { kind: ExprKind::Neg(Box::new(e)), line }
        } else {
            self.parse_postfix()
        }
    }

    fn parse_postfix(&mut self) -> Expr {
        let expr = self.parse_primary();
        self.parse_postfix_rest(expr)
    }

    fn parse_primary(&mut self) -> Expr {
        let line = self.peek_line();
        match self.peek().clone() {
            Tok::Int(n) => { self.p += 1; Expr { kind: ExprKind::Int(n), line } }
            Tok::Str(s) => { self.p += 1; Expr { kind: ExprKind::Str(s), line } }
            Tok::True => { self.p += 1; Expr { kind: ExprKind::Bool(true), line } }
            Tok::False => { self.p += 1; Expr { kind: ExprKind::Bool(false), line } }
            Tok::Nil => { self.p += 1; Expr { kind: ExprKind::Nil, line } }
            Tok::Ident(s) => { self.p += 1; Expr { kind: ExprKind::Ident(s), line } }
            Tok::LParen => {
                self.p += 1;
                let e = self.parse_expr();
                self.expect(&Tok::RParen);
                e
            }
            Tok::LBracket => {
                self.p += 1;
                let mut elems = Vec::new();
                if !self.at(&Tok::RBracket) {
                    loop {
                        elems.push(self.parse_expr());
                        if self.at(&Tok::Comma) { self.p += 1; } else { break; }
                    }
                }
                self.expect(&Tok::RBracket);
                Expr { kind: ExprKind::ListLit(elems), line }
            }
            Tok::Fn => {
                self.p += 1;
                self.expect(&Tok::LParen);
                let params = self.parse_params();
                self.expect(&Tok::RParen);
                let body = self.parse_block();
                Expr { kind: ExprKind::FnLit(params, body), line }
            }
            _ => panic!("unexpected token {:?}", self.peek()),
        }
    }
}

// ==================== VALUES ====================

#[derive(Clone)]
enum Value {
    Int(i64),
    Bool(bool),
    Str(Rc<String>),
    List(Rc<RefCell<Vec<Value>>>),
    Func(Rc<Func>),
    Nil,
}

struct Func {
    params: Vec<String>,
    body: Vec<Stmt>,
    captured: Rc<RefCell<Scope>>,
    builtin: Option<Builtin>,
}

#[derive(Clone, Copy)]
enum Builtin { Print, BuiltinStr, BuiltinType, BuiltinLen, BuiltinPush, BuiltinPop, BuiltinRange, BuiltinSlice }

struct Scope {
    vars: HashMap<String, Value>,
    parent: Option<Rc<RefCell<Scope>>>,
}

impl Scope {
    fn new(parent: Option<Rc<RefCell<Scope>>>) -> Rc<RefCell<Scope>> {
        Rc::new(RefCell::new(Scope { vars: HashMap::new(), parent }))
    }
    fn lookup(&self, name: &str) -> Option<&Value> {
        if let Some(v) = self.vars.get(name) { return Some(v); }
        if let Some(ref p) = self.parent { return p.borrow().lookup(name); }
        None
    }
    fn assign(&mut self, name: &str, val: Value) -> bool {
        if self.vars.contains_key(name) { self.vars.insert(name.to_string(), val); return true; }
        if let Some(ref p) = self.parent.clone() {
            if p.borrow_mut().assign(name, val) { return true; }
        }
        false
    }
}

// ==================== ERROR / FLOW ====================

struct RtError { line: usize, msg: String }
type Result<T> = std::result::Result<T, RtError>;

#[derive(Clone)]
enum Flow { Normal, Break, Continue, Return(Value) }

// ==================== INTERPRETER ====================

struct Interp {
    output: String,
}

fn type_name(v: &Value) -> &'static str {
    match v {
        Value::Int(_) => "int",
        Value::Bool(_) => "bool",
        Value::Str(_) => "string",
        Value::List(_) => "list",
        Value::Func(_) => "function",
        Value::Nil => "nil",
    }
}

fn is_truthy(v: &Value) -> bool {
    match v {
        Value::Bool(b) => *b,
        Value::Nil => false,
        Value::Int(n) => *n != 0,
        Value::Str(s) => !s.is_empty(),
        Value::List(l) => !l.borrow().is_empty(),
        Value::Func(_) => true,
    }
}

fn escape_str(s: &str) -> String {
    let mut r = String::new();
    for c in s.chars() {
        match c {
            '\\' => r.push_str("\\\\"),
            '"' => r.push_str("\\\""),
            '\n' => r.push_str("\\n"),
            '\t' => r.push_str("\\t"),
            _ => r.push(c),
        }
    }
    r
}

fn values_equal(a: &Value, b: &Value) -> bool {
    match (a, b) {
        (Value::Int(x), Value::Int(y)) => x == y,
        (Value::Bool(x), Value::Bool(y)) => x == y,
        (Value::Str(x), Value::Str(y)) => x == y,
        (Value::Nil, Value::Nil) => true,
        (Value::Func(x), Value::Func(y)) => Rc::ptr_eq(x, y),
        (Value::List(x), Value::List(y)) => {
            let xa = x.borrow();
            let ya = y.borrow();
            if xa.len() != ya.len() { return false; }
            for i in 0..xa.len() {
                if !values_equal(&xa[i], &ya[i]) { return false; }
            }
            true
        }
        _ => false,
    }
}

impl Interp {
    fn new() -> Self { Interp { output: String::new() } }

    fn display(&self, v: &Value) -> String {
        let mut seen = HashSet::new();
        self.display_inner(v, false, &mut seen)
    }

    fn display_inner(&self, v: &Value, in_list: bool, seen: &mut HashSet<usize>) -> String {
        match v {
            Value::Int(n) => n.to_string(),
            Value::Bool(b) => if *b { "true" } else { "false" }.to_string(),
            Value::Nil => "nil".to_string(),
            Value::Str(s) => {
                if in_list { format!("\"{}\"", escape_str(s)) } else { s.to_string() }
            }
            Value::Func(_) => "<fn>".to_string(),
            Value::List(l) => {
                let ptr = Rc::as_ptr(l) as usize;
                if seen.contains(&ptr) { return "[...]".to_string(); }
                seen.insert(ptr);
                let elems = l.borrow();
                let parts: Vec<String> = elems.iter().map(|e| self.display_inner(e, true, seen)).collect();
                seen.remove(&ptr);
                format!("[{}]", parts.join(", "))
            }
        }
    }

    fn lookup(&self, name: &str, scope: &Rc<RefCell<Scope>>, line: usize) -> Result<Value> {
        scope.borrow().lookup(name).cloned().ok_or(RtError {
            line, msg: format!("undefined variable {}", name),
        })
    }

    fn eval(&mut self, e: &Expr, scope: &Rc<RefCell<Scope>>) -> Result<Value> {
        match &e.kind {
            ExprKind::Int(n) => Ok(Value::Int(*n)),
            ExprKind::Str(s) => Ok(Value::Str(Rc::new(s.clone()))),
            ExprKind::Bool(b) => Ok(Value::Bool(*b)),
            ExprKind::Nil => Ok(Value::Nil),
            ExprKind::Ident(name) => self.lookup(name, scope, e.line),
            ExprKind::Neg(inner) => {
                let v = self.eval(inner, scope)?;
                match v {
                    Value::Int(n) => {
                        n.checked_neg().ok_or(RtError { line: e.line, msg: "integer overflow".into() })
                            .map(Value::Int)
                    }
                    other => Err(RtError { line: e.line, msg: format!("cannot apply - to {}", type_name(&other)) }),
                }
            }
            ExprKind::Not(inner) => {
                let v = self.eval(inner, scope)?;
                Ok(Value::Bool(!is_truthy(&v)))
            }
            ExprKind::Bin(op, left, right) => {
                match op {
                    BinOp::And => {
                        let l = self.eval(left, scope)?;
                        if !is_truthy(&l) { return Ok(l); }
                        self.eval(right, scope)
                    }
                    BinOp::Or => {
                        let l = self.eval(left, scope)?;
                        if is_truthy(&l) { return Ok(l); }
                        self.eval(right, scope)
                    }
                    _ => {
                        let l = self.eval(left, scope)?;
                        let r = self.eval(right, scope)?;
                        self.eval_binop(*op, l, r, e.line)
                    }
                }
            }
            ExprKind::Index(obj, idx) => {
                let obj_val = self.eval(obj, scope)?;
                let idx_val = self.eval(idx, scope)?;
                self.eval_index(&obj_val, &idx_val, e.line)
            }
            ExprKind::Call(callee, args) => {
                let callee_val = self.eval(callee, scope)?;
                let mut arg_vals = Vec::with_capacity(args.len());
                for a in args { arg_vals.push(self.eval(a, scope)?); }
                self.call_value(&callee_val, arg_vals, e.line)
            }
            ExprKind::ListLit(elems) => {
                let mut v = Vec::with_capacity(elems.len());
                for e in elems { v.push(self.eval(e, scope)?); }
                Ok(Value::List(Rc::new(RefCell::new(v))))
            }
            ExprKind::FnLit(params, body) => {
                Ok(Value::Func(Rc::new(Func {
                    params: params.clone(),
                    body: body.clone(),
                    captured: scope.clone(),
                    builtin: None,
                })))
            }
        }
    }

    fn eval_binop(&mut self, op: BinOp, l: Value, r: Value, line: usize) -> Result<Value> {
        match op {
            BinOp::Add => {
                match (&l, &r) {
                    (Value::Int(a), Value::Int(b)) => {
                        a.checked_add(*b).map(Value::Int)
                            .ok_or(RtError { line, msg: "integer overflow".into() })
                    }
                    (Value::Str(a), Value::Str(b)) => {
                        Ok(Value::Str(Rc::new(format!("{}{}", a, b))))
                    }
                    (Value::List(a), Value::List(b)) => {
                        let mut new_list = a.borrow().clone();
                        new_list.extend(b.borrow().iter().cloned());
                        Ok(Value::List(Rc::new(RefCell::new(new_list))))
                    }
                    _ => Err(RtError { line, msg: format!("cannot apply + to {} and {}", type_name(&l), type_name(&r)) }),
                }
            }
            BinOp::Sub | BinOp::Mul | BinOp::Div | BinOp::Mod => {
                let (a, b) = match (&l, &r) {
                    (Value::Int(a), Value::Int(b)) => (*a, *b),
                    _ => return Err(RtError { line, msg: format!("cannot apply {} to {} and {}", op_sym(op), type_name(&l), type_name(&r)) }),
                };
                match op {
                    BinOp::Sub => a.checked_sub(b).map(Value::Int).ok_or(RtError{line,msg:"integer overflow".into()}),
                    BinOp::Mul => a.checked_mul(b).map(Value::Int).ok_or(RtError{line,msg:"integer overflow".into()}),
                    BinOp::Div => {
                        if b == 0 { return Err(RtError{line,msg:"division by zero".into()}); }
                        a.checked_div(b).map(Value::Int).ok_or(RtError{line,msg:"integer overflow".into()})
                    }
                    BinOp::Mod => {
                        if b == 0 { return Err(RtError{line,msg:"division by zero".into()}); }
                        if b == -1 { return Ok(Value::Int(0)); }
                        a.checked_rem(b).map(Value::Int).ok_or(RtError{line,msg:"integer overflow".into()})
                    }
                    _ => unreachable!(),
                }
            }
            BinOp::Eq => Ok(Value::Bool(values_equal(&l, &r))),
            BinOp::Ne => Ok(Value::Bool(!values_equal(&l, &r))),
            BinOp::Lt | BinOp::Le | BinOp::Gt | BinOp::Ge => {
                match (&l, &r) {
                    (Value::Int(a), Value::Int(b)) => {
                        let res = match op {
                            BinOp::Lt => a < b, BinOp::Le => a <= b,
                            BinOp::Gt => a > b, BinOp::Ge => a >= b,
                            _ => unreachable!(),
                        };
                        Ok(Value::Bool(res))
                    }
                    (Value::Str(a), Value::Str(b)) => {
                        let res = match op {
                            BinOp::Lt => a.as_str() < b.as_str(), BinOp::Le => a.as_str() <= b.as_str(),
                            BinOp::Gt => a.as_str() > b.as_str(), BinOp::Ge => a.as_str() >= b.as_str(),
                            _ => unreachable!(),
                        };
                        Ok(Value::Bool(res))
                    }
                    _ => Err(RtError { line, msg: format!("cannot apply {} to {} and {}", op_sym(op), type_name(&l), type_name(&r)) }),
                }
            }
            _ => unreachable!(),
        }
    }

    fn eval_index(&mut self, obj: &Value, idx: &Value, line: usize) -> Result<Value> {
        match (obj, idx) {
            (Value::List(l), Value::Int(i)) => {
                let l = l.borrow();
                let i = *i as usize;
                if i >= l.len() {
                    return Err(RtError { line, msg: format!("index {} out of range for length {}", *i, l.len()) });
                }
                Ok(l[i].clone())
            }
            (Value::Str(s), Value::Int(i)) => {
                let chars: Vec<char> = s.chars().collect();
                let i = *i as usize;
                if i >= chars.len() {
                    return Err(RtError { line, msg: format!("index {} out of range for length {}", *i, chars.len()) });
                }
                Ok(Value::Str(Rc::new(chars[i].to_string())))
            }
            (Value::List(_), other) => {
                Err(RtError { line, msg: format!("cannot index list with {}", type_name(other)) })
            }
            (other, Value::Int(_)) => {
                Err(RtError { line, msg: format!("cannot index {} with int", type_name(other)) })
            }
            (obj, idx) => {
                Err(RtError { line, msg: format!("cannot index {} with {}", type_name(obj), type_name(idx)) })
            }
        }
    }

    fn call_value(&mut self, callee: &Value, args: Vec<Value>, line: usize) -> Result<Value> {
        match callee {
            Value::Func(f) => self.call_func(f, args, line),
            other => Err(RtError { line, msg: format!("cannot call {}", type_name(other)) }),
        }
    }

    fn call_func(&mut self, f: &Rc<Func>, args: Vec<Value>, line: usize) -> Result<Value> {
        if let Some(builtin) = &f.builtin {
            return self.call_builtin(*builtin, args, line);
        }
        if args.len() != f.params.len() {
            return Err(RtError { line, msg: format!("expected {} arguments, got {}", f.params.len(), args.len()) });
        }
        let call_scope = Scope::new(Some(f.captured.clone()));
        for (i, name) in f.params.iter().enumerate() {
            call_scope.borrow_mut().vars.insert(name.clone(), args[i].clone());
        }
        let flow = self.exec_block(&f.body, &call_scope)?;
        match flow {
            Flow::Return(v) => Ok(v),
            _ => Ok(Value::Nil),
        }
    }

    fn call_builtin(&mut self, b: Builtin, args: Vec<Value>, line: usize) -> Result<Value> {
        let arity_err = |n: usize| -> RtError {
            RtError { line, msg: format!("expected {} arguments, got {}", n, args.len()) }
        };
        let bad_arg = |name: &str| -> RtError {
            RtError { line, msg: format!("bad argument to {}", name) }
        };
        match b {
            Builtin::Print => {
                let parts: Vec<String> = args.iter().map(|v| self.display(v)).collect();
                self.output.push_str(&parts.join(" "));
                self.output.push('\n');
                Ok(Value::Nil)
            }
            Builtin::BuiltinStr => {
                if args.len() != 1 { return Err(arity_err(1)); }
                Ok(Value::Str(Rc::new(self.display(&args[0]))))
            }
            Builtin::BuiltinType => {
                if args.len() != 1 { return Err(arity_err(1)); }
                Ok(Value::Str(Rc::new(type_name(&args[0]).to_string())))
            }
            Builtin::BuiltinLen => {
                if args.len() != 1 { return Err(arity_err(1)); }
                match &args[0] {
                    Value::Str(s) => Ok(Value::Int(s.chars().count() as i64)),
                    Value::List(l) => Ok(Value::Int(l.borrow().len() as i64)),
                    _ => Err(bad_arg("len")),
                }
            }
            Builtin::BuiltinPush => {
                if args.len() != 2 { return Err(arity_err(2)); }
                match &args[0] {
                    Value::List(l) => { l.borrow_mut().push(args[1].clone()); Ok(Value::Nil) }
                    _ => Err(bad_arg("push")),
                }
            }
            Builtin::BuiltinPop => {
                if args.len() != 1 { return Err(arity_err(1)); }
                match &args[0] {
                    Value::List(l) => {
                        let mut l = l.borrow_mut();
                        if l.is_empty() { return Err(bad_arg("pop")); }
                        Ok(l.pop().unwrap())
                    }
                    _ => Err(bad_arg("pop")),
                }
            }
            Builtin::BuiltinRange => {
                if args.len() != 2 { return Err(arity_err(2)); }
                let (a, b) = match (&args[0], &args[1]) {
                    (Value::Int(a), Value::Int(b)) => (*a, *b),
                    _ => return Err(bad_arg("range")),
                };
                let mut v = Vec::new();
                if a < b {
                    let mut i = a;
                    while i < b { v.push(Value::Int(i)); i += 1; }
                }
                Ok(Value::List(Rc::new(RefCell::new(v))))
            }
            Builtin::BuiltinSlice => {
                if args.len() != 3 { return Err(arity_err(3)); }
                let (a, b) = match (&args[1], &args[2]) {
                    (Value::Int(a), Value::Int(b)) => (*a, *b),
                    _ => return Err(bad_arg("slice")),
                };
                match &args[0] {
                    Value::Str(s) => {
                        let chars: Vec<char> = s.chars().collect();
                        if a < 0 || b < 0 || a > b || (b as usize) > chars.len() {
                            return Err(bad_arg("slice"));
                        }
                        let s2: String = chars[a as usize..b as usize].iter().collect();
                        Ok(Value::Str(Rc::new(s2)))
                    }
                    Value::List(l) => {
                        let l = l.borrow();
                        if a < 0 || b < 0 || a > b || (b as usize) > l.len() {
                            return Err(bad_arg("slice"));
                        }
                        let new_list = l[a as usize..b as usize].to_vec();
                        Ok(Value::List(Rc::new(RefCell::new(new_list))))
                    }
                    _ => Err(bad_arg("slice")),
                }
            }
        }
    }

    fn exec_block(&mut self, stmts: &[Stmt], scope: &Rc<RefCell<Scope>>) -> Result<Flow> {
        for s in stmts {
            let flow = self.exec_stmt(s, scope)?;
            if !matches!(flow, Flow::Normal) { return Ok(flow); }
        }
        Ok(Flow::Normal)
    }

    fn exec_stmt(&mut self, s: &Stmt, scope: &Rc<RefCell<Scope>>) -> Result<Flow> {
        match &s.kind {
            StmtKind::Let(name, expr) => {
                let val = self.eval(expr, scope)?;
                scope.borrow_mut().vars.insert(name.clone(), val);
                Ok(Flow::Normal)
            }
            StmtKind::FnDecl(name, params, body) => {
                let func = Value::Func(Rc::new(Func {
                    params: params.clone(),
                    body: body.clone(),
                    captured: scope.clone(),
                    builtin: None,
                }));
                scope.borrow_mut().vars.insert(name.clone(), func);
                Ok(Flow::Normal)
            }
            StmtKind::If(cond, then_body, else_br) => {
                let val = self.eval(cond, scope)?;
                if is_truthy(&val) {
                    let body_scope = Scope::new(Some(scope.clone()));
                    self.exec_block(then_body, &body_scope)
                } else {
                    match else_br {
                        Some(ElseBr::Block(body)) => {
                            let body_scope = Scope::new(Some(scope.clone()));
                            self.exec_block(body, &body_scope)
                        }
                        Some(ElseBr::IfStmt(stmt)) => {
                            self.exec_stmt(stmt, scope)
                        }
                        None => Ok(Flow::Normal),
                    }
                }
            }
            StmtKind::While(cond, body) => {
                loop {
                    let val = self.eval(cond, scope)?;
                    if !is_truthy(&val) { break; }
                    let body_scope = Scope::new(Some(scope.clone()));
                    let flow = self.exec_block(body, &body_scope)?;
                    match flow {
                        Flow::Break => break,
                        Flow::Return(v) => return Ok(Flow::Return(v)),
                        _ => {}
                    }
                }
                Ok(Flow::Normal)
            }
            StmtKind::For(var, expr, body) => {
                let list_val = self.eval(expr, scope)?;
                let list = match &list_val {
                    Value::List(l) => l.clone(),
                    other => return Err(RtError { line: s.line, msg: format!("cannot iterate {}", type_name(other)) }),
                };
                let mut i: usize = 0;
                loop {
                    let len = list.borrow().len();
                    if i >= len { break; }
                    let elem = list.borrow()[i].clone();
                    let body_scope = Scope::new(Some(scope.clone()));
                    body_scope.borrow_mut().vars.insert(var.clone(), elem);
                    let flow = self.exec_block(body, &body_scope)?;
                    match flow {
                        Flow::Break => break,
                        Flow::Return(v) => return Ok(Flow::Return(v)),
                        _ => {}
                    }
                    i += 1;
                }
                Ok(Flow::Normal)
            }
            StmtKind::Return(expr) => {
                let val = match expr {
                    Some(e) => self.eval(e, scope)?,
                    None => Value::Nil,
                };
                Ok(Flow::Return(val))
            }
            StmtKind::Break => Ok(Flow::Break),
            StmtKind::Continue => Ok(Flow::Continue),
            StmtKind::Assign(name, expr) => {
                let val = self.eval(expr, scope)?;
                if !scope.borrow_mut().assign(name, val) {
                    return Err(RtError { line: s.line, msg: format!("undefined variable {}", name) });
                }
                Ok(Flow::Normal)
            }
            StmtKind::IndexAssign(obj_expr, idx_expr, val_expr) => {
                let obj_val = self.eval(obj_expr, scope)?;
                let idx_val = self.eval(idx_expr, scope)?;
                let val = self.eval(val_expr, scope)?;
                match &obj_val {
                    Value::List(l) => {
                        match &idx_val {
                            Value::Int(i) => {
                                let i = *i;
                                let len = l.borrow().len();
                                if i < 0 || (i as usize) >= len {
                                    return Err(RtError { line: s.line, msg: format!("index {} out of range for length {}", i, len) });
                                }
                                l.borrow_mut()[i as usize] = val;
                            }
                            other => return Err(RtError { line: s.line, msg: format!("cannot index list with {}", type_name(other)) }),
                        }
                    }
                    other => return Err(RtError { line: s.line, msg: format!("cannot assign into {}", type_name(other)) }),
                }
                Ok(Flow::Normal)
            }
            StmtKind::ExprStmt(expr) => {
                self.eval(expr, scope)?;
                Ok(Flow::Normal)
            }
        }
    }
}

fn op_sym(op: BinOp) -> &'static str {
    match op {
        BinOp::Add => "+", BinOp::Sub => "-", BinOp::Mul => "*",
        BinOp::Div => "/", BinOp::Mod => "%",
        BinOp::Eq => "==", BinOp::Ne => "!=",
        BinOp::Lt => "<", BinOp::Le => "<=", BinOp::Gt => ">", BinOp::Ge => ">=",
        BinOp::And => "and", BinOp::Or => "or",
    }
}

// ==================== MAIN ====================

fn main() {
    let args: Vec<String> = std::env::args().collect();
    let dir = &args[1];
    let path = format!("{}/program.tern", dir);
    let src = std::fs::read_to_string(&path).unwrap();

    let tokens = lex(&src);
    let mut parser = Parser::new(tokens);
    let program = parser.parse_program();

    // Set up builtins scope
    let builtins_scope = Scope::new(None);
    {
        let mut bs = builtins_scope.borrow_mut();
        let mk_builtin = |b: Builtin, name: &str| -> (String, Value) {
            (name.to_string(), Value::Func(Rc::new(Func {
                params: vec![],
                body: vec![],
                captured: builtins_scope.clone(),
                builtin: Some(b),
            })))
        };
        bs.vars.insert("print".into(), mk_builtin(Builtin::Print, "print").1);
        bs.vars.insert("str".into(), mk_builtin(Builtin::BuiltinStr, "str").1);
        bs.vars.insert("type".into(), mk_builtin(Builtin::BuiltinType, "type").1);
        bs.vars.insert("len".into(), mk_builtin(Builtin::BuiltinLen, "len").1);
        bs.vars.insert("push".into(), mk_builtin(Builtin::BuiltinPush, "push").1);
        bs.vars.insert("pop".into(), mk_builtin(Builtin::BuiltinPop, "pop").1);
        bs.vars.insert("range".into(), mk_builtin(Builtin::BuiltinRange, "range").1);
        bs.vars.insert("slice".into(), mk_builtin(Builtin::BuiltinSlice, "slice").1);
    }

    let global_scope = Scope::new(Some(builtins_scope));
    let mut interp = Interp::new();

    match interp.exec_block(&program, &global_scope) {
        Ok(_) => {}
        Err(e) => {
            print!("{}", interp.output);
            println!("error at line {}: {}", e.line, e.msg);
            let _ = std::io::stdout().flush();
            process::exit(0);
        }
    }

    print!("{}", interp.output);
    let _ = std::io::stdout().flush();
    process::exit(0);
}

import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;
import java.util.zip.CRC32;

public class Main {

    static class Section {
        String path;
        String kind;
        List<Hunk> hunks = new ArrayList<>();
    }

    static class Hunk {
        int a, b, c, d;
        List<byte[]> oldLines = new ArrayList<>();
        List<byte[]> newLines = new ArrayList<>();
        boolean malformed;
    }

    public static void main(String[] args) throws Exception {
        String dir = args[0];
        byte[] diffBytes = Files.readAllBytes(Paths.get(dir, "changes.diff"));
        String diff = new String(diffBytes, StandardCharsets.ISO_8859_1);

        List<Section> sections = parseDiff(diff);
        sections.sort(Comparator.comparing(s -> s.path));

        StringBuilder out = new StringBuilder();
        for (Section sec : sections) {
            processSection(sec, dir, out);
        }
        System.out.print(out);
    }

    static List<String> splitLines(String s) {
        List<String> lines = new ArrayList<>();
        int start = 0;
        for (int i = 0; i < s.length(); i++) {
            if (s.charAt(i) == '\n') {
                lines.add(s.substring(start, i));
                start = i + 1;
            }
        }
        if (start < s.length()) {
            lines.add(s.substring(start));
        }
        return lines;
    }

    static List<Section> parseDiff(String diff) {
        List<String> lines = splitLines(diff);
        List<Section> sections = new ArrayList<>();
        int i = 0, n = lines.size();

        while (i < n) {
            String line = lines.get(i);
            if (!line.startsWith("diff --git a/")) {
                i++;
                continue;
            }

            String rest = line.substring("diff --git a/".length());
            int sp = rest.indexOf(' ');
            String path = rest.substring(0, sp);

            Section sec = new Section();
            sec.path = path;
            sec.kind = "modify";
            i++;

            while (i < n) {
                String h = lines.get(i);
                if (h.startsWith("--- ") || h.startsWith("@@ ") || h.startsWith("diff --git ")) break;
                if (h.startsWith("new file mode ")) sec.kind = "create";
                else if (h.startsWith("deleted file mode ")) sec.kind = "delete";
                i++;
            }

            if (i < n && lines.get(i).startsWith("--- ")) i++;
            if (i < n && lines.get(i).startsWith("+++ ")) i++;

            while (i < n && lines.get(i).startsWith("@@ ")) {
                Hunk hunk = new Hunk();
                try {
                    parseHunkHeader(lines.get(i), hunk);
                } catch (Exception e) {
                    hunk.malformed = true;
                }
                i++;

                List<String> body = new ArrayList<>();
                while (i < n && !lines.get(i).startsWith("@@ ") && !lines.get(i).startsWith("diff --git ")) {
                    if (!lines.get(i).isEmpty()) {
                        body.add(lines.get(i));
                    }
                    i++;
                }

                if (!hunk.malformed) {
                    for (int j = 0; j < body.size(); j++) {
                        String bl = body.get(j);
                        char marker = bl.charAt(0);
                        if (marker == '\\') continue;

                        String content = bl.substring(1);
                        boolean noNL = (j + 1 < body.size() && body.get(j + 1).charAt(0) == '\\');

                        byte[] lineBytes;
                        if (noNL) {
                            lineBytes = content.getBytes(StandardCharsets.ISO_8859_1);
                        } else {
                            lineBytes = (content + "\n").getBytes(StandardCharsets.ISO_8859_1);
                        }

                        if (marker == ' ') {
                            hunk.oldLines.add(lineBytes.clone());
                            hunk.newLines.add(lineBytes);
                        } else if (marker == '-') {
                            hunk.oldLines.add(lineBytes);
                        } else if (marker == '+') {
                            hunk.newLines.add(lineBytes);
                        }
                    }

                    if (hunk.oldLines.size() != hunk.b || hunk.newLines.size() != hunk.d) {
                        hunk.malformed = true;
                    }
                }

                sec.hunks.add(hunk);
            }

            sections.add(sec);
        }
        return sections;
    }

    static void parseHunkHeader(String line, Hunk hunk) {
        int end = line.indexOf(" @@", 3);
        if (end < 0) end = line.lastIndexOf("@@");
        String ranges = line.substring(3, end);

        int plusIdx = ranges.indexOf('+');
        String oldRange = ranges.substring(0, plusIdx).trim().substring(1);
        String newRange = ranges.substring(plusIdx + 1).trim();

        String[] ab = oldRange.split(",");
        hunk.a = Integer.parseInt(ab[0]);
        hunk.b = ab.length > 1 ? Integer.parseInt(ab[1]) : 1;

        String[] cd = newRange.split(",");
        hunk.c = Integer.parseInt(cd[0]);
        hunk.d = cd.length > 1 ? Integer.parseInt(cd[1]) : 1;
    }

    static List<byte[]> splitIntoLines(byte[] data) {
        List<byte[]> lines = new ArrayList<>();
        int start = 0;
        for (int i = 0; i < data.length; i++) {
            if (data[i] == '\n') {
                lines.add(Arrays.copyOfRange(data, start, i + 1));
                start = i + 1;
            }
        }
        if (start < data.length) {
            lines.add(Arrays.copyOfRange(data, start, data.length));
        }
        return lines;
    }

    static byte[] joinLines(List<byte[]> lines) {
        int total = 0;
        for (byte[] l : lines) total += l.length;
        byte[] result = new byte[total];
        int pos = 0;
        for (byte[] l : lines) {
            System.arraycopy(l, 0, result, pos, l.length);
            pos += l.length;
        }
        return result;
    }

    static boolean matchAt(List<byte[]> content, int p, List<byte[]> oldLines) {
        int start = p - 1;
        if (start < 0 || start + oldLines.size() > content.size()) return false;
        for (int i = 0; i < oldLines.size(); i++) {
            if (!Arrays.equals(content.get(start + i), oldLines.get(i))) return false;
        }
        return true;
    }

    static String formatOffset(int k) {
        if (k > 0) return "+" + k;
        return String.valueOf(k);
    }

    static void processSection(Section sec, String dir, StringBuilder out) throws Exception {
        Path filePath = Paths.get(dir, "tree", sec.path);

        if (sec.kind.equals("create")) {
            if (Files.exists(filePath)) {
                out.append(sec.path).append(": ").append(sec.kind).append("\n");
                out.append("  error: already exists\n");
                return;
            }
        } else {
            if (!Files.exists(filePath)) {
                out.append(sec.path).append(": ").append(sec.kind).append("\n");
                out.append("  error: not found\n");
                return;
            }
        }

        List<byte[]> content;
        if (sec.kind.equals("create")) {
            content = new ArrayList<>();
        } else {
            byte[] fileBytes = Files.readAllBytes(filePath);
            content = splitIntoLines(fileBytes);
        }

        int delta = 0;
        boolean allApplied = true;
        List<String> hunkResults = new ArrayList<>();

        for (int hi = 0; hi < sec.hunks.size(); hi++) {
            Hunk hunk = sec.hunks.get(hi);
            int hunkNum = hi + 1;

            if (hunk.malformed) {
                hunkResults.add("hunk " + hunkNum + ": malformed");
                allApplied = false;
                continue;
            }

            int P = hunk.a + delta;

            if (hunk.b == 0) {
                if (P >= 0 && P <= content.size()) {
                    content.addAll(P, hunk.newLines);
                    hunkResults.add("hunk " + hunkNum + ": applied at " + P + " (offset 0)");
                    delta += hunk.d - hunk.b;
                } else {
                    hunkResults.add("hunk " + hunkNum + ": rejected");
                    allApplied = false;
                }
            } else {
                int lineCount = content.size();
                int found = -1;

                for (int m = 0; ; m++) {
                    if (m == 0) {
                        if (P >= 1 && P + hunk.b - 1 <= lineCount) {
                            if (matchAt(content, P, hunk.oldLines)) {
                                found = P;
                                break;
                            }
                        }
                    } else {
                        int p1 = P - m;
                        if (p1 >= 1 && p1 + hunk.b - 1 <= lineCount) {
                            if (matchAt(content, p1, hunk.oldLines)) {
                                found = p1;
                                break;
                            }
                        }
                        int p2 = P + m;
                        if (p2 >= 1 && p2 + hunk.b - 1 <= lineCount) {
                            if (matchAt(content, p2, hunk.oldLines)) {
                                found = p2;
                                break;
                            }
                        }
                    }
                    if (m > 0 && P - m < 1 && P + m + hunk.b - 1 > lineCount) break;
                }

                if (found >= 0) {
                    int start = found - 1;
                    content.subList(start, start + hunk.b).clear();
                    content.addAll(start, hunk.newLines);
                    hunkResults.add("hunk " + hunkNum + ": applied at " + found + " (offset " + formatOffset(found - P) + ")");
                    delta += hunk.d - hunk.b;
                } else {
                    hunkResults.add("hunk " + hunkNum + ": rejected");
                    allApplied = false;
                }
            }
        }

        out.append(sec.path).append(": ").append(sec.kind).append("\n");
        for (String hr : hunkResults) {
            out.append("  ").append(hr).append("\n");
        }

        if (sec.kind.equals("delete") && allApplied && content.isEmpty()) {
            out.append("  result: deleted\n");
        } else {
            byte[] finalContent = joinLines(content);
            CRC32 crc = new CRC32();
            crc.update(finalContent);
            long crcVal = crc.getValue();
            out.append("  result: ").append(content.size()).append(" lines, crc32 ")
               .append(String.format("%08x", crcVal)).append("\n");
        }
    }
}

