                if m == 0x5C {
                    if j > 0 {
                        let pm = body[j - 1].0
                        if pm == 0x20 {
                            if !old.isEmpty && old.last!.last == 0x0A { old[old.count - 1] = Array(old[old.count - 1].dropLast()) }
                            if !new.isEmpty && new.last!.last == 0x0A { new[new.count - 1] = Array(new[new.count - 1].dropLast()) }
                        } else if pm == 0x2D {
                            if !old.isEmpty && old.last!.last == 0x0A { old[old.count - 1] = Array(old[old.count - 1].dropLast()) }
                        } else if pm == 0x2B {
                            if !new.isEmpty && new.last!.last == 0x0A { new[new.count - 1] = Array(new[new.count - 1].dropLast()) }
                        }
                    }
                } else if m == 0x20 {
                    old.append(content); new.append(content)
                } else if m == 0x2D {
                    old.append(content)
                } else if m == 0x2B {
                    new.append(content)
                }
            }
            let mal = (old.count != b || new.count != d)
            hunks.append(Hunk(a: a, b: b, c: c, d: d, oldLines: old, newLines: new, malformed: mal))
        }
        sections.append(Section(path: path, kind: kind, hunks: hunks))
    }
    return sections
}

func checkMatch(content: [[UInt8]], at p: Int, oldLines: [[UInt8]]) -> Bool {
    let si = p - 1
    if si < 0 || si + oldLines.count > content.count { return false }
    for i in 0..<oldLines.count {
        if content[si + i] != oldLines[i] { return false }
    }
    return true
}

let args = CommandLine.arguments
guard args.count >= 2 else { exit(1) }
let dir = args[1]
guard let diffData = FileManager.default.contents(atPath: dir + "/changes.diff") else { exit(1) }
let sections = parseDiff([UInt8](diffData))
let sorted = sections.sorted { Array($0.path.utf8) < Array($1.path.utf8) }
let treeDir = dir + "/tree"

var out: [String] = []
for sec in sorted {
    out.append("\(sec.path): \(sec.kind.rawValue)")
    let fp = treeDir + "/" + sec.path
    let exists = FileManager.default.fileExists(atPath: fp)
    if sec.kind == .create {
        if exists { out.append("  error: already exists"); continue }
    } else {
        if !exists { out.append("  error: not found"); continue }
    }
    var content: [[UInt8]]
    if sec.kind == .create {
        content = []
    } else {
        guard let fd = FileManager.default.contents(atPath: fp) else {
            out.append("  error: not found"); continue
        }
        content = splitLines([UInt8](fd))
    }
    var delta = 0
    var hunkResults: [(applied: Bool, offset: Int, position: Int, malformed: Bool)] = []
    for hunk in sec.hunks {
        if hunk.malformed {
            hunkResults.append((false, 0, 0, true))
            continue
        }
        let P = hunk.a + delta
        if hunk.b == 0 {
            if P >= 0 && P <= content.count {
                content.insert(contentsOf: hunk.newLines, at: P)
                hunkResults.append((true, 0, P, false))
                delta += hunk.d - hunk.b
            } else {
                hunkResults.append((false, 0, 0, false))
            }
        } else {
            let lc = content.count
            let minP = 1
            let maxP = lc - hunk.b + 1
            if minP > maxP {
                hunkResults.append((false, 0, 0, false))
                continue
            }
            var found = false
            var foundP = 0
            var k = 0
            while true {
                if k == 0 {
                    if P >= minP && P <= maxP && checkMatch(content: content, at: P, oldLines: hunk.oldLines) {
                        found = true; foundP = P; break
                    }
                } else {
                    let p1 = P - k
                    if p1 >= minP && p1 <= maxP && checkMatch(content: content, at: p1, oldLines: hunk.oldLines) {
                        found = true; foundP = p1; break
                    }
                    let p2 = P + k
                    if p2 >= minP && p2 <= maxP && checkMatch(content: content, at: p2, oldLines: hunk.oldLines) {
                        found = true; foundP = p2; break
                    }
                }
                if P - k < minP && P + k > maxP { break }
                k += 1
            }
            if found {
                let si = foundP - 1
                content.removeSubrange(si..<(si + hunk.b))
                content.insert(contentsOf: hunk.newLines, at: si)
                let off = foundP - P
                hunkResults.append((true, off, foundP, false))
                delta += hunk.d - hunk.b
            } else {
                hunkResults.append((false, 0, 0, false))
            }
        }
    }
    for (hi, hr) in hunkResults.enumerated() {
        let hn = hi + 1
        if hr.malformed {
            out.append("  hunk \(hn): malformed")
        } else if hr.applied {
            let os = hr.offset > 0 ? "+\(hr.offset)" : "\(hr.offset)"
            out.append("  hunk \(hn): applied at \(hr.position) (offset \(os))")
        } else {
            out.append("  hunk \(hn): rejected")
        }
    }
    if sec.kind == .delete {
        let allApplied = hunkResults.allSatisfy { $0.applied }
        if allApplied && content.isEmpty {
            out.append("  result: deleted")
        } else {
            let bytes = joinLines(content)
            let crc = crc32(bytes)
            out.append("  result: \(content.count) lines, crc32 \(String(format: "%08x", crc))")
        }
    } else {
        let bytes = joinLines(content)
        let crc = crc32(bytes)
        out.append("  result: \(content.count) lines, crc32 \(String(format: "%08x", crc))")
    }
}

if !out.isEmpty {
    print(out.joined(separator: "\n"))
}

import Foundation

func crc32(_ data: [UInt8]) -> UInt32 {
    var table = [UInt32](repeating: 0, count: 256)
    for i in 0..<256 {
        var c = UInt32(i)
        for _ in 0..<8 {
            if c & 1 != 0 { c = 0xEDB88320 ^ (c >> 1) } else { c = c >> 1 }
        }
        table[i] = c
    }
    var crc: UInt32 = 0xFFFFFFFF
    for byte in data {
        crc = table[Int((crc ^ UInt32(byte)) & 0xFF)] ^ (crc >> 8)
    }
    return crc ^ 0xFFFFFFFF
}

func splitLines(_ data: [UInt8]) -> [[UInt8]] {
    if data.isEmpty { return [] }
    var lines: [[UInt8]] = []
    var start = 0
    for i in 0..<data.count {
        if data[i] == 0x0A {
            lines.append(Array(data[start...i]))
            start = i + 1
        }
    }
    if start < data.count {
        lines.append(Array(data[start..<data.count]))
    }
    return lines
}

func joinLines(_ lines: [[UInt8]]) -> [UInt8] {
    var r: [UInt8] = []
    for l in lines { r.append(contentsOf: l) }
    return r
}

func ls(_ line: [UInt8]) -> String {
    return String(bytes: line, encoding: .isoLatin1) ?? ""
}

func parseHunkHeader(_ line: [UInt8]) -> (a: Int, b: Int, c: Int, d: Int)? {
    guard line.count >= 4,
          line[0] == 0x40, line[1] == 0x40, line[2] == 0x20, line[3] == 0x2D else { return nil }
    var i = 4
    func ri() -> Int? {
        let s = i
        while i < line.count && line[i] >= 0x30 && line[i] <= 0x39 { i += 1 }
        if i == s { return nil }
        var v = 0
        for j in s..<i { v = v * 10 + Int(line[j] - 0x30) }
        return v
    }
    guard let a = ri() else { return nil }
    var b = 1
    if i < line.count && line[i] == 0x2C { i += 1; guard let v = ri() else { return nil }; b = v }
    guard i < line.count, line[i] == 0x20 else { return nil }; i += 1
    guard i < line.count, line[i] == 0x2B else { return nil }; i += 1
    guard let c = ri() else { return nil }
    var d = 1
    if i < line.count && line[i] == 0x2C { i += 1; guard let v = ri() else { return nil }; d = v }
    guard i < line.count, line[i] == 0x20 else { return nil }; i += 1
    guard i + 1 < line.count, line[i] == 0x40, line[i+1] == 0x40 else { return nil }
    return (a, b, c, d)
}

enum SK: String {
    case create
    case delete
    case modify
}

struct Hunk {
    let a: Int, b: Int, c: Int, d: Int
    let oldLines: [[UInt8]], newLines: [[UInt8]]
    let malformed: Bool
}

struct Section {
    let path: String
    let kind: SK
    let hunks: [Hunk]
}

func parseDiff(_ data: [UInt8]) -> [Section] {
    let lines = splitLines(data)
    var sections: [Section] = []
    var i = 0
    while i < lines.count {
        let s = ls(lines[i])
        guard s.hasPrefix("diff --git a/") else { i += 1; continue }
        let rest = String(s.dropFirst("diff --git a/".count))
        guard let sp = rest.firstIndex(of: " ") else { i += 1; continue }
        let path = String(rest[..<sp])
        i += 1
        var kind: SK = .modify
        while i < lines.count {
            let hs = ls(lines[i])
            if hs.hasPrefix("new file mode ") { kind = .create; i += 1 }
            else if hs.hasPrefix("deleted file mode ") { kind = .delete; i += 1 }
            else if hs.hasPrefix("index ") { i += 1 }
            else if hs.hasPrefix("--- ") || hs.hasPrefix("+++ ") { i += 1 }
            else { break }
        }
        var hunks: [Hunk] = []
        while i < lines.count {
            let hs = ls(lines[i])
            if hs.hasPrefix("diff --git ") { break }
            if !hs.hasPrefix("@@ ") { i += 1; continue }
            guard let (a, b, c, d) = parseHunkHeader(lines[i]) else { i += 1; continue }
            i += 1
            var body: [(UInt8, [UInt8])] = []
            while i < lines.count {
                let bl = lines[i]
                let bs = ls(bl)
                if bs.hasPrefix("@@ ") || bs.hasPrefix("diff --git ") { break }
                if bl.isEmpty { i += 1; continue }
                body.append((bl[0], Array(bl.dropFirst())))
                i += 1
            }
            var old: [[UInt8]] = []
            var new: [[UInt8]] = []
            for j in 0..<body.count {
                let (m, content) = body[j]
                if m == 0x5C {
                    if j > 0 {
                        let pm = body[j - 1].0
                        if pm == 0x20 {
                            if !old.isEmpty && old.last!.last == 0x0A { old[old.count - 1] = Array(old[old.count - 1].dropLast()) }
                            if !new.isEmpty && new.last!.last == 0x0A { new[new.count - 1] = Array(new[new.count - 1].dropLast()) }
                        } else if pm == 0x2D {
                            if !old.isEmpty && old.last!.last == 0x0A { old[old.count - 1] = Array(old[old.count - 1].dropLast()) }
                        } else if pm == 0x2B {
                            if !new.isEmpty && new.last!.last == 0x0A { new[new.count - 1] = Array(new[new.count - 1].dropLast()) }
                        }
                    }
                } else if m == 0x20 {
                    old.append(content); new.append(content)
                } else if m == 0x2D {
                    old.append(content)
                } else if m == 0x2B {
                    new.append(content)
                }
            }
            let mal = (old.count != b || new.count != d)
            hunks.append(Hunk(a: a, b: b, c: c, d: d, oldLines: old, newLines: new, malformed: mal))
        }
        sections.append(Section(path: path, kind: kind, hunks: hunks))
    }
    return sections
}

func checkMatch(content: [[UInt8]], at p: Int, oldLines: [[UInt8]]) -> Bool {
    let si = p - 1
    if si < 0 || si + oldLines.count > content.count { return false }
    for i in 0..<oldLines.count {
        if content[si + i] != oldLines[i] { return false }
    }
    return true
}

