    constructor(data: Uint8Array, pos: number) {
        this.data = data;
        this.pos = pos;
        this.bitPos = 0;
    }
    readBit(): number {
        const bit = (this.data[this.pos] >>> this.bitPos) & 1;
        this.bitPos++;
        if (this.bitPos === 8) { this.bitPos = 0; this.pos++; }
        return bit;
    }
    readBits(n: number): number {
        let val = 0;
        for (let i = 0; i < n; i++) {
