        let x1 = pts[1][0], y1 = pts[1][1]
        let x2 = pts[2][0], y2 = pts[2][1]
        let e0 = (x1 - x0) * (y - y0) - (y1 - y0) * (x - x0)
        let e1 = (x2 - x1) * (y - y1) - (y2 - y1) * (x - x1)
        let e2 = (x0 - x2) * (y - y2) - (y0 - y2) * (x - x2)
        return (e0 >= 0 && e1 >= 0 && e2 >= 0) || (e0 <= 0 && e1 <= 0 && e2 <= 0)
    case "line":
