import Foundation

// CRC32 table
var crcTable: [UInt32] = []
func initCRC() {
    crcTable = [UInt32](repeating: 0, count: 256)
    for n in 0..<256 {
        var c = UInt32(n)
        for _ in 0..<8 {
            if c & 1 != 0 {
                c = 0xEDB88320 ^ (c >> 1)
            } else {
                c = c >> 1
            }
        }
        crcTable[n] = c
    }
}

func crc32(_ data: [UInt8]) -> UInt32 {
    var c: UInt32 = 0xFFFFFFFF
    for b in data {
        c = crcTable[Int((c ^ UInt32(b)) & 0xFF)] ^ (c >> 8)
    }
    return c ^ 0xFFFFFFFF
}

func adler32(_ data: [UInt8]) -> UInt32 {
    var s1: UInt32 = 1
    var s2: UInt32 = 0
    for b in data {
        s1 = (s1 + UInt32(b)) % 65521
        s2 = (s2 + s1) % 65521
    }
    return (s2 << 16) | s1
}

func makePNG(width: Int, height: Int, pixels: [UInt8]) -> [UInt8] {
    var rawData: [UInt8] = []
    rawData.reserveCapacity(height * (1 + width * 3))
    for y in 0..<height {
        rawData.append(0)
        let rowStart = y * width * 3
        for i in 0..<(width * 3) {
            rawData.append(pixels[rowStart + i])
        }
    }

    // zlib stream with stored DEFLATE blocks
    var zlibData: [UInt8] = []
    zlibData.append(0x78)
    zlibData.append(0x01)

    let maxBlock = 65535
    var offset = 0
    while offset < rawData.count {
        let remaining = rawData.count - offset
        let blockLen = min(remaining, maxBlock)
        let isLast = (offset + blockLen >= rawData.count)

        zlibData.append(isLast ? 1 : 0)
        let len = UInt16(blockLen)
        let nlen = ~len
        zlibData.append(UInt8(len & 0xFF))
        zlibData.append(UInt8((len >> 8) & 0xFF))
        zlibData.append(UInt8(nlen & 0xFF))
        zlibData.append(UInt8((nlen >> 8) & 0xFF))

        for i in 0..<blockLen {
            zlibData.append(rawData[offset + i])
        }
        offset += blockLen
    }

    let adler = adler32(rawData)
    zlibData.append(UInt8((adler >> 24) & 0xFF))
    zlibData.append(UInt8((adler >> 16) & 0xFF))
    zlibData.append(UInt8((adler >> 8) & 0xFF))
    zlibData.append(UInt8(adler & 0xFF))

    // Build PNG
    var png: [UInt8] = []
    let sig: [UInt8] = [137, 80, 78, 71, 13, 10, 26, 10]
    png.append(contentsOf: sig)

    func addChunk(_ type: String, _ data: [UInt8]) {
        let len = UInt32(data.count)
        png.append(UInt8((len >> 24) & 0xFF))
        png.append(UInt8((len >> 16) & 0xFF))
        png.append(UInt8((len >> 8) & 0xFF))
        png.append(UInt8(len & 0xFF))
        let typeBytes = Array(type.utf8)
        png.append(contentsOf: typeBytes)
        png.append(contentsOf: data)
        var crcData: [UInt8] = []
        crcData.append(contentsOf: typeBytes)
        crcData.append(contentsOf: data)
        let crc = crc32(crcData)
        png.append(UInt8((crc >> 24) & 0xFF))
        png.append(UInt8((crc >> 16) & 0xFF))
        png.append(UInt8((crc >> 8) & 0xFF))
        png.append(UInt8(crc & 0xFF))
    }

    var ihdr: [UInt8] = []
    let w = UInt32(width)
    let h = UInt32(height)
    ihdr.append(UInt8((w >> 24) & 0xFF))
    ihdr.append(UInt8((w >> 16) & 0xFF))
    ihdr.append(UInt8((w >> 8) & 0xFF))
    ihdr.append(UInt8(w & 0xFF))
    ihdr.append(UInt8((h >> 24) & 0xFF))
    ihdr.append(UInt8((h >> 16) & 0xFF))
    ihdr.append(UInt8((h >> 8) & 0xFF))
    ihdr.append(UInt8(h & 0xFF))
    ihdr.append(8)  // bit depth
    ihdr.append(2)  // color type RGB
    ihdr.append(0)  // compression
    ihdr.append(0)  // filter
    ihdr.append(0)  // interlace
    addChunk("IHDR", ihdr)
    addChunk("IDAT", zlibData)
    addChunk("IEND", [])
    return png
}

