      result.has.add(fieldNum);
      if (isMessageField(fd.type, schema)) {
        if (wireType !== 2) { pos = skipField(data, pos, wireType, fieldNum); continue; }
        const [len, p3] = readVarint(data, pos); pos = p3;
        const msgData = data.subarray(pos, pos + Number(len)); pos += Number(len);
        const existing = result.fields.get(fieldNum);
        if (existing && cur === fieldNum) {
