}

function decodeMapEntry(data: Uint8Array, fd: FieldDef, schema: Parser): { key: any; value: any } {
  let key: any = fd.mapKey === 'string' ? '' : 0;
  let value: any = getDefaultScalar(fd.mapValue!, schema);
  let pos = 0;
  while (pos < data.length) {
    const [keyVarint, p2] = readVarint(data, pos); pos = p2;
    const fn = Number(keyVarint >> 3n);
    const wt = Number(keyVarint & 7n);
    if (fn === 1) {
      const [k, np] = decodeScalar(data, pos, wt, fd.mapKey!, schema);
      pos = np; key = k;
    } else if (fn === 2) {
      if (isMessageField(fd.mapValue!, schema)) {
        if (wt === 2) {
          const [len, p3] = readVarint(data, pos); pos = p3;
          const msgData = data.subarray(pos, pos + Number(len)); pos += Number(len);
          value = decodeMessage(msgData, schema.messages.get(fd.mapValue!)!, schema);
        } else { pos = skipField(data, pos, wt, fn); }
      } else {
        const [v, np] = decodeScalar(data, pos, wt, fd.mapValue!, schema);
        pos = np; value = v;
      }
    } else { pos = skipField(data, pos, wt, fn); }
  }
  return { key, value };
}

function getDefaultScalar(type: string, schema: Parser): any {
  if (schema.enums.has(type)) return 0;
  if (type === 'bool') return false;
  if (type === 'string') return '';
  if (type === 'bytes') return new Uint8Array(0);
  if (type === 'int64' || type === 'uint64' || type === 'sint64' || type === 'fixed64' || type === 'sfixed64') return 0n;
  return 0;
}

// ==================== SERIALIZER ====================
function toCamelCase(name: string): string {
  let result = ''; let cap = false;
  for (let i = 0; i < name.length; i++) {
    if (name[i] === '_') { cap = true; }
    else {
      if (cap && name[i] >= 'a' && name[i] <= 'z') result += name[i].toUpperCase();
      else result += name[i];
      cap = false;
    }
  }
  return result;
}

function escapeJson(s: string): string {
  let r = '"';
  for (let i = 0; i < s.length; i++) {
    const c = s.charCodeAt(i);
    if (c === 34) r += '\\"';
    else if (c === 92) r += '\\\\';
    else if (c === 8) r += '\\b';
    else if (c === 9) r += '\\t';
    else if (c === 10) r += '\\n';
    else if (c === 12) r += '\\f';
    else if (c === 13) r += '\\r';
    else if (c < 32) r += '\\u00' + c.toString(16).padStart(2, '0');
    else r += s[i];
  }
  return r + '"';
}

const B64CH = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
function base64(data: Uint8Array): string {
  let r = ''; let i = 0;
  while (i < data.length) {
    const b0 = data[i++];
    const b1 = i < data.length ? data[i++] : -1;
    const b2 = i < data.length ? data[i++] : -1;
    r += B64CH[b0 >> 2];
    if (b1 === -1) { r += B64CH[(b0 & 3) << 4] + '=='; }
    else if (b2 === -1) { r += B64CH[((b0 & 3) << 4) | (b1 >> 4)] + B64CH[(b1 & 15) << 2] + '='; }
    else { r += B64CH[((b0 & 3) << 4) | (b1 >> 4)] + B64CH[((b1 & 15) << 2) | (b2 >> 6)] + B64CH[b2 & 63]; }
  }
  return r;
}

function isDefault(val: any, type: string, schema: Parser): boolean {
  if (schema.enums.has(type)) return val === 0;
  if (type === 'bool') return val === false;
  if (type === 'string') return val === '';
  if (type === 'bytes') return (val as Uint8Array).length === 0;
  if (typeof val === 'bigint') return val === 0n;
  if (typeof val === 'number') return val === 0;
  return false;
}

function serializeScalar(val: any, type: string, schema: Parser): string {
  if (schema.enums.has(type)) {
    const ed = schema.enums.get(type)!;
    const name = ed.values.get(val as number);
    if (name !== undefined) return `"${name}"`;
    return String(val);
  }
  if (type === 'bool') return val ? 'true' : 'false';
  if (type === 'string') return escapeJson(val as string);
  if (type === 'bytes') return `"${base64(val as Uint8Array)}"`;
  if (type === 'int64' || type === 'uint64' || type === 'sint64' || type === 'fixed64' || type === 'sfixed64') {
    return `"${(val as bigint).toString()}"`;
  }
  return String(val);
}

function serializeMsg(msg: DecodedMsg, msgDef: MessageDef, schema: Parser): string {
  const parts: string[] = [];
  const fieldNums = Array.from(msgDef.fields.keys()).sort((a, b) => a - b);
  for (const fn of fieldNums) {
    const fd = msgDef.fields.get(fn)!;
    const jn = toCamelCase(fd.name);
    const val = msg.fields.get(fn);

    if (fd.type === 'map') {
      if (!val || (val as Map<any, any>).size === 0) continue;
      parts.push(`${escapeJson(jn)}:${serializeMap(val as Map<any, any>, fd, schema)}`);
    } else if (fd.label === 'repeated') {
      if (!val || (val as any[]).length === 0) continue;
      const arr = val as any[];
      const items = arr.map(v => isMessageField(fd.type, schema) ? serializeMsg(v as DecodedMsg, schema.messages.get(fd.type)!, schema) : serializeScalar(v, fd.type, schema));
      parts.push(`${escapeJson(jn)}:[${items.join(',')}]`);
    } else if (fd.label === 'oneof') {
      const setMember = msg.oneofSet.get(fd.oneofName!);
      if (setMember !== fn) continue;
      if (val === undefined) continue;
      if (isMessageField(fd.type, schema)) parts.push(`${escapeJson(jn)}:${serializeMsg(val as DecodedMsg, schema.messages.get(fd.type)!, schema)}`);
      else parts.push(`${escapeJson(jn)}:${serializeScalar(val, fd.type, schema)}`);
    } else if (isMessageField(fd.type, schema)) {
      if (val === undefined) continue;
      parts.push(`${escapeJson(jn)}:${serializeMsg(val as DecodedMsg, schema.messages.get(fd.type)!, schema)}`);
    } else if (fd.label === 'optional') {
      if (!msg.has.has(fn)) continue;
      parts.push(`${escapeJson(jn)}:${serializeScalar(val, fd.type, schema)}`);
    } else {
      if (val === undefined) continue;
      if (isDefault(val, fd.type, schema)) continue;
      parts.push(`${escapeJson(jn)}:${serializeScalar(val, fd.type, schema)}`);
    }
  }
  return '{' + parts.join(',') + '}';
}

function serializeMap(entries: Map<any, any>, fd: FieldDef, schema: Parser): string {
  const isIntKey = fd.mapKey === 'int32';
  const keys = Array.from(entries.keys());
  if (isIntKey) {
    keys.sort((a, b) => (a as number) - (b as number));
  } else {
    keys.sort((a, b) => {
      const sa = a as string; const sb = b as string;
      let i = 0, j = 0;
      while (i < sa.length && j < sb.length) {
        const ca = sa.codePointAt(i)!; const cb = sb.codePointAt(j)!;
        if (ca !== cb) return ca - cb;
        i += ca > 0xFFFF ? 2 : 1; j += cb > 0xFFFF ? 2 : 1;
      }
      if (i < sa.length) return 1; if (j < sb.length) return -1; return 0;
    });
  }
  const parts: string[] = [];
  for (const k of keys) {
    const kStr = isIntKey ? String(k) : escapeJson(k as string);
    const v = entries.get(k);
    let vStr: string;
    if (isMessageField(fd.mapValue!, schema)) {
      vStr = serializeMsg(v as DecodedMsg, schema.messages.get(fd.mapValue!)!, schema);
    } else {
      vStr = serializeScalar(v, fd.mapValue!, schema);
    }
    parts.push(`${kStr}:${vStr}`);
  }
  return '{' + parts.join(',') + '}';
}

// ==================== MAIN ====================
const dir = process.argv[2];
const schemaSrc = fs.readFileSync(path.join(dir, 'schema.proto'), 'utf-8');
const binData = fs.readFileSync(path.join(dir, 'messages.bin'));

const parser = new Parser(schemaSrc);
parser.parse();

const rootMsgDef = parser.messages.get(parser.rootMessage)!;

// Read records
let pos = 0;
const lines: string[] = [];
while (pos < binData.length) {
  const [len, p2] = readVarint(binData, pos); pos = p2;
  const msgData = binData.subarray(pos, pos + Number(len)); pos += Number(len);
  const decoded = decodeMessage(msgData, rootMsgDef, parser);
  lines.push(serializeMsg(decoded, rootMsgDef, parser));
}

process.stdout.write(lines.join('\n') + '\n');

import * as fs from 'fs';
import * as path from 'path';

// ==================== LEXER ====================
interface Token { type: 'ident' | 'number' | 'string' | 'punct'; value: string; }

class Lexer {
  private input: string; private pos: number;
  constructor(input: string) { this.input = input; this.pos = 0; }
  private skip(): void {
    while (this.pos < this.input.length) {
      const ch = this.input[this.pos];
      if (ch === ' ' || ch === '\t' || ch === '\r' || ch === '\n') { this.pos++; }
      else if (ch === '/' && this.pos + 1 < this.input.length && this.input[this.pos + 1] === '/') {
        this.pos += 2; while (this.pos < this.input.length && this.input[this.pos] !== '\n') this.pos++;
      } else if (ch === '/' && this.pos + 1 < this.input.length && this.input[this.pos + 1] === '*') {
        this.pos += 2;
        while (this.pos + 1 < this.input.length && !(this.input[this.pos] === '*' && this.input[this.pos + 1] === '/')) this.pos++;
        this.pos += 2;
      } else break;
    }
  }
  next(): Token | null {
    this.skip();
    if (this.pos >= this.input.length) return null;
    const ch = this.input[this.pos];
    if (ch === '"') {
      this.pos++; const start = this.pos;
      while (this.pos < this.input.length && this.input[this.pos] !== '"') this.pos++;
      const val = this.input.substring(start, this.pos); this.pos++;
      return { type: 'string', value: val };
    }
    if ((ch >= 'a' && ch <= 'z') || (ch >= 'A' && ch <= 'Z') || ch === '_') {
      const start = this.pos;
      while (this.pos < this.input.length && /[a-zA-Z0-9_]/.test(this.input[this.pos])) this.pos++;
      return { type: 'ident', value: this.input.substring(start, this.pos) };
    }
    if ((ch >= '0' && ch <= '9') || ch === '-') {
      const start = this.pos;
      if (ch === '-') this.pos++;
      if (this.pos < this.input.length && this.input[this.pos] === '0' && this.pos + 1 < this.input.length && (this.input[this.pos + 1] === 'x' || this.input[this.pos + 1] === 'X')) {
        this.pos += 2; while (this.pos < this.input.length && /[0-9a-fA-F]/.test(this.input[this.pos])) this.pos++;
      } else { while (this.pos < this.input.length && /[0-9]/.test(this.input[this.pos])) this.pos++; }
      return { type: 'number', value: this.input.substring(start, this.pos) };
    }
    this.pos++; return { type: 'punct', value: ch };
  }
}

// ==================== SCHEMA TYPES ====================
interface FieldDef {
  name: string; number: number; type: string;
  label: 'singular' | 'repeated' | 'optional' | 'oneof';
  oneofName?: string; mapKey?: string; mapValue?: string;
}
interface MessageDef { name: string; fields: Map<number, FieldDef>; oneofs: Map<string, number[]>; }
interface EnumDef { name: string; values: Map<number, string>; }

// ==================== PARSER ====================
class Parser {
  private tokens: Token[]; private pos: number;
  messages = new Map<string, MessageDef>();
  enums = new Map<string, EnumDef>();
  rootMessage = '';
  constructor(input: string) {
    const lexer = new Lexer(input); this.tokens = []; this.pos = 0;
    let t: Token | null; while ((t = lexer.next()) !== null) this.tokens.push(t);
  }
  private peek(): Token | null { return this.pos < this.tokens.length ? this.tokens[this.pos] : null; }
  private next(): Token { if (this.pos >= this.tokens.length) throw new Error('EOF'); return this.tokens[this.pos++]; }
  private expectIdent(): string { const t = this.next(); if (t.type !== 'ident') throw new Error(`Expected ident got ${t.type}:${t.value}`); return t.value; }
  private expectPunct(v: string): void { const t = this.next(); if (t.type !== 'punct' || t.value !== v) throw new Error(`Expected '${v}' got ${t.type}:${t.value}`); }
  private skipToSemi(): void { let d = 0; while (true) { const t = this.next(); if (t.type === 'punct' && t.value === '{') d++; if (t.type === 'punct' && t.value === '}') d--; if (t.type === 'punct' && t.value === ';' && d === 0) return; } }
  private skipOptions(): void { if (this.peek()?.type === 'punct' && this.peek()?.value === '[') { this.next(); let d = 1; while (d > 0) { const t = this.next(); if (t.type === 'punct' && t.value === '[') d++; if (t.type === 'punct' && t.value === ']') d--; } } }

  parse(): void {
    while (this.peek()) {
      const t = this.peek()!;
      if (t.type === 'ident') {
        if (t.value === 'syntax') { this.next(); this.expectPunct('='); this.next(); this.expectPunct(';'); }
        else if (t.value === 'package') { this.next(); this.skipToSemi(); }
        else if (t.value === 'option') { this.next(); this.skipToSemi(); }
        else if (t.value === 'message') { this.next(); this.parseMessage(true); }
        else if (t.value === 'enum') { this.next(); this.parseEnum(); }
        else this.next();
      } else this.next();
    }
  }

  private parseMessage(top: boolean): void {
    const name = this.expectIdent();
    if (top && !this.rootMessage) this.rootMessage = name;
    const msg: MessageDef = { name, fields: new Map(), oneofs: new Map() };
    this.messages.set(name, msg);
    this.expectPunct('{');
    while (true) {
      const t = this.peek(); if (!t) break;
      if (t.type === 'punct' && t.value === '}') { this.next(); break; }
      if (t.type === 'ident') {
        if (t.value === 'message') { this.next(); this.parseMessage(false); }
        else if (t.value === 'enum') { this.next(); this.parseEnum(); }
        else if (t.value === 'oneof') { this.next(); this.parseOneof(msg); }
        else if (t.value === 'reserved') { this.next(); this.skipToSemi(); }
        else if (t.value === 'option') { this.next(); this.skipToSemi(); }
        else if (t.value === 'map') { this.parseMapField(msg); }
        else this.parseField(msg);
      } else if (t.type === 'punct' && t.value === ';') this.next();
      else this.next();
    }
  }

  private parseField(msg: MessageDef): void {
    let label: FieldDef['label'] = 'singular';
    const t = this.peek()!;
    if (t.type === 'ident' && (t.value === 'repeated' || t.value === 'optional')) { label = t.value as any; this.next(); }
    const type = this.expectIdent(); const name = this.expectIdent();
    this.expectPunct('='); const num = parseInt(this.next().value);
    this.skipOptions(); this.expectPunct(';');
    msg.fields.set(num, { name, number: num, type, label });
  }

  private parseMapField(msg: MessageDef): void {
    this.next(); this.expectPunct('<');
    const keyType = this.expectIdent(); this.expectPunct(',');
    const valueType = this.expectIdent(); this.expectPunct('>');
    const name = this.expectIdent(); this.expectPunct('=');
    const num = parseInt(this.next().value); this.skipOptions(); this.expectPunct(';');
    msg.fields.set(num, { name, number: num, type: 'map', label: 'repeated', mapKey: keyType, mapValue: valueType });
  }

  private parseOneof(msg: MessageDef): void {
    const oneofName = this.expectIdent(); msg.oneofs.set(oneofName, []);
    this.expectPunct('{');
    while (true) {
      const t = this.peek(); if (!t) break;
      if (t.type === 'punct' && t.value === '}') { this.next(); break; }
      if (t.type === 'ident') {
        if (t.value === 'option') { this.next(); this.skipToSemi(); }
        else {
          const type = this.expectIdent(); const name = this.expectIdent();
          this.expectPunct('='); const num = parseInt(this.next().value);
          this.skipOptions(); this.expectPunct(';');
          msg.fields.set(num, { name, number: num, type, label: 'oneof', oneofName });
          msg.oneofs.get(oneofName)!.push(num);
        }
      } else if (t.type === 'punct' && t.value === ';') this.next();
      else this.next();
    }
  }

  private parseEnum(): void {
    const name = this.expectIdent(); const ed: EnumDef = { name, values: new Map() };
    this.enums.set(name, ed); this.expectPunct('{');
    while (true) {
      const t = this.peek(); if (!t) break;
      if (t.type === 'punct' && t.value === '}') { this.next(); break; }
      if (t.type === 'ident') {
        if (t.value === 'option' || t.value === 'reserved') { this.next(); this.skipToSemi(); }
        else {
          const vname = this.expectIdent(); this.expectPunct('=');
          const num = parseInt(this.next().value); this.skipOptions(); this.expectPunct(';');
          ed.values.set(num, vname);
        }
      } else if (t.type === 'punct' && t.value === ';') this.next();
      else this.next();
    }
  }
}

// ==================== DECODER ====================
type ScalarVal = number | bigint | string | Uint8Array | boolean;
interface DecodedMsg { fields: Map<number, any>; has: Set<number>; oneofSet: Map<string, number>; }

const decoder = new TextDecoder();

function readVarint(data: Uint8Array, pos: number): [bigint, number] {
  let result = 0n; let shift = 0n; let i = pos;
  while (i < data.length) {
    const b = data[i]; i++;
    result |= BigInt(b & 0x7f) << shift;
    if ((b & 0x80) === 0) break;
    shift += 7n;
  }
  return [result, i];
}

function varintToUint64(v: bigint): bigint { return v & 0xFFFFFFFFFFFFFFFFn; }
function varintToInt64(v: bigint): bigint {
  v = v & 0xFFFFFFFFFFFFFFFFn;
  if (v >= 0x8000000000000000n) v -= 0x10000000000000000n;
  return v;
}
function varintToUint32(v: bigint): number { return Number(v & 0xFFFFFFFFn); }
function varintToInt32(v: bigint): number {
  let n = Number(v & 0xFFFFFFFFn);
  if (n >= 0x80000000) n -= 0x100000000;
  return n;
}
function zigzag32(v: bigint): number {
  const n = Number(v & 0xFFFFFFFFn);
  return (n >>> 1) ^ -(n & 1);
}
function zigzag64(v: bigint): bigint {
  v = v & 0xFFFFFFFFFFFFFFFFn;
  return (v >> 1n) ^ -(v & 1n);
}
function readFixed32(data: Uint8Array, pos: number): number {
  return (data[pos] | (data[pos + 1] << 8) | (data[pos + 2] << 16) | (data[pos + 3] << 24)) >>> 0;
}
function readSfixed32(data: Uint8Array, pos: number): number {
  return data[pos] | (data[pos + 1] << 8) | (data[pos + 2] << 16) | (data[pos + 3] << 24);
}
function readFixed64(data: Uint8Array, pos: number): bigint {
  let v = 0n;
  for (let i = 7; i >= 0; i--) v = (v << 8n) | BigInt(data[pos + i]);
  return v;
}
function readSfixed64(data: Uint8Array, pos: number): bigint {
  let v = readFixed64(data, pos);
  if (v >= 0x8000000000000000n) v -= 0x10000000000000000n;
  return v;
}

function isPackable(type: string, schema: Parser): boolean {
  if (schema.enums.has(type)) return true;
  return ['int32','int64','uint32','uint64','sint32','sint64','bool','fixed32','sfixed32','fixed64','sfixed64'].includes(type);
}
function isMessageField(type: string, schema: Parser): boolean { return schema.messages.has(type); }

function decodeScalar(data: Uint8Array, pos: number, wireType: number, type: string, schema: Parser): [ScalarVal, number] {
  if (type === 'string') {
    const [len, p2] = readVarint(data, pos);
    const start = p2; const end = start + Number(len);
    return [decoder.decode(data.subarray(start, end)), end];
  }
  if (type === 'bytes') {
    const [len, p2] = readVarint(data, pos);
    const start = p2; const end = start + Number(len);
    return [data.slice(start, end), end];
  }
  if (type === 'bool') {
    const [v, p2] = readVarint(data, pos);
    return [v !== 0n, p2];
  }
  if (schema.enums.has(type)) {
    const [v, p2] = readVarint(data, pos);
    return [varintToInt32(v), p2];
  }
  switch (type) {
    case 'int32': { const [v, p2] = readVarint(data, pos); return [varintToInt32(v), p2]; }
    case 'int64': { const [v, p2] = readVarint(data, pos); return [varintToInt64(v), p2]; }
    case 'uint32': { const [v, p2] = readVarint(data, pos); return [varintToUint32(v), p2]; }
    case 'uint64': { const [v, p2] = readVarint(data, pos); return [varintToUint64(v), p2]; }
    case 'sint32': { const [v, p2] = readVarint(data, pos); return [zigzag32(v), p2]; }
    case 'sint64': { const [v, p2] = readVarint(data, pos); return [zigzag64(v), p2]; }
    case 'fixed32': return [readFixed32(data, pos), pos + 4];
    case 'sfixed32': return [readSfixed32(data, pos), pos + 4];
    case 'fixed64': return [readFixed64(data, pos), pos + 8];
    case 'sfixed64': return [readSfixed64(data, pos), pos + 8];
    default: { const [v, p2] = readVarint(data, pos); return [varintToInt32(v), p2]; }
  }
}

function skipField(data: Uint8Array, pos: number, wireType: number, fieldNum: number): number {
  switch (wireType) {
    case 0: while (pos < data.length && (data[pos] & 0x80)) pos++; pos++; return pos;
    case 1: return pos + 8;
    case 2: { const [len, p2] = readVarint(data, pos); return p2 + Number(len); }
    case 5: return pos + 4;
    case 3: {
      while (pos < data.length) {
        const [key, p2] = readVarint(data, pos); pos = p2;
        const fn = Number(key >> 3n); const wt = Number(key & 7n);
        if (wt === 4 && fn === fieldNum) return pos;
        pos = skipField(data, pos, wt, fn);
      }
      return pos;
    }
    case 4: return pos;
    default: return pos;
  }
}

function getWireType(type: string): number {
  if (type === 'string' || type === 'bytes') return 2;
  if (type === 'fixed64' || type === 'sfixed64') return 1;
  if (type === 'fixed32' || type === 'sfixed32') return 5;
  return 0;
}

function decodeMapEntry(data: Uint8Array, fd: FieldDef, schema: Parser): { key: any; value: any } {
  let key: any = fd.mapKey === 'string' ? '' : 0;
  let value: any = getDefaultScalar(fd.mapValue!, schema);
  let pos = 0;
  while (pos < data.length) {
    const [keyVarint, p2] = readVarint(data, pos); pos = p2;
    const fn = Number(keyVarint >> 3n);
    const wt = Number(keyVarint & 7n);
    if (fn === 1) {
      const [k, np] = decodeScalar(data, pos, wt, fd.mapKey!, schema);
      pos = np; key = k;
    } else if (fn === 2) {
      if (isMessageField(fd.mapValue!, schema)) {
        if (wt === 2) {
          const [len, p3] = readVarint(data, pos); pos = p3;
          const msgData = data.subarray(pos, pos + Number(len)); pos += Number(len);
          value = decodeMessage(msgData, schema.messages.get(fd.mapValue!)!, schema);
        } else { pos = skipField(data, pos, wt, fn); }
      } else {
        const [v, np] = decodeScalar(data, pos, wt, fd.mapValue!, schema);
        pos = np; value = v;
      }
    } else { pos = skipField(data, pos, wt, fn); }
  }
  return { key, value };
}

function getDefaultScalar(type: string, schema: Parser): any {
  if (schema.enums.has(type)) return 0;
  if (type === 'bool') return false;
  if (type === 'string') return '';
  if (type === 'bytes') return new Uint8Array(0);
  if (type === 'int64' || type === 'uint64' || type === 'sint64' || type === 'fixed64' || type === 'sfixed64') return 0n;
  return 0;
}

function decodeMessage(data: Uint8Array, msgDef: MessageDef, schema: Parser): DecodedMsg {
  const result: DecodedMsg = { fields: new Map(), has: new Set(), oneofSet: new Map() };
  let pos = 0;
  while (pos < data.length) {
    const [key, p2] = readVarint(data, pos); pos = p2;
    const fieldNum = Number(key >> 3n);
    const wireType = Number(key & 7n);
    const fd = msgDef.fields.get(fieldNum);
    if (!fd) { pos = skipField(data, pos, wireType, fieldNum); continue; }

    if (fd.type === 'map') {
      if (wireType !== 2) { pos = skipField(data, pos, wireType, fieldNum); continue; }
      const [len, p3] = readVarint(data, pos); pos = p3;
      const entryData = data.subarray(pos, pos + Number(len)); pos += Number(len);
      const entry = decodeMapEntry(entryData, fd, schema);
      if (!result.fields.has(fieldNum)) result.fields.set(fieldNum, new Map());
      (result.fields.get(fieldNum) as Map<any, any>).set(entry.key, entry.value);
    } else if (fd.label === 'repeated') {
      if (!result.fields.has(fieldNum)) result.fields.set(fieldNum, []);
      const arr = result.fields.get(fieldNum) as any[];
      if (wireType === 2 && isPackable(fd.type, schema)) {
        const [len, p3] = readVarint(data, pos); pos = p3;
        const packedData = data.subarray(pos, pos + Number(len)); pos += Number(len);
        let pp = 0;
        while (pp < packedData.length) {
          const wt = getWireType(fd.type);
          const [val, np] = decodeScalar(packedData, pp, wt, fd.type, schema);
          arr.push(val); pp = np;
        }
      } else if (isMessageField(fd.type, schema)) {
        if (wireType !== 2) { pos = skipField(data, pos, wireType, fieldNum); continue; }
        const [len, p3] = readVarint(data, pos); pos = p3;
        const msgData = data.subarray(pos, pos + Number(len)); pos += Number(len);
        arr.push(decodeMessage(msgData, schema.messages.get(fd.type)!, schema));
      } else {
        const [val, np] = decodeScalar(data, pos, wireType, fd.type, schema);
        pos = np; arr.push(val);
      }
    } else if (fd.label === 'oneof') {
      const oneofName = fd.oneofName!;
      const cur = result.oneofSet.get(oneofName);
      if (cur !== undefined && cur !== fieldNum) { result.fields.delete(cur); result.has.delete(cur); }
      result.oneofSet.set(oneofName, fieldNum);
      result.has.add(fieldNum);
      if (isMessageField(fd.type, schema)) {
        if (wireType !== 2) { pos = skipField(data, pos, wireType, fieldNum); continue; }
        const [len, p3] = readVarint(data, pos); pos = p3;
        const msgData = data.subarray(pos, pos + Number(len)); pos += Number(len);
        const existing = result.fields.get(fieldNum);
        if (existing && cur === fieldNum) {
          mergeMessageInto(existing, msgData, schema.messages.get(fd.type)!, schema);
        } else {
          result.fields.set(fieldNum, decodeMessage(msgData, schema.messages.get(fd.type)!, schema));
        }
      } else {
        const [val, np] = decodeScalar(data, pos, wireType, fd.type, schema);
        pos = np; result.fields.set(fieldNum, val);
      }
    } else if (isMessageField(fd.type, schema)) {
      if (wireType !== 2) { pos = skipField(data, pos, wireType, fieldNum); continue; }
      const [len, p3] = readVarint(data, pos); pos = p3;
      const msgData = data.subarray(pos, pos + Number(len)); pos += Number(len);
      const existing = result.fields.get(fieldNum);
      if (existing) {
        mergeMessageInto(existing, msgData, schema.messages.get(fd.type)!, schema);
      } else {
        result.fields.set(fieldNum, decodeMessage(msgData, schema.messages.get(fd.type)!, schema));
      }
      result.has.add(fieldNum);
    } else {
      if (wireType === 2 && isPackable(fd.type, schema)) { pos = skipField(data, pos, wireType, fieldNum); continue; }
      const [val, np] = decodeScalar(data, pos, wireType, fd.type, schema);
      pos = np; result.fields.set(fieldNum, val); result.has.add(fieldNum);
    }
  }
  return result;
}

function mergeMessageInto(target: DecodedMsg, data: Uint8Array, msgDef: MessageDef, schema: Parser): void {
  let pos = 0;
  while (pos < data.length) {
    const [key, p2] = readVarint(data, pos); pos = p2;
    const fieldNum = Number(key >> 3n);
    const wireType = Number(key & 7n);
    const fd = msgDef.fields.get(fieldNum);
    if (!fd) { pos = skipField(data, pos, wireType, fieldNum); continue; }

    if (fd.type === 'map') {
      if (wireType !== 2) { pos = skipField(data, pos, wireType, fieldNum); continue; }
      const [len, p3] = readVarint(data, pos); pos = p3;
      const entryData = data.subarray(pos, pos + Number(len)); pos += Number(len);
      const entry = decodeMapEntry(entryData, fd, schema);
      if (!target.fields.has(fieldNum)) target.fields.set(fieldNum, new Map());
      (target.fields.get(fieldNum) as Map<any, any>).set(entry.key, entry.value);
    } else if (fd.label === 'repeated') {
      if (!target.fields.has(fieldNum)) target.fields.set(fieldNum, []);
      const arr = target.fields.get(fieldNum) as any[];
      if (wireType === 2 && isPackable(fd.type, schema)) {
        const [len, p3] = readVarint(data, pos); pos = p3;
        const packedData = data.subarray(pos, pos + Number(len)); pos += Number(len);
        let pp = 0;
        while (pp < packedData.length) {
          const wt = getWireType(fd.type);
          const [val, np] = decodeScalar(packedData, pp, wt, fd.type, schema);
          arr.push(val); pp = np;
        }
      } else if (isMessageField(fd.type, schema)) {
        if (wireType !== 2) { pos = skipField(data, pos, wireType, fieldNum); continue; }
        const [len, p3] = readVarint(data, pos); pos = p3;
        const msgData = data.subarray(pos, pos + Number(len)); pos += Number(len);
        arr.push(decodeMessage(msgData, schema.messages.get(fd.type)!, schema));
      } else {
        const [val, np] = decodeScalar(data, pos, wireType, fd.type, schema);
        pos = np; arr.push(val);
      }
    } else if (fd.label === 'oneof') {
      const oneofName = fd.oneofName!;
      const cur = target.oneofSet.get(oneofName);
      if (cur !== undefined && cur !== fieldNum) { target.fields.delete(cur); target.has.delete(cur); }
      target.oneofSet.set(oneofName, fieldNum);
      target.has.add(fieldNum);
      if (isMessageField(fd.type, schema)) {
        if (wireType !== 2) { pos = skipField(data, pos, wireType, fieldNum); continue; }
        const [len, p3] = readVarint(data, pos); pos = p3;
        const msgData = data.subarray(pos, pos + Number(len)); pos += Number(len);
        const existing = target.fields.get(fieldNum);
        if (existing && cur === fieldNum) {
          mergeMessageInto(existing, msgData, schema.messages.get(fd.type)!, schema);
        } else {
          target.fields.set(fieldNum, decodeMessage(msgData, schema.messages.get(fd.type)!, schema));
        }
      } else {
        const [val, np] = decodeScalar(data, pos, wireType, fd.type, schema);
        pos = np; target.fields.set(fieldNum, val);
      }
    } else if (isMessageField(fd.type, schema)) {
      if (wireType !== 2) { pos = skipField(data, pos, wireType, fieldNum); continue; }
      const [len, p3] = readVarint(data, pos); pos = p3;
      const msgData = data.subarray(pos, pos + Number(len)); pos += Number(len);
      const existing = target.fields.get(fieldNum);
      if (existing) {
        mergeMessageInto(existing, msgData, schema.messages.get(fd.type)!, schema);
      } else {
        target.fields.set(fieldNum, decodeMessage(msgData, schema.messages.get(fd.type)!, schema));
      }
      target.has.add(fieldNum);
    } else {
      const [val, np] = decodeScalar(data, pos, wireType, fd.type, schema);
      pos = np; target.fields.set(fieldNum, val); target.has.add(fieldNum);
    }
  }
}

// ==================== SERIALIZER ====================
function toCamelCase(name: string): string {
  let result = ''; let cap = false;
  for (let i = 0; i < name.length; i++) {
    if (name[i] === '_') { cap = true; }
    else {
      if (cap && name[i] >= 'a' && name[i] <= 'z') result += name[i].toUpperCase();
      else result += name[i];
      cap = false;
    }
  }
  return result;
}

function escapeJson(s: string): string {
  let r = '"';
  for (let i = 0; i < s.length; i++) {
    const c = s.charCodeAt(i);
    if (c === 34) r += '\\"';
    else if (c === 92) r += '\\\\';
    else if (c === 8) r += '\\b';
    else if (c === 9) r += '\\t';
    else if (c === 10) r += '\\n';
    else if (c === 12) r += '\\f';
    else if (c === 13) r += '\\r';
    else if (c < 32) r += '\\u00' + c.toString(16).padStart(2, '0');
    else r += s[i];
  }
  return r + '"';
}

const B64CH = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
function base64(data: Uint8Array): string {
  let r = ''; let i = 0;
  while (i < data.length) {
    const b0 = data[i++];
    const b1 = i < data.length ? data[i++] : -1;
    const b2 = i < data.length ? data[i++] : -1;
    r += B64CH[b0 >> 2];
    if (b1 === -1) { r += B64CH[(b0 & 3) << 4] + '=='; }
    else if (b2 === -1) { r += B64CH[((b0 & 3) << 4) | (b1 >> 4)] + B64CH[(b1 & 15) << 2] + '='; }
    else { r += B64CH[((b0 & 3) << 4) | (b1 >> 4)] + B64CH[((b1 & 15) << 2) | (b2 >> 6)] + B64CH[b2 & 63]; }
  }
  return r;
}

function isDefault(val: any, type: string, schema: Parser): boolean {
  if (schema.enums.has(type)) return val === 0;
  if (type === 'bool') return val === false;
  if (type === 'string') return val === '';
  if (type === 'bytes') return (val as Uint8Array).length === 0;
  if (typeof val === 'bigint') return val === 0n;
  if (typeof val === 'number') return val === 0;
  return false;
}

function serializeScalar(val: any, type: string, schema: Parser): string {
  if (schema.enums.has(type)) {
    const ed = schema.enums.get(type)!;
    const name = ed.values.get(val as number);
    if (name !== undefined) return `"${name}"`;
    return String(val);
  }
  if (type === 'bool') return val ? 'true' : 'false';
  if (type === 'string') return escapeJson(val as string);
  if (type === 'bytes') return `"${base64(val as Uint8Array)}"`;
  if (type === 'int64' || type === 'uint64' || type === 'sint64' || type === 'fixed64' || type === 'sfixed64') {
    return `"${(val as bigint).toString()}"`;
  }
  return String(val);
}

function serializeMsg(msg: DecodedMsg, msgDef: MessageDef, schema: Parser): string {
  const parts: string[] = [];
  const fieldNums = Array.from(msgDef.fields.keys()).sort((a, b) => a - b);
  for (const fn of fieldNums) {
    const fd = msgDef.fields.get(fn)!;
    const jn = toCamelCase(fd.name);
    const val = msg.fields.get(fn);

    if (fd.type === 'map') {
      if (!val || (val as Map<any, any>).size === 0) continue;
      parts.push(`${escapeJson(jn)}:${serializeMap(val as Map<any, any>, fd, schema)}`);
    } else if (fd.label === 'repeated') {
      if (!val || (val as any[]).length === 0) continue;
      const arr = val as any[];
      const items = arr.map(v => isMessageField(fd.type, schema) ? serializeMsg(v as DecodedMsg, schema.messages.get(fd.type)!, schema) : serializeScalar(v, fd.type, schema));
      parts.push(`${escapeJson(jn)}:[${items.join(',')}]`);
    } else if (fd.label === 'oneof') {
      const setMember = msg.oneofSet.get(fd.oneofName!);
      if (setMember !== fn) continue;
      if (val === undefined) continue;
      if (isMessageField(fd.type, schema)) parts.push(`${escapeJson(jn)}:${serializeMsg(val as DecodedMsg, schema.messages.get(fd.type)!, schema)}`);
      else parts.push(`${escapeJson(jn)}:${serializeScalar(val, fd.type, schema)}`);
    } else if (isMessageField(fd.type, schema)) {
      if (val === undefined) continue;
      parts.push(`${escapeJson(jn)}:${serializeMsg(val as DecodedMsg, schema.messages.get(fd.type)!, schema)}`);
    } else if (fd.label === 'optional') {
      if (!msg.has.has(fn)) continue;
      parts.push(`${escapeJson(jn)}:${serializeScalar(val, fd.type, schema)}`);
    } else {
      if (val === undefined) continue;
      if (isDefault(val, fd.type, schema)) continue;
      parts.push(`${escapeJson(jn)}:${serializeScalar(val, fd.type, schema)}`);
    }
  }
  return '{' + parts.join(',') + '}';
}

function serializeMap(entries: Map<any, any>, fd: FieldDef, schema: Parser): string {
  const isIntKey = fd.mapKey === 'int32';
  const keys = Array.from(entries.keys());
  if (isIntKey) {
    keys.sort((a, b) => (a as number) - (b as number));
  } else {
    keys.sort((a, b) => {
      const sa = a as string; const sb = b as string;
      let i = 0, j = 0;
      while (i < sa.length && j < sb.length) {
        const ca = sa.codePointAt(i)!; const cb = sb.codePointAt(j)!;
        if (ca !== cb) return ca - cb;
        i += ca > 0xFFFF ? 2 : 1; j += cb > 0xFFFF ? 2 : 1;
      }
      if (i < sa.length) return 1; if (j < sb.length) return -1; return 0;
    });
  }
  const parts: string[] = [];
  for (const k of keys) {
    const kStr = isIntKey ? String(k) : escapeJson(k as string);
    const v = entries.get(k);
    let vStr: string;
    if (isMessageField(fd.mapValue!, schema)) {
      vStr = serializeMsg(v as DecodedMsg, schema.messages.get(fd.mapValue!)!, schema);
    } else {
      vStr = serializeScalar(v, fd.mapValue!, schema);
    }
    parts.push(`${kStr}:${vStr}`);
  }
  return '{' + parts.join(',') + '}';
}

// ==================== MAIN ====================
const dir = process.argv[2];
const schemaSrc = fs.readFileSync(path.join(dir, 'schema.proto'), 'utf-8');
const binData = fs.readFileSync(path.join(dir, 'messages.bin'));

const parser = new Parser(schemaSrc);
parser.parse();

const rootMsgDef = parser.messages.get(parser.rootMessage)!;

// Read records
let pos = 0;
const lines: string[] = [];
while (pos < binData.length) {
  const [len, p2] = readVarint(binData, pos); pos = p2;
  const msgData = binData.subarray(pos, pos + Number(len)); pos += Number(len);
  const decoded = decodeMessage(msgData, rootMsgDef, parser);
  lines.push(serializeMsg(decoded, rootMsgDef, parser));
}

process.stdout.write(lines.join('\n') + '\n');

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <ctype.h>
#include <stdarg.h>

/* ===== String Buffer ===== */
typedef struct { char *buf; size_t len, cap; } SB;
static void sb_init(SB *s){s->cap=1024;s->buf=malloc(s->cap);s->len=0;s->buf[0]=0;}
static void sb_ens(SB *s,size_t n){if(s->len+n+1>s->cap){while(s->len+n+1>s->cap)s->cap*=2;s->buf=realloc(s->buf,s->cap);}}
static void sb_c(SB *s,char c){sb_ens(s,1);s->buf[s->len++]=c;s->buf[s->len]=0;}
static void sb_s(SB *s,const char *t){size_t l=strlen(t);sb_ens(s,l);memcpy(s->buf+s->len,t,l);s->len+=l;s->buf[s->len]=0;}
static void sb_n(SB *s,const char *t,size_t n){sb_ens(s,n);memcpy(s->buf+s->len,t,n);s->len+=n;s->buf[s->len]=0;}
static void sb_f(SB *s,const char *fmt,...){va_list ap;va_start(ap,fmt);char tmp[512];int n=vsnprintf(tmp,512,fmt,ap);va_end(ap);sb_ens(s,n);memcpy(s->buf+s->len,tmp,n);s->len+=n;s->buf[s->len]=0;}

/* ===== Proto Lexer ===== */
static const char *g_src, *g_src_end;
typedef enum{TK_EOF,TK_IDENT,TK_NUM,TK_STR,TK_PUNCT}TokType;
static TokType tk_type;
static char tk_str[4096];
static long long tk_num;
static char tk_ch;

static void skip_ws(void){
    while(g_src<g_src_end){
        if(isspace((unsigned char)*g_src)){g_src++;}
        else if(g_src+1<g_src_end&&g_src[0]=='/'&&g_src[1]=='/'){g_src+=2;while(g_src<g_src_end&&*g_src!='\n')g_src++;}
        else if(g_src+1<g_src_end&&g_src[0]=='/'&&g_src[1]=='*'){g_src+=2;while(g_src+1<g_src_end&&!(g_src[0]=='*'&&g_src[1]=='/'))g_src++;if(g_src+1<g_src_end)g_src+=2;}
        else break;
    }
}
static void next_tok(void){
    skip_ws();
    if(g_src>=g_src_end){tk_type=TK_EOF;return;}
    if(*g_src=='"'){g_src++;int i=0;while(g_src<g_src_end&&*g_src!='"'){if(i<4095)tk_str[i++]=*g_src;else g_src++;if(i<4095)tk_str[i]=*g_src;g_src++;}tk_str[i]=0;if(g_src<g_src_end)g_src++;tk_type=TK_STR;}
    else if(isalpha((unsigned char)*g_src)||*g_src=='_'){int i=0;while(g_src<g_src_end&&(isalnum((unsigned char)*g_src)||*g_src=='_')){if(i<4095)tk_str[i++]=*g_src;g_src++;}tk_str[i]=0;tk_type=TK_IDENT;}
    else if(isdigit((unsigned char)*g_src)){int i=0;while(g_src<g_src_end&&isdigit((unsigned char)*g_src)){if(i<4095)tk_str[i++]=*g_src;g_src++;}tk_str[i]=0;tk_num=strtoll(tk_str,NULL,10);tk_type=TK_NUM;}
    else{tk_ch=*g_src++;tk_type=TK_PUNCT;}
}
static void skip_to_semi(void){while(tk_type!=TK_EOF){if(tk_type==TK_PUNCT&&tk_ch==';'){next_tok();return;}next_tok();}}
static void skip_to_close_brace(void){int d=1;while(tk_type!=TK_EOF&&d>0){if(tk_type==TK_PUNCT&&tk_ch=='{')d++;else if(tk_type==TK_PUNCT&&tk_ch=='}')d--;if(d>0)next_tok();}if(tk_type==TK_PUNCT&&tk_ch=='}')next_tok();}
static void skip_to_close_bracket(void){int d=1;while(tk_type!=TK_EOF&&d>0){if(tk_type==TK_PUNCT&&tk_ch=='[')d++;else if(tk_type==TK_PUNCT&&tk_ch==']')d--;if(d>0)next_tok();}if(tk_type==TK_PUNCT&&tk_ch==']')next_tok();}

/* ===== Schema Structures ===== */
#define MAX_MSGS 512
#define MAX_ENUMS 256
#define MAX_FIELDS 256
#define MAX_ENUM_VALS 256
#define MAX_ONEOFS 64

typedef enum{FT_INT32,FT_INT64,FT_UINT32,FT_UINT64,FT_SINT32,FT_SINT64,FT_BOOL,FT_STRING,FT_BYTES,
FT_FIXED32,FT_FIXED64,FT_SFIXED32,FT_SFIXED64,FT_ENUM,FT_MESSAGE,FT_MAP}FieldType;

typedef struct{
    char name[128]; char jname[128]; int number; FieldType type;
    int is_repeated, is_optional, in_oneof, oneof_idx;
    char type_name[128];
    FieldType map_key_type, map_value_type;
    char map_value_type_name[128];
}FieldDef;

typedef struct{
    char name[128]; int nfields; FieldDef fields[MAX_FIELDS];
    int noneofs; char oneof_names[MAX_ONEOFS][128];
}MsgDef;

typedef struct{
    char name[128]; int nvals;
    struct{int val;char name[128];}vals[MAX_ENUM_VALS];
}EnumDef;

static MsgDef msgs[MAX_MSGS]; static int nmsgs=0;
static EnumDef enums[MAX_ENUMS]; static int nenums=0;
static char root_name[128]; static int found_root=0;

/* ===== Proto Parser ===== */
static FieldType parse_scalar_type(const char *n){
    if(!strcmp(n,"int32"))return FT_INT32; if(!strcmp(n,"int64"))return FT_INT64;
    if(!strcmp(n,"uint32"))return FT_UINT32; if(!strcmp(n,"uint64"))return FT_UINT64;
    if(!strcmp(n,"sint32"))return FT_SINT32; if(!strcmp(n,"sint64"))return FT_SINT64;
    if(!strcmp(n,"bool"))return FT_BOOL; if(!strcmp(n,"string"))return FT_STRING;
    if(!strcmp(n,"bytes"))return FT_BYTES; if(!strcmp(n,"fixed32"))return FT_FIXED32;
    if(!strcmp(n,"fixed64"))return FT_FIXED64; if(!strcmp(n,"sfixed32"))return FT_SFIXED32;
    if(!strcmp(n,"sfixed64"))return FT_SFIXED64;
    return (FieldType)-1;
}
static void resolve_type_name(const char *n, FieldType *out, char *tn){
    FieldType st=parse_scalar_type(n);
    if(st!=(FieldType)-1){*out=st;tn[0]=0;return;}
    for(int i=0;i<nmsgs;i++)if(!strcmp(msgs[i].name,n)){*out=FT_MESSAGE;strcpy(tn,n);return;}
    for(int i=0;i<nenums;i++)if(!strcmp(enums[i].name,n)){*out=FT_ENUM;strcpy(tn,n);return;}
    *out=FT_INT32;tn[0]=0;
}
static void to_lower_camel(const char *n, char *out){
    int j=0,up=0;
    for(int i=0;n[i];i++){
        if(n[i]=='_'){up=1;}
        else{if(up&&n[i]>='a'&&n[i]<='z')out[j++]=n[i]-'a'+'A';else out[j++]=n[i];up=0;}
    }
    out[j]=0;
}
static void parse_field(int mi, const char *label){
    FieldDef *f=&msgs[mi].fields[msgs[mi].nfields++];
    memset(f,0,sizeof(*f));
    f->is_repeated=(label&&!strcmp(label,"repeated"));
    f->is_optional=(label&&!strcmp(label,"optional"));
    if(label)next_tok();
    /* tok is type name */
    strcpy(f->type_name,tk_str);
    next_tok(); /* field name */
    strcpy(f->name,tk_str);
    to_lower_camel(f->name,f->jname);
    next_tok(); /* = */
    next_tok(); /* number */
    if(tk_type==TK_PUNCT&&tk_ch=='-'){next_tok();f->number=-(int)tk_num;}
    else f->number=(int)tk_num;
    next_tok();
    if(tk_type==TK_PUNCT&&tk_ch=='[')skip_to_close_bracket();
    if(tk_type==TK_PUNCT&&tk_ch==';')next_tok();
}
static void parse_map_field(int mi){
    FieldDef *f=&msgs[mi].fields[msgs[mi].nfields++];
    memset(f,0,sizeof(*f));
    f->type=FT_MAP;
    next_tok(); /* < */
    next_tok(); /* key type */
    f->map_key_type=parse_scalar_type(tk_str);
    next_tok(); /* , */
    next_tok(); /* value type */
    strcpy(f->map_value_type_name,tk_str);
    FieldType st=parse_scalar_type(tk_str);
    if(st!=(FieldType)-1)f->map_value_type=st;
    else f->map_value_type=(FieldType)-2; /* message or enum, resolve later */
    next_tok(); /* > */
    next_tok(); /* name */
    strcpy(f->name,tk_str);
    to_lower_camel(f->name,f->jname);
    next_tok(); /* = */
    next_tok(); /* number */
    f->number=(int)tk_num;
    next_tok();
    if(tk_type==TK_PUNCT&&tk_ch=='[')skip_to_close_bracket();
    if(tk_type==TK_PUNCT&&tk_ch==';')next_tok();
}
static void parse_enum(void){
    next_tok(); /* name */
    int ei=nenums++;
    strcpy(enums[ei].name,tk_str);
    enums[ei].nvals=0;
    next_tok(); /* { */
    next_tok();
    while(tk_type!=TK_EOF&&!(tk_type==TK_PUNCT&&tk_ch=='}')){
        if(tk_type==TK_IDENT&&(!strcmp(tk_str,"option")||!strcmp(tk_str,"reserved"))){skip_to_semi();}
        else if(tk_type==TK_IDENT){
            strcpy(enums[ei].vals[enums[ei].nvals].name,tk_str);
            next_tok(); /* = */
            next_tok();
            int val;
            if(tk_type==TK_PUNCT&&tk_ch=='-'){next_tok();val=-(int)tk_num;}
            else val=(int)tk_num;
            enums[ei].vals[enums[ei].nvals].val=val;
            enums[ei].nvals++;
            next_tok();
            if(tk_type==TK_PUNCT&&tk_ch=='[')skip_to_close_bracket();
            if(tk_type==TK_PUNCT&&tk_ch==';')next_tok();
        } else next_tok();
    }
    next_tok(); /* } */
}
static void parse_message(void){
    next_tok(); /* name */
    int mi=nmsgs++;
    strcpy(msgs[mi].name,tk_str);
    msgs[mi].nfields=0; msgs[mi].noneofs=0;
    if(!found_root){strcpy(root_name,tk_str);found_root=1;}
    next_tok(); /* { */
    next_tok();
    while(tk_type!=TK_EOF&&!(tk_type==TK_PUNCT&&tk_ch=='}')){
        if(tk_type==TK_IDENT&&!strcmp(tk_str,"message")){parse_message();}
        else if(tk_type==TK_IDENT&&!strcmp(tk_str,"enum")){parse_enum();}
        else if(tk_type==TK_IDENT&&!strcmp(tk_str,"oneof")){
            next_tok(); int oi=msgs[mi].noneofs++;
            strcpy(msgs[mi].oneof_names[oi],tk_str);
            next_tok(); /* { */
            next_tok();
            while(tk_type!=TK_EOF&&!(tk_type==TK_PUNCT&&tk_ch=='}')){
                if(tk_type==TK_IDENT&&!strcmp(tk_str,"option")){skip_to_semi();}
                else if(tk_type==TK_IDENT&&!strcmp(tk_str,"reserved")){skip_to_semi();}
                else if(tk_type==TK_IDENT&&!strcmp(tk_str,"map")){
                    int fi=msgs[mi].nfields;
                    parse_map_field(mi);
                    msgs[mi].fields[fi].in_oneof=1;
                    msgs[mi].fields[fi].oneof_idx=oi;
                }
                else if(tk_type==TK_IDENT){
                    int fi=msgs[mi].nfields;
                    parse_field(mi,NULL);
                    msgs[mi].fields[fi].in_oneof=1;
                    msgs[mi].fields[fi].oneof_idx=oi;
                }
                else next_tok();
            }
            next_tok(); /* } */
        }
        else if(tk_type==TK_IDENT&&!strcmp(tk_str,"option")){skip_to_semi();}
        else if(tk_type==TK_IDENT&&!strcmp(tk_str,"reserved")){skip_to_semi();}
        else if(tk_type==TK_IDENT&&!strcmp(tk_str,"map")){parse_map_field(mi);}
        else if(tk_type==TK_IDENT&&(!strcmp(tk_str,"repeated")||!strcmp(tk_str,"optional"))){
            char lbl[16];strcpy(lbl,tk_str);parse_field(mi,lbl);
        }
        else if(tk_type==TK_IDENT){parse_field(mi,NULL);}
        else next_tok();
    }
    next_tok(); /* } */
}
static void parse_proto(void){
    next_tok();
    while(tk_type!=TK_EOF){
        if(tk_type==TK_IDENT&&(!strcmp(tk_str,"syntax")||!strcmp(tk_str,"package")||!strcmp(tk_str,"option"))){skip_to_semi();}
        else if(tk_type==TK_IDENT&&!strcmp(tk_str,"message")){parse_message();}
        else if(tk_type==TK_IDENT&&!strcmp(tk_str,"enum")){parse_enum();}
        else next_tok();
    }
}
static void resolve_all_types(void){
    for(int mi=0;mi<nmsgs;mi++){
        for(int fi=0;fi<msgs[mi].nfields;fi++){
            FieldDef *f=&msgs[mi].fields[fi];
            if(f->type==FT_MAP){
                if(f->map_value_type==(FieldType)-2){
                    FieldType out;char tn[128];
                    resolve_type_name(f->map_value_type_name,&out,tn);
                    f->map_value_type=out;
                }
            } else if(f->type!=(FieldType)-1){
                /* already scalar */
            } else {
                FieldType out;char tn[128];
                resolve_type_name(f->type_name,&out,tn);
                f->type=out;
                if(out==FT_MESSAGE||out==FT_ENUM)strcpy(f->type_name,tn);
            }
        }
    }
}

/* ===== Binary Reader ===== */
static uint64_t read_varint(const uint8_t *d,int *pos,int len){
    uint64_t v=0;int shift=0;
    while(*pos<len){uint8_t b=d[(*pos)++];v|=(uint64_t)(b&0x7F)<<shift;if(!(b&0x80))break;shift+=7;}
    return v;
}
static uint32_t read_fixed32(const uint8_t *d,int *pos,int len){
    uint32_t v=0;if(*pos+4<=len){memcpy(&v,d+*pos,4);}*pos+=4;return v;
}
static uint64_t read_fixed64(const uint8_t *d,int *pos,int len){
    uint64_t v=0;if(*pos+8<=len){memcpy(&v,d+*pos,8);}*pos+=8;return v;
}

/* ===== Decoded Message Structures ===== */
typedef struct DecMsg DecMsg;
typedef struct{int64_t i64;uint64_t u64;char *bytes;int bytes_len;DecMsg *msg;}Val;
typedef struct{int64_t key_i64;char *key_str;int key_str_len;Val val;}MapEntry;
typedef struct{
    int occurred;Val val;
    Val *elems;int nelems,capelems;
    MapEntry *map_entries;int nmap,capmap;
}Slot;
struct DecMsg{MsgDef *def;Slot *slots;int *oneof_set;};

static MsgDef *get_msg_def(const char *n){for(int i=0;i<nmsgs;i++)if(!strcmp(msgs[i].name,n))return &msgs[i];return NULL;}
static EnumDef *get_enum_def(const char *n){for(int i=0;i<nenums;i++)if(!strcmp(enums[i].name,n))return &enums[i];return NULL;}
static int find_field(MsgDef *def,int num){for(int i=0;i<def->nfields;i++)if(def->fields[i].number==num)return i;return -1;}

static DecMsg *new_msg(MsgDef *def){
    DecMsg *m=calloc(1,sizeof(DecMsg));
    m->def=def;
    m->slots=calloc(def->nfields>0?def->nfields:1,sizeof(Slot));
    m->oneof_set=calloc(def->noneofs>0?def->noneofs:1,sizeof(int));
    for(int i=0;i<def->noneofs;i++)m->oneof_set[i]=-1;
    return m;
}
static void append_val(Slot *s,Val v){
    if(s->nelems>=s->capelems){s->capelems=s->capelems?s->capelems*2:4;s->elems=realloc(s->elems,s->capelems*sizeof(Val));}
    s->elems[s->nelems++]=v;
}
static void append_msg_elem(Slot *s,DecMsg *m){
    Val v={0};v.msg=m;append_val(s,v);
}
static void append_map_entry(Slot *s,MapEntry e){
    if(s->nmap>=s->capmap){s->capmap=s->capmap?s->capmap*2:4;s->map_entries=realloc(s->map_entries,s->capmap*sizeof(MapEntry));}
    s->map_entries[s->nmap++]=e;
}
static void clear_slot(Slot *s){memset(s,0,sizeof(*s));}

/* ===== Decoder ===== */
static int is_packed_type(FieldType t){
    return t==FT_INT32||t==FT_INT64||t==FT_UINT32||t==FT_UINT64||t==FT_SINT32||t==FT_SINT64||
           t==FT_BOOL||t==FT_ENUM||t==FT_FIXED32||t==FT_FIXED64||t==FT_SFIXED32||t==FT_SFIXED64;
}
static int elem_wt(FieldType t){
    if(t==FT_FIXED32||t==FT_SFIXED32)return 5;
    if(t==FT_FIXED64||t==FT_SFIXED64)return 1;
    return 0;
}
static Val decode_scalar(const uint8_t *d,int *pos,int len,FieldType ft,int wt){
    Val v={0};
    if(wt==0){
        uint64_t raw=read_varint(d,pos,len);
        switch(ft){
            case FT_INT32:v.i64=(int32_t)(uint32_t)raw;break;
            case FT_INT64:v.i64=(int64_t)raw;break;
            case FT_UINT32:v.u64=(uint32_t)raw;break;
            case FT_UINT64:v.u64=raw;break;
            case FT_SINT32:{uint32_t x=(uint32_t)raw;v.i64=(int32_t)((x>>1)^-(int32_t)(x&1));}break;
            case FT_SINT64:{uint64_t x=raw;v.i64=(int64_t)((x>>1)^-(int64_t)(x&1));}break;
            case FT_BOOL:v.i64=(raw!=0);break;
            case FT_ENUM:v.i64=(int32_t)(uint32_t)raw;break;
            default:break;
        }
    }else if(wt==1){
        uint64_t raw=read_fixed64(d,pos,len);
        if(ft==FT_FIXED64)v.u64=raw;
        else if(ft==FT_SFIXED64)v.i64=(int64_t)raw;
    }else if(wt==5){
        uint32_t raw=read_fixed32(d,pos,len);
        if(ft==FT_FIXED32)v.u64=raw;
        else if(ft==FT_SFIXED32)v.i64=(int32_t)raw;
    }else if(wt==2){
        int slen=(int)read_varint(d,pos,len);
        if(slen<0)slen=0;
        if(*pos+slen>len)slen=len-*pos;
        if(ft==FT_STRING||ft==FT_BYTES){
            v.bytes=malloc(slen+1);memcpy(v.bytes,d+*pos,slen);v.bytes[slen]=0;v.bytes_len=slen;
        }
        *pos+=slen;
    }
    return v;
}
static void skip_field(const uint8_t *d,int *pos,int len,int wt,int fn){
    switch(wt){
        case 0:read_varint(d,pos,len);break;
        case 1:*pos+=8;break;
        case 2:{int l=(int)read_varint(d,pos,len);*pos+=l;}break;
        case 5:*pos+=4;break;
        case 3:{while(*pos<len){uint64_t k=read_varint(d,pos,len);int w=(int)(k&7),f=(int)(k>>3);if(w==4&&f==fn)break;skip_field(d,pos,len,w,f);}}break;
        case 4:break;
    }
}
static void decode_map_entry(DecMsg *msg,int fi,const uint8_t *d,int len){
    FieldDef *fd=&msg->def->fields[fi];
    Slot *slot=&msg->slots[fi];
    int64_t key_i64=0;char *key_str=NULL;int key_str_len=0;
    Val val={0};
    int pos=0;
    while(pos<len){
        uint64_t k=read_varint(d,&pos,len);
        int fn=(int)(k>>3),wt=(int)(k&7);
        if(fn==1){
            if(fd->map_key_type==FT_STRING){
                int slen=(int)read_varint(d,&pos,len);
                if(pos+slen>len)slen=len-pos;
                key_str=malloc(slen+1);memcpy(key_str,d+pos,slen);key_str[slen]=0;key_str_len=slen;pos+=slen;
            }else{key_i64=(int32_t)(uint32_t)read_varint(d,&pos,len);}
        }else if(fn==2){
            if(fd->map_value_type==FT_MESSAGE){
                int slen=(int)read_varint(d,&pos,len);
                if(pos+slen>len)slen=len-pos;
                MsgDef *md=get_msg_def(fd->map_value_type_name);
                if(md){val.msg=new_msg(md);decode_msg(val.msg,d+pos,slen);}
                pos+=slen;
            }else{
                val=decode_scalar(d,&pos,len,fd->map_value_type,wt);
            }
        }else{skip_field(d,&pos,len,wt,fn);}
    }
    /* find existing entry with same key */
    int found=-1;
    for(int i=0;i<slot->nmap;i++){
        if(fd->map_key_type==FT_STRING){
            if(slot->map_entries[i].key_str_len==key_str_len&&key_str&&slot->map_entries[i].key_str&&
               memcmp(slot->map_entries[i].key_str,key_str,key_str_len)==0){found=i;break;}
        }else{
            if(slot->map_entries[i].key_i64==key_i64){found=i;break;}
        }
    }
    MapEntry e={key_i64,key_str,key_str_len,val};
    if(found>=0){
        /* free old value msg if any */
        slot->map_entries[found].val=val;
        slot->map_entries[found].key_str=key_str;
        slot->map_entries[found].key_str_len=key_str_len;
    }else{
        append_map_entry(slot,e);
    }
}
void decode_msg(DecMsg *msg,const uint8_t *d,int len);
void decode_msg(DecMsg *msg,const uint8_t *d,int len){
    int pos=0;
    while(pos<len){
        uint64_t key=read_varint(d,&pos,len);
        int fnum=(int)(key>>3),wt=(int)(key&7);
        int fi=find_field(msg->def,fnum);
        if(fi<0){skip_field(d,&pos,len,wt,fnum);continue;}
        FieldDef *fd=&msg->def->fields[fi];
        Slot *slot=&msg->slots[fi];
        /* oneof handling */
        if(fd->in_oneof){
            int oi=fd->oneof_idx;
            if(msg->oneof_set[oi]!=fi){
                if(msg->oneof_set[oi]>=0)clear_slot(&msg->slots[msg->oneof_set[oi]]);
                msg->oneof_set[oi]=fi;
            }
        }
        if(fd->type==FT_MAP){
            int slen=(int)read_varint(d,&pos,len);
            if(pos+slen>len)slen=len-pos;
            decode_map_entry(msg,fi,d+pos,slen);
            pos+=slen;
        }else if(fd->is_repeated&&is_packed_type(fd->type)&&wt==2){
            int slen=(int)read_varint(d,&pos,len);
            if(pos+slen>len)slen=len-pos;
            int ppos=0;int ewt=elem_wt(fd->type);
            while(ppos<slen){Val v=decode_scalar(d+pos,&ppos,slen,fd->type,ewt);append_val(slot,v);}
            pos+=slen;
        }else if(fd->type==FT_MESSAGE){
            int slen=(int)read_varint(d,&pos,len);
            if(pos+slen>len)slen=len-pos;
            MsgDef *md=get_msg_def(fd->type_name);
            if(!md){pos+=slen;continue;}
            if(fd->is_repeated){
                DecMsg *sub=new_msg(md);decode_msg(sub,d+pos,slen);append_msg_elem(slot,sub);
            }else{
                if(!slot->val.msg)slot->val.msg=new_msg(md);
                decode_msg(slot->val.msg,d+pos,slen);
                slot->occurred=1;
            }
            pos+=slen;
        }else{
            Val v=decode_scalar(d,&pos,len,fd->type,wt);
            if(fd->is_repeated){append_val(slot,v);}
            else{slot->val=v;slot->occurred=1;}
        }
    }
}

/* ===== JSON Output ===== */
static void print_json_str(SB *out,const char *s,int len){
    for(int i=0;i<len;i++){
        unsigned char c=(unsigned char)s[i];
        if(c=='"')sb_s(out,"\\\"");
        else if(c=='\\')sb_s(out,"\\\\");
        else if(c=='\b')sb_s(out,"\\b");
        else if(c=='\t')sb_s(out,"\\t");
        else if(c=='\n')sb_s(out,"\\n");
        else if(c=='\f')sb_s(out,"\\f");
        else if(c=='\r')sb_s(out,"\\r");
        else if(c<0x20)sb_f(out,"\\u%04x",c);
        else sb_c(out,(char)c);
    }
}
static void base64_enc(SB *out,const char *d,int len){
    static const char tbl[]="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
    int i=0;
    while(i<len){
        uint32_t n=((uint8_t)d[i])<<16;
        if(i+1<len)n|=((uint8_t)d[i+1])<<8;
        if(i+2<len)n|=((uint8_t)d[i+2]);
        sb_c(out,tbl[(n>>18)&0x3F]);
        sb_c(out,tbl[(n>>12)&0x3F]);
        sb_c(out,i+1<len?tbl[(n>>6)&0x3F]:'=');
        sb_c(out,i+2<len?tbl[n&0x3F]:'=');
        i+=3;
    }
}
static void print_scalar(SB *out,FieldType ft,const char *type_name,Val *v){
    switch(ft){
        case FT_INT32:case FT_SINT32:case FT_SFIXED32:sb_f(out,"%lld",(long long)v->i64);break;
        case FT_UINT32:case FT_FIXED32:sb_f(out,"%llu",(unsigned long long)v->u64);break;
        case FT_INT64:case FT_SINT64:case FT_SFIXED64:sb_c(out,'"');sb_f(out,"%lld",(long long)v->i64);sb_c(out,'"');break;
        case FT_UINT64:case FT_FIXED64:sb_c(out,'"');sb_f(out,"%llu",(unsigned long long)v->u64);sb_c(out,'"');break;
        case FT_BOOL:sb_s(out,v->i64?"true":"false");break;
        case FT_ENUM:{
            EnumDef *ed=get_enum_def(type_name);
            int found=0;
            if(ed){for(int i=0;i<ed->nvals;i++){if(ed->vals[i].val==(int)v->i64){sb_c(out,'"');sb_s(out,ed->vals[i].name);sb_c(out,'"');found=1;break;}}}
            if(!found)sb_f(out,"%lld",(long long)v->i64);
        }break;
        case FT_STRING:sb_c(out,'"');print_json_str(out,v->bytes?v->bytes:"",v->bytes_len);sb_c(out,'"');break;
        case FT_BYTES:sb_c(out,'"');base64_enc(out,v->bytes?v->bytes:"",v->bytes_len);sb_c(out,'"');break;
        default:sb_c(out,'"');sb_c(out,'"');break;
    }
}
static void print_msg(SB *out,DecMsg *msg);
static int is_default(FieldType ft,Val *v){
    switch(ft){
        case FT_INT32:case FT_INT64:case FT_SINT32:case FT_SINT64:case FT_SFIXED32:case FT_SFIXED64:return v->i64==0;
        case FT_UINT32:case FT_UINT64:case FT_FIXED32:case FT_FIXED64:return v->u64==0;
        case FT_BOOL:case FT_ENUM:return v->i64==0;
        case FT_STRING:case FT_BYTES:return v->bytes_len==0;
        default:return 0;
    }
}
static int should_print(int fi,FieldDef *fd,Slot *slot,DecMsg *msg){
    if(fd->type==FT_MAP)return slot->nmap>0;
    if(fd->is_repeated)return slot->nelems>0;
    if(fd->type==FT_MESSAGE)return slot->occurred;
    if(fd->in_oneof)return msg->oneof_set[fd->oneof_idx]==fi;
    if(!slot->occurred)return 0;
    if(fd->is_optional)return 1;
    return !is_default(fd->type,&slot->val);
}
static int map_key_cmp(FieldDef *fd,MapEntry *a,MapEntry *b){
    if(fd->map_key_type==FT_STRING){
        int ml=a->key_str_len<b->key_str_len?a->key_str_len:b->key_str_len;
        int r=memcmp(a->key_str?a->key_str:"",b->key_str?b->key_str:"",ml);
        if(r)return r;
        return a->key_str_len-b->key_str_len;
    }
    if(a->key_i64<b->key_i64)return -1;
    if(a->key_i64>b->key_i64)return 1;
    return 0;
}
static void print_map(SB *out,FieldDef *fd,Slot *slot){
    sb_c(out,'{');
    /* sort */
    for(int i=1;i<slot->nmap;i++){
        MapEntry tmp=slot->map_entries[i];int j=i-1;
        while(j>=0&&map_key_cmp(fd,&slot->map_entries[j],&tmp)>0){slot->map_entries[j+1]=slot->map_entries[j];j--;}
        slot->map_entries[j+1]=tmp;
    }
    for(int i=0;i<slot->nmap;i++){
        if(i>0)sb_c(out,',');
        sb_c(out,'"');
        if(fd->map_key_type==FT_STRING)print_json_str(out,slot->map_entries[i].key_str?slot->map_entries[i].key_str:"",slot->map_entries[i].key_str_len);
        else sb_f(out,"%lld",(long long)slot->map_entries[i].key_i64);
        sb_s(out,"\":");
        Val *v=&slot->map_entries[i].val;
        if(fd->map_value_type==FT_MESSAGE){
            if(v->msg)print_msg(out,v->msg);else sb_s(out,"{}");
        }else{
            print_scalar(out,fd->map_value_type,fd->map_value_type_name,v);
        }
    }
    sb_c(out,'}');
}
static void print_msg(SB *out,DecMsg *msg){
    sb_c(out,'{');
    int n=msg->def->nfields;
    int order[MAX_FIELDS];
    for(int i=0;i<n;i++)order[i]=i;
    for(int i=0;i<n-1;i++)for(int j=i+1;j<n;j++)
        if(msg->def->fields[order[j]].number<msg->def->fields[order[i]].number){int t=order[i];order[i]=order[j];order[j]=t;}
    int first=1;
    for(int i=0;i<n;i++){
        int fi=order[i];
        FieldDef *fd=&msg->def->fields[fi];
        Slot *slot=&msg->slots[fi];
        if(!should_print(fi,fd,slot,msg))continue;
        if(!first)sb_c(out,',');first=0;
        sb_c(out,'"');sb_s(out,fd->jname);sb_s(out,"\":");
        if(fd->type==FT_MAP){print_map(out,fd,slot);}
        else if(fd->is_repeated){
            sb_c(out,'[');
            for(int j=0;j<slot->nelems;j++){
                if(j>0)sb_c(out,',');
                if(fd->type==FT_MESSAGE){if(slot->elems[j].msg)print_msg(out,slot->elems[j].msg);else sb_s(out,"{}");}
                else print_scalar(out,fd->type,fd->type_name,&slot->elems[j]);
            }
            sb_c(out,']');
        }else if(fd->type==FT_MESSAGE){
            if(slot->val.msg)print_msg(out,slot->val.msg);else sb_s(out,"{}");
        }else{
            print_scalar(out,fd->type,fd->type_name,&slot->val);
        }
    }
    sb_c(out,'}');
}

/* ===== Main ===== */
int main(int argc,char **argv){
    (void)argc;(void)argv;
    /* read schema */
    FILE *f=fopen("schema.proto","rb");
    if(!f){fprintf(stderr,"cannot open schema.proto\n");return 1;}
    fseek(f,0,SEEK_END);long fsz=ftell(f);fseek(f,0,SEEK_SET);
    char *src=malloc(fsz+1);fread(src,1,fsz,f);src[fsz]=0;fclose(f);
    g_src=src;g_src_end=src+fsz;
    parse_proto();
    resolve_all_types();

    /* read messages.bin */
    f=fopen("messages.bin","rb");
    if(!f){fprintf(stderr,"cannot open messages.bin\n");return 1;}
    fseek(f,0,SEEK_END);long bsz=ftell(f);fseek(f,0,SEEK_SET);
    uint8_t *bin=malloc(bsz);fread(bin,1,bsz,f);fclose(f);

    MsgDef *root=get_msg_def(root_name);
    if(!root)return 0;

    int pos=0;
    while(pos<bsz){
        uint64_t rlen=read_varint(bin,&pos,bsz);
        if(pos+(int)rlen>bsz)rlen=bsz-pos;
        DecMsg *m=new_msg(root);
        decode_msg(m,bin+pos,(int)rlen);
        pos+=rlen;
        SB out;sb_init(&out);
        print_msg(&out,m);
        printf("%s\n",out.buf);
        free(out.buf);
    }
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <ctype.h>
#include <stdarg.h>

/* ===== String Buffer ===== */
typedef struct { char *buf; size_t len, cap; } SB;
static void sb_init(SB *s){s->cap=1024;s->buf=malloc(s->cap);s->len=0;s->buf[0]=0;}
static void sb_ens(SB *s,size_t n){if(s->len+n+1>s->cap){while(s->len+n+1>s->cap)s->cap*=2;s->buf=realloc(s->buf,s->cap);}}
static void sb_c(SB *s,char c){sb_ens(s,1);s->buf[s->len++]=c;s->buf[s->len]=0;}
static void sb_s(SB *s,const char *t){size_t l=strlen(t);sb_ens(s,l);memcpy(s->buf+s->len,t,l);s->len+=l;s->buf[s->len]=0;}
static void sb_n(SB *s,const char *t,size_t n){sb_ens(s,n);memcpy(s->buf+s->len,t,n);s->len+=n;s->buf[s->len]=0;}
static void sb_f(SB *s,const char *fmt,...){va_list ap;va_start(ap,fmt);char tmp[512];int n=vsnprintf(tmp,512,fmt,ap);va_end(ap);sb_ens(s,n);memcpy(s->buf+s->len,tmp,n);s->len+=n;s->buf[s->len]=0;}

/* ===== Proto Lexer ===== */
static const char *g_src, *g_src_end;
typedef enum{TK_EOF,TK_IDENT,TK_NUM,TK_STR,TK_PUNCT}TokType;
static TokType tk_type;
static char tk_str[4096];
static long long tk_num;
static char tk_ch;

static void skip_ws(void){
    while(g_src<g_src_end){
        if(isspace((unsigned char)*g_src)){g_src++;}
        else if(g_src+1<g_src_end&&g_src[0]=='/'&&g_src[1]=='/'){g_src+=2;while(g_src<g_src_end&&*g_src!='\n')g_src++;}
        else if(g_src+1<g_src_end&&g_src[0]=='/'&&g_src[1]=='*'){g_src+=2;while(g_src+1<g_src_end&&!(g_src[0]=='*'&&g_src[1]=='/'))g_src++;if(g_src+1<g_src_end)g_src+=2;}
        else break;
    }
}
static void next_tok(void){
    skip_ws();
    if(g_src>=g_src_end){tk_type=TK_EOF;return;}
    if(*g_src=='"'){g_src++;int i=0;while(g_src<g_src_end&&*g_src!='"'){if(i<4095)tk_str[i++]=*g_src;else g_src++;if(i<4095)tk_str[i]=*g_src;g_src++;}tk_str[i]=0;if(g_src<g_src_end)g_src++;tk_type=TK_STR;}
    else if(isalpha((unsigned char)*g_src)||*g_src=='_'){int i=0;while(g_src<g_src_end&&(isalnum((unsigned char)*g_src)||*g_src=='_')){if(i<4095)tk_str[i++]=*g_src;g_src++;}tk_str[i]=0;tk_type=TK_IDENT;}
    else if(isdigit((unsigned char)*g_src)){int i=0;while(g_src<g_src_end&&isdigit((unsigned char)*g_src)){if(i<4095)tk_str[i++]=*g_src;g_src++;}tk_str[i]=0;tk_num=strtoll(tk_str,NULL,10);tk_type=TK_NUM;}
    else{tk_ch=*g_src++;tk_type=TK_PUNCT;}
}
static void skip_to_semi(void){while(tk_type!=TK_EOF){if(tk_type==TK_PUNCT&&tk_ch==';'){next_tok();return;}next_tok();}}
static void skip_to_close_bracket(void){int d=1;while(tk_type!=TK_EOF&&d>0){if(tk_type==TK_PUNCT&&tk_ch=='[')d++;else if(tk_type==TK_PUNCT&&tk_ch==']')d--;if(d>0)next_tok();}if(tk_type==TK_PUNCT&&tk_ch==']')next_tok();}

/* ===== Schema Structures ===== */
#define MAX_MSGS 512
#define MAX_ENUMS 256
#define MAX_FIELDS 256
#define MAX_ENUM_VALS 256
#define MAX_ONEOFS 64

typedef enum{FT_INT32,FT_INT64,FT_UINT32,FT_UINT64,FT_SINT32,FT_SINT64,FT_BOOL,FT_STRING,FT_BYTES,
FT_FIXED32,FT_FIXED64,FT_SFIXED32,FT_SFIXED64,FT_ENUM,FT_MESSAGE,FT_MAP}FieldType;

typedef struct{
    char name[128]; char jname[128]; int number; FieldType type;
    int is_repeated, is_optional, in_oneof, oneof_idx;
    char type_name[128];
    FieldType map_key_type, map_value_type;
    char map_value_type_name[128];
}FieldDef;

typedef struct{
    char name[128]; int nfields; FieldDef fields[MAX_FIELDS];
    int noneofs; char oneof_names[MAX_ONEOFS][128];
}MsgDef;

typedef struct{
    char name[128]; int nvals;
    struct{int val;char name[128];}vals[MAX_ENUM_VALS];
}EnumDef;

static MsgDef msgs[MAX_MSGS]; static int nmsgs=0;
static EnumDef enums[MAX_ENUMS]; static int nenums=0;
static char root_name[128]; static int found_root=0;

/* ===== Proto Parser ===== */
static FieldType parse_scalar_type(const char *n){
    if(!strcmp(n,"int32"))return FT_INT32; if(!strcmp(n,"int64"))return FT_INT64;
    if(!strcmp(n,"uint32"))return FT_UINT32; if(!strcmp(n,"uint64"))return FT_UINT64;
    if(!strcmp(n,"sint32"))return FT_SINT32; if(!strcmp(n,"sint64"))return FT_SINT64;
    if(!strcmp(n,"bool"))return FT_BOOL; if(!strcmp(n,"string"))return FT_STRING;
    if(!strcmp(n,"bytes"))return FT_BYTES; if(!strcmp(n,"fixed32"))return FT_FIXED32;
    if(!strcmp(n,"fixed64"))return FT_FIXED64; if(!strcmp(n,"sfixed32"))return FT_SFIXED32;
    if(!strcmp(n,"sfixed64"))return FT_SFIXED64;
    return (FieldType)-1;
}
static void resolve_type_name(const char *n, FieldType *out, char *tn){
    FieldType st=parse_scalar_type(n);
    if(st!=(FieldType)-1){*out=st;tn[0]=0;return;}
    for(int i=0;i<nmsgs;i++)if(!strcmp(msgs[i].name,n)){*out=FT_MESSAGE;strcpy(tn,n);return;}
    for(int i=0;i<nenums;i++)if(!strcmp(enums[i].name,n)){*out=FT_ENUM;strcpy(tn,n);return;}
    *out=FT_INT32;tn[0]=0;
}
static void to_lower_camel(const char *n, char *out){
    int j=0,up=0;
    for(int i=0;n[i];i++){
        if(n[i]=='_'){up=1;}
        else{if(up&&n[i]>='a'&&n[i]<='z')out[j++]=n[i]-'a'+'A';else out[j++]=n[i];up=0;}
    }
    out[j]=0;
}
static void parse_field(int mi, const char *label){
    FieldDef *f=&msgs[mi].fields[msgs[mi].nfields++];
    memset(f,0,sizeof(*f));
    f->type=(FieldType)-1; /* needs resolution */
    f->is_repeated=(label&&!strcmp(label,"repeated"));
    f->is_optional=(label&&!strcmp(label,"optional"));
    if(label)next_tok();
    /* tok is type name */
    strcpy(f->type_name,tk_str);
    next_tok(); /* field name */
    strcpy(f->name,tk_str);
    to_lower_camel(f->name,f->jname);
    next_tok(); /* = */
    next_tok(); /* number */
    if(tk_type==TK_PUNCT&&tk_ch=='-'){next_tok();f->number=-(int)tk_num;}
    else f->number=(int)tk_num;
    next_tok();
    if(tk_type==TK_PUNCT&&tk_ch=='[')skip_to_close_bracket();
    if(tk_type==TK_PUNCT&&tk_ch==';')next_tok();
}
static void parse_map_field(int mi){
    FieldDef *f=&msgs[mi].fields[msgs[mi].nfields++];
    memset(f,0,sizeof(*f));
    f->type=FT_MAP;
    next_tok(); /* < */
    next_tok(); /* key type */
    f->map_key_type=parse_scalar_type(tk_str);
    next_tok(); /* , */
    next_tok(); /* value type */
    strcpy(f->map_value_type_name,tk_str);
    FieldType st=parse_scalar_type(tk_str);
    if(st!=(FieldType)-1)f->map_value_type=st;
    else f->map_value_type=(FieldType)-2; /* message or enum, resolve later */
    next_tok(); /* > */
    next_tok(); /* name */
    strcpy(f->name,tk_str);
    to_lower_camel(f->name,f->jname);
    next_tok(); /* = */
    next_tok(); /* number */
    f->number=(int)tk_num;
    next_tok();
    if(tk_type==TK_PUNCT&&tk_ch=='[')skip_to_close_bracket();
    if(tk_type==TK_PUNCT&&tk_ch==';')next_tok();
}
static void parse_enum(void){
    next_tok(); /* name */
    int ei=nenums++;
    strcpy(enums[ei].name,tk_str);
    enums[ei].nvals=0;
    next_tok(); /* { */
    next_tok();
    while(tk_type!=TK_EOF&&!(tk_type==TK_PUNCT&&tk_ch=='}')){
        if(tk_type==TK_IDENT&&(!strcmp(tk_str,"option")||!strcmp(tk_str,"reserved"))){skip_to_semi();}
        else if(tk_type==TK_IDENT){
            strcpy(enums[ei].vals[enums[ei].nvals].name,tk_str);
            next_tok(); /* = */
            next_tok();
            int val;
            if(tk_type==TK_PUNCT&&tk_ch=='-'){next_tok();val=-(int)tk_num;}
            else val=(int)tk_num;
            enums[ei].vals[enums[ei].nvals].val=val;
            enums[ei].nvals++;
            next_tok();
            if(tk_type==TK_PUNCT&&tk_ch=='[')skip_to_close_bracket();
            if(tk_type==TK_PUNCT&&tk_ch==';')next_tok();
        } else next_tok();
    }
    next_tok(); /* } */
}
static void parse_message(void){
    next_tok(); /* name */
    int mi=nmsgs++;
    strcpy(msgs[mi].name,tk_str);
    msgs[mi].nfields=0; msgs[mi].noneofs=0;
    if(!found_root){strcpy(root_name,tk_str);found_root=1;}
    next_tok(); /* { */
    next_tok();
    while(tk_type!=TK_EOF&&!(tk_type==TK_PUNCT&&tk_ch=='}')){
        if(tk_type==TK_IDENT&&!strcmp(tk_str,"message")){parse_message();}
        else if(tk_type==TK_IDENT&&!strcmp(tk_str,"enum")){parse_enum();}
        else if(tk_type==TK_IDENT&&!strcmp(tk_str,"oneof")){
            next_tok(); int oi=msgs[mi].noneofs++;
            strcpy(msgs[mi].oneof_names[oi],tk_str);
            next_tok(); /* { */
            next_tok();
            while(tk_type!=TK_EOF&&!(tk_type==TK_PUNCT&&tk_ch=='}')){
                if(tk_type==TK_IDENT&&!strcmp(tk_str,"option")){skip_to_semi();}
                else if(tk_type==TK_IDENT&&!strcmp(tk_str,"reserved")){skip_to_semi();}
                else if(tk_type==TK_IDENT&&!strcmp(tk_str,"map")){
                    int fi=msgs[mi].nfields;
                    parse_map_field(mi);
                    msgs[mi].fields[fi].in_oneof=1;
                    msgs[mi].fields[fi].oneof_idx=oi;
                }
                else if(tk_type==TK_IDENT){
                    int fi=msgs[mi].nfields;
                    parse_field(mi,NULL);
                    msgs[mi].fields[fi].in_oneof=1;
                    msgs[mi].fields[fi].oneof_idx=oi;
                }
                else next_tok();
            }
            next_tok(); /* } */
        }
        else if(tk_type==TK_IDENT&&!strcmp(tk_str,"option")){skip_to_semi();}
        else if(tk_type==TK_IDENT&&!strcmp(tk_str,"reserved")){skip_to_semi();}
        else if(tk_type==TK_IDENT&&!strcmp(tk_str,"map")){parse_map_field(mi);}
        else if(tk_type==TK_IDENT&&(!strcmp(tk_str,"repeated")||!strcmp(tk_str,"optional"))){
            char lbl[16];strcpy(lbl,tk_str);parse_field(mi,lbl);
        }
        else if(tk_type==TK_IDENT){parse_field(mi,NULL);}
        else next_tok();
    }
    next_tok(); /* } */
}
static void parse_proto(void){
    next_tok();
    while(tk_type!=TK_EOF){
        if(tk_type==TK_IDENT&&(!strcmp(tk_str,"syntax")||!strcmp(tk_str,"package")||!strcmp(tk_str,"option"))){skip_to_semi();}
        else if(tk_type==TK_IDENT&&!strcmp(tk_str,"message")){parse_message();}
        else if(tk_type==TK_IDENT&&!strcmp(tk_str,"enum")){parse_enum();}
        else next_tok();
    }
}
static void resolve_all_types(void){
    for(int mi=0;mi<nmsgs;mi++){
        for(int fi=0;fi<msgs[mi].nfields;fi++){
            FieldDef *f=&msgs[mi].fields[fi];
            if(f->type==FT_MAP){
                if(f->map_value_type==(FieldType)-2){
                    FieldType out;char tn[128];
                    resolve_type_name(f->map_value_type_name,&out,tn);
                    f->map_value_type=out;
                }
            } else if(f->type!=(FieldType)-1){
                /* already scalar, nothing to do */
            } else {
                FieldType out;char tn[128];
                resolve_type_name(f->type_name,&out,tn);
                f->type=out;
                if(out==FT_MESSAGE||out==FT_ENUM)strcpy(f->type_name,tn);
            }
        }
    }
}

/* ===== Binary Reader ===== */
static uint64_t read_varint(const uint8_t *d,int *pos,int len){
    uint64_t v=0;int shift=0;
    while(*pos<len){uint8_t b=d[(*pos)++];v|=(uint64_t)(b&0x7F)<<shift;if(!(b&0x80))break;shift+=7;}
    return v;
}
static uint32_t read_fixed32(const uint8_t *d,int *pos,int len){
    uint32_t v=0;if(*pos+4<=len){memcpy(&v,d+*pos,4);}*pos+=4;return v;
}
static uint64_t read_fixed64(const uint8_t *d,int *pos,int len){
    uint64_t v=0;if(*pos+8<=len){memcpy(&v,d+*pos,8);}*pos+=8;return v;
}

/* ===== Decoded Message Structures ===== */
typedef struct DecMsg DecMsg;
typedef struct{int64_t i64;uint64_t u64;char *bytes;int bytes_len;DecMsg *msg;}Val;
typedef struct{int64_t key_i64;char *key_str;int key_str_len;Val val;}MapEntry;
typedef struct{
    int occurred;Val val;
    Val *elems;int nelems,capelems;
    MapEntry *map_entries;int nmap,capmap;
}Slot;
struct DecMsg{MsgDef *def;Slot *slots;int *oneof_set;};

static MsgDef *get_msg_def(const char *n){for(int i=0;i<nmsgs;i++)if(!strcmp(msgs[i].name,n))return &msgs[i];return NULL;}
static EnumDef *get_enum_def(const char *n){for(int i=0;i<nenums;i++)if(!strcmp(enums[i].name,n))return &enums[i];return NULL;}
static int find_field(MsgDef *def,int num){for(int i=0;i<def->nfields;i++)if(def->fields[i].number==num)return i;return -1;}

static DecMsg *new_msg(MsgDef *def){
    DecMsg *m=calloc(1,sizeof(DecMsg));
    m->def=def;
    m->slots=calloc(def->nfields>0?def->nfields:1,sizeof(Slot));
    m->oneof_set=calloc(def->noneofs>0?def->noneofs:1,sizeof(int));
    for(int i=0;i<def->noneofs;i++)m->oneof_set[i]=-1;
    return m;
}
static void append_val(Slot *s,Val v){
    if(s->nelems>=s->capelems){s->capelems=s->capelems?s->capelems*2:4;s->elems=realloc(s->elems,s->capelems*sizeof(Val));}
    s->elems[s->nelems++]=v;
}
static void append_msg_elem(Slot *s,DecMsg *m){
    Val v={0};v.msg=m;append_val(s,v);
}
static void append_map_entry(Slot *s,MapEntry e){
    if(s->nmap>=s->capmap){s->capmap=s->capmap?s->capmap*2:4;s->map_entries=realloc(s->map_entries,s->capmap*sizeof(MapEntry));}
    s->map_entries[s->nmap++]=e;
}
static void clear_slot(Slot *s){memset(s,0,sizeof(*s));}

/* ===== Decoder ===== */
static int is_packed_type(FieldType t){
    return t==FT_INT32||t==FT_INT64||t==FT_UINT32||t==FT_UINT64||t==FT_SINT32||t==FT_SINT64||
           t==FT_BOOL||t==FT_ENUM||t==FT_FIXED32||t==FT_FIXED64||t==FT_SFIXED32||t==FT_SFIXED64;
}
static int elem_wt(FieldType t){
    if(t==FT_FIXED32||t==FT_SFIXED32)return 5;
    if(t==FT_FIXED64||t==FT_SFIXED64)return 1;
    return 0;
}
static Val decode_scalar(const uint8_t *d,int *pos,int len,FieldType ft,int wt){
    Val v={0};
    if(wt==0){
        uint64_t raw=read_varint(d,pos,len);
        switch(ft){
            case FT_INT32:v.i64=(int32_t)(uint32_t)raw;break;
            case FT_INT64:v.i64=(int64_t)raw;break;
            case FT_UINT32:v.u64=(uint32_t)raw;break;
            case FT_UINT64:v.u64=raw;break;
            case FT_SINT32:{uint32_t x=(uint32_t)raw;v.i64=(int32_t)((x>>1)^-(int32_t)(x&1));}break;
            case FT_SINT64:{uint64_t x=raw;v.i64=(int64_t)((x>>1)^-(int64_t)(x&1));}break;
            case FT_BOOL:v.i64=(raw!=0);break;
            case FT_ENUM:v.i64=(int32_t)(uint32_t)raw;break;
            default:break;
        }
    }else if(wt==1){
        uint64_t raw=read_fixed64(d,pos,len);
        if(ft==FT_FIXED64)v.u64=raw;
        else if(ft==FT_SFIXED64)v.i64=(int64_t)raw;
    }else if(wt==5){
        uint32_t raw=read_fixed32(d,pos,len);
        if(ft==FT_FIXED32)v.u64=raw;
        else if(ft==FT_SFIXED32)v.i64=(int32_t)raw;
    }else if(wt==2){
        int slen=(int)read_varint(d,pos,len);
        if(slen<0)slen=0;
        if(*pos+slen>len)slen=len-*pos;
        if(ft==FT_STRING||ft==FT_BYTES){
            v.bytes=malloc(slen+1);memcpy(v.bytes,d+*pos,slen);v.bytes[slen]=0;v.bytes_len=slen;
        }
        *pos+=slen;
    }
    return v;
}
static void skip_field(const uint8_t *d,int *pos,int len,int wt,int fn){
    switch(wt){
        case 0:read_varint(d,pos,len);break;
        case 1:*pos+=8;break;
        case 2:{int l=(int)read_varint(d,pos,len);*pos+=l;}break;
        case 5:*pos+=4;break;
        case 3:{while(*pos<len){uint64_t k=read_varint(d,pos,len);int w=(int)(k&7),f=(int)(k>>3);if(w==4&&f==fn)break;skip_field(d,pos,len,w,f);}}break;
        case 4:break;
    }
}

/* Forward declaration */
static void decode_msg(DecMsg *msg,const uint8_t *d,int len);

static void decode_map_entry(DecMsg *msg,int fi,const uint8_t *d,int len){
    FieldDef *fd=&msg->def->fields[fi];
    Slot *slot=&msg->slots[fi];
    int64_t key_i64=0;char *key_str=NULL;int key_str_len=0;
    Val val={0};
    int pos=0;
    while(pos<len){
        uint64_t k=read_varint(d,&pos,len);
        int fn=(int)(k>>3),wt=(int)(k&7);
        if(fn==1){
            if(fd->map_key_type==FT_STRING){
                int slen=(int)read_varint(d,&pos,len);
                if(pos+slen>len)slen=len-pos;
                key_str=malloc(slen+1);memcpy(key_str,d+pos,slen);key_str[slen]=0;key_str_len=slen;pos+=slen;
            }else{key_i64=(int32_t)(uint32_t)read_varint(d,&pos,len);}
        }else if(fn==2){
            if(fd->map_value_type==FT_MESSAGE){
                int slen=(int)read_varint(d,&pos,len);
                if(pos+slen>len)slen=len-pos;
                MsgDef *md=get_msg_def(fd->map_value_type_name);
                if(md){val.msg=new_msg(md);decode_msg(val.msg,d+pos,slen);}
                pos+=slen;
            }else{
                val=decode_scalar(d,&pos,len,fd->map_value_type,wt);
            }
        }else{skip_field(d,&pos,len,wt,fn);}
    }
    /* find existing entry with same key */
    int found=-1;
    for(int i=0;i<slot->nmap;i++){
        if(fd->map_key_type==FT_STRING){
            if(slot->map_entries[i].key_str_len==key_str_len&&key_str&&slot->map_entries[i].key_str&&
               memcmp(slot->map_entries[i].key_str,key_str,key_str_len)==0){found=i;break;}
        }else{
            if(slot->map_entries[i].key_i64==key_i64){found=i;break;}
        }
    }
    MapEntry e={key_i64,key_str,key_str_len,val};
    if(found>=0){
        slot->map_entries[found].val=val;
        slot->map_entries[found].key_str=key_str;
        slot->map_entries[found].key_str_len=key_str_len;
    }else{
        append_map_entry(slot,e);
    }
}
static void decode_msg(DecMsg *msg,const uint8_t *d,int len){
    int pos=0;
    while(pos<len){
        uint64_t key=read_varint(d,&pos,len);
        int fnum=(int)(key>>3),wt=(int)(key&7);
        int fi=find_field(msg->def,fnum);
        if(fi<0){skip_field(d,&pos,len,wt,fnum);continue;}
        FieldDef *fd=&msg->def->fields[fi];
        Slot *slot=&msg->slots[fi];
        /* oneof handling */
        if(fd->in_oneof){
            int oi=fd->oneof_idx;
            if(msg->oneof_set[oi]!=fi){
                if(msg->oneof_set[oi]>=0)clear_slot(&msg->slots[msg->oneof_set[oi]]);
                msg->oneof_set[oi]=fi;
            }
        }
        if(fd->type==FT_MAP){
            int slen=(int)read_varint(d,&pos,len);
            if(pos+slen>len)slen=len-pos;
            decode_map_entry(msg,fi,d+pos,slen);
            pos+=slen;
        }else if(fd->is_repeated&&is_packed_type(fd->type)&&wt==2){
            int slen=(int)read_varint(d,&pos,len);
            if(pos+slen>len)slen=len-pos;
            int ppos=0;int ewt=elem_wt(fd->type);
            while(ppos<slen){Val v=decode_scalar(d+pos,&ppos,slen,fd->type,ewt);append_val(slot,v);}
            pos+=slen;
        }else if(fd->type==FT_MESSAGE){
            int slen=(int)read_varint(d,&pos,len);
            if(pos+slen>len)slen=len-pos;
            MsgDef *md=get_msg_def(fd->type_name);
            if(!md){pos+=slen;continue;}
            if(fd->is_repeated){
                DecMsg *sub=new_msg(md);decode_msg(sub,d+pos,slen);append_msg_elem(slot,sub);
            }else{
                if(!slot->val.msg)slot->val.msg=new_msg(md);
                decode_msg(slot->val.msg,d+pos,slen);
                slot->occurred=1;
            }
            pos+=slen;
        }else{
            Val v=decode_scalar(d,&pos,len,fd->type,wt);
            if(fd->is_repeated){append_val(slot,v);}
            else{slot->val=v;slot->occurred=1;}
        }
    }
}

/* ===== JSON Output ===== */
static void print_json_str(SB *out,const char *s,int len){
    for(int i=0;i<len;i++){
        unsigned char c=(unsigned char)s[i];
        if(c=='"')sb_s(out,"\\\"");
        else if(c=='\\')sb_s(out,"\\\\");
        else if(c=='\b')sb_s(out,"\\b");
        else if(c=='\t')sb_s(out,"\\t");
        else if(c=='\n')sb_s(out,"\\n");
        else if(c=='\f')sb_s(out,"\\f");
        else if(c=='\r')sb_s(out,"\\r");
        else if(c<0x20)sb_f(out,"\\u%04x",c);
        else sb_c(out,(char)c);
    }
}
static void base64_enc(SB *out,const char *d,int len){
    static const char tbl[]="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
    int i=0;
    while(i<len){
        uint32_t n=((uint8_t)d[i])<<16;
        if(i+1<len)n|=((uint8_t)d[i+1])<<8;
        if(i+2<len)n|=((uint8_t)d[i+2]);
        sb_c(out,tbl[(n>>18)&0x3F]);
        sb_c(out,tbl[(n>>12)&0x3F]);
        sb_c(out,i+1<len?tbl[(n>>6)&0x3F]:'=');
        sb_c(out,i+2<len?tbl[n&0x3F]:'=');
        i+=3;
    }
}
static void print_scalar(SB *out,FieldType ft,const char *type_name,Val *v){
    switch(ft){
        case FT_INT32:case FT_SINT32:case FT_SFIXED32:sb_f(out,"%lld",(long long)v->i64);break;
        case FT_UINT32:case FT_FIXED32:sb_f(out,"%llu",(unsigned long long)v->u64);break;
        case FT_INT64:case FT_SINT64:case FT_SFIXED64:sb_c(out,'"');sb_f(out,"%lld",(long long)v->i64);sb_c(out,'"');break;
        case FT_UINT64:case FT_FIXED64:sb_c(out,'"');sb_f(out,"%llu",(unsigned long long)v->u64);sb_c(out,'"');break;
        case FT_BOOL:sb_s(out,v->i64?"true":"false");break;
        case FT_ENUM:{
            EnumDef *ed=get_enum_def(type_name);
            int found=0;
            if(ed){for(int i=0;i<ed->nvals;i++){if(ed->vals[i].val==(int)v->i64){sb_c(out,'"');sb_s(out,ed->vals[i].name);sb_c(out,'"');found=1;break;}}}
            if(!found)sb_f(out,"%lld",(long long)v->i64);
        }break;
        case FT_STRING:sb_c(out,'"');print_json_str(out,v->bytes?v->bytes:"",v->bytes_len);sb_c(out,'"');break;
        case FT_BYTES:sb_c(out,'"');base64_enc(out,v->bytes?v->bytes:"",v->bytes_len);sb_c(out,'"');break;
        default:sb_c(out,'"');sb_c(out,'"');break;
    }
}
static void print_msg(SB *out,DecMsg *msg);
static int is_default(FieldType ft,Val *v){
    switch(ft){
        case FT_INT32:case FT_INT64:case FT_SINT32:case FT_SINT64:case FT_SFIXED32:case FT_SFIXED64:return v->i64==0;
        case FT_UINT32:case FT_UINT64:case FT_FIXED32:case FT_FIXED64:return v->u64==0;
        case FT_BOOL:case FT_ENUM:return v->i64==0;
        case FT_STRING:case FT_BYTES:return v->bytes_len==0;
        default:return 0;
    }
}
static int should_print(int fi,FieldDef *fd,Slot *slot,DecMsg *msg){
    if(fd->type==FT_MAP)return slot->nmap>0;
    if(fd->is_repeated)return slot->nelems>0;
    if(fd->type==FT_MESSAGE)return slot->occurred;
    if(fd->in_oneof)return msg->oneof_set[fd->oneof_idx]==fi;
    if(!slot->occurred)return 0;
    if(fd->is_optional)return 1;
    return !is_default(fd->type,&slot->val);
}
static int map_key_cmp(FieldDef *fd,MapEntry *a,MapEntry *b){
    if(fd->map_key_type==FT_STRING){
        int ml=a->key_str_len<b->key_str_len?a->key_str_len:b->key_str_len;
        int r=memcmp(a->key_str?a->key_str:"",b->key_str?b->key_str:"",ml);
        if(r)return r;
        return a->key_str_len-b->key_str_len;
    }
    if(a->key_i64<b->key_i64)return -1;
    if(a->key_i64>b->key_i64)return 1;
    return 0;
}
static void print_map(SB *out,FieldDef *fd,Slot *slot){
    sb_c(out,'{');
    for(int i=1;i<slot->nmap;i++){
        MapEntry tmp=slot->map_entries[i];int j=i-1;
        while(j>=0&&map_key_cmp(fd,&slot->map_entries[j],&tmp)>0){slot->map_entries[j+1]=slot->map_entries[j];j--;}
        slot->map_entries[j+1]=tmp;
    }
    for(int i=0;i<slot->nmap;i++){
        if(i>0)sb_c(out,',');
        sb_c(out,'"');
        if(fd->map_key_type==FT_STRING)print_json_str(out,slot->map_entries[i].key_str?slot->map_entries[i].key_str:"",slot->map_entries[i].key_str_len);
        else sb_f(out,"%lld",(long long)slot->map_entries[i].key_i64);
        sb_s(out,"\":");
        Val *v=&slot->map_entries[i].val;
        if(fd->map_value_type==FT_MESSAGE){
            if(v->msg)print_msg(out,v->msg);else sb_s(out,"{}");
        }else{
            print_scalar(out,fd->map_value_type,fd->map_value_type_name,v);
        }
    }
    sb_c(out,'}');
}
static void print_msg(SB *out,DecMsg *msg){
    sb_c(out,'{');
    int n=msg->def->nfields;
    int order[MAX_FIELDS];
    for(int i=0;i<n;i++)order[i]=i;
    for(int i=0;i<n-1;i++)for(int j=i+1;j<n;j++)
        if(msg->def->fields[order[j]].number<msg->def->fields[order[i]].number){int t=order[i];order[i]=order[j];order[j]=t;}
    int first=1;
    for(int i=0;i<n;i++){
        int fi=order[i];
        FieldDef *fd=&msg->def->fields[fi];
        Slot *slot=&msg->slots[fi];
        if(!should_print(fi,fd,slot,msg))continue;
        if(!first)sb_c(out,',');first=0;
        sb_c(out,'"');sb_s(out,fd->jname);sb_s(out,"\":");
        if(fd->type==FT_MAP){print_map(out,fd,slot);}
        else if(fd->is_repeated){
            sb_c(out,'[');
            for(int j=0;j<slot->nelems;j++){
                if(j>0)sb_c(out,',');
                if(fd->type==FT_MESSAGE){if(slot->elems[j].msg)print_msg(out,slot->elems[j].msg);else sb_s(out,"{}");}
                else print_scalar(out,fd->type,fd->type_name,&slot->elems[j]);
            }
            sb_c(out,']');
        }else if(fd->type==FT_MESSAGE){
            if(slot->val.msg)print_msg(out,slot->val.msg);else sb_s(out,"{}");
        }else{
            print_scalar(out,fd->type,fd->type_name,&slot->val);
        }
    }
    sb_c(out,'}');
}

/* ===== Main ===== */
int main(int argc,char **argv){
    (void)argc;(void)argv;
    /* read schema */
    FILE *f=fopen("schema.proto","rb");
    if(!f){fprintf(stderr,"cannot open schema.proto\n");return 1;}
    fseek(f,0,SEEK_END);long fsz=ftell(f);fseek(f,0,SEEK_SET);
    char *src=malloc(fsz+1);fread(src,1,fsz,f);src[fsz]=0;fclose(f);
    g_src=src;g_src_end=src+fsz;
    parse_proto();
    resolve_all_types();

    /* read messages.bin */
    f=fopen("messages.bin","rb");
    if(!f){fprintf(stderr,"cannot open messages.bin\n");return 1;}
    fseek(f,0,SEEK_END);long bsz=ftell(f);fseek(f,0,SEEK_SET);
    uint8_t *bin=malloc(bsz);fread(bin,1,bsz,f);fclose(f);

    MsgDef *root=get_msg_def(root_name);
    if(!root)return 0;

    int pos=0;
    while(pos<bsz){
        uint64_t rlen=read_varint(bin,&pos,bsz);
        if(pos+(int)rlen>bsz)rlen=bsz-pos;
        DecMsg *m=new_msg(root);
        decode_msg(m,bin+pos,(int)rlen);
        pos+=rlen;
        SB out;sb_init(&out);
        print_msg(&out,m);
        printf("%s\n",out.buf);
        free(out.buf);
    }
    return 0;
}

use std::collections::HashMap;
use std::env;
use std::fs;

// ============= Schema Types =============

#[derive(Debug, Clone, Copy, PartialEq)]
enum ScalarType {
    Int32, Int64, Uint32, Uint64, Sint32, Sint64,
    Bool, Str, Bytes,
    Fixed32, Fixed64, Sfixed32, Sfixed64,
}

#[derive(Debug, Clone)]
enum TypeRef {
    Scalar(ScalarType),
    Named(String),
}

#[derive(Debug, Clone)]
enum FieldKind {
    Scalar(ScalarType),
    Named(String),
    Map { key: ScalarType, value: TypeRef },
}

#[derive(Debug, Clone)]
struct FieldDef {
    number: u32,
    name: String,
    kind: FieldKind,
    repeated: bool,
    optional: bool,
    oneof_name: Option<String>,
}

#[derive(Debug, Clone)]
struct MessageDef {
    fields: Vec<FieldDef>,
}

#[derive(Debug, Clone)]
struct EnumDef {
    values: Vec<(String, i64)>,
}

struct Schema {
    root_message: String,
    messages: HashMap<String, MessageDef>,
    enums: HashMap<String, EnumDef>,
}

// ============= Lexer =============

#[derive(Debug, Clone, PartialEq)]
enum Token {
    Ident(String),
    Num(i64),
    StrLit(String),
    Punct(char),
    EOF,
}

struct Lexer {
    chars: Vec<char>,
    pos: usize,
}

impl Lexer {
    fn new(input: &str) -> Self {
        Lexer { chars: input.chars().collect(), pos: 0 }
    }

    fn skip_ws_comments(&mut self) {
        loop {
            while self.pos < self.chars.len() && self.chars[self.pos].is_whitespace() {
                self.pos += 1;
            }
            if self.pos + 1 < self.chars.len() && self.chars[self.pos] == '/' && self.chars[self.pos + 1] == '/' {
                while self.pos < self.chars.len() && self.chars[self.pos] != '\n' {
                    self.pos += 1;
                }
            } else if self.pos + 1 < self.chars.len() && self.chars[self.pos] == '/' && self.chars[self.pos + 1] == '*' {
                self.pos += 2;
                while self.pos + 1 < self.chars.len() && !(self.chars[self.pos] == '*' && self.chars[self.pos + 1] == '/') {
                    self.pos += 1;
                }
                if self.pos + 1 < self.chars.len() { self.pos += 2; }
            } else {
                break;
            }
        }
    }

    fn next_token(&mut self) -> Token {
        self.skip_ws_comments();
        if self.pos >= self.chars.len() { return Token::EOF; }
        let c = self.chars[self.pos];
        if c.is_alphabetic() || c == '_' {
            let mut s = String::new();
            while self.pos < self.chars.len() && (self.chars[self.pos].is_alphanumeric() || self.chars[self.pos] == '_') {
                s.push(self.chars[self.pos]); self.pos += 1;
            }
            return Token::Ident(s);
        }
        if c == '.' && self.pos + 1 < self.chars.len() && self.chars[self.pos + 1].is_ascii_digit() {
            let mut s = String::from("0");
            s.push(c);
            self.pos += 1;
            while self.pos < self.chars.len() && self.chars[self.pos].is_ascii_digit() {
                s.push(self.chars[self.pos]); self.pos += 1;
            }
            return Token::Num(0);
        }
        if c.is_ascii_digit() {
            if c == '0' && self.pos + 1 < self.chars.len() && (self.chars[self.pos+1] == 'x' || self.chars[self.pos+1] == 'X') {
                self.pos += 2;
                let mut s = String::new();
                while self.pos < self.chars.len() && self.chars[self.pos].is_ascii_hexdigit() {
                    s.push(self.chars[self.pos]); self.pos += 1;
                }
                return Token::Num(i64::from_str_radix(&s, 16).unwrap_or(0));
            }
            let mut s = String::new();
            while self.pos < self.chars.len() && self.chars[self.pos].is_ascii_digit() {
                s.push(self.chars[self.pos]); self.pos += 1;
            }
            return Token::Num(s.parse::<i64>().unwrap_or(0));
        }
        if c == '-' && self.pos + 1 < self.chars.len() && self.chars[self.pos + 1].is_ascii_digit() {
            self.pos += 1;
            let mut s = String::from("-");
            while self.pos < self.chars.len() && self.chars[self.pos].is_ascii_digit() {
                s.push(self.chars[self.pos]); self.pos += 1;
            }
            return Token::Num(s.parse::<i64>().unwrap_or(0));
        }
        if c == '"' {
            self.pos += 1;
            let mut s = String::new();
            while self.pos < self.chars.len() && self.chars[self.pos] != '"' {
                if self.chars[self.pos] == '\\' {
                    self.pos += 1;
                    if self.pos < self.chars.len() {
                        s.push(self.chars[self.pos]); self.pos += 1;
                    }
                } else {
                    s.push(self.chars[self.pos]); self.pos += 1;
                }
            }
            if self.pos < self.chars.len() { self.pos += 1; }
            return Token::StrLit(s);
        }
        self.pos += 1;
        Token::Punct(c)
    }
}

// ============= Parser =============

struct Parser {
    tokens: Vec<Token>,
    pos: usize,
    messages: HashMap<String, MessageDef>,
    enums: HashMap<String, EnumDef>,
    root_message: String,
    found_first: bool,
}

impl Parser {
    fn new(input: &str) -> Self {
        let mut lexer = Lexer::new(input);
        let mut tokens = Vec::new();
        loop {
            let t = lexer.next_token();
            let is_eof = t == Token::EOF;
            tokens.push(t);
            if is_eof { break; }
        }
        Parser { tokens, pos: 0, messages: HashMap::new(), enums: HashMap::new(), root_message: String::new(), found_first: false }
    }

    fn peek(&self) -> &Token {
        &self.tokens[self.pos.min(self.tokens.len() - 1)]
    }

    fn peek_at(&self, offset: usize) -> &Token {
        &self.tokens[(self.pos + offset).min(self.tokens.len() - 1)]
    }

    fn advance(&mut self) -> Token {
        let t = self.tokens[self.pos.min(self.tokens.len() - 1)].clone();
        self.pos += 1;
        t
    }

    fn expect_punct(&mut self, c: char) {
        let t = self.advance();
        assert_eq!(t, Token::Punct(c), "expected {:?} got {:?}", c, t);
    }

    fn expect_ident(&mut self) -> String {
        match self.advance() {
            Token::Ident(s) => s,
            t => panic!("expected ident, got {:?}", t),
        }
    }

    fn expect_num(&mut self) -> i64 {
        match self.advance() {
            Token::Num(n) => n,
            t => panic!("expected num, got {:?}", t),
        }
    }

    fn is_ident(&self, s: &str) -> bool {
        matches!(self.peek(), Token::Ident(ref x) if x == s)
    }

    fn is_punct(&self, c: char) -> bool {
        matches!(self.peek(), Token::Punct(x) if *x == c)
    }

    fn skip_to_punct(&mut self, c: char) {
        loop {
            match self.peek() {
                Token::Punct(x) if *x == c => { self.advance(); return; }
                Token::EOF => return,
                _ => { self.advance(); }
            }
        }
    }

    fn parse_schema(&mut self) {
        loop {
            match self.peek() {
                Token::EOF => break,
                Token::Ident(s) if s == "syntax" => {
                    self.advance();
                    self.expect_punct('=');
                    self.advance();
                    self.expect_punct(';');
                }
                Token::Ident(s) if s == "package" => {
                    self.advance();
                    self.skip_to_punct(';');
                }
                Token::Ident(s) if s == "option" => {
                    self.advance();
                    self.skip_to_punct(';');
                }
                Token::Ident(s) if s == "message" => {
                    self.advance();
                    let name = self.expect_ident();
                    if !self.found_first {
                        self.root_message = name.clone();
                        self.found_first = true;
                    }
                    let msg = self.parse_message_body();
                    self.messages.insert(name, msg);
                }
                Token::Ident(s) if s == "enum" => {
                    self.advance();
                    let name = self.expect_ident();
                    let ed = self.parse_enum_body();
                    self.enums.insert(name, ed);
                }
                _ => { self.advance(); }
            }
        }
    }

    fn parse_message_body(&mut self) -> MessageDef {
        self.expect_punct('{');
        let mut fields = Vec::new();
        loop {
            match self.peek() {
                Token::Punct('}') => { self.advance(); break; }
                Token::EOF => break,
                Token::Ident(s) if s == "message" => {
                    self.advance();
                    let name = self.expect_ident();
                    let msg = self.parse_message_body();
                    self.messages.insert(name, msg);
                }
                Token::Ident(s) if s == "enum" => {
                    self.advance();
                    let name = self.expect_ident();
                    let ed = self.parse_enum_body();
                    self.enums.insert(name, ed);
                }
                Token::Ident(s) if s == "oneof" => {
                    self.advance();
                    let oneof_name = self.expect_ident();
                    self.expect_punct('{');
                    loop {
                        match self.peek() {
                            Token::Punct('}') => { self.advance(); break; }
                            Token::EOF => break,
                            Token::Ident(s) if s == "option" => {
                                self.advance();
                                self.skip_to_punct(';');
                            }
                            Token::Ident(s) if s == "map" => {
                                let f = self.parse_map_field(Some(&oneof_name));
                                fields.push(f);
                            }
                            _ => {
                                if let Some(f) = self.parse_field(None, Some(&oneof_name)) {
                                    fields.push(f);
                                }
                            }
                        }
                    }
                }
                Token::Ident(s) if s == "reserved" => {
                    self.advance();
                    self.skip_to_punct(';');
                }
                Token::Ident(s) if s == "option" => {
                    self.advance();
                    self.skip_to_punct(';');
                }
                Token::Ident(s) if s == "map" => {
                    let f = self.parse_map_field(None);
                    fields.push(f);
                }
                Token::Ident(s) if s == "repeated" || s == "optional" => {
                    let label = s.clone();
                    self.advance();
                    if let Some(mut f) = self.parse_field_rest() {
                        f.repeated = label == "repeated";
                        f.optional = label == "optional";
                        fields.push(f);
                    }
                }
                _ => {
                    if let Some(f) = self.parse_field_rest() {
                        fields.push(f);
                    }
                }
            }
        }
        MessageDef { fields }
    }

    fn parse_enum_body(&mut self) -> EnumDef {
        self.expect_punct('{');
        let mut values = Vec::new();
        loop {
            match self.peek() {
                Token::Punct('}') => { self.advance(); break; }
                Token::EOF => break,
                Token::Ident(s) if s == "option" || s == "reserved" => {
                    self.advance();
                    self.skip_to_punct(';');
                }
                Token::Ident(name) => {
                    let name = name.clone();
                    self.advance();
                    self.expect_punct('=');
                    let val = self.expect_num();
                    self.expect_punct(';');
                    values.push((name, val));
                }
                _ => { self.advance(); }
            }
        }
        EnumDef { values }
    }

    fn parse_field(&mut self, label: Option<String>, oneof_name: Option<&str>) -> Option<FieldDef> {
        // label already consumed by caller for repeated/optional
        // This is called when we see a type directly (no label)
        let mut f = self.parse_field_rest()?;
        f.oneof_name = oneof_name.map(|s| s.to_string());
        Some(f)
    }

    fn parse_field_rest(&mut self) -> Option<FieldDef> {
        let type_name = match self.peek() {
            Token::Ident(s) => s.clone(),
            _ => { self.advance(); return None; }
        };
        self.advance();
        let field_name = match self.peek() {
            Token::Ident(s) => s.clone(),
            _ => { return None; }
        };
        self.advance();
        if !self.is_punct('=') { return None; }
        self.advance(); // =
        let number = self.expect_num() as u32;
        // optional field options [ ... ]
        if self.is_punct('[') {
            self.skip_to_punct(']');
        }
        if self.is_punct(';') { self.advance(); }
        let kind = self.resolve_field_type(&type_name);
        Some(FieldDef {
            number,
            name: field_name,
            kind,
            repeated: false,
            optional: false,
            oneof_name: None,
        })
    }

    fn parse_map_field(&mut self, oneof_name: Option<&str>) -> FieldDef {
        self.advance(); // map
        self.expect_punct('<');
        let key_name = self.expect_ident();
        self.expect_punct(',');
        let val_name = self.expect_ident();
        self.expect_punct('>');
        let field_name = self.expect_ident();
        self.expect_punct('=');
        let number = self.expect_num() as u32;
        if self.is_punct('[') { self.skip_to_punct(']'); }
        if self.is_punct(';') { self.advance(); }
        let key_type = self.resolve_scalar(&key_name);
        let val_type = self.resolve_typeref(&val_name);
        FieldDef {
            number,
            name: field_name,
            kind: FieldKind::Map { key: key_type, value: val_type },
            repeated: false,
            optional: false,
            oneof_name: oneof_name.map(|s| s.to_string()),
        }
    }

    fn resolve_scalar(&self, name: &str) -> ScalarType {
        match name {
            "int32" => ScalarType::Int32,
            "int64" => ScalarType::Int64,
            "uint32" => ScalarType::Uint32,
            "uint64" => ScalarType::Uint64,
            "sint32" => ScalarType::Sint32,
            "sint64" => ScalarType::Sint64,
            "bool" => ScalarType::Bool,
            "string" => ScalarType::Str,
            "bytes" => ScalarType::Bytes,
            "fixed32" => ScalarType::Fixed32,
            "fixed64" => ScalarType::Fixed64,
            "sfixed32" => ScalarType::Sfixed32,
            "sfixed64" => ScalarType::Sfixed64,
            _ => ScalarType::Int32, // fallback
        }
    }

    fn resolve_typeref(&self, name: &str) -> TypeRef {
        match name {
            "int32" => TypeRef::Scalar(ScalarType::Int32),
            "int64" => TypeRef::Scalar(ScalarType::Int64),
            "uint32" => TypeRef::Scalar(ScalarType::Uint32),
            "uint64" => TypeRef::Scalar(ScalarType::Uint64),
            "sint32" => TypeRef::Scalar(ScalarType::Sint32),
            "sint64" => TypeRef::Scalar(ScalarType::Sint64),
            "bool" => TypeRef::Scalar(ScalarType::Bool),
            "string" => TypeRef::Scalar(ScalarType::Str),
            "bytes" => TypeRef::Scalar(ScalarType::Bytes),
            "fixed32" => TypeRef::Scalar(ScalarType::Fixed32),
            "fixed64" => TypeRef::Scalar(ScalarType::Fixed64),
            "sfixed32" => TypeRef::Scalar(ScalarType::Sfixed32),
            "sfixed64" => TypeRef::Scalar(ScalarType::Sfixed64),
            _ => TypeRef::Named(name.to_string()),
        }
    }

    fn resolve_field_type(&self, name: &str) -> FieldKind {
        match name {
            "int32" => FieldKind::Scalar(ScalarType::Int32),
            "int64" => FieldKind::Scalar(ScalarType::Int64),
            "uint32" => FieldKind::Scalar(ScalarType::Uint32),
            "uint64" => FieldKind::Scalar(ScalarType::Uint64),
            "sint32" => FieldKind::Scalar(ScalarType::Sint32),
            "sint64" => FieldKind::Scalar(ScalarType::Sint64),
            "bool" => FieldKind::Scalar(ScalarType::Bool),
            "string" => FieldKind::Scalar(ScalarType::Str),
            "bytes" => FieldKind::Scalar(ScalarType::Bytes),
            "fixed32" => FieldKind::Scalar(ScalarType::Fixed32),
            "fixed64" => FieldKind::Scalar(ScalarType::Fixed64),
            "sfixed32" => FieldKind::Scalar(ScalarType::Sfixed32),
            "sfixed64" => FieldKind::Scalar(ScalarType::Sfixed64),
            _ => FieldKind::Named(name.to_string()),
        }
    }
}

// ============= Varint / Fixed Reading =============

fn read_varint(data: &[u8], mut pos: usize) -> (u64, usize) {
    let mut result: u64 = 0;
    let mut shift = 0;
    loop {
        if pos >= data.len() { break; }
        let byte = data[pos];
        pos += 1;
        result |= ((byte & 0x7F) as u64) << shift;
        if byte & 0x80 == 0 { break; }
        shift += 7;
    }
    (result, pos)
}

fn read_fixed32(data: &[u8], pos: usize) -> (u32, usize) {
    let val = u32::from_le_bytes([data[pos], data[pos+1], data[pos+2], data[pos+3]]);
    (val, pos + 4)
}

fn read_fixed64(data: &[u8], pos: usize) -> (u64, usize) {
    let val = u64::from_le_bytes([
        data[pos], data[pos+1], data[pos+2], data[pos+3],
        data[pos+4], data[pos+5], data[pos+6], data[pos+7],
    ]);
    (val, pos + 8)
}

fn zigzag32(n: u64) -> i32 {
    let n = n as u32;
    ((n >> 1) as i32) ^ (-(n & 1) as i32)
}

fn zigzag64(n: u64) -> i64 {
    ((n >> 1) as i64) ^ (-((n & 1) as i64))
}

// ============= Decoded Value Types =============

#[derive(Debug, Clone)]
enum DecodedValue {
    Int32(i32),
    Int64(i64),
    Uint32(u32),
    Uint64(u64),
    Bool(bool),
    Enum(i32),
    Str(String),
    Bytes(Vec<u8>),
    Message(DecodedMessage),
}

#[derive(Debug, Clone)]
enum MapKey {
    Str(String),
    Int32(i32),
}

#[derive(Debug, Clone)]
enum FieldState {
    Singular { present: bool, value: Option<DecodedValue> },
    Repeated(Vec<DecodedValue>),
    Map(Vec<(MapKey, DecodedValue)>),
}

#[derive(Debug, Clone)]
struct DecodedMessage {
    fields: HashMap<u32, FieldState>,
    oneof_active: HashMap<String, u32>,
}

// ============= Decoder =============

fn is_packed_type(st: ScalarType) -> bool {
    matches!(st, ScalarType::Int32 | ScalarType::Int64 | ScalarType::Uint32 | ScalarType::Uint64 |
        ScalarType::Sint32 | ScalarType::Sint64 | ScalarType::Bool | ScalarType::Fixed32 |
        ScalarType::Fixed64 | ScalarType::Sfixed32 | ScalarType::Sfixed64)
}

fn wire_type_for_scalar(st: ScalarType) -> u8 {
    match st {
        ScalarType::Int32 | ScalarType::Int64 | ScalarType::Uint32 | ScalarType::Uint64 |
        ScalarType::Sint32 | ScalarType::Sint64 | ScalarType::Bool => 0,
        ScalarType::Fixed64 | ScalarType::Sfixed64 => 1,
        ScalarType::Str | ScalarType::Bytes => 2,
        ScalarType::Fixed32 | ScalarType::Sfixed32 => 5,
    }
}

fn decode_scalar_value(st: ScalarType, data: &[u8], pos: &mut usize, wire_type: u8) -> DecodedValue {
    match st {
        ScalarType::Int32 => {
            let (raw, np) = read_varint(data, *pos); *pos = np;
            DecodedValue::Int32((raw as u32) as i32)
        }
        ScalarType::Int64 => {
            let (raw, np) = read_varint(data, *pos); *pos = np;
            DecodedValue::Int64(raw as i64)
        }
        ScalarType::Uint32 => {
            let (raw, np) = read_varint(data, *pos); *pos = np;
            DecodedValue::Uint32(raw as u32)
        }
        ScalarType::Uint64 => {
            let (raw, np) = read_varint(data, *pos); *pos = np;
            DecodedValue::Uint64(raw)
        }
        ScalarType::Sint32 => {
            let (raw, np) = read_varint(data, *pos); *pos = np;
            DecodedValue::Int32(zigzag32(raw))
        }
        ScalarType::Sint64 => {
            let (raw, np) = read_varint(data, *pos); *pos = np;
            DecodedValue::Int64(zigzag64(raw))
        }
        ScalarType::Bool => {
            let (raw, np) = read_varint(data, *pos); *pos = np;
            DecodedValue::Bool(raw != 0)
        }
        ScalarType::Str => {
            let (len, np) = read_varint(data, *pos); *pos = np;
            let s = String::from_utf8_lossy(&data[*pos..*pos + len as usize]).to_string();
            *pos += len as usize;
            DecodedValue::Str(s)
        }
        ScalarType::Bytes => {
            let (len, np) = read_varint(data, *pos); *pos = np;
            let b = data[*pos..*pos + len as usize].to_vec();
            *pos += len as usize;
            DecodedValue::Bytes(b)
        }
        ScalarType::Fixed32 => {
            let (v, np) = read_fixed32(data, *pos); *pos = np;
            DecodedValue::Uint32(v)
        }
        ScalarType::Sfixed32 => {
            let (v, np) = read_fixed32(data, *pos); *pos = np;
            DecodedValue::Int32(v as i32)
        }
        ScalarType::Fixed64 => {
            let (v, np) = read_fixed64(data, *pos); *pos = np;
            DecodedValue::Uint64(v)
        }
        ScalarType::Sfixed64 => {
            let (v, np) = read_fixed64(data, *pos); *pos = np;
            DecodedValue::Int64(v as i64)
        }
    }
}

fn decode_enum_value(data: &[u8], pos: &mut usize) -> i32 {
    let (raw, np) = read_varint(data, *pos);
    *pos = np;
    (raw as u32) as i32
}

fn skip_field(data: &[u8], pos: &mut usize, wire_type: u8, field_number: u32) {
    match wire_type {
        0 => { let (_, np) = read_varint(data, *pos); *pos = np; }
        1 => { *pos += 8; }
        2 => { let (len, np) = read_varint(data, *pos); *pos = np + len as usize; }
        5 => { *pos += 4; }
        3 => {
            loop {
                let (key, np) = read_varint(data, *pos);
                *pos = np;
                let fn_ = (key >> 3) as u32;
                let wt = (key & 7) as u8;
                if wt == 4 && fn_ == field_number { break; }
                skip_field(data, pos, wt, fn_);
            }
        }
        4 => {} // end group - shouldn't happen here
        _ => {}
    }
}

fn decode_message(data: &[u8], msg_name: &str, schema: &Schema) -> DecodedMessage {
    let msg_def = match schema.messages.get(msg_name) {
        Some(m) => m,
        None => return DecodedMessage { fields: HashMap::new(), oneof_active: HashMap::new() },
    };
    let mut result = DecodedMessage { fields: HashMap::new(), oneof_active: HashMap::new() };
    let mut pos = 0;
    while pos < data.len() {
        let (key, np) = read_varint(data, pos);
        pos = np;
        let field_number = (key >> 3) as u32;
        let wire_type = (key & 7) as u8;

        let fdef = msg_def.fields.iter().find(|f| f.number == field_number);
        match fdef {
            None => { skip_field(data, &mut pos, wire_type, field_number); }
            Some(fdef) => {
                decode_field(&mut result, fdef, data, &mut pos, wire_type, schema);
            }
        }
    }
    result
}

fn decode_field(result: &mut DecodedMessage, fdef: &FieldDef, data: &[u8], pos: &mut usize, wire_type: u8, schema: &Schema) {
    match &fdef.kind {
        FieldKind::Scalar(st) => {
            if fdef.repeated {
                if wire_type == 2 && is_packed_type(*st) {
                    let (len, np) = read_varint(data, *pos); *pos = np;
                    let end = *pos + len as usize;
                    let entry = result.fields.entry(fdef.number).or_insert_with(|| FieldState::Repeated(Vec::new()));
                    if let FieldState::Repeated(ref mut vec) = entry {
                        while *pos < end {
                            vec.push(decode_scalar_value(*st, data, pos, wire_type_for_scalar(*st)));
                        }
                    }
                } else {
                    let val = decode_scalar_value(*st, data, pos, wire_type);
                    let entry = result.fields.entry(fdef.number).or_insert_with(|| FieldState::Repeated(Vec::new()));
                    if let FieldState::Repeated(ref mut vec) = entry {
                        vec.push(val);
                    }
                }
            } else {
                let val = decode_scalar_value(*st, data, pos, wire_type);
                handle_singular(result, fdef, val);
            }
        }
        FieldKind::Named(ref name) => {
            if schema.enums.contains_key(name.as_str()) {
                // Enum
                if fdef.repeated {
                    if wire_type == 2 {
                        let (len, np) = read_varint(data, *pos); *pos = np;
                        let end = *pos + len as usize;
                        let entry = result.fields.entry(fdef.number).or_insert_with(|| FieldState::Repeated(Vec::new()));
                        if let FieldState::Repeated(ref mut vec) = entry {
                            while *pos < end {
                                let v = decode_enum_value(data, pos);
                                vec.push(DecodedValue::Enum(v));
                            }
                        }
                    } else {
                        let v = decode_enum_value(data, pos);
                        let entry = result.fields.entry(fdef.number).or_insert_with(|| FieldState::Repeated(Vec::new()));
                        if let FieldState::Repeated(ref mut vec) = entry {
                            vec.push(DecodedValue::Enum(v));
                        }
                    }
                } else {
                    let v = decode_enum_value(data, pos);
                    handle_singular(result, fdef, DecodedValue::Enum(v));
                }
            } else {
                // Message
                let (len, np) = read_varint(data, *pos); *pos = np;
                let sub_data = &data[*pos..*pos + len as usize];
                *pos += len as usize;
                let sub_msg = decode_message(sub_data, name, schema);
                if fdef.repeated {
                    let entry = result.fields.entry(fdef.number).or_insert_with(|| FieldState::Repeated(Vec::new()));
                    if let FieldState::Repeated(ref mut vec) = entry {
                        vec.push(DecodedValue::Message(sub_msg));
                    }
                } else {
                    handle_singular_message(result, fdef, sub_msg, name, schema);
                }
            }
        }
        FieldKind::Map { key: key_type, ref value } => {
            let (len, np) = read_varint(data, *pos); *pos = np;
            let entry_data = &data[*pos..*pos + len as usize];
            *pos += len as usize;
            let (map_key, map_val) = decode_map_entry(entry_data, *key_type, value, schema);
            let entry = result.fields.entry(fdef.number).or_insert_with(|| FieldState::Map(Vec::new()));
            if let FieldState::Map(ref mut entries) = entry {
                let existing = entries.iter().position(|(k, _)| key_eq(k, &map_key));
                if let Some(idx) = existing {
                    entries[idx].1 = map_val;
                } else {
                    entries.push((map_key, map_val));
                }
            }
        }
    }
}

fn handle_singular(result: &mut DecodedMessage, fdef: &FieldDef, val: DecodedValue) {
    if let Some(ref oneof_name) = fdef.oneof_name {
        if let Some(&prev) = result.oneof_active.get(oneof_name) {
            if prev != fdef.number {
                result.fields.remove(&prev);
            }
        }
        result.oneof_active.insert(oneof_name.clone(), fdef.number);
    }
    let entry = result.fields.entry(fdef.number).or_insert_with(|| FieldState::Singular { present: false, value: None });
    if let FieldState::Singular { ref mut present, ref mut value } = entry {
        *present = true;
        *value = Some(val);
    }
}

fn handle_singular_message(result: &mut DecodedMessage, fdef: &FieldDef, sub_msg: DecodedMessage, msg_name: &str, schema: &Schema) {
    let should_merge = if let Some(ref oneof_name) = fdef.oneof_name {
        result.oneof_active.get(oneof_name) == Some(&fdef.number)
    } else {
        true
    };

    if let Some(ref oneof_name) = fdef.oneof_name {
        if let Some(&prev) = result.oneof_active.get(oneof_name) {
            if prev != fdef.number {
                result.fields.remove(&prev);
            }
        }
        result.oneof_active.insert(oneof_name.clone(), fdef.number);
    }

    let entry = result.fields.entry(fdef.number).or_insert_with(|| FieldState::Singular { present: false, value: None });
    if let FieldState::Singular { ref mut present, ref mut value } = entry {
        if *present && should_merge {
            if let Some(DecodedValue::Message(ref mut existing)) = value {
                merge_messages(existing, sub_msg, msg_name, schema);
            }
        } else {
            *present = true;
            *value = Some(DecodedValue::Message(sub_msg));
        }
    }
}

fn merge_messages(target: &mut DecodedMessage, source: DecodedMessage, msg_name: &str, schema: &Schema) {
    let msg_def = match schema.messages.get(msg_name) {
        Some(m) => m,
        None => return,
    };
    for (field_num, source_state) in source.fields {
        let fdef = msg_def.fields.iter().find(|f| f.number == field_num);
        match source_state {
            FieldState::Singular { present, value } => {
                if !present { continue; }
                let is_message = fdef.map_or(false, |f| matches!(f.kind, FieldKind::Named(ref n) if schema.messages.contains_key(n.as_str())));
                let entry = target.fields.entry(field_num).or_insert_with(|| FieldState::Singular { present: false, value: None });
                if let FieldState::Singular { ref mut present: tp, ref mut value: tv } = entry {
                    if *tp && is_message {
                        if let (Some(DecodedValue::Message(ref mut existing)), Some(DecodedValue::Message(new_msg))) = (tv.as_mut(), value) {
                            let sub_name = fdef.and_then(|f| if let FieldKind::Named(ref n) = f.kind { Some(n.clone()) } else { None }).unwrap_or_default();
                            merge_messages(existing, new_msg, &sub_name, schema);
                        }
                    } else {
                        *tp = true;
                        *tv = value;
                    }
                }
            }
            FieldState::Repeated(vals) => {
                let entry = target.fields.entry(field_num).or_insert_with(|| FieldState::Repeated(Vec::new()));
                if let FieldState::Repeated(ref mut vec) = entry {
                    vec.extend(vals);
                }
            }
            FieldState::Map(entries) => {
                let entry = target.fields.entry(field_num).or_insert_with(|| FieldState::Map(Vec::new()));
                if let FieldState::Map(ref mut existing) = entry {
                    for (k, v) in entries {
                        let idx = existing.iter().position(|(ek, _)| key_eq(ek, &k));
                        if let Some(i) = idx {
                            existing[i].1 = v;
                        } else {
                            existing.push((k, v));
                        }
                    }
                }
            }
        }
    }
    for (name, num) in source.oneof_active {
        target.oneof_active.insert(name, num);
    }
}

fn decode_map_entry(data: &[u8], key_type: ScalarType, val_type: &TypeRef, schema: &Schema) -> (MapKey, DecodedValue) {
    let mut key: Option<MapKey> = None;
    let mut val: Option<DecodedValue> = None;
    let mut pos = 0;
    while pos < data.len() {
        let (key_raw, np) = read_varint(data, pos);
        pos = np;
        let field_num = (key_raw >> 3) as u32;
        let wt = (key_raw & 7) as u8;
        if field_num == 1 {
            key = Some(decode_map_key(key_type, data, &mut pos, wt));
        } else if field_num == 2 {
            val = Some(decode_map_value(val_type, data, &mut pos, wt, schema));
        } else {
            skip_field(data, &mut pos, wt, field_num);
        }
    }
    let map_key = key.unwrap_or(match key_type {
        ScalarType::Str => MapKey::Str(String::new()),
        _ => MapKey::Int32(0),
    });
    let map_val = val.unwrap_or(default_value_for_typeref(val_type));
    (map_key, map_val)
}

fn decode_map_key(kt: ScalarType, data: &[u8], pos: &mut usize, wt: u8) -> MapKey {
    match kt {
        ScalarType::Str => {
            let (len, np) = read_varint(data, *pos); *pos = np;
            let s = String::from_utf8_lossy(&data[*pos..*pos + len as usize]).to_string();
            *pos += len as usize;
            MapKey::Str(s)
        }
        _ => {
            let (raw, np) = read_varint(data, *pos); *pos = np;
            MapKey::Int32((raw as u32) as i32)
        }
    }
}

fn decode_map_value(vt: &TypeRef, data: &[u8], pos: &mut usize, wt: u8, schema: &Schema) -> DecodedValue {
    match vt {
        TypeRef::Scalar(st) => decode_scalar_value(*st, data, pos, wt),
        TypeRef::Named(name) => {
            if schema.enums.contains_key(name.as_str()) {
                let v = decode_enum_value(data, pos);
                DecodedValue::Enum(v)
            } else {
                let (len, np) = read_varint(data, *pos); *pos = np;
                let sub = decode_message(&data[*pos..*pos + len as usize], name, schema);
                *pos += len as usize;
                DecodedValue::Message(sub)
            }
        }
    }
}

fn default_value_for_typeref(vt: &TypeRef) -> DecodedValue {
    match vt {
        TypeRef::Scalar(st) => default_value_for_scalar(*st),
        TypeRef::Named(name) => {
            // Check if it's an enum
            // We don't have schema here, so we'll handle this differently
            // Actually we need schema... let me pass it
            // For now, return empty message (will be overridden)
            DecodedValue::Message(DecodedMessage { fields: HashMap::new(), oneof_active: HashMap::new() })
        }
    }
}

fn default_value_for_scalar(st: ScalarType) -> DecodedValue {
    match st {
        ScalarType::Int32 | ScalarType::Sint32 | ScalarType::Sfixed32 => DecodedValue::Int32(0),
        ScalarType::Int64 | ScalarType::Sint64 | ScalarType::Sfixed64 => DecodedValue::Int64(0),
        ScalarType::Uint32 | ScalarType::Fixed32 => DecodedValue::Uint32(0),
        ScalarType::Uint64 | ScalarType::Fixed64 => DecodedValue::Uint64(0),
        ScalarType::Bool => DecodedValue::Bool(false),
        ScalarType::Str => DecodedValue::Str(String::new()),
        ScalarType::Bytes => DecodedValue::Bytes(Vec::new()),
    }
}

fn key_eq(a: &MapKey, b: &MapKey) -> bool {
    match (a, b) {
        (MapKey::Str(a), MapKey::Str(b)) => a == b,
        (MapKey::Int32(a), MapKey::Int32(b)) => a == b,
        _ => false,
    }
}

// ============= JSON Serializer =============

fn to_camel_case(name: &str) -> String {
    let mut result = String::new();
    let mut upper_next = false;
    for c in name.chars() {
        if c == '_' {
            upper_next = true;
        } else {
            if upper_next {
                if c.is_ascii_lowercase() {
                    result.push(c.to_ascii_uppercase());
                } else {
                    result.push(c);
                }
                upper_next = false;
            } else {
                result.push(c);
            }
        }
    }
    result
}

fn json_escape(s: &str) -> String {
    let mut result = String::new();
    for c in s.chars() {
        match c {
            '"' => result.push_str("\\\""),
            '\\' => result.push_str("\\\\"),
            '\u{0008}' => result.push_str("\\b"),
            '\t' => result.push_str("\\t"),
            '\n' => result.push_str("\\n"),
            '\u{000C}' => result.push_str("\\f"),
            '\r' => result.push_str("\\r"),
            c if (c as u32) < 0x20 => {
                result.push_str(&format!("\\u{:04x}", c as u32));
            }
            _ => result.push(c),
        }
    }
    result
}

fn base64_encode(data: &[u8]) -> String {
    const CHARS: &[u8] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
    let mut result = String::new();
    for chunk in data.chunks(3) {
        let b0 = chunk[0] as u32;
        let b1 = if chunk.len() > 1 { chunk[1] as u32 } else { 0 };
        let b2 = if chunk.len() > 2 { chunk[2] as u32 } else { 0 };
        let n = (b0 << 16) | (b1 << 8) | b2;
        result.push(CHARS[((n >> 18) & 63) as usize] as char);
        result.push(CHARS[((n >> 12) & 63) as usize] as char);
        if chunk.len() > 1 {
            result.push(CHARS[((n >> 6) & 63) as usize] as char);
        } else {
            result.push('=');
        }
        if chunk.len() > 2 {
            result.push(CHARS[(n & 63) as usize] as char);
        } else {
            result.push('=');
        }
    }
    result
}

fn is_default_value(val: &DecodedValue) -> bool {
    match val {
        DecodedValue::Int32(v) => *v == 0,
        DecodedValue::Int64(v) => *v == 0,
        DecodedValue::Uint32(v) => *v == 0,
        DecodedValue::Uint64(v) => *v == 0,
        DecodedValue::Bool(v) => !*v,
        DecodedValue::Enum(v) => *v == 0,
        DecodedValue::Str(s) => s.is_empty(),
        DecodedValue::Bytes(b) => b.is_empty(),
        DecodedValue::Message(_) => false, // messages are always printed if present
    }
}

fn serialize_value(val: &DecodedValue, schema: &Schema, enum_name: Option<&str>) -> String {
    match val {
        DecodedValue::Int32(v) => format!("{}", v),
        DecodedValue::Int64(v) => format!("\"{}\"", v),
        DecodedValue::Uint32(v) => format!("{}", v),
        DecodedValue::Uint64(v) => format!("\"{}\"", v),
        DecodedValue::Bool(v) => if *v { "true".to_string() } else { "false".to_string() },
        DecodedValue::Str(s) => format!("\"{}\"", json_escape(s)),
        DecodedValue::Bytes(b) => format!("\"{}\"", base64_encode(b)),
        DecodedValue::Enum(v) => {
            if let Some(name) = enum_name {
                if let Some(ed) = schema.enums.get(name) {
                    for (ename, eval) in &ed.values {
                        if *eval == *v as i64 {
                            return format!("\"{}\"", ename);
                        }
                    }
                }
            }
            format!("{}", v)
        }
        DecodedValue::Message(msg) => {
            // We need the message name to serialize
            // This is handled at a higher level
            format!("{}", serialize_message_no_name(msg, schema))
        }
    }
}

fn serialize_message(msg: &DecodedMessage, msg_name: &str, schema: &Schema) -> String {
    let msg_def = match schema.messages.get(msg_name) {
        Some(m) => m,
        None => return "{}".to_string(),
    };
    let mut parts: Vec<(u32, String)> = Vec::new();
    let mut sorted_fields: Vec<&FieldDef> = msg_def.fields.iter().collect();
    sorted_fields.sort_by_key(|f| f.number);

    for fdef in sorted_fields {
        let state = match msg.fields.get(&fdef.number) {
            Some(s) => s,
            None => continue,
        };
        match state {
            FieldState::Repeated(vec) => {
                if vec.is_empty() { continue; }
                let json_name = to_camel_case(&fdef.name);
                let enum_name = get_enum_name(fdef, schema);
                let elems: Vec<String> = vec.iter().map(|v| serialize_value(v, schema, enum_name.as_deref())).collect();
                parts.push((fdef.number, format!("\"{}\": [{}]", json_name, elems.join(","))));
            }
            FieldState::Map(entries) => {
                if entries.is_empty() { continue; }
                let json_name = to_camel_case(&fdef.name);
                let val_enum_name = get_map_value_enum_name(fdef, schema);
                let mut sorted_entries: Vec<&(MapKey, DecodedValue)> = entries.iter().collect();
                // Determine key type for sorting
                let key_is_int = if let FieldKind::Map { key, .. } = &fdef.kind {
                    *key != ScalarType::Str
                } else { false };
                if key_is_int {
                    sorted_entries.sort_by_key(|(k, _)| match k {
                        MapKey::Int32(v) => *v,
                        _ => 0,
                    });
                } else {
                    sorted_entries.sort_by(|(a, _), (b, _)| {
                        let sa = match a { MapKey::Str(s) => s.as_bytes(), _ => &[] };
                        let sb = match b { MapKey::Str(s) => s.as_bytes(), _ => &[] };
                        sa.cmp(sb)
                    });
                }
                let members: Vec<String> = sorted_entries.iter().map(|(k, v)| {
                    let key_str = match k {
                        MapKey::Str(s) => format!("\"{}\"", json_escape(s)),
                        MapKey::Int32(i) => format!("\"{}\"", i),
                    };
                    let val_str = serialize_value(v, schema, val_enum_name.as_deref());
                    format!("{}:{}", key_str, val_str)
                }).collect();
                parts.push((fdef.number, format!("\"{}\": {{{}}}", json_name, members.join(","))));
            }
            FieldState::Singular { present, value } => {
                if !present { continue; }
                let val = match value {
                    Some(v) => v,
                    None => continue,
                };
                // Presence check for singular scalars
                let is_message = matches!(&fdef.kind, FieldKind::Named(ref n) if schema.messages.contains_key(n.as_str()));
                let is_oneof_member = fdef.oneof_name.is_some();
                let should_print = if is_message {
                    true // always print if present
                } else if fdef.optional || is_oneof_member {
                    true // always print if present
                } else {
                    !is_default_value(val)
                };
                if !should_print { continue; }
                let json_name = to_camel_case(&fdef.name);
                let enum_name = get_enum_name(fdef, schema);
                let val_str = serialize_value(val, schema, enum_name.as_deref());
                parts.push((fdef.number, format!("\"{}\":{}", json_name, val_str)));
            }
        }
    }
    parts.sort_by_key(|(num, _)| *num);
    let body: Vec<&str> = parts.iter().map(|(_, s)| s.as_str()).collect();
    format!("{{{}}}", body.join(","))
}

fn serialize_message_no_name(msg: &DecodedMessage, schema: &Schema) -> String {
    // This is called for nested messages where we don't know the name
    // We need to pass the name somehow... let me fix this
    // Actually, let me restructure to pass msg_name through
    "{}".to_string() // placeholder - will fix
}

fn get_enum_name(fdef: &FieldDef, schema: &Schema) -> Option<String> {
    match &fdef.kind {
        FieldKind::Named(ref name) => {
            if schema.enums.contains_key(name.as_str()) {
                Some(name.clone())
            } else {
                None
            }
        }
        _ => None,
    }
}

fn get_map_value_enum_name(fdef: &FieldDef, schema: &Schema) -> Option<String> {
    if let FieldKind::Map { ref value, .. } = fdef.kind {
        if let TypeRef::Named(ref name) = value {
            if schema.enums.contains_key(name.as_str()) {
                return Some(name.clone());
            }
        }
    }
    None
}

