fn main() {
    let args: Vec<String> = env::args().collect();
    let dir = &args[1];

    let schema_text = fs::read_to_string(format!("{}/schema.proto", dir)).unwrap();
    let messages_data = fs::read(format!("{}/messages.bin", dir)).unwrap();

    let mut parser = Parser::new(&schema_text);
    parser.parse_schema();
    let schema = Schema {
        root_message: parser.root_message.clone(),
        messages: std::mem::replace(&mut parser.messages, HashMap::new()),
        enums: std::mem::replace(&mut parser.enums, HashMap::new()),
    };

    let mut pos = 0;
    while pos < messages_data.len() {
        let (len, np) = read_varint(&messages_data, pos);
        pos = np;
        let msg_bytes = &messages_data[pos..pos + len as usize];
        pos += len as usize;

        let decoded = decode_message(msg_bytes, &schema.root_message, &schema);
        let json = serialize_message(&decoded, &schema.root_message, &schema);
        println!("{}", json);
    }
}

use std::collections::HashMap;
use std::env;
use std::fs;

// ============= Schema Types =============

#[derive(Debug, Clone, Copy, PartialEq)]
enum ScalarType {
    Int32, Int64, Uint32, Uint64, Sint32, Sint64,
    Bool, Str, Bytes,
    Fixed32, Fixed64, Sfixed32, Sfixed64,
}

#[derive(Debug, Clone)]
enum TypeRef {
    Scalar(ScalarType),
    Named(String),
}

#[derive(Debug, Clone)]
enum FieldKind {
    Scalar(ScalarType),
    Named(String),
    Map { key: ScalarType, value: TypeRef },
}

#[derive(Debug, Clone)]
struct FieldDef {
    number: u32,
    name: String,
    kind: FieldKind,
    repeated: bool,
    optional: bool,
    oneof_name: Option<String>,
}

#[derive(Debug, Clone)]
struct MessageDef {
    fields: Vec<FieldDef>,
}

#[derive(Debug, Clone)]
struct EnumDef {
    values: Vec<(String, i64)>,
}

struct Schema {
    root_message: String,
    messages: HashMap<String, MessageDef>,
    enums: HashMap<String, EnumDef>,
}

// ============= Lexer =============

#[derive(Debug, Clone, PartialEq)]
enum Token {
    Ident(String),
    Num(i64),
    StrLit(String),
    Punct(char),
    EOF,
}

struct Lexer {
    chars: Vec<char>,
    pos: usize,
}

impl Lexer {
    fn new(input: &str) -> Self {
        Lexer { chars: input.chars().collect(), pos: 0 }
    }

    fn skip_ws_comments(&mut self) {
        loop {
            while self.pos < self.chars.len() && self.chars[self.pos].is_whitespace() {
                self.pos += 1;
            }
            if self.pos + 1 < self.chars.len() && self.chars[self.pos] == '/' && self.chars[self.pos + 1] == '/' {
                while self.pos < self.chars.len() && self.chars[self.pos] != '\n' {
                    self.pos += 1;
                }
            } else if self.pos + 1 < self.chars.len() && self.chars[self.pos] == '/' && self.chars[self.pos + 1] == '*' {
                self.pos += 2;
                while self.pos + 1 < self.chars.len() && !(self.chars[self.pos] == '*' && self.chars[self.pos + 1] == '/') {
                    self.pos += 1;
                }
                if self.pos + 1 < self.chars.len() { self.pos += 2; }
            } else {
                break;
            }
        }
    }

    fn next_token(&mut self) -> Token {
        self.skip_ws_comments();
        if self.pos >= self.chars.len() { return Token::EOF; }
        let c = self.chars[self.pos];
        if c.is_alphabetic() || c == '_' {
            let mut s = String::new();
            while self.pos < self.chars.len() && (self.chars[self.pos].is_alphanumeric() || self.chars[self.pos] == '_') {
                s.push(self.chars[self.pos]); self.pos += 1;
            }
            return Token::Ident(s);
        }
        if c == '.' && self.pos + 1 < self.chars.len() && self.chars[self.pos + 1].is_ascii_digit() {
            let mut s = String::from("0");
            s.push(c);
            self.pos += 1;
            while self.pos < self.chars.len() && self.chars[self.pos].is_ascii_digit() {
                s.push(self.chars[self.pos]); self.pos += 1;
            }
            return Token::Num(0);
        }
        if c.is_ascii_digit() {
            if c == '0' && self.pos + 1 < self.chars.len() && (self.chars[self.pos+1] == 'x' || self.chars[self.pos+1] == 'X') {
                self.pos += 2;
                let mut s = String::new();
                while self.pos < self.chars.len() && self.chars[self.pos].is_ascii_hexdigit() {
                    s.push(self.chars[self.pos]); self.pos += 1;
                }
                return Token::Num(i64::from_str_radix(&s, 16).unwrap_or(0));
            }
            let mut s = String::new();
            while self.pos < self.chars.len() && self.chars[self.pos].is_ascii_digit() {
                s.push(self.chars[self.pos]); self.pos += 1;
            }
            return Token::Num(s.parse::<i64>().unwrap_or(0));
        }
        if c == '-' && self.pos + 1 < self.chars.len() && self.chars[self.pos + 1].is_ascii_digit() {
            self.pos += 1;
            let mut s = String::from("-");
            while self.pos < self.chars.len() && self.chars[self.pos].is_ascii_digit() {
                s.push(self.chars[self.pos]); self.pos += 1;
            }
            return Token::Num(s.parse::<i64>().unwrap_or(0));
        }
        if c == '"' {
            self.pos += 1;
            let mut s = String::new();
            while self.pos < self.chars.len() && self.chars[self.pos] != '"' {
                if self.chars[self.pos] == '\\' {
                    self.pos += 1;
                    if self.pos < self.chars.len() {
                        s.push(self.chars[self.pos]); self.pos += 1;
                    }
                } else {
                    s.push(self.chars[self.pos]); self.pos += 1;
                }
            }
            if self.pos < self.chars.len() { self.pos += 1; }
            return Token::StrLit(s);
        }
        self.pos += 1;
        Token::Punct(c)
    }
}

// ============= Parser =============

struct Parser {
    tokens: Vec<Token>,
    pos: usize,
    messages: HashMap<String, MessageDef>,
    enums: HashMap<String, EnumDef>,
    root_message: String,
    found_first: bool,
}

impl Parser {
    fn new(input: &str) -> Self {
        let mut lexer = Lexer::new(input);
        let mut tokens = Vec::new();
        loop {
            let t = lexer.next_token();
            let is_eof = t == Token::EOF;
            tokens.push(t);
            if is_eof { break; }
        }
        Parser { tokens, pos: 0, messages: HashMap::new(), enums: HashMap::new(), root_message: String::new(), found_first: false }
    }

    fn peek(&self) -> &Token {
        &self.tokens[self.pos.min(self.tokens.len() - 1)]
    }

    fn advance(&mut self) -> Token {
        let t = self.tokens[self.pos.min(self.tokens.len() - 1)].clone();
        self.pos += 1;
        t
    }

    fn expect_punct(&mut self, c: char) {
        let t = self.advance();
        assert_eq!(t, Token::Punct(c), "expected {:?} got {:?}", c, t);
    }

    fn expect_ident(&mut self) -> String {
        match self.advance() {
            Token::Ident(s) => s,
            t => panic!("expected ident, got {:?}", t),
        }
    }

    fn expect_num(&mut self) -> i64 {
        match self.advance() {
            Token::Num(n) => n,
            t => panic!("expected num, got {:?}", t),
        }
    }

    fn is_punct(&self, c: char) -> bool {
        matches!(self.peek(), Token::Punct(x) if *x == c)
    }

    fn skip_to_punct(&mut self, c: char) {
        loop {
            match self.peek() {
                Token::Punct(x) if *x == c => { self.advance(); return; }
                Token::EOF => return,
                _ => { self.advance(); }
            }
        }
    }

    fn parse_schema(&mut self) {
        loop {
            match self.peek() {
                Token::EOF => break,
                Token::Ident(s) if s == "syntax" => {
                    self.advance();
                    self.expect_punct('=');
                    self.advance();
                    self.expect_punct(';');
                }
                Token::Ident(s) if s == "package" => {
                    self.advance();
                    self.skip_to_punct(';');
                }
                Token::Ident(s) if s == "option" => {
                    self.advance();
                    self.skip_to_punct(';');
                }
                Token::Ident(s) if s == "message" => {
                    self.advance();
                    let name = self.expect_ident();
                    if !self.found_first {
                        self.root_message = name.clone();
                        self.found_first = true;
                    }
                    let msg = self.parse_message_body();
                    self.messages.insert(name, msg);
                }
                Token::Ident(s) if s == "enum" => {
                    self.advance();
                    let name = self.expect_ident();
                    let ed = self.parse_enum_body();
                    self.enums.insert(name, ed);
                }
                _ => { self.advance(); }
            }
        }
    }

    fn parse_message_body(&mut self) -> MessageDef {
        self.expect_punct('{');
        let mut fields = Vec::new();
        loop {
            match self.peek() {
                Token::Punct('}') => { self.advance(); break; }
                Token::EOF => break,
                Token::Ident(s) if s == "message" => {
                    self.advance();
                    let name = self.expect_ident();
                    let msg = self.parse_message_body();
                    self.messages.insert(name, msg);
                }
                Token::Ident(s) if s == "enum" => {
                    self.advance();
                    let name = self.expect_ident();
                    let ed = self.parse_enum_body();
                    self.enums.insert(name, ed);
                }
                Token::Ident(s) if s == "oneof" => {
                    self.advance();
                    let oneof_name = self.expect_ident();
                    self.expect_punct('{');
                    loop {
                        match self.peek() {
                            Token::Punct('}') => { self.advance(); break; }
                            Token::EOF => break,
                            Token::Ident(s) if s == "option" => {
                                self.advance();
                                self.skip_to_punct(';');
                            }
                            Token::Ident(s) if s == "map" => {
                                let f = self.parse_map_field(Some(&oneof_name));
                                fields.push(f);
                            }
                            _ => {
                                if let Some(mut f) = self.parse_field_rest() {
                                    f.oneof_name = Some(oneof_name.clone());
                                    fields.push(f);
                                }
                            }
                        }
                    }
                }
                Token::Ident(s) if s == "reserved" => {
                    self.advance();
                    self.skip_to_punct(';');
                }
                Token::Ident(s) if s == "option" => {
                    self.advance();
                    self.skip_to_punct(';');
                }
                Token::Ident(s) if s == "map" => {
                    let f = self.parse_map_field(None);
                    fields.push(f);
                }
                Token::Ident(s) if s == "repeated" || s == "optional" => {
                    let label = s.clone();
                    self.advance();
                    if let Some(mut f) = self.parse_field_rest() {
                        f.repeated = label == "repeated";
                        f.optional = label == "optional";
                        fields.push(f);
                    }
                }
                _ => {
                    if let Some(f) = self.parse_field_rest() {
                        fields.push(f);
                    }
                }
            }
        }
        MessageDef { fields }
    }

    fn parse_enum_body(&mut self) -> EnumDef {
        self.expect_punct('{');
        let mut values = Vec::new();
        loop {
            match self.peek() {
                Token::Punct('}') => { self.advance(); break; }
                Token::EOF => break,
                Token::Ident(s) if s == "option" || s == "reserved" => {
                    self.advance();
                    self.skip_to_punct(';');
                }
                Token::Ident(name) => {
                    let name = name.clone();
                    self.advance();
                    self.expect_punct('=');
                    let val = self.expect_num();
                    // skip options if present
                    if self.is_punct('[') { self.skip_to_punct(']'); }
                    self.expect_punct(';');
                    values.push((name, val));
                }
                _ => { self.advance(); }
            }
        }
        EnumDef { values }
    }

    fn parse_field_rest(&mut self) -> Option<FieldDef> {
        let type_name = match self.peek() {
            Token::Ident(s) => s.clone(),
            _ => { self.advance(); return None; }
        };
        self.advance();
        let field_name = match self.peek() {
            Token::Ident(s) => s.clone(),
            _ => { return None; }
        };
        self.advance();
        if !self.is_punct('=') { return None; }
        self.advance(); // =
        let number = self.expect_num() as u32;
        // optional field options [ ... ]
        if self.is_punct('[') {
            self.skip_to_punct(']');
        }
        if self.is_punct(';') { self.advance(); }
        let kind = self.resolve_field_type(&type_name);
        Some(FieldDef {
            number,
            name: field_name,
            kind,
            repeated: false,
            optional: false,
            oneof_name: None,
        })
    }

    fn parse_map_field(&mut self, oneof_name: Option<&str>) -> FieldDef {
        self.advance(); // map
        self.expect_punct('<');
        let key_name = self.expect_ident();
        self.expect_punct(',');
        let val_name = self.expect_ident();
        self.expect_punct('>');
        let field_name = self.expect_ident();
        self.expect_punct('=');
        let number = self.expect_num() as u32;
        if self.is_punct('[') { self.skip_to_punct(']'); }
        if self.is_punct(';') { self.advance(); }
        let key_type = self.resolve_scalar(&key_name);
        let val_type = self.resolve_typeref(&val_name);
        FieldDef {
            number,
            name: field_name,
            kind: FieldKind::Map { key: key_type, value: val_type },
            repeated: false,
            optional: false,
            oneof_name: oneof_name.map(|s| s.to_string()),
        }
    }

    fn resolve_scalar(&self, name: &str) -> ScalarType {
        match name {
            "int32" => ScalarType::Int32,
            "int64" => ScalarType::Int64,
            "uint32" => ScalarType::Uint32,
            "uint64" => ScalarType::Uint64,
            "sint32" => ScalarType::Sint32,
            "sint64" => ScalarType::Sint64,
            "bool" => ScalarType::Bool,
            "string" => ScalarType::Str,
            "bytes" => ScalarType::Bytes,
            "fixed32" => ScalarType::Fixed32,
            "fixed64" => ScalarType::Fixed64,
            "sfixed32" => ScalarType::Sfixed32,
            "sfixed64" => ScalarType::Sfixed64,
            _ => ScalarType::Int32,
        }
    }

    fn resolve_typeref(&self, name: &str) -> TypeRef {
        match name {
            "int32" => TypeRef::Scalar(ScalarType::Int32),
            "int64" => TypeRef::Scalar(ScalarType::Int64),
            "uint32" => TypeRef::Scalar(ScalarType::Uint32),
            "uint64" => TypeRef::Scalar(ScalarType::Uint64),
            "sint32" => TypeRef::Scalar(ScalarType::Sint32),
            "sint64" => TypeRef::Scalar(ScalarType::Sint64),
            "bool" => TypeRef::Scalar(ScalarType::Bool),
            "string" => TypeRef::Scalar(ScalarType::Str),
            "bytes" => TypeRef::Scalar(ScalarType::Bytes),
            "fixed32" => TypeRef::Scalar(ScalarType::Fixed32),
            "fixed64" => TypeRef::Scalar(ScalarType::Fixed64),
            "sfixed32" => TypeRef::Scalar(ScalarType::Sfixed32),
            "sfixed64" => TypeRef::Scalar(ScalarType::Sfixed64),
            _ => TypeRef::Named(name.to_string()),
        }
    }

    fn resolve_field_type(&self, name: &str) -> FieldKind {
        match name {
            "int32" => FieldKind::Scalar(ScalarType::Int32),
            "int64" => FieldKind::Scalar(ScalarType::Int64),
            "uint32" => FieldKind::Scalar(ScalarType::Uint32),
            "uint64" => FieldKind::Scalar(ScalarType::Uint64),
            "sint32" => FieldKind::Scalar(ScalarType::Sint32),
            "sint64" => FieldKind::Scalar(ScalarType::Sint64),
            "bool" => FieldKind::Scalar(ScalarType::Bool),
            "string" => FieldKind::Scalar(ScalarType::Str),
            "bytes" => FieldKind::Scalar(ScalarType::Bytes),
            "fixed32" => FieldKind::Scalar(ScalarType::Fixed32),
            "fixed64" => FieldKind::Scalar(ScalarType::Fixed64),
            "sfixed32" => FieldKind::Scalar(ScalarType::Sfixed32),
            "sfixed64" => FieldKind::Scalar(ScalarType::Sfixed64),
            _ => FieldKind::Named(name.to_string()),
        }
    }
}

// ============= Varint / Fixed Reading =============

fn read_varint(data: &[u8], mut pos: usize) -> (u64, usize) {
    let mut result: u64 = 0;
    let mut shift = 0;
    loop {
        if pos >= data.len() { break; }
        let byte = data[pos];
        pos += 1;
        result |= ((byte & 0x7F) as u64) << shift;
        if byte & 0x80 == 0 { break; }
        shift += 7;
    }
    (result, pos)
}

fn read_fixed32(data: &[u8], pos: usize) -> (u32, usize) {
    let val = u32::from_le_bytes([data[pos], data[pos+1], data[pos+2], data[pos+3]]);
    (val, pos + 4)
}

fn read_fixed64(data: &[u8], pos: usize) -> (u64, usize) {
    let val = u64::from_le_bytes([
        data[pos], data[pos+1], data[pos+2], data[pos+3],
        data[pos+4], data[pos+5], data[pos+6], data[pos+7],
    ]);
    (val, pos + 8)
}

fn zigzag32(n: u64) -> i32 {
    let n = n as u32;
    ((n >> 1) as i32) ^ ((n & 1) as i32).wrapping_neg()
}

fn zigzag64(n: u64) -> i64 {
    ((n >> 1) as i64) ^ ((n & 1) as i64).wrapping_neg()
}

// ============= Decoded Value Types =============

#[derive(Debug, Clone)]
enum DecodedValue {
    Int32(i32),
    Int64(i64),
    Uint32(u32),
    Uint64(u64),
    Bool(bool),
    Enum(i32),
    Str(String),
    Bytes(Vec<u8>),
    Message(DecodedMessage),
}

#[derive(Debug, Clone)]
enum MapKey {
    Str(String),
    Int32(i32),
}

#[derive(Debug, Clone)]
enum FieldState {
    Singular { present: bool, value: Option<DecodedValue> },
    Repeated(Vec<DecodedValue>),
    Map(Vec<(MapKey, DecodedValue)>),
}

#[derive(Debug, Clone)]
struct DecodedMessage {
    fields: HashMap<u32, FieldState>,
    oneof_active: HashMap<String, u32>,
}

// ============= Decoder =============

fn is_packed_type(st: ScalarType) -> bool {
    matches!(st, ScalarType::Int32 | ScalarType::Int64 | ScalarType::Uint32 | ScalarType::Uint64 |
        ScalarType::Sint32 | ScalarType::Sint64 | ScalarType::Bool | ScalarType::Fixed32 |
        ScalarType::Fixed64 | ScalarType::Sfixed32 | ScalarType::Sfixed64)
}

fn wire_type_for_scalar(st: ScalarType) -> u8 {
    match st {
        ScalarType::Int32 | ScalarType::Int64 | ScalarType::Uint32 | ScalarType::Uint64 |
        ScalarType::Sint32 | ScalarType::Sint64 | ScalarType::Bool => 0,
        ScalarType::Fixed64 | ScalarType::Sfixed64 => 1,
        ScalarType::Str | ScalarType::Bytes => 2,
        ScalarType::Fixed32 | ScalarType::Sfixed32 => 5,
    }
}

fn decode_scalar_value(st: ScalarType, data: &[u8], pos: &mut usize, _wire_type: u8) -> DecodedValue {
    match st {
        ScalarType::Int32 => {
            let (raw, np) = read_varint(data, *pos); *pos = np;
            DecodedValue::Int32((raw as u32) as i32)
        }
        ScalarType::Int64 => {
            let (raw, np) = read_varint(data, *pos); *pos = np;
            DecodedValue::Int64(raw as i64)
        }
        ScalarType::Uint32 => {
            let (raw, np) = read_varint(data, *pos); *pos = np;
            DecodedValue::Uint32(raw as u32)
        }
        ScalarType::Uint64 => {
            let (raw, np) = read_varint(data, *pos); *pos = np;
            DecodedValue::Uint64(raw)
        }
        ScalarType::Sint32 => {
            let (raw, np) = read_varint(data, *pos); *pos = np;
            DecodedValue::Int32(zigzag32(raw))
        }
        ScalarType::Sint64 => {
            let (raw, np) = read_varint(data, *pos); *pos = np;
            DecodedValue::Int64(zigzag64(raw))
        }
        ScalarType::Bool => {
            let (raw, np) = read_varint(data, *pos); *pos = np;
            DecodedValue::Bool(raw != 0)
        }
        ScalarType::Str => {
            let (len, np) = read_varint(data, *pos); *pos = np;
            let s = String::from_utf8_lossy(&data[*pos..*pos + len as usize]).to_string();
            *pos += len as usize;
            DecodedValue::Str(s)
        }
        ScalarType::Bytes => {
            let (len, np) = read_varint(data, *pos); *pos = np;
            let b = data[*pos..*pos + len as usize].to_vec();
            *pos += len as usize;
            DecodedValue::Bytes(b)
        }
        ScalarType::Fixed32 => {
            let (v, np) = read_fixed32(data, *pos); *pos = np;
            DecodedValue::Uint32(v)
        }
        ScalarType::Sfixed32 => {
            let (v, np) = read_fixed32(data, *pos); *pos = np;
            DecodedValue::Int32(v as i32)
        }
        ScalarType::Fixed64 => {
            let (v, np) = read_fixed64(data, *pos); *pos = np;
            DecodedValue::Uint64(v)
        }
        ScalarType::Sfixed64 => {
            let (v, np) = read_fixed64(data, *pos); *pos = np;
            DecodedValue::Int64(v as i64)
        }
    }
}

fn decode_enum_value(data: &[u8], pos: &mut usize) -> i32 {
    let (raw, np) = read_varint(data, *pos);
    *pos = np;
    (raw as u32) as i32
}

fn skip_field(data: &[u8], pos: &mut usize, wire_type: u8, field_number: u32) {
    match wire_type {
        0 => { let (_, np) = read_varint(data, *pos); *pos = np; }
        1 => { *pos += 8; }
        2 => { let (len, np) = read_varint(data, *pos); *pos = np + len as usize; }
        5 => { *pos += 4; }
        3 => {
            loop {
                let (key, np) = read_varint(data, *pos);
                *pos = np;
                let fn_ = (key >> 3) as u32;
                let wt = (key & 7) as u8;
                if wt == 4 && fn_ == field_number { break; }
                skip_field(data, pos, wt, fn_);
            }
        }
        4 => {}
        _ => {}
    }
}

fn decode_message(data: &[u8], msg_name: &str, schema: &Schema) -> DecodedMessage {
    let msg_def = match schema.messages.get(msg_name) {
        Some(m) => m,
        None => return DecodedMessage { fields: HashMap::new(), oneof_active: HashMap::new() },
    };
    let mut result = DecodedMessage { fields: HashMap::new(), oneof_active: HashMap::new() };
    let mut pos = 0;
    while pos < data.len() {
        let (key, np) = read_varint(data, pos);
        pos = np;
        let field_number = (key >> 3) as u32;
        let wire_type = (key & 7) as u8;

        let fdef = msg_def.fields.iter().find(|f| f.number == field_number);
        match fdef {
            None => { skip_field(data, &mut pos, wire_type, field_number); }
            Some(fdef) => {
                decode_field(&mut result, fdef, data, &mut pos, wire_type, schema);
            }
        }
    }
    result
}

fn decode_field(result: &mut DecodedMessage, fdef: &FieldDef, data: &[u8], pos: &mut usize, wire_type: u8, schema: &Schema) {
    match &fdef.kind {
        FieldKind::Scalar(st) => {
            if fdef.repeated {
                if wire_type == 2 && is_packed_type(*st) {
                    let (len, np) = read_varint(data, *pos); *pos = np;
                    let end = *pos + len as usize;
                    let entry = result.fields.entry(fdef.number).or_insert_with(|| FieldState::Repeated(Vec::new()));
                    if let FieldState::Repeated(ref mut vec) = entry {
                        while *pos < end {
                            vec.push(decode_scalar_value(*st, data, pos, wire_type_for_scalar(*st)));
                        }
                    }
                } else {
                    let val = decode_scalar_value(*st, data, pos, wire_type);
                    let entry = result.fields.entry(fdef.number).or_insert_with(|| FieldState::Repeated(Vec::new()));
                    if let FieldState::Repeated(ref mut vec) = entry {
                        vec.push(val);
                    }
                }
            } else {
                let val = decode_scalar_value(*st, data, pos, wire_type);
                handle_singular(result, fdef, val);
            }
        }
        FieldKind::Named(ref name) => {
            if schema.enums.contains_key(name.as_str()) {
                if fdef.repeated {
                    if wire_type == 2 {
                        let (len, np) = read_varint(data, *pos); *pos = np;
                        let end = *pos + len as usize;
                        let entry = result.fields.entry(fdef.number).or_insert_with(|| FieldState::Repeated(Vec::new()));
                        if let FieldState::Repeated(ref mut vec) = entry {
                            while *pos < end {
                                let v = decode_enum_value(data, pos);
                                vec.push(DecodedValue::Enum(v));
                            }
                        }
                    } else {
                        let v = decode_enum_value(data, pos);
                        let entry = result.fields.entry(fdef.number).or_insert_with(|| FieldState::Repeated(Vec::new()));
                        if let FieldState::Repeated(ref mut vec) = entry {
                            vec.push(DecodedValue::Enum(v));
                        }
                    }
                } else {
                    let v = decode_enum_value(data, pos);
                    handle_singular(result, fdef, DecodedValue::Enum(v));
                }
            } else {
                // Message
                let (len, np) = read_varint(data, *pos); *pos = np;
                let sub_data = &data[*pos..*pos + len as usize];
                *pos += len as usize;
                let sub_msg = decode_message(sub_data, name, schema);
                if fdef.repeated {
                    let entry = result.fields.entry(fdef.number).or_insert_with(|| FieldState::Repeated(Vec::new()));
                    if let FieldState::Repeated(ref mut vec) = entry {
                        vec.push(DecodedValue::Message(sub_msg));
                    }
                } else {
                    handle_singular_message(result, fdef, sub_msg, name, schema);
                }
            }
        }
        FieldKind::Map { key: key_type, ref value } => {
            let (len, np) = read_varint(data, *pos); *pos = np;
            let entry_data = &data[*pos..*pos + len as usize];
            *pos += len as usize;
            let (map_key, map_val) = decode_map_entry(entry_data, *key_type, value, schema);
            let entry = result.fields.entry(fdef.number).or_insert_with(|| FieldState::Map(Vec::new()));
            if let FieldState::Map(ref mut entries) = entry {
                let existing = entries.iter().position(|(k, _)| key_eq(k, &map_key));
                if let Some(idx) = existing {
                    entries[idx].1 = map_val;
                } else {
                    entries.push((map_key, map_val));
                }
            }
        }
    }
}

fn handle_singular(result: &mut DecodedMessage, fdef: &FieldDef, val: DecodedValue) {
    if let Some(ref oneof_name) = fdef.oneof_name {
        if let Some(&prev) = result.oneof_active.get(oneof_name) {
            if prev != fdef.number {
                result.fields.remove(&prev);
            }
        }
        result.oneof_active.insert(oneof_name.clone(), fdef.number);
    }
    let entry = result.fields.entry(fdef.number).or_insert_with(|| FieldState::Singular { present: false, value: None });
    if let FieldState::Singular { ref mut present, ref mut value } = entry {
        *present = true;
        *value = Some(val);
    }
}

fn handle_singular_message(result: &mut DecodedMessage, fdef: &FieldDef, sub_msg: DecodedMessage, msg_name: &str, schema: &Schema) {
    let should_merge = if let Some(ref oneof_name) = fdef.oneof_name {
        result.oneof_active.get(oneof_name) == Some(&fdef.number)
    } else {
        true
    };

    if let Some(ref oneof_name) = fdef.oneof_name {
        if let Some(&prev) = result.oneof_active.get(oneof_name) {
            if prev != fdef.number {
                result.fields.remove(&prev);
            }
        }
        result.oneof_active.insert(oneof_name.clone(), fdef.number);
    }

    let entry = result.fields.entry(fdef.number).or_insert_with(|| FieldState::Singular { present: false, value: None });
    if let FieldState::Singular { ref mut present, ref mut value } = entry {
        if *present && should_merge {
            if let Some(DecodedValue::Message(ref mut existing)) = value {
                merge_messages(existing, sub_msg, msg_name, schema);
            }
        } else {
            *present = true;
            *value = Some(DecodedValue::Message(sub_msg));
        }
    }
}

fn merge_messages(target: &mut DecodedMessage, source: DecodedMessage, msg_name: &str, schema: &Schema) {
    let msg_def = match schema.messages.get(msg_name) {
        Some(m) => m,
        None => return,
    };
    for (field_num, source_state) in source.fields {
        let fdef = msg_def.fields.iter().find(|f| f.number == field_num);
        match source_state {
            FieldState::Singular { present, value } => {
                if !present { continue; }
                let is_message = fdef.map_or(false, |f| matches!(f.kind, FieldKind::Named(ref n) if schema.messages.contains_key(n.as_str())));
                let entry = target.fields.entry(field_num).or_insert_with(|| FieldState::Singular { present: false, value: None });
                if let FieldState::Singular { present: ref mut tp, value: ref mut tv } = entry {
                    if *tp && is_message {
                        if let (Some(DecodedValue::Message(ref mut existing)), Some(DecodedValue::Message(new_msg))) = (tv.as_mut(), value) {
                            let sub_name = fdef.and_then(|f| if let FieldKind::Named(ref n) = f.kind { Some(n.clone()) } else { None }).unwrap_or_default();
                            merge_messages(existing, new_msg, &sub_name, schema);
                        }
                    } else {
                        *tp = true;
                        *tv = value;
                    }
                }
            }
            FieldState::Repeated(vals) => {
                let entry = target.fields.entry(field_num).or_insert_with(|| FieldState::Repeated(Vec::new()));
                if let FieldState::Repeated(ref mut vec) = entry {
                    vec.extend(vals);
                }
            }
            FieldState::Map(entries) => {
                let entry = target.fields.entry(field_num).or_insert_with(|| FieldState::Map(Vec::new()));
                if let FieldState::Map(ref mut existing) = entry {
                    for (k, v) in entries {
                        let idx = existing.iter().position(|(ek, _)| key_eq(ek, &k));
                        if let Some(i) = idx {
                            existing[i].1 = v;
                        } else {
                            existing.push((k, v));
                        }
                    }
                }
            }
        }
    }
    for (name, num) in source.oneof_active {
        target.oneof_active.insert(name, num);
    }
}

fn decode_map_entry(data: &[u8], key_type: ScalarType, val_type: &TypeRef, schema: &Schema) -> (MapKey, DecodedValue) {
    let mut key: Option<MapKey> = None;
    let mut val: Option<DecodedValue> = None;
    let mut pos = 0;
    while pos < data.len() {
        let (key_raw, np) = read_varint(data, pos);
        pos = np;
        let field_num = (key_raw >> 3) as u32;
        let wt = (key_raw & 7) as u8;
        if field_num == 1 {
            key = Some(decode_map_key(key_type, data, &mut pos, wt));
        } else if field_num == 2 {
            val = Some(decode_map_value(val_type, data, &mut pos, wt, schema));
        } else {
            skip_field(data, &mut pos, wt, field_num);
        }
    }
    let map_key = key.unwrap_or(match key_type {
        ScalarType::Str => MapKey::Str(String::new()),
        _ => MapKey::Int32(0),
    });
    let map_val = val.unwrap_or(default_value_for_typeref(val_type, schema));
    (map_key, map_val)
}

fn decode_map_key(kt: ScalarType, data: &[u8], pos: &mut usize, _wt: u8) -> MapKey {
    match kt {
        ScalarType::Str => {
            let (len, np) = read_varint(data, *pos); *pos = np;
            let s = String::from_utf8_lossy(&data[*pos..*pos + len as usize]).to_string();
            *pos += len as usize;
            MapKey::Str(s)
        }
        _ => {
            let (raw, np) = read_varint(data, *pos); *pos = np;
            MapKey::Int32((raw as u32) as i32)
        }
    }
}

fn decode_map_value(vt: &TypeRef, data: &[u8], pos: &mut usize, wt: u8, schema: &Schema) -> DecodedValue {
    match vt {
        TypeRef::Scalar(st) => decode_scalar_value(*st, data, pos, wt),
        TypeRef::Named(name) => {
            if schema.enums.contains_key(name.as_str()) {
                let v = decode_enum_value(data, pos);
                DecodedValue::Enum(v)
            } else {
                let (len, np) = read_varint(data, *pos); *pos = np;
                let sub = decode_message(&data[*pos..*pos + len as usize], name, schema);
                *pos += len as usize;
                DecodedValue::Message(sub)
            }
        }
    }
}

fn default_value_for_typeref(vt: &TypeRef, schema: &Schema) -> DecodedValue {
    match vt {
        TypeRef::Scalar(st) => default_value_for_scalar(*st),
        TypeRef::Named(name) => {
            if schema.enums.contains_key(name.as_str()) {
                DecodedValue::Enum(0)
            } else {
                DecodedValue::Message(DecodedMessage { fields: HashMap::new(), oneof_active: HashMap::new() })
            }
        }
    }
}

fn default_value_for_scalar(st: ScalarType) -> DecodedValue {
    match st {
        ScalarType::Int32 | ScalarType::Sint32 | ScalarType::Sfixed32 => DecodedValue::Int32(0),
        ScalarType::Int64 | ScalarType::Sint64 | ScalarType::Sfixed64 => DecodedValue::Int64(0),
        ScalarType::Uint32 | ScalarType::Fixed32 => DecodedValue::Uint32(0),
        ScalarType::Uint64 | ScalarType::Fixed64 => DecodedValue::Uint64(0),
        ScalarType::Bool => DecodedValue::Bool(false),
        ScalarType::Str => DecodedValue::Str(String::new()),
        ScalarType::Bytes => DecodedValue::Bytes(Vec::new()),
    }
}

fn key_eq(a: &MapKey, b: &MapKey) -> bool {
    match (a, b) {
        (MapKey::Str(a), MapKey::Str(b)) => a == b,
        (MapKey::Int32(a), MapKey::Int32(b)) => a == b,
        _ => false,
    }
}

// ============= JSON Serializer =============

fn to_camel_case(name: &str) -> String {
    let mut result = String::new();
    let mut upper_next = false;
    for c in name.chars() {
        if c == '_' {
            upper_next = true;
        } else {
            if upper_next {
                if c.is_ascii_lowercase() {
                    result.push(c.to_ascii_uppercase());
                } else {
                    result.push(c);
                }
                upper_next = false;
            } else {
                result.push(c);
            }
        }
    }
    result
}

fn json_escape(s: &str) -> String {
    let mut result = String::new();
    for c in s.chars() {
        match c {
            '"' => result.push_str("\\\""),
            '\\' => result.push_str("\\\\"),
            '\u{0008}' => result.push_str("\\b"),
            '\t' => result.push_str("\\t"),
            '\n' => result.push_str("\\n"),
            '\u{000C}' => result.push_str("\\f"),
            '\r' => result.push_str("\\r"),
            c if (c as u32) < 0x20 => {
                result.push_str(&format!("\\u{:04x}", c as u32));
            }
            _ => result.push(c),
        }
    }
    result
}

fn base64_encode(data: &[u8]) -> String {
    const CHARS: &[u8] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
    let mut result = String::new();
    for chunk in data.chunks(3) {
        let b0 = chunk[0] as u32;
        let b1 = if chunk.len() > 1 { chunk[1] as u32 } else { 0 };
        let b2 = if chunk.len() > 2 { chunk[2] as u32 } else { 0 };
        let n = (b0 << 16) | (b1 << 8) | b2;
        result.push(CHARS[((n >> 18) & 63) as usize] as char);
        result.push(CHARS[((n >> 12) & 63) as usize] as char);
        if chunk.len() > 1 {
            result.push(CHARS[((n >> 6) & 63) as usize] as char);
        } else {
            result.push('=');
        }
        if chunk.len() > 2 {
            result.push(CHARS[(n & 63) as usize] as char);
        } else {
            result.push('=');
        }
    }
    result
}

fn is_default_value(val: &DecodedValue) -> bool {
    match val {
        DecodedValue::Int32(v) => *v == 0,
        DecodedValue::Int64(v) => *v == 0,
        DecodedValue::Uint32(v) => *v == 0,
        DecodedValue::Uint64(v) => *v == 0,
        DecodedValue::Bool(v) => !*v,
        DecodedValue::Enum(v) => *v == 0,
        DecodedValue::Str(s) => s.is_empty(),
        DecodedValue::Bytes(b) => b.is_empty(),
        DecodedValue::Message(_) => false,
    }
}

fn serialize_value(val: &DecodedValue, schema: &Schema, enum_name: Option<&str>, msg_name: Option<&str>) -> String {
    match val {
        DecodedValue::Int32(v) => format!("{}", v),
        DecodedValue::Int64(v) => format!("\"{}\"", v),
        DecodedValue::Uint32(v) => format!("{}", v),
        DecodedValue::Uint64(v) => format!("\"{}\"", v),
        DecodedValue::Bool(v) => if *v { "true".to_string() } else { "false".to_string() },
        DecodedValue::Str(s) => format!("\"{}\"", json_escape(s)),
        DecodedValue::Bytes(b) => format!("\"{}\"", base64_encode(b)),
        DecodedValue::Enum(v) => {
            if let Some(name) = enum_name {
                if let Some(ed) = schema.enums.get(name) {
                    for (ename, eval) in &ed.values {
                        if *eval == *v as i64 {
                            return format!("\"{}\"", ename);
                        }
                    }
                }
            }
            format!("{}", v)
        }
        DecodedValue::Message(msg) => {
            let mn = msg_name.unwrap_or("");
            serialize_message(msg, mn, schema)
        }
    }
}

fn serialize_message(msg: &DecodedMessage, msg_name: &str, schema: &Schema) -> String {
    let msg_def = match schema.messages.get(msg_name) {
        Some(m) => m,
        None => return "{}".to_string(),
    };
    let mut parts: Vec<(u32, String)> = Vec::new();
    let mut sorted_fields: Vec<&FieldDef> = msg_def.fields.iter().collect();
    sorted_fields.sort_by_key(|f| f.number);

    for fdef in sorted_fields {
        let state = match msg.fields.get(&fdef.number) {
            Some(s) => s,
            None => continue,
        };
        match state {
            FieldState::Repeated(vec) => {
                if vec.is_empty() { continue; }
                let json_name = to_camel_case(&fdef.name);
                let enum_name = get_enum_name(fdef, schema);
                let msg_name_for_val = get_msg_name(fdef, schema);
                let elems: Vec<String> = vec.iter().map(|v| serialize_value(v, schema, enum_name.as_deref(), msg_name_for_val.as_deref())).collect();
                parts.push((fdef.number, format!("\"{}\": [{}]", json_name, elems.join(","))));
            }
            FieldState::Map(entries) => {
                if entries.is_empty() { continue; }
                let json_name = to_camel_case(&fdef.name);
                let val_enum_name = get_map_value_enum_name(fdef, schema);
                let val_msg_name = get_map_value_msg_name(fdef, schema);
                let mut sorted_entries: Vec<&(MapKey, DecodedValue)> = entries.iter().collect();
                let key_is_int = if let FieldKind::Map { key, .. } = &fdef.kind {
                    *key != ScalarType::Str
                } else { false };
                if key_is_int {
                    sorted_entries.sort_by_key(|(k, _)| match k {
                        MapKey::Int32(v) => *v,
                        _ => 0,
                    });
                } else {
                    sorted_entries.sort_by(|(a, _), (b, _)| {
                        let sa = match a { MapKey::Str(s) => s.as_bytes(), _ => &[] };
                        let sb = match b { MapKey::Str(s) => s.as_bytes(), _ => &[] };
                        sa.cmp(sb)
                    });
                }
                let members: Vec<String> = sorted_entries.iter().map(|(k, v)| {
                    let key_str = match k {
                        MapKey::Str(s) => format!("\"{}\"", json_escape(s)),
                        MapKey::Int32(i) => format!("\"{}\"", i),
                    };
                    let val_str = serialize_value(v, schema, val_enum_name.as_deref(), val_msg_name.as_deref());
                    format!("{}:{}", key_str, val_str)
                }).collect();
                parts.push((fdef.number, format!("\"{}\": {{{}}}", json_name, members.join(","))));
            }
            FieldState::Singular { present, value } => {
                if !present { continue; }
                let val = match value {
                    Some(v) => v,
                    None => continue,
                };
                let is_message = matches!(&fdef.kind, FieldKind::Named(ref n) if schema.messages.contains_key(n.as_str()));
                let is_oneof_member = fdef.oneof_name.is_some();
                let should_print = if is_message {
                    true
                } else if fdef.optional || is_oneof_member {
                    true
                } else {
                    !is_default_value(val)
                };
                if !should_print { continue; }
                let json_name = to_camel_case(&fdef.name);
                let enum_name = get_enum_name(fdef, schema);
                let msg_name_for_val = get_msg_name(fdef, schema);
                let val_str = serialize_value(val, schema, enum_name.as_deref(), msg_name_for_val.as_deref());
                parts.push((fdef.number, format!("\"{}\":{}", json_name, val_str)));
            }
        }
    }
    parts.sort_by_key(|(num, _)| *num);
    let body: Vec<&str> = parts.iter().map(|(_, s)| s.as_str()).collect();
    format!("{{{}}}", body.join(","))
}

fn get_enum_name(fdef: &FieldDef, schema: &Schema) -> Option<String> {
    match &fdef.kind {
        FieldKind::Named(ref name) => {
            if schema.enums.contains_key(name.as_str()) {
                Some(name.clone())
            } else {
                None
            }
        }
        _ => None,
    }
}

fn get_msg_name(fdef: &FieldDef, schema: &Schema) -> Option<String> {
    match &fdef.kind {
        FieldKind::Named(ref name) => {
            if schema.messages.contains_key(name.as_str()) {
                Some(name.clone())
            } else {
                None
            }
        }
        _ => None,
    }
}

fn get_map_value_enum_name(fdef: &FieldDef, schema: &Schema) -> Option<String> {
    if let FieldKind::Map { ref value, .. } = fdef.kind {
        if let TypeRef::Named(ref name) = value {
            if schema.enums.contains_key(name.as_str()) {
                return Some(name.clone());
            }
        }
    }
    None
}

fn get_map_value_msg_name(fdef: &FieldDef, schema: &Schema) -> Option<String> {
    if let FieldKind::Map { ref value, .. } = fdef.kind {
        if let TypeRef::Named(ref name) = value {
            if schema.messages.contains_key(name.as_str()) {
                return Some(name.clone());
            }
        }
    }
    None
}

// ============= Main =============

fn main() {
    let args: Vec<String> = env::args().collect();
    let dir = &args[1];

    let schema_text = fs::read_to_string(format!("{}/schema.proto", dir)).unwrap();
    let messages_data = fs::read(format!("{}/messages.bin", dir)).unwrap();

    let mut parser = Parser::new(&schema_text);
    parser.parse_schema();
    let schema = Schema {
        root_message: parser.root_message.clone(),
        messages: std::mem::replace(&mut parser.messages, HashMap::new()),
        enums: std::mem::replace(&mut parser.enums, HashMap::new()),
    };

    let mut pos = 0;
    while pos < messages_data.len() {
        let (len, np) = read_varint(&messages_data, pos);
        pos = np;
        let msg_bytes = &messages_data[pos..pos + len as usize];
        pos += len as usize;

        let decoded = decode_message(msg_bytes, &schema.root_message, &schema);
        let json = serialize_message(&decoded, &schema.root_message, &schema);
        println!("{}", json);
    }
}

import java.io.*;
import java.net.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;

public class Main {

    public static void main(String[] args) throws Exception {
        String dataDir = args[0];
        String baseUrl = args[1];

        String clientJson = new String(Files.readAllBytes(Paths.get(dataDir, "client.json")), StandardCharsets.UTF_8);
        Map<String, Object> client = (Map<String, Object>) parseJson(clientJson);

        String clientId = (String) client.get("client_id");
        String clientSecret = (String) client.get("client_secret");
        String scope = (String) client.get("scope");
        int pageSize = ((Number) client.get("page_size")).intValue();

        URL url = new URL(baseUrl);
        String host = url.getHost();
        int port = url.getPort() == -1 ? url.getDefaultPort() : url.getPort();
        String basePath = url.getPath();

        String accessToken = getToken(host, port, basePath, clientId, clientSecret, scope);

        int pages = 0;
        int retries = 0;
        int reauth = 0;
        List<Map<String, Object>> allOrders = new ArrayList<>();
        String cursor = null;
        boolean tokenUsedSuccessfully = false;

        while (true) {
            String path = basePath + "/orders?limit=" + pageSize;
            if (cursor != null) {
                path += "&cursor=" + percentEncode(cursor);
            }

            HttpResponse resp = makeRequest("GET", host, port, path, "Bearer " + accessToken, null, null);

            if (resp.status == 429) {
                retries++;
                String ra = resp.headers.getOrDefault("retry-after", "1").trim();
                long wait = Long.parseLong(ra);
                Thread.sleep(wait * 1000L);
                continue;
            }
            if (resp.status == 503) {
                retries++;
                Thread.sleep(500);
                continue;
            }
            if (resp.status == 401) {
                if (!tokenUsedSuccessfully) {
                    System.out.println("ERROR " + resp.status + " " + resp.body);
                    return;
                }
                reauth++;
                accessToken = getToken(host, port, basePath, clientId, clientSecret, scope);
                tokenUsedSuccessfully = false;
                continue;
            }
            if (resp.status != 200) {
                System.out.println("ERROR " + resp.status + " " + resp.body);
                return;
            }

            tokenUsedSuccessfully = true;
            pages++;

            Map<String, Object> pageData = (Map<String, Object>) parseJson(resp.body);
            Object dataObj = pageData.get("data");
            if (dataObj instanceof List) {
                for (Object item : (List<?>) dataObj) {
                    allOrders.add((Map<String, Object>) item);
                }
            }

            Object nextCursor = pageData.get("next_cursor");
            if (nextCursor == null) {
                break;
            }
            cursor = (String) nextCursor;
        }

        Map<String, Long> totals = new HashMap<>();
        Map<String, Integer> statusCounts = new TreeMap<>();

        for (Map<String, Object> order : allOrders) {
            String status = (String) order.get("status");
            statusCounts.merge(status, 1, Integer::sum);

            if (!"cancelled".equals(status)) {
                Map<String, Object> customer = (Map<String, Object>) order.get("customer");
                String name = (String) customer.get("name");
                String currency = (String) order.get("currency");
                String amountStr = (String) order.get("amount");
                long cents = parseAmount(amountStr);
                String key = name + "\0" + currency;
                totals.merge(key, cents, Long::sum);
            }
        }

        List<String> keys = new ArrayList<>(totals.keySet());
        keys.sort((a, b) -> {
            int nullA = a.indexOf('\0');
            int nullB = b.indexOf('\0');
            String nameA = a.substring(0, nullA);
            String curA = a.substring(nullA + 1);
            String nameB = b.substring(0, nullB);
            String curB = b.substring(nullB + 1);
            byte[] bytesA = nameA.getBytes(StandardCharsets.UTF_8);
            byte[] bytesB = nameB.getBytes(StandardCharsets.UTF_8);
            int cmp = compareUnsignedBytes(bytesA, bytesB);
            if (cmp != 0) return cmp;
            return curA.compareTo(curB);
        });

        for (String key : keys) {
            int nullIdx = key.indexOf('\0');
            String name = key.substring(0, nullIdx);
            String currency = key.substring(nullIdx + 1);
            long cents = totals.get(key);
            System.out.println("total " + currency + " " + formatAmount(cents) + " " + name);
        }

        for (Map.Entry<String, Integer> entry : statusCounts.entrySet()) {
            System.out.println("status " + entry.getKey() + " " + entry.getValue());
        }

        System.out.println("orders " + allOrders.size() + " pages " + pages + " retries " + retries + " reauth " + reauth);
    }

    static String getToken(String host, int port, String basePath, String clientId, String clientSecret, String scope) throws Exception {
        String encodedId = formUrlEncode(clientId);
        String encodedSecret = formUrlEncode(clientSecret);
        String credentials = encodedId + ":" + encodedSecret;
        String b64 = Base64.getEncoder().encodeToString(credentials.getBytes(StandardCharsets.UTF_8));

        String body = "grant_type=client_credentials&scope=" + formUrlEncode(scope);
        String path = basePath + "/oauth/token";

        HttpResponse resp = makeRequest("POST", host, port, path, "Basic " + b64, "application/x-www-form-urlencoded", body);

        if (resp.status != 200) {
            System.out.println("ERROR " + resp.status + " " + resp.body);
            System.exit(0);
        }

        Map<String, Object> tokenData = (Map<String, Object>) parseJson(resp.body);
        return (String) tokenData.get("access_token");
    }

    static HttpResponse makeRequest(String method, String host, int port, String path, String authHeader, String contentType, String body) throws Exception {
        Socket socket = new Socket();
        socket.connect(new InetSocketAddress(host, port), 30000);
        socket.setSoTimeout(30000);

        OutputStream out = socket.getOutputStream();
        StringBuilder req = new StringBuilder();
        req.append(method).append(" ").append(path).append(" HTTP/1.1\r\n");
        if (port == 80 || port == 443) {
            req.append("Host: ").append(host).append("\r\n");
        } else {
            req.append("Host: ").append(host).append(":").append(port).append("\r\n");
        }
        req.append("Connection: close\r\n");
        if (authHeader != null) {
            req.append("Authorization: ").append(authHeader).append("\r\n");
        }
        if (contentType != null) {
            req.append("Content-Type: ").append(contentType).append("\r\n");
        }
        if (body != null) {
            byte[] bodyBytes = body.getBytes(StandardCharsets.UTF_8);
            req.append("Content-Length: ").append(bodyBytes.length).append("\r\n");
        }
        req.append("\r\n");
        out.write(req.toString().getBytes(StandardCharsets.UTF_8));
        if (body != null) {
            out.write(body.getBytes(StandardCharsets.UTF_8));
        }
        out.flush();

        InputStream in = new BufferedInputStream(socket.getInputStream());
        HttpResponse resp = new HttpResponse();

        // Read status line
        String statusLine = readLine(in);
        String[] parts = statusLine.split(" ", 3);
        resp.status = Integer.parseInt(parts[1]);

        // Read headers
        resp.headers = new HashMap<>();
        String line;
        while ((line = readLine(in)) != null && !line.isEmpty()) {
            int colon = line.indexOf(':');
            if (colon >= 0) {
                String key = line.substring(0, colon).trim().toLowerCase();
                String val = line.substring(colon + 1).trim();
                resp.headers.put(key, val);
            }
        }

        // Read body
        String te = resp.headers.getOrDefault("transfer-encoding", "");
        String cl = resp.headers.get("content-length");

        if (te.toLowerCase().contains("chunked")) {
            resp.body = readChunkedBody(in);
        } else if (cl != null) {
            int len = Integer.parseInt(cl.trim());
            byte[] buf = new byte[len];
            int read = 0;
            while (read < len) {
                int r = in.read(buf, read, len - read);
                if (r == -1) break;
                read += r;
            }
            resp.body = new String(buf, 0, read, StandardCharsets.UTF_8);
        } else {
            // Read until EOF
            ByteArrayOutputStream baos = new ByteArrayOutputStream();
            byte[] buf = new byte[4096];
            int r;
            while ((r = in.read(buf)) != -1) {
                baos.write(buf, 0, r);
            }
            resp.body = new String(baos.toByteArray(), StandardCharsets.UTF_8);
        }

        socket.close();
        return resp;
    }

    static String readLine(InputStream in) throws IOException {
        StringBuilder sb = new StringBuilder();
        int c;
        while ((c = in.read()) != -1) {
            if (c == '\r') {
                int next = in.read();
                if (next == '\n') break;
                sb.append('\r');
                if (next != -1) sb.append((char) next);
            } else if (c == '\n') {
                break;
            } else {
                sb.append((char) c);
            }
        }
        if (c == -1 && sb.length() == 0) return null;
        return sb.toString();
    }

    static String readChunkedBody(InputStream in) throws IOException {
        ByteArrayOutputStream baos = new ByteArrayOutputStream();
        while (true) {
            String sizeLine = readLine(in);
            if (sizeLine == null) break;
            // Remove chunk extensions
            int semi = sizeLine.indexOf(';');
            if (semi >= 0) sizeLine = sizeLine.substring(0, semi);
            sizeLine = sizeLine.trim();
            int chunkSize = Integer.parseInt(sizeLine, 16);
            if (chunkSize == 0) {
                // Read trailing CRLF (and possible trailers)
                String trailer;
                while ((trailer = readLine(in)) != null && !trailer.isEmpty()) {
                    // skip trailers
                }
                break;
            }
            int read = 0;
            while (read < chunkSize) {
                int r = in.read();
                if (r == -1) break;
                baos.write(r);
                read++;
            }
            // Read CRLF after chunk data
            in.read(); // \r
            in.read(); // \n
        }
        return new String(baos.toByteArray(), StandardCharsets.UTF_8);
    }

    static String formUrlEncode(String s) {
        byte[] bytes = s.getBytes(StandardCharsets.UTF_8);
        StringBuilder sb = new StringBuilder();
        for (byte b : bytes) {
            int c = b & 0xFF;
            if ((c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z') || (c >= '0' && c <= '9')
                    || c == '-' || c == '.' || c == '_' || c == '*') {
                sb.append((char) c);
            } else if (c == ' ') {
                sb.append('+');
            } else {
                sb.append('%');
                sb.append(String.format("%02X", c));
            }
        }
        return sb.toString();
    }

    static String percentEncode(String s) {
        byte[] bytes = s.getBytes(StandardCharsets.UTF_8);
        StringBuilder sb = new StringBuilder();
        for (byte b : bytes) {
            int c = b & 0xFF;
            if ((c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z') || (c >= '0' && c <= '9')
                    || c == '-' || c == '.' || c == '_' || c == '~') {
                sb.append((char) c);
            } else {
                sb.append('%');
                sb.append(String.format("%02X", c));
            }
        }
        return sb.toString();
    }

    static long parseAmount(String s) {
        boolean negative = false;
        if (s.startsWith("-")) {
            negative = true;
            s = s.substring(1);
        }
        int dot = s.indexOf('.');
        long cents;
        if (dot == -1) {
            cents = Long.parseLong(s) * 100;
        } else {
            String intPart = s.substring(0, dot);
            String fracPart = s.substring(dot + 1);
            long intCents = (intPart.isEmpty() ? 0 : Long.parseLong(intPart)) * 100;
            long fracCents;
            if (fracPart.length() == 1) {
                fracCents = Long.parseLong(fracPart) * 10;
            } else {
                fracCents = Long.parseLong(fracPart);
            }
            cents = intCents + fracCents;
        }
        return negative ? -cents : cents;
    }

    static String formatAmount(long cents) {
        boolean negative = cents < 0;
        long abs = negative ? -cents : cents;
        long intPart = abs / 100;
        long fracPart = abs % 100;
        return (negative ? "-" : "") + intPart + "." + (fracPart < 10 ? "0" : "") + fracPart;
    }

    static int compareUnsignedBytes(byte[] a, byte[] b) {
        int len = Math.min(a.length, b.length);
        for (int i = 0; i < len; i++) {
            int diff = (a[i] & 0xFF) - (b[i] & 0xFF);
            if (diff != 0) return diff;
        }
        return a.length - b.length;
    }

    // --- JSON Parser ---

    static Object parseJson(String json) {
        JsonParser p = new JsonParser(json);
        return p.parse();
    }

    static class JsonParser {
        String input;
        int pos;

        JsonParser(String input) {
            this.input = input;
            this.pos = 0;
        }

        Object parse() {
            skipWs();
            Object val = parseValue();
            return val;
        }

        void skipWs() {
            while (pos < input.length()) {
                char c = input.charAt(pos);
                if (c == ' ' || c == '\t' || c == '\n' || c == '\r') pos++;
                else break;
            }
        }

        Object parseValue() {
            skipWs();
            if (pos >= input.length()) return null;
            char c = input.charAt(pos);
            if (c == '{') return parseObject();
            if (c == '[') return parseArray();
            if (c == '"') return parseString();
            if (c == 't') { pos += 4; return Boolean.TRUE; }
            if (c == 'f') { pos += 5; return Boolean.FALSE; }
            if (c == 'n') { pos += 4; return null; }
            return parseNumber();
        }

        Map<String, Object> parseObject() {
            Map<String, Object> map = new LinkedHashMap<>();
            pos++; // {
            skipWs();
            if (pos < input.length() && input.charAt(pos) == '}') { pos++; return map; }
            while (true) {
                skipWs();
                String key = parseString();
                skipWs();
                pos++; // :
                skipWs();
                Object val = parseValue();
                map.put(key, val);
                skipWs();
                if (pos < input.length() && input.charAt(pos) == ',') { pos++; }
                else break;
            }
            skipWs();
            if (pos < input.length() && input.charAt(pos) == '}') pos++;
            return map;
        }

        List<Object> parseArray() {
            List<Object> list = new ArrayList<>();
            pos++; // [
            skipWs();
            if (pos < input.length() && input.charAt(pos) == ']') { pos++; return list; }
            while (true) {
                skipWs();
                list.add(parseValue());
                skipWs();
                if (pos < input.length() && input.charAt(pos) == ',') { pos++; }
                else break;
            }
            skipWs();
            if (pos < input.length() && input.charAt(pos) == ']') pos++;
            return list;
        }

        String parseString() {
            pos++; // opening "
            StringBuilder sb = new StringBuilder();
            while (pos < input.length()) {
                char c = input.charAt(pos);
                if (c == '"') { pos++; break; }
                if (c == '\\') {
                    pos++;
                    char esc = input.charAt(pos);
                    switch (esc) {
                        case '"': sb.append('"'); break;
                        case '\\': sb.append('\\'); break;
                        case '/': sb.append('/'); break;
                        case 'b': sb.append('\b'); break;
                        case 'f': sb.append('\f'); break;
                        case 'n': sb.append('\n'); break;
                        case 'r': sb.append('\r'); break;
                        case 't': sb.append('\t'); break;
                        case 'u': {
                            int hi = Integer.parseInt(input.substring(pos + 1, pos + 5), 16);
                            pos += 4;
                            if (hi >= 0xD800 && hi <= 0xDBFF && pos + 1 < input.length()
                                    && input.charAt(pos + 1) == '\\' && input.charAt(pos + 2) == 'u') {
                                int lo = Integer.parseInt(input.substring(pos + 3, pos + 7), 16);
                                pos += 6;
                                sb.append((char) hi);
                                sb.append((char) lo);
                            } else {
                                sb.append((char) hi);
                            }
                            break;
                        }
                    }
                } else {
                    sb.append(c);
                }
                pos++;
            }
            return sb.toString();
        }

        Number parseNumber() {
            int start = pos;
            if (pos < input.length() && input.charAt(pos) == '-') pos++;
            while (pos < input.length() && input.charAt(pos) >= '0' && input.charAt(pos) <= '9') pos++;
            boolean isFloat = false;
            if (pos < input.length() && input.charAt(pos) == '.') {
                isFloat = true;
                pos++;
                while (pos < input.length() && input.charAt(pos) >= '0' && input.charAt(pos) <= '9') pos++;
            }
            if (pos < input.length() && (input.charAt(pos) == 'e' || input.charAt(pos) == 'E')) {
                isFloat = true;
                pos++;
                if (pos < input.length() && (input.charAt(pos) == '+' || input.charAt(pos) == '-')) pos++;
                while (pos < input.length() && input.charAt(pos) >= '0' && input.charAt(pos) <= '9') pos++;
            }
            String numStr = input.substring(start, pos);
            if (isFloat) {
                return Double.parseDouble(numStr);
            } else {
                long val = Long.parseLong(numStr);
                if (val >= Integer.MIN_VALUE && val <= Integer.MAX_VALUE) return (int) val;
                return val;
            }
        }
    }

    static class HttpResponse {
        int status;
        Map<String, String> headers;
        String body;
    }
}

import * as fs from 'fs';
import * as path from 'path';
import * as http from 'http';

interface ClientConfig {
  client_id: string;
  client_secret: string;
  scope: string;
  page_size: number;
}

interface Order {
  id: string;
  customer: { id: string; name: string };
  amount: string;
  currency: string;
  status: string;
}

interface PageResponse {
  data: Order[];
  next_cursor: string | null;
}

interface HttpResponse {
  status: number;
  headers: http.IncomingHttpHeaders;
  body: string;
}

function formUrlEncode(s: string): string {
  let result = '';
  const buf = Buffer.from(s, 'utf-8');
  for (const byte of buf) {
    if (
      (byte >= 0x41 && byte <= 0x5A) ||
      (byte >= 0x61 && byte <= 0x7A) ||
      (byte >= 0x30 && byte <= 0x39) ||
      byte === 0x2D || byte === 0x2E || byte === 0x5F || byte === 0x2A
    ) {
      result += String.fromCharCode(byte);
    } else if (byte === 0x20) {
      result += '+';
    } else {
      result += '%' + byte.toString(16).toUpperCase().padStart(2, '0');
    }
  }
  return result;
}

function httpRequest(
  url: string,
  opts: { method: string; headers?: Record<string, string>; body?: string }
): Promise<HttpResponse> {
  return new Promise((resolve, reject) => {
    const parsed = new URL(url);
    const reqOpts: http.RequestOptions = {
      hostname: parsed.hostname,
      port: parsed.port ? parseInt(parsed.port) : 80,
      path: parsed.pathname + parsed.search,
      method: opts.method,
      headers: {
        'Connection': 'close',
        ...(opts.headers || {}),
      },
      agent: false,
    };
    if (opts.body) {
      const bodyBuf = Buffer.from(opts.body, 'utf-8');
      (reqOpts.headers as Record<string, string>)['Content-Length'] = bodyBuf.length.toString();
    }
    const req = http.request(reqOpts, (res) => {
      const chunks: Buffer[] = [];
      res.on('data', (chunk: Buffer) => chunks.push(chunk));
      res.on('end', () => {
        resolve({
          status: res.statusCode!,
          headers: res.headers,
          body: Buffer.concat(chunks).toString('utf-8'),
        });
      });
      res.on('error', reject);
    });
    req.on('error', reject);
    if (opts.body) req.write(opts.body);
    req.end();
  });
}

function sleep(ms: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

function fatal(status: number, body: string): never {
  process.stdout.write(`ERROR ${status} ${body}\n`);
  process.exit(0);
}

function parseAmount(s: string): bigint {
  let negative = false;
  let i = 0;
  if (s[i] === '-') {
    negative = true;
    i++;
  }
  let intPart = '';
  while (i < s.length && s[i] >= '0' && s[i] <= '9') {
    intPart += s[i];
    i++;
  }
  let decPart = '00';
  if (i < s.length && s[i] === '.') {
    i++;
    let dp = '';
    while (i < s.length && s[i] >= '0' && s[i] <= '9') {
      dp += s[i];
      i++;
    }
    if (dp.length === 1) dp += '0';
    decPart = dp;
  }
  const cents = BigInt(intPart) * 100n + BigInt(decPart);
  return negative ? -cents : cents;
}

function formatCents(cents: bigint): string {
  const negative = cents < 0n;
  const abs = negative ? -cents : cents;
  const intPart = abs / 100n;
  const decPart = abs % 100n;
  const decStr = decPart.toString().padStart(2, '0');
  return (negative ? '-' : '') + intPart.toString() + '.' + decStr;
}

function compareUtf8(a: string, b: string): number {
  const bufA = Buffer.from(a, 'utf-8');
  const bufB = Buffer.from(b, 'utf-8');
  const len = Math.min(bufA.length, bufB.length);
  for (let i = 0; i < len; i++) {
    if (bufA[i] !== bufB[i]) return bufA[i] - bufB[i];
  }
  return bufA.length - bufB.length;
}

async function main() {
  const args = process.argv.slice(2);
  const dataDir = args[0];
  const baseUrl = args[1];

  const config: ClientConfig = JSON.parse(
    fs.readFileSync(path.join(dataDir, 'client.json'), 'utf-8')
  );

  let accessToken: string;
  let tokenUsed = false;
  let pages = 0;
  let retries = 0;
  let reauths = 0;

  async function getToken(): Promise<string> {
    const body = `grant_type=client_credentials&scope=${formUrlEncode(config.scope)}`;
    const credentials =
      formUrlEncode(config.client_id) + ':' + formUrlEncode(config.client_secret);
    const b64 = Buffer.from(credentials, 'utf-8').toString('base64');

    const resp = await httpRequest(`${baseUrl}/oauth/token`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/x-www-form-urlencoded',
        'Authorization': `Basic ${b64}`,
      },
      body,
    });

    if (resp.status !== 200) {
      fatal(resp.status, resp.body);
    }

    const json = JSON.parse(resp.body);
    return json.access_token as string;
  }

  accessToken = await getToken();

  const orders: Order[] = [];
  let cursor: string | null = null;

  while (true) {
    let url = `${baseUrl}/orders?limit=${config.page_size}`;
    if (cursor !== null) {
      url += `&cursor=${encodeURIComponent(cursor)}`;
    }

    let resp: HttpResponse;
    while (true) {
      resp = await httpRequest(url, {
        method: 'GET',
        headers: {
          'Authorization': `Bearer ${accessToken}`,
        },
      });

      if (resp.status === 200) {
        tokenUsed = true;
        break;
      } else if (resp.status === 429) {
        retries++;
        const retryAfterHeader = resp.headers['retry-after'];
        const retryAfter =
          typeof retryAfterHeader === 'string'
            ? parseInt(retryAfterHeader, 10) || 0
            : 0;
        await sleep(retryAfter * 1000);
        continue;
      } else if (resp.status === 503) {
        retries++;
        await sleep(100);
        continue;
      } else if (resp.status === 401) {
        if (!tokenUsed) {
          fatal(resp.status, resp.body);
        }
        reauths++;
        accessToken = await getToken();
        tokenUsed = false;
        continue;
      } else {
        fatal(resp.status, resp.body);
      }
    }

    pages++;
    const pageData: PageResponse = JSON.parse(resp.body);
    for (const order of pageData.data) {
      orders.push(order);
    }
    cursor = pageData.next_cursor;
    if (cursor === null) break;
  }

  // Process orders
  const totals = new Map<string, bigint>();
  const totalInfo = new Map<string, { name: string; currency: string }>();
  const statusCounts = new Map<string, number>();

  for (const order of orders) {
    statusCounts.set(order.status, (statusCounts.get(order.status) || 0) + 1);

    if (order.status !== 'cancelled') {
      const name = order.customer.name;
      const currency = order.currency;
      const key = name + '\0' + currency;
      const cents = parseAmount(order.amount);
      totals.set(key, (totals.get(key) || 0n) + cents);
      if (!totalInfo.has(key)) {
        totalInfo.set(key, { name, currency });
      }
    }
  }

  // Build output lines
  const lines: string[] = [];

  // Sort totals by name (UTF-8 byte order), then currency
  const totalEntries: { name: string; currency: string; cents: bigint }[] = [];
  for (const [key, info] of totalInfo) {
    totalEntries.push({ name: info.name, currency: info.currency, cents: totals.get(key)! });
  }
  totalEntries.sort((a, b) => {
    const cmp = compareUtf8(a.name, b.name);
    if (cmp !== 0) return cmp;
    return compareUtf8(a.currency, b.currency);
  });

  for (const entry of totalEntries) {
    lines.push(`total ${entry.currency} ${formatCents(entry.cents)} ${entry.name}`);
  }

  // Status counts sorted by status (lowercase ASCII)
  const sortedStatuses = Array.from(statusCounts.entries()).sort((a, b) =>
    a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : 0
  );
  for (const [status, count] of sortedStatuses) {
    lines.push(`status ${status} ${count}`);
  }

  lines.push(
    `orders ${orders.length} pages ${pages} retries ${retries} reauth ${reauths}`
  );

  process.stdout.write(lines.join('\n') + '\n');
}

main().catch((e) => {
  process.stderr.write(String(e) + '\n');
  process.exit(1);
});

import Foundation

// MARK: - Helpers

func formURLEncode(_ s: String) -> String {
    var result = ""
    for byte in s.utf8 {
        if (byte >= 0x30 && byte <= 0x39) ||
           (byte >= 0x41 && byte <= 0x5A) ||
           (byte >= 0x61 && byte <= 0x7A) ||
           byte == 0x2D || byte == 0x2E || byte == 0x5F || byte == 0x2A {
            result.append(Character(UnicodeScalar(byte)))
        } else if byte == 0x20 {
            result.append("+")
        } else {
            result.append(String(format: "%%%02X", byte))
        }
    }
    return result
}

func percentEncode(_ s: String) -> String {
    var result = ""
    for byte in s.utf8 {
        if (byte >= 0x30 && byte <= 0x39) ||
           (byte >= 0x41 && byte <= 0x5A) ||
           (byte >= 0x61 && byte <= 0x7A) ||
           byte == 0x2D || byte == 0x2E || byte == 0x5F || byte == 0x7E {
            result.append(Character(UnicodeScalar(byte)))
        } else {
            result.append(String(format: "%%%02X", byte))
        }
    }
    return result
}

func parseCents(_ s: String) -> Int64 {
    var negative = false
    var idx = s.startIndex
    if idx < s.endIndex && s[idx] == "-" {
        negative = true
        idx = s.index(after: idx)
    }
    var intPart: Int64 = 0
    while idx < s.endIndex && s[idx] != "." {
        intPart = intPart * 10 + Int64(s[idx].asciiValue! - 48)
        idx = s.index(after: idx)
    }
    var fracPart: Int64 = 0
    if idx < s.endIndex && s[idx] == "." {
        idx = s.index(after: idx)
        var digits = 0
        while idx < s.endIndex && digits < 2 {
            fracPart = fracPart * 10 + Int64(s[idx].asciiValue! - 48)
            digits += 1
            idx = s.index(after: idx)
        }
        while digits < 2 {
            fracPart *= 10
            digits += 1
        }
    }
    let total = intPart * 100 + fracPart
    return negative ? -total : total
}

func formatCents(_ cents: Int64) -> String {
    let negative = cents < 0
    let absCents = negative ? (-cents) : cents
    let intPart = absCents / 100
    let fracPart = absCents % 100
    let sign = negative ? "-" : ""
    let fracStr = fracPart < 10 ? "0\(fracPart)" : "\(fracPart)"
    return "\(sign)\(intPart).\(fracStr)"
}

// MARK: - HTTP

let sessionConfig = URLSessionConfiguration.default
sessionConfig.requestCachePolicy = .reloadIgnoringLocalCacheData
sessionConfig.urlCache = nil
sessionConfig.httpShouldSetCookies = false
let session = URLSession(configuration: sessionConfig)

func httpRequest(method: String, url: String, headers: [String: String], body: Data?) -> (Int, [String: String], Data) {
    let semaphore = DispatchSemaphore(value: 0)
    var statusCode = 0
    var responseHeaders: [String: String] = [:]
    var responseBody = Data()

    guard let urlObj = URL(string: url) else {
        fatalError("Invalid URL: \(url)")
    }

    var request = URLRequest(url: urlObj)
    request.httpMethod = method
    request.timeoutInterval = 120
    for (key, value) in headers {
        request.setValue(value, forHTTPHeaderField: key)
    }
    if let body = body {
        request.httpBody = body
    }

    let task = session.dataTask(with: request) { data, response, error in
        if let error = error {
            FileHandle.standardError.write("HTTP error: \(error.localizedDescription)\n".data(using: .utf8)!)
            semaphore.signal()
            return
        }
        if let httpResponse = response as? HTTPURLResponse {
            statusCode = httpResponse.statusCode
            for (key, value) in httpResponse.allHeaderFields {
                if let k = key as? String, let v = value as? String {
                    responseHeaders[k.lowercased()] = v
                }
            }
        }
        responseBody = data ?? Data()
        semaphore.signal()
    }
    task.resume()
    semaphore.wait()

    return (statusCode, responseHeaders, responseBody)
}

// MARK: - Main

let args = CommandLine.arguments
guard args.count >= 3 else { exit(1) }
let dataDir = args[1]
let baseURL = args[2]

let clientPath = (dataDir as NSString).appendingPathComponent("client.json")
let clientData = try! Data(contentsOf: URL(fileURLWithPath: clientPath))
let client = try! JSONSerialization.jsonObject(with: clientData) as! [String: Any]
let clientId = client["client_id"] as! String
let clientSecret = client["client_secret"] as! String
let scope = client["scope"] as! String
let pageSize = (client["page_size"] as! NSNumber).intValue

func getToken() -> String {
    let encodedId = formURLEncode(clientId)
    let encodedSecret = formURLEncode(clientSecret)
    let credentials = "\(encodedId):\(encodedSecret)"
    let b64 = Data(credentials.utf8).base64EncodedString()

    let bodyStr = "grant_type=client_credentials&scope=\(formURLEncode(scope))"
    let bodyData = Data(bodyStr.utf8)

    let url = "\(baseURL)/oauth/token"
    let (status, _, body) = httpRequest(method: "POST", url: url, headers: [
        "Content-Type": "application/x-www-form-urlencoded",
        "Authorization": "Basic \(b64)"
    ], body: bodyData)

    if status != 200 {
        let bodyStr = String(data: body, encoding: .utf8) ?? ""
        print("ERROR \(status) \(bodyStr)")
        exit(0)
    }

    let json = try! JSONSerialization.jsonObject(with: body) as! [String: Any]
    return json["access_token"] as! String
}

var accessToken = getToken()
var firstRequestWithToken = true
var cursor: String? = nil
var allOrders: [[String: Any]] = []
var pagesCount = 0
var retriesCount = 0
var reauthCount = 0

while true {
    let isThisFirst = firstRequestWithToken
    firstRequestWithToken = false

    var urlString = "\(baseURL)/orders?limit=\(pageSize)"
    if let c = cursor {
        urlString += "&cursor=\(percentEncode(c))"
    }

    let (status, headers, body) = httpRequest(method: "GET", url: urlString, headers: [
        "Authorization": "Bearer \(accessToken)"
    ], body: nil)

    if status == 200 {
        pagesCount += 1
        let json = try! JSONSerialization.jsonObject(with: body) as! [String: Any]
        let data = json["data"] as! [[String: Any]]
        allOrders.append(contentsOf: data)

        let nextCursor = json["next_cursor"]
        if nextCursor == nil || nextCursor is NSNull {
            break
        }
        cursor = nextCursor as! String
    } else if status == 429 {
        retriesCount += 1
        let retryAfter = Int(headers["retry-after"] ?? "1") ?? 1
        Thread.sleep(forTimeInterval: TimeInterval(retryAfter))
    } else if status == 503 {
        retriesCount += 1
        Thread.sleep(forTimeInterval: 0.5)
    } else if status == 401 {
        if isThisFirst {
            let bodyStr = String(data: body, encoding: .utf8) ?? ""
            print("ERROR 401 \(bodyStr)")
            exit(0)
        }
        reauthCount += 1
        accessToken = getToken()
        firstRequestWithToken = true
    } else {
        let bodyStr = String(data: body, encoding: .utf8) ?? ""
        print("ERROR \(status) \(bodyStr)")
        exit(0)
    }
}

// MARK: - Process orders

struct PairKey: Hashable {
    let name: String
    let currency: String
}

var totals: [PairKey: Int64] = [:]
var statusCounts: [String: Int] = [:]

for order in allOrders {
    let status = order["status"] as! String
    statusCounts[status, default: 0] += 1

    if status == "cancelled" { continue }

    let customer = order["customer"] as! [String: Any]
    let name = customer["name"] as! String
    let currency = order["currency"] as! String
    let amount = order["amount"] as! String
    let cents = parseCents(amount)

    let key = PairKey(name: name, currency: currency)
    totals[key, default: 0] += cents
}

// Sort totals by name (UTF-8 byte order), then by currency (UTF-8 byte order)
var totalLines: [(name: String, currency: String, cents: Int64)] = []
for (key, cents) in totals {
    totalLines.append((name: key.name, currency: key.currency, cents: cents))
}

totalLines.sort { a, b in
    let aName = Array(a.name.utf8)
    let bName = Array(b.name.utf8)
    if aName != bName {
        return aName.lexicographicallyPrecedes(bName)
    }
    return Array(a.currency.utf8).lexicographicallyPrecedes(Array(b.currency.utf8))
}

for line in totalLines {
    print("total \(line.currency) \(formatCents(line.cents)) \(line.name)")
}

// Sort statuses alphabetically (ASCII lowercase)
let sortedStatuses = statusCounts.keys.sorted()
for status in sortedStatuses {
    print("status \(status) \(statusCounts[status]!)")
}

// Final summary line
print("orders \(allOrders.count) pages \(pagesCount) retries \(retriesCount) reauth \(reauthCount)")

use std::collections::HashMap;
use std::io::{Read, Write, BufRead, BufReader};
use std::net::TcpStream;
use std::thread::sleep;
use std::time::Duration;
use std::process;

// ==================== JSON ====================

#[derive(Debug, Clone)]
enum Json {
    Null,
    Bool(bool),
    Num(f64),
    Str(String),
    Arr(Vec<Json>),
    Obj(Vec<(String, Json)>),
}

impl Json {
    fn get(&self, key: &str) -> Option<&Json> {
        if let Json::Obj(pairs) = self {
            for (k, v) in pairs {
                if k == key { return Some(v); }
            }
        }
        None
    }
    fn as_str(&self) -> &str {
        if let Json::Str(s) = self { s } else { panic!("not a string") }
    }
    fn as_num(&self) -> f64 {
        if let Json::Num(n) = self { *n } else { panic!("not a number") }
    }
}

struct JsonParser<'a> {
    input: &'a [u8],
    pos: usize,
}

impl<'a> JsonParser<'a> {
    fn new(input: &'a str) -> Self {
        JsonParser { input: input.as_bytes(), pos: 0 }
    }
    fn parse(&mut self) -> Json {
        self.skip_ws();
        let val = self.parse_value();
        val
    }
    fn skip_ws(&mut self) {
        while self.pos < self.input.len() {
            match self.input[self.pos] {
                b' ' | b'\t' | b'\n' | b'\r' => self.pos += 1,
                _ => break,
            }
        }
    }
    fn peek(&self) -> Option<u8> {
        if self.pos < self.input.len() { Some(self.input[self.pos]) } else { None }
    }
    fn expect(&mut self, b: u8) {
        if self.peek() != Some(b) {
            panic!("expected '{}' at pos {}", b as char, self.pos);
        }
        self.pos += 1;
    }
    fn parse_value(&mut self) -> Json {
        match self.peek() {
            Some(b'{') => self.parse_object(),
            Some(b'[') => self.parse_array(),
            Some(b'"') => Json::Str(self.parse_string()),
            Some(b't') => { self.expect_lit("true"); Json::Bool(true) }
            Some(b'f') => { self.expect_lit("false"); Json::Bool(false) }
            Some(b'n') => { self.expect_lit("null"); Json::Null }
            _ => self.parse_number(),
        }
    }
    fn expect_lit(&mut self, lit: &str) {
        for &b in lit.as_bytes() { self.expect(b); }
    }
    fn parse_object(&mut self) -> Json {
        self.expect(b'{');
        let mut pairs = Vec::new();
        self.skip_ws();
        if self.peek() == Some(b'}') { self.pos += 1; return Json::Obj(pairs); }
        loop {
            self.skip_ws();
            let key = self.parse_string();
            self.skip_ws();
            self.expect(b':');
            self.skip_ws();
            let val = self.parse_value();
            pairs.push((key, val));
            self.skip_ws();
            match self.peek() {
                Some(b',') => { self.pos += 1; }
                Some(b'}') => { self.pos += 1; break; }
                _ => panic!("expected , or }} at pos {}", self.pos),
            }
        }
        Json::Obj(pairs)
    }
    fn parse_array(&mut self) -> Json {
        self.expect(b'[');
        let mut items = Vec::new();
        self.skip_ws();
        if self.peek() == Some(b']') { self.pos += 1; return Json::Arr(items); }
        loop {
            self.skip_ws();
            items.push(self.parse_value());
            self.skip_ws();
            match self.peek() {
                Some(b',') => { self.pos += 1; }
                Some(b']') => { self.pos += 1; break; }
                _ => panic!("expected , or ] at pos {}", self.pos),
            }
        }
        Json::Arr(items)
    }
    fn parse_string(&mut self) -> String {
        self.expect(b'"');
        let mut bytes: Vec<u8> = Vec::new();
        loop {
            let b = self.input[self.pos];
            self.pos += 1;
            match b {
                b'"' => break,
                b'\\' => {
                    let esc = self.input[self.pos];
                    self.pos += 1;
                    match esc {
                        b'"' => bytes.push(b'"'),
                        b'\\' => bytes.push(b'\\'),
                        b'/' => bytes.push(b'/'),
                        b'b' => bytes.push(0x08),
                        b'f' => bytes.push(0x0C),
                        b'n' => bytes.push(b'\n'),
                        b'r' => bytes.push(b'\r'),
                        b't' => bytes.push(b'\t'),
                        b'u' => {
                            let cp = self.parse_hex4();
                            let code_point = if cp >= 0xD800 && cp <= 0xDBFF {
                                self.expect(b'\\');
                                self.expect(b'u');
                                let cp2 = self.parse_hex4();
                                0x10000 + ((cp - 0xD800) << 10) + (cp2 - 0xDC00)
                            } else {
                                cp
                            };
                            let ch = char::from_u32(code_point).unwrap();
                            let mut buf = [0u8; 4];
                            let s = ch.encode_utf8(&mut buf);
                            bytes.extend_from_slice(s.as_bytes());
                        }
                        _ => panic!("unknown escape \\{}", esc as char),
                    }
                }
                _ => bytes.push(b),
            }
        }
        String::from_utf8(bytes).unwrap()
    }
    fn parse_hex4(&mut self) -> u32 {
        let hex = std::str::from_utf8(&self.input[self.pos..self.pos + 4]).unwrap();
        self.pos += 4;
        u32::from_str_radix(hex, 16).unwrap()
    }
    fn parse_number(&mut self) -> Json {
        let start = self.pos;
        if self.peek() == Some(b'-') { self.pos += 1; }
        while self.pos < self.input.len() && self.input[self.pos].is_ascii_digit() { self.pos += 1; }
        if self.pos < self.input.len() && self.input[self.pos] == b'.' {
            self.pos += 1;
            while self.pos < self.input.len() && self.input[self.pos].is_ascii_digit() { self.pos += 1; }
        }
        if self.pos < self.input.len() && (self.input[self.pos] == b'e' || self.input[self.pos] == b'E') {
            self.pos += 1;
            if self.pos < self.input.len() && (self.input[self.pos] == b'+' || self.input[self.pos] == b'-') { self.pos += 1; }
            while self.pos < self.input.len() && self.input[self.pos].is_ascii_digit() { self.pos += 1; }
        }
        let s = std::str::from_utf8(&self.input[start..self.pos]).unwrap();
        Json::Num(s.parse::<f64>().unwrap())
    }
}

// ==================== Encoding helpers ====================

fn form_urlencode(s: &str) -> String {
    let mut result = String::new();
    for b in s.bytes() {
        match b {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'.' | b'*' | b'_' => {
                result.push(b as char);
            }
            b' ' => result.push('+'),
            _ => result.push_str(&format!("%{:02X}", b)),
        }
    }
    result
}

fn percent_encode_query(s: &str) -> String {
    let mut result = String::new();
    for b in s.bytes() {
        match b {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'_' | b'.' | b'~' => {
                result.push(b as char);
            }
            _ => result.push_str(&format!("%{:02X}", b)),
        }
    }
    result
}

fn base64_encode(data: &[u8]) -> String {
    const CHARS: &[u8] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
    let mut result = String::new();
    for chunk in data.chunks(3) {
        let b0 = chunk[0] as u32;
        let b1 = if chunk.len() > 1 { chunk[1] as u32 } else { 0 };
        let b2 = if chunk.len() > 2 { chunk[2] as u32 } else { 0 };
        let n = (b0 << 16) | (b1 << 8) | b2;
        result.push(CHARS[((n >> 18) & 63) as usize] as char);
        result.push(CHARS[((n >> 12) & 63) as usize] as char);
        if chunk.len() > 1 {
            result.push(CHARS[((n >> 6) & 63) as usize] as char);
        } else {
            result.push('=');
        }
        if chunk.len() > 2 {
            result.push(CHARS[(n & 63) as usize] as char);
        } else {
            result.push('=');
        }
    }
    result
}

// ==================== HTTP ====================

struct HttpResponse {
    status: u16,
    headers: Vec<(String, String)>,
    body: String,
}

fn parse_url(url: &str) -> (String, u16, String) {
    let rest = url.strip_prefix("http://").unwrap();
    let (authority, path) = if let Some(slash_pos) = rest.find('/') {
        (&rest[..slash_pos], &rest[slash_pos..])
    } else {
        (rest, "")
    };
    let (host, port) = if let Some(colon_pos) = authority.rfind(':') {
        (&authority[..colon_pos], authority[colon_pos + 1..].parse::<u16>().unwrap())
    } else {
        (authority, 80u16)
    };
    (host.to_string(), port, path.to_string())
}

fn read_chunked_body(reader: &mut BufReader<TcpStream>) -> String {
    let mut body = Vec::new();
    loop {
        let mut line = String::new();
        reader.read_line(&mut line).unwrap();
        let size_str = line.trim();
        let size = usize::from_str_radix(size_str, 16).unwrap();
        if size == 0 {
            // Read trailing headers / final CRLF
            loop {
                let mut line = String::new();
                reader.read_line(&mut line).unwrap();
                if line.trim().is_empty() { break; }
            }
            break;
        }
        let mut buf = vec![0u8; size];
        reader.read_exact(&mut buf).unwrap();
        body.extend_from_slice(&buf);
        // Read CRLF after chunk data
        let mut crlf = [0u8; 2];
        reader.read_exact(&mut crlf).unwrap();
    }
    String::from_utf8(body).unwrap()
}

fn http_request(host: &str, port: u16, method: &str, path: &str, headers: &[(&str, String)], body: Option<&str>) -> HttpResponse {
    let addr = format!("{}:{}", host, port);
    let mut stream = TcpStream::connect(&addr).expect("connection failed");
    stream.set_read_timeout(Some(Duration::from_secs(30))).unwrap();
    stream.set_write_timeout(Some(Duration::from_secs(30))).unwrap();

    let mut req = format!("{} {} HTTP/1.1\r\n", method, path);
    req.push_str(&format!("Host: {}\r\n", addr));
    for (k, v) in headers {
        req.push_str(&format!("{}: {}\r\n", k, v));
    }
    if let Some(b) = body {
        req.push_str(&format!("Content-Length: {}\r\n", b.len()));
    }
    req.push_str("\r\n");
    if let Some(b) = body {
        req.push_str(b);
    }

    stream.write_all(req.as_bytes()).unwrap();
    stream.flush().unwrap();

    let mut reader = BufReader::new(stream);

    // Status line
    let mut status_line = String::new();
    reader.read_line(&mut status_line).unwrap();
    let parts: Vec<&str> = status_line.trim().splitn(3, ' ').collect();
    let status: u16 = parts[1].parse().unwrap();

    // Headers
    let mut headers_vec = Vec::new();
    loop {
        let mut line = String::new();
        reader.read_line(&mut line).unwrap();
        let trimmed = line.trim_end();
        if trimmed.is_empty() { break; }
        let colon_pos = trimmed.find(':').unwrap();
        let key = trimmed[..colon_pos].trim().to_lowercase();
        let value = trimmed[colon_pos + 1..].trim().to_string();
        headers_vec.push((key, value));
    }

    // Body
    let is_chunked = headers_vec.iter().any(|(k, v)| k == "transfer-encoding" && v.to_lowercase().contains("chunked"));
    let body = if is_chunked {
        read_chunked_body(&mut reader)
    } else if let Some((_, v)) = headers_vec.iter().find(|(k, _)| k == "content-length") {
        let len: usize = v.parse().unwrap();
        if len == 0 {
            String::new()
        } else {
            let mut buf = vec![0u8; len];
            reader.read_exact(&mut buf).unwrap();
            String::from_utf8(buf).unwrap()
        }
    } else {
        let mut buf = Vec::new();
        reader.read_to_end(&mut buf).unwrap();
        String::from_utf8(buf).unwrap()
    };

    HttpResponse { status, headers: headers_vec, body }
}

// ==================== Amount parsing ====================

fn parse_cents(s: &str) -> i64 {
    let (neg, s) = if s.starts_with('-') { (true, &s[1..]) } else { (false, s) };
    let (int_part, frac_part) = if let Some(dot_pos) = s.find('.') {
        (&s[..dot_pos], &s[dot_pos + 1..])
    } else {
        (s, "")
    };
    let int_cents: i64 = int_part.parse::<i64>().unwrap() * 100;
    let frac_cents: i64 = if frac_part.is_empty() {
        0
    } else if frac_part.len() == 1 {
        frac_part.parse::<i64>().unwrap() * 10
    } else {
        frac_part[..2].parse::<i64>().unwrap()
    };
    let total = int_cents + frac_cents;
    if neg { -total } else { total }
}

fn format_cents(cents: i64) -> String {
    if cents < 0 {
        let abs = -(cents as i128);
        format!("-{}.{:02}", abs / 100, abs % 100)
    } else {
        format!("{}.{:02}", cents / 100, cents % 100)
    }
}

// ==================== Main ====================

fn get_token(host: &str, port: u16, path_prefix: &str, client_id: &str, client_secret: &str, scope: &str) -> String {
    let encoded_id = form_urlencode(client_id);
    let encoded_secret = form_urlencode(client_secret);
    let credentials = format!("{}:{}", encoded_id, encoded_secret);
    let auth_b64 = base64_encode(credentials.as_bytes());
    let auth_header = format!("Basic {}", auth_b64);

    let body = format!("grant_type=client_credentials&scope={}", form_urlencode(scope));
    let path = format!("{}/oauth/token", path_prefix);

    let resp = http_request(host, port, "POST", &path,
        &[("Authorization", auth_header), ("Content-Type", "application/x-www-form-urlencoded".to_string())],
        Some(&body));

    if resp.status != 200 {
        println!("ERROR {} {}", resp.status, resp.body);
        process::exit(0);
    }

    let json = JsonParser::new(&resp.body).parse();
    json.get("access_token").unwrap().as_str().to_string()
}

fn main() {
    let args: Vec<String> = std::env::args().collect();
    let data_dir = &args[1];
    let base_url = &args[2];

    // Read client.json
    let client_json_str = std::fs::read_to_string(format!("{}/client.json", data_dir)).unwrap();
    let client = JsonParser::new(&client_json_str).parse();

    let client_id = client.get("client_id").unwrap().as_str().to_string();
    let client_secret = client.get("client_secret").unwrap().as_str().to_string();
    let scope = client.get("scope").unwrap().as_str().to_string();
    let page_size = client.get("page_size").unwrap().as_num() as usize;

    let (host, port, path_prefix) = parse_url(base_url);

    // Get initial token
    let mut token = get_token(&host, port, &path_prefix, &client_id, &client_secret, &scope);

    // Fetch orders
    let mut all_orders: Vec<Json> = Vec::new();
    let mut pages: usize = 0;
    let mut retries: usize = 0;
    let mut reauths: usize = 0;
    let mut cursor: Option<String> = None;
    let mut got_success_with_token = false;

    loop {
        let path = if let Some(ref c) = cursor {
            format!("{}/orders?limit={}&cursor={}", path_prefix, page_size, percent_encode_query(c))
        } else {
            format!("{}/orders?limit={}", path_prefix, page_size)
        };

        let auth_value = format!("Bearer {}", token);
        let resp = http_request(&host, port, "GET", &path, &[("Authorization", auth_value)], None);

        match resp.status {
            200 => {
                pages += 1;
                got_success_with_token = true;
                let json = JsonParser::new(&resp.body).parse();
                if let Some(data) = json.get("data") {
                    if let Json::Arr(items) = data {
                        all_orders.extend(items.iter().cloned());
                    }
                }
                let next = json.get("next_cursor");
                match next {
                    Some(Json::Str(s)) => {
                        cursor = Some(s.clone());
                    }
                    _ => {
                        break;
                    }
                }
            }
            429 => {
                retries += 1;
                let retry_after = resp.headers.iter()
                    .find(|(k, _)| k == "retry-after")
                    .and_then(|(_, v)| v.parse::<u64>().ok())
                    .unwrap_or(1);
                sleep(Duration::from_secs(retry_after));
            }
            503 => {
                retries += 1;
                sleep(Duration::from_millis(500));
            }
            401 => {
                if !got_success_with_token {
                    println!("ERROR {} {}", resp.status, resp.body);
                    process::exit(0);
                }
                reauths += 1;
                token = get_token(&host, port, &path_prefix, &client_id, &client_secret, &scope);
                got_success_with_token = false;
            }
            _ => {
                println!("ERROR {} {}", resp.status, resp.body);
                process::exit(0);
            }
        }
    }

    // Process orders
    let mut totals: HashMap<(String, String), i64> = HashMap::new();
    let mut status_counts: HashMap<String, usize> = HashMap::new();

    for order in &all_orders {
        let status = order.get("status").unwrap().as_str().to_string();
        *status_counts.entry(status.clone()).or_insert(0) += 1;

        if status != "cancelled" {
            let name = order.get("customer").unwrap().get("name").unwrap().as_str().to_string();
            let currency = order.get("currency").unwrap().as_str().to_string();
            let amount_str = order.get("amount").unwrap().as_str();
            let cents = parse_cents(amount_str);
            *totals.entry((name, currency)).or_insert(0) += cents;
        }
    }

    // Sort totals by (name, currency) - Rust String Ord is byte-order which equals code-point order for UTF-8
    let mut total_entries: Vec<((String, String), i64)> = totals.into_iter().collect();
    total_entries.sort_by(|a, b| a.0.cmp(&b.0));

    for ((name, currency), cents) in &total_entries {
        println!("total {} {} {}", currency, format_cents(*cents), name);
    }

    // Sort statuses
    let mut status_entries: Vec<(String, usize)> = status_counts.into_iter().collect();
    status_entries.sort();

    for (status, count) in &status_entries {
        println!("status {} {}", status, count);
    }

    // Final line
    println!("orders {} pages {} retries {} reauth {}", all_orders.len(), pages, retries, reauths);
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
