/* ============ Growable buffer ============ */
typedef struct { char *data; size_t len, cap; } buf_t;
static void buf_init(buf_t *b) { b->data=NULL; b->len=0; b->cap=0; }
static void buf_append(buf_t *b, const char *s, size_t n) {
    if(b->len+n > b->cap){ b->cap=(b->len+n)*2; if(b->cap<256)b->cap=256; b->data=realloc(b->data,b->cap); }
    memcpy(b->data+b->len,s,n); b->len+=n;
}
static void buf_appendc(buf_t *b, char c){ buf_append(b,&c,1); }
static void buf_appends(buf_t *b, const char *s){ buf_append(b,s,strlen(s)); }

/* ============ Base64 ============ */
static const char b64_tab[]="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
static char *base64_encode(const unsigned char *data, size_t len){
    size_t olen=4*((len+2)/3);
    char *out=malloc(olen+1);
    size_t i,j;
    for(i=0,j=0;i<len;){
        unsigned int a=i<len?data[i++]:0;
        unsigned int b=i<len?data[i++]:0;
        unsigned int c=i<len?data[i++]:0;
        unsigned int t=(a<<16)|(b<<8)|c;
        out[j++]=b64_tab[(t>>18)&0x3F];
        out[j++]=b64_tab[(t>>12)&0x3F];
        out[j++]=b64_tab[(t>>6)&0x3F];
        out[j++]=b64_tab[t&0x3F];
    }
    if(len%3==1){out[olen-2]='=';out[olen-1]='=';}
    else if(len%3==2){out[olen-1]='=';}
    out[olen]='\0';
    return out;
}

/* ============ URL encoding ============ */
static char *url_encode_rfc6749(const char *s){
    buf_t b; buf_init(&b);
    for(const unsigned char *p=(const unsigned char*)s;*p;p++){
        if(isalnum(*p)||*p=='-'||*p=='.'||*p=='_'||*p=='*') buf_appendc(&b,*p);
        else if(*p==' ') buf_appends(&b,"+");
        else { char h[4]; snprintf(h,4,"%%%02X",*p); buf_appends(&b,h); }
    }
    buf_appendc(&b,'\0');
    return b.data;
}
static char *url_encode_query(const char *s){
    buf_t b; buf_init(&b);
    for(const unsigned char *p=(const unsigned char*)s;*p;p++){
        if(isalnum(*p)||*p=='-'||*p=='.'||*p=='_'||*p=='~') buf_appendc(&b,*p);
        else { char h[4]; snprintf(h,4,"%%%02X",*p); buf_appends(&b,h); }
    }
    buf_appendc(&b,'\0');
    return b.data;
}

/* ============ JSON Parser ============ */
typedef enum{JV_NULL,JV_TRUE,JV_FALSE,JV_NUMBER,JV_STRING,JV_ARRAY,JV_OBJECT}jtype;
typedef struct jval{
    jtype type;
    char *str;
    long long num;
    struct jval **arr; int arr_len;
    char **keys; struct jval **vals; int obj_len;
}jval;

static void skip_ws(const char **pp){ while(**pp==' '||**pp=='\t'||**pp=='\n'||**pp=='\r')(*pp)++; }
static int hex_val(char c){ if(c>='0'&&c<='9')return c-'0'; if(c>='a'&&c<='f')return c-'a'+10; if(c>='A'&&c<='F')return c-'A'+10; return 0; }

static void utf8_encode(int cp, buf_t *out){
    if(cp<0x80){ buf_appendc(out,cp); }
    else if(cp<0x800){ buf_appendc(out,0xC0|(cp>>6)); buf_appendc(out,0x80|(cp&0x3F)); }
    else if(cp<0x10000){ buf_appendc(out,0xE0|(cp>>12)); buf_appendc(out,0x80|((cp>>6)&0x3F)); buf_appendc(out,0x80|(cp&0x3F)); }
    else{ buf_appendc(out,0xF0|(cp>>18)); buf_appendc(out,0x80|((cp>>12)&0x3F)); buf_appendc(out,0x80|((cp>>6)&0x3F)); buf_appendc(out,0x80|(cp&0x3F)); }
}

static char *parse_json_string(const char **pp){
    (*pp)++;
    buf_t b; buf_init(&b);
    while(**pp!='"'){
        if(**pp=='\\'){
            (*pp)++;
            switch(**pp){
                case '"': buf_appendc(&b,'"'); break;
                case '\\':buf_appendc(&b,'\\');break;
                case '/': buf_appendc(&b,'/'); break;
                case 'b': buf_appendc(&b,'\b');break;
                case 'f': buf_appendc(&b,'\f');break;
                case 'n': buf_appendc(&b,'\n');break;
                case 'r': buf_appendc(&b,'\r');break;
                case 't': buf_appendc(&b,'\t');break;
                case 'u':{
                    (*pp)++;
                    int cp=0;
                    for(int i=0;i<4;i++) cp=(cp<<4)|hex_val(*(*pp)++);
                    (*pp)--;
                    if(cp>=0xD800&&cp<=0xDBFF){
                        (*pp)++;
                        if(**pp=='\\'&&(*pp)[1]=='u'){
                            *pp+=2;
                            int lo=0;
                            for(int i=0;i<4;i++) lo=(lo<<4)|hex_val(*(*pp)++);
                            (*pp)--;
                            cp=0x10000+((cp-0xD800)<<10)+(lo-0xDC00);
                        }
                    }
                    utf8_encode(cp,&b);
                    break;
                }
                default: buf_appendc(&b,**pp); break;
            }
            (*pp)++;
        } else {
            buf_appendc(&b,**pp);
            (*pp)++;
        }
    }
    (*pp)++;
    buf_appendc(&b,'\0');
    return b.data;
}

static jval *parse_value(const char **pp);

static jval *parse_object(const char **pp){
    jval *v=calloc(1,sizeof(jval)); v->type=JV_OBJECT;
    (*pp)++; skip_ws(pp);
    if(**pp=='}'){(*pp)++;return v;}
    int cap=8;
    v->keys=malloc(cap*sizeof(char*)); v->vals=malloc(cap*sizeof(jval*));
    while(1){
        skip_ws(pp);
        char *key=parse_json_string(pp);
        skip_ws(pp); (*pp)++; skip_ws(pp);
        jval *val=parse_value(pp);
        if(v->obj_len>=cap){cap*=2;v->keys=realloc(v->keys,cap*sizeof(char*));v->vals=realloc(v->vals,cap*sizeof(jval*));}
        v->keys[v->obj_len]=key; v->vals[v->obj_len]=val; v->obj_len++;
        skip_ws(pp);
        if(**pp==','){(*pp)++;continue;}
        if(**pp=='}'){(*pp)++;break;}
        break;
    }
    return v;
}

static jval *parse_array(const char **pp){
    jval *v=calloc(1,sizeof(jval)); v->type=JV_ARRAY;
    (*pp)++; skip_ws(pp);
    if(**pp==']'){(*pp)++;return v;}
    int cap=8;
    v->arr=malloc(cap*sizeof(jval*));
    while(1){
        skip_ws(pp);
        jval *item=parse_value(pp);
        if(v->arr_len>=cap){cap*=2;v->arr=realloc(v->arr,cap*sizeof(jval*));}
        v->arr[v->arr_len++]=item;
        skip_ws(pp);
        if(**pp==','){(*pp)++;continue;}
        if(**pp==']'){(*pp)++;break;}
        break;
    }
    return v;
}

static jval *parse_value(const char **pp){
    skip_ws(pp);
    if(**pp=='"'){jval*v=calloc(1,sizeof(jval));v->type=JV_STRING;v->str=parse_json_string(pp);return v;}
    if(**pp=='{')return parse_object(pp);
    if(**pp=='[')return parse_array(pp);
    jval *v=calloc(1,sizeof(jval));
    if(!strncmp(*pp,"null",4)){v->type=JV_NULL;*pp+=4;}
    else if(!strncmp(*pp,"true",4)){v->type=JV_TRUE;*pp+=4;}
    else if(!strncmp(*pp,"false",5)){v->type=JV_FALSE;*pp+=5;}
    else{
        v->type=JV_NUMBER;
        char *end;
        v->num=strtoll(*pp,&end,10);
        *pp=end;
        if(**pp=='.'){(*pp)++;while(isdigit(**pp))(*pp)++;}
        if(**pp=='e'||**pp=='E'){(*pp)++;if(**pp=='+'||**pp=='-')(*pp)++;while(isdigit(**pp))(*pp)++;}
    }
    return v;
}

static jval *jget(jval *obj,const char *key){
    if(!obj||obj->type!=JV_OBJECT)return NULL;
    for(int i=0;i<obj->obj_len;i++) if(strcmp(obj->keys[i],key)==0)return obj->vals[i];
    return NULL;
}

/* ============ HTTP Client ============ */
typedef struct{
    int status;
    char *body; size_t body_len;
    char *hn[64]; char *hv[64]; int hc;
}http_resp;

static char *get_header(http_resp *r,const char *name){
    for(int i=0;i<r->hc;i++) if(strcasecmp(r->hn[i],name)==0)return r->hv[i];
    return NULL;
}

static http_resp *http_request(const char *host,int port,const char *method,
    const char *path,const char *extra_hdrs,const char *body,size_t body_len)
{
    int fd=socket(AF_INET,SOCK_STREAM,0);
    struct addrinfo hints={0},*res;
    hints.ai_family=AF_INET; hints.ai_socktype=SOCK_STREAM;
    char ps[16]; snprintf(ps,16,"%d",port);
    getaddrinfo(host,ps,&hints,&res);
    if(connect(fd,res->ai_addr,res->ai_addrlen)<0){perror("connect");exit(1);}
    freeaddrinfo(res);

    buf_t req; buf_init(&req);
    buf_appends(&req,method); buf_appendc(&req,' ');
    buf_appends(&req,path); buf_appends(&req," HTTP/1.1\r\n");
    buf_appends(&req,"Host: "); buf_appends(&req,host);
    if(port!=80){char p2[16];snprintf(p2,16,":%d",port);buf_appends(&req,p2);}
    buf_appends(&req,"\r\nConnection: close\r\n");
    if(extra_hdrs)buf_appends(&req,extra_hdrs);
    if(body&&body_len>0){char cl[64];snprintf(cl,64,"Content-Length: %zu\r\n",body_len);buf_appends(&req,cl);}
    buf_appends(&req,"\r\n");
    if(body&&body_len>0)buf_append(&req,body,body_len);

    write(fd,req.data,req.len);
    shutdown(fd,SHUT_WR);

    buf_t resp; buf_init(&resp);
    char tmp[8192]; ssize_t n;
    while((n=read(fd,tmp,sizeof(tmp)))>0) buf_append(&resp,tmp,n);
    close(fd);

    http_resp *r=calloc(1,sizeof(http_resp));
    char *data=resp.data;
    char *pos=data;

    if(strncmp(pos,"HTTP/1.1 ",9)==0||strncmp(pos,"HTTP/1.0 ",9)==0){pos+=9;r->status=atoi(pos);}
    char *eol=strstr(pos,"\r\n");
    if(eol)pos=eol+2;

    while(pos<data+resp.len){
        eol=strstr(pos,"\r\n");
        if(!eol||eol==pos){if(eol)pos=eol+2;break;}
        *eol='\0';
        char *colon=strchr(pos,':');
        if(colon){
            *colon='\0';
            char *val=colon+1;
            while(*val==' ')val++;
            if(r->hc<64){r->hn[r->hc]=strdup(pos);r->hv[r->hc]=strdup(val);r->hc++;}
        }
        pos=eol+2;
    }

    char *body_start=pos;
    size_t body_avail=(data+resp.len)-body_start;
    char *te=get_header(r,"Transfer-Encoding");
    char *cl_str=get_header(r,"Content-Length");

    if(te&&strcasestr(te,"chunked")){
        buf_t dec; buf_init(&dec);
        char *cp=body_start,*end=data+resp.len;
        while(cp<end){
            char *endptr;
            long cs=strtol(cp,&endptr,16);
            cp=endptr;
            while(cp<end&&*cp!='\n')cp++;
            if(cp<end)cp++;
            if(cs==0)break;
            if(cp+cs<=end){buf_append(&dec,cp,cs);cp+=cs;}
            if(cp<end&&*cp=='\r')cp++;
            if(cp<end&&*cp=='\n')cp++;
        }
        r->body=dec.data?dec.data:strdup("");
        r->body_len=dec.len;
    } else if(cl_str){
        size_t clen=(size_t)atol(cl_str);
        if(clen>body_avail)clen=body_avail;
        r->body=malloc(clen+1);
        memcpy(r->body,body_start,clen);
        r->body[clen]='\0';
        r->body_len=clen;
    } else {
        r->body=malloc(body_avail+1);
        memcpy(r->body,body_start,body_avail);
        r->body[body_avail]='\0';
        r->body_len=body_avail;
    }

    free(resp.data); free(req.data);
    return r;
}

/* ============ Amount ============ */
static long long parse_amount(const char *s){
    int neg=0;
    if(*s=='-'){neg=1;s++;}
    long long ip=0;
    while(isdigit(*s)){ip=ip*10+(*s-'0');s++;}
    long long cents=ip*100;
    if(*s=='.'){
        s++;
        int d1=-1,d2=-1;
        if(isdigit(*s)){d1=*s-'0';s++;}
        if(isdigit(*s)){d2=*s-'0';s++;}
        if(d1>=0&&d2>=0)cents+=d1*10+d2;
        else if(d1>=0)cents+=d1*10;
    }
    return neg?-cents:cents;
}

static void format_amount(long long cents,char *out,size_t sz){
    if(cents<0){cents=-cents;snprintf(out,sz,"-%lld.%02lld",cents/100,cents%100);}
    else snprintf(out,sz,"%lld.%02lld",cents/100,cents%100);
}

/* ============ Sorting ============ */
typedef struct{char *name;char *currency;long long cents;}total_entry;
static int cmp_total(const void *a,const void *b){
    total_entry *ta=(total_entry*)a,*tb=(total_entry*)b;
    int c=strcmp(ta->name,tb->name);
    if(c)return c;
    return strcmp(ta->currency,tb->currency);
}
static int cmp_strp(const void *a,const void *b){return strcmp(*(char**)a,*(char**)b);}

/* ============ Main ============ */
int main(int argc,char *argv[]){
    if(argc<3){fprintf(stderr,"Usage: %s <data_dir> <base_url>\n",argv[0]);return 1;}
    const char *data_dir=argv[1];
    const char *base_url=argv[2];

    /* Read client.json */
    char path[4096];
    snprintf(path,sizeof(path),"%s/client.json",data_dir);
    FILE *f=fopen(path,"rb");
    if(!f){perror("fopen");return 1;}
    buf_t jf; buf_init(&jf);
    char tmp[4096]; size_t n;
    while((n=fread(tmp,1,sizeof(tmp),f))>0)buf_append(&jf,tmp,n);
    fclose(f); buf_appendc(&jf,'\0');

    const char *jp=jf.data;
    jval *client=parse_value(&jp);
    char *client_id=jget(client,"client_id")->str;
    char *client_secret=jget(client,"client_secret")->str;
    char *scope=jget(client,"scope")->str;
    int page_size=(int)jget(client,"page_size")->num;

    /* Parse base URL */
    const char *url=base_url;
    if(!strncmp(url,"http://",7))url+=7;
    char host[256]={0}; int port=80;
    const char *slash=strchr(url,'/');
    const char *colon=strchr(url,':');
    if(colon&&(!slash||colon<slash)){
        int hl=colon-url; memcpy(host,url,hl); host[hl]='\0';
        port=atoi(colon+1);
    } else {
        if(slash){int hl=slash-url;memcpy(host,url,hl);host[hl]='\0';}
        else strcpy(host,url);
    }
    char *base_path=slash?strdup(slash):strdup("");

    /* Build auth header */
    char *enc_id=url_encode_rfc6749(client_id);
    char *enc_secret=url_encode_rfc6749(client_secret);
    buf_t cred; buf_init(&cred);
    buf_appends(&cred,enc_id); buf_appendc(&cred,':'); buf_appends(&cred,enc_secret);
    char *b64=base64_encode((unsigned char*)cred.data,cred.len);

    char token_path[4096];
    snprintf(token_path,sizeof(token_path),"%s/oauth/token",base_path);
    char *enc_scope=url_encode_rfc6749(scope);
    char tok_body[4096];
    snprintf(tok_body,sizeof(tok_body),"grant_type=client_credentials&scope=%s",enc_scope);
    char tok_hdrs[8192];
    snprintf(tok_hdrs,sizeof(tok_hdrs),"Content-Type: application/x-www-form-urlencoded\r\nAuthorization: Basic %s\r\n",b64);

    http_resp *resp=http_request(host,port,"POST",token_path,tok_hdrs,tok_body,strlen(tok_body));
    if(resp->status!=200){
        printf("ERROR %d %s\n",resp->status,resp->body?resp->body:"");
        return 0;
    }
    jp=resp->body;
    jval *tok=parse_value(&jp);
    char *access_token=jget(tok,"access_token")->str;

    /* Fetch orders */
    int pages=0,retries=0,reauth=0,order_count=0;
    char *cursor=NULL;
    int token_fresh=1;

    typedef struct{char *name;char *currency;char *status;long long cents;}order_t;
    order_t *orders=NULL; int orders_cap=0,orders_len=0;

    while(1){
        char opath[8192];
        if(cursor){
            char *ec=url_encode_query(cursor);
            snprintf(opath,sizeof(opath),"%s/orders?limit=%d&cursor=%s",base_path,page_size,ec);
            free(ec);
        } else {
            snprintf(opath,sizeof(opath),"%s/orders?limit=%d",base_path,page_size);
        }
        char ahdr[8192];
        snprintf(ahdr,sizeof(ahdr),"Authorization: Bearer %s\r\n",access_token);

        resp=http_request(host,port,"GET",opath,ahdr,NULL,0);

        if(resp->status==429){
            retries++;
            char *ra=get_header(resp,"Retry-After");
            int w=ra?atoi(ra):1;
            sleep(w);
            continue;
        }
        if(resp->status==503){
            retries++;
            usleep(100000);
            continue;
        }
        if(resp->status==401){
            if(token_fresh){
                printf("ERROR %d %s\n",resp->status,resp->body?resp->body:"");
                return 0;
            }
            reauth++;
            resp=http_request(host,port,"POST",token_path,tok_hdrs,tok_body,strlen(tok_body));
            if(resp->status!=200){
                printf("ERROR %d %s\n",resp->status,resp->body?resp->body:"");
                return 0;
            }
            jp=resp->body;
            tok=parse_value(&jp);
            access_token=jget(tok,"access_token")->str;
            token_fresh=1;
            continue;
        }
        if(resp->status!=200){
            printf("ERROR %d %s\n",resp->status,resp->body?resp->body:"");
            return 0;
        }

        pages++; token_fresh=0;

        jp=resp->body;
        jval *page=parse_value(&jp);
        jval *data=jget(page,"data");
        if(data&&data->type==JV_ARRAY){
            for(int i=0;i<data->arr_len;i++){
                jval *o=data->arr[i];
                jval *cust=jget(o,"customer");
                char *name=cust?jget(cust,"name")->str:"";
                char *currency=jget(o,"currency")->str;
                char *status=jget(o,"status")->str;
                char *amt=jget(o,"amount")->str;
                long long cents=parse_amount(amt);
                if(orders_len>=orders_cap){orders_cap=orders_cap?orders_cap*2:256;orders=realloc(orders,orders_cap*sizeof(order_t));}
                orders[orders_len].name=strdup(name);
                orders[orders_len].currency=strdup(currency);
                orders[orders_len].status=strdup(status);
                orders[orders_len].cents=cents;
                orders_len++; order_count++;
            }
        }
        jval *nc=jget(page,"next_cursor");
        if(!nc||nc->type==JV_NULL)break;
        free(cursor);
        cursor=strdup(nc->str);
    }

    /* Compute totals for non-cancelled */
    total_entry *totals=malloc((orders_len+1)*sizeof(total_entry));
    int tl=0;
    for(int i=0;i<orders_len;i++){
        if(strcmp(orders[i].status,"cancelled")==0)continue;
        totals[tl].name=orders[i].name;
        totals[tl].currency=orders[i].currency;
        totals[tl].cents=orders[i].cents;
        tl++;
    }
    qsort(totals,tl,sizeof(total_entry),cmp_total);

    for(int i=0;i<tl;){
        int j=i+1;
        while(j<tl&&strcmp(totals[j].name,totals[i].name)==0&&strcmp(totals[j].currency,totals[i].currency)==0)j++;
        long long sum=0;
        for(int k=i;k<j;k++)sum+=totals[k].cents;
        char amt[64]; format_amount(sum,amt,64);
        printf("total %s %s %s\n",totals[i].currency,amt,totals[i].name);
        i=j;
    }

    /* Status counts */
    if(orders_len>0){
        char **all_st=malloc(orders_len*sizeof(char*));
        for(int i=0;i<orders_len;i++)all_st[i]=orders[i].status;
        qsort(all_st,orders_len,sizeof(char*),cmp_strp);
        for(int i=0;i<orders_len;){
            int j=i+1;
            while(j<orders_len&&strcmp(all_st[j],all_st[i])==0)j++;
            printf("status %s %d\n",all_st[i],j-i);
            i=j;
        }
        free(all_st);
    }

    printf("orders %d pages %d retries %d reauth %d\n",order_count,pages,retries,reauth);
    return 0;
}

#!/usr/bin/env python3
import sys
import json
import http.client
from urllib.parse import urlparse
import codecs


def escape(s):
    result = []
    for ch in s:
        if ch == '\\':
            result.append('\\\\')
        elif ch == '\n':
            result.append('\\n')
        elif ch == '\r':
            result.append('\\r')
        elif ch == '\t':
            result.append('\\t')
        else:
            result.append(ch)
    return ''.join(result)


def read_stream(resp):
    while True:
        try:
            chunk = resp.read1(65536)
        except Exception:
            break
        if not chunk:
            break
        yield chunk


def parse_sse_lines(byte_chunks):
    """Decode bytes to lines, handling partial UTF-8 and CRLF."""
    decoder = codecs.getincrementaldecoder('utf-8')()
    buffer = ''

    for chunk in byte_chunks:
        buffer += decoder.decode(chunk)
        while True:
            nl = buffer.find('\n')
            if nl == -1:
                break
            line = buffer[:nl]
            buffer = buffer[nl + 1:]
            if line.endswith('\r'):
                line = line[:-1]
            yield line

    buffer += decoder.decode(b'', final=True)
    if buffer:
        line = buffer
        if line.endswith('\r'):
            line = line[:-1]
        yield line


def parse_sse_events(lines):
    """Parse SSE events from an iterator of lines."""
    event_type = None
    data_lines = []

    for line in lines:
        if line == '':
            if data_lines:
                data = '\n'.join(data_lines)
                yield (event_type or 'message', data)
            event_type = None
            data_lines = []
        elif line.startswith(':'):
            pass
        elif line.startswith('event:'):
            val = line[6:]
            if val.startswith(' '):
                val = val[1:]
            event_type = val
        elif line.startswith('data:'):
            val = line[5:]
            if val.startswith(' '):
                val = val[1:]
            data_lines.append(val)

    if data_lines:
        data = '\n'.join(data_lines)
        yield (event_type or 'message', data)


def process_stream(resp):
    """Process a streaming response. Returns (blocks, stop_reason, usage)."""
    lines = parse_sse_lines(read_stream(resp))
    events = parse_sse_events(lines)

    blocks = {}
    stop_reason = None
    usage = {'input_tokens': 0, 'output_tokens': 0, 'cache_read_input_tokens': 0}

    for event_type, data_str in events:
        if event_type == 'ping':
            continue

        try:
            data = json.loads(data_str)
        except (json.JSONDecodeError, ValueError):
            continue

        evt_type = data.get('type', event_type)

        if evt_type == 'message_start':
            msg = data.get('message', {})
            u = msg.get('usage', {})
            usage['input_tokens'] += u.get('input_tokens', 0)
            usage['cache_read_input_tokens'] += u.get('cache_read_input_tokens', 0)

        elif evt_type == 'content_block_start':
            idx = data['index']
            cb = data['content_block']
            blocks[idx] = {
                'type': cb['type'],
                'thinking': cb.get('thinking', ''),
                'signature': cb.get('signature', ''),
                'text': cb.get('text', ''),
                'id': cb.get('id', ''),
                'name': cb.get('name', ''),
                'input_json': '',
            }

        elif evt_type == 'content_block_delta':
            idx = data['index']
            delta = data['delta']
            dtype = delta['type']
            if dtype == 'thinking_delta':
                blocks[idx]['thinking'] += delta['thinking']
            elif dtype == 'signature_delta':
                blocks[idx]['signature'] += delta['signature']
            elif dtype == 'text_delta':
                blocks[idx]['text'] += delta['text']
            elif dtype == 'input_json_delta':
                blocks[idx]['input_json'] += delta['partial_json']

        elif evt_type == 'message_delta':
            d = data.get('delta', {})
            if 'stop_reason' in d:
                stop_reason = d['stop_reason']
            u = data.get('usage', {})
            usage['output_tokens'] += u.get('output_tokens', 0)

        elif evt_type == 'message_stop':
            pass

    sorted_blocks = [blocks[i] for i in sorted(blocks.keys())]
    return sorted_blocks, stop_reason, usage


def print_blocks(blocks):
    for b in blocks:
        if b['type'] == 'thinking':
            print(f'thinking {escape(b["thinking"])}')
            print(f'signature {escape(b["signature"])}')
        elif b['type'] == 'text':
            print(f'text {escape(b["text"])}')
        elif b['type'] == 'tool_use':
            print(f'tool_use {b["id"]} {b["name"]} {escape(b["input_json"])}')


def execute_tool(name, input_obj):
    if name == 'measure':
        text = input_obj.get('text', '')
        unit = input_obj.get('unit', '')
        if unit == 'code_points':
            return str(len(text)), False
        elif unit == 'utf8_bytes':
            return str(len(text.encode('utf-8'))), False
        elif unit == 'utf16_units':
            count = 0
            for ch in text:
                if ord(ch) > 0xFFFF:
                    count += 2
                else:
                    count += 1
            return str(count), False
        else:
            return f'unsupported unit: {unit}', True
    elif name == 'reverse':
        text = input_obj.get('text', '')
        return text[::-1], False
    else:
        return f'unknown tool: {name}', True


def make_request(base_url, api_key, body):
    parsed = urlparse(base_url)
    host = parsed.hostname
    port = parsed.port or 80
    path = parsed.path + '/v1/messages'

    conn = http.client.HTTPConnection(host, port)
    body_bytes = json.dumps(body).encode('utf-8')
    headers = {
        'Content-Length': str(len(body_bytes)),
        'x-api-key': api_key,
        'anthropic-version': '2023-06-01',
        'content-type': 'application/json',
    }
    conn.request('POST', path, body_bytes, headers)
    return conn


def main():
    data_dir = sys.argv[1]
    base_url = sys.argv[2]

    with open(f'{data_dir}/request.json', 'r') as f:
        req_data = json.load(f)

    api_key = req_data['api_key']
    model = req_data['model']
    max_tokens = req_data['max_tokens']
    thinking_budget = req_data['thinking_budget']
    system = req_data['system']
    prompt = req_data['prompt']
    tools = req_data['tools']

    # Request 1
    body1 = {
        'model': model,
        'max_tokens': max_tokens,
        'stream': True,
        'thinking': {'type': 'enabled', 'budget_tokens': thinking_budget},
        'system': system,
        'tools': tools,
        'messages': [{'role': 'user', 'content': prompt}],
    }

    conn = make_request(base_url, api_key, body1)
    resp = conn.getresponse()

    if resp.status != 200:
        error_body = resp.read()
        try:
            err = json.loads(error_body)
            err_type = err['error']['type']
            err_msg = err['error']['message']
        except Exception:
            err_type = 'unknown'
            err_msg = error_body.decode('utf-8', errors='replace')
        print(f'ERROR {resp.status} {err_type}: {err_msg}')
        sys.exit(0)

    print('request 1')
    blocks1, stop_reason1, usage1 = process_stream(resp)
    print_blocks(blocks1)
    print(f'stop_reason {stop_reason1}')

    # Execute tools
    results = []
    for b in blocks1:
        if b['type'] == 'tool_use':
            try:
                input_obj = json.loads(b['input_json'])
            except Exception:
                input_obj = {}
            result, is_error = execute_tool(b['name'], input_obj)
            results.append((b['id'], result, is_error))

    for tool_id, result, is_error in results:
        if is_error:
            print(f'error {tool_id} {escape(result)}')
        else:
            print(f'result {tool_id} {escape(result)}')

    # Build request 2
    assistant_content = []
    for b in blocks1:
        if b['type'] == 'thinking':
            assistant_content.append({
                'type': 'thinking',
                'thinking': b['thinking'],
                'signature': b['signature'],
            })
        elif b['type'] == 'text':
            assistant_content.append({
                'type': 'text',
                'text': b['text'],
            })
        elif b['type'] == 'tool_use':
            input_obj = json.loads(b['input_json'])
            assistant_content.append({
                'type': 'tool_use',
                'id': b['id'],
                'name': b['name'],
                'input': input_obj,
            })

    tool_result_content = []
    for tool_id, result, is_error in results:
        block = {'type': 'tool_result', 'tool_use_id': tool_id, 'content': result}
        if is_error:
            block['is_error'] = True
        tool_result_content.append(block)

    body2 = {
        'model': model,
        'max_tokens': max_tokens,
        'stream': True,
        'thinking': {'type': 'enabled', 'budget_tokens': thinking_budget},
        'system': system,
        'tools': tools,
        'messages': [
            {'role': 'user', 'content': prompt},
            {'role': 'assistant', 'content': assistant_content},
            {'role': 'user', 'content': tool_result_content},
        ],
    }

    conn2 = make_request(base_url, api_key, body2)
    resp2 = conn2.getresponse()

    if resp2.status != 200:
        error_body = resp2.read()
        try:
            err = json.loads(error_body)
            err_type = err['error']['type']
            err_msg = err['error']['message']
        except Exception:
            err_type = 'unknown'
            err_msg = error_body.decode('utf-8', errors='replace')
        print(f'ERROR {resp2.status} {err_type}: {err_msg}')
        sys.exit(0)

    print('request 2')
    blocks2, stop_reason2, usage2 = process_stream(resp2)
    print_blocks(blocks2)
    print(f'stop_reason {stop_reason2}')

    # Usage totals
    total_input = usage1['input_tokens'] + usage2['input_tokens']
    total_output = usage1['output_tokens'] + usage2['output_tokens']
    total_cache_read = usage1['cache_read_input_tokens'] + usage2['cache_read_input_tokens']

    print(f'usage input={total_input} output={total_output} cache_read={total_cache_read}')


if __name__ == '__main__':
    main()

import sys
import struct
import zlib
import re
from decimal import Decimal


def main():
    filepath = sys.argv[1] + '/db.sqlite'
    with open(filepath, 'rb') as f:
        data = f.read()

    assert data[:16] == b'SQLite format 3\x00'
    page_size = struct.unpack('>H', data[16:18])[0]
    if page_size == 1:
        page_size = 65536
    reserved_bytes = data[20]
    usable_size = page_size - reserved_bytes

    def get_page(pn):
        o = (pn - 1) * page_size
        return data[o:o + page_size]

    def read_varint(buf, pos):
        r = 0
        for i in range(9):
            b = buf[pos + i]
            if i < 8:
                r = (r << 7) | (b & 0x7F)
                if b < 0x80:
                    return r, pos + i + 1
            else:
                r = (r << 8) | b
                return r, pos + i + 1

    def parse_btree(pn):
        pg = get_page(pn)
        h = 100 if pn == 1 else 0
        pt = pg[h]
        nc = struct.unpack('>H', pg[h + 3:h + 5])[0]
        if pt in (2, 5):
            rm = struct.unpack('>I', pg[h + 8:h + 12])[0]
            co = h + 12
        else:
            rm = 0
            co = h + 8
        cp = [struct.unpack('>H', pg[co + i * 2:co + i * 2 + 2])[0] for i in range(nc)]
        return pt, cp, rm, pg

    def read_payload(pg, off, tsz):
        X = usable_size - 35
        M = ((usable_size - 12) * 32) // 255 - 23
        if tsz <= X:
            return pg[off:off + tsz]
        K = M + (tsz - M) % (usable_size - 4)
        if K > X:
            K = M
        buf = bytearray(pg[off:off + K])
        ovf = struct.unpack('>I', pg[off + K:off + K + 4])[0]
        rem = tsz - K
        while rem > 0 and ovf != 0:
            op = get_page(ovf)
            nx = struct.unpack('>I', op[0:4])[0]
            av = usable_size - 4
            tk = min(rem, av)
            buf.extend(op[4:4 + tk])
            rem -= tk
            ovf = nx
        return bytes(buf)

    def parse_record(buf):
        if not buf:
            return []
        hs, p = read_varint(buf, 0)
        sts = []
        while p < hs:
            st, p = read_varint(buf, p)
            sts.append(st)
        vals = []
        d = hs
        for st in sts:
            if st == 0:
                vals.append(('NULL', None))
            elif st == 1:
                vals.append(('INT', struct.unpack('>b', buf[d:d + 1])[0])); d += 1
            elif st == 2:
                vals.append(('INT', struct.unpack('>h', buf[d:d + 2])[0])); d += 2
            elif st == 3:
                vals.append(('INT', int.from_bytes(buf[d:d + 3], 'big', signed=True))); d += 3
            elif st == 4:
                vals.append(('INT', struct.unpack('>i', buf[d:d + 4])[0])); d += 4
            elif st == 5:
                vals.append(('INT', int.from_bytes(buf[d:d + 6], 'big', signed=True))); d += 6
            elif st == 6:
                vals.append(('INT', struct.unpack('>q', buf[d:d + 8])[0])); d += 8
            elif st == 7:
                vals.append(('REAL', struct.unpack('>d', buf[d:d + 8])[0])); d += 8
            elif st == 8:
                vals.append(('INT', 0))
            elif st == 9:
                vals.append(('INT', 1))
            elif st >= 12 and st % 2 == 0:
                n = (st - 12) // 2
                vals.append(('BLOB', buf[d:d + n])); d += n
            elif st >= 13:
                n = (st - 13) // 2
                vals.append(('TEXT', buf[d:d + n])); d += n
        return vals

    def walk_table(pn):
        rows = []
        pt, cp, rm, pg = parse_btree(pn)
        if pt == 5:
            for c in cp:
                rows.extend(walk_table(struct.unpack('>I', pg[c:c + 4])[0]))
            if rm:
                rows.extend(walk_table(rm))
        elif pt == 13:
            for c in cp:
                o = c
                ps, o = read_varint(pg, o)
                rid, o = read_varint(pg, o)
                if rid >= (1 << 63):
                    rid -= (1 << 64)
                rec = read_payload(pg, o, ps)
                rows.append((rid, rec))
        return rows

    def parse_create(sql):
        i = 0
        ps = None
        while i < len(sql):
            if sql[i] == '"':
                i += 1
                while i < len(sql) and sql[i] != '"':
                    i += 1
                i += 1
            elif sql[i] == '(':
                ps = i
                break
            else:
                i += 1
        if ps is None:
            return []
        depth = 0
        pe = None
        for i in range(ps, len(sql)):
            if sql[i] == '(':
                depth += 1
            elif sql[i] == ')':
                depth -= 1
                if depth == 0:
                    pe = i
                    break
        if pe is None:
            return []
        ds = sql[ps + 1:pe]
        defs = []
        depth = 0
        cur = []
        for ch in ds:
            if ch == '(':
                depth += 1
                cur.append(ch)
            elif ch == ')':
                depth -= 1
                cur.append(ch)
            elif ch == ',' and depth == 0:
                defs.append(''.join(cur))
                cur = []
            else:
                cur.append(ch)
        if cur:
            defs.append(''.join(cur))
        cols = []
        for d in defs:
            d = d.strip()
            if not d:
                continue
            if d.startswith('"'):
                eq = d.index('"', 1)
                nm = d[1:eq]
                rest = d[eq + 1:].strip()
            else:
                parts = d.split(None, 1)
                nm = parts[0]
                rest = parts[1] if len(parts) > 1 else ''
            ra = False
            rt = rest.split()
            if rt and rt[0].upper() == 'INTEGER':
                if re.search(r'\bPRIMARY\s+KEY\b', d.upper()):
                    ra = True
            cols.append((nm, ra))
        return cols

    def fmt_real(v):
        d = Decimal(v)
        s, dg, ex = d.as_tuple()
        pre = '-' if s else ''
        if ex >= 0:
            si = ''.join(map(str, dg)) + '0' * ex
            if not si:
                si = '0'
            return pre + si + '.0'
        ad = ''.join(map(str, dg))
        il = len(ad) + ex
        if il > 0:
            ip = ad[:il]
            fp = ad[il:]
        else:
            ip = '0'
            fp = '0' * (-il) + ad
        fp = fp.rstrip('0') or '0'
        return pre + ip + '.' + fp

    def fmt_text(b):
        t = b.decode('utf-8')
        r = ['"']
        for c in t:
            cp = ord(c)
            if cp == 0x5C:
                r.append('\\\\')
            elif cp == 0x22:
                r.append('\\"')
            elif cp == 0x0A:
                r.append('\\n')
            elif cp == 0x0D:
                r.append('\\r')
            elif cp == 0x09:
                r.append('\\t')
            elif cp < 0x20 or cp == 0x7F:
                r.append(f'\\x{cp:02X}')
            else:
                r.append(c)
        r.append('"')
        return ''.join(r)

    def fmt_val(v):
        t, d = v
        if t == 'NULL':
            return 'NULL'
        if t == 'INT':
            return str(d)
        if t == 'REAL':
            return fmt_real(d)
        if t == 'TEXT':
            if len(d) <= 100:
                return fmt_text(d)
            return f"<TEXT len={len(d)} crc32={zlib.crc32(d) & 0xFFFFFFFF:08x}>"
        if t == 'BLOB':
            if len(d) <= 100:
                return f"X'{d.hex().upper()}'"
            return f"<BLOB len={len(d)} crc32={zlib.crc32(d) & 0xFFFFFFFF:08x}>"

    # Read schema from page 1
    schema = walk_table(1)
    tables = []
    for rid, rec in schema:
        vals = parse_record(rec)
        if len(vals) < 5:
            continue
        typ, nm, rp, sq = vals[0][1], vals[1][1], vals[3][1], vals[4][1]
        if isinstance(typ, bytes):
            typ = typ.decode('utf-8')
        if isinstance(nm, bytes):
            nm = nm.decode('utf-8')
        if isinstance(sq, bytes):
            sq = sq.decode('utf-8')
        if typ == 'table' and not nm.startswith('sqlite_') and rp:
            tables.append((nm, rp, sq))

    tables.sort(key=lambda t: t[0].encode('utf-8'))

    parts = []
    for tn, rp, sq in tables:
        cols = parse_create(sq)
        rows = walk_table(rp)
        rows.sort(key=lambda r: r[0])
        lines = [f"TABLE {tn} rows={len(rows)}"]
        lines.append("COLUMNS " + ", ".join(c[0] for c in cols))
        for rid, rec in rows:
            vals = parse_record(rec)
            fv = []
            for i, (cn, ra) in enumerate(cols):
                if ra:
                    fv.append(('INT', rid))
                elif i < len(vals):
                    fv.append(vals[i])
                else:
                    fv.append(('NULL', None))
            lines.append(f"{rid}: {', '.join(fmt_val(v) for v in fv)}")
        parts.append('\n'.join(lines))

    print('\n\n'.join(parts))


main()

import java.io.*;
import java.nio.file.*;
import java.util.*;
import java.util.zip.CRC32;
import java.math.BigDecimal;
import java.nio.charset.StandardCharsets;

public class Main {
    static byte[] fileData;
    static int pageSize, reservedBytes, usableSize;

    static class Val {
        int type; // 0=null 1=int 2=real 3=text 4=blob
        long intVal;
        double realVal;
        byte[] bytesVal;
    }

    static class Rec {
        long rowid;
        Val[] vals;
    }

    static class SchemaEntry {
        String name, sql;
        int rootpage;
    }

    static class ColInfo {
        String name, type;
        boolean ipk;
    }

    public static void main(String[] args) throws Exception {
        fileData = Files.readAllBytes(Paths.get(args[0], "db.sqlite"));
        pageSize = ((fileData[16] & 0xFF) << 8) | (fileData[17] & 0xFF);
        if (pageSize == 1) pageSize = 65536;
        reservedBytes = fileData[20] & 0xFF;
        usableSize = pageSize - reservedBytes;

        List<Rec> schemaRecs = readBTree(1);
        List<SchemaEntry> tables = new ArrayList<>();

        for (Rec r : schemaRecs) {
            if (r.vals.length < 5) continue;
            if (r.vals[0].type != 3) continue;
            String type = new String(r.vals[0].bytesVal, StandardCharsets.UTF_8);
            if (!"table".equals(type)) continue;
            if (r.vals[1].type != 3) continue;
            String name = new String(r.vals[1].bytesVal, StandardCharsets.UTF_8);
            if (name.startsWith("sqlite_")) continue;
            if (r.vals[3].type != 1) continue;
            SchemaEntry se = new SchemaEntry();
            se.name = name;
            se.rootpage = (int) r.vals[3].intVal;
            se.sql = r.vals[4].type == 3 ? new String(r.vals[4].bytesVal, StandardCharsets.UTF_8) : "";
            tables.add(se);
        }

        tables.sort((a, b) -> {
            byte[] an = a.name.getBytes(StandardCharsets.UTF_8);
            byte[] bn = b.name.getBytes(StandardCharsets.UTF_8);
            for (int i = 0; i < Math.min(an.length, bn.length); i++) {
                int c = (an[i] & 0xFF) - (bn[i] & 0xFF);
                if (c != 0) return c;
            }
            return an.length - bn.length;
        });

        boolean first = true;
        for (SchemaEntry t : tables) {
            if (!first) System.out.println();
            first = false;
            dumpTable(t);
        }
    }

    static void dumpTable(SchemaEntry t) {
        List<ColInfo> cols = parseCols(t.sql);
        List<Rec> recs = readBTree(t.rootpage);
        recs.sort(Comparator.comparingLong(r -> r.rowid));

        System.out.println("TABLE " + t.name + " rows=" + recs.size());
        StringBuilder sb = new StringBuilder("COLUMNS ");
        for (int i = 0; i < cols.size(); i++) {
            if (i > 0) sb.append(", ");
            sb.append(cols.get(i).name);
        }
        System.out.println(sb);

        for (Rec r : recs) {
            StringBuilder line = new StringBuilder();
            line.append(r.rowid).append(": ");
            for (int i = 0; i < cols.size(); i++) {
                if (i > 0) line.append(", ");
                Val v;
                if (cols.get(i).ipk) {
                    v = new Val();
                    v.type = 1;
                    v.intVal = r.rowid;
                } else if (i < r.vals.length) {
                    v = r.vals[i];
                } else {
                    v = new Val();
                    v.type = 0;
                }
                line.append(fmtVal(v));
            }
            System.out.println(line);
        }
    }

    // ---- B-tree ----

    static byte[] readPage(int pg) {
        int off = (pg - 1) * pageSize;
        return Arrays.copyOfRange(fileData, off, off + pageSize);
    }

    static List<Rec> readBTree(int root) {
        List<Rec> list = new ArrayList<>();
        walkBTree(root, list);
        return list;
    }

    static void walkBTree(int pg, List<Rec> list) {
        byte[] d = readPage(pg);
        int ho = (pg == 1) ? 100 : 0;
        int ptype = d[ho] & 0xFF;
        int nc = ((d[ho + 3] & 0xFF) << 8) | (d[ho + 4] & 0xFF);
        int cps = ho + (ptype == 5 ? 12 : 8);
        if (ptype == 13) {
            for (int i = 0; i < nc; i++) {
                int co = ((d[cps + i * 2] & 0xFF) << 8) | (d[cps + i * 2 + 1] & 0xFF);
                list.add(readLeafCell(d, co));
            }
        } else if (ptype == 5) {
            for (int i = 0; i < nc; i++) {
                int co = ((d[cps + i * 2] & 0xFF) << 8) | (d[cps + i * 2 + 1] & 0xFF);
                walkBTree(readInt32(d, co), list);
            }
            walkBTree(readInt32(d, ho + 8), list);
        }
    }

    static Rec readLeafCell(byte[] d, int co) {
        int[] pos = {co};
        long payloadLen = readVarint(d, pos);
        long rowid = readVarint(d, pos);

        int X = usableSize - 35;
        int M = ((usableSize - 12) * 32 / 255) - 23;
        int local;
        if (payloadLen <= X) {
            local = (int) payloadLen;
        } else {
            int K = M + (int) ((payloadLen - M) % (usableSize - 4));
            local = (K <= X) ? K : M;
        }

        byte[] payload = new byte[(int) payloadLen];
        System.arraycopy(d, pos[0], payload, 0, local);

        if (payloadLen > local) {
            int ovf = readInt32(d, pos[0] + local);
            int rem = (int) (payloadLen - local);
            int off = local;
            while (ovf != 0 && rem > 0) {
                byte[] od = readPage(ovf);
                int next = readInt32(od, 0);
                int chunk = Math.min(rem, usableSize - 4);
                System.arraycopy(od, 4, payload, off, chunk);
                off += chunk;
                rem -= chunk;
                ovf = next;
            }
        }

        Rec r = new Rec();
        r.rowid = rowid;
        r.vals = parseRecord(payload);
        return r;
    }

    // ---- Record parsing ----

    static Val[] parseRecord(byte[] payload) {
        if (payload.length == 0) return new Val[0];
        int[] pos = {0};
        long hdrSize = readVarint(payload, pos);
        List<Long> sts = new ArrayList<>();
        while (pos[0] < hdrSize) {
            sts.add(readVarint(payload, pos));
        }
        int dp = (int) hdrSize;
        Val[] vals = new Val[sts.size()];
        for (int i = 0; i < sts.size(); i++) {
            long st = sts.get(i);
            vals[i] = readVal(payload, dp, st);
            dp += stSize(st);
        }
        return vals;
    }

    static Val readVal(byte[] d, int off, long st) {
        Val v = new Val();
        if (st == 0) { v.type = 0; }
        else if (st == 1) { v.type = 1; v.intVal = (byte) d[off]; }
        else if (st == 2) { v.type = 1; v.intVal = (short) readInt16(d, off); }
        else if (st == 3) { v.type = 1; v.intVal = readInt24(d, off); }
        else if (st == 4) { v.type = 1; v.intVal = readInt32(d, off); }
        else if (st == 5) { v.type = 1; v.intVal = readInt48(d, off); }
        else if (st == 6) { v.type = 1; v.intVal = readInt64(d, off); }
        else if (st == 7) { v.type = 2; v.realVal = Double.longBitsToDouble(readInt64(d, off)); }
        else if (st == 8) { v.type = 1; v.intVal = 0; }
        else if (st == 9) { v.type = 1; v.intVal = 1; }
        else if (st >= 12 && st % 2 == 0) {
            v.type = 4;
            int len = (int) ((st - 12) / 2);
            v.bytesVal = Arrays.copyOfRange(d, off, off + len);
        } else if (st >= 13) {
            v.type = 3;
            int len = (int) ((st - 13) / 2);
            v.bytesVal = Arrays.copyOfRange(d, off, off + len);
        }
        return v;
    }

    static int stSize(long st) {
        if (st <= 4) return (int) st;
        if (st == 5) return 6;
        if (st == 6 || st == 7) return 8;
        if (st <= 11) return 0;
        return (int) ((st - 12) / 2);
    }

    // ---- Varint ----

    static long readVarint(byte[] d, int[] pos) {
        long val = 0;
        for (int i = 0; i < 9; i++) {
            int b = d[pos[0] + i] & 0xFF;
            if (i < 8) {
                val = (val << 7) | (b & 0x7F);
                if ((b & 0x80) == 0) { pos[0] += i + 1; return val; }
            } else {
                val = (val << 8) | b;
                pos[0] += 9;
                return val;
            }
        }
        pos[0] += 9;
        return val;
    }

    // ---- Integer readers ----

    static int readInt16(byte[] d, int o) {
        return (short) (((d[o] & 0xFF) << 8) | (d[o + 1] & 0xFF));
    }

    static int readInt24(byte[] d, int o) {
        int v = ((d[o] & 0xFF) << 16) | ((d[o + 1] & 0xFF) << 8) | (d[o + 2] & 0xFF);
        if ((v & 0x800000) != 0) v |= 0xFF000000;
        return v;
    }

    static int readInt32(byte[] d, int o) {
        return ((d[o] & 0xFF) << 24) | ((d[o + 1] & 0xFF) << 16) |
               ((d[o + 2] & 0xFF) << 8) | (d[o + 3] & 0xFF);
    }

    static long readInt48(byte[] d, int o) {
        long v = ((long)(d[o] & 0xFF) << 40) | ((long)(d[o+1] & 0xFF) << 32) |
                 ((long)(d[o+2] & 0xFF) << 24) | ((long)(d[o+3] & 0xFF) << 16) |
                 ((long)(d[o+4] & 0xFF) << 8) | (d[o+5] & 0xFF);
        if ((v & 0x800000000000L) != 0) v |= 0xFFFF000000000000L;
        return v;
    }

    static long readInt64(byte[] d, int o) {
        return ((long)(d[o] & 0xFF) << 56) | ((long)(d[o+1] & 0xFF) << 48) |
               ((long)(d[o+2] & 0xFF) << 40) | ((long)(d[o+3] & 0xFF) << 32) |
               ((long)(d[o+4] & 0xFF) << 24) | ((long)(d[o+5] & 0xFF) << 16) |
               ((long)(d[o+6] & 0xFF) << 8) | (d[o+7] & 0xFF);
    }

    // ---- CREATE TABLE parsing ----

    static final Set<String> CONSTRAINT_KW = new HashSet<>(Arrays.asList(
        "PRIMARY", "NOT", "NULL", "UNIQUE", "CHECK", "DEFAULT",
        "COLLATE", "REFERENCES", "GENERATED", "AS", "HIDDEN"
    ));

    static List<ColInfo> parseCols(String sql) {
        List<ColInfo> cols = new ArrayList<>();
        boolean inQ = false;
        int open = -1;
        for (int i = 0; i < sql.length(); i++) {
            char c = sql.charAt(i);
            if (c == '"') inQ = !inQ;
            else if (c == '(' && !inQ) { open = i; break; }
        }
        if (open < 0) return cols;

        int depth = 0, close = -1;
        inQ = false;
        for (int i = open; i < sql.length(); i++) {
            char c = sql.charAt(i);
            if (c == '"') inQ = !inQ;
            else if (!inQ) {
                if (c == '(') depth++;
                else if (c == ')') { depth--; if (depth == 0) { close = i; break; } }
            }
        }
        if (close < 0) return cols;

        String defs = sql.substring(open + 1, close);
        List<String> defList = splitCommas(defs);

        for (String def : defList) {
            def = def.trim();
            if (def.isEmpty()) continue;
            ColInfo ci = new ColInfo();
            int j = 0;
            while (j < def.length() && Character.isWhitespace(def.charAt(j))) j++;
            if (j < def.length() && def.charAt(j) == '"') {
                int end = def.indexOf('"', j + 1);
                ci.name = def.substring(j + 1, end);
                j = end + 1;
            } else {
                int s = j;
                while (j < def.length() && (Character.isLetterOrDigit(def.charAt(j)) || def.charAt(j) == '_')) j++;
                ci.name = def.substring(s, j);
            }
            String rest = def.substring(j).trim();
            ci.type = extractType(rest);
            ci.ipk = ci.type.equalsIgnoreCase("INTEGER") && hasPK(rest);
            cols.add(ci);
        }
        return cols;
    }

    static List<String> splitCommas(String s) {
        List<String> res = new ArrayList<>();
        int depth = 0;
        boolean inQ = false;
        int start = 0;
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c == '"') inQ = !inQ;
            else if (!inQ) {
                if (c == '(') depth++;
                else if (c == ')') depth--;
                else if (c == ',' && depth == 0) {
                    res.add(s.substring(start, i));
                    start = i + 1;
                }
            }
        }
        res.add(s.substring(start));
        return res;
    }

    static String extractType(String rest) {
        StringBuilder sb = new StringBuilder();
        int i = 0;
        while (i < rest.length()) {
            while (i < rest.length() && Character.isWhitespace(rest.charAt(i))) i++;
            if (i >= rest.length()) break;
            if (rest.charAt(i) == '(') {
                int d = 0, s = i;
                while (i < rest.length()) {
                    if (rest.charAt(i) == '(') d++;
                    else if (rest.charAt(i) == ')') { d--; if (d == 0) { i++; break; } }
                    i++;
                }
                if (sb.length() > 0) sb.append(' ');
                sb.append(rest, s, i);
            } else if (Character.isLetter(rest.charAt(i)) || rest.charAt(i) == '_') {
                int s = i;
                while (i < rest.length() && (Character.isLetterOrDigit(rest.charAt(i)) || rest.charAt(i) == '_')) i++;
                String w = rest.substring(s, i);
                if (CONSTRAINT_KW.contains(w.toUpperCase())) break;
                if (sb.length() > 0) sb.append(' ');
                sb.append(w);
            } else {
                break;
            }
        }
        return sb.toString();
    }

    static boolean hasPK(String rest) {
        String[] toks = rest.split("\\s+");
        for (int i = 0; i < toks.length - 1; i++) {
            if (toks[i].equalsIgnoreCase("PRIMARY") && toks[i + 1].equalsIgnoreCase("KEY"))
                return true;
        }
        return false;
    }

    // ---- Value formatting ----

    static String fmtVal(Val v) {
        switch (v.type) {
            case 0: return "NULL";
            case 1: return Long.toString(v.intVal);
            case 2: return fmtReal(v.realVal);
            case 3: return fmtText(v.bytesVal);
            case 4: return fmtBlob(v.bytesVal);
            default: return "NULL";
        }
    }

    static String fmtReal(double d) {
        BigDecimal bd = new BigDecimal(d).stripTrailingZeros();
        String s = bd.toPlainString();
        if (!s.contains(".")) s += ".0";
        return s;
    }

    static String fmtText(byte[] b) {
        if (b.length > 100) {
            CRC32 crc = new CRC32();
            crc.update(b);
            return String.format("<TEXT len=%d crc32=%08x>", b.length, crc.getValue());
        }
        StringBuilder sb = new StringBuilder("\"");
        int i = 0;
        while (i < b.length) {
            int v = b[i] & 0xFF;
            if (v == '\\') { sb.append("\\\\"); i++; }
            else if (v == '"') { sb.append("\\\""); i++; }
            else if (v == '\n') { sb.append("\\n"); i++; }
            else if (v == '\r') { sb.append("\\r"); i++; }
            else if (v == '\t') { sb.append("\\t"); i++; }
            else if (v < 0x20 || v == 0x7F) { sb.append(String.format("\\x%02X", v)); i++; }
            else if (v < 0x80) { sb.append((char) v); i++; }
            else {
                int sl;
                if ((v & 0xE0) == 0xC0) sl = 2;
                else if ((v & 0xF0) == 0xE0) sl = 3;
                else if ((v & 0xF8) == 0xF0) sl = 4;
                else sl = 1;
                sb.append(new String(b, i, sl, StandardCharsets.UTF_8));
                i += sl;
            }
        }
        sb.append('"');
        return sb.toString();
    }

    static String fmtBlob(byte[] b) {
        if (b.length > 100) {
            CRC32 crc = new CRC32();
            crc.update(b);
            return String.format("<BLOB len=%d crc32=%08x>", b.length, crc.getValue());
        }
        StringBuilder sb = new StringBuilder("X'");
        for (byte x : b) sb.append(String.format("%02X", x & 0xFF));
        sb.append('\'');
        return sb.toString();
    }
}

import * as http from 'http';
import * as fs from 'fs';
import * as path from 'path';

interface ContentBlock {
  type: 'thinking' | 'text' | 'tool_use';
  thinking?: string;
  signature?: string;
  text?: string;
  id?: string;
  name?: string;
  partialJson?: string;
}

interface StreamResult {
  status: number;
  errorType?: string;
  errorMessage?: string;
  blocks?: ContentBlock[];
  stopReason?: string;
  inputTokens?: number;
  outputTokens?: number;
  cacheReadTokens?: number;
}

function escapeString(s: string): string {
  let result = '';
  for (let i = 0; i < s.length; i++) {
    const ch = s[i];
    if (ch === '\\') result += '\\\\';
    else if (ch === '\n') result += '\\n';
    else if (ch === '\r') result += '\\r';
    else if (ch === '\t') result += '\\t';
    else result += ch;
  }
  return result;
}

function executeTool(name: string, input: Record<string, string>): { result: string; isError: boolean } {
  if (name === 'measure') {
    const text = input['text'] ?? '';
    const unit = input['unit'] ?? '';
    if (unit === 'code_points') {
      return { result: String(Array.from(text).length), isError: false };
    } else if (unit === 'utf8_bytes') {
      return { result: String(Buffer.byteLength(text, 'utf8')), isError: false };
    } else if (unit === 'utf16_units') {
      return { result: String(text.length), isError: false };
    } else {
      return { result: `unsupported unit: ${unit}`, isError: true };
    }
  } else if (name === 'reverse') {
    const text = input['text'] ?? '';
    return { result: Array.from(text).reverse().join(''), isError: false };
  } else {
    return { result: `unknown tool: ${name}`, isError: true };
  }
}

async function streamRequest(baseUrl: string, apiKey: string, body: object): Promise<StreamResult> {
  return new Promise((resolve, reject) => {
    const url = new URL(baseUrl + '/v1/messages');
    const bodyStr = JSON.stringify(body);

    const options: http.RequestOptions = {
      hostname: url.hostname,
      port: url.port ? parseInt(url.port) : 80,
      path: url.pathname,
      method: 'POST',
      headers: {
        'Host': url.host,
        'Content-Length': String(Buffer.byteLength(bodyStr, 'utf8')),
        'x-api-key': apiKey,
        'anthropic-version': '2023-06-01',
        'content-type': 'application/json'
      }
    };

    const req = http.request(options, (res) => {
      const statusCode = res.statusCode || 0;

      if (statusCode !== 200) {
        let bodyData = '';
        res.setEncoding('utf-8');
        res.on('data', (chunk: string) => { bodyData += chunk; });
        res.on('end', () => {
          try {
            const err = JSON.parse(bodyData);
            resolve({
              status: statusCode,
              errorType: err.error?.type ?? 'unknown',
              errorMessage: err.error?.message ?? ''
            });
          } catch {
            resolve({ status: statusCode, errorType: 'unknown', errorMessage: bodyData });
          }
        });
        res.on('error', reject);
        return;
      }

      // Parse SSE stream
      const decoder = new TextDecoder('utf-8');
      let buffer = '';
      let eventType = '';
      let dataLines: string[] = [];

      const blocks = new Map<number, ContentBlock>();
      let stopReason = '';
      let inputTokens = 0;
      let outputTokens = 0;
      let cacheReadTokens = 0;

      function processLine(line: string) {
        if (line === '') {
          if (dataLines.length > 0) {
            const data = dataLines.join('\n');
            handleEvent(eventType, data);
          }
          eventType = '';
          dataLines = [];
        } else if (line.startsWith(':')) {
          // comment, ignore
        } else if (line.startsWith('event:')) {
          let val = line.substring(6);
          if (val.startsWith(' ')) val = val.substring(1);
          eventType = val;
        } else if (line.startsWith('data:')) {
          let val = line.substring(5);
          if (val.startsWith(' ')) val = val.substring(1);
          dataLines.push(val);
        }
      }

      function handleEvent(event: string, data: string) {
        if (event === 'ping') return;

        let parsed: any;
        try {
          parsed = JSON.parse(data);
        } catch {
          return;
        }

        if (event === 'message_start') {
          const usage = parsed.message?.usage;
          if (usage) {
            inputTokens += usage.input_tokens || 0;
            cacheReadTokens += usage.cache_read_input_tokens || 0;
          }
        } else if (event === 'content_block_start') {
          const idx: number = parsed.index;
          const cb = parsed.content_block;
          if (cb.type === 'thinking') {
            blocks.set(idx, { type: 'thinking', thinking: '', signature: '' });
          } else if (cb.type === 'text') {
            blocks.set(idx, { type: 'text', text: '' });
          } else if (cb.type === 'tool_use') {
            blocks.set(idx, { type: 'tool_use', id: cb.id, name: cb.name, partialJson: '' });
          }
        } else if (event === 'content_block_delta') {
          const idx: number = parsed.index;
          const delta = parsed.delta;
          const block = blocks.get(idx);
          if (!block) return;

          if (delta.type === 'thinking_delta') {
            block.thinking = (block.thinking || '') + (delta.thinking || '');
          } else if (delta.type === 'signature_delta') {
            block.signature = (block.signature || '') + (delta.signature || '');
          } else if (delta.type === 'text_delta') {
            block.text = (block.text || '') + (delta.text || '');
          } else if (delta.type === 'input_json_delta') {
            block.partialJson = (block.partialJson || '') + (delta.partial_json || '');
          }
        } else if (event === 'message_delta') {
          if (parsed.delta?.stop_reason) {
            stopReason = parsed.delta.stop_reason;
          }
          if (parsed.usage?.output_tokens !== undefined) {
            outputTokens += parsed.usage.output_tokens;
          }
        } else if (event === 'message_stop') {
          // end of reply
        }
      }

      function processBuffer() {
        while (true) {
          const nlIndex = buffer.indexOf('\n');
          if (nlIndex === -1) break;
          let line = buffer.substring(0, nlIndex);
          if (line.endsWith('\r')) {
            line = line.substring(0, line.length - 1);
          }
          buffer = buffer.substring(nlIndex + 1);
          processLine(line);
        }
      }

      res.on('data', (chunk: Buffer) => {
        const text = decoder.decode(chunk, { stream: true });
        buffer += text;
        processBuffer();
      });

      res.on('end', () => {
        // Flush decoder
        const remaining = decoder.decode();
        if (remaining) {
          buffer += remaining;
        }
        processBuffer();

        // Process any remaining buffer as a final line (no trailing newline)
        if (buffer.length > 0) {
          let line = buffer;
          if (line.endsWith('\r')) line = line.substring(0, line.length - 1);
          processLine(line);
          buffer = '';
        }

        // Dispatch any pending event
        if (dataLines.length > 0) {
          const data = dataLines.join('\n');
          handleEvent(eventType, data);
          dataLines = [];
        }

        const orderedBlocks: ContentBlock[] = [];
        const sortedIndices = Array.from(blocks.keys()).sort((a, b) => a - b);
        for (const idx of sortedIndices) {
          orderedBlocks.push(blocks.get(idx)!);
        }

        resolve({
          status: 200,
          blocks: orderedBlocks,
          stopReason,
          inputTokens,
          outputTokens,
          cacheReadTokens
        });
      });

      res.on('error', reject);
    });

    req.on('error', reject);
    req.write(bodyStr);
    req.end();
  });
}

function printBlocks(blocks: ContentBlock[]) {
  for (const block of blocks) {
    if (block.type === 'thinking') {
      console.log(`thinking ${escapeString(block.thinking || '')}`);
      console.log(`signature ${escapeString(block.signature || '')}`);
    } else if (block.type === 'text') {
      console.log(`text ${escapeString(block.text || '')}`);
    } else if (block.type === 'tool_use') {
      console.log(`tool_use ${block.id} ${block.name} ${escapeString(block.partialJson || '')}`);
    }
  }
}

async function main() {
  const dataDir = process.argv[2];
  const baseUrl = process.argv[3];

  const requestJson = JSON.parse(fs.readFileSync(path.join(dataDir, 'request.json'), 'utf-8'));

  let totalInput = 0;
  let totalOutput = 0;
  let totalCacheRead = 0;

  // Request 1
  console.log('request 1');

  const result1 = await streamRequest(baseUrl, requestJson.api_key, {
    model: requestJson.model,
    max_tokens: requestJson.max_tokens,
    stream: true,
    thinking: { type: 'enabled', budget_tokens: requestJson.thinking_budget },
    system: requestJson.system,
    tools: requestJson.tools,
    messages: [{ role: 'user', content: requestJson.prompt }]
  });

  if (result1.status !== 200) {
    console.log(`ERROR ${result1.status} ${result1.errorType}: ${result1.errorMessage}`);
    process.exit(0);
  }

  const blocks1 = result1.blocks || [];
  printBlocks(blocks1);
  console.log(`stop_reason ${result1.stopReason}`);

  totalInput += result1.inputTokens || 0;
  totalOutput += result1.outputTokens || 0;
  totalCacheRead += result1.cacheReadTokens || 0;

  // Execute tools
  const assistantContent: any[] = [];
  const toolResults: any[] = [];

  for (const block of blocks1) {
    if (block.type === 'thinking') {
      assistantContent.push({
        type: 'thinking',
        thinking: block.thinking || '',
        signature: block.signature || ''
      });
    } else if (block.type === 'text') {
      assistantContent.push({ type: 'text', text: block.text || '' });
    } else if (block.type === 'tool_use') {
      let input: Record<string, string> = {};
      try {
        input = JSON.parse(block.partialJson || '{}');
      } catch {
        input = {};
      }
      assistantContent.push({
        type: 'tool_use',
        id: block.id,
        name: block.name,
        input
      });

      const toolResult = executeTool(block.name!, input);
      if (toolResult.isError) {
        console.log(`error ${block.id} ${escapeString(toolResult.result)}`);
        toolResults.push({ tool_use_id: block.id, content: toolResult.result, is_error: true });
      } else {
        console.log(`result ${block.id} ${escapeString(toolResult.result)}`);
        toolResults.push({ tool_use_id: block.id, content: toolResult.result });
      }
    }
  }

  // Request 2
  console.log('request 2');

  const result2 = await streamRequest(baseUrl, requestJson.api_key, {
    model: requestJson.model,
    max_tokens: requestJson.max_tokens,
    stream: true,
    thinking: { type: 'enabled', budget_tokens: requestJson.thinking_budget },
    system: requestJson.system,
    tools: requestJson.tools,
    messages: [
      { role: 'user', content: requestJson.prompt },
      { role: 'assistant', content: assistantContent },
      { role: 'user', content: toolResults }
    ]
  });

  if (result2.status !== 200) {
    console.log(`ERROR ${result2.status} ${result2.errorType}: ${result2.errorMessage}`);
    process.exit(0);
  }

  const blocks2 = result2.blocks || [];
  printBlocks(blocks2);
  console.log(`stop_reason ${result2.stopReason}`);

  totalInput += result2.inputTokens || 0;
  totalOutput += result2.outputTokens || 0;
  totalCacheRead += result2.cacheReadTokens || 0;

