const pageSize = pageSizeRaw === 1 ? 65536 : pageSizeRaw;
const reservedBytes = data[20];
const usableSize = pageSize - reservedBytes;

// CRC32 (zlib/PNG)
const crc32Table: number[] = [];
for (let i = 0; i < 256; i++) {
    let c = i;
    for (let j = 0; j < 8; j++) {
        c = (c & 1) ? (0xEDB88320 ^ (c >>> 1)) : (c >>> 1);
    }
    crc32Table[i] = c;
}
function crc32(buf: Buffer): number {
    let crc = 0xFFFFFFFF;
    for (let i = 0; i < buf.length; i++) {
        crc = crc32Table[(crc ^ buf[i]) & 0xFF] ^ (crc >>> 8);
    }
    return (crc ^ 0xFFFFFFFF) >>> 0;
}

// Varint (regular number, for payload sizes and serial types)
function readVarint(buf: Buffer, offset: number): [number, number] {
    let value = 0;
    for (let i = 0; i < 9; i++) {
        const b = buf[offset + i];
        if (i < 8) {
            value = value * 128 + (b & 0x7f);
        } else {
            value = value * 256 + b;
        }
        if ((b & 0x80) === 0) return [value, offset + i + 1];
    }
    return [value, offset + 9];
}

// Varint (BigInt, for rowids)
function readVarintBig(buf: Buffer, offset: number): [bigint, number] {
    let value = 0n;
    for (let i = 0; i < 9; i++) {
        const b = buf[offset + i];
        if (i < 8) {
            value = value * 128n + BigInt(b & 0x7f);
        } else {
            value = value * 256n + BigInt(b);
        }
        if ((b & 0x80) === 0) return [value, offset + i + 1];
    }
    return [value, offset + 9];
}

function getPage(pageNum: number): Buffer {
    const off = (pageNum - 1) * pageSize;
    return data.subarray(off, off + pageSize);
}

function getHdrOff(pageNum: number): number {
    return pageNum === 1 ? 100 : 0;
}

// Overflow calculation
const maxLocal = Math.floor((usableSize - 12) * 64 / 255) - 23;
const minLocal = Math.floor((usableSize - 12) * 32 / 255) - 23;

function readPayload(pageData: Buffer, offset: number, payloadSize: number): Buffer {
    let localSize: number;
    let hasOverflow = false;

    if (payloadSize <= maxLocal) {
        localSize = payloadSize;
    } else {
        localSize = minLocal + ((payloadSize - minLocal) % (usableSize - 4));
        hasOverflow = payloadSize > localSize;
    }

    const local = pageData.subarray(offset, offset + localSize);

    if (!hasOverflow) return local;

    const overflowPageNum = pageData.readUInt32BE(offset + localSize);
    if (overflowPageNum === 0) return local;

    const parts: Buffer[] = [local];
    let remaining = payloadSize - localSize;
    let op = overflowPageNum;
    while (op !== 0 && remaining > 0) {
        const opPage = getPage(op);
        const nextOp = opPage.readUInt32BE(0);
        const chunkSize = Math.min(remaining, usableSize - 4);
        parts.push(opPage.subarray(4, 4 + chunkSize));
        remaining -= chunkSize;
        op = nextOp;
    }
    return Buffer.concat(parts);
}

// Walk b-tree, collect rows
interface Row { rowid: bigint; payload: Buffer; }

function walkBTree(rootPage: number): Row[] {
    const results: Row[] = [];

    function walk(pageNum: number) {
        const page = getPage(pageNum);
        const hdrOff = getHdrOff(pageNum);
        const pageType = page[hdrOff];
        const cellCount = page.readUInt16BE(hdrOff + 3);
        const cellPtrStart = hdrOff + (pageType === 5 ? 12 : 8);

        if (pageType === 5) {
            // Interior table b-tree
            for (let i = 0; i < cellCount; i++) {
                const cellOff = page.readUInt16BE(cellPtrStart + i * 2);
                const childPage = page.readUInt32BE(cellOff);
                walk(childPage);
            }
            const rightChild = page.readUInt32BE(hdrOff + 8);
            walk(rightChild);
        } else if (pageType === 13) {
            // Leaf table b-tree
            for (let i = 0; i < cellCount; i++) {
                const cellOff = page.readUInt16BE(cellPtrStart + i * 2);
                const [payloadSize, off1] = readVarint(page, cellOff);
                const [rowid, off2] = readVarintBig(page, off1);
                const payload = readPayload(page, off2, payloadSize);
                results.push({ rowid, payload });
            }
        }
    }

    walk(rootPage);
    return results;
}

// Record value representation
interface RecordValue {
    type: 'null' | 'int' | 'real' | 'text' | 'blob';
    value: any;
}

function readRecord(payload: Buffer): RecordValue[] {
    if (payload.length === 0) return [];

    const [headerSize, off1] = readVarint(payload, 0);
    let offset = off1;
    const headerEnd = headerSize;

    const serialTypes: number[] = [];
    while (offset < headerEnd && offset < payload.length) {
        const [st, nextOff] = readVarint(payload, offset);
        serialTypes.push(st);
        offset = nextOff;
    }

    const values: RecordValue[] = [];
    for (const st of serialTypes) {
        if (st === 0) {
            values.push({ type: 'null', value: null });
        } else if (st === 1) {
            const v = payload.readInt8(offset); offset += 1;
            values.push({ type: 'int', value: BigInt(v) });
        } else if (st === 2) {
            const v = payload.readInt16BE(offset); offset += 2;
            values.push({ type: 'int', value: BigInt(v) });
        } else if (st === 3) {
            let v = (payload[offset] << 16) | (payload[offset + 1] << 8) | payload[offset + 2];
            if (v & 0x800000) v -= 0x1000000;
            offset += 3;
            values.push({ type: 'int', value: BigInt(v) });
        } else if (st === 4) {
            const v = payload.readInt32BE(offset); offset += 4;
            values.push({ type: 'int', value: BigInt(v) });
        } else if (st === 5) {
            let v = 0n;
            for (let i = 0; i < 6; i++) v = (v << 8n) | BigInt(payload[offset + i]);
            if (v & (1n << 47n)) v -= (1n << 48n);
            offset += 6;
            values.push({ type: 'int', value: v });
        } else if (st === 6) {
            const v = payload.readBigInt64BE(offset); offset += 8;
            values.push({ type: 'int', value: v });
        } else if (st === 7) {
            const v = payload.readDoubleBE(offset); offset += 8;
            values.push({ type: 'real', value: v });
        } else if (st === 8) {
            values.push({ type: 'int', value: 0n });
        } else if (st === 9) {
            values.push({ type: 'int', value: 1n });
        } else if (st >= 12 && st % 2 === 0) {
            const len = (st - 12) / 2;
            values.push({ type: 'blob', value: payload.subarray(offset, offset + len) });
            offset += len;
        } else if (st >= 13) {
            const len = (st - 13) / 2;
            values.push({ type: 'text', value: payload.subarray(offset, offset + len) });
            offset += len;
        } else {
            // Reserved types 10, 11
            values.push({ type: 'null', value: null });
        }
    }

    return values;
}

// Formatting
function formatValue(val: RecordValue): string {
    if (val.type === 'null') return 'NULL';
    if (val.type === 'int') return val.value.toString();
    if (val.type === 'real') return formatReal(val.value);
    if (val.type === 'text') return formatText(val.value);
    if (val.type === 'blob') return formatBlob(val.value);
    return 'NULL';
}

function formatReal(n: number): string {
    if (Object.is(n, -0)) return '-0.0';
    let s = n.toFixed(8);
    if (s.includes('.')) {
        s = s.replace(/0+$/, '');
        if (s.endsWith('.')) s += '0';
    }
    return s;
}

function formatText(buf: Buffer): string {
    if (buf.length > 100) {
        const crc = crc32(buf);
        return `<TEXT len=${buf.length} crc32=${crc.toString(16).padStart(8, '0')}>`;
    }
    return escapeText(buf);
}

function formatBlob(buf: Buffer): string {
    if (buf.length > 100) {
        const crc = crc32(buf);
        return `<BLOB len=${buf.length} crc32=${crc.toString(16).padStart(8, '0')}>`;
    }
    return "X'" + buf.toString('hex').toUpperCase() + "'";
}

function escapeText(buf: Buffer): string {
    let result = '"';
    let safeStart = 0;
    for (let i = 0; i < buf.length; i++) {
        const b = buf[i];
        let escape: string | null = null;
        if (b === 0x5C) escape = '\\\\';
        else if (b === 0x22) escape = '\\"';
        else if (b === 0x0A) escape = '\\n';
        else if (b === 0x0D) escape = '\\r';
        else if (b === 0x09) escape = '\\t';
        else if (b < 0x20 || b === 0x7F) escape = '\\x' + b.toString(16).toUpperCase().padStart(2, '0');
        if (escape !== null) {
            if (i > safeStart) result += buf.subarray(safeStart, i).toString('utf-8');
            result += escape;
            safeStart = i + 1;
        }
    }
    if (buf.length > safeStart) result += buf.subarray(safeStart).toString('utf-8');
    result += '"';
    return result;
}

// Parse CREATE TABLE SQL for column definitions
function parseColumns(sql: string): { name: string; isRowidAlias: boolean }[] {
    const openParen = sql.indexOf('(');
    const closeParen = sql.lastIndexOf(')');
    if (openParen === -1 || closeParen === -1) return [];
    const defsStr = sql.substring(openParen + 1, closeParen);

    // Split by commas not inside parentheses
    const defs: string[] = [];
    let depth = 0;
    let current = '';
    for (const ch of defsStr) {
        if (ch === '(') depth++;
        else if (ch === ')') depth--;
        if (ch === ',' && depth === 0) {
            defs.push(current.trim());
            current = '';
        } else {
            current += ch;
        }
    }
    if (current.trim()) defs.push(current.trim());

    const columns: { name: string; isRowidAlias: boolean }[] = [];
    for (const def of defs) {
        let rest = def.trim();
        let name: string;
        if (rest.startsWith('"')) {
            const endQuote = rest.indexOf('"', 1);
            name = rest.substring(1, endQuote);
            rest = rest.substring(endQuote + 1).trim();
        } else {
            const match = rest.match(/^([^\s(]+)/);
            if (!match) continue;
            name = match[1];
            rest = rest.substring(name.length).trim();
        }

        // Check for INTEGER PRIMARY KEY alias
        let isRowidAlias = false;
        const typeMatch = rest.match(/^([A-Za-z_][A-Za-z0-9_]*)/);
        if (typeMatch) {
            const typeWord = typeMatch[1].toUpperCase();
            const afterType = rest.substring(typeMatch[1].length).trimStart();
            const typeIsInteger = typeWord === 'INTEGER' && !afterType.startsWith('(');
            if (typeIsInteger && /PRIMARY\s+KEY/i.test(def)) {
                isRowidAlias = true;
            }
        }

        columns.push({ name, isRowidAlias });
    }
    return columns;
}

// Main logic
const schemaRows = walkBTree(1);
const tables: { name: string; rootpage: number; sql: string }[] = [];

for (const row of schemaRows) {
    const values = readRecord(row.payload);
    if (values.length < 5) continue;

    const type = values[0].type === 'text' ? values[0].value.toString('utf-8') : '';
    const name = values[1].type === 'text' ? values[1].value.toString('utf-8') : '';
    const rootpage = values[3].type === 'int' ? Number(values[3].value) : 0;
    const sql = values[4].type === 'text' ? values[4].value.toString('utf-8') : '';

    if (type === 'table' && !name.startsWith('sqlite_') && rootpage > 0) {
        tables.push({ name, rootpage, sql });
    }
}

// Sort by name (byte-wise ascending)
tables.sort((a, b) => {
    const aBuf = Buffer.from(a.name, 'utf-8');
    const bBuf = Buffer.from(b.name, 'utf-8');
    return Buffer.compare(aBuf, bBuf);
});

const outputs: string[] = [];

for (const table of tables) {
    const columns = parseColumns(table.sql);
    const rows = walkBTree(table.rootpage);

    const lines: string[] = [];
    lines.push(`TABLE ${table.name} rows=${rows.length}`);
    lines.push(`COLUMNS ${columns.map(c => c.name).join(', ')}`);

    for (const row of rows) {
        const values = readRecord(row.payload);
        const parts: string[] = [];

        for (let i = 0; i < columns.length; i++) {
            if (columns[i].isRowidAlias) {
                parts.push(row.rowid.toString());
            } else if (i < values.length) {
                parts.push(formatValue(values[i]));
            } else {
                parts.push('NULL');
            }
        }

        lines.push(`${row.rowid}: ${parts.join(', ')}`);
    }

    outputs.push(lines.join('\n'));
}

if (outputs.length > 0) {
    process.stdout.write(outputs.join('\n\n') + '\n');
}

