        else if (b === 0x0D) escape = '\\r';
        else if (b === 0x09) escape = '\\t';
        else if (b < 0x20 || b === 0x7F) escape = '\\x' + b.toString(16).toUpperCase().padStart(2, '0');
        if (escape !== null) {
            if (i > safeStart) result += buf.subarray(safeStart, i).toString('utf-8');
            result += escape;
            safeStart = i + 1;
        }
    }
    if (buf.length > safeStart) result += buf.subarray(safeStart).toString('utf-8');
    result += '"';
    return result;
}

// Parse CREATE TABLE SQL for column definitions
function parseColumns(sql: string): { name: string; isRowidAlias: boolean }[] {
    // Find the opening paren (skip if table name is quoted)
    let openParen = -1;
    let inQuote = false;
    for (let i = 0; i < sql.length; i++) {
        if (sql[i] === '"') inQuote = !inQuote;
        else if (sql[i] === '(' && !inQuote) { openParen = i; break; }
    }
    const closeParen = sql.lastIndexOf(')');
    if (openParen === -1 || closeParen === -1) return [];
    const defsStr = sql.substring(openParen + 1, closeParen);

    // Split by commas not inside parentheses
    const defs: string[] = [];
    let depth = 0;
    let current = '';
    for (const ch of defsStr) {
        if (ch === '(') depth++;
        else if (ch === ')') depth--;
        if (ch === ',' && depth === 0) {
            defs.push(current.trim());
            current = '';
        } else {
            current += ch;
        }
    }
    if (current.trim()) defs.push(current.trim());

    const columns: { name: string; isRowidAlias: boolean }[] = [];
    for (const def of defs) {
        let rest = def.trim();
        let name: string;
        if (rest.startsWith('"')) {
            const endQuote = rest.indexOf('"', 1);
            name = rest.substring(1, endQuote);
            rest = rest.substring(endQuote + 1).trim();
        } else {
            const match = rest.match(/^([^\s(]+)/);
            if (!match) continue;
            name = match[1];
            rest = rest.substring(name.length).trim();
        }

        // Check for INTEGER PRIMARY KEY alias
        let isRowidAlias = false;
        const typeMatch = rest.match(/^([A-Za-z_][A-Za-z0-9_]*)/);
        if (typeMatch) {
            const typeWord = typeMatch[1].toUpperCase();
            const afterType = rest.substring(typeMatch[1].length).trimStart();
            const typeIsInteger = typeWord === 'INTEGER' && !afterType.startsWith('(');
            if (typeIsInteger && /PRIMARY\s+KEY/i.test(def)) {
                isRowidAlias = true;
            }
        }

        columns.push({ name, isRowidAlias });
    }
    return columns;
}

// Main logic
const schemaRows = walkBTree(1);
const tables: { name: string; rootpage: number; sql: string }[] = [];

for (const row of schemaRows) {
    const values = readRecord(row.payload);
    if (values.length < 5) continue;

    const type = values[0].type === 'text' ? values[0].value.toString('utf-8') : '';
    const name = values[1].type === 'text' ? values[1].value.toString('utf-8') : '';
    const rootpage = values[3].type === 'int' ? Number(values[3].value) : 0;
    const sql = values[4].type === 'text' ? values[4].value.toString('utf-8') : '';

    if (type === 'table' && !name.startsWith('sqlite_') && rootpage > 0) {
        tables.push({ name, rootpage, sql });
    }
}

// Sort by name (byte-wise ascending)
tables.sort((a, b) => {
    const aBuf = Buffer.from(a.name, 'utf-8');
    const bBuf = Buffer.from(b.name, 'utf-8');
    return Buffer.compare(aBuf, bBuf);
});

const outputs: string[] = [];

for (const table of tables) {
    const columns = parseColumns(table.sql);
    const rows = walkBTree(table.rootpage);

    // Sort rows by rowid (signed 64-bit)
    rows.sort((a, b) => {
        if (a.rowid < b.rowid) return -1;
        if (a.rowid > b.rowid) return 1;
        return 0;
    });

    const lines: string[] = [];
    lines.push(`TABLE ${table.name} rows=${rows.length}`);
    lines.push(`COLUMNS ${columns.map(c => c.name).join(', ')}`);

    for (const row of rows) {
        const values = readRecord(row.payload);
        const parts: string[] = [];

        for (let i = 0; i < columns.length; i++) {
            if (columns[i].isRowidAlias) {
                parts.push(row.rowid.toString());
            } else if (i < values.length) {
                parts.push(formatValue(values[i]));
            } else {
                parts.push('NULL');
            }
        }

        lines.push(`${row.rowid}: ${parts.join(', ')}`);
    }

    outputs.push(lines.join('\n'));
}

if (outputs.length > 0) {
    process.stdout.write(outputs.join('\n\n') + '\n');
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <strings.h>
#include <stdint.h>
#include <inttypes.h>
#include <ctype.h>

static uint8_t *db;
static long db_size;
static int page_size, reserved_bytes, num_pages, usable_size;

static uint16_t be16(const uint8_t *p){return (p[0]<<8)|p[1];}
static uint32_t be32(const uint8_t *p){return ((uint32_t)p[0]<<24)|((uint32_t)p[1]<<16)|((uint32_t)p[2]<<8)|p[3];}

static uint64_t read_varint(const uint8_t *p,int *n){
    uint64_t v=0;int i;
    for(i=0;i<9;i++){
        if(i==8){v=(v<<8)|p[8];*n=9;return v;}
        v=(v<<7)|(p[i]&0x7F);
        if(!(p[i]&0x80)){*n=i+1;return v;}
    }
    *n=9;return v;
}

static uint8_t *get_page(int pgno){return db+(long)(pgno-1)*page_size;}

static uint32_t crc32(const uint8_t *data,int len){
    uint32_t c=0xFFFFFFFF;
    for(int i=0;i<len;i++){c^=data[i];for(int j=0;j<8;j++){if(c&1)c=(c>>1)^0xEDB88320;else c>>=1;}}
    return c^0xFFFFFFFF;
}

typedef struct{int type;int64_t ival;double dval;uint8_t *data;int len;}Value;
typedef struct{int64_t rowid;int ncols;Value *vals;}Row;
typedef struct{char *name;char *sql;int rootpage;int ncols;char **colnames;int *is_alias;}Table;

static void parse_record(const uint8_t *data,int len,Value **vals,int *nvals){
    int pos=0,br;
    uint64_t hdr=(uint64_t)read_varint(data+pos,&br);
    pos+=br;
    int data_start=(int)hdr;
    int stypes[512];int n=0;
    while(pos<data_start&&n<512){
        uint64_t st=read_varint(data+pos,&br);pos+=br;
        stypes[n++]=(int)st;
    }
    *nvals=n;
    *vals=calloc(n?n:1,sizeof(Value));
    for(int i=0;i<n;i++){
        int st=stypes[i];
        if(st==0){(*vals)[i].type=0;}
        else if(st>=1&&st<=6){
            (*vals)[i].type=1;
            int nb=(st==5)?6:(st==6)?8:st;
            int64_t v=0;
            if(nb<8&&(data[pos]&0x80))v=-1;
            for(int j=0;j<nb;j++)v=(v<<8)|data[pos+j];
            (*vals)[i].ival=v;pos+=nb;
        }else if(st==7){
            (*vals)[i].type=2;
            uint64_t bits=0;for(int j=0;j<8;j++)bits=(bits<<8)|data[pos+j];
            memcpy(&(*vals)[i].dval,&bits,8);pos+=8;
        }else if(st==8){(*vals)[i].type=1;(*vals)[i].ival=0;}
        else if(st==9){(*vals)[i].type=1;(*vals)[i].ival=1;}
        else if(st>=12&&st%2==0){
            int bl=(st-12)/2;(*vals)[i].type=4;(*vals)[i].len=bl;
            (*vals)[i].data=malloc(bl+1);memcpy((*vals)[i].data,data+pos,bl);(*vals)[i].data[bl]=0;pos+=bl;
        }else if(st>=13){
            int tl=(st-13)/2;(*vals)[i].type=3;(*vals)[i].len=tl;
            (*vals)[i].data=malloc(tl+1);memcpy((*vals)[i].data,data+pos,tl);(*vals)[i].data[tl]=0;pos+=tl;
        }
    }
}

static void walk_btree(int pgno,Row **rows,int *nrows,int *cap){
    if(pgno<=0||pgno>num_pages)return;
    uint8_t *pg=get_page(pgno);
    int hdr=(pgno==1)?100:0;
    int ptype=pg[hdr];
    int ncells=be16(pg+hdr+3);
    if(ptype==5){
        int rightmost=(int)be32(pg+hdr+8);
        int pb=hdr+12;
        for(int i=0;i<ncells;i++){
            int co=be16(pg+pb+i*2);
            int left=(int)be32(pg+co);
            walk_btree(left,rows,nrows,cap);
        }
        walk_btree(rightmost,rows,nrows,cap);
    }else if(ptype==13){
        int pb=hdr+8;
        int U=((usable_size-35)*32/255)-23;
        for(int i=0;i<ncells;i++){
            int co=be16(pg+pb+i*2);
            int pos=co,br;
            uint64_t psz=read_varint(pg+pos,&br);pos+=br;
            int64_t rowid=(int64_t)read_varint(pg+pos,&br);pos+=br;
            int local;
            if((int)psz<=U)local=(int)psz;
            else local=((int)(psz-35)%(usable_size-4))+35;
            uint8_t *payload=malloc(psz?psz:1);
            memcpy(payload,pg+pos,local);pos+=local;
            if((int)psz>local){
                int op=(int)be32(pg+pos);
                int rem=(int)psz-local,written=local;
                while(op!=0&&rem>0){
                    uint8_t *o=get_page(op);
                    int chunk=rem<(usable_size-4)?rem:(usable_size-4);
                    memcpy(payload+written,o+4,chunk);
                    written+=chunk;rem-=chunk;
                    op=(int)be32(o);
                }
            }
            Value *vals;int nvals;
            parse_record(payload,(int)psz,&vals,&nvals);
            if(*nrows>=*cap){*cap=*cap?*cap*2:64;*rows=realloc(*rows,*cap*sizeof(Row));}
            (*rows)[*nrows].rowid=rowid;(*rows)[*nrows].ncols=nvals;(*rows)[*nrows].vals=vals;
            (*nrows)++;
            free(payload);
        }
    }
}

static const char *find_open_paren(const char *s){
    int q=0;
    for(const char *p=s;*p;p++){
        if(*p=='"')q=!q;
        else if(*p=='('&&!q)return p;
    }
    return NULL;
}

static const char *find_close_paren(const char *open){
    int d=0,q=0;
    for(const char *p=open;*p;p++){
        if(*p=='"')q=!q;
        else if(!q){if(*p=='(')d++;else if(*p==')'){d--;if(!d)return p;}}
    }
    return NULL;
}

static int contains_pk(const char *s,const char *end){
    int fp=0;
    while(s<end){
        while(s<end&&!isalpha((unsigned char)*s)&&*s!='_')s++;
        if(s>=end)break;
        const char *ws=s;
        while(s<end&&(isalnum((unsigned char)*s)||*s=='_'))s++;
        int wl=s-ws;
        if(wl==7&&strncasecmp(ws,"PRIMARY",7)==0)fp=1;
        else if(fp&&wl==3&&strncasecmp(ws,"KEY",3)==0)return 1;
    }
    return 0;
}

static int is_alias(const char *def,int len){
    const char *p=def,*end=def+len;
    while(p<end&&isspace((unsigned char)*p))p++;
    if(p<end&&*p=='"'){p++;while(p<end&&*p!='"')p++;if(p<end)p++;}
    else{while(p<end&&(isalnum((unsigned char)*p)||*p=='_'))p++;}
    while(p<end&&isspace((unsigned char)*p))p++;
    if(end-p>=7&&strncasecmp(p,"INTEGER",7)==0){
        const char *a=p+7;
        if(a>=end||(!isalnum((unsigned char)*a)&&*a!='_')){
            const char *q=a;while(q<end&&isspace((unsigned char)*q))q++;
            if(q>=end||*q!='(')return contains_pk(a,end);
        }
    }
    return 0;
}

static void parse_columns(const char *sql,Table *tbl){
    tbl->ncols=0;tbl->colnames=NULL;tbl->is_alias=NULL;
    if(!sql)return;
    const char *op=find_open_paren(sql);
    if(!op)return;
    const char *cp=find_close_paren(op);
    if(!cp)return;
    const char *start=op+1,*end=cp;
    /* split by commas at depth 0, not inside quotes */
    int depth=0,q=0,n=0,cap=16;
    char **defs=malloc(cap*sizeof(char*));
    const char *ss=start;
    for(const char *p=start;p<=end;p++){
        if(p==end||(*p==','&&depth==0&&!q)){
            int l=p-ss;
            while(l>0&&isspace((unsigned char)*ss)){ss++;l--;}
            while(l>0&&isspace((unsigned char)ss[l-1]))l--;
            if(l>0){
                if(n>=cap){cap*=2;defs=realloc(defs,cap*sizeof(char*));}
                defs[n]=malloc(l+1);memcpy(defs[n],ss,l);defs[n][l]=0;n++;
            }
            ss=p+1;
        }
        if(p<end){
            if(*p=='"')q=!q;
            else if(!q){if(*p=='(')depth++;else if(*p==')')depth--;}
        }
    }
    tbl->ncols=n;
    tbl->colnames=malloc(n?n*sizeof(char*):1);
    tbl->is_alias=malloc(n?n*sizeof(int):1);
    for(int i=0;i<n;i++){
        const char *d=defs[i];
        while(*d&&isspace((unsigned char)*d))d++;
        char *name;
        if(*d=='"'){
            d++;const char *ns=d;
            while(*d&&*d!='"')d++;
            int nl=d-ns;name=malloc(nl+1);memcpy(name,ns,nl);name[nl]=0;
        }else{
            const char *ns=d;
            while(*d&&(isalnum((unsigned char)*d)||*d=='_'))d++;
            int nl=d-ns;name=malloc(nl+1);memcpy(name,ns,nl);name[nl]=0;
        }
        tbl->colnames[i]=name;
        tbl->is_alias[i]=is_alias(defs[i],(int)strlen(defs[i]));
        free(defs[i]);
    }
    free(defs);
}

static void print_real(double d){
    char buf[512];
    snprintf(buf,sizeof(buf),"%.8f",d);
    int len=strlen(buf),dot=-1;
    for(int i=0;i<len;i++)if(buf[i]=='.'){dot=i;break;}
    if(dot>=0){
        int last=len-1;
        while(last>dot+1&&buf[last]=='0')last--;
        buf[last+1]=0;
    }
    printf("%s",buf);
}

static void print_text(const uint8_t *data,int len){
    putchar('"');
    for(int i=0;i<len;i++){
        uint8_t c=data[i];
        if(c=='\\')printf("\\\\");
        else if(c=='"')printf("\\\"");
        else if(c=='\n')printf("\\n");
        else if(c=='\r')printf("\\r");
        else if(c=='\t')printf("\\t");
        else if(c<0x20||c==0x7F)printf("\\x%02X",c);
        else putchar(c);
    }
    putchar('"');
}

static void print_blob(const uint8_t *data,int len){
    printf("X'");
    for(int i=0;i<len;i++)printf("%02X",data[i]);
    printf("'");
}

static void print_long(const char *type,const uint8_t *data,int len){
    printf("<%s len=%d crc32=%08x>",type,len,crc32(data,len));
}

static void print_value(Value *v,int alias,int64_t rowid){
    if(alias){printf("%" PRId64,rowid);return;}
    switch(v->type){
        case 0:printf("NULL");break;
        case 1:printf("%" PRId64,v->ival);break;
        case 2:print_real(v->dval);break;
        case 3:if(v->len<=100)print_text(v->data,v->len);else print_long("TEXT",v->data,v->len);break;
        case 4:if(v->len<=100)print_blob(v->data,v->len);else print_long("BLOB",v->data,v->len);break;
    }
}

static int cmp_table(const void *a,const void *b){
    return strcmp(((const Table*)a)->name,((const Table*)b)->name);
}
static int cmp_row(const void *a,const void *b){
    int64_t ra=((const Row*)a)->rowid,rb=((const Row*)b)->rowid;
    return ra<rb?-1:ra>rb?1:0;
}

int main(int argc,char *argv[]){
    char path[4096];
    snprintf(path,sizeof(path),"%s/db.sqlite",argv[1]);
    FILE *f=fopen(path,"rb");
    fseek(f,0,SEEK_END);db_size=ftell(f);fseek(f,0,SEEK_SET);
    db=malloc(db_size);fread(db,1,db_size,f);fclose(f);

    page_size=be16(db+16);if(page_size==1)page_size=65536;
    reserved_bytes=db[20];
    num_pages=(int)be32(db+28);
    usable_size=page_size-reserved_bytes;

    /* walk schema b-tree (page 1) */
    Row *srows=NULL;int ns=0,cs=0;
    walk_btree(1,&srows,&ns,&cs);

    /* extract tables */
    Table *tables=malloc(ns*sizeof(Table));
    int nt=0;
    for(int i=0;i<ns;i++){
        Value *v=srows[i].vals;int nv=srows[i].ncols;
        if(nv<4)continue;
        if(v[0].type!=3||!v[0].data)continue;
        if(strcmp((char*)v[0].data,"table")!=0)continue;
        if(v[1].type!=3||!v[1].data)continue;
        const char *name=(char*)v[1].data;
        if(strncmp(name,"sqlite_",7)==0)continue;
        int rp=(v[3].type==1)?(int)v[3].ival:0;
        if(rp==0)continue;
        char *sql=NULL;
        if(v[4].type==3&&v[4].data)sql=strdup((char*)v[4].data);
        tables[nt].name=strdup(name);
        tables[nt].sql=sql;
        tables[nt].rootpage=rp;
        tables[nt].ncols=0;tables[nt].colnames=NULL;tables[nt].is_alias=NULL;
        nt++;
    }
    qsort(tables,nt,sizeof(Table),cmp_table);

    for(int i=0;i<nt;i++){
        if(i>0)printf("\n");
        parse_columns(tables[i].sql,&tables[i]);
        Row *rows=NULL;int nr=0,cr=0;
        walk_btree(tables[i].rootpage,&rows,&nr,&cr);
        qsort(rows,nr,sizeof(Row),cmp_row);
        printf("TABLE %s rows=%d\n",tables[i].name,nr);
        printf("COLUMNS");
        for(int c=0;c<tables[i].ncols;c++){
            printf("%s %s",c?",":"",tables[i].colnames[c]);
        }
        printf("\n");
        for(int r=0;r<nr;r++){
            printf("%" PRId64 ":",rows[r].rowid);
            for(int c=0;c<tables[i].ncols;c++){
                printf(" ");
                if(c<rows[r].ncols)
                    print_value(&rows[r].vals[c],tables[i].is_alias[c],rows[r].rowid);
                else{
                    if(tables[i].is_alias[c])printf("%" PRId64,rows[r].rowid);
                    else printf("NULL");
                }
                if(c<tables[i].ncols-1)printf(",");
            }
            printf("\n");
        }
    }
    return 0;
}

#define _POSIX_C_SOURCE 200809L
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <strings.h>
#include <stdint.h>
#include <inttypes.h>
#include <ctype.h>

static uint8_t *db;
static long db_size;
static int page_size, reserved_bytes, num_pages, usable_size;

static uint16_t be16(const uint8_t *p){return (p[0]<<8)|p[1];}
static uint32_t be32(const uint8_t *p){return ((uint32_t)p[0]<<24)|((uint32_t)p[1]<<16)|((uint32_t)p[2]<<8)|p[3];}

static uint64_t read_varint(const uint8_t *p,int *n){
    uint64_t v=0;int i;
    for(i=0;i<9;i++){
        if(i==8){v=(v<<8)|p[8];*n=9;return v;}
        v=(v<<7)|(p[i]&0x7F);
        if(!(p[i]&0x80)){*n=i+1;return v;}
    }
    *n=9;return v;
}

static uint8_t *get_page(int pgno){return db+(long)(pgno-1)*page_size;}

static uint32_t crc32_fn(const uint8_t *data,int len){
    uint32_t c=0xFFFFFFFF;
    for(int i=0;i<len;i++){c^=data[i];for(int j=0;j<8;j++){if(c&1)c=(c>>1)^0xEDB88320;else c>>=1;}}
    return c^0xFFFFFFFF;
}

typedef struct{int type;int64_t ival;double dval;uint8_t *data;int len;}Value;
typedef struct{int64_t rowid;int ncols;Value *vals;}Row;
typedef struct{char *name;char *sql;int rootpage;int ncols;char **colnames;int *is_alias;}Table;

static void parse_record(const uint8_t *data,int len,Value **vals,int *nvals){
    if(len<=0){*nvals=0;*vals=NULL;return;}
    int pos=0,br;
    uint64_t hdr_size=read_varint(data+pos,&br);
    pos+=br;
    int data_start=(int)hdr_size;
    if(data_start>len)data_start=len;

    int stypes_cap=64,n=0;
    int *stypes=malloc(stypes_cap*sizeof(int));
    while(pos<data_start){
        if(n>=stypes_cap){stypes_cap*=2;stypes=realloc(stypes,stypes_cap*sizeof(int));}
        uint64_t st=read_varint(data+pos,&br);pos+=br;
        stypes[n++]=(int)st;
    }

    *nvals=n;
    *vals=calloc(n?n:1,sizeof(Value));

    for(int i=0;i<n;i++){
        int st=stypes[i];
        if(st==0){
            (*vals)[i].type=0;
        }else if(st>=1&&st<=6){
            (*vals)[i].type=1;
            int nb=(st==5)?6:(st==6)?8:st;
            if(pos+nb>len)nb=len-pos;
            int64_t v=0;
            if(nb>0&&pos<len&&(data[pos]&0x80))v=-1;
            for(int j=0;j<nb;j++)v=(v<<8)|data[pos+j];
            (*vals)[i].ival=v;pos+=nb;
        }else if(st==7){
            (*vals)[i].type=2;
            uint64_t bits=0;
            for(int j=0;j<8&&pos+j<len;j++)bits=(bits<<8)|data[pos+j];
            memcpy(&(*vals)[i].dval,&bits,8);pos+=8;
        }else if(st==8){
            (*vals)[i].type=1;(*vals)[i].ival=0;
        }else if(st==9){
            (*vals)[i].type=1;(*vals)[i].ival=1;
        }else if(st>=12&&st%2==0){
            int bl=(st-12)/2;
            (*vals)[i].type=4;
            if(pos+bl>len)bl=len-pos;
            if(bl<0)bl=0;
            (*vals)[i].len=bl;
            (*vals)[i].data=malloc(bl+1);
            memcpy((*vals)[i].data,data+pos,bl);
            (*vals)[i].data[bl]=0;
            pos+=bl;
        }else if(st>=13){
            int tl=(st-13)/2;
            (*vals)[i].type=3;
            if(pos+tl>len)tl=len-pos;
            if(tl<0)tl=0;
            (*vals)[i].len=tl;
            (*vals)[i].data=malloc(tl+1);
            memcpy((*vals)[i].data,data+pos,tl);
            (*vals)[i].data[tl]=0;
            pos+=tl;
        }
    }
    free(stypes);
}

static void walk_btree(int pgno,Row **rows,int *nrows,int *cap){
    if(pgno<=0||pgno>num_pages)return;
    uint8_t *pg=get_page(pgno);
    int hdr=(pgno==1)?100:0;
    int ptype=pg[hdr];
    int ncells=be16(pg+hdr+3);

    if(ptype==5){
        int rightmost=(int)be32(pg+hdr+8);
        int pb=hdr+12;
        for(int i=0;i<ncells;i++){
            int co=be16(pg+pb+i*2);
            int left=(int)be32(pg+co);
            walk_btree(left,rows,nrows,cap);
        }
        walk_btree(rightmost,rows,nrows,cap);
    }else if(ptype==13){
        int pb=hdr+8;
        int X=usable_size-35;
        for(int i=0;i<ncells;i++){
            int co=be16(pg+pb+i*2);
            int pos=co,br;
            uint64_t psz=read_varint(pg+pos,&br);pos+=br;
            int64_t rowid=(int64_t)read_varint(pg+pos,&br);pos+=br;

            int local;
            if((int)psz<=X)local=(int)psz;
            else{
                local=((int)(psz-X)%(usable_size-4))+X;
                if(local>X)local=X;
            }

            uint8_t *payload=malloc(psz?psz:1);
            if(local>0)memcpy(payload,pg+pos,local);
            pos+=local;

            if((int)psz>local){
                int op=(int)be32(pg+pos);
                int rem=(int)psz-local,written=local;
                while(op!=0&&rem>0&&op<=num_pages){
                    uint8_t *o=get_page(op);
                    int chunk=rem<(usable_size-4)?rem:(usable_size-4);
                    memcpy(payload+written,o+4,chunk);
                    written+=chunk;rem-=chunk;
                    op=(int)be32(o);
                }
            }

            Value *vals;int nvals;
            parse_record(payload,(int)psz,&vals,&nvals);
            if(*nrows>=*cap){*cap=*cap?*cap*2:64;*rows=realloc(*rows,*cap*sizeof(Row));}
            (*rows)[*nrows].rowid=rowid;(*rows)[*nrows].ncols=nvals;(*rows)[*nrows].vals=vals;
            (*nrows)++;
            free(payload);
        }
    }
}

static const char *find_open_paren(const char *s){
    int q=0;
    for(const char *p=s;*p;p++){
        if(*p=='"')q=!q;
        else if(*p=='('&&!q)return p;
    }
    return NULL;
}

static const char *find_close_paren(const char *open){
    int d=0,q=0;
    for(const char *p=open;*p;p++){
        if(*p=='"')q=!q;
        else if(!q){if(*p=='(')d++;else if(*p==')'){d--;if(!d)return p;}}
    }
    return NULL;
}

static int contains_pk(const char *s,const char *end){
    int fp=0;
    while(s<end){
        while(s<end&&!isalpha((unsigned char)*s)&&*s!='_')s++;
        if(s>=end)break;
        const char *ws=s;
        while(s<end&&(isalnum((unsigned char)*s)||*s=='_'))s++;
        int wl=s-ws;
        if(wl==7&&strncasecmp(ws,"PRIMARY",7)==0){fp=1;}
        else if(fp&&wl==3&&strncasecmp(ws,"KEY",3)==0){return 1;}
        else{fp=0;}
    }
    return 0;
}

static int is_alias(const char *def,int len){
    const char *p=def,*end=def+len;
    while(p<end&&isspace((unsigned char)*p))p++;
    if(p<end&&*p=='"'){p++;while(p<end&&*p!='"')p++;if(p<end)p++;}
    else{while(p<end&&(isalnum((unsigned char)*p)||*p=='_'))p++;}
    while(p<end&&isspace((unsigned char)*p))p++;
    if(end-p>=7&&strncasecmp(p,"INTEGER",7)==0){
        const char *a=p+7;
        if(a>=end||(!isalnum((unsigned char)*a)&&*a!='_')){
            const char *q=a;while(q<end&&isspace((unsigned char)*q))q++;
            if(q>=end||*q!='(')return contains_pk(a,end);
        }
    }
    return 0;
}

static void parse_columns(const char *sql,Table *tbl){
    tbl->ncols=0;tbl->colnames=NULL;tbl->is_alias=NULL;
    if(!sql)return;
    const char *op=find_open_paren(sql);
    if(!op)return;
    const char *cp=find_close_paren(op);
    if(!cp)return;
    const char *start=op+1,*end=cp;
    int depth=0,q=0,n=0,cap=16;
    char **defs=malloc(cap*sizeof(char*));
    const char *ss=start;
    for(const char *p=start;p<=end;p++){
        if(p==end||(*p==','&&depth==0&&!q)){
            int l=p-ss;
            while(l>0&&isspace((unsigned char)*ss)){ss++;l--;}
            while(l>0&&isspace((unsigned char)ss[l-1]))l--;
            if(l>0){
                if(n>=cap){cap*=2;defs=realloc(defs,cap*sizeof(char*));}
                defs[n]=malloc(l+1);memcpy(defs[n],ss,l);defs[n][l]=0;n++;
            }
            ss=p+1;
        }
        if(p<end){
            if(*p=='"')q=!q;
            else if(!q){if(*p=='(')depth++;else if(*p==')')depth--;}
        }
    }
    tbl->ncols=n;
    tbl->colnames=malloc(n?n*sizeof(char*):1);
    tbl->is_alias=malloc(n?n*sizeof(int):1);
    for(int i=0;i<n;i++){
        const char *d=defs[i];
        while(*d&&isspace((unsigned char)*d))d++;
        char *name;
        if(*d=='"'){
            d++;const char *ns=d;
            while(*d&&*d!='"')d++;
            int nl=d-ns;name=malloc(nl+1);memcpy(name,ns,nl);name[nl]=0;
        }else{
            const char *ns=d;
            while(*d&&(isalnum((unsigned char)*d)||*d=='_'))d++;
            int nl=d-ns;name=malloc(nl+1);memcpy(name,ns,nl);name[nl]=0;
        }
        tbl->colnames[i]=name;
        tbl->is_alias[i]=is_alias(defs[i],(int)strlen(defs[i]));
        free(defs[i]);
    }
    free(defs);
}

static void print_real(double d){
    char buf[512];
    snprintf(buf,sizeof(buf),"%.8f",d);
    int len=strlen(buf),dot=-1;
    for(int i=0;i<len;i++)if(buf[i]=='.'){dot=i;break;}
    if(dot>=0){
        int last=len-1;
        while(last>dot+1&&buf[last]=='0')last--;
        buf[last+1]=0;
    }
    printf("%s",buf);
}

static void print_text(const uint8_t *data,int len){
    putchar('"');
    for(int i=0;i<len;i++){
        uint8_t c=data[i];
        if(c=='\\')printf("\\\\");
        else if(c=='"')printf("\\\"");
        else if(c=='\n')printf("\\n");
        else if(c=='\r')printf("\\r");
        else if(c=='\t')printf("\\t");
        else if(c<0x20||c==0x7F)printf("\\x%02X",c);
        else putchar(c);
    }
    putchar('"');
}

static void print_blob(const uint8_t *data,int len){
    printf("X'");
    for(int i=0;i<len;i++)printf("%02X",data[i]);
    printf("'");
}

static void print_long(const char *type,const uint8_t *data,int len){
    printf("<%s len=%d crc32=%08x>",type,len,crc32_fn(data,len));
}

static void print_value(Value *v,int alias,int64_t rowid){
    if(alias){printf("%" PRId64,rowid);return;}
    switch(v->type){
        case 0:printf("NULL");break;
        case 1:printf("%" PRId64,v->ival);break;
        case 2:print_real(v->dval);break;
        case 3:if(v->len<=100)print_text(v->data,v->len);else print_long("TEXT",v->data,v->len);break;
        case 4:if(v->len<=100)print_blob(v->data,v->len);else print_long("BLOB",v->data,v->len);break;
    }
}

static int cmp_table(const void *a,const void *b){
    return strcmp(((const Table*)a)->name,((const Table*)b)->name);
}
static int cmp_row(const void *a,const void *b){
    int64_t ra=((const Row*)a)->rowid,rb=((const Row*)b)->rowid;
    return ra<rb?-1:ra>rb?1:0;
}

int main(int argc,char *argv[]){
    if(argc<2)return 1;
    char path[4096];
    snprintf(path,sizeof(path),"%s/db.sqlite",argv[1]);
    FILE *f=fopen(path,"rb");
    if(!f)return 1;
    fseek(f,0,SEEK_END);db_size=ftell(f);fseek(f,0,SEEK_SET);
    db=malloc(db_size);fread(db,1,db_size,f);fclose(f);

    page_size=be16(db+16);if(page_size==1)page_size=65536;
    reserved_bytes=db[20];
    num_pages=(int)(db_size/page_size);
    usable_size=page_size-reserved_bytes;

    /* walk schema b-tree (page 1) */
    Row *srows=NULL;int ns=0,cs=0;
    walk_btree(1,&srows,&ns,&cs);

    /* extract tables */
    Table *tables=malloc((ns+1)*sizeof(Table));
    int nt=0;
    for(int i=0;i<ns;i++){
        Value *v=srows[i].vals;int nv=srows[i].ncols;
        if(nv<5)continue;
        if(v[0].type!=3||!v[0].data)continue;
        if(strcmp((char*)v[0].data,"table")!=0)continue;
        if(v[1].type!=3||!v[1].data)continue;
        const char *name=(char*)v[1].data;
        if(strncmp(name,"sqlite_",7)==0)continue;
        int rp=(v[3].type==1)?(int)v[3].ival:0;
        if(rp==0)continue;
        char *sql=NULL;
        if(v[4].type==3&&v[4].data)sql=strdup((char*)v[4].data);
        tables[nt].name=strdup(name);
        tables[nt].sql=sql;
        tables[nt].rootpage=rp;
        tables[nt].ncols=0;tables[nt].colnames=NULL;tables[nt].is_alias=NULL;
        nt++;
    }
    qsort(tables,nt,sizeof(Table),cmp_table);

    for(int i=0;i<nt;i++){
        if(i>0)printf("\n");
        parse_columns(tables[i].sql,&tables[i]);
        Row *rows=NULL;int nr=0,cr=0;
        walk_btree(tables[i].rootpage,&rows,&nr,&cr);
        qsort(rows,nr,sizeof(Row),cmp_row);
        printf("TABLE %s rows=%d\n",tables[i].name,nr);
        printf("COLUMNS");
        for(int c=0;c<tables[i].ncols;c++){
            printf("%s %s",c?",":"",tables[i].colnames[c]);
        }
        printf("\n");
        for(int r=0;r<nr;r++){
            printf("%" PRId64 ":",rows[r].rowid);
            for(int c=0;c<tables[i].ncols;c++){
                printf(" ");
                if(c<rows[r].ncols)
                    print_value(&rows[r].vals[c],tables[i].is_alias[c],rows[r].rowid);
                else{
                    if(tables[i].is_alias[c])printf("%" PRId64,rows[r].rowid);
                    else printf("NULL");
                }
                if(c<tables[i].ncols-1)printf(",");
            }
            printf("\n");
        }
    }
    return 0;
}

use std::env;
use std::fs;

#[derive(Clone)]
enum Value {
    Null,
    Integer(i64),
    Real(f64),
    Text(Vec<u8>),
    Blob(Vec<u8>),
}

fn read_be_u16(d: &[u8], o: usize) -> u16 {
    u16::from_be_bytes([d[o], d[o + 1]])
}

fn read_be_u32(d: &[u8], o: usize) -> u32 {
    u32::from_be_bytes([d[o], d[o + 1], d[o + 2], d[o + 3]])
}

fn read_be_i16(d: &[u8], o: usize) -> i16 {
    i16::from_be_bytes([d[o], d[o + 1]])
}

fn read_be_i32(d: &[u8], o: usize) -> i32 {
    i32::from_be_bytes([d[o], d[o + 1], d[o + 2], d[o + 3]])
}

fn read_be_i64(d: &[u8], o: usize) -> i64 {
    i64::from_be_bytes(d[o..o + 8].try_into().unwrap())
}

fn read_be_f64(d: &[u8], o: usize) -> f64 {
    f64::from_be_bytes(d[o..o + 8].try_into().unwrap())
}

fn read_varint(d: &[u8], o: usize) -> (u64, usize) {
    let mut r: u64 = 0;
    let mut i = 0;
    loop {
        let b = d[o + i];
        if i == 8 {
            r = (r << 8) | (b as u64);
            i += 1;
            break;
        }
        r = (r << 7) | ((b & 0x7f) as u64);
        i += 1;
        if b & 0x80 == 0 {
            break;
        }
    }
    (r, i)
}

fn walk_btree(d: &[u8], pg: usize, ps: usize, res: usize, rows: &mut Vec<(i64, Vec<u8>)>) {
    if pg == 0 {
        return;
    }
    let base = (pg - 1) * ps;
    let h = if pg == 1 { 100 } else { 0 };
    let pt = d[base + h];
    let nc = read_be_u16(d, base + h + 3) as usize;

    if pt == 5 {
        for i in 0..nc {
            let co = read_be_u16(d, base + h + 12 + i * 2) as usize;
            let child = read_be_u32(d, base + co) as usize;
            walk_btree(d, child, ps, res, rows);
        }
        let rm = read_be_u32(d, base + h + 8) as usize;
        walk_btree(d, rm, ps, res, rows);
    } else if pt == 13 {
        let usable = ps - res;
        let max_local = usable - 35;
        for i in 0..nc {
            let co = read_be_u16(d, base + h + 8 + i * 2) as usize;
            let mut pos = base + co;
            let (psize, n) = read_varint(d, pos);
            pos += n;
            let (rid_u, n) = read_varint(d, pos);
            pos += n;
            let rid = rid_u as i64;
            let psize = psize as usize;
            let mut payload = Vec::with_capacity(psize);
            if psize <= max_local {
                payload.extend_from_slice(&d[pos..pos + psize]);
            } else {
                let local = max_local - 4;
                payload.extend_from_slice(&d[pos..pos + local]);
                pos += local;
                let mut ov = read_be_u32(d, pos) as usize;
                while ov != 0 {
                    let ob = (ov - 1) * ps;
                    let next = read_be_u32(d, ob) as usize;
                    let avail = usable - 4;
                    let rem = psize - payload.len();
                    let tr = avail.min(rem);
                    payload.extend_from_slice(&d[ob + 4..ob + 4 + tr]);
                    ov = next;
                }
            }
            rows.push((rid, payload));
        }
    }
}

fn parse_record(payload: &[u8], ncols: usize) -> Vec<Value> {
    if payload.is_empty() {
        return vec![Value::Null; ncols];
    }
    let mut pos = 0;
    let (hs, n) = read_varint(payload, pos);
    let hs = hs as usize;
    pos += n;
    let mut sts = Vec::new();
    while pos < hs {
        let (st, n) = read_varint(payload, pos);
        pos += n;
        sts.push(st);
    }
    let mut bp = hs;
    let mut vals = Vec::new();
    for &st in &sts {
        let (v, np) = read_value(payload, bp, st);
        vals.push(v);
        bp = np;
    }
    while vals.len() < ncols {
        vals.push(Value::Null);
    }
    vals
}

fn read_value(d: &[u8], p: usize, st: u64) -> (Value, usize) {
    match st {
        0 => (Value::Null, p),
        1 => (Value::Integer(d[p] as i8 as i64), p + 1),
        2 => (Value::Integer(read_be_i16(d, p) as i64), p + 2),
        3 => {
            let mut b = [0u8; 8];
            if d[p] & 0x80 != 0 {
                b[0] = 0xff;
                b[1] = 0xff;
            }
            b[5..8].copy_from_slice(&d[p..p + 3]);
            (Value::Integer(i64::from_be_bytes(b)), p + 3)
        }
        4 => (Value::Integer(read_be_i32(d, p) as i64), p + 4),
        5 => {
            let mut b = [0u8; 8];
            if d[p] & 0x80 != 0 {
                b[0] = 0xff;
                b[1] = 0xff;
            }
            b[2..8].copy_from_slice(&d[p..p + 6]);
            (Value::Integer(i64::from_be_bytes(b)), p + 6)
        }
        6 => (Value::Integer(read_be_i64(d, p)), p + 8),
        7 => (Value::Real(read_be_f64(d, p)), p + 8),
        8 => (Value::Integer(0), p),
        9 => (Value::Integer(1), p),
        n if n >= 12 && n % 2 == 0 => {
            let len = ((n - 12) / 2) as usize;
            (Value::Blob(d[p..p + len].to_vec()), p + len)
        }
        n if n >= 13 => {
            let len = ((n - 13) / 2) as usize;
            (Value::Text(d[p..p + len].to_vec()), p + len)
        }
        _ => (Value::Null, p),
    }
}

fn crc32(data: &[u8]) -> u32 {
    let mut crc = 0xFFFFFFFFu32;
    for &b in data {
        crc ^= b as u32;
        for _ in 0..8 {
            if crc & 1 != 0 {
                crc = (crc >> 1) ^ 0xEDB88320;
            } else {
                crc >>= 1;
            }
        }
    }
    crc ^ 0xFFFFFFFF
}

fn format_real(v: f64) -> String {
    let mut s = format!("{:.8}", v);
    while s.ends_with('0') && !s.ends_with(".0") {
        s.pop();
    }
    s
}

fn format_text(bytes: &[u8]) -> String {
    let mut out: Vec<u8> = Vec::new();
    out.push(b'"');
    for &b in bytes {
        match b {
            b'\\' => out.extend_from_slice(b"\\\\"),
            b'"' => out.extend_from_slice(b"\\\""),
            b'\n' => out.extend_from_slice(b"\\n"),
            b'\r' => out.extend_from_slice(b"\\r"),
            b'\t' => out.extend_from_slice(b"\\t"),
            0x7F => out.extend_from_slice(b"\\x7F"),
            _ if b < 0x20 => {
                out.extend_from_slice(&format!("\\x{:02X}", b).into_bytes());
            }
            _ => out.push(b),
        }
    }
    out.push(b'"');
    String::from_utf8(out).unwrap()
}

fn format_value(v: &Value) -> String {
    match v {
        Value::Null => "NULL".to_string(),
        Value::Integer(n) => n.to_string(),
        Value::Real(f) => format_real(*f),
        Value::Text(b) => {
            if b.len() <= 100 {
                format_text(b)
            } else {
                format!("<TEXT len={} crc32={:08x}>", b.len(), crc32(b))
            }
        }
        Value::Blob(b) => {
            if b.len() <= 100 {
                format!(
                    "X'{}'",
                    b.iter().map(|x| format!("{:02X}", x)).collect::<String>()
                )
            } else {
                format!("<BLOB len={} crc32={:08x}>", b.len(), crc32(b))
            }
        }
    }
}

fn split_defs(s: &str) -> Vec<&str> {
    let mut result = Vec::new();
    let mut depth = 0i32;
    let mut start = 0;
    for (i, ch) in s.char_indices() {
        match ch {
            '(' => depth += 1,
            ')' => depth -= 1,
            ',' if depth == 0 => {
                result.push(&s[start..i]);
                start = i + 1;
            }
            _ => {}
        }
    }
    if start < s.len() {
        result.push(&s[start..]);
    }
    result
}

fn extract_col_name(def: &str) -> (String, &str) {
    let def = def.trim_start();
    let db = def.as_bytes();
    if db[0] == b'"' {
        let end = def[1..].find('"').unwrap() + 1;
        (def[1..end].to_string(), &def[end + 1..])
    } else {
        let mut end = 0;
        while end < db.len()
            && !db[end].is_ascii_whitespace()
            && db[end] != b'('
            && db[end] != b','
            && db[end] != b')'
        {
            end += 1;
        }
        (def[..end].to_string(), &def[end..])
    }
}

fn is_ipk(rest: &str) -> bool {
    let rest = rest.trim_start();
    let rb = rest.as_bytes();
    let mut end = 0;
    while end < rb.len() && (rb[end].is_ascii_alphanumeric() || rb[end] == b'_') {
        end += 1;
    }
    let tw = &rest[..end];
    if tw.to_uppercase() != "INTEGER" {
        return false;
    }
    let mut p = end;
    while p < rb.len() && (rb[p] as char).is_whitespace() {
        p += 1;
    }
    if p < rb.len() && rb[p] == b'(' {
        return false;
    }
    let upper = rest.to_uppercase();
    let words: Vec<&str> = upper.split_whitespace().collect();
    for i in 0..words.len().saturating_sub(1) {
        if words[i] == "PRIMARY" && words[i + 1] == "KEY" {
            return true;
        }
    }
    false
}

fn parse_create_table(sql: &str) -> (Vec<String>, Vec<usize>) {
    let sb = sql.as_bytes();
    let mut pos = 0;

    while pos < sb.len() && (sb[pos] as char).is_whitespace() {
        pos += 1;
    }
    while pos < sb.len() && !((sb[pos] as char).is_whitespace() || sb[pos] == b'(') {
        pos += 1;
    }
    while pos < sb.len() && (sb[pos] as char).is_whitespace() {
        pos += 1;
    }
    while pos < sb.len() && !((sb[pos] as char).is_whitespace() || sb[pos] == b'(') {
        pos += 1;
    }
    while pos < sb.len() && (sb[pos] as char).is_whitespace() {
        pos += 1;
    }

    if pos < sb.len() && sb[pos] == b'"' {
        pos += 1;
        while pos < sb.len() && sb[pos] != b'"' {
            pos += 1;
        }
        if pos < sb.len() {
            pos += 1;
        }
    } else {
        while pos < sb.len() && sb[pos] != b'(' && !((sb[pos] as char).is_whitespace()) {
            pos += 1;
        }
    }
    while pos < sb.len() && (sb[pos] as char).is_whitespace() {
        pos += 1;
    }

    if pos >= sb.len() || sb[pos] != b'(' {
        return (vec![], vec![]);
    }
    pos += 1;
    let cs = pos;
    let mut depth = 1i32;
    while pos < sb.len() && depth > 0 {
        match sb[pos] {
            b'(' => depth += 1,
            b')' => depth -= 1,
            _ => {}
        }
        if depth > 0 {
            pos += 1;
        }
    }
    let content = &sql[cs..pos];
    let defs = split_defs(content);
    let mut names = Vec::new();
    let mut ipks = Vec::new();

    for (i, def) in defs.iter().enumerate() {
        let def = def.trim();
        if def.is_empty() {
            continue;
        }
        let (name, rest) = extract_col_name(def);
        names.push(name);
        if is_ipk(rest) {
            ipks.push(i);
        }
    }
    (names, ipks)
}

fn main() {
    let args: Vec<String> = env::args().collect();
    let dir = &args[1];
    let path = format!("{}/db.sqlite", dir);
    let data = fs::read(&path).unwrap();

    let ps_raw = u16::from_be_bytes([data[16], data[17]]) as usize;
    let ps = if ps_raw == 1 { 65536 } else { ps_raw };
    let res = data[18] as usize;

    let mut schema_rows = Vec::new();
    walk_btree(&data, 1, ps, res, &mut schema_rows);

    let mut tables: Vec<(String, usize, String)> = Vec::new();
    for (_, payload) in &schema_rows {
        let vals = parse_record(payload, 5);
        if vals.len() < 5 {
            continue;
        }
        if let (Value::Text(t), Value::Text(nm), Value::Integer(rp), Value::Text(sq)) =
            (&vals[0], &vals[1], &vals[3], &vals[4])
        {
            let ts = String::from_utf8_lossy(t);
            let ns = String::from_utf8_lossy(nm);
            if ts == "table" && !ns.starts_with("sqlite_") {
                let sqs = String::from_utf8_lossy(sq).to_string();
                tables.push((ns.to_string(), *rp as usize, sqs));
            }
        }
    }

    tables.sort_by(|a, b| a.0.cmp(&b.0));

    for (i, (name, rootpage, sql)) in tables.iter().enumerate() {
        if i > 0 {
            println!();
        }

        let (col_names, ipk_cols) = parse_create_table(sql);
        let ncols = col_names.len();

        let mut rows = Vec::new();
        if *rootpage != 0 {
            walk_btree(&data, *rootpage, ps, res, &mut rows);
        }

        println!("TABLE {} rows={}", name, rows.len());
        println!("COLUMNS {}", col_names.join(", "));

        for (rid, payload) in &rows {
            let mut vals = parse_record(payload, ncols);
            for &ic in &ipk_cols {
                if ic < vals.len() {
                    vals[ic] = Value::Integer(*rid);
                }
            }
            let fmt: Vec<String> = vals.iter().map(|v| format_value(v)).collect();
            println!("{}: {}", rid, fmt.join(", "));
        }
    }
}

use std::env;
use std::fs;

#[derive(Clone)]
enum Value {
    Null,
    Integer(i64),
    Real(f64),
    Text(Vec<u8>),
    Blob(Vec<u8>),
}

fn read_be_u16(d: &[u8], o: usize) -> u16 {
    u16::from_be_bytes([d[o], d[o + 1]])
}

fn read_be_u32(d: &[u8], o: usize) -> u32 {
    u32::from_be_bytes([d[o], d[o + 1], d[o + 2], d[o + 3]])
}

fn read_be_i16(d: &[u8], o: usize) -> i16 {
    i16::from_be_bytes([d[o], d[o + 1]])
}

fn read_be_i32(d: &[u8], o: usize) -> i32 {
    i32::from_be_bytes([d[o], d[o + 1], d[o + 2], d[o + 3]])
}

fn read_be_i64(d: &[u8], o: usize) -> i64 {
    i64::from_be_bytes(d[o..o + 8].try_into().unwrap())
}

fn read_be_f64(d: &[u8], o: usize) -> f64 {
    f64::from_be_bytes(d[o..o + 8].try_into().unwrap())
}

fn read_varint(d: &[u8], o: usize) -> (u64, usize) {
    let mut r: u64 = 0;
    let mut i = 0;
    loop {
        let b = d[o + i];
        if i == 8 {
            r = (r << 8) | (b as u64);
            i += 1;
            break;
        }
        r = (r << 7) | ((b & 0x7f) as u64);
        i += 1;
        if b & 0x80 == 0 {
            break;
        }
    }
    (r, i)
}

fn walk_btree(d: &[u8], pg: usize, ps: usize, res: usize, rows: &mut Vec<(i64, Vec<u8>)>) {
    if pg == 0 {
        return;
    }
    let base = (pg - 1) * ps;
    let h = if pg == 1 { 100 } else { 0 };
    let pt = d[base + h];
    let nc = read_be_u16(d, base + h + 3) as usize;

    if pt == 5 {
        // Interior table b-tree page
        for i in 0..nc {
            let co = read_be_u16(d, base + h + 12 + i * 2) as usize;
            let child = read_be_u32(d, base + co) as usize;
            walk_btree(d, child, ps, res, rows);
        }
        let rm = read_be_u32(d, base + h + 8) as usize;
        walk_btree(d, rm, ps, res, rows);
    } else if pt == 13 {
        // Leaf table b-tree page
        let usable = ps - res;
        let max_local = usable - 35;
        let min_local = ((usable - 12) * 32 / 255) - 23;
        for i in 0..nc {
            let co = read_be_u16(d, base + h + 8 + i * 2) as usize;
            let mut pos = base + co;
            let (psize, n) = read_varint(d, pos);
            pos += n;
            let (rid_u, n) = read_varint(d, pos);
            pos += n;
            let rid = rid_u as i64;
            let psize = psize as usize;
            let mut payload = Vec::with_capacity(psize);
            if psize <= max_local {
                payload.extend_from_slice(&d[pos..pos + psize]);
            } else {
                let k = min_local + ((psize - min_local) % (usable - 4));
                let local = if k <= max_local { k } else { min_local };
                payload.extend_from_slice(&d[pos..pos + local]);
                pos += local;
                let mut ov = read_be_u32(d, pos) as usize;
                while ov != 0 {
                    let ob = (ov - 1) * ps;
                    let next = read_be_u32(d, ob) as usize;
                    let avail = usable - 4;
                    let rem = psize - payload.len();
                    let tr = avail.min(rem);
                    payload.extend_from_slice(&d[ob + 4..ob + 4 + tr]);
                    ov = next;
                }
            }
            rows.push((rid, payload));
        }
    }
}

fn parse_record(payload: &[u8], ncols: usize) -> Vec<Value> {
    if payload.is_empty() {
        return vec![Value::Null; ncols];
    }
    let mut pos = 0;
    let (hs, n) = read_varint(payload, pos);
    let hs = hs as usize;
    pos += n;
    let mut sts = Vec::new();
    while pos < hs {
        let (st, n) = read_varint(payload, pos);
        pos += n;
        sts.push(st);
    }
    let mut bp = hs;
    let mut vals = Vec::new();
    for &st in &sts {
        let (v, np) = read_value(payload, bp, st);
        vals.push(v);
        bp = np;
    }
    while vals.len() < ncols {
        vals.push(Value::Null);
    }
    vals
}

fn read_value(d: &[u8], p: usize, st: u64) -> (Value, usize) {
    match st {
        0 => (Value::Null, p),
        1 => (Value::Integer(d[p] as i8 as i64), p + 1),
        2 => (Value::Integer(read_be_i16(d, p) as i64), p + 2),
        3 => {
            let mut b = [0u8; 8];
            if d[p] & 0x80 != 0 {
                b[0] = 0xff;
                b[1] = 0xff;
            }
            b[5..8].copy_from_slice(&d[p..p + 3]);
            (Value::Integer(i64::from_be_bytes(b)), p + 3)
        }
        4 => (Value::Integer(read_be_i32(d, p) as i64), p + 4),
        5 => {
            let mut b = [0u8; 8];
            if d[p] & 0x80 != 0 {
                b[0] = 0xff;
                b[1] = 0xff;
            }
            b[2..8].copy_from_slice(&d[p..p + 6]);
            (Value::Integer(i64::from_be_bytes(b)), p + 6)
        }
        6 => (Value::Integer(read_be_i64(d, p)), p + 8),
        7 => (Value::Real(read_be_f64(d, p)), p + 8),
        8 => (Value::Integer(0), p),
        9 => (Value::Integer(1), p),
        n if n >= 12 && n % 2 == 0 => {
            let len = ((n - 12) / 2) as usize;
            (Value::Blob(d[p..p + len].to_vec()), p + len)
        }
        n if n >= 13 => {
            let len = ((n - 13) / 2) as usize;
            (Value::Text(d[p..p + len].to_vec()), p + len)
        }
        _ => (Value::Null, p),
    }
}

fn crc32(data: &[u8]) -> u32 {
    let mut crc = 0xFFFFFFFFu32;
    for &b in data {
        crc ^= b as u32;
        for _ in 0..8 {
            if crc & 1 != 0 {
                crc = (crc >> 1) ^ 0xEDB88320;
            } else {
                crc >>= 1;
            }
        }
    }
    crc ^ 0xFFFFFFFF
}

fn format_real(v: f64) -> String {
    let mut s = format!("{:.8}", v);
    while s.ends_with('0') && !s.ends_with(".0") {
        s.pop();
    }
    s
}

fn format_text(bytes: &[u8]) -> String {
    let mut out: Vec<u8> = Vec::new();
    out.push(b'"');
    for &b in bytes {
        match b {
            b'\\' => out.extend_from_slice(b"\\\\"),
            b'"' => out.extend_from_slice(b"\\\""),
            b'\n' => out.extend_from_slice(b"\\n"),
            b'\r' => out.extend_from_slice(b"\\r"),
            b'\t' => out.extend_from_slice(b"\\t"),
            0x7F => out.extend_from_slice(b"\\x7F"),
            _ if b < 0x20 => {
                out.extend_from_slice(&format!("\\x{:02X}", b).into_bytes());
            }
            _ => out.push(b),
        }
    }
    out.push(b'"');
    String::from_utf8(out).unwrap()
}

fn format_value(v: &Value) -> String {
    match v {
        Value::Null => "NULL".to_string(),
        Value::Integer(n) => n.to_string(),
        Value::Real(f) => format_real(*f),
        Value::Text(b) => {
            if b.len() <= 100 {
                format_text(b)
            } else {
                format!("<TEXT len={} crc32={:08x}>", b.len(), crc32(b))
            }
        }
        Value::Blob(b) => {
            if b.len() <= 100 {
                format!(
                    "X'{}'",
                    b.iter().map(|x| format!("{:02X}", x)).collect::<String>()
                )
            } else {
                format!("<BLOB len={} crc32={:08x}>", b.len(), crc32(b))
            }
        }
    }
}

fn split_defs(s: &str) -> Vec<&str> {
    let mut result = Vec::new();
    let mut depth = 0i32;
    let mut start = 0;
    for (i, ch) in s.char_indices() {
        match ch {
            '(' => depth += 1,
            ')' => depth -= 1,
            ',' if depth == 0 => {
                result.push(&s[start..i]);
                start = i + 1;
            }
            _ => {}
        }
    }
    if start < s.len() {
        result.push(&s[start..]);
    }
    result
}

fn extract_col_name(def: &str) -> (String, &str) {
    let def = def.trim_start();
    let db = def.as_bytes();
    if db.is_empty() {
        return (String::new(), def);
    }
    if db[0] == b'"' {
        let end = def[1..].find('"').unwrap() + 1;
        (def[1..end].to_string(), &def[end + 1..])
    } else {
        let mut end = 0;
        while end < db.len()
            && !db[end].is_ascii_whitespace()
            && db[end] != b'('
            && db[end] != b','
            && db[end] != b')'
        {
            end += 1;
        }
        (def[..end].to_string(), &def[end..])
    }
}

fn is_ipk(rest: &str) -> bool {
    let rest = rest.trim_start();
    let rb = rest.as_bytes();
    let mut end = 0;
    while end < rb.len() && (rb[end].is_ascii_alphanumeric() || rb[end] == b'_') {
        end += 1;
    }
    let tw = &rest[..end];
    if tw.to_uppercase() != "INTEGER" {
        return false;
    }
    let mut p = end;
    while p < rb.len() && (rb[p] as char).is_whitespace() {
        p += 1;
    }
    if p < rb.len() && rb[p] == b'(' {
        return false;
    }
    let upper = rest.to_uppercase();
    let words: Vec<&str> = upper.split_whitespace().collect();
    for i in 0..words.len().saturating_sub(1) {
        if words[i] == "PRIMARY" && words[i + 1] == "KEY" {
            return true;
        }
    }
    false
}

fn parse_create_table(sql: &str) -> (Vec<String>, Vec<usize>) {
    let sb = sql.as_bytes();
    let mut pos = 0;

    // Skip "CREATE"
    while pos < sb.len() && (sb[pos] as char).is_whitespace() {
        pos += 1;
    }
    while pos < sb.len() && !((sb[pos] as char).is_whitespace() || sb[pos] == b'(') {
        pos += 1;
    }
    // Skip "TABLE"
    while pos < sb.len() && (sb[pos] as char).is_whitespace() {
        pos += 1;
    }
    while pos < sb.len() && !((sb[pos] as char).is_whitespace() || sb[pos] == b'(') {
        pos += 1;
    }
    // Skip whitespace before table name
    while pos < sb.len() && (sb[pos] as char).is_whitespace() {
        pos += 1;
    }

    // Skip table name (possibly quoted)
    if pos < sb.len() && sb[pos] == b'"' {
        pos += 1;
        while pos < sb.len() && sb[pos] != b'"' {
            pos += 1;
        }
        if pos < sb.len() {
            pos += 1;
        }
    } else {
        while pos < sb.len() && sb[pos] != b'(' && !((sb[pos] as char).is_whitespace()) {
            pos += 1;
        }
    }
    // Skip whitespace before opening paren
    while pos < sb.len() && (sb[pos] as char).is_whitespace() {
        pos += 1;
    }

    if pos >= sb.len() || sb[pos] != b'(' {
        return (vec![], vec![]);
    }
    pos += 1;
    let cs = pos;
    let mut depth = 1i32;
    while pos < sb.len() && depth > 0 {
        match sb[pos] {
            b'(' => depth += 1,
            b')' => depth -= 1,
            _ => {}
        }
        if depth > 0 {
            pos += 1;
        }
    }
    let content = &sql[cs..pos];
    let defs = split_defs(content);
    let mut names = Vec::new();
    let mut ipks = Vec::new();

    for (i, def) in defs.iter().enumerate() {
        let def = def.trim();
        if def.is_empty() {
            continue;
        }
        let (name, rest) = extract_col_name(def);
        names.push(name);
        if is_ipk(rest) {
            ipks.push(i);
        }
    }
    (names, ipks)
}

