import Foundation

// MARK: - Output escaping

func escapeString(_ s: String) -> String {
    var r = ""
    for u in s.unicodeScalars {
        switch u {
        case "\\": r += "\\\\"
        case "\n": r += "\\n"
        case "\r": r += "\\r"
        case "\t": r += "\\t"
        default: r.unicodeScalars.append(u)
        }
    }
    return r
}

// MARK: - HTTP

func makeRequest(baseUrl: String, body: Data, apiKey: String) -> (Int, Data) {
    let url = URL(string: "\(baseUrl)/v1/messages")!
    var req = URLRequest(url: url)
    req.httpMethod = "POST"
    req.setValue(apiKey, forHTTPHeaderField: "x-api-key")
    req.setValue("2023-06-01", forHTTPHeaderField: "anthropic-version")
    req.setValue("application/json", forHTTPHeaderField: "content-type")
    req.httpBody = body
    let cfg = URLSessionConfiguration.default
    cfg.timeoutIntervalForRequest = 300
    cfg.timeoutIntervalForResource = 300
    let session = URLSession(configuration: cfg)
    let sem = DispatchSemaphore(value: 0)
    var out: (Int, Data)?
    session.dataTask(with: req) { d, r, e in
        guard let r = r as? HTTPURLResponse, let d = d else {
            FileHandle.standardError.write("HTTP error: \(e?.localizedDescription ?? "?")\n".data(using: .utf8)!)
            exit(1)
        }
        out = (r.statusCode, d)
        sem.signal()
    }.resume()
    sem.wait()
    return out!
}

// MARK: - SSE parsing

func parseSSE(_ data: Data) -> [(String, String)] {
    guard let text = String(data: data, encoding: .utf8) else { return [] }
    var events: [(String, String)] = []
    var evType = ""
    var dataLines: [String] = []
    for var line in text.components(separatedBy: "\n") {
        if line.hasSuffix("\r") { line = String(line.dropLast()) }
        if line.isEmpty {
            if !dataLines.isEmpty {
                events.append((evType, dataLines.joined(separator: "\n")))
            }
            evType = ""
            dataLines = []
        } else if line.hasPrefix(":") {
            // comment – skip
        } else if line.hasPrefix("event:") {
            var v = String(line.dropFirst(6))
            if v.hasPrefix(" ") { v = String(v.dropFirst()) }
            evType = v
        } else if line.hasPrefix("data:") {
            var v = String(line.dropFirst(5))
            if v.hasPrefix(" ") { v = String(v.dropFirst()) }
            dataLines.append(v)
        }
    }
    if !dataLines.isEmpty {
        events.append((evType, dataLines.joined(separator: "\n")))
    }
    return events
}

// MARK: - Content-block model

struct Block {
    var type = ""
    var thinking = ""
    var signature = ""
    var text = ""
    var toolId = ""
    var toolName = ""
    var rawInput = ""
}

struct Reply {
    var blocks: [Block] = []
    var stopReason = ""
    var inputTokens = 0
    var outputTokens = 0
    var cacheRead = 0
}

func processReply(_ data: Data) -> Reply {
    let events = parseSSE(data)
    var blocks: [Int: Block] = [:]
    var order: [Int] = []
    var reply = Reply()

    for (evType, evData) in events {
        guard let jd = evData.data(using: .utf8),
              let j = try? JSONSerialization.jsonObject(with: jd) as? [String: Any] else { continue }

        switch evType {
        case "message_start":
            if let msg = j["message"] as? [String: Any],
               let u = msg["usage"] as? [String: Any] {
                reply.inputTokens = u["input_tokens"] as? Int ?? 0
                reply.cacheRead = u["cache_read_input_tokens"] as? Int ?? 0
            }

        case "content_block_start":
            let idx = j["index"] as? Int ?? 0
            if let cb = j["content_block"] as? [String: Any] {
                var b = Block()
                b.type = cb["type"] as? String ?? ""
                if b.type == "thinking" {
                    b.thinking = cb["thinking"] as? String ?? ""
                    b.signature = cb["signature"] as? String ?? ""
                } else if b.type == "text" {
                    b.text = cb["text"] as? String ?? ""
                } else if b.type == "tool_use" {
                    b.toolId = cb["id"] as? String ?? ""
                    b.toolName = cb["name"] as? String ?? ""
                }
                blocks[idx] = b
                order.append(idx)
            }

        case "content_block_delta":
            let idx = j["index"] as? Int ?? 0
            guard var b = blocks[idx], let d = j["delta"] as? [String: Any] else { continue }
            switch d["type"] as? String ?? "" {
            case "thinking_delta":
                b.thinking += d["thinking"] as? String ?? ""
            case "signature_delta":
                b.signature += d["signature"] as? String ?? ""
            case "text_delta":
                b.text += d["text"] as? String ?? ""
            case "input_json_delta":
                b.rawInput += d["partial_json"] as? String ?? ""
            default: break
            }
            blocks[idx] = b

        case "message_delta":
            if let d = j["delta"] as? [String: Any] {
                reply.stopReason = d["stop_reason"] as? String ?? ""
            }
            if let u = j["usage"] as? [String: Any] {
                reply.outputTokens = u["output_tokens"] as? Int ?? 0
            }

        default: break
        }
    }

    order.sort()
    reply.blocks = order.compactMap { blocks[$0] }
    return reply
}

// MARK: - Tools

func runTool(name: String, input: [String: Any]) -> (String, Bool) {
    switch name {
    case "measure":
        let text = input["text"] as? String ?? ""
        let unit = input["unit"] as? String ?? ""
        switch unit {
        case "code_points":  return (String(text.unicodeScalars.count), false)
        case "utf8_bytes":   return (String(text.utf8.count), false)
        case "utf16_units":  return (String(text.utf16.count), false)
        default:             return ("unsupported unit: \(unit)", true)
        }
    case "reverse":
        let text = input["text"] as? String ?? ""
        var view = String.UnicodeScalarView()
        view.append(contentsOf: text.unicodeScalars.reversed())
        return (String(view), false)
    default:
        return ("unknown tool: \(name)", true)
    }
}

// MARK: - Printing helpers

func printBlocks(_ reply: Reply) {
    for b in reply.blocks {
        switch b.type {
        case "thinking":
            print("thinking \(escapeString(b.thinking))")
            print("signature \(escapeString(b.signature))")
        case "text":
            print("text \(escapeString(b.text))")
        case "tool_use":
            print("tool_use \(escapeString(b.toolId)) \(escapeString(b.toolName)) \(escapeString(b.rawInput))")
        default: break
        }
    }
    print("stop_reason \(reply.stopReason)")
}

func printError(_ status: Int, _ body: Data) {
    if let j = try? JSONSerialization.jsonObject(with: body) as? [String: Any],
       let e = j["error"] as? [String: Any] {
        print("ERROR \(status) \(e["type"] as? String ?? "unknown"): \(e["message"] as? String ?? "")")
    } else {
        print("ERROR \(status) unknown: unknown")
    }
}

