import java.io.*;
import java.net.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;

public class Main {

    // ===== JSON Parser =====
    private static int jp;
    private static String js;

    static Object parseJson(String s) {
        js = s; jp = 0;
        return parseVal();
    }

    static void skipWs() {
        while (jp < js.length() && " \t\n\r".indexOf(js.charAt(jp)) >= 0) jp++;
    }

    static Object parseVal() {
        skipWs();
        char c = js.charAt(jp);
        if (c == '"') return parseStr();
        if (c == '{') return parseObj();
        if (c == '[') return parseArr();
        if (c == 't') { jp += 4; return Boolean.TRUE; }
        if (c == 'f') { jp += 5; return Boolean.FALSE; }
        if (c == 'n') { jp += 4; return null; }
        return parseNum();
    }

    static String parseStr() {
        jp++;
        StringBuilder sb = new StringBuilder();
        while (js.charAt(jp) != '"') {
            char c = js.charAt(jp);
            if (c == '\\') {
                jp++;
                char e = js.charAt(jp);
                switch (e) {
                    case '"': sb.append('"'); break;
                    case '\\': sb.append('\\'); break;
                    case '/': sb.append('/'); break;
                    case 'b': sb.append('\b'); break;
                    case 'f': sb.append('\f'); break;
                    case 'n': sb.append('\n'); break;
                    case 'r': sb.append('\r'); break;
                    case 't': sb.append('\t'); break;
                    case 'u': {
                        int cp = Integer.parseInt(js.substring(jp + 1, jp + 5), 16);
                        jp += 4;
                        if (Character.isHighSurrogate((char) cp) && jp + 1 < js.length()
                                && js.charAt(jp + 1) == '\\' && js.charAt(jp + 2) == 'u') {
                            int lo = Integer.parseInt(js.substring(jp + 3, jp + 7), 16);
                            jp += 6;
                            sb.appendCodePoint(Character.toCodePoint((char) cp, (char) lo));
                        } else {
                            sb.append((char) cp);
                        }
                        break;
                    }
                }
            } else {
                sb.append(c);
            }
            jp++;
        }
        jp++;
        return sb.toString();
    }

    @SuppressWarnings("unchecked")
    static Map<String, Object> parseObj() {
        jp++;
        Map<String, Object> m = new LinkedHashMap<>();
        skipWs();
        if (js.charAt(jp) == '}') { jp++; return m; }
        while (true) {
            skipWs();
            String k = parseStr();
            skipWs();
            jp++;
            m.put(k, parseVal());
            skipWs();
            if (js.charAt(jp) == '}') { jp++; return m; }
            jp++;
        }
    }

    static List<Object> parseArr() {
        jp++;
        List<Object> a = new ArrayList<>();
        skipWs();
        if (js.charAt(jp) == ']') { jp++; return a; }
        while (true) {
            a.add(parseVal());
            skipWs();
            if (js.charAt(jp) == ']') { jp++; return a; }
            jp++;
        }
    }

    static Object parseNum() {
        int start = jp;
        if (js.charAt(jp) == '-') jp++;
        while (jp < js.length() && Character.isDigit(js.charAt(jp))) jp++;
        boolean isFloat = false;
        if (jp < js.length() && js.charAt(jp) == '.') {
            isFloat = true; jp++;
            while (jp < js.length() && Character.isDigit(js.charAt(jp))) jp++;
        }
        if (jp < js.length() && (js.charAt(jp) == 'e' || js.charAt(jp) == 'E')) {
            isFloat = true; jp++;
            if (jp < js.length() && (js.charAt(jp) == '+' || js.charAt(jp) == '-')) jp++;
            while (jp < js.length() && Character.isDigit(js.charAt(jp))) jp++;
        }
        String s = js.substring(start, jp);
        if (isFloat) return Double.parseDouble(s);
        return Long.parseLong(s);
    }

    // ===== JSON Serializer =====
    @SuppressWarnings("unchecked")
    static String toJson(Object v) {
        if (v == null) return "null";
        if (v instanceof String) return jsonQ((String) v);
        if (v instanceof Long) return v.toString();
        if (v instanceof Integer) return v.toString();
        if (v instanceof Double) {
            double d = (Double) v;
            if (d == Math.floor(d) && !Double.isInfinite(d)) return Long.toString((long) d);
            return v.toString();
        }
        if (v instanceof Boolean) return v.toString();
        if (v instanceof Map) {
            StringBuilder sb = new StringBuilder("{");
            boolean first = true;
            for (Map.Entry<String, Object> e : ((Map<String, Object>) v).entrySet()) {
                if (!first) sb.append(',');
                first = false;
                sb.append(jsonQ(e.getKey())).append(':').append(toJson(e.getValue()));
            }
            return sb.append('}').toString();
        }
        if (v instanceof List) {
            StringBuilder sb = new StringBuilder("[");
            boolean first = true;
            for (Object item : (List<Object>) v) {
                if (!first) sb.append(',');
                first = false;
                sb.append(toJson(item));
            }
            return sb.append(']').toString();
        }
        throw new RuntimeException("Cannot serialize: " + v.getClass());
    }

    static String jsonQ(String s) {
        StringBuilder sb = new StringBuilder("\"");
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            switch (c) {
                case '"': sb.append("\\\""); break;
                case '\\': sb.append("\\\\"); break;
                case '\n': sb.append("\\n"); break;
                case '\r': sb.append("\\r"); break;
                case '\t': sb.append("\\t"); break;
                case '\b': sb.append("\\b"); break;
                case '\f': sb.append("\\f"); break;
                default:
                    if (c < 0x20) sb.append(String.format("\\u%04x", (int) c));
                    else sb.append(c);
            }
        }
        return sb.append('"').toString();
    }

    // ===== Display escaping =====
    static String esc(String s) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            switch (c) {
                case '\\': sb.append("\\\\"); break;
                case '\n': sb.append("\\n"); break;
                case '\r': sb.append("\\r"); break;
                case '\t': sb.append("\\t"); break;
                default: sb.append(c);
            }
        }
        return sb.toString();
    }

    // ===== HTTP =====
    static int readLine(InputStream is, StringBuilder sb) throws IOException {
        sb.setLength(0);
        int c;
        while ((c = is.read()) != -1) {
            if (c == '\n') return sb.length();
            if (c == '\r') {
                is.mark(1);
                int n = is.read();
                if (n != '\n') is.reset();
                return sb.length();
            }
            sb.append((char) c);
        }
        return sb.length();
    }

    static byte[] readAll(InputStream is) throws IOException {
        ByteArrayOutputStream baos = new ByteArrayOutputStream();
        byte[] buf = new byte[8192];
        int n;
        while ((n = is.read(buf)) != -1) baos.write(buf, 0, n);
        return baos.toByteArray();
    }

    static byte[] readChunked(InputStream is) throws IOException {
        ByteArrayOutputStream out = new ByteArrayOutputStream();
        StringBuilder sb = new StringBuilder();
        while (true) {
            readLine(is, sb);
            String line = sb.toString().trim();
            int semi = line.indexOf(';');
            if (semi >= 0) line = line.substring(0, semi);
            int sz = Integer.parseInt(line, 16);
            if (sz == 0) {
                while (readLine(is, sb) > 0) { }
                break;
            }
            byte[] buf = new byte[sz];
            int off = 0;
            while (off < sz) {
                int r = is.read(buf, off, sz - off);
                if (r == -1) throw new IOException("EOF in chunk");
                off += r;
            }
            out.write(buf, 0, sz);
            readLine(is, sb);
        }
        return out.toByteArray();
    }

    static class Resp {
        int status;
        byte[] body;
        Resp(int s, byte[] b) { status = s; body = b; }
    }

    static Resp sendReq(String baseUrl, String apiKey, String body) throws Exception {
        URL url = new URL(baseUrl + "/v1/messages");
        String host = url.getHost();
        int port = url.getPort() == -1 ? 80 : url.getPort();
        String path = url.getPath();
        if (url.getQuery() != null) path += "?" + url.getQuery();

        Socket sock = new Socket();
        sock.connect(new InetSocketAddress(host, port), 30000);
        sock.setSoTimeout(120000);
        OutputStream os = sock.getOutputStream();

        byte[] bodyBytes = body.getBytes(StandardCharsets.UTF_8);
        String hdr = "POST " + path + " HTTP/1.1\r\n"
                + "Host: " + host + (port != 80 ? ":" + port : "") + "\r\n"
                + "Content-Length: " + bodyBytes.length + "\r\n"
                + "x-api-key: " + apiKey + "\r\n"
                + "anthropic-version: 2023-06-01\r\n"
                + "content-type: application/json\r\n"
                + "\r\n";
        os.write(hdr.getBytes(StandardCharsets.US_ASCII));
        os.write(bodyBytes);
        os.flush();

        InputStream is = new BufferedInputStream(sock.getInputStream());
        StringBuilder sb = new StringBuilder();
        readLine(is, sb);
        String statusLine = sb.toString();
        int status = Integer.parseInt(statusLine.split(" ")[1]);

        Map<String, String> headers = new HashMap<>();
        while (readLine(is, sb) > 0) {
            int c = sb.indexOf(":");
            if (c >= 0) {
                headers.put(sb.substring(0, c).toLowerCase().trim(), sb.substring(c + 1).trim());
            }
        }

        byte[] respBody;
        String te = headers.get("transfer-encoding");
        if (te != null && te.toLowerCase().contains("chunked")) {
            respBody = readChunked(is);
        } else {
            String cl = headers.get("content-length");
            if (cl != null) {
                int len = Integer.parseInt(cl);
                respBody = new byte[len];
                int off = 0;
                while (off < len) {
                    int r = is.read(respBody, off, len - off);
                    if (r == -1) break;
                    off += r;
                }
            } else {
                respBody = readAll(is);
            }
        }
        sock.close();
        return new Resp(status, respBody);
    }

    // ===== SSE Parsing =====
    static class SSEEvent {
        String type, data;
        SSEEvent(String t, String d) { type = t; data = d; }
    }

    static List<SSEEvent> parseSSE(byte[] body) {
        String text = new String(body, StandardCharsets.UTF_8);
        List<SSEEvent> events = new ArrayList<>();
        String eventType = "";
        StringBuilder dataBuf = new StringBuilder();
        boolean hasData = false;

        String[] lines = text.split("\r?\n", -1);
        for (String line : lines) {
            if (line.isEmpty()) {
                if (hasData) {
                    events.add(new SSEEvent(eventType, dataBuf.toString()));
                }
                eventType = "";
                dataBuf = new StringBuilder();
                hasData = false;
            } else if (line.charAt(0) == ':') {
                // comment
            } else {
                int colon = line.indexOf(':');
                String field, value;
                if (colon >= 0) {
                    field = line.substring(0, colon);
                    value = line.substring(colon + 1);
                    if (value.startsWith(" ")) value = value.substring(1);
                } else {
                    field = line;
                    value = "";
                }
                if (field.equals("event")) {
                    eventType = value;
                } else if (field.equals("data")) {
                    if (hasData) dataBuf.append('\n');
                    dataBuf.append(value);
                    hasData = true;
                }
            }
        }
        if (hasData) {
            events.add(new SSEEvent(eventType, dataBuf.toString()));
        }
        return events;
    }

    // ===== Content Block =====
    static class Block {
        String type;
        String thinking = "";
        String signature = "";
        String text = "";
        String id;
        String name;
        StringBuilder inputJson = new StringBuilder();
    }

    // ===== Parsed Response =====
    static class ParsedResp {
        List<Block> blocks = new ArrayList<>();
        String stopReason = "";
        long inputTokens = 0;
        long outputTokens = 0;
        long cacheReadTokens = 0;
    }

    @SuppressWarnings("unchecked")
    static ParsedResp parseStream(byte[] body) {
        List<SSEEvent> events = parseSSE(body);
        ParsedResp pr = new ParsedResp();
        TreeMap<Integer, Block> blockMap = new TreeMap<>();

        for (SSEEvent ev : events) {
            Map<String, Object> data = (Map<String, Object>) parseJson(ev.data);
            String type = (String) data.get("type");
            if (type == null) continue;

            switch (type) {
                case "message_start": {
                    Map<String, Object> msg = (Map<String, Object>) data.get("message");
                    if (msg != null) {
                        Map<String, Object> usage = (Map<String, Object>) msg.get("usage");
                        if (usage != null) {
                            if (usage.containsKey("input_tokens"))
                                pr.inputTokens += ((Number) usage.get("input_tokens")).longValue();
                            if (usage.containsKey("cache_read_input_tokens"))
                                pr.cacheReadTokens += ((Number) usage.get("cache_read_input_tokens")).longValue();
                        }
                    }
                    break;
                }
                case "content_block_start": {
                    int idx = ((Number) data.get("index")).intValue();
                    Map<String, Object> cb = (Map<String, Object>) data.get("content_block");
                    Block b = new Block();
                    b.type = (String) cb.get("type");
                    if ("tool_use".equals(b.type)) {
                        b.id = (String) cb.get("id");
                        b.name = (String) cb.get("name");
                    }
                    blockMap.put(idx, b);
                    break;
                }
                case "content_block_delta": {
                    int idx = ((Number) data.get("index")).intValue();
                    Map<String, Object> delta = (Map<String, Object>) data.get("delta");
                    String dt = (String) delta.get("type");
                    Block b = blockMap.get(idx);
                    if (b == null) break;
                    if ("thinking_delta".equals(dt)) {
                        b.thinking += (String) delta.get("thinking");
                    } else if ("signature_delta".equals(dt)) {
                        b.signature += (String) delta.get("signature");
                    } else if ("text_delta".equals(dt)) {
                        b.text += (String) delta.get("text");
                    } else if ("input_json_delta".equals(dt)) {
                        b.inputJson.append((String) delta.get("partial_json"));
                    }
                    break;
                }
                case "content_block_stop": {
                    int idx = ((Number) data.get("index")).intValue();
                    Block b = blockMap.get(idx);
                    if (b != null) pr.blocks.add(b);
                    break;
                }
                case "message_delta": {
                    Map<String, Object> delta = (Map<String, Object>) data.get("delta");
                    if (delta != null && delta.containsKey("stop_reason"))
                        pr.stopReason = (String) delta.get("stop_reason");
                    Map<String, Object> usage = (Map<String, Object>) data.get("usage");
                    if (usage != null && usage.containsKey("output_tokens"))
                        pr.outputTokens += ((Number) usage.get("output_tokens")).longValue();
                    break;
                }
                case "message_stop":
                case "ping":
                default:
                    break;
            }
        }
        return pr;
    }

    // ===== Tool Execution =====
    static class ToolResult {
        String content;
        boolean isError;
        ToolResult(String c, boolean e) { content = c; isError = e; }
    }

    @SuppressWarnings("unchecked")
    static ToolResult executeTool(String name, Map<String, Object> input) {
        if ("measure".equals(name)) {
            String text = (String) input.get("text");
            String unit = (String) input.get("unit");
            if ("code_points".equals(unit)) {
                return new ToolResult(String.valueOf(text.codePointCount(0, text.length())), false);
            } else if ("utf8_bytes".equals(unit)) {
                return new ToolResult(String.valueOf(text.getBytes(StandardCharsets.UTF_8).length), false);
            } else if ("utf16_units".equals(unit)) {
                return new ToolResult(String.valueOf(text.length()), false);
            } else {
                return new ToolResult("unsupported unit: " + unit, true);
            }
        } else if ("reverse".equals(name)) {
            String text = (String) input.get("text");
            int[] cps = text.codePoints().toArray();
            StringBuilder sb = new StringBuilder();
            for (int i = cps.length - 1; i >= 0; i--) sb.appendCodePoint(cps[i]);
            return new ToolResult(sb.toString(), false);
        } else {
            return new ToolResult("unknown tool: " + name, true);
        }
    }

    // ===== Print output lines =====
    static void printOutput(List<String> lines) {
        for (String line : lines) {
            System.out.println(line);
        }
    }

    @SuppressWarnings("unchecked")
    static void printError(List<String> output, Resp r) {
        String body = new String(r.body, StandardCharsets.UTF_8);
        Map<String, Object> err = (Map<String, Object>) parseJson(body);
        Map<String, Object> error = (Map<String, Object>) err.get("error");
        String errType = (String) error.get("type");
        String errMsg = (String) error.get("message");
        printOutput(output);
        System.out.println("ERROR " + r.status + " " + errType + ": " + errMsg);
    }

    // ===== Main =====
    @SuppressWarnings("unchecked")
    public static void main(String[] args) throws Exception {
        String dataDir = args[0];
        String baseUrl = args[1];

        String reqJson = new String(
                Files.readAllBytes(new File(dataDir, "request.json").toPath()),
                StandardCharsets.UTF_8);
        Map<String, Object> config = (Map<String, Object>) parseJson(reqJson);

        String apiKey = (String) config.get("api_key");
        Object model = config.get("model");
        long maxTokens = ((Number) config.get("max_tokens")).longValue();
        long thinkingBudget = ((Number) config.get("thinking_budget")).longValue();
        Object system = config.get("system");
        Object prompt = config.get("prompt");
        Object tools = config.get("tools");

        List<String> output = new ArrayList<>();
        long totalIn = 0, totalOut = 0, totalCache = 0;

        // ===== Request 1 =====
        output.add("request 1");

        Map<String, Object> req1 = new LinkedHashMap<>();
        req1.put("model", model);
        req1.put("max_tokens", maxTokens);
        req1.put("stream", true);
        Map<String, Object> thinkCfg = new LinkedHashMap<>();
        thinkCfg.put("type", "enabled");
        thinkCfg.put("budget_tokens", thinkingBudget);
        req1.put("thinking", thinkCfg);
        req1.put("system", system);
        req1.put("tools", tools);
        List<Object> msgs1 = new ArrayList<>();
        Map<String, Object> um1 = new LinkedHashMap<>();
        um1.put("role", "user");
        um1.put("content", prompt);
        msgs1.add(um1);
        req1.put("messages", msgs1);

        Resp r1 = sendReq(baseUrl, apiKey, toJson(req1));
        if (r1.status != 200) {
            printError(output, r1);
            return;
        }

        ParsedResp p1 = parseStream(r1.body);
        for (Block b : p1.blocks) {
            if ("thinking".equals(b.type)) {
                output.add("thinking " + esc(b.thinking));
                output.add("signature " + esc(b.signature));
            } else if ("text".equals(b.type)) {
                output.add("text " + esc(b.text));
            } else if ("tool_use".equals(b.type)) {
                output.add("tool_use " + b.id + " " + b.name + " " + esc(b.inputJson.toString()));
            }
        }
        output.add("stop_reason " + p1.stopReason);
        totalIn += p1.inputTokens;
        totalOut += p1.outputTokens;
        totalCache += p1.cacheReadTokens;

        // Execute tools
        List<ToolResult> results = new ArrayList<>();
        for (Block b : p1.blocks) {
            if ("tool_use".equals(b.type)) {
                Map<String, Object> input = (Map<String, Object>) parseJson(b.inputJson.toString());
                ToolResult tr = executeTool(b.name, input);
                results.add(tr);
                if (tr.isError) {
                    output.add("error " + b.id + " " + esc(tr.content));
                } else {
                    output.add("result " + b.id + " " + esc(tr.content));
                }
            }
        }

        // ===== Request 2 =====
        output.add("request 2");

        // Build assistant message content
        List<Object> assistantContent = new ArrayList<>();
        for (Block b : p1.blocks) {
            Map<String, Object> block = new LinkedHashMap<>();
            if ("thinking".equals(b.type)) {
                block.put("type", "thinking");
                block.put("thinking", b.thinking);
                block.put("signature", b.signature);
            } else if ("text".equals(b.type)) {
                block.put("type", "text");
                block.put("text", b.text);
            } else if ("tool_use".equals(b.type)) {
                block.put("type", "tool_use");
                block.put("id", b.id);
                block.put("name", b.name);
                block.put("input", parseJson(b.inputJson.toString()));
            }
            assistantContent.add(block);
        }

        // Build tool results
        List<Object> toolResults = new ArrayList<>();
        int ri = 0;
        for (Block b : p1.blocks) {
            if ("tool_use".equals(b.type)) {
                Map<String, Object> tr = new LinkedHashMap<>();
                tr.put("type", "tool_result");
                tr.put("tool_use_id", b.id);
                tr.put("content", results.get(ri).content);
                if (results.get(ri).isError) tr.put("is_error", true);
                toolResults.add(tr);
                ri++;
            }
        }

        Map<String, Object> req2 = new LinkedHashMap<>();
        req2.put("model", model);
        req2.put("max_tokens", maxTokens);
        req2.put("stream", true);
        Map<String, Object> thinkCfg2 = new LinkedHashMap<>();
        thinkCfg2.put("type", "enabled");
        thinkCfg2.put("budget_tokens", thinkingBudget);
        req2.put("thinking", thinkCfg2);
        req2.put("system", system);
        req2.put("tools", tools);
        List<Object> msgs2 = new ArrayList<>();
        Map<String, Object> um2 = new LinkedHashMap<>();
        um2.put("role", "user");
        um2.put("content", prompt);
        msgs2.add(um2);
        Map<String, Object> am = new LinkedHashMap<>();
        am.put("role", "assistant");
        am.put("content", assistantContent);
        msgs2.add(am);
        Map<String, Object> um3 = new LinkedHashMap<>();
        um3.put("role", "user");
        um3.put("content", toolResults);
        msgs2.add(um3);
        req2.put("messages", msgs2);

        Resp r2 = sendReq(baseUrl, apiKey, toJson(req2));
        if (r2.status != 200) {
            printError(output, r2);
            return;
        }

        ParsedResp p2 = parseStream(r2.body);
        for (Block b : p2.blocks) {
            if ("thinking".equals(b.type)) {
                output.add("thinking " + esc(b.thinking));
                output.add("signature " + esc(b.signature));
            } else if ("text".equals(b.type)) {
                output.add("text " + esc(b.text));
            } else if ("tool_use".equals(b.type)) {
                output.add("tool_use " + b.id + " " + b.name + " " + esc(b.inputJson.toString()));
            }
        }
        output.add("stop_reason " + p2.stopReason);
        totalIn += p2.inputTokens;
        totalOut += p2.outputTokens;
        totalCache += p2.cacheReadTokens;

        output.add("usage input=" + totalIn + " output=" + totalOut + " cache_read=" + totalCache);

        printOutput(output);
    }
}

import * as fs from 'fs';
import * as path from 'path';
import * as http from 'http';

function parseCsv(text: string): string[][] {
  if (text.charCodeAt(0) === 0xFEFF) text = text.slice(1);
  const rows: string[][] = [];
  let i = 0;
  const len = text.length;
  while (i < len) {
    const row: string[] = [];
    while (true) {
      if (i < len && text[i] === '"') {
        i++;
        let field = '';
        while (i < len) {
          if (text[i] === '"') {
            if (i + 1 < len && text[i + 1] === '"') {
              field += '"';
              i += 2;
            } else {
              i++;
              break;
            }
          } else {
            field += text[i];
            i++;
          }
        }
        row.push(field);
      } else {
        let field = '';
        while (i < len && text[i] !== ',' && text[i] !== '\r' && text[i] !== '\n') {
          field += text[i];
          i++;
        }
        row.push(field);
      }
      if (i < len && text[i] === ',') {
        i++;
      } else {
        if (i < len && text[i] === '\r') i++;
        if (i < len && text[i] === '\n') i++;
        break;
      }
    }
    if (row.length > 1 || row[0] !== '' || i < len) {
      rows.push(row);
    }
  }
  return rows;
}

function compactJsonString(s: string): string {
  let result = '"';
  for (let i = 0; i < s.length; i++) {
    const code = s.codePointAt(i)!;
    if (s[i] === '"') result += '\\"';
    else if (s[i] === '\\') result += '\\\\';
    else if (code === 0x08) result += '\\b';
    else if (code === 0x0C) result += '\\f';
    else if (code === 0x0A) result += '\\n';
    else if (code === 0x0D) result += '\\r';
    else if (code === 0x09) result += '\\t';
    else if (code < 0x20) result += '\\u00' + code.toString(16).padStart(2, '0');
    else result += s[i];
    if (code > 0xFFFF) i++;
  }
  result += '"';
  return result;
}

function compactJson(val: any): string {
  if (val === null || val === undefined) return 'null';
  if (typeof val === 'number') return String(val);
  if (typeof val === 'string') return compactJsonString(val);
  if (typeof val === 'boolean') return val ? 'true' : 'false';
  if (Array.isArray(val)) return '[' + val.map(compactJson).join(',') + ']';
  if (typeof val === 'object') {
    const parts: string[] = [];
    for (const k of Object.keys(val)) {
      parts.push(compactJsonString(k) + ':' + compactJson(val[k]));
    }
    return '{' + parts.join(',') + '}';
  }
  return String(val);
}

function executeTool(name: string, argsStr: string, inventory: Map<string, {sku:string,name:string,price_cents:number,currency:string,stock:number}>, rates: Record<string,number>): string {
  if (name === 'inventory_lookup') {
    const args = JSON.parse(argsStr);
    const sku: string = args.sku;
    const row = inventory.get(sku);
    if (!row) {
      return compactJson({ error: 'unknown sku: ' + sku });
    }
    return compactJson({ sku: row.sku, name: row.name, price_cents: row.price_cents, currency: row.currency, stock: row.stock });
  } else if (name === 'convert_currency') {
    const args = JSON.parse(argsStr);
    const amountCents: number = args.amount_cents;
    const from: string = args.from;
    const to: string = args.to;
    const rFrom = BigInt(rates[from]);
    const rTo = BigInt(rates[to]);
    const amount = BigInt(amountCents);
    const numerator = 2n * amount * rTo + rFrom;
    const denominator = 2n * rFrom;
    const converted = Number(numerator / denominator);
    return compactJson({ amount_cents: converted, currency: to });
  } else {
    return compactJson({ error: 'unknown tool: ' + name });
  }
}

function makeRequest(baseUrl: string, apiKey: string, body: string): Promise<{ status: number; body: string }> {
  return new Promise((resolve, reject) => {
    const urlObj = new URL(baseUrl + '/chat/completions');
    const bodyBuf = Buffer.from(body, 'utf8');
    const req = http.request({
      hostname: urlObj.hostname,
      port: urlObj.port ? parseInt(urlObj.port) : 80,
      path: urlObj.pathname,
      method: 'POST',
      headers: {
        'Host': urlObj.host,
        'Authorization': 'Bearer ' + apiKey,
        'Content-Type': 'application/json',
        'Content-Length': bodyBuf.length,
      },
    }, (res) => {
      const chunks: Buffer[] = [];
      res.on('data', (chunk: Buffer) => chunks.push(chunk));
      res.on('end', () => {
        const data = Buffer.concat(chunks).toString('utf8');
        resolve({ status: res.statusCode!, body: data });
      });
    });
    req.on('error', reject);
    req.write(bodyBuf);
    req.end();
  });
}

async function main() {
  const dataDir = process.argv[2];
  const baseUrl = process.argv[3];

  const taskRaw = fs.readFileSync(path.join(dataDir, 'task.json'), 'utf8');
  const task = JSON.parse(taskRaw);

  const csvRaw = fs.readFileSync(path.join(dataDir, 'inventory.csv'), 'utf8');
  const csvRows = parseCsv(csvRaw);

  const ratesRaw = fs.readFileSync(path.join(dataDir, 'rates.json'), 'utf8');
  const ratesData = JSON.parse(ratesRaw);
  const rates: Record<string, number> = ratesData.rates;

  const inventory = new Map<string, { sku: string; name: string; price_cents: number; currency: string; stock: number }>();
  for (let i = 1; i < csvRows.length; i++) {
    const r = csvRows[i];
    if (r.length >= 5) {
      inventory.set(r[0], {
        sku: r[0],
        name: r[1],
        price_cents: parseInt(r[2], 10),
        currency: r[3],
        stock: parseInt(r[4], 10),
      });
    }
  }

  const messages: any[] = [
    { role: 'system', content: task.system },
    { role: 'user', content: task.user },
  ];

  let totalPrompt = 0;
  let totalCompletion = 0;
  let totalTotal = 0;
  let requestCount = 0;
  const outputLines: string[] = [];

  while (true) {
    const reqBody = JSON.stringify({
      model: task.model,
      messages: messages,
      tools: task.tools,
      tool_choice: 'auto',
    });

    const resp = await makeRequest(baseUrl, task.api_key, reqBody);
    requestCount++;

    if (resp.status !== 200) {
      let errMsg = '';
      try {
        const errBody = JSON.parse(resp.body);
        errMsg = errBody.error ? errBody.error.message : '';
      } catch {
        errMsg = '';
      }
      for (const line of outputLines) console.log(line);
      console.log('ERROR ' + resp.status + ' ' + errMsg);
      process.exit(0);
    }

    const completion = JSON.parse(resp.body);
    if (completion.usage) {
      totalPrompt += completion.usage.prompt_tokens || 0;
      totalCompletion += completion.usage.completion_tokens || 0;
      totalTotal += completion.usage.total_tokens || 0;
    }

    const choice = completion.choices[0];
    const msg = choice.message;
    const finishReason = choice.finish_reason;

    if (finishReason === 'tool_calls') {
      const assistantMsg: any = { role: msg.role };
      assistantMsg.content = msg.content !== undefined ? msg.content : null;
      assistantMsg.tool_calls = msg.tool_calls;
      messages.push(assistantMsg);

      if (typeof msg.content === 'string') {
        outputLines.push('SAY ' + msg.content);
      }

      const toolCalls = msg.tool_calls || [];
      for (const tc of toolCalls) {
        outputLines.push('CALL ' + tc.id + ' ' + tc.function.name);
      }

      for (const tc of toolCalls) {
        const result = executeTool(tc.function.name, tc.function.arguments, inventory, rates);
        outputLines.push('RESULT ' + tc.id + ' ' + result);
        messages.push({ role: 'tool', tool_call_id: tc.id, content: result });
      }
    } else {
      outputLines.push('FINAL ' + (msg.content !== undefined && msg.content !== null ? msg.content : ''));
      break;
    }
  }

  for (const line of outputLines) console.log(line);
  console.log('USAGE prompt=' + totalPrompt + ' completion=' + totalCompletion + ' total=' + totalTotal + ' requests=' + requestCount);
}

main().catch((e) => {
  console.error(e);
  process.exit(0);
});

