import Foundation

// MARK: - JSON String Escaping (for tool result output)
func escapeJSONString(_ s: String) -> String {
    var result = ""
    for scalar in s.unicodeScalars {
        switch scalar {
        case "\"": result += "\\\""
        case "\\": result += "\\\\"
        case "\u{0008}": result += "\\b"
        case "\u{000C}": result += "\\f"
        case "\u{000A}": result += "\\n"
        case "\u{000D}": result += "\\r"
        case "\u{0009}": result += "\\t"
        default:
            if scalar.value < 0x20 {
                result += String(format: "\\u%04x", scalar.value)
            } else {
                result.unicodeScalars.append(scalar)
            }
        }
    }
    return result
}

// MARK: - CSV Parser (RFC 4180 with BOM handling)
func parseCSV(_ data: Data) -> [[String]] {
    var bytes = [UInt8](data)
    if bytes.count >= 3 && bytes[0] == 0xEF && bytes[1] == 0xBB && bytes[2] == 0xBF {
        bytes = Array(bytes[3...])
    }
    let text = String(decoding: bytes, as: UTF8.self)

    var records: [[String]] = []
    var currentRecord: [String] = []
    var currentField = ""
    var inQuotes = false
    var i = text.startIndex

    while i < text.endIndex {
        let ch = text[i]
        if inQuotes {
            if ch == "\"" {
                let next = text.index(after: i)
                if next < text.endIndex && text[next] == "\"" {
                    currentField.append("\"")
                    i = text.index(after: next)
                } else {
                    inQuotes = false
                    i = text.index(after: i)
                }
            } else {
                currentField.append(ch)
                i = text.index(after: i)
            }
        } else {
            if ch == "\"" && currentField.isEmpty {
                inQuotes = true
                i = text.index(after: i)
            } else if ch == "," {
                currentRecord.append(currentField)
                currentField = ""
                i = text.index(after: i)
            } else if ch == "\r" {
                currentRecord.append(currentField)
                currentField = ""
                records.append(currentRecord)
                currentRecord = []
                i = text.index(after: i)
                if i < text.endIndex && text[i] == "\n" {
                    i = text.index(after: i)
                }
            } else if ch == "\n" {
                currentRecord.append(currentField)
                currentField = ""
                records.append(currentRecord)
                currentRecord = []
                i = text.index(after: i)
            } else {
                currentField.append(ch)
                i = text.index(after: i)
            }
        }
    }

    if !currentField.isEmpty || !currentRecord.isEmpty {
        currentRecord.append(currentField)
        records.append(currentRecord)
    }

    return records
}

