            StringBuilder field = new StringBuilder();
            if (text.charAt(i) == '"') {
                i++; // skip opening quote
                while (i < len) {
                    if (text.charAt(i) == '"') {
                        if (i + 1 < len && text.charAt(i + 1) == '"') {
                            field.append('"');
                            i += 2;
                        } else {
                            i++; // skip closing quote
                            break;
                        }
                    } else {
                        field.append(text.charAt(i));
                        i++;
                    }
                }
            } else {
                while (i < len) {
                    char c = text.charAt(i);
                    if (c == ',' || c == '\r' || c == '\n') break;
                    field.append(c);
                    i++;
                }
            }
            fields.add(field.toString());

            if (i < len) {
                if (text.charAt(i) == ',') {
                    i++;
                } else if (text.charAt(i) == '\r' && i + 1 < len && text.charAt(i + 1) == '\n') {
                    i += 2;
                    records.add(fields);
                    fields = new ArrayList<>();
                } else if (text.charAt(i) == '\n') {
                    i++;
                    records.add(fields);
                    fields = new ArrayList<>();
                } else if (text.charAt(i) == '\r') {
                    i++;
                    records.add(fields);
                    fields = new ArrayList<>();
                } else {
                    break;
                }
            }
        }
        if (!fields.isEmpty()) records.add(fields);
        return records;
    }

    // ── Helpers ──────────────────────────────────────────────────────
    static long toLong(Object obj) {
        if (obj instanceof Long) return (Long) obj;
        if (obj instanceof Integer) return ((Integer) obj).longValue();
        if (obj instanceof Double) return ((Double) obj).longValue();
        if (obj instanceof BigInteger) return ((BigInteger) obj).longValue();
        return ((Number) obj).longValue();
    }

    // ── Tool execution ───────────────────────────────────────────────
    @SuppressWarnings("unchecked")
    static String executeTool(String name, String argsStr,
                              Map<String, Map<String, String>> inventory,
                              Map<String, Object> rates) {
        StringBuilder sb = new StringBuilder();

        if ("inventory_lookup".equals(name)) {
            Map<String, Object> args = (Map<String, Object>) parseJson(argsStr);
            String sku = (String) args.get("sku");
            Map<String, String> rec = inventory.get(sku);
            if (rec == null) {
                sb.append("{\"error\":");
                writeJsonString(sb, "unknown sku: " + sku);
                sb.append('}');
            } else {
                sb.append("{\"sku\":");
                writeJsonString(sb, rec.get("sku"));
                sb.append(",\"name\":");
                writeJsonString(sb, rec.get("name"));
                sb.append(",\"price_cents\":").append(Long.parseLong(rec.get("price_cents")));
                sb.append(",\"currency\":");
                writeJsonString(sb, rec.get("currency"));
                sb.append(",\"stock\":").append(Long.parseLong(rec.get("stock")));
                sb.append('}');
            }
        } else if ("convert_currency".equals(name)) {
            Map<String, Object> args = (Map<String, Object>) parseJson(argsStr);
            long amountCents = toLong(args.get("amount_cents"));
            String from = (String) args.get("from");
            String to   = (String) args.get("to");
            long rateFrom = toLong(rates.get(from));
            long rateTo   = toLong(rates.get(to));
            BigInteger two = BigInteger.valueOf(2);
            BigInteger numerator = two.multiply(BigInteger.valueOf(amountCents))
                                      .multiply(BigInteger.valueOf(rateTo))
                                      .add(BigInteger.valueOf(rateFrom));
            BigInteger denominator = two.multiply(BigInteger.valueOf(rateFrom));
            BigInteger result = numerator.divide(denominator);
            sb.append("{\"amount_cents\":").append(result).append(",\"currency\":");
            writeJsonString(sb, to);
            sb.append('}');
        } else {
            sb.append("{\"error\":");
            writeJsonString(sb, "unknown tool: " + name);
            sb.append('}');
        }
        return sb.toString();
    }

    // ── Main ─────────────────────────────────────────────────────────
    @SuppressWarnings("unchecked")
    public static void main(String[] args) throws Exception {
        String dataDir = args[0];
        String baseUrl = args[1];

        // ── read inputs ──
        String taskJson = new String(Files.readAllBytes(Paths.get(dataDir, "task.json")), StandardCharsets.UTF_8);
        byte[] csvBytes = Files.readAllBytes(Paths.get(dataDir, "inventory.csv"));
        String ratesJson = new String(Files.readAllBytes(Paths.get(dataDir, "rates.json")), StandardCharsets.UTF_8);

        Map<String, Object> task = (Map<String, Object>) parseJson(taskJson);
        String apiKey  = (String) task.get("api_key");
        String model   = (String) task.get("model");
        String system  = (String) task.get("system");
        String user    = (String) task.get("user");
        List<Object> tools = (List<Object>) task.get("tools");

        // ── inventory ──
        String csvText = new String(csvBytes, StandardCharsets.UTF_8);
        if (csvText.startsWith("\uFEFF")) csvText = csvText.substring(1);
        List<List<String>> csvRecords = parseCsv(csvText);
        Map<String, Map<String, String>> inventory = new LinkedHashMap<>();
        if (!csvRecords.isEmpty()) {
            List<String> header = csvRecords.get(0);
            for (int i = 1; i < csvRecords.size(); i++) {
                List<String> row = csvRecords.get(i);
                Map<String, String> rec = new LinkedHashMap<>();
                for (int j = 0; j < header.size() && j < row.size(); j++) {
                    rec.put(header.get(j), row.get(j));
                }
                inventory.put(rec.get("sku"), rec);
            }
        }

        // ── rates ──
        Map<String, Object> ratesData = (Map<String, Object>) parseJson(ratesJson);
        Map<String, Object> ratesMap = (Map<String, Object>) ratesData.get("rates");

        // ── conversation ──
        List<Object> messages = new ArrayList<>();
        Map<String, Object> sysMsg = new LinkedHashMap<>();
        sysMsg.put("role", "system");
        sysMsg.put("content", system);
        messages.add(sysMsg);
        Map<String, Object> userMsg = new LinkedHashMap<>();
        userMsg.put("role", "user");
        userMsg.put("content", user);
        messages.add(userMsg);

        // ── HTTP loop ──
        HttpClient client = HttpClient.newBuilder()
                .version(HttpClient.Version.HTTP_1_1)
                .build();

        int requests = 0;
        long totalPrompt = 0, totalCompletion = 0, totalTotal = 0;

        while (true) {
            Map<String, Object> body = new LinkedHashMap<>();
            body.put("model", model);
            body.put("messages", messages);
            body.put("tools", tools);
            body.put("tool_choice", "auto");
            String bodyStr = toJson(body);

            HttpRequest req = HttpRequest.newBuilder()
                    .uri(URI.create(baseUrl + "/chat/completions"))
                    .header("Authorization", "Bearer " + apiKey)
                    .header("Content-Type", "application/json")
                    .POST(HttpRequest.BodyPublishers.ofByteArray(bodyStr.getBytes(StandardCharsets.UTF_8)))
                    .build();

            HttpResponse<byte[]> resp = client.send(req, HttpResponse.BodyHandlers.ofByteArray());
            requests++;

            int status = resp.statusCode();
            String respBodyStr = new String(resp.body(), StandardCharsets.UTF_8);

            if (status != 200) {
                Map<String, Object> errBody = (Map<String, Object>) parseJson(respBodyStr);
                Map<String, Object> error = (Map<String, Object>) errBody.get("error");
                String errMsg = (String) error.get("message");
                System.out.println("ERROR " + status + " " + errMsg);
                System.exit(0);
            }

            Map<String, Object> respBody = (Map<String, Object>) parseJson(respBodyStr);

            // usage
            Map<String, Object> usage = (Map<String, Object>) respBody.get("usage");
            if (usage != null) {
                totalPrompt     += toLong(usage.get("prompt_tokens"));
                totalCompletion += toLong(usage.get("completion_tokens"));
                totalTotal      += toLong(usage.get("total_tokens"));
            }

            List<Object> choices = (List<Object>) respBody.get("choices");
            Map<String, Object> choice = (Map<String, Object>) choices.get(0);
            String finishReason = (String) choice.get("finish_reason");
            Map<String, Object> msg = (Map<String, Object>) choice.get("message");

            if ("stop".equals(finishReason)) {
                String content = (String) msg.get("content");
                System.out.println("FINAL " + content);
                break;
            }

            // finish_reason == "tool_calls"
            String content = (String) msg.get("content");
            if (content != null) {
                System.out.println("SAY " + content);
            }

            List<Object> toolCalls = (List<Object>) msg.get("tool_calls");

            // print CALL lines
            for (Object tcObj : toolCalls) {
                Map<String, Object> tc = (Map<String, Object>) tcObj;
                String id = (String) tc.get("id");
                Map<String, Object> fn = (Map<String, Object>) tc.get("function");
                String name = (String) fn.get("name");
                System.out.println("CALL " + id + " " + name);
            }

            // build assistant message for conversation
            Map<String, Object> assistantMsg = new LinkedHashMap<>();
            assistantMsg.put("role", "assistant");
            assistantMsg.put("content", content);
            List<Object> newToolCalls = new ArrayList<>();
            for (Object tcObj : toolCalls) {
                Map<String, Object> tc = (Map<String, Object>) tcObj;
                Map<String, Object> newTc = new LinkedHashMap<>();
                newTc.put("id", tc.get("id"));
                newTc.put("type", tc.get("type"));
                Map<String, Object> fn = (Map<String, Object>) tc.get("function");
                Map<String, Object> newFn = new LinkedHashMap<>();
                newFn.put("name", fn.get("name"));
                newFn.put("arguments", fn.get("arguments"));
                newTc.put("function", newFn);
                newToolCalls.add(newTc);
            }
            assistantMsg.put("tool_calls", newToolCalls);
            messages.add(assistantMsg);

            // execute tools, print RESULT lines, build tool messages
            for (Object tcObj : toolCalls) {
                Map<String, Object> tc = (Map<String, Object>) tcObj;
                String id = (String) tc.get("id");
                Map<String, Object> fn = (Map<String, Object>) tc.get("function");
                String name = (String) fn.get("name");
                String argsStr = (String) fn.get("arguments");

                String result = executeTool(name, argsStr, inventory, ratesMap);
                System.out.println("RESULT " + id + " " + result);

                Map<String, Object> toolMsg = new LinkedHashMap<>();
                toolMsg.put("role", "tool");
                toolMsg.put("tool_call_id", id);
                toolMsg.put("content", result);
                messages.add(toolMsg);
            }
        }

        System.out.println("USAGE prompt=" + totalPrompt + " completion=" + totalCompletion
                + " total=" + totalTotal + " requests=" + requests);
    }
}

use std::env;
use std::fs;
use std::io::{Read, Write};
use std::net::TcpStream;

// ==================== JSON ====================

#[derive(Debug, Clone)]
enum Json {
    Null,
    Bool(bool),
    Num(String),
    Str(String),
    Arr(Vec<Json>),
    Obj(Vec<(String, Json)>),
}

impl Json {
    fn get(&self, key: &str) -> Option<&Json> {
        if let Json::Obj(obj) = self {
            for (k, v) in obj {
                if k == key { return Some(v); }
            }
        }
        None
    }
    fn as_str(&self) -> &str {
        match self { Json::Str(s) => s, _ => "" }
    }
    fn as_int(&self) -> i64 {
        match self { Json::Num(s) => s.parse().unwrap_or(0), _ => 0 }
    }
}

struct JsonParser { data: Vec<u8>, pos: usize }

impl JsonParser {
    fn new(s: &str) -> Self { JsonParser { data: s.as_bytes().to_vec(), pos: 0 } }

    fn skip_ws(&mut self) {
        while self.pos < self.data.len() && matches!(self.data[self.pos], b' '|b'\t'|b'\n'|b'\r') {
            self.pos += 1;
        }
    }
    fn peek(&self) -> u8 {
        if self.pos < self.data.len() { self.data[self.pos] } else { 0 }
    }
    fn parse(&mut self) -> Json {
        self.skip_ws();
        match self.peek() {
            b'n' => { self.pos += 4; Json::Null }
            b't' => { self.pos += 4; Json::Bool(true) }
            b'f' => { self.pos += 5; Json::Bool(false) }
            b'"' => Json::Str(self.parse_string()),
            b'[' => self.parse_array(),
            b'{' => self.parse_object(),
            _ => self.parse_number(),
        }
    }
    fn parse_string(&mut self) -> String {
        self.pos += 1;
        let mut bytes: Vec<u8> = Vec::new();
        loop {
            if self.pos >= self.data.len() { break; }
            match self.data[self.pos] {
                b'"' => { self.pos += 1; break; }
                b'\\' => {
                    self.pos += 1;
                    if self.pos >= self.data.len() { break; }
                    match self.data[self.pos] {
                        b'"' => { bytes.push(b'"'); self.pos += 1; }
                        b'\\' => { bytes.push(b'\\'); self.pos += 1; }
                        b'/' => { bytes.push(b'/'); self.pos += 1; }
                        b'b' => { bytes.push(8); self.pos += 1; }
                        b'f' => { bytes.push(12); self.pos += 1; }
                        b'n' => { bytes.push(b'\n'); self.pos += 1; }
                        b'r' => { bytes.push(b'\r'); self.pos += 1; }
                        b't' => { bytes.push(b'\t'); self.pos += 1; }
                        b'u' => {
                            self.pos += 1;
                            let cp = self.parse_hex4();
                            if cp >= 0xD800 && cp <= 0xDBFF {
                                if self.pos + 1 < self.data.len()
                                    && self.data[self.pos] == b'\\'
                                    && self.data[self.pos + 1] == b'u' {
                                    self.pos += 2;
                                    let cp2 = self.parse_hex4();
                                    if cp2 >= 0xDC00 && cp2 <= 0xDFFF {
                                        let full = 0x10000 + ((cp - 0xD800) << 10) + (cp2 - 0xDC00);
                                        if let Some(c) = char::from_u32(full) {
                                            let mut buf = [0u8; 4];
                                            bytes.extend_from_slice(c.encode_utf8(&mut buf).as_bytes());
                                        }
                                    }
                                }
                            } else if !(cp >= 0xDC00 && cp <= 0xDFFF) {
                                if let Some(c) = char::from_u32(cp) {
                                    let mut buf = [0u8; 4];
                                    bytes.extend_from_slice(c.encode_utf8(&mut buf).as_bytes());
                                }
                            }
                        }
                        _ => { bytes.push(self.data[self.pos]); self.pos += 1; }
                    }
                }
                _ => { bytes.push(self.data[self.pos]); self.pos += 1; }
            }
        }
        String::from_utf8_lossy(&bytes).to_string()
    }
    fn parse_hex4(&mut self) -> u32 {
        let hex = std::str::from_utf8(&self.data[self.pos..self.pos + 4]).unwrap_or("0000");
        self.pos += 4;
        u32::from_str_radix(hex, 16).unwrap_or(0)
    }
    fn parse_number(&mut self) -> Json {
        let start = self.pos;
        if self.pos < self.data.len() && self.data[self.pos] == b'-' { self.pos += 1; }
        while self.pos < self.data.len() && self.data[self.pos].is_ascii_digit() { self.pos += 1; }
        if self.pos < self.data.len() && self.data[self.pos] == b'.' {
            self.pos += 1;
            while self.pos < self.data.len() && self.data[self.pos].is_ascii_digit() { self.pos += 1; }
        }
        if self.pos < self.data.len() && (self.data[self.pos] == b'e' || self.data[self.pos] == b'E') {
            self.pos += 1;
            if self.pos < self.data.len() && (self.data[self.pos] == b'+' || self.data[self.pos] == b'-') {
                self.pos += 1;
            }
            while self.pos < self.data.len() && self.data[self.pos].is_ascii_digit() { self.pos += 1; }
        }
        Json::Num(String::from_utf8_lossy(&self.data[start..self.pos]).to_string())
    }
    fn parse_array(&mut self) -> Json {
        self.pos += 1;
        let mut items = Vec::new();
        self.skip_ws();
        if self.peek() == b']' { self.pos += 1; return Json::Arr(items); }
        loop {
            items.push(self.parse());
            self.skip_ws();
            if self.peek() == b',' { self.pos += 1; self.skip_ws(); continue; }
            if self.peek() == b']' { self.pos += 1; break; }
            break;
        }
        Json::Arr(items)
    }
    fn parse_object(&mut self) -> Json {
        self.pos += 1;
        let mut items = Vec::new();
        self.skip_ws();
        if self.peek() == b'}' { self.pos += 1; return Json::Obj(items); }
        loop {
            self.skip_ws();
            let key = self.parse_string();
            self.skip_ws();
            if self.peek() == b':' { self.pos += 1; }
            let val = self.parse();
            items.push((key, val));
            self.skip_ws();
            if self.peek() == b',' { self.pos += 1; continue; }
            if self.peek() == b'}' { self.pos += 1; break; }
            break;
        }
        Json::Obj(items)
    }
}

fn parse_json(s: &str) -> Json {
    if s.is_empty() { return Json::Null; }
    let mut p = JsonParser::new(s);
    p.parse()
}

fn json_to_string(j: &Json) -> String {
    match j {
        Json::Null => "null".into(),
        Json::Bool(b) => if *b { "true".into() } else { "false".into() },
        Json::Num(s) => s.clone(),
        Json::Str(s) => format!("\"{}\"", json_escape(s)),
        Json::Arr(arr) => {
            let items: Vec<String> = arr.iter().map(json_to_string).collect();
            format!("[{}]", items.join(","))
        }
        Json::Obj(obj) => {
            let items: Vec<String> = obj.iter()
                .map(|(k, v)| format!("\"{}\":{}", json_escape(k), json_to_string(v)))
                .collect();
            format!("{{{}}}", items.join(","))
        }
    }
}

fn json_escape(s: &str) -> String {
    let mut r = String::new();
    for ch in s.chars() {
        match ch {
            '"' => r.push_str("\\\""),
            '\\' => r.push_str("\\\\"),
            '\n' => r.push_str("\\n"),
            '\r' => r.push_str("\\r"),
            '\t' => r.push_str("\\t"),
            '\u{0008}' => r.push_str("\\b"),
            '\u{000C}' => r.push_str("\\f"),
            c if (c as u32) < 0x20 => r.push_str(&format!("\\u{:04x}", c as u32)),
            c => r.push(c),
        }
    }
    r
}

// ==================== HTTP ====================

struct ByteReader { stream: TcpStream, buf: Vec<u8>, pos: usize }

impl ByteReader {
    fn new(stream: TcpStream) -> Self { ByteReader { stream, buf: Vec::new(), pos: 0 } }

    fn fill(&mut self) -> bool {
        if self.pos > 0 {
            self.buf.drain(..self.pos);
            self.pos = 0;
        }
        let mut tmp = [0u8; 8192];
        match self.stream.read(&mut tmp) {
            Ok(0) => false,
            Ok(n) => { self.buf.extend_from_slice(&tmp[..n]); true }
            Err(_) => false,
        }
    }
    fn read_byte(&mut self) -> Option<u8> {
        if self.pos >= self.buf.len() && !self.fill() { return None; }
        let b = self.buf[self.pos];
        self.pos += 1;
        Some(b)
    }
    fn read_line(&mut self) -> Vec<u8> {
        let mut line = Vec::new();
        loop {
            match self.read_byte() {
                Some(b'\n') => {
                    if line.last() == Some(&b'\r') { line.pop(); }
                    return line;
                }
                Some(b) => line.push(b),
                None => return line,
            }
        }
    }
    fn read_exact(&mut self, n: usize) -> Vec<u8> {
        let mut result = Vec::with_capacity(n);
        for _ in 0..n {
            match self.read_byte() {
                Some(b) => result.push(b),
                None => break,
            }
        }
        result
    }
}

fn read_chunked(reader: &mut ByteReader) -> Vec<u8> {
    let mut body = Vec::new();
    loop {
        let line = reader.read_line();
        let line_str = String::from_utf8_lossy(&line);
        let size_str = line_str.split(';').next().unwrap_or("").trim();
        let size = usize::from_str_radix(size_str, 16).unwrap_or(0);
        if size == 0 {
            loop {
                let tl = reader.read_line();
                if tl.is_empty() { break; }
            }
            break;
        }
        let chunk = reader.read_exact(size);
        body.extend_from_slice(&chunk);
        reader.read_line();
    }
    body
}

fn http_post(host: &str, port: u16, path: &str, api_key: &str, body: &str) -> (u16, Vec<u8>) {
    let addr = format!("{}:{}", host, port);
    let stream = TcpStream::connect(&addr).expect("connect failed");
    let header = format!(
        "POST {} HTTP/1.1\r\nHost: {}\r\nContent-Length: {}\r\nx-api-key: {}\r\nanthropic-version: 2023-06-01\r\ncontent-type: application/json\r\nConnection: close\r\n\r\n",
        path, host, body.len(), api_key
    );
    let mut stream = stream;
    stream.write_all(header.as_bytes()).unwrap();
    stream.write_all(body.as_bytes()).unwrap();
    stream.flush().unwrap();

    let mut reader = ByteReader::new(stream);
    let status_line = reader.read_line();
    let status_str = String::from_utf8_lossy(&status_line);
    let status: u16 = status_str.split_whitespace().nth(1).unwrap_or("0").parse().unwrap_or(0);

    let mut content_length: Option<usize> = None;
    let mut is_chunked = false;
    loop {
        let line = reader.read_line();
        if line.is_empty() { break; }
        let lower = String::from_utf8_lossy(&line).to_lowercase();
        if lower.starts_with("transfer-encoding:") && lower.contains("chunked") {
            is_chunked = true;
        }
        if lower.starts_with("content-length:") {
            content_length = Some(lower[15..].trim().parse().unwrap_or(0));
        }
    }

    let body_bytes = if is_chunked {
        read_chunked(&mut reader)
    } else if let Some(len) = content_length {
        reader.read_exact(len)
    } else {
        let mut result = Vec::new();
        while let Some(b) = reader.read_byte() { result.push(b); }
        result
    };
    (status, body_bytes)
}

// ==================== SSE ====================

struct SseEvent { event_type: String, data: String }

fn parse_sse(body: &[u8]) -> Vec<SseEvent> {
    let mut events = Vec::new();
    let mut cur_type = String::new();
    let mut cur_data: Vec<String> = Vec::new();

    let mut lines: Vec<&[u8]> = Vec::new();
    let mut start = 0;
    let mut i = 0;
    while i < body.len() {
        if body[i] == b'\n' {
            let end = if i > start && body[i - 1] == b'\r' { i - 1 } else { i };
            lines.push(&body[start..end]);
            start = i + 1;
        }
        i += 1;
    }
    if start < body.len() { lines.push(&body[start..]); }

    for line in lines {
        if line.is_empty() {
            if !cur_data.is_empty() {
                events.push(SseEvent { event_type: cur_type.clone(), data: cur_data.join("\n") });
            }
            cur_type.clear();
            cur_data.clear();
        } else if line[0] == b':' {
            // comment
        } else if line.starts_with(b"event:") {
            let val = &line[6..];
            let val = if val.first() == Some(&b' ') { &val[1..] } else { val };
            cur_type = String::from_utf8_lossy(val).to_string();
        } else if line.starts_with(b"data:") {
            let val = &line[5..];
            let val = if val.first() == Some(&b' ') { &val[1..] } else { val };
            cur_data.push(String::from_utf8_lossy(val).to_string());
        }
    }
    events
}

// ==================== Content Blocks ====================

#[derive(Debug, Clone)]
enum ContentBlock {
    Thinking { thinking: String, signature: String },
    Text { text: String },
    ToolUse { id: String, name: String, raw_input: String },
}

struct ReplyResult {
    blocks: Vec<ContentBlock>,
    stop_reason: String,
    input_tokens: i64,
    output_tokens: i64,
    cache_read: i64,
}

fn process_reply(events: &[SseEvent]) -> ReplyResult {
    let mut blocks: Vec<Option<ContentBlock>> = Vec::new();
    let mut stop_reason = String::new();
    let mut input_tokens = 0i64;
    let mut output_tokens = 0i64;
    let mut cache_read = 0i64;

    for event in events {
        let data = parse_json(&event.data);
        match event.event_type.as_str() {
            "message_start" => {
                if let Some(msg) = data.get("message") {
                    if let Some(usage) = msg.get("usage") {
                        input_tokens += usage.get("input_tokens").map_or(0, |v| v.as_int());
                        cache_read += usage.get("cache_read_input_tokens").map_or(0, |v| v.as_int());
                    }
                }
            }
            "content_block_start" => {
                let idx = data.get("index").map_or(0, |v| v.as_int()) as usize;
                while blocks.len() <= idx { blocks.push(None); }
                if let Some(cb) = data.get("content_block") {
                    let btype = cb.get("type").map_or("", |t| t.as_str());
                    match btype {
                        "thinking" => {
                            blocks[idx] = Some(ContentBlock::Thinking {
                                thinking: String::new(), signature: String::new(),
                            });
                        }
                        "text" => {
                            blocks[idx] = Some(ContentBlock::Text { text: String::new() });
                        }
                        "tool_use" => {
                            blocks[idx] = Some(ContentBlock::ToolUse {
                                id: cb.get("id").map_or("", |v| v.as_str()).to_string(),
                                name: cb.get("name").map_or("", |v| v.as_str()).to_string(),
                                raw_input: String::new(),
                            });
                        }
                        _ => {}
                    }
                }
            }
            "content_block_delta" => {
                let idx = data.get("index").map_or(0, |v| v.as_int()) as usize;
                if idx < blocks.len() {
                    if let Some(block) = &mut blocks[idx] {
                        if let Some(delta) = data.get("delta") {
                            let dtype = delta.get("type").map_or("", |t| t.as_str());
                            match dtype {
                                "thinking_delta" => {
                                    if let ContentBlock::Thinking { thinking, .. } = block {
                                        *thinking += delta.get("thinking").map_or("", |v| v.as_str());
                                    }
                                }
                                "signature_delta" => {
                                    if let ContentBlock::Thinking { signature, .. } = block {
                                        *signature += delta.get("signature").map_or("", |v| v.as_str());
                                    }
                                }
                                "text_delta" => {
                                    if let ContentBlock::Text { text } = block {
                                        *text += delta.get("text").map_or("", |v| v.as_str());
                                    }
                                }
                                "input_json_delta" => {
                                    if let ContentBlock::ToolUse { raw_input, .. } = block {
                                        *raw_input += delta.get("partial_json").map_or("", |v| v.as_str());
                                    }
                                }
                                _ => {}
                            }
                        }
                    }
                }
            }
            "message_delta" => {
                if let Some(delta) = data.get("delta") {
                    if let Some(sr) = delta.get("stop_reason") {
                        stop_reason = sr.as_str().to_string();
                    }
                }
                if let Some(usage) = data.get("usage") {
                    output_tokens += usage.get("output_tokens").map_or(0, |v| v.as_int());
                }
            }
            _ => {}
        }
    }
    ReplyResult {
        blocks: blocks.into_iter().filter_map(|b| b).collect(),
        stop_reason, input_tokens, output_tokens, cache_read,
    }
}

// ==================== Tools ====================

fn execute_tool(name: &str, input: &Json) -> (String, bool) {
    match name {
        "measure" => {
            let text = input.get("text").map_or("", |v| v.as_str());
            let unit = input.get("unit").map_or("", |v| v.as_str());
            match unit {
                "code_points" => (text.chars().count().to_string(), false),
                "utf8_bytes" => (text.len().to_string(), false),
                "utf16_units" => (text.encode_utf16().count().to_string(), false),
                _ => (format!("unsupported unit: {}", unit), true),
            }
        }
        "reverse" => {
            let text = input.get("text").map_or("", |v| v.as_str());
            (text.chars().rev().collect(), false)
        }
        _ => (format!("unknown tool: {}", name), true),
    }
}

// ==================== Output ====================

fn escape_output(s: &str) -> String {
    let mut r = String::new();
    for ch in s.chars() {
        match ch {
            '\\' => r.push_str("\\\\"),
            '\n' => r.push_str("\\n"),
            '\r' => r.push_str("\\r"),
            '\t' => r.push_str("\\t"),
            c => r.push(c),
        }
    }
    r
}

fn print_blocks(blocks: &[ContentBlock]) {
    for block in blocks {
        match block {
            ContentBlock::Thinking { thinking, signature } => {
                println!("thinking {}", escape_output(thinking));
                println!("signature {}", escape_output(signature));
            }
            ContentBlock::Text { text } => {
                println!("text {}", escape_output(text));
            }
            ContentBlock::ToolUse { id, name, raw_input } => {
                println!("tool_use {} {} {}", id, name, escape_output(raw_input));
            }
        }
    }
}

// ==================== Request Building ====================

fn build_body(
    model: &str,
    max_tokens: &Json,
    thinking_budget: &Json,
    system: &Json,
    tools: &Json,
    messages: Json,
) -> String {
    let body = Json::Obj(vec![
        ("model".into(), Json::Str(model.into())),
        ("max_tokens".into(), max_tokens.clone()),
        ("stream".into(), Json::Bool(true)),
        ("thinking".into(), Json::Obj(vec![
            ("type".into(), Json::Str("enabled".into())),
            ("budget_tokens".into(), thinking_budget.clone()),
        ])),
        ("system".into(), system.clone()),
        ("tools".into(), tools.clone()),
        ("messages".into(), messages),
    ]);
    json_to_string(&body)
}

// ==================== URL Parsing ====================

fn parse_url(url: &str) -> (String, u16, String) {
    let rest = url.strip_prefix("http://").unwrap_or(url);
    let (authority, path) = match rest.find('/') {
        Some(i) => (&rest[..i], &rest[i..]),
        None => (rest, "/"),
    };
    let (host, port) = match authority.rfind(':') {
        Some(i) => (&authority[..i], authority[i + 1..].parse().unwrap_or(80)),
        None => (authority, 80),
    };
    (host.to_string(), port, path.to_string())
}

// ==================== Main ====================

fn main() {
    let args: Vec<String> = env::args().collect();
    let data_dir = &args[1];
    let base_url = &args[2];

    let json_str = fs::read_to_string(format!("{}/request.json", data_dir)).expect("read request.json");
    let req = parse_json(&json_str);

    let api_key = req.get("api_key").map_or("", |v| v.as_str()).to_string();
    let model = req.get("model").map_or("", |v| v.as_str()).to_string();
    let max_tokens = req.get("max_tokens").cloned().unwrap_or(Json::Num("8000".into()));
    let thinking_budget = req.get("thinking_budget").cloned().unwrap_or(Json::Num("2048".into()));
    let system = req.get("system").cloned().unwrap_or(Json::Null);
    let prompt = req.get("prompt").cloned().unwrap_or(Json::Str(String::new()));
    let tools = req.get("tools").cloned().unwrap_or(Json::Arr(vec![]));

    let (host, port, path) = parse_url(base_url);
    let full_path = format!("{}/v1/messages", path);

    let mut total_input = 0i64;
    let mut total_output = 0i64;
    let mut total_cache_read = 0i64;

    // === Request 1 ===
    println!("request 1");

    let messages1 = Json::Arr(vec![
        Json::Obj(vec![
            ("role".into(), Json::Str("user".into())),
            ("content".into(), prompt.clone()),
        ]),
    ]);
    let body1 = build_body(&model, &max_tokens, &thinking_budget, &system, &tools, messages1);
    let (status, body_bytes) = http_post(&host, port, &full_path, &api_key, &body1);

    if status != 200 {
        let err_str = String::from_utf8_lossy(&body_bytes);
        let err_json = parse_json(&err_str);
        let etype = err_json.get("error").map_or("", |e| e.get("type").map_or("", |v| v.as_str()));
        let emsg = err_json.get("error").map_or("", |e| e.get("message").map_or("", |v| v.as_str()));
        println!("ERROR {} {}: {}", status, etype, emsg);
        return;
    }

    let events = parse_sse(&body_bytes);
    let reply1 = process_reply(&events);
    total_input += reply1.input_tokens;
    total_output += reply1.output_tokens;
    total_cache_read += reply1.cache_read;

    print_blocks(&reply1.blocks);
    println!("stop_reason {}", reply1.stop_reason);

    // Execute tools
    let mut tool_results: Vec<(String, String, bool)> = Vec::new();
    for block in &reply1.blocks {
        if let ContentBlock::ToolUse { id, name, raw_input } = block {
            let input = if raw_input.is_empty() { Json::Obj(vec![]) } else { parse_json(raw_input) };
            let (result, is_error) = execute_tool(name, &input);
            println!("{} {} {}", if is_error { "error" } else { "result" }, id, escape_output(&result));
            tool_results.push((id.clone(), result, is_error));
        }
    }

    // === Request 2 ===
    println!("request 2");

    let mut assistant_content: Vec<Json> = Vec::new();
    for block in &reply1.blocks {
        match block {
            ContentBlock::Thinking { thinking, signature } => {
                assistant_content.push(Json::Obj(vec![
                    ("type".into(), Json::Str("thinking".into())),
                    ("thinking".into(), Json::Str(thinking.clone())),
                    ("signature".into(), Json::Str(signature.clone())),
                ]));
            }
            ContentBlock::Text { text } => {
                assistant_content.push(Json::Obj(vec![
                    ("type".into(), Json::Str("text".into())),
                    ("text".into(), Json::Str(text.clone())),
                ]));
            }
            ContentBlock::ToolUse { id, name, raw_input } => {
                let input = if raw_input.is_empty() { Json::Obj(vec![]) } else { parse_json(raw_input) };
                assistant_content.push(Json::Obj(vec![
                    ("type".into(), Json::Str("tool_use".into())),
                    ("id".into(), Json::Str(id.clone())),
                    ("name".into(), Json::Str(name.clone())),
                    ("input".into(), input),
                ]));
            }
        }
    }

    let mut tool_result_content: Vec<Json> = Vec::new();
    for (id, result, is_error) in &tool_results {
        let mut obj = vec![
            ("type".into(), Json::Str("tool_result".into())),
            ("tool_use_id".into(), Json::Str(id.clone())),
            ("content".into(), Json::Str(result.clone())),
        ];
        if *is_error {
            obj.push(("is_error".into(), Json::Bool(true)));
        }
        tool_result_content.push(Json::Obj(obj));
    }

    let messages2 = Json::Arr(vec![
        Json::Obj(vec![
            ("role".into(), Json::Str("user".into())),
            ("content".into(), prompt.clone()),
        ]),
        Json::Obj(vec![
            ("role".into(), Json::Str("assistant".into())),
            ("content".into(), Json::Arr(assistant_content)),
        ]),
        Json::Obj(vec![
            ("role".into(), Json::Str("user".into())),
            ("content".into(), Json::Arr(tool_result_content)),
        ]),
    ]);

    let body2 = build_body(&model, &max_tokens, &thinking_budget, &system, &tools, messages2);
    let (status, body_bytes) = http_post(&host, port, &full_path, &api_key, &body2);

    if status != 200 {
        let err_str = String::from_utf8_lossy(&body_bytes);
        let err_json = parse_json(&err_str);
        let etype = err_json.get("error").map_or("", |e| e.get("type").map_or("", |v| v.as_str()));
        let emsg = err_json.get("error").map_or("", |e| e.get("message").map_or("", |v| v.as_str()));
        println!("ERROR {} {}: {}", status, etype, emsg);
        return;
    }

    let events = parse_sse(&body_bytes);
    let reply2 = process_reply(&events);
    total_input += reply2.input_tokens;
    total_output += reply2.output_tokens;
    total_cache_read += reply2.cache_read;

    print_blocks(&reply2.blocks);
    println!("stop_reason {}", reply2.stop_reason);

    println!("usage input={} output={} cache_read={}", total_input, total_output, total_cache_read);
}

use std::collections::HashMap;
use std::env;
use std::fs;
use std::io::{Read, Write};
use std::net::TcpStream;

#[derive(Debug, Clone)]
enum Json {
    Null,
    Bool(bool),
    Num(f64),
    Str(String),
    Arr(Vec<Json>),
    Obj(Vec<(String, Json)>),
}

impl Json {
    fn get(&self, key: &str) -> Option<&Json> {
        if let Json::Obj(pairs) = self {
            for (k, v) in pairs {
                if k == key { return Some(v); }
            }
        }
        None
    }
    fn as_str(&self) -> Option<&str> {
        if let Json::Str(s) = self { Some(s) } else { None }
    }
    fn as_f64(&self) -> Option<f64> {
        if let Json::Num(n) = self { Some(*n) } else { None }
    }
    fn as_i64(&self) -> Option<i64> {
        if let Json::Num(n) = self { Some(*n as i64) } else { None }
    }
    fn as_arr(&self) -> Option<&Vec<Json>> {
        if let Json::Arr(a) = self { Some(a) } else { None }
    }
}

struct JsonParser {
    chars: Vec<char>,
    pos: usize,
}

impl JsonParser {
    fn new(s: &str) -> Self {
        JsonParser { chars: s.chars().collect(), pos: 0 }
    }
    fn parse(&mut self) -> Json {
        self.skip_ws();
        self.parse_value()
    }
    fn skip_ws(&mut self) {
        while self.pos < self.chars.len()
            && matches!(self.chars[self.pos], ' ' | '\t' | '\n' | '\r')
        {
            self.pos += 1;
        }
    }
    fn parse_value(&mut self) -> Json {
        self.skip_ws();
        if self.pos >= self.chars.len() { return Json::Null; }
        match self.chars[self.pos] {
            '{' => self.parse_object(),
            '[' => self.parse_array(),
            '"' => Json::Str(self.parse_string()),
            't' => { self.pos += 4; Json::Bool(true) }
            'f' => { self.pos += 5; Json::Bool(false) }
            'n' => { self.pos += 4; Json::Null }
            _ => self.parse_number(),
        }
    }
    fn parse_object(&mut self) -> Json {
        self.pos += 1;
        self.skip_ws();
        let mut pairs = Vec::new();
        if self.pos < self.chars.len() && self.chars[self.pos] == '}' {
            self.pos += 1;
            return Json::Obj(pairs);
        }
        loop {
            self.skip_ws();
            let key = self.parse_string();
            self.skip_ws();
            self.pos += 1;
            let val = self.parse_value();
            pairs.push((key, val));
            self.skip_ws();
            if self.pos < self.chars.len() && self.chars[self.pos] == ',' {
                self.pos += 1;
            } else {
                break;
            }
        }
        self.skip_ws();
        if self.pos < self.chars.len() && self.chars[self.pos] == '}' { self.pos += 1; }
        Json::Obj(pairs)
    }
    fn parse_array(&mut self) -> Json {
        self.pos += 1;
        self.skip_ws();
        let mut items = Vec::new();
        if self.pos < self.chars.len() && self.chars[self.pos] == ']' {
            self.pos += 1;
            return Json::Arr(items);
        }
        loop {
            items.push(self.parse_value());
            self.skip_ws();
            if self.pos < self.chars.len() && self.chars[self.pos] == ',' {
                self.pos += 1;
            } else {
                break;
            }
        }
        self.skip_ws();
        if self.pos < self.chars.len() && self.chars[self.pos] == ']' { self.pos += 1; }
        Json::Arr(items)
    }
    fn parse_string(&mut self) -> String {
        self.pos += 1;
        let mut result = String::new();
        while self.pos < self.chars.len() {
            match self.chars[self.pos] {
                '"' => { self.pos += 1; return result; }
                '\\' => {
                    self.pos += 1;
                    if self.pos >= self.chars.len() { break; }
                    match self.chars[self.pos] {
                        '"' => { result.push('"'); self.pos += 1; }
                        '\\' => { result.push('\\'); self.pos += 1; }
                        '/' => { result.push('/'); self.pos += 1; }
                        'b' => { result.push('\u{0008}'); self.pos += 1; }
                        'f' => { result.push('\u{000C}'); self.pos += 1; }
                        'n' => { result.push('\n'); self.pos += 1; }
                        'r' => { result.push('\r'); self.pos += 1; }
                        't' => { result.push('\t'); self.pos += 1; }
                        'u' => {
                            self.pos += 1;
                            let cp = self.parse_hex4();
                            if (0xD800..=0xDBFF).contains(&cp)
                                && self.pos + 1 < self.chars.len()
                                && self.chars[self.pos] == '\\'
                                && self.chars[self.pos + 1] == 'u'
                            {
                                self.pos += 2;
                                let cp2 = self.parse_hex4();
                                let combined =
                                    0x10000 + ((cp - 0xD800) << 10) + (cp2 - 0xDC00);
                                result.push(
                                    char::from_u32(combined).unwrap_or('\u{FFFD}'),
                                );
                            } else {
                                result.push(char::from_u32(cp).unwrap_or('\u{FFFD}'));
                            }
                        }
                        _ => { result.push(self.chars[self.pos]); self.pos += 1; }
                    }
                }
                _ => { result.push(self.chars[self.pos]); self.pos += 1; }
            }
        }
        result
    }
    fn parse_hex4(&mut self) -> u32 {
        let mut val = 0u32;
        for _ in 0..4 {
            let c = self.chars[self.pos];
            val = val * 16
                + match c {
                    '0'..='9' => (c as u32) - ('0' as u32),
                    'a'..='f' => (c as u32) - ('a' as u32) + 10,
                    'A'..='F' => (c as u32) - ('A' as u32) + 10,
                    _ => 0,
                };
            self.pos += 1;
        }
        val
    }
    fn parse_number(&mut self) -> Json {
        let start = self.pos;
        if self.pos < self.chars.len() && self.chars[self.pos] == '-' { self.pos += 1; }
        while self.pos < self.chars.len() && self.chars[self.pos].is_ascii_digit() {
            self.pos += 1;
        }
        if self.pos < self.chars.len() && self.chars[self.pos] == '.' {
            self.pos += 1;
            while self.pos < self.chars.len() && self.chars[self.pos].is_ascii_digit() {
                self.pos += 1;
            }
        }
        if self.pos < self.chars.len()
            && (self.chars[self.pos] == 'e' || self.chars[self.pos] == 'E')
        {
            self.pos += 1;
            if self.pos < self.chars.len()
                && (self.chars[self.pos] == '+' || self.chars[self.pos] == '-')
            {
                self.pos += 1;
            }
            while self.pos < self.chars.len() && self.chars[self.pos].is_ascii_digit() {
                self.pos += 1;
            }
        }
        let s: String = self.chars[start..self.pos].iter().collect();
        Json::Num(s.parse::<f64>().unwrap_or(0.0))
    }
}

fn json_escape_string(s: &str) -> String {
    let mut r = String::with_capacity(s.len() + 2);
    r.push('"');
    for c in s.chars() {
        match c {
            '"' => r.push_str("\\\""),
            '\\' => r.push_str("\\\\"),
            '\u{0008}' => r.push_str("\\b"),
            '\u{000C}' => r.push_str("\\f"),
            '\n' => r.push_str("\\n"),
            '\r' => r.push_str("\\r"),
            '\t' => r.push_str("\\t"),
            c if (c as u32) < 0x20 => r.push_str(&format!("\\u{:04x}", c as u32)),
            _ => r.push(c),
        }
    }
    r.push('"');
    r
}

fn json_to_string(val: &Json) -> String {
    match val {
        Json::Null => "null".to_string(),
        Json::Bool(b) => if *b { "true".to_string() } else { "false".to_string() },
        Json::Num(n) => {
            if *n == n.floor() && n.abs() < 1e15 {
                format!("{}", *n as i64)
            } else {
                format!("{}", n)
            }
        }
        Json::Str(s) => json_escape_string(s),
        Json::Arr(items) => {
            let parts: Vec<String> = items.iter().map(|v| json_to_string(v)).collect();
            format!("[{}]", parts.join(","))
        }
        Json::Obj(pairs) => {
            let parts: Vec<String> = pairs
                .iter()
                .map(|(k, v)| format!("{}:{}", json_escape_string(k), json_to_string(v)))
                .collect();
            format!("{{{}}}", parts.join(","))
        }
    }
}

fn parse_csv(data: &[u8]) -> Vec<Vec<String>> {
    let mut start = 0;
    if data.len() >= 3 && data[0] == 0xEF && data[1] == 0xBB && data[2] == 0xBF {
        start = 3;
    }
    let text = String::from_utf8(data[start..].to_vec()).unwrap();
    let chars: Vec<char> = text.chars().collect();
    let mut records: Vec<Vec<String>> = Vec::new();
    let mut cur_rec: Vec<String> = Vec::new();
    let mut cur_field = String::new();
    let mut in_quotes = false;
    let mut pos = 0;
    while pos < chars.len() {
        if in_quotes {
            if chars[pos] == '"' {
                if pos + 1 < chars.len() && chars[pos + 1] == '"' {
                    cur_field.push('"');
                    pos += 2;
                } else {
                    in_quotes = false;
                    pos += 1;
                }
            } else {
                cur_field.push(chars[pos]);
                pos += 1;
            }
        } else {
            match chars[pos] {
                '"' => { in_quotes = true; pos += 1; }
                ',' => {
                    cur_rec.push(std::mem::take(&mut cur_field));
                    pos += 1;
                }
                '\r' if pos + 1 < chars.len() && chars[pos + 1] == '\n' => {
                    cur_rec.push(std::mem::take(&mut cur_field));
                    records.push(std::mem::take(&mut cur_rec));
                    pos += 2;
                }
                '\n' => {
                    cur_rec.push(std::mem::take(&mut cur_field));
                    records.push(std::mem::take(&mut cur_rec));
                    pos += 1;
                }
                _ => { cur_field.push(chars[pos]); pos += 1; }
            }
        }
    }
    if !cur_field.is_empty() || !cur_rec.is_empty() {
        cur_rec.push(cur_field);
        records.push(cur_rec);
    }
    records
}

fn parse_url(url: &str) -> (String, u16, String) {
    let rest = url.strip_prefix("http://").unwrap_or(url);
    let slash_pos = rest.find('/').unwrap_or(rest.len());
    let host_port = &rest[..slash_pos];
    let path = if slash_pos < rest.len() { &rest[slash_pos..] } else { "/" };
    let colon_pos = host_port.rfind(':');
    let (host, port) = if let Some(cp) = colon_pos {
        (
            host_port[..cp].to_string(),
            host_port[cp + 1..].parse::<u16>().unwrap_or(80),
        )
    } else {
        (host_port.to_string(), 80u16)
    };
    (host, port, path.to_string())
}

fn http_post(url: &str, api_key: &str, body: &[u8]) -> (u16, Vec<u8>) {
    let (host, port, path) = parse_url(url);
    let mut stream = TcpStream::connect(format!("{}:{}", host, port)).unwrap();
    let mut req = format!("POST {} HTTP/1.1\r\n", path);
    req.push_str(&format!("Host: {}:{}\r\n", host, port));
    req.push_str(&format!("Authorization: Bearer {}\r\n", api_key));
    req.push_str("Content-Type: application/json\r\n");
    req.push_str(&format!("Content-Length: {}\r\n", body.len()));
    req.push_str("\r\n");
    stream.write_all(req.as_bytes()).unwrap();
    stream.write_all(body).unwrap();
    stream.flush().unwrap();
    let mut resp = Vec::new();
    stream.read_to_end(&mut resp).unwrap();

    let mut hdr_end = resp.len();
    let mut body_start = resp.len();
    for i in 0..resp.len().saturating_sub(3) {
        if resp[i] == b'\r'
            && resp[i + 1] == b'\n'
            && resp[i + 2] == b'\r'
            && resp[i + 3] == b'\n'
        {
            hdr_end = i;
            body_start = i + 4;
            break;
        }
    }
    if body_start == resp.len() {
        for i in 0..resp.len().saturating_sub(1) {
            if resp[i] == b'\n' && resp[i + 1] == b'\n' {
                hdr_end = i;
                body_start = i + 2;
                break;
            }
        }
    }
    let hdr = String::from_utf8_lossy(&resp[..hdr_end]).to_string();
    let status = hdr
        .lines()
        .next()
        .unwrap_or("")
        .splitn(3, ' ')
        .nth(1)
        .unwrap_or("0")
        .parse::<u16>()
        .unwrap_or(0);
    let cl: Option<usize> = hdr
        .lines()
        .find(|l| l.to_lowercase().starts_with("content-length:"))
        .and_then(|l| l[l.find(':').unwrap() + 1..].trim().parse().ok());
    let body_bytes = if let Some(cl) = cl {
        let end = std::cmp::min(body_start + cl, resp.len());
        resp[body_start..end].to_vec()
    } else {
        resp[body_start..].to_vec()
    };
    (status, body_bytes)
}

fn main() {
    let args: Vec<String> = env::args().collect();
    let data_dir = &args[1];
    let base_url = &args[2];
    let url = format!("{}/chat/completions", base_url);

    // Read task.json
    let task_str =
        String::from_utf8(fs::read(format!("{}/task.json", data_dir)).unwrap()).unwrap();
    let task = JsonParser::new(&task_str).parse();
    let api_key = task
        .get("api_key")
        .and_then(|v| v.as_str())
        .unwrap_or("")
        .to_string();
    let model = task
        .get("model")
        .and_then(|v| v.as_str())
        .unwrap_or("")
        .to_string();
    let system = task
        .get("system")
        .and_then(|v| v.as_str())
        .unwrap_or("")
        .to_string();
    let user = task
        .get("user")
        .and_then(|v| v.as_str())
        .unwrap_or("")
        .to_string();
    let tools = task.get("tools").cloned().unwrap_or(Json::Arr(vec![]));

    // Read inventory.csv
    let inv_data = fs::read(format!("{}/inventory.csv", data_dir)).unwrap();
    let inv_records = parse_csv(&inv_data);
    let mut inv_map: HashMap<String, (String, i64, String, i64)> = HashMap::new();
    for rec in inv_records.iter().skip(1) {
        if rec.len() >= 5 {
            inv_map.insert(
                rec[0].clone(),
                (
                    rec[1].clone(),
                    rec[2].parse().unwrap_or(0),
                    rec[3].clone(),
                    rec[4].parse().unwrap_or(0),
                ),
            );
        }
    }

    // Read rates.json
    let rates_str =
        String::from_utf8(fs::read(format!("{}/rates.json", data_dir)).unwrap()).unwrap();
    let rates_json = JsonParser::new(&rates_str).parse();
    let mut rates_map: HashMap<String, i128> = HashMap::new();
    if let Some(rates_obj) = rates_json.get("rates") {
        if let Json::Obj(pairs) = rates_obj {
            for (k, v) in pairs {
                if let Some(n) = v.as_f64() {
                    rates_map.insert(k.clone(), n as i128);
                }
            }
        }
    }

    // Build initial conversation
    let mut conversation: Vec<Json> = vec![
        Json::Obj(vec![
            ("role".into(), Json::Str("system".into())),
            ("content".into(), Json::Str(system)),
        ]),
        Json::Obj(vec![
            ("role".into(), Json::Str("user".into())),
            ("content".into(), Json::Str(user)),
        ]),
    ];

    let mut total_prompt: i64 = 0;
    let mut total_completion: i64 = 0;
    let mut total_total: i64 = 0;
    let mut num_requests: i64 = 0;

    loop {
        let body = Json::Obj(vec![
            ("model".into(), Json::Str(model.clone())),
            ("messages".into(), Json::Arr(conversation.clone())),
            ("tools".into(), tools.clone()),
            ("tool_choice".into(), Json::Str("auto".into())),
        ]);
        let body_str = json_to_string(&body);
        num_requests += 1;

        let (status, resp_body) = http_post(&url, &api_key, body_str.as_bytes());

        if status != 200 {
            let resp_str = String::from_utf8_lossy(&resp_body).to_string();
            let err_json = JsonParser::new(&resp_str).parse();
            let err_msg = err_json
                .get("error")
                .and_then(|e| e.get("message"))
                .and_then(|m| m.as_str())
                .unwrap_or("unknown error")
                .to_string();
            println!("ERROR {} {}", status, err_msg);
            std::process::exit(0);
        }

        let resp_str = String::from_utf8_lossy(&resp_body).to_string();
        let resp = JsonParser::new(&resp_str).parse();

        if let Some(usage) = resp.get("usage") {
            total_prompt += usage
                .get("prompt_tokens")
                .and_then(|v| v.as_i64())
                .unwrap_or(0);
            total_completion += usage
                .get("completion_tokens")
                .and_then(|v| v.as_i64())
                .unwrap_or(0);
            total_total += usage
                .get("total_tokens")
                .and_then(|v| v.as_i64())
                .unwrap_or(0);
        }

        let choice = resp
            .get("choices")
            .and_then(|c| c.as_arr())
            .and_then(|a| a.first())
            .cloned()
            .unwrap_or(Json::Null);
        let finish_reason = choice
            .get("finish_reason")
            .and_then(|v| v.as_str())
            .unwrap_or("")
            .to_string();
        let message = choice.get("message").cloned().unwrap_or(Json::Null);

        if finish_reason == "tool_calls" {
            // SAY
            if let Some(Json::Str(s)) = message.get("content") {
                println!("SAY {}", s);
            }

            // CALL lines
            let tool_calls = message
                .get("tool_calls")
                .and_then(|tc| tc.as_arr())
                .cloned()
                .unwrap_or_default();
            for tc in &tool_calls {
                let id = tc.get("id").and_then(|v| v.as_str()).unwrap_or("");
                let name = tc
                    .get("function")
                    .and_then(|f| f.get("name"))
                    .and_then(|v| v.as_str())
                    .unwrap_or("");
                println!("CALL {} {}", id, name);
            }

            // Execute tools and RESULT lines
            let mut tool_msgs: Vec<Json> = Vec::new();
            for tc in &tool_calls {
                let id = tc
                    .get("id")
                    .and_then(|v| v.as_str())
                    .unwrap_or("")
                    .to_string();
                let name = tc
                    .get("function")
                    .and_then(|f| f.get("name"))
                    .and_then(|v| v.as_str())
                    .unwrap_or("")
                    .to_string();
                let args_str = tc
                    .get("function")
                    .and_then(|f| f.get("arguments"))
                    .and_then(|v| v.as_str())
                    .unwrap_or("{}")
                    .to_string();
                let args_json = JsonParser::new(&args_str).parse();

                let result = match name.as_str() {
                    "inventory_lookup" => {
                        let sku = args_json
                            .get("sku")
                            .and_then(|v| v.as_str())
                            .unwrap_or("");
                        if let Some((n, p, c, s)) = inv_map.get(sku) {
                            format!(
                                "{{\"sku\":{},\"name\":{},\"price_cents\":{},\"currency\":{},\"stock\":{}}}",
                                json_escape_string(sku),
                                json_escape_string(n),
                                p,
                                json_escape_string(c),
                                s
                            )
                        } else {
                            format!(
                                "{{\"error\":{}}}",
                                json_escape_string(&format!("unknown sku: {}", sku))
                            )
                        }
                    }
                    "convert_currency" => {
                        let amount = args_json
                            .get("amount_cents")
                            .and_then(|v| v.as_f64())
                            .unwrap_or(0.0) as i128;
                        let from = args_json
                            .get("from")
                            .and_then(|v| v.as_str())
                            .unwrap_or("");
                        let to = args_json
                            .get("to")
                            .and_then(|v| v.as_str())
                            .unwrap_or("");
                        let rf = *rates_map.get(from).unwrap_or(&1_000_000);
                        let rt = *rates_map.get(to).unwrap_or(&1_000_000);
                        let converted = (2 * amount * rt + rf) / (2 * rf);
                        format!(
                            "{{\"amount_cents\":{},\"currency\":{}}}",
                            converted,
                            json_escape_string(to)
                        )
                    }
                    _ => format!(
                        "{{\"error\":{}}}",
                        json_escape_string(&format!("unknown tool: {}", name))
                    ),
                };

                println!("RESULT {} {}", id, result);
                tool_msgs.push(Json::Obj(vec![
                    ("role".into(), Json::Str("tool".into())),
                    ("tool_call_id".into(), Json::Str(id)),
                    ("content".into(), Json::Str(result)),
                ]));
            }

            // Build assistant message preserving structure
            let mut assistant_msg: Vec<(String, Json)> = Vec::new();
            assistant_msg.push(("role".into(), Json::Str("assistant".into())));
            assistant_msg.push((
                "content".into(),
                message.get("content").cloned().unwrap_or(Json::Null),
            ));
            if let Some(tc) = message.get("tool_calls") {
                assistant_msg.push(("tool_calls".into(), tc.clone()));
            }
            conversation.push(Json::Obj(assistant_msg));
            conversation.extend(tool_msgs);
        } else {
            // stop or other finish_reason
            let content = message
                .get("content")
                .and_then(|v| v.as_str())
                .unwrap_or("")
                .to_string();
            println!("FINAL {}", content);
            println!(
                "USAGE prompt={} completion={} total={} requests={}",
                total_prompt, total_completion, total_total, num_requests
            );
            break;
        }
    }
}

import java.io.*;
import java.nio.*;
import java.nio.file.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        String dir = args[0];
        File[] files = new File(dir).listFiles();
        if (files == null) return;

        List<File> wavFiles = new ArrayList<>();
        for (File f : files) {
            if (f.isFile() && f.getName().endsWith(".wav")) {
                wavFiles.add(f);
            }
        }
        wavFiles.sort((a, b) -> {
            byte[] aBytes = a.getName().getBytes("UTF-8");
            byte[] bBytes = b.getName().getBytes("UTF-8");
            int minLen = Math.min(aBytes.length, bBytes.length);
            for (int i = 0; i < minLen; i++) {
                int cmp = (aBytes[i] & 0xFF) - (bBytes[i] & 0xFF);
                if (cmp != 0) return cmp;
            }
            return aBytes.length - bBytes.length;
        });

        boolean first = true;
        for (File f : wavFiles) {
            if (!first) System.out.println();
            first = false;
            processFile(f);
        }
    }

    static void processFile(File file) throws Exception {
        String name = file.getName();
        byte[] data = Files.readAllBytes(file.toPath());

        if (data.length < 12) {
            System.out.println(name + ": unsupported");
            return;
        }
        if (data[0] != 'R' || data[1] != 'I' || data[2] != 'F' || data[3] != 'F') {
            System.out.println(name + ": unsupported");
            return;
        }
        if (data[8] != 'W' || data[9] != 'A' || data[10] != 'V' || data[11] != 'E') {
            System.out.println(name + ": unsupported");
            return;
        }

        int pos = 12;
        int formatTag = -1;
        int channels = -1;
        int sampleRate = -1;
        int bitsPerSample = -1;
        int effectiveFormat = -1;
        byte[] fmtBody = null;
        int fmtBodyLen = 0;
        byte[] dataBody = null;
        int dataBodyLen = 0;

        while (pos + 8 <= data.length) {
            String chunkId = new String(data, pos, 4, "US-ASCII");
            int chunkSize = readInt32LE(data, pos + 4);
            pos += 8;

            if (chunkId.equals("fmt ")) {
                fmtBodyLen = Math.min(chunkSize, data.length - pos);
                fmtBody = Arrays.copyOfRange(data, pos, pos + fmtBodyLen);
                if (fmtBodyLen >= 16) {
                    formatTag = readInt16LE(fmtBody, 0) & 0xFFFF;
                    channels = readInt16LE(fmtBody, 2) & 0xFFFF;
                    sampleRate = readInt32LE(fmtBody, 4);
                    bitsPerSample = readInt16LE(fmtBody, 14) & 0xFFFF;

                    if (formatTag == 0xFFFE && fmtBodyLen >= 26) {
                        effectiveFormat = readInt16LE(fmtBody, 24) & 0xFFFF;
                    } else {
                        effectiveFormat = formatTag;
                    }
                }
            } else if (chunkId.equals("data")) {
                dataBodyLen = Math.min(chunkSize, data.length - pos);
                dataBody = Arrays.copyOfRange(data, pos, pos + dataBodyLen);
            }

            pos += chunkSize;
            if (chunkSize % 2 != 0) pos++;
        }

        if (effectiveFormat != 1 || bitsPerSample != 16) {
            System.out.println(name + ": unsupported");
            return;
        }
        if (channels < 1 || channels > 2) {
            System.out.println(name + ": unsupported");
            return;
        }
        if (sampleRate != 8000 && sampleRate != 16000) {
            System.out.println(name + ": unsupported");
            return;
        }
        if (dataBody == null) {
            System.out.println(name + ": unsupported");
            return;
        }

        int frameSize = 2 * channels;
        int numFrames = dataBodyLen / frameSize;
        short[] samples = new short[numFrames];
        for (int i = 0; i < numFrames; i++) {
            samples[i] = (short) readInt16LE(dataBody, i * frameSize);
        }

        int N = sampleRate / 50;
        int numBlocks = numFrames / N;

        double[] lowFreqs = {697, 770, 852, 941};
        double[] highFreqs = {1209, 1336, 1477, 1633};

        char[][] keypad = {
            {'1', '2', '3', 'A'},
            {'4', '5', '6', 'B'},
            {'7', '8', '9', 'C'},
            {'*', '0', '#', 'D'}
        };

        char[] labels = new char[numBlocks];
        Arrays.fill(labels, '\0');

        for (int i = 0; i < numBlocks; i++) {
            int offset = i * N;
            double E = 0;
            for (int n = 0; n < N; n++) {
                double x = samples[offset + n];
                E += x * x;
            }

            if (E < 1000000.0 * N) {
                continue;
            }

            double maxLowR = -1;
            int maxLowIdx = -1;
            double maxHighR = -1;
            int maxHighIdx = -1;

            for (int fi = 0; fi < 4; fi++) {
                double r = goertzel(samples, offset, N, lowFreqs[fi], sampleRate, E);
                if (r > maxLowR) {
                    maxLowR = r;
                    maxLowIdx = fi;
                }
            }
            for (int fi = 0; fi < 4; fi++) {
                double r = goertzel(samples, offset, N, highFreqs[fi], sampleRate, E);
                if (r > maxHighR) {
                    maxHighR = r;
                    maxHighIdx = fi;
                }
            }

            if (maxLowR >= 0.1 && maxHighR >= 0.1 && (maxLowR + maxHighR) >= 0.6) {
                labels[i] = keypad[maxLowIdx][maxHighIdx];
            }
        }

        // Bridging
        char[] bridged = Arrays.copyOf(labels, labels.length);
        for (int i = 1; i < numBlocks - 1; i++) {
            if (labels[i] == '\0' && labels[i - 1] != '\0' && labels[i + 1] != '\0' && labels[i - 1] == labels[i + 1]) {
                bridged[i] = labels[i - 1];
            }
        }

        // Events: maximal runs of same digit >= 2 blocks
        List<int[]> events = new ArrayList<>();
        int i = 0;
        while (i < numBlocks) {
            if (bridged[i] == '\0') {
                i++;
                continue;
            }
            char digit = bridged[i];
            int start = i;
            while (i < numBlocks && bridged[i] == digit) {
                i++;
            }
            int end = i - 1;
            if (end - start + 1 >= 2) {
                events.add(new int[]{start, end, digit});
            }
        }

        // Output
        System.out.println(name + ": " + sampleRate + " Hz, " + channels + " ch, " + numBlocks + " blocks");
        for (int[] ev : events) {
            System.out.println((char) ev[2] + " " + (20 * ev[0]) + " " + (20 * (ev[1] + 1)));
        }
        StringBuilder digits = new StringBuilder();
        for (int[] ev : events) {
            digits.append((char) ev[2]);
        }
        System.out.println("digits: " + digits.toString());
    }

    static double goertzel(short[] samples, int offset, int N, double freq, int rate, double E) {
        double c = 2.0 * Math.cos(2.0 * Math.PI * freq / rate);
        double s1 = 0, s2 = 0;
        for (int n = 0; n < N; n++) {
            double s = samples[offset + n] + c * s1 - s2;
            s2 = s1;
            s1 = s;
        }
        double P = s1 * s1 + s2 * s2 - c * s1 * s2;
        return 2.0 * P / (N * E);
    }

    static int readInt16LE(byte[] data, int offset) {
        return (data[offset] & 0xFF) | ((data[offset + 1] & 0xFF) << 8);
    }

    static int readInt32LE(byte[] data, int offset) {
        return (data[offset] & 0xFF) | ((data[offset + 1] & 0xFF) << 8) |
               ((data[offset + 2] & 0xFF) << 16) | ((data[offset + 3] & 0xFF) << 24);
    }
}

