                double r = goertzel(samples, offset, N, highFreqs[fi], sampleRate, E);
                if (r > maxHighR) {
                    maxHighR = r;
                    maxHighIdx = fi;
                }
            }

            if (maxLowR >= 0.1 && maxHighR >= 0.1 && (maxLowR + maxHighR) >= 0.6) {
                labels[i] = keypad[maxLowIdx][maxHighIdx];
            }
        }

        // Bridging
        char[] bridged = Arrays.copyOf(labels, labels.length);
        for (int i = 1; i < numBlocks - 1; i++) {
            if (labels[i] == '\0' && labels[i - 1] != '\0' && labels[i + 1] != '\0' && labels[i - 1] == labels[i + 1]) {
                bridged[i] = labels[i - 1];
            }
        }

        // Events: maximal runs of same digit >= 2 blocks
        List<int[]> events = new ArrayList<>();
        int i = 0;
        while (i < numBlocks) {
            if (bridged[i] == '\0') {
                i++;
                continue;
            }
            char digit = bridged[i];
            int start = i;
            while (i < numBlocks && bridged[i] == digit) {
                i++;
            }
            int end = i - 1;
            if (end - start + 1 >= 2) {
                events.add(new int[]{start, end, digit});
            }
        }

        // Output
        System.out.println(name + ": " + sampleRate + " Hz, " + channels + " ch, " + numBlocks + " blocks");
        for (int[] ev : events) {
            System.out.println((char) ev[2] + " " + (20 * ev[0]) + " " + (20 * (ev[1] + 1)));
        }
        StringBuilder digits = new StringBuilder();
        for (int[] ev : events) {
            digits.append((char) ev[2]);
        }
        System.out.println("digits: " + digits.toString());
    }

    static double goertzel(short[] samples, int offset, int N, double freq, int rate, double E) {
        double c = 2.0 * Math.cos(2.0 * Math.PI * freq / rate);
        double s1 = 0, s2 = 0;
        for (int n = 0; n < N; n++) {
            double s = samples[offset + n] + c * s1 - s2;
            s2 = s1;
            s1 = s;
        }
        double P = s1 * s1 + s2 * s2 - c * s1 * s2;
        return 2.0 * P / (N * E);
    }

    static int readInt16LE(byte[] data, int offset) {
        return (data[offset] & 0xFF) | ((data[offset + 1] & 0xFF) << 8);
    }

    static int readInt32LE(byte[] data, int offset) {
        return (data[offset] & 0xFF) | ((data[offset + 1] & 0xFF) << 8) |
               ((data[offset + 2] & 0xFF) << 16) | ((data[offset + 3] & 0xFF) << 24);
    }
}

import Foundation

func readU16LE(_ data: [UInt8], _ offset: Int) -> Int {
    return Int(data[offset]) | (Int(data[offset + 1]) << 8)
}

func readU32LE(_ data: [UInt8], _ offset: Int) -> Int {
    return Int(data[offset]) | (Int(data[offset + 1]) << 8) | (Int(data[offset + 2]) << 16) | (Int(data[offset + 3]) << 24)
}

func readI16LE(_ data: [UInt8], _ offset: Int) -> Int {
    let val = Int(data[offset]) | (Int(data[offset + 1]) << 8)
    if val >= 32768 { return val - 65536 }
    return val
}

func processFile(path: String, name: String) -> String {
    guard let data = try? Data(contentsOf: URL(fileURLWithPath: path)) else {
        return "\(name): unsupported"
    }
    let bytes = [UInt8](data)

    // Check RIFF header
    guard bytes.count >= 12 else { return "\(name): unsupported" }
    guard bytes[0] == 0x52 && bytes[1] == 0x49 && bytes[2] == 0x46 && bytes[3] == 0x46 else {
        return "\(name): unsupported"
    }
    guard bytes[8] == 0x57 && bytes[9] == 0x41 && bytes[10] == 0x56 && bytes[11] == 0x45 else {
        return "\(name): unsupported"
    }

    // Parse chunks
    var fmtBody: [UInt8]? = nil
    var dataBody: [UInt8]? = nil
    var pos = 12

    while pos + 8 <= bytes.count {
        let chunkId = String(bytes: bytes[pos..<pos+4], encoding: .ascii) ?? ""
        let chunkSize = readU32LE(bytes, pos + 4)
        let bodyStart = pos + 8
        let bodyEnd = min(bodyStart + chunkSize, bytes.count)

        if chunkId == "fmt " {
            fmtBody = Array(bytes[bodyStart..<bodyEnd])
        } else if chunkId == "data" {
            dataBody = Array(bytes[bodyStart..<bodyEnd])
        }

        pos = bodyStart + chunkSize
        if chunkSize % 2 == 1 { pos += 1 }
    }

    guard let fmt = fmtBody, fmt.count >= 16 else { return "\(name): unsupported" }
    guard let dataBytes = dataBody else { return "\(name): unsupported" }

    let formatTag = readU16LE(fmt, 0)
    let channels = readU16LE(fmt, 2)
    let sampleRate = readU32LE(fmt, 4)
    let bitsPerSample = readU16LE(fmt, 14)

    var effectiveFormat = formatTag
    if formatTag == 0xFFFE {
        if fmt.count >= 26 {
            effectiveFormat = readU16LE(fmt, 24)
        } else {
            return "\(name): unsupported"
        }
    }

    guard effectiveFormat == 1 && bitsPerSample == 16 else {
        return "\(name): unsupported"
    }
    guard channels == 1 || channels == 2 else { return "\(name): unsupported" }
    guard sampleRate == 8000 || sampleRate == 16000 else { return "\(name): unsupported" }

    // Extract left channel samples
    let frameSize = 2 * channels
    let numFrames = dataBytes.count / frameSize
    var samples = [Int](repeating: 0, count: numFrames)
    for i in 0..<numFrames {
        samples[i] = readI16LE(dataBytes, i * frameSize)
    }

    // DTMF detection
    let N = sampleRate / 50
    let numBlocks = samples.count / N

    let lowFreqs: [Double] = [697, 770, 852, 941]
    let highFreqs: [Double] = [1209, 1336, 1477, 1633]

    let digitMap: [[String]] = [
        ["1", "2", "3", "A"],
        ["4", "5", "6", "B"],
        ["7", "8", "9", "C"],
        ["*", "0", "#", "D"]
    ]

    // Step 3: detect digits per block
    var labels = [String?](repeating: nil, count: numBlocks)

    for block in 0..<numBlocks {
        let start = block * N

        // Energy
        var E = 0.0
        for i in 0..<N {
            let v = Double(samples[start + i])
            E += v * v
        }

        if E < 1000000.0 * Double(N) { continue }

        // Goertzel for low frequencies
        var rLow = [Double](repeating: 0, count: 4)
        for fi in 0..<4 {
            let f = lowFreqs[fi]
            let c = 2.0 * cos(2.0 * Double.pi * f / Double(sampleRate))
            var s1 = 0.0, s2 = 0.0
            for n in 0..<N {
                let s = Double(samples[start + n]) + c * s1 - s2
                s2 = s1
                s1 = s
            }
            let P = s1 * s1 + s2 * s2 - c * s1 * s2
            rLow[fi] = 2.0 * P / (Double(N) * E)
        }

        // Goertzel for high frequencies
        var rHigh = [Double](repeating: 0, count: 4)
        for fi in 0..<4 {
            let f = highFreqs[fi]
            let c = 2.0 * cos(2.0 * Double.pi * f / Double(sampleRate))
            var s1 = 0.0, s2 = 0.0
            for n in 0..<N {
                let s = Double(samples[start + n]) + c * s1 - s2
                s2 = s1
                s1 = s
            }
            let P = s1 * s1 + s2 * s2 - c * s1 * s2
            rHigh[fi] = 2.0 * P / (Double(N) * E)
        }

        // Find max in each group
        var maxLowIdx = 0
        var maxHighIdx = 0
        for i in 1..<4 {
            if rLow[i] > rLow[maxLowIdx] { maxLowIdx = i }
            if rHigh[i] > rHigh[maxHighIdx] { maxHighIdx = i }
        }

        if rLow[maxLowIdx] >= 0.1 && rHigh[maxHighIdx] >= 0.1 && rLow[maxLowIdx] + rHigh[maxHighIdx] >= 0.6 {
            labels[block] = digitMap[maxLowIdx][maxHighIdx]
        }
    }

    // Step 4: Bridging
    var bridged = labels
    if numBlocks > 2 {
        for i in 1..<numBlocks-1 {
            if labels[i] == nil {
                if let prev = labels[i-1], let next = labels[i+1], prev == next {
                    bridged[i] = prev
                }
            }
        }
    }

    // Step 5: Events
    var events: [(digit: String, start: Int, end: Int)] = []
    var i = 0
    while i < numBlocks {
        if let d = bridged[i] {
            var j = i
            while j + 1 < numBlocks && bridged[j + 1] == d {
                j += 1
            }
            if j - i + 1 >= 2 {
                events.append((digit: d, start: 20 * i, end: 20 * (j + 1)))
            }
            i = j + 1
        } else {
            i += 1
        }
    }

    // Output
    var result = "\(name): \(sampleRate) Hz, \(channels) ch, \(numBlocks) blocks\n"
    for e in events {
        result += "\(e.digit) \(e.start) \(e.end)\n"
    }
    let digitsStr = events.map { $0.digit }.joined()
    result += "digits: \(digitsStr)"

    return result
}

// Main
let args = CommandLine.arguments
guard args.count >= 2 else { exit(1) }

let dir = args[1]
let fm = FileManager.default
guard let entries = try? fm.contentsOfDirectory(atPath: dir) else { exit(1) }

let wavFiles = entries.filter { $0.hasSuffix(".wav") }.sorted { a, b in
    let aBytes = Array(a.utf8)
    let bBytes = Array(b.utf8)
    let minLen = min(aBytes.count, bBytes.count)
    for i in 0..<minLen {
        if aBytes[i] < bBytes[i] { return true }
        if aBytes[i] > bBytes[i] { return false }
    }
    return aBytes.count < bBytes.count
}

var outputs: [String] = []
for file in wavFiles {
    let path = dir + "/" + file
    outputs.append(processFile(path: path, name: file))
}

if !outputs.isEmpty {
    print(outputs.joined(separator: "\n\n"))
}

import * as fs from 'fs';
import * as path from 'path';

const dir = process.argv[2];
const files = fs.readdirSync(dir)
  .filter(f => f.endsWith('.wav'))
  .sort((a, b) => Buffer.compare(Buffer.from(a, 'utf8'), Buffer.from(b, 'utf8')));

const LOW_FREQS = [697, 770, 852, 941];
const HIGH_FREQS = [1209, 1336, 1477, 1633];

const KEYPAD: string[][] = [
  ['1', '2', '3', 'A'],
  ['4', '5', '6', 'B'],
  ['7', '8', '9', 'C'],
  ['*', '0', '#', 'D'],
];

interface WavInfo {
  supported: boolean;
  rate: number;
  channels: number;
  samples: number[];
}

function parseWav(filepath: string): WavInfo {
  const buf = fs.readFileSync(filepath);

  if (buf.length < 12) return { supported: false, rate: 0, channels: 0, samples: [] };
  if (buf.toString('ascii', 0, 4) !== 'RIFF') return { supported: false, rate: 0, channels: 0, samples: [] };
  if (buf.toString('ascii', 8, 12) !== 'WAVE') return { supported: false, rate: 0, channels: 0, samples: [] };

  let offset = 12;
  let fmtBody: Buffer | null = null;
  let dataBody: Buffer | null = null;

  while (offset + 8 <= buf.length) {
    const id = buf.toString('ascii', offset, offset + 4);
    const size = buf.readUInt32LE(offset + 4);
    const bodyStart = offset + 8;

    if (id === 'fmt ') {
      fmtBody = buf.subarray(bodyStart, bodyStart + size);
    } else if (id === 'data') {
      dataBody = buf.subarray(bodyStart, bodyStart + size);
    }

    offset = bodyStart + size + (size % 2);
  }

  if (!fmtBody || !dataBody) return { supported: false, rate: 0, channels: 0, samples: [] };

  const formatTag = fmtBody.readUInt16LE(0);
  const channels = fmtBody.readUInt16LE(2);
  const rate = fmtBody.readUInt32LE(4);
  const bitsPerSample = fmtBody.readUInt16LE(14);

  let effectiveFormat = formatTag;
  if (formatTag === 0xFFFE) {
    if (fmtBody.length < 26) return { supported: false, rate, channels, samples: [] };
    effectiveFormat = fmtBody.readUInt16LE(24);
  }

  if (effectiveFormat !== 1 || bitsPerSample !== 16) {
    return { supported: false, rate, channels, samples: [] };
  }

  if ((channels !== 1 && channels !== 2) || (rate !== 8000 && rate !== 16000)) {
    return { supported: false, rate, channels, samples: [] };
  }

  const frameSize = 2 * channels;
  const numFrames = Math.floor(dataBody.length / frameSize);
  const samples: number[] = new Array(numFrames);

  for (let i = 0; i < numFrames; i++) {
    samples[i] = dataBody.readInt16LE(i * frameSize);
  }

  return { supported: true, rate, channels, samples };
}

function goertzelPower(samples: number[], start: number, N: number, freq: number, rate: number): number {
  const c = 2 * Math.cos(2 * Math.PI * freq / rate);
  let s1 = 0, s2 = 0;
  for (let n = 0; n < N; n++) {
    const s = samples[start + n] + c * s1 - s2;
    s2 = s1;
    s1 = s;
  }
  return s1 * s1 + s2 * s2 - c * s1 * s2;
}

function detectDigit(samples: number[], blockStart: number, N: number, rate: number): string | null {
  let E = 0;
  for (let n = 0; n < N; n++) {
    const v = samples[blockStart + n];
    E += v * v;
  }

  if (E < 1000000 * N) return null;

  let maxLowR = -1, maxLowIdx = 0;
  let maxHighR = -1, maxHighIdx = 0;

  for (let i = 0; i < 4; i++) {
    const P = goertzelPower(samples, blockStart, N, LOW_FREQS[i], rate);
    const r = 2 * P / (N * E);
    if (r > maxLowR) {
      maxLowR = r;
      maxLowIdx = i;
    }
  }

  for (let i = 0; i < 4; i++) {
    const P = goertzelPower(samples, blockStart, N, HIGH_FREQS[i], rate);
    const r = 2 * P / (N * E);
    if (r > maxHighR) {
      maxHighR = r;
      maxHighIdx = i;
    }
  }

  if (maxLowR >= 0.1 && maxHighR >= 0.1 && maxLowR + maxHighR >= 0.6) {
    return KEYPAD[maxLowIdx][maxHighIdx];
  }

  return null;
}

const results: string[] = [];

for (const file of files) {
  const filepath = path.join(dir, file);
  const info = parseWav(filepath);

  if (!info.supported) {
    results.push(`${file}: unsupported`);
    continue;
  }

  const { rate, channels, samples } = info;
  const N = rate / 50;
  const numBlocks = Math.floor(samples.length / N);

  const labels: (string | null)[] = new Array(numBlocks);
  for (let i = 0; i < numBlocks; i++) {
    labels[i] = detectDigit(samples, i * N, N, rate);
  }

  // Bridging: use original labels for decision
  const bridged: (string | null)[] = [...labels];
  for (let i = 1; i < numBlocks - 1; i++) {
    if (labels[i] === null && labels[i - 1] !== null && labels[i + 1] !== null && labels[i - 1] === labels[i + 1]) {
      bridged[i] = labels[i - 1];
    }
  }

  // Events: maximal runs of same digit, length >= 2
  const events: { digit: string; start: number; end: number }[] = [];
  let i = 0;
  while (i < numBlocks) {
    if (bridged[i] !== null) {
      const digit = bridged[i]!;
      const startIdx = i;
      while (i < numBlocks && bridged[i] === digit) i++;
      const endIdx = i - 1;
      if (endIdx - startIdx + 1 >= 2) {
        events.push({ digit, start: 20 * startIdx, end: 20 * (endIdx + 1) });
      }
    } else {
      i++;
    }
  }

  const lines: string[] = [];
  lines.push(`${file}: ${rate} Hz, ${channels} ch, ${numBlocks} blocks`);
  for (const ev of events) {
    lines.push(`${ev.digit} ${ev.start} ${ev.end}`);
  }
  lines.push(`digits: ${events.map(e => e.digit).join('')}`);
  results.push(lines.join('\n'));
}

process.stdout.write(results.join('\n\n') + '\n');

import sys
import struct
import datetime
import os


def parse_tzif(filepath):
    with open(filepath, 'rb') as f:
        data = f.read()

    pos = 0
    assert data[pos:pos + 4] == b'TZif'
    pos = 20
    isutcnt1, isstdcnt1, leapcnt1, timecnt1, typecnt1, charcnt1 = struct.unpack('>6I', data[pos:pos + 24])
    pos += 24
    block1_size = timecnt1 * 4 + timecnt1 + typecnt1 * 6 + charcnt1 + leapcnt1 * 8 + isstdcnt1 + isutcnt1
    pos += block1_size

    assert data[pos:pos + 4] == b'TZif'
    pos += 20
    isutcnt2, isstdcnt2, leapcnt2, timecnt2, typecnt2, charcnt2 = struct.unpack('>6I', data[pos:pos + 24])
    pos += 24

    transition_times = []
    for i in range(timecnt2):
        t = struct.unpack('>q', data[pos:pos + 8])[0]
        transition_times.append(t)
        pos += 8

    type_indices = list(data[pos:pos + timecnt2])
    pos += timecnt2

    types = []
    for i in range(typecnt2):
        gmtoff, isdst, abbrind = struct.unpack('>lBB', data[pos:pos + 6])
        types.append((gmtoff, isdst, abbrind))
        pos += 6

    abbr_chars = data[pos:pos + charcnt2]
    pos += charcnt2
    pos += leapcnt2 * 12 + isstdcnt2 + isutcnt2

    posix_str = ""
    if pos < len(data) and data[pos:pos + 1] == b'\n':
        pos += 1
        end = data.index(b'\n', pos)
        posix_str = data[pos:end].decode('ascii')

    abbrs = []
    for i in range(typecnt2):
        abbrind = types[i][2]
        end = abbr_chars.index(b'\x00', abbrind)
        abbrs.append(abbr_chars[abbrind:end].decode('ascii'))

    return transition_times, type_indices, types, abbrs, posix_str


def parse_posix_tz(s):
    if not s:
        return None

    pos = [0]

    def parse_name():
        if s[pos[0]] == '<':
            end = s.index('>', pos[0])
            name = s[pos[0] + 1:end]
            pos[0] = end + 1
            return name
        else:
            start = pos[0]
            while pos[0] < len(s) and s[pos[0]].isalpha():
                pos[0] += 1
            return s[start:pos[0]]

    def parse_offset():
        sign = 1
        if pos[0] < len(s) and s[pos[0]] == '-':
            sign = -1
            pos[0] += 1
        elif pos[0] < len(s) and s[pos[0]] == '+':
            pos[0] += 1

        hh_start = pos[0]
        while pos[0] < len(s) and s[pos[0]].isdigit():
            pos[0] += 1
        hh = int(s[hh_start:pos[0]])

        mm = 0
        ss = 0
        if pos[0] < len(s) and s[pos[0]] == ':':
            pos[0] += 1
            mm_start = pos[0]
            while pos[0] < len(s) and s[pos[0]].isdigit():
                pos[0] += 1
            mm = int(s[mm_start:pos[0]])

            if pos[0] < len(s) and s[pos[0]] == ':':
                pos[0] += 1
                ss_start = pos[0]
                while pos[0] < len(s) and s[pos[0]].isdigit():
                    pos[0] += 1
                ss = int(s[ss_start:pos[0]])

        return sign * (hh * 3600 + mm * 60 + ss)

    def parse_rule():
        assert s[pos[0]] == 'M'
        pos[0] += 1
        m_start = pos[0]
        while s[pos[0]] != '.':
            pos[0] += 1
        m = int(s[m_start:pos[0]])
        pos[0] += 1
        w_start = pos[0]
        while s[pos[0]] != '.':
            pos[0] += 1
        w = int(s[w_start:pos[0]])
        pos[0] += 1
        d_start = pos[0]
        while pos[0] < len(s) and s[pos[0]].isdigit():
            pos[0] += 1
        d = int(s[d_start:pos[0]])

        time = 2 * 3600
        if pos[0] < len(s) and s[pos[0]] == '/':
            pos[0] += 1
            time = parse_offset()

        return (m, w, d, time)

    std_name = parse_name()
    std_offset = parse_offset()

    dst_name = None
    dst_offset = None
    start_rule = None
    end_rule = None

    if pos[0] < len(s) and s[pos[0]] != ',':
        dst_name = parse_name()
        if pos[0] < len(s) and (s[pos[0]].isdigit() or s[pos[0]] in '+-'):
            dst_offset = parse_offset()
        if dst_offset is None:
            dst_offset = std_offset - 3600

    if pos[0] < len(s) and s[pos[0]] == ',':
        pos[0] += 1
        start_rule = parse_rule()
        pos[0] += 1
        end_rule = parse_rule()

    return {
        'std_name': std_name,
        'std_offset': std_offset,
        'dst_name': dst_name,
        'dst_offset': dst_offset,
        'start_rule': start_rule,
        'end_rule': end_rule,
    }


def find_mwd(year, month, week, day):
    py_day = (day + 6) % 7
    first = datetime.date(year, month, 1)
    delta = (py_day - first.weekday()) % 7
    first_occ = first + datetime.timedelta(days=delta)

    if week <= 4:
        result = first_occ + datetime.timedelta(days=(week - 1) * 7)
    else:
        if month == 12:
            last = datetime.date(year, 12, 31)
        else:
            last = datetime.date(year, month + 1, 1) - datetime.timedelta(days=1)
        delta2 = (last.weekday() - py_day) % 7
        result = last - datetime.timedelta(days=delta2)

    return result


def footer_transition_utc(rule, offset, year):
    date = find_mwd(year, rule[0], rule[1], rule[2])
    epoch = datetime.date(1970, 1, 1)
    days = (date - epoch).days
    local_seconds = days * 86400 + rule[3]
    utc_seconds = local_seconds + offset
    return utc_seconds


def is_dst_footer(t, footer):
    if not footer or not footer['dst_name'] or not footer['start_rule']:
        return False

    dt = datetime.datetime(1970, 1, 1) + datetime.timedelta(seconds=t)
    year = dt.year

    for y in [year - 1, year, year + 1]:
        try:
            start_utc = footer_transition_utc(footer['start_rule'], footer['std_offset'], y)
            end_utc = footer_transition_utc(footer['end_rule'], footer['dst_offset'], y)
        except (ValueError, OverflowError):
            continue

        if start_utc < end_utc:
            if start_utc <= t < end_utc:
                return True
        else:
            if t >= start_utc or t < end_utc:
                return True

    return False


def get_offset(t, transitions, type_indices, types, abbrs, footer):
    if not transitions:
        if footer and footer['dst_name'] and footer['start_rule']:
            if is_dst_footer(t, footer):
                return (-footer['dst_offset'], 1, footer['dst_name'])
            else:
                return (-footer['std_offset'], 0, footer['std_name'])
        elif footer:
            return (-footer['std_offset'], 0, footer['std_name'])
        elif types:
            return (types[0][0], types[0][1], abbrs[0])
        else:
            return (0, 0, "UTC")

    if t < transitions[0]:
        return (types[0][0], types[0][1], abbrs[0])

    if t > transitions[-1]:
        if footer and footer['dst_name'] and footer['start_rule']:
            if is_dst_footer(t, footer):
                return (-footer['dst_offset'], 1, footer['dst_name'])
            else:
                return (-footer['std_offset'], 0, footer['std_name'])
        elif footer:
            return (-footer['std_offset'], 0, footer['std_name'])
        else:
            idx = type_indices[-1]
            return (types[idx][0], types[idx][1], abbrs[idx])

    lo, hi = 0, len(transitions) - 1
    while lo < hi:
        mid = (lo + hi + 1) // 2
        if transitions[mid] <= t:
            lo = mid
        else:
            hi = mid - 1

    idx = type_indices[lo]
    return (types[idx][0], types[idx][1], abbrs[idx])


def format_offset(utc_offset):
    sign = '+' if utc_offset >= 0 else '-'
    abs_off = abs(utc_offset)
    h = abs_off // 3600
    m = (abs_off % 3600) // 60
    s = abs_off % 60
    result = f"{sign}{h:02d}:{m:02d}"
    if s != 0:
        result += f":{s:02d}"
    return result


def format_local(t, utc_offset):
    local_t = t + utc_offset
    days = local_t // 86400
    rem = local_t % 86400
    if rem < 0:
        days -= 1
        rem += 86400

    date = datetime.date(1970, 1, 1) + datetime.timedelta(days=days)
    h = rem // 3600
    m = (rem % 3600) // 60
    s = rem % 60

    offset_str = format_offset(utc_offset)
    return f"{date.year:04d}-{date.month:02d}-{date.day:02d}T{h:02d}:{m:02d}:{s:02d}{offset_str}"


def parse_wall_clock(s):
    date_part, time_part = s.split('T')
    y, m, d = map(int, date_part.split('-'))
    h, mi, sec = map(int, time_part.split(':'))
    date = datetime.date(y, m, d)
    epoch = datetime.date(1970, 1, 1)
    days = (date - epoch).days
    return days * 86400 + h * 3600 + mi * 60 + sec


def get_all_offsets(transitions, type_indices, types, footer):
    offsets = set()
    for i in range(len(types)):
        offsets.add(types[i][0])
    if footer:
        offsets.add(-footer['std_offset'])
        if footer['dst_offset'] is not None:
            offsets.add(-footer['dst_offset'])
    return offsets


def find_gap_old_offset(wall_clock, transitions, type_indices, types, abbrs, footer):
    all_trans = []

    if transitions:
        for i in range(len(transitions)):
            T = transitions[i]
            old_off = types[0][0] if i == 0 else types[type_indices[i - 1]][0]
            new_off = types[type_indices[i]][0]
            if new_off > old_off:
                all_trans.append((T, old_off, new_off))

    # Transition from last TZif to footer
    if transitions and footer:
        last_offset = types[type_indices[-1]][0]
        t_check = transitions[-1] + 1
        if footer['dst_name'] and footer['start_rule']:
            if is_dst_footer(t_check, footer):
                footer_off = -footer['dst_offset']
            else:
                footer_off = -footer['std_offset']
        else:
            footer_off = -footer['std_offset']
        if footer_off > last_offset:
            all_trans.append((t_check, last_offset, footer_off))

    # Footer spring-forward transitions
    if footer and footer['dst_name'] and footer['start_rule']:
        std_off = -footer['std_offset']
        dst_off = -footer['dst_offset']
        if dst_off > std_off:
            approx_utc = wall_clock + footer['std_offset']
            try:
                dt = datetime.datetime(1970, 1, 1) + datetime.timedelta(seconds=approx_utc)
                year = dt.year
            except (OverflowError, ValueError):
                year = 2000

            last_tzif = transitions[-1] if transitions else float('-inf')

            for y in range(year - 2, year + 3):
                try:
                    start_utc = footer_transition_utc(footer['start_rule'], footer['std_offset'], y)
                    if start_utc > last_tzif:
                        all_trans.append((start_utc, std_off, dst_off))
                except (ValueError, OverflowError):
                    pass

    for T, old_off, new_off in all_trans:
        if T + old_off <= wall_clock < T + new_off:
            return old_off

    return None


def main():
    if len(sys.argv) < 2:
        sys.exit(1)

    directory = sys.argv[1]

    with open(os.path.join(directory, 'queries.txt'), 'r') as f:
        lines = f.readlines()

    tz_cache = {}

    def get_tz(filename):
        if filename not in tz_cache:
            path = os.path.join(directory, filename)
            transitions, type_indices, types, abbrs, posix_str = parse_tzif(path)
            footer = parse_posix_tz(posix_str)
            tz_cache[filename] = (transitions, type_indices, types, abbrs, footer)
        return tz_cache[filename]

    output_lines = []

    for line in lines:
        line = line.rstrip('\n').rstrip('\r')
        if not line.strip():
            continue

        parts = line.split(' ')
        query_type = parts[0]
        filename = parts[1]

        transitions, type_indices, types, abbrs, footer = get_tz(filename)

        if query_type == 'UTC':
            t = int(parts[2])
            utc_offset, isdst, abbr = get_offset(t, transitions, type_indices, types, abbrs, footer)
            local_str = format_local(t, utc_offset)
            output_lines.append(f"{line} -> {local_str} {abbr}")

        elif query_type == 'LOCAL':
            wall_str = parts[2]
            wall_clock = parse_wall_clock(wall_str)

            offsets = get_all_offsets(transitions, type_indices, types, footer)

            results = []
            for o in sorted(offsets):
                t = wall_clock - o
                actual_offset, _, abbr = get_offset(t, transitions, type_indices, types, abbrs, footer)
                if actual_offset == o:
                    results.append((t, o, abbr))

            results.sort(key=lambda x: x[0])

            if len(results) == 1:
                t, o, abbr = results[0]
                offset_str = format_offset(o)
                output_lines.append(f"{line} -> {t} {offset_str} {abbr}")
            elif len(results) >= 2:
                parts_out = []
                for t, o, abbr in results:
                    offset_str = format_offset(o)
                    parts_out.append(f"{t} {offset_str} {abbr}")
                output_lines.append(f"{line} -> {' | '.join(parts_out)}")
            else:
                # Gap
                old_offset = find_gap_old_offset(wall_clock, transitions, type_indices, types, abbrs, footer)
                if old_offset is None:
                    # Fallback: try simple approach
                    for o in sorted(offsets):
                        t = wall_clock - o
                        actual_offset, _, _ = get_offset(t, transitions, type_indices, types, abbrs, footer)
                        if actual_offset > o:
                            old_offset = o
                            break
                        if actual_offset < o:
                            old_offset = actual_offset
                            break

                if old_offset is not None:
                    t = wall_clock - old_offset
                    actual_offset, _, abbr = get_offset(t, transitions, type_indices, types, abbrs, footer)
                    local_str = format_local(t, actual_offset)
                    output_lines.append(f"{line} -> GAP {t} {local_str} {abbr}")
                else:
                    output_lines.append(f"{line} -> ERROR")

    print('\n'.join(output_lines))


if __name__ == '__main__':
    main()

import sys
import struct
import datetime
import os


def parse_tzif(filepath):
    with open(filepath, 'rb') as f:
        data = f.read()

    pos = 0
    assert data[pos:pos + 4] == b'TZif'
    pos = 20
    isutcnt1, isstdcnt1, leapcnt1, timecnt1, typecnt1, charcnt1 = struct.unpack('>6I', data[pos:pos + 24])
    pos += 24
    block1_size = timecnt1 * 4 + timecnt1 + typecnt1 * 6 + charcnt1 + leapcnt1 * 8 + isstdcnt1 + isutcnt1
    pos += block1_size

    assert data[pos:pos + 4] == b'TZif'
    pos += 20
    isutcnt2, isstdcnt2, leapcnt2, timecnt2, typecnt2, charcnt2 = struct.unpack('>6I', data[pos:pos + 24])
    pos += 24

    transition_times = []
    for i in range(timecnt2):
        t = struct.unpack('>q', data[pos:pos + 8])[0]
        transition_times.append(t)
        pos += 8

    type_indices = list(data[pos:pos + timecnt2])
    pos += timecnt2

    types = []
    for i in range(typecnt2):
        gmtoff, isdst, abbrind = struct.unpack('>lBB', data[pos:pos + 6])
        types.append((gmtoff, isdst, abbrind))
        pos += 6

    abbr_chars = data[pos:pos + charcnt2]
    pos += charcnt2
    pos += leapcnt2 * 12 + isstdcnt2 + isutcnt2

    posix_str = ""
    if pos < len(data) and data[pos:pos + 1] == b'\n':
        pos += 1
        end = data.index(b'\n', pos)
        posix_str = data[pos:end].decode('ascii')

    abbrs = []
    for i in range(typecnt2):
        abbrind = types[i][2]
        end = abbr_chars.index(b'\x00', abbrind)
        abbrs.append(abbr_chars[abbrind:end].decode('ascii'))

    return transition_times, type_indices, types, abbrs, posix_str


def parse_posix_tz(s):
    if not s:
        return None

    pos = [0]

    def parse_name():
        if pos[0] < len(s) and s[pos[0]] == '<':
            end = s.index('>', pos[0])
            name = s[pos[0] + 1:end]
            pos[0] = end + 1
            return name
        else:
            start = pos[0]
            while pos[0] < len(s) and s[pos[0]].isalpha():
                pos[0] += 1
            return s[start:pos[0]]

    def parse_offset():
        sign = 1
        if pos[0] < len(s) and s[pos[0]] == '-':
            sign = -1
            pos[0] += 1
        elif pos[0] < len(s) and s[pos[0]] == '+':
            pos[0] += 1

        hh_start = pos[0]
        while pos[0] < len(s) and s[pos[0]].isdigit():
            pos[0] += 1
        hh = int(s[hh_start:pos[0]])

        mm = 0
        ss = 0
        if pos[0] < len(s) and s[pos[0]] == ':':
            pos[0] += 1
            mm_start = pos[0]
            while pos[0] < len(s) and s[pos[0]].isdigit():
                pos[0] += 1
            mm = int(s[mm_start:pos[0]])

            if pos[0] < len(s) and s[pos[0]] == ':':
                pos[0] += 1
                ss_start = pos[0]
                while pos[0] < len(s) and s[pos[0]].isdigit():
                    pos[0] += 1
                ss = int(s[ss_start:pos[0]])

        return sign * (hh * 3600 + mm * 60 + ss)

    def parse_rule():
        assert s[pos[0]] == 'M'
        pos[0] += 1
        m_start = pos[0]
        while s[pos[0]] != '.':
            pos[0] += 1
        m = int(s[m_start:pos[0]])
        pos[0] += 1
        w_start = pos[0]
        while s[pos[0]] != '.':
            pos[0] += 1
        w = int(s[w_start:pos[0]])
        pos[0] += 1
        d_start = pos[0]
        while pos[0] < len(s) and s[pos[0]].isdigit():
            pos[0] += 1
        d = int(s[d_start:pos[0]])

        time = 2 * 3600
        if pos[0] < len(s) and s[pos[0]] == '/':
            pos[0] += 1
            time = parse_offset()

        return (m, w, d, time)

    std_name = parse_name()
    std_offset = parse_offset()

    dst_name = None
    dst_offset = None
    start_rule = None
    end_rule = None

    if pos[0] < len(s) and s[pos[0]] != ',':
        dst_name = parse_name()
        if pos[0] < len(s) and (s[pos[0]].isdigit() or s[pos[0]] in '+-'):
            dst_offset = parse_offset()
        if dst_offset is None:
            dst_offset = std_offset - 3600

    if pos[0] < len(s) and s[pos[0]] == ',':
        pos[0] += 1
        start_rule = parse_rule()
        pos[0] += 1
        end_rule = parse_rule()

    return {
        'std_name': std_name,
        'std_offset': std_offset,
        'dst_name': dst_name,
        'dst_offset': dst_offset,
        'start_rule': start_rule,
        'end_rule': end_rule,
    }


def find_mwd(year, month, week, day):
    py_day = (day + 6) % 7
    first = datetime.date(year, month, 1)
    delta = (py_day - first.weekday()) % 7
    first_occ = first + datetime.timedelta(days=delta)

    if week <= 4:
        result = first_occ + datetime.timedelta(days=(week - 1) * 7)
    else:
        if month == 12:
            last = datetime.date(year, 12, 31)
        else:
            last = datetime.date(year, month + 1, 1) - datetime.timedelta(days=1)
        delta2 = (last.weekday() - py_day) % 7
        result = last - datetime.timedelta(days=delta2)

    return result


def footer_transition_utc(rule, offset, year):
    date = find_mwd(year, rule[0], rule[1], rule[2])
    epoch = datetime.date(1970, 1, 1)
    days = (date - epoch).days
    local_seconds = days * 86400 + rule[3]
    utc_seconds = local_seconds + offset
    return utc_seconds


def is_dst_footer(t, footer):
    if not footer or not footer['dst_name'] or not footer['start_rule']:
        return False

    days = t // 86400
    if t < 0 and t % 86400 != 0:
        days -= 1
    try:
        dt = datetime.date(1970, 1, 1) + datetime.timedelta(days=days)
        year = dt.year
    except (OverflowError, ValueError):
        return False

    for y in [year - 1, year, year + 1]:
        try:
            start_utc = footer_transition_utc(footer['start_rule'], footer['std_offset'], y)
            end_utc = footer_transition_utc(footer['end_rule'], footer['dst_offset'], y)
        except (ValueError, OverflowError):
            continue

        if start_utc == end_utc:
            continue
        elif start_utc < end_utc:
            # Northern hemisphere: DST from start to end in same year
            if start_utc <= t < end_utc:
                return True
        else:
            # Southern hemisphere: DST from start in year y to end in year y+1
            try:
                end_utc_next = footer_transition_utc(footer['end_rule'], footer['dst_offset'], y + 1)
            except (ValueError, OverflowError):
                continue
            if start_utc <= t < end_utc_next:
                return True

    return False


def get_offset(t, transitions, type_indices, types, abbrs, footer):
    if not transitions:
        if footer and footer['dst_name'] and footer['start_rule']:
            if is_dst_footer(t, footer):
                return (-footer['dst_offset'], 1, footer['dst_name'])
            else:
                return (-footer['std_offset'], 0, footer['std_name'])
        elif footer:
            return (-footer['std_offset'], 0, footer['std_name'])
        elif types:
            return (types[0][0], types[0][1], abbrs[0])
        else:
            return (0, 0, "UTC")

    if t < transitions[0]:
        return (types[0][0], types[0][1], abbrs[0])

    if t > transitions[-1]:
        if footer and footer['dst_name'] and footer['start_rule']:
            if is_dst_footer(t, footer):
                return (-footer['dst_offset'], 1, footer['dst_name'])
            else:
                return (-footer['std_offset'], 0, footer['std_name'])
        elif footer:
            return (-footer['std_offset'], 0, footer['std_name'])
        else:
            idx = type_indices[-1]
            return (types[idx][0], types[idx][1], abbrs[idx])

    lo, hi = 0, len(transitions) - 1
    while lo < hi:
        mid = (lo + hi + 1) // 2
        if transitions[mid] <= t:
            lo = mid
        else:
            hi = mid - 1

    idx = type_indices[lo]
    return (types[idx][0], types[idx][1], abbrs[idx])


def format_offset(utc_offset):
    sign = '+' if utc_offset >= 0 else '-'
    abs_off = abs(utc_offset)
    h = abs_off // 3600
    m = (abs_off % 3600) // 60
    s = abs_off % 60
    result = f"{sign}{h:02d}:{m:02d}"
    if s != 0:
        result += f":{s:02d}"
    return result


def format_local(t, utc_offset):
    local_t = t + utc_offset
    days = local_t // 86400
    rem = local_t % 86400
    if rem < 0:
        days -= 1
        rem += 86400

    date = datetime.date(1970, 1, 1) + datetime.timedelta(days=days)
    h = rem // 3600
    m = (rem % 3600) // 60
    s = rem % 60

    offset_str = format_offset(utc_offset)
    return f"{date.year:04d}-{date.month:02d}-{date.day:02d}T{h:02d}:{m:02d}:{s:02d}{offset_str}"


def parse_wall_clock(s):
    date_part, time_part = s.split('T')
    y, m, d = map(int, date_part.split('-'))
    h, mi, sec = map(int, time_part.split(':'))
    date = datetime.date(y, m, d)
    epoch = datetime.date(1970, 1, 1)
    days = (date - epoch).days
    return days * 86400 + h * 3600 + mi * 60 + sec


def get_all_offsets(transitions, type_indices, types, footer):
    offsets = set()
    for i in range(len(types)):
        offsets.add(types[i][0])
    if footer:
        offsets.add(-footer['std_offset'])
        if footer['dst_offset'] is not None:
            offsets.add(-footer['dst_offset'])
    return offsets


def find_gap_old_offset(wall_clock, transitions, type_indices, types, abbrs, footer):
    all_trans = []

    if transitions:
        for i in range(len(transitions)):
            T = transitions[i]
            old_off = types[0][0] if i == 0 else types[type_indices[i - 1]][0]
            new_off = types[type_indices[i]][0]
            if new_off > old_off:
                all_trans.append((T, old_off, new_off))

    # Transition from last TZif entry to footer
    if transitions and footer:
        last_offset = types[type_indices[-1]][0]
        t_check = transitions[-1] + 1
        if footer['dst_name'] and footer['start_rule']:
            if is_dst_footer(t_check, footer):
                footer_off = -footer['dst_offset']
            else:
                footer_off = -footer['std_offset']
        else:
            footer_off = -footer['std_offset']
        if footer_off > last_offset:
            all_trans.append((t_check, last_offset, footer_off))

    # Footer spring-forward transitions
    if footer and footer['dst_name'] and footer['start_rule']:
        std_off = -footer['std_offset']
        dst_off = -footer['dst_offset']
        if dst_off > std_off:
            approx_utc = wall_clock + footer['std_offset']
            try:
                days = approx_utc // 86400
                if approx_utc < 0 and approx_utc % 86400 != 0:
                    days -= 1
                dt = datetime.date(1970, 1, 1) + datetime.timedelta(days=days)
                year = dt.year
            except (OverflowError, ValueError):
                year = 2000

            last_tzif = transitions[-1] if transitions else float('-inf')

            for y in range(year - 2, year + 3):
                try:
                    start_utc = footer_transition_utc(footer['start_rule'], footer['std_offset'], y)
                    if start_utc > last_tzif:
                        all_trans.append((start_utc, std_off, dst_off))
                except (ValueError, OverflowError):
                    pass

    for T, old_off, new_off in all_trans:
        if T + old_off <= wall_clock < T + new_off:
            return old_off

    return None


def main():
    if len(sys.argv) < 2:
        sys.exit(1)

    directory = sys.argv[1]

    with open(os.path.join(directory, 'queries.txt'), 'r') as f:
        lines = f.readlines()

    tz_cache = {}

    def get_tz(filename):
        if filename not in tz_cache:
            path = os.path.join(directory, filename)
            transitions, type_indices, types, abbrs, posix_str = parse_tzif(path)
            footer = parse_posix_tz(posix_str)
            tz_cache[filename] = (transitions, type_indices, types, abbrs, footer)
        return tz_cache[filename]

    output_lines = []

    for line in lines:
        line = line.rstrip('\n').rstrip('\r')
        if not line.strip():
            continue

        parts = line.split(' ')
        query_type = parts[0]
        filename = parts[1]

        transitions, type_indices, types, abbrs, footer = get_tz(filename)

        if query_type == 'UTC':
            t = int(parts[2])
            utc_offset, isdst, abbr = get_offset(t, transitions, type_indices, types, abbrs, footer)
            local_str = format_local(t, utc_offset)
            output_lines.append(f"{line} -> {local_str} {abbr}")

        elif query_type == 'LOCAL':
            wall_str = parts[2]
            wall_clock = parse_wall_clock(wall_str)

            offsets = get_all_offsets(transitions, type_indices, types, footer)

            results = []
            for o in sorted(offsets):
                t = wall_clock - o
                actual_offset, _, abbr = get_offset(t, transitions, type_indices, types, abbrs, footer)
                if actual_offset == o:
                    results.append((t, o, abbr))

            results.sort(key=lambda x: x[0])

            if len(results) == 1:
                t, o, abbr = results[0]
                offset_str = format_offset(o)
                output_lines.append(f"{line} -> {t} {offset_str} {abbr}")
            elif len(results) >= 2:
                parts_out = []
                for t, o, abbr in results:
                    offset_str = format_offset(o)
                    parts_out.append(f"{t} {offset_str} {abbr}")
                output_lines.append(f"{line} -> {' | '.join(parts_out)}")
            else:
                # Gap
                old_offset = find_gap_old_offset(wall_clock, transitions, type_indices, types, abbrs, footer)
                if old_offset is None:
                    # Fallback: try to find the transition that caused the gap
                    for o in sorted(offsets):
                        t = wall_clock - o
                        actual_offset, _, _ = get_offset(t, transitions, type_indices, types, abbrs, footer)
                        if actual_offset > o:
                            old_offset = o
                            break
                        if actual_offset < o:
                            old_offset = actual_offset
                            break

                if old_offset is not None:
                    t = wall_clock - old_offset
                    actual_offset, _, abbr = get_offset(t, transitions, type_indices, types, abbrs, footer)
                    local_str = format_local(t, actual_offset)
                    output_lines.append(f"{line} -> GAP {t} {local_str} {abbr}")
                else:
                    output_lines.append(f"{line} -> ERROR")

    print('\n'.join(output_lines))


if __name__ == '__main__':
    main()

use std::env;
use std::fs;
use std::io::Read;
use std::path::Path;

fn read_u16_le(data: &[u8], offset: usize) -> u16 {
    (data[offset] as u16) | ((data[offset + 1] as u16) << 8)
}

fn read_u32_le(data: &[u8], offset: usize) -> u32 {
    (data[offset] as u32)
        | ((data[offset + 1] as u32) << 8)
        | ((data[offset + 2] as u32) << 16)
        | ((data[offset + 3] as u32) << 24)
}

fn goertzel(block: &[f64], freq: f64, rate: f64, n: usize, e: f64) -> f64 {
    let c = 2.0 * (2.0 * std::f64::consts::PI * freq / rate).cos();
    let mut s1 = 0.0f64;
    let mut s2 = 0.0f64;
    for i in 0..n {
        let s = block[i] + c * s1 - s2;
        s2 = s1;
        s1 = s;
    }
    let p = s1 * s1 + s2 * s2 - c * s1 * s2;
    2.0 * p / (n as f64 * e)
}

fn process_file(name: &str, data: &[u8]) {
    if data.len() < 12 || &data[0..4] != b"RIFF" || &data[8..12] != b"WAVE" {
        println!("{}: unsupported", name);
        return;
    }

    let mut pos = 12;
    let mut fmt_body: Option<Vec<u8>> = None;
    let mut data_body: Option<Vec<u8>> = None;

    while pos + 8 <= data.len() {
        let chunk_id = &data[pos..pos + 4];
        let chunk_size = read_u32_le(data, pos + 4) as usize;
        let body_start = pos + 8;
        let body_end = body_start + chunk_size;

        if body_end > data.len() {
            break;
        }

        if chunk_id == b"fmt " {
            fmt_body = Some(data[body_start..body_end].to_vec());
        } else if chunk_id == b"data" {
            data_body = Some(data[body_start..body_end].to_vec());
        }

        pos = body_end + if chunk_size % 2 == 1 { 1 } else { 0 };
    }

    let fmt = match fmt_body {
        Some(f) => f,
        None => {
            println!("{}: unsupported", name);
            return;
        }
    };
    let data_chunk = match data_body {
        Some(d) => d,
        None => {
            println!("{}: unsupported", name);
            return;
        }
    };

    if fmt.len() < 16 {
        println!("{}: unsupported", name);
        return;
    }

    let format_tag = read_u16_le(&fmt, 0);
    let channels = read_u16_le(&fmt, 2) as usize;
    let sample_rate = read_u32_le(&fmt, 4) as usize;
    let bits_per_sample = read_u16_le(&fmt, 14) as usize;

    let effective_format = if format_tag == 0xFFFE {
        if fmt.len() < 26 {
            println!("{}: unsupported", name);
            return;
        }
        read_u16_le(&fmt, 24)
    } else {
        format_tag
    };

    if effective_format != 1 || bits_per_sample != 16 {
        println!("{}: unsupported", name);
        return;
    }

    if (channels != 1 && channels != 2) || (sample_rate != 8000 && sample_rate != 16000) {
        println!("{}: unsupported", name);
        return;
    }

    // Extract left channel samples
    let bytes_per_frame = 2 * channels;
    let num_frames = data_chunk.len() / bytes_per_frame;

    let mut samples: Vec<f64> = Vec::with_capacity(num_frames);
    for i in 0..num_frames {
        let offset = i * bytes_per_frame;
        let raw = (data_chunk[offset] as u16) | ((data_chunk[offset + 1] as u16) << 8);
        samples.push(raw as i16 as f64);
    }

    // Detection
    let n = sample_rate / 50;
    let num_blocks = samples.len() / n;

    let low_freqs: [f64; 4] = [697.0, 770.0, 852.0, 941.0];
    let high_freqs: [f64; 4] = [1209.0, 1336.0, 1477.0, 1633.0];
    let digit_map: [[char; 4]; 4] = [
        ['1', '2', '3', 'A'],
        ['4', '5', '6', 'B'],
        ['7', '8', '9', 'C'],
        ['*', '0', '#', 'D'],
    ];

    let mut labels: Vec<Option<char>> = vec![None; num_blocks];

    for i in 0..num_blocks {
        let block = &samples[i * n..(i + 1) * n];

        let e: f64 = block.iter().map(|x| x * x).sum();

        if e < 1000000.0 * n as f64 {
            continue;
        }

        let mut best_low_idx = 0usize;
        let mut best_low_r = -1.0f64;
        let mut best_high_idx = 0usize;
        let mut best_high_r = -1.0f64;

        for fi in 0..4 {
            let r = goertzel(block, low_freqs[fi], sample_rate as f64, n, e);
            if r > best_low_r {
                best_low_r = r;
                best_low_idx = fi;
            }
        }

        for fi in 0..4 {
            let r = goertzel(block, high_freqs[fi], sample_rate as f64, n, e);
            if r > best_high_r {
                best_high_r = r;
                best_high_idx = fi;
            }
        }

        if best_low_r >= 0.1 && best_high_r >= 0.1 && best_low_r + best_high_r >= 0.6 {
            labels[i] = Some(digit_map[best_low_idx][best_high_idx]);
        }
    }

    // Bridging
    let mut bridged = labels.clone();
    for i in 0..num_blocks {
        if labels[i].is_none() && i > 0 && i + 1 < num_blocks {
            if labels[i - 1].is_some() && labels[i - 1] == labels[i + 1] {
                bridged[i] = labels[i - 1];
            }
        }
    }

    // Events
    let mut events: Vec<(char, usize, usize)> = Vec::new();
    let mut i = 0;
    while i < num_blocks {
        if let Some(d) = bridged[i] {
            let start = i;
            while i < num_blocks && bridged[i] == Some(d) {
                i += 1;
            }
            let end = i; // exclusive
            if end - start >= 2 {
                events.push((d, 20 * start, 20 * end));
            }
        } else {
            i += 1;
        }
    }

    // Output
    println!("{}: {} Hz, {} ch, {} blocks", name, sample_rate, channels, num_blocks);
    for (d, start, end) in &events {
        println!("{} {} {}", d, start, end);
    }
    let digits: String = events.iter().map(|(d, _, _)| *d).collect();
    println!("digits: {}", digits);
}

fn main() {
    let args: Vec<String> = env::args().collect();
    let dir = &args[1];

    let mut files: Vec<String> = Vec::new();
    let entries = fs::read_dir(dir).unwrap();
    for entry in entries {
        let entry = entry.unwrap();
        let name = entry.file_name().to_string_lossy().to_string();
        if name.ends_with(".wav") {
            files.push(name);
        }
    }
    files.sort();

    let mut first = true;
    for name in &files {
        if !first {
            println!();
        }
        first = false;

        let path = Path::new(dir).join(name);
        let mut data = Vec::new();
        fs::File::open(&path)
            .unwrap()
            .read_to_end(&mut data)
            .unwrap();

        process_file(name, &data);
    }
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <dirent.h>
#include <math.h>
#include <stdint.h>

static uint16_t read_u16(const uint8_t *p) {
    return (uint16_t)(p[0] | (p[1] << 8));
}

static uint32_t read_u32(const uint8_t *p) {
    return (uint32_t)(p[0] | (p[1] << 8) | (p[2] << 16) | ((uint32_t)p[3] << 24));
}

static int16_t read_i16(const uint8_t *p) {
    return (int16_t)(p[0] | (p[1] << 8));
}

static const double low_freqs[4] = {697, 770, 852, 941};
static const double high_freqs[4] = {1209, 1336, 1477, 1633};

static const char keypad[4][4] = {
    {'1', '2', '3', 'A'},
    {'4', '5', '6', 'B'},
    {'7', '8', '9', 'C'},
    {'*', '0', '#', 'D'}
};

typedef struct {
    char *name;
} FileEntry;

static int cmp_files(const void *a, const void *b) {
    const FileEntry *fa = (const FileEntry *)a;
    const FileEntry *fb = (const FileEntry *)b;
    return strcmp(fa->name, fb->name);
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <directory>\n", argv[0]);
        return 1;
    }

    const char *dirpath = argv[1];

    DIR *dir = opendir(dirpath);
    if (!dir) {
        perror("opendir");
        return 1;
    }

    FileEntry *files = NULL;
    int nfiles = 0, cap = 0;
    struct dirent *ent;
    while ((ent = readdir(dir)) != NULL) {
        const char *name = ent->d_name;
        size_t len = strlen(name);
        if (len >= 4 && strcmp(name + len - 4, ".wav") == 0) {
            if (nfiles >= cap) {
                cap = cap ? cap * 2 : 16;
                files = realloc(files, cap * sizeof(FileEntry));
            }
            files[nfiles].name = strdup(name);
            nfiles++;
        }
    }
    closedir(dir);

    qsort(files, nfiles, sizeof(FileEntry), cmp_files);

    for (int fi = 0; fi < nfiles; fi++) {
        if (fi > 0) printf("\n");

        char path[4096];
        snprintf(path, sizeof(path), "%s/%s", dirpath, files[fi].name);

        FILE *fp = fopen(path, "rb");
        if (!fp) {
            printf("%s: unsupported\n", files[fi].name);
            continue;
        }

        fseek(fp, 0, SEEK_END);
        long fsize = ftell(fp);
        fseek(fp, 0, SEEK_SET);

        uint8_t *buf = malloc(fsize > 0 ? fsize : 1);
        if (fsize > 0) {
            size_t rd = fread(buf, 1, fsize, fp);
            (void)rd;
        }
        fclose(fp);

        if (fsize < 12 || memcmp(buf, "RIFF", 4) != 0 || memcmp(buf + 8, "WAVE", 4) != 0) {
            printf("%s: unsupported\n", files[fi].name);
            free(buf);
            continue;
        }

        const uint8_t *fmt_body = NULL;
        uint32_t fmt_size = 0;
        const uint8_t *data_body = NULL;
        uint32_t data_size = 0;

        uint32_t pos = 12;
        while (pos + 8 <= (uint32_t)fsize) {
            const uint8_t *chunk_id = buf + pos;
            uint32_t chunk_size = read_u32(buf + pos + 4);
            uint32_t body_start = pos + 8;

            if (body_start + chunk_size > (uint32_t)fsize)
                break;

            if (memcmp(chunk_id, "fmt ", 4) == 0) {
                fmt_body = buf + body_start;
                fmt_size = chunk_size;
            } else if (memcmp(chunk_id, "data", 4) == 0) {
                data_body = buf + body_start;
                data_size = chunk_size;
            }

            pos = body_start + chunk_size;
            if (chunk_size & 1) pos++;
        }

        if (!fmt_body || !data_body || fmt_size < 16) {
            printf("%s: unsupported\n", files[fi].name);
            free(buf);
            continue;
        }

        uint16_t format_tag = read_u16(fmt_body);
        uint16_t channels = read_u16(fmt_body + 2);
        uint32_t sample_rate = read_u32(fmt_body + 4);
        uint16_t bits_per_sample = read_u16(fmt_body + 14);

        uint16_t effective_format = format_tag;
        if (format_tag == 0xFFFE) {
            if (fmt_size >= 26) {
                effective_format = read_u16(fmt_body + 24);
            } else {
                printf("%s: unsupported\n", files[fi].name);
                free(buf);
                continue;
            }
        }

        if (effective_format != 1 || bits_per_sample != 16 ||
            (channels != 1 && channels != 2) ||
            (sample_rate != 8000 && sample_rate != 16000)) {
            printf("%s: unsupported\n", files[fi].name);
            free(buf);
            continue;
        }

        int frames = (int)(data_size / (2 * channels));
        int16_t *samples = malloc(frames * sizeof(int16_t));
        for (int i = 0; i < frames; i++) {
            samples[i] = read_i16(data_body + (size_t)i * 2 * channels);
        }

        int N = (int)(sample_rate / 50);
        int nblocks = frames / N;

        printf("%s: %u Hz, %u ch, %d blocks\n", files[fi].name, sample_rate, channels, nblocks);

        char *labels = calloc(nblocks, 1);

        for (int b = 0; b < nblocks; b++) {
            int16_t *x = samples + (size_t)b * N;

            double E = 0;
            for (int n = 0; n < N; n++) {
                double v = (double)x[n];
                E += v * v;
            }

            if (E < 1000000.0 * N) {
                labels[b] = 0;
                continue;
            }

            double r_low[4], r_high[4];

            for (int i = 0; i < 4; i++) {
                double f = low_freqs[i];
                double c = 2.0 * cos(2.0 * M_PI * f / (double)sample_rate);
                double s1 = 0, s2 = 0;
                for (int n = 0; n < N; n++) {
                    double s = (double)x[n] + c * s1 - s2;
                    s2 = s1;
                    s1 = s;
                }
                double P = s1 * s1 + s2 * s2 - c * s1 * s2;
                r_low[i] = 2.0 * P / ((double)N * E);
            }

            for (int i = 0; i < 4; i++) {
                double f = high_freqs[i];
                double c = 2.0 * cos(2.0 * M_PI * f / (double)sample_rate);
                double s1 = 0, s2 = 0;
                for (int n = 0; n < N; n++) {
                    double s = (double)x[n] + c * s1 - s2;
                    s2 = s1;
                    s1 = s;
                }
                double P = s1 * s1 + s2 * s2 - c * s1 * s2;
                r_high[i] = 2.0 * P / ((double)N * E);
            }

            int best_low = 0, best_high = 0;
            for (int i = 1; i < 4; i++) {
                if (r_low[i] > r_low[best_low]) best_low = i;
                if (r_high[i] > r_high[best_high]) best_high = i;
            }

            if (r_low[best_low] >= 0.1 && r_high[best_high] >= 0.1 &&
                r_low[best_low] + r_high[best_high] >= 0.6) {
                labels[b] = keypad[best_low][best_high];
            } else {
                labels[b] = 0;
            }
        }

        /* Bridging */
        char *bridged = malloc(nblocks);
        memcpy(bridged, labels, nblocks);
        for (int b = 1; b < nblocks - 1; b++) {
            if (labels[b] == 0 && labels[b - 1] != 0 && labels[b - 1] == labels[b + 1]) {
                bridged[b] = labels[b - 1];
            }
        }

        /* Events */
        char *digits_str = malloc(nblocks + 1);
        int dpos = 0;

        int b = 0;
        while (b < nblocks) {
            if (bridged[b] == 0) { b++; continue; }
            int start = b;
            char digit = bridged[b];
            while (b < nblocks && bridged[b] == digit) b++;
            int end = b;
            if (end - start >= 2) {
                int start_ms = 20 * start;
                int end_ms = 20 * end;
                printf("%c %d %d\n", digit, start_ms, end_ms);
                digits_str[dpos++] = digit;
            }
        }
        digits_str[dpos] = '\0';
        printf("digits: %s\n", digits_str);

        free(digits_str);
        free(bridged);
        free(labels);
        free(samples);
        free(buf);
    }

    for (int i = 0; i < nfiles; i++) free(files[i].name);
    free(files);

    return 0;
}

import java.io.*;
import java.nio.file.*;
import java.util.*;
import java.time.LocalDate;

public class Main {
    static Map<String, TZifData> cache = new HashMap<>();

    static class TZifData {
        long[] transitions;
        int[] typeIndices;
        int[] offsets;
        boolean[] isdst;
        String[] abbrevs;
        String stdAbbr;
        int stdOffset;
        String dstAbbr;
        int dstOffset;
        boolean hasDst;
        boolean hasRule;
        int dstStartMonth, dstStartWeek, dstStartDay, dstStartTime;
        int dstEndMonth, dstEndWeek, dstEndDay, dstEndTime;
    }

    public static void main(String[] args) throws Exception {
        String dir = args[0];
        List<String> lines = Files.readAllLines(Paths.get(dir, "queries.txt"));
        StringBuilder sb = new StringBuilder();
        for (String line : lines) {
            if (line.trim().isEmpty()) continue;
            sb.append(processQuery(dir, line)).append("\n");
        }
        System.out.print(sb);
    }

    static String processQuery(String dir, String line) throws Exception {
        String[] parts = line.split(" ");
        String type = parts[0];
        String file = parts[1];
        TZifData tz = loadTZif(dir, file);
        if (type.equals("UTC")) {
            long t = Long.parseLong(parts[2]);
            return handleUTC(line, t, tz);
        } else {
            return handleLocal(line, parts[2], tz);
        }
    }

    static String handleUTC(String line, long t, TZifData tz) {
        long[] info = getOffsetAndType(t, tz);
        long offset = info[0];
        int typeIdx = (int) info[1];
        long local = t + offset;
        String abbr = getAbbr(tz, typeIdx);
        return line + " -> " + formatLocal(local) + formatOffset(offset) + " " + abbr;
    }

    static String handleLocal(String line, String localStr, TZifData tz) {
        int year = Integer.parseInt(localStr.substring(0, 4));
        int month = Integer.parseInt(localStr.substring(5, 7));
        int day = Integer.parseInt(localStr.substring(8, 10));
        int hour = Integer.parseInt(localStr.substring(11, 13));
        int min = Integer.parseInt(localStr.substring(14, 16));
        int sec = Integer.parseInt(localStr.substring(17, 19));
        long W = fromCalendar(year, month, day, hour, min, sec);

        List<long[]> results = new ArrayList<>();
        int n = tz.transitions.length;

        if (n > 0) {
            // Period before first transition
            long t0 = W - tz.offsets[0];
            if (t0 < tz.transitions[0]) {
                results.add(new long[]{t0, tz.offsets[0], 0});
            }
            // Periods between transitions
            for (int i = 0; i < n - 1; i++) {
                int ti = tz.typeIndices[i];
                long t = W - tz.offsets[ti];
                if (t >= tz.transitions[i] && t < tz.transitions[i + 1]) {
                    results.add(new long[]{t, tz.offsets[ti], ti});
                }
            }
            // Single point at last transition
            int lastTi = tz.typeIndices[n - 1];
            long tLast = W - tz.offsets[lastTi];
            if (tLast == tz.transitions[n - 1]) {
                results.add(new long[]{tLast, tz.offsets[lastTi], lastTi});
            }
            // POSIX TZ period
            checkPosixTZ(W, tz.transitions[n - 1], tz, results);
        } else {
            checkPosixTZ(W, Long.MIN_VALUE, tz, results);
        }

        results.sort((a, b) -> Long.compare(a[0], b[0]));

        if (results.size() == 1) {
            long t = results.get(0)[0];
            long offset = results.get(0)[1];
            int typeIdx = (int) results.get(0)[2];
            return line + " -> " + t + " " + formatOffset(offset) + " " + getAbbr(tz, typeIdx);
        } else if (results.size() >= 2) {
            long t1 = results.get(0)[0], o1 = results.get(0)[1];
            long t2 = results.get(1)[0], o2 = results.get(1)[1];
            String a1 = getAbbr(tz, (int) results.get(0)[2]);
            String a2 = getAbbr(tz, (int) results.get(1)[2]);
            return line + " -> " + t1 + " " + formatOffset(o1) + " " + a1 + " | " + t2 + " " + formatOffset(o2) + " " + a2;
        } else {
            // GAP
            long t = findGapTime(W, tz);
            long[] info = getOffsetAndType(t, tz);
            long localT = t + info[0];
            String abbr = getAbbr(tz, (int) info[1]);
            return line + " -> GAP " + t + " " + formatLocal(localT) + formatOffset(info[0]) + " " + abbr;
        }
    }

    static void checkPosixTZ(long W, long lastTrans, TZifData tz, List<long[]> results) {
        long t = W - tz.stdOffset;
        if (t > lastTrans && !isInDST(t, tz)) {
            results.add(new long[]{t, tz.stdOffset, -1});
        }
        if (tz.hasDst) {
            t = W - tz.dstOffset;
            if (t > lastTrans && isInDST(t, tz)) {
                results.add(new long[]{t, tz.dstOffset, -2});
            }
        }
    }

    static long findGapTime(long W, TZifData tz) {
        int n = tz.transitions.length;
        // Check table transitions for gaps (offset increases)
        for (int i = 0; i < n; i++) {
            int prevTi = (i == 0) ? 0 : tz.typeIndices[i - 1];
            int newTi = tz.typeIndices[i];
            int prevOff = tz.offsets[prevTi];
            int newOff = tz.offsets[newTi];
            if (newOff > prevOff) {
                long gapStart = tz.transitions[i] + prevOff;
                long gapEnd = tz.transitions[i] + newOff;
                if (W >= gapStart && W < gapEnd) {
                    return W - prevOff;
                }
            }
        }
        // Check boundary between last table transition and POSIX TZ
        if (n > 0) {
            int lastTi = tz.typeIndices[n - 1];
            int lastOff = tz.offsets[lastTi];
            long justAfter = tz.transitions[n - 1] + 1;
            int posixOff;
            if (tz.hasDst && isInDST(justAfter, tz)) {
                posixOff = tz.dstOffset;
            } else {
                posixOff = tz.stdOffset;
            }
            if (posixOff > lastOff) {
                long gapStart = tz.transitions[n - 1] + 1 + lastOff;
                long gapEnd = tz.transitions[n - 1] + 1 + posixOff;
                if (W >= gapStart && W < gapEnd) {
                    return W - lastOff;
                }
            }
        }
        // Check POSIX TZ DST starts for gaps
        if (tz.hasDst && tz.hasRule) {
            int year = getYearFromSeconds(W);
            for (int y = year - 2; y <= year + 2; y++) {
                long dstStart = computeDstStart(y, tz);
                if (n > 0 && dstStart <= tz.transitions[n - 1]) continue;
                long gapStart = dstStart + tz.stdOffset;
                long gapEnd = dstStart + tz.dstOffset;
                if (W >= gapStart && W < gapEnd) {
                    return W - tz.stdOffset;
                }
            }
        }
        return W - tz.stdOffset;
    }

    static long[] getOffsetAndType(long t, TZifData tz) {
        int n = tz.transitions.length;
        if (n == 0 || t < tz.transitions[0]) {
            return new long[]{tz.offsets[0], 0};
        }
        if (t > tz.transitions[n - 1]) {
            if (tz.hasDst && isInDST(t, tz)) {
                return new long[]{tz.dstOffset, -2};
            } else {
                return new long[]{tz.stdOffset, -1};
            }
        }
        int lo = 0, hi = n - 1, idx = 0;
        while (lo <= hi) {
            int mid = (lo + hi) >>> 1;
            if (tz.transitions[mid] <= t) {
                idx = mid;
                lo = mid + 1;
            } else {
                hi = mid - 1;
            }
        }
        int typeIdx = tz.typeIndices[idx];
        return new long[]{tz.offsets[typeIdx], typeIdx};
    }

    static String getAbbr(TZifData tz, int typeIdx) {
        if (typeIdx == -1) return tz.stdAbbr;
        if (typeIdx == -2) return tz.dstAbbr;
        return tz.abbrevs[typeIdx];
    }

    static boolean isInDST(long t, TZifData tz) {
        if (!tz.hasDst) return false;
        if (!tz.hasRule) return true;
        int year = getYearFromSeconds(t);
        long latestStart = Long.MIN_VALUE;
        long latestEnd = Long.MIN_VALUE;
        for (int y = year - 1; y <= year + 1; y++) {
            long ds = computeDstStart(y, tz);
            long de = computeDstEnd(y, tz);
            if (ds <= t && ds > latestStart) latestStart = ds;
            if (de <= t && de > latestEnd) latestEnd = de;
        }
        return latestStart > latestEnd;
    }

    static long computeDstStart(int year, TZifData tz) {
        int day = findDayOfMonth(year, tz.dstStartMonth, tz.dstStartWeek, tz.dstStartDay);
        long localMidnight = fromCalendar(year, tz.dstStartMonth, day, 0, 0, 0);
        long localTime = localMidnight + tz.dstStartTime;
        return localTime - tz.stdOffset;
    }

    static long computeDstEnd(int year, TZifData tz) {
        int day = findDayOfMonth(year, tz.dstEndMonth, tz.dstEndWeek, tz.dstEndDay);
        long localMidnight = fromCalendar(year, tz.dstEndMonth, day, 0, 0, 0);
        long localTime = localMidnight + tz.dstEndTime;
        return localTime - tz.dstOffset;
    }

    static int findDayOfMonth(int year, int month, int week, int dayOfWeek) {
        LocalDate first = LocalDate.of(year, month, 1);
        int firstDow = first.getDayOfWeek().getValue() % 7;
        int firstOcc = 1 + ((dayOfWeek - firstDow + 7) % 7);
        if (week <= 4) {
            return firstOcc + (week - 1) * 7;
        } else {
            int dim = first.lengthOfMonth();
            return firstOcc + 7 * ((dim - firstOcc) / 7);
        }
    }

    static int getYearFromSeconds(long t) {
        long days = Math.floorDiv(t, 86400);
        return (int) LocalDate.of(1970, 1, 1).plusDays(days).getYear();
    }

    static long fromCalendar(int year, int month, int day, int hour, int min, int sec) {
        return LocalDate.of(year, month, day).toEpochDay() * 86400L + hour * 3600L + min * 60L + sec;
    }

    static String formatLocal(long localSeconds) {
        long days = Math.floorDiv(localSeconds, 86400);
        long tod = localSeconds - days * 86400;
        LocalDate date = LocalDate.of(1970, 1, 1).plusDays(days);
        int h = (int) (tod / 3600);
        int m = (int) ((tod % 3600) / 60);
        int s = (int) (tod % 60);
        return String.format("%04d-%02d-%02dT%02d:%02d:%02d",
                date.getYear(), date.getMonthValue(), date.getDayOfMonth(), h, m, s);
    }

    static String formatOffset(long offset) {
        boolean neg = offset < 0;
        long abs = Math.abs(offset);
        long h = abs / 3600;
        long m = (abs % 3600) / 60;
        long s = abs % 60;
        String sign = neg ? "-" : "+";
        if (s != 0) {
            return String.format("%s%02d:%02d:%02d", sign, h, m, s);
        } else {
            return String.format("%s%02d:%02d", sign, h, m);
        }
    }

    // --- TZif loading ---

    static TZifData loadTZif(String dir, String file) throws Exception {
        if (cache.containsKey(file)) return cache.get(file);
        byte[] data = Files.readAllBytes(Paths.get(dir, file));
        int pos = 0;
        // First header
        pos += 4; pos += 1; pos += 15;
        int isutcnt1 = readIntBE(data, pos); pos += 4;
        int isstdcnt1 = readIntBE(data, pos); pos += 4;
        int leapcnt1 = readIntBE(data, pos); pos += 4;
        int timecnt1 = readIntBE(data, pos); pos += 4;
        int typecnt1 = readIntBE(data, pos); pos += 4;
        int charcnt1 = readIntBE(data, pos); pos += 4;
        pos += timecnt1 * 4 + timecnt1 + typecnt1 * 6 + charcnt1 + leapcnt1 * 8 + isstdcnt1 + isutcnt1;
        // Second header
        pos += 4; pos += 1; pos += 15;
        int isutcnt = readIntBE(data, pos); pos += 4;
        int isstdcnt = readIntBE(data, pos); pos += 4;
        int leapcnt = readIntBE(data, pos); pos += 4;
        int timecnt = readIntBE(data, pos); pos += 4;
        int typecnt = readIntBE(data, pos); pos += 4;
        int charcnt = readIntBE(data, pos); pos += 4;
        // Second data block
        long[] transitions = new long[timecnt];
        for (int i = 0; i < timecnt; i++) { transitions[i] = readLongBE(data, pos); pos += 8; }
        int[] typeIndices = new int[timecnt];
        for (int i = 0; i < timecnt; i++) { typeIndices[i] = data[pos++] & 0xFF; }
        int[] offsets = new int[typecnt];
        boolean[] isdst = new boolean[typecnt];
        int[] abbrIdx = new int[typecnt];
        for (int i = 0; i < typecnt; i++) {
            offsets[i] = readIntBE(data, pos); pos += 4;
            isdst[i] = data[pos++] != 0;
            abbrIdx[i] = data[pos++] & 0xFF;
        }
        byte[] chars = new byte[charcnt];
        System.arraycopy(data, pos, chars, 0, charcnt); pos += charcnt;
        String[] abbrevs = new String[typecnt];
        for (int i = 0; i < typecnt; i++) {
            int start = abbrIdx[i];
            int end = start;
            while (end < charcnt && chars[end] != 0) end++;
            abbrevs[i] = new String(chars, start, end - start);
        }
        pos += leapcnt * 12;
        pos += isstdcnt;
        pos += isutcnt;
        // Footer
        pos++; // skip \n
        int tzStart = pos;
        while (pos < data.length && data[pos] != '\n') pos++;
        String tzString = new String(data, tzStart, pos - tzStart);

        TZifData tz = new TZifData();
        tz.transitions = transitions;
        tz.typeIndices = typeIndices;
        tz.offsets = offsets;
        tz.isdst = isdst;
        tz.abbrevs = abbrevs;
        parseTZString(tz, tzString);
        cache.put(file, tz);
        return tz;
    }

    static int readIntBE(byte[] data, int pos) {
        return ((data[pos] & 0xFF) << 24) | ((data[pos + 1] & 0xFF) << 16) |
                ((data[pos + 2] & 0xFF) << 8) | (data[pos + 3] & 0xFF);
    }

    static long readLongBE(byte[] data, int pos) {
        return ((long) (data[pos] & 0xFF) << 56) | ((long) (data[pos + 1] & 0xFF) << 48) |
                ((long) (data[pos + 2] & 0xFF) << 40) | ((long) (data[pos + 3] & 0xFF) << 32) |
                ((long) (data[pos + 4] & 0xFF) << 24) | ((long) (data[pos + 5] & 0xFF) << 16) |
                ((long) (data[pos + 6] & 0xFF) << 8) | ((long) (data[pos + 7] & 0xFF));
    }

    // --- POSIX TZ string parsing ---

    static int[] parseTZString(TZifData tz, String s) {
        int pos = 0, len = s.length();
        // std name
        int nameStart = pos;
        if (pos < len && s.charAt(pos) == '<') {
            int end = s.indexOf('>', pos);
            tz.stdAbbr = s.substring(pos + 1, end);
            pos = end + 1;
        } else {
            while (pos < len && Character.isLetter(s.charAt(pos))) pos++;
            tz.stdAbbr = s.substring(nameStart, pos);
        }
        // std offset
        int[] r = parseOffset(s, pos);
        tz.stdOffset = -r[0];
        pos = r[1];
        // dst
        tz.hasDst = false;
        tz.hasRule = false;
        if (pos < len) {
            nameStart = pos;
            if (pos < len && s.charAt(pos) == '<') {
                int end = s.indexOf('>', pos);
                tz.dstAbbr = s.substring(pos + 1, end);
                pos = end + 1;
            } else {
                while (pos < len && Character.isLetter(s.charAt(pos))) pos++;
                tz.dstAbbr = s.substring(nameStart, pos);
            }
            tz.hasDst = true;
            if (pos < len && (s.charAt(pos) == '+' || s.charAt(pos) == '-' || Character.isDigit(s.charAt(pos)))) {
                r = parseOffset(s, pos);
                tz.dstOffset = -r[0];
                pos = r[1];
            } else {
                tz.dstOffset = tz.stdOffset + 3600;
            }
            if (pos < len && s.charAt(pos) == ',') {
                pos++;
                r = parseRule(s, pos, tz, true);
                pos = r[0];
                if (pos < len && s.charAt(pos) == ',') pos++;
                r = parseRule(s, pos, tz, false);
                pos = r[0];
                tz.hasRule = true;
            }
        }
        return new int[]{pos};
    }

    static int[] parseOffset(String s, int pos) {
        int sign = 1;
        if (pos < s.length() && s.charAt(pos) == '+') { pos++; }
        else if (pos < s.length() && s.charAt(pos) == '-') { sign = -1; pos++; }
        int hours = 0;
        while (pos < s.length() && Character.isDigit(s.charAt(pos))) {
            hours = hours * 10 + (s.charAt(pos) - '0'); pos++;
        }
        int minutes = 0, seconds = 0;
        if (pos < s.length() && s.charAt(pos) == ':') {
            pos++;
            while (pos < s.length() && Character.isDigit(s.charAt(pos))) {
                minutes = minutes * 10 + (s.charAt(pos) - '0'); pos++;
            }
            if (pos < s.length() && s.charAt(pos) == ':') {
                pos++;
                while (pos < s.length() && Character.isDigit(s.charAt(pos))) {
                    seconds = seconds * 10 + (s.charAt(pos) - '0'); pos++;
                }
            }
        }
        return new int[]{sign * (hours * 3600 + minutes * 60 + seconds), pos};
    }

    static int[] parseRule(String s, int pos, TZifData tz, boolean isStart) {
        pos++; // skip 'M'
        int month = 0;
        while (pos < s.length() && Character.isDigit(s.charAt(pos))) {
            month = month * 10 + (s.charAt(pos) - '0'); pos++;
        }
        pos++; // skip '.'
        int week = 0;
        while (pos < s.length() && Character.isDigit(s.charAt(pos))) {
            week = week * 10 + (s.charAt(pos) - '0'); pos++;
        }
        pos++; // skip '.'
        int day = 0;
        while (pos < s.length() && Character.isDigit(s.charAt(pos))) {
            day = day * 10 + (s.charAt(pos) - '0'); pos++;
        }
        int time = 2 * 3600;
        if (pos < s.length() && s.charAt(pos) == '/') {
            pos++;
            int[] r = parseOffset(s, pos);
            time = r[0];
            pos = r[1];
        }
        if (isStart) {
            tz.dstStartMonth = month; tz.dstStartWeek = week; tz.dstStartDay = day; tz.dstStartTime = time;
        } else {
            tz.dstEndMonth = month; tz.dstEndWeek = week; tz.dstEndDay = day; tz.dstEndTime = time;
        }
        return new int[]{pos};
    }
}

import Foundation

// Big-endian readers
func readBE32(_ d: [UInt8], _ o: Int) -> Int32 {
    Int32(bitPattern: UInt32(d[o]) << 24 | UInt32(d[o+1]) << 16 | UInt32(d[o+2]) << 8 | UInt32(d[o+3]))
}
func readBE64(_ d: [UInt8], _ o: Int) -> Int64 {
    var v: UInt64 = 0
    for i in 0..<8 { v = v << 8 | UInt64(d[o+i]) }
    return Int64(bitPattern: v)
}

struct LTT { var gmtoff: Int32; var isdst: UInt8; var abbrind: UInt8 }

struct Footer {
    var stdAbbr: String; var stdOff: Int32
    var dstAbbr: String; var dstOff: Int32; var hasDst: Bool
    var sM: Int; var sW: Int; var sD: Int; var sT: Int
    var eM: Int; var eW: Int; var eD: Int; var eT: Int
}

struct TZif {
    var transTimes: [Int64]; var transTypes: [UInt8]; var types: [LTT]; var abbrs: [UInt8]; var footer: Footer?
    func abbr(_ idx: UInt8) -> String {
        var s = ""; var i = Int(idx)
        while i < abbrs.count && abbrs[i] != 0 { s.append(Character(UnicodeScalar(abbrs[i]))); i += 1 }
        return s
    }
}

// Date arithmetic
func isLeap(_ y: Int) -> Bool { (y % 4 == 0 && y % 100 != 0) || y % 400 == 0 }
func dim(_ y: Int, _ m: Int) -> Int {
    let d = [31,28,31,30,31,30,31,31,30,31,30,31]
    return m == 2 && isLeap(y) ? 29 : d[m-1]
}
func dow(_ y: Int, _ m: Int, _ d: Int) -> Int {
    let t = [0,3,2,5,0,3,5,1,4,6,2,4]
    var yr = y; if m < 3 { yr -= 1 }
    return (yr + yr/4 - yr/100 + yr/400 + t[m-1] + d) % 7
}
func daysFromCivil(_ y: Int, _ m: Int, _ d: Int) -> Int {
    let y2 = m <= 2 ? y-1 : y
    let era = (y2 >= 0 ? y2 : y2-399) / 400
    let yoe = y2 - era*400
    let mp = m + (m > 2 ? -3 : 9)
    let doy = (153*mp+2)/5 + d - 1
    let doe = yoe*365 + yoe/4 - yoe/100 + doy
    return era*146097 + doe - 719468
}
func civilFromDays(_ z: Int) -> (Int,Int,Int) {
    let z2 = z + 719468
    let era = (z2 >= 0 ? z2 : z2-146096) / 146097
    let doe = z2 - era*146097
    let yoe = (doe - doe/1460 + doe/36524 - doe/146096) / 365
    let y = yoe + era*400
    let doy = doe - (365*yoe + yoe/4 - yoe/100)
    let mp = (5*doy+2)/153
    let d = doy - (153*mp+2)/5 + 1
    let m = mp < 10 ? mp+3 : mp-9
    return (y + (m <= 2 ? 1 : 0), m, d)
}
func w2s(_ y: Int, _ m: Int, _ d: Int, _ h: Int, _ mi: Int, _ s: Int) -> Int64 {
    Int64(daysFromCivil(y,m,d))*86400 + Int64(h)*3600 + Int64(mi)*60 + Int64(s)
}
func s2w(_ s: Int64) -> (Int,Int,Int,Int,Int,Int) {
    var days = Int(s / 86400); var secs = Int(s % 86400)
    if secs < 0 { secs += 86400; days -= 1 }
    let (y,m,d) = civilFromDays(days)
    return (y, m, d, secs/3600, (secs%3600)/60, secs%60)
}
func nthWD(_ y: Int, _ m: Int, _ wd: Int, _ wk: Int) -> Int {
    if wk == 5 {
        let last = dim(y,m); let ld = dow(y,m,last)
        return last - (ld - wd + 7) % 7
    } else {
        let fd = dow(y,m,1)
        return 1 + (wd - fd + 7) % 7 + (wk-1)*7
    }
}

// Footer parsing
func parseFooter(_ str: String) -> Footer? {
    if str.isEmpty { return nil }
    var pos = str.startIndex; let end = str.endIndex
    func peek() -> Character? { pos < end ? str[pos] : nil }
    func adv() -> Character { let c = str[pos]; pos = str.index(after: pos); return c }
    func parseName() -> String {
        if peek() == "<" { adv(); var n = ""; while pos < end && str[pos] != ">" { n.append(adv()) }; if pos < end { adv() }; return n }
        var n = ""; while pos < end && str[pos].isLetter { n.append(adv()) }; return n
    }
    func parseOff() -> Int32 {
        var sign: Int32 = 1
        if peek() == "+" { adv() } else if peek() == "-" { sign = -1; adv() }
        var h: Int32 = 0; while pos < end && str[pos].isNumber { h = h*10 + Int32(str[pos].asciiValue!-48); adv() }
        var m: Int32 = 0; if peek() == ":" { adv(); while pos < end && str[pos].isNumber { m = m*10 + Int32(str[pos].asciiValue!-48); adv() } }
        var s: Int32 = 0; if peek() == ":" { adv(); while pos < end && str[pos].isNumber { s = s*10 + Int32(str[pos].asciiValue!-48); adv() } }
        return sign*(h*3600+m*60+s)
    }
    func parseTime() -> Int {
        var sign = 1
        if peek() == "+" { adv() } else if peek() == "-" { sign = -1; adv() }
        var h = 0; while pos < end && str[pos].isNumber { h = h*10 + Int(str[pos].asciiValue!-48); adv() }
        var m = 0; if peek() == ":" { adv(); while pos < end && str[pos].isNumber { m = m*10 + Int(str[pos].asciiValue!-48); adv() } }
        var s = 0; if peek() == ":" { adv(); while pos < end && str[pos].isNumber { s = s*10 + Int(str[pos].asciiValue!-48); adv() } }
        return sign*(h*3600+m*60+s)
    }
    func parseRule() -> (Int,Int,Int) {
        var m = 0, w = 0, d = 0
        if peek() == "M" { adv() }
        while pos < end && str[pos].isNumber { m = m*10 + Int(str[pos].asciiValue!-48); adv() }
        if peek() == "." { adv() }
        while pos < end && str[pos].isNumber { w = w*10 + Int(str[pos].asciiValue!-48); adv() }
        if peek() == "." { adv() }
        while pos < end && str[pos].isNumber { d = d*10 + Int(str[pos].asciiValue!-48); adv() }
        return (m,w,d)
    }

    let stdName = parseName()
    let stdPosix = parseOff()
    let stdOff = -stdPosix

    var dstName = ""; var hasDst = false; var dstOff = stdOff + 3600
    if peek() != nil && peek() != "," {
        dstName = parseName(); hasDst = true
        if peek() != nil && peek() != "," { dstOff = -parseOff() }
    }

    var sM=0,sW=0,sD=0,sT=7200,eM=0,eW=0,eD=0,eT=7200
    if hasDst && peek() == "," {
        adv()
        let sr = parseRule(); sM=sr.0; sW=sr.1; sD=sr.2
        if peek() == "/" { adv(); sT = parseTime() }
        if peek() == "," {
            adv()
            let er = parseRule(); eM=er.0; eW=er.1; eD=er.2
            if peek() == "/" { adv(); eT = parseTime() }
        }
    }
    return Footer(stdAbbr: stdName, stdOff: stdOff, dstAbbr: dstName, dstOff: dstOff, hasDst: hasDst,
                  sM:sM, sW:sW, sD:sD, sT:sT, eM:eM, eW:eW, eD:eD, eT:eT)
}

// TZif parsing
func parseTZif(_ data: [UInt8]) -> TZif {
    let isutcnt1 = Int(readBE32(data,20)); let isstdcnt1 = Int(readBE32(data,24))
    let leapcnt1 = Int(readBE32(data,28)); let timecnt1 = Int(readBE32(data,32))
    let typecnt1 = Int(readBE32(data,36)); let charcnt1 = Int(readBE32(data,40))
    let block1Size = timecnt1*4 + timecnt1 + typecnt1*6 + charcnt1 + leapcnt1*8 + isstdcnt1 + isutcnt1
    let b2 = 44 + block1Size
    let isutcnt = Int(readBE32(data,b2+20)); let isstdcnt = Int(readBE32(data,b2+24))
    let leapcnt = Int(readBE32(data,b2+28)); let timecnt = Int(readBE32(data,b2+32))
    let typecnt = Int(readBE32(data,b2+36)); let charcnt = Int(readBE32(data,b2+40))
    var o = b2 + 44
    var transTimes = [Int64](); for _ in 0..<timecnt { transTimes.append(readBE64(data,o)); o += 8 }
    var transTypes = [UInt8](); for _ in 0..<timecnt { transTypes.append(data[o]); o += 1 }
    var types = [LTT](); for _ in 0..<typecnt {
        types.append(LTT(gmtoff: readBE32(data,o), isdst: data[o+4], abbrind: data[o+5])); o += 6
    }
    let abbrs = Array(data[o..<o+charcnt]); o += charcnt
    o += leapcnt*12 + isstdcnt + isutcnt
    if o < data.count && data[o] == 0x0A { o += 1 }
    var fs = ""; while o < data.count && data[o] != 0x0A { fs.append(Character(UnicodeScalar(data[o]))); o += 1 }
    return TZif(transTimes: transTimes, transTypes: transTypes, types: types, abbrs: abbrs, footer: fs.isEmpty ? nil : parseFooter(fs))
}

// Footer transition computation
func dstStart(_ y: Int, _ f: Footer) -> Int64 {
    let d = nthWD(y, f.sM, f.sD, f.sW)
    return w2s(y, f.sM, d, 0, 0, 0) + Int64(f.sT) - Int64(f.stdOff)
}
func dstEnd(_ y: Int, _ f: Footer) -> Int64 {
    let d = nthWD(y, f.eM, f.eD, f.eW)
    return w2s(y, f.eM, d, 0, 0, 0) + Int64(f.eT) - Int64(f.dstOff)
}

func footerOffset(_ t: Int64, _ f: Footer) -> (Int32, String, Bool) {
    if !f.hasDst { return (f.stdOff, f.stdAbbr, false) }
    let (y,_,_,_,_,_) = s2w(t)
    var trs: [(Int64, Bool)] = []
    for yr in (y-1)...(y+1) {
        trs.append((dstStart(yr,f), true))
        trs.append((dstEnd(yr,f), false))
    }
    trs.sort { $0.0 < $1.0 }
    var isdst = trs.first!.1 ? false : true
    for (time, dst) in trs { if time <= t { isdst = dst } else { break } }
    return isdst ? (f.dstOff, f.dstAbbr, true) : (f.stdOff, f.stdAbbr, false)
}

func offsetAt(_ t: Int64, _ tz: TZif) -> (Int32, String, Bool) {
    if tz.transTimes.isEmpty {
        if let f = tz.footer { return footerOffset(t, f) }
        let tp = tz.types[0]; return (tp.gmtoff, tz.abbr(tp.abbrind), tp.isdst != 0)
    }
    let last = tz.transTimes[tz.transTimes.count-1]
    if t < tz.transTimes[0] {
        let tp = tz.types[0]; return (tp.gmtoff, tz.abbr(tp.abbrind), tp.isdst != 0)
    }
    if t > last {
        if let f = tz.footer { return footerOffset(t, f) }
        let tp = tz.types[Int(tz.transTypes[tz.transTypes.count-1])]
        return (tp.gmtoff, tz.abbr(tp.abbrind), tp.isdst != 0)
    }
    var lo = 0, hi = tz.transTimes.count - 1
    while lo < hi { let mid = (lo+hi+1)/2; if tz.transTimes[mid] <= t { lo = mid } else { hi = mid-1 } }
    let tp = tz.types[Int(tz.transTypes[lo])]
    return (tp.gmtoff, tz.abbr(tp.abbrind), tp.isdst != 0)
}

func fmtOff(_ o: Int32) -> String {
    let a = abs(Int(o)); let s = o < 0 ? "-" : "+"
    let h = a/3600, m = (a%3600)/60, sec = a%60
    return sec != 0 ? String(format:"%@%02d:%02d:%02d",s,h,m,sec) : String(format:"%@%02d:%02d",s,h,m)
}
func fmtLocal(_ t: Int64, _ off: Int32) -> String {
    let ls = t + Int64(off); let (y,m,d,h,mi,s) = s2w(ls)
    return String(format:"%04d-%02d-%02dT%02d:%02d:%02d%@",y,m,d,h,mi,s,fmtOff(off))
}

func parseWall(_ s: String) -> (Int,Int,Int,Int,Int,Int) {
    let a = Array(s)
    return (Int(String(a[0..<4]))!, Int(String(a[5..<7]))!, Int(String(a[8..<10]))!,
            Int(String(a[11..<13]))!, Int(String(a[14..<16]))!, Int(String(a[17..<19]))!)
}

func processLocal(_ wallStr: String, _ tz: TZif) -> String {
    let (wy,wm,wd,wh,wmi,ws) = parseWall(wallStr)
    let wSec = w2s(wy,wm,wd,wh,wmi,ws)

    var offsets = Set<Int32>()
    for tp in tz.types { offsets.insert(tp.gmtoff) }
    if let f = tz.footer { offsets.insert(f.stdOff); if f.hasDst { offsets.insert(f.dstOff) } }

    var results: [(Int64,Int32,String)] = []
    for O in offsets {
        let t = wSec - Int64(O)
        let (ao, ab, _) = offsetAt(t, tz)
        if ao == O { results.append((t, O, ab)) }
    }
    results.sort { $0.0 < $1.0 }

    if results.count == 1 {
        return "\(results[0].0) \(fmtOff(results[0].1)) \(results[0].2)"
    } else if results.count >= 2 {
        return results.map { "\($0.0) \(fmtOff($0.1)) \($0.2)" }.joined(separator: " | ")
    }

    // Gap: find the transition
    let (gy,_,_,_,_,_) = s2w(wSec)
    // Check file transitions
    for i in 0..<tz.transTimes.count {
        let T = tz.transTimes[i]
        let oA = tz.types[Int(tz.transTypes[i])].gmtoff
        let oB: Int32 = i == 0 ? tz.types[0].gmtoff : tz.types[Int(tz.transTypes[i-1])].gmtoff
        if oA > oB && wSec >= T+Int64(oB) && wSec < T+Int64(oA) {
            let t = wSec - Int64(oB)
            let (lo, la, _) = offsetAt(t, tz)
            return "GAP \(t) \(fmtLocal(t,lo)) \(la)"
        }
    }
    // Check footer transitions
    if let f = tz.footer, f.hasDst {
        let lastT = tz.transTimes.isEmpty ? Int64.min : tz.transTimes[tz.transTimes.count-1]
        for yr in (gy-2)...(gy+2) {
            let ds = dstStart(yr,f), de = dstEnd(yr,f)
            if ds > lastT && f.dstOff > f.stdOff {
                if wSec >= ds+Int64(f.stdOff) && wSec < ds+Int64(f.dstOff) {
                    let t = wSec - Int64(f.stdOff)
                    let (lo, la, _) = offsetAt(t, tz)
                    return "GAP \(t) \(fmtLocal(t,lo)) \(la)"
                }
            }
            if de > lastT && f.stdOff > f.dstOff {
                if wSec >= de+Int64(f.dstOff) && wSec < de+Int64(f.stdOff) {
                    let t = wSec - Int64(f.dstOff)
                    let (lo, la, _) = offsetAt(t, tz)
                    return "GAP \(t) \(fmtLocal(t,lo)) \(la)"
                }
            }
        }
    }
    return "GAP 0 1970-01-01T00:00:00+00:00 ?"
}

// Main
let args = CommandLine.arguments
let dir = args[1]
let qContent = try! String(contentsOfFile: dir + "/queries.txt", encoding: .utf8)
let lines = qContent.components(separatedBy: "\n")
var cache: [String: TZif] = [:]

func getTZ(_ fn: String) -> TZif {
    if let c = cache[fn] { return c }
    let path = dir + "/" + fn
    let data = [UInt8](try! Data(contentsOf: URL(fileURLWithPath: path)))
    let tz = parseTZif(data)
    cache[fn] = tz
    return tz
}

for line in lines {
    if line.isEmpty { continue }
    let parts = line.components(separatedBy: " ")
    let qType = parts[0]; let fn = parts[1]
    if qType == "UTC" {
        let t = Int64(parts[2])!
        let tz = getTZ(fn)
        let (off, ab, _) = offsetAt(t, tz)
        print("\(line) -> \(fmtLocal(t,off)) \(ab)")
    } else {
        let ws = parts[2]
        let tz = getTZ(fn)
        print("\(line) -> \(processLocal(ws, tz))")
    }
}

import * as fs from 'fs';
import * as path from 'path';

// ============ Date utilities ============

function isLeapYear(y: number): boolean {
  return (y % 4 === 0 && y % 100 !== 0) || y % 400 === 0;
}

function daysInMonth(y: number, m: number): number {
  const days = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
  if (m === 2 && isLeapYear(y)) return 29;
  return days[m - 1];
}

function daysFromCivil(y: number, m: number, d: number): number {
  y -= m <= 2 ? 1 : 0;
  const era = Math.floor(y / 400);
  const yoe = y - era * 400;
  const mp = (m + 9) % 12;
  const doy = Math.floor((153 * mp + 2) / 5) + d - 1;
  const doe = yoe * 365 + Math.floor(yoe / 4) - Math.floor(yoe / 100) + doy;
  return era * 146097 + doe - 719468;
}

function civilFromDays(days: number): [number, number, number] {
  days += 719468;
  const era = Math.floor(days / 146097);
  const doe = days - era * 146097;
  const yoe = Math.floor((doe - Math.floor(doe / 1460) + Math.floor(doe / 36524) - Math.floor(doe / 146096)) / 365);
  const y = yoe + era * 400;
  const doy = doe - (365 * yoe + Math.floor(yoe / 4) - Math.floor(yoe / 100));
  const mp = Math.floor((5 * doy + 2) / 153);
  const d = doy - Math.floor((153 * mp + 2) / 5) + 1;
  const m = mp + (mp < 10 ? 3 : -9);
  return [y + (m <= 2 ? 1 : 0), m, d];
}

function dayOfWeek(y: number, m: number, d: number): number {
  const days = daysFromCivil(y, m, d);
  return ((days + 4) % 7 + 7) % 7; // 0=Sunday
}

function secondsFromCivil(y: number, m: number, d: number, h: number, min: number, s: number): number {
  return daysFromCivil(y, m, d) * 86400 + h * 3600 + min * 60 + s;
}

function pad2(n: number): string {
  return n < 10 ? '0' + n : '' + n;
}

function pad4(n: number): string {
  if (n < 0) return '-' + pad4(-n);
  if (n < 10) return '000' + n;
  if (n < 100) return '00' + n;
  if (n < 1000) return '0' + n;
  return '' + n;
}

function formatDateTime(t: number): string {
  const days = Math.floor(t / 86400);
  const secsOfDay = t - days * 86400;
  const [y, m, d] = civilFromDays(days);
  const h = Math.floor(secsOfDay / 3600);
  const min = Math.floor((secsOfDay % 3600) / 60);
  const s = secsOfDay % 60;
  return `${pad4(y)}-${pad2(m)}-${pad2(d)}T${pad2(h)}:${pad2(min)}:${pad2(s)}`;
}

function formatOffset(gmtoff: number): string {
  const sign = gmtoff >= 0 ? '+' : '-';
  const abs = Math.abs(gmtoff);
  const h = Math.floor(abs / 3600);
  const m = Math.floor((abs % 3600) / 60);
  const s = abs % 60;
  if (s !== 0) {
    return `${sign}${pad2(h)}:${pad2(m)}:${pad2(s)}`;
  }
  return `${sign}${pad2(h)}:${pad2(m)}`;
}

// ============ TZif Parsing ============

interface TypeRecord {
  gmtoff: number;
  isdst: number;
  abbrIndex: number;
}

interface TzifData {
  transitions: number[];
  typeIndices: number[];
  types: TypeRecord[];
  abbrs: string[];
  footer: string;
}

function parseTZif(buf: Buffer): TzifData {
  // First header (44 bytes)
  const isutcnt1 = buf.readInt32BE(20);
  const isstdcnt1 = buf.readInt32BE(24);
  const leapcnt1 = buf.readInt32BE(28);
  const timecnt1 = buf.readInt32BE(32);
  const typecnt1 = buf.readInt32BE(36);
  const charcnt1 = buf.readInt32BE(40);

  const block1Size = timecnt1 * 4 + timecnt1 * 1 + typecnt1 * 6 + charcnt1 + leapcnt1 * 8 + isstdcnt1 + isutcnt1;
  let offset = 44 + block1Size;

  // Second header (44 bytes)
  const isutcnt = buf.readInt32BE(offset + 20);
  const isstdcnt = buf.readInt32BE(offset + 24);
  const leapcnt = buf.readInt32BE(offset + 28);
  const timecnt = buf.readInt32BE(offset + 32);
  const typecnt = buf.readInt32BE(offset + 36);
  const charcnt = buf.readInt32BE(offset + 40);
  offset += 44;

  // Read 64-bit transition times
  const transitions: number[] = [];
  for (let i = 0; i < timecnt; i++) {
    const hi = buf.readInt32BE(offset);
    const lo = buf.readUInt32BE(offset + 4);
    transitions.push(hi * 4294967296 + lo);
    offset += 8;
  }

  // Read type indices
  const typeIndices: number[] = [];
  for (let i = 0; i < timecnt; i++) {
    typeIndices.push(buf[offset++]);
  }

  // Read type records
  const types: TypeRecord[] = [];
  for (let i = 0; i < typecnt; i++) {
    const gmtoff = buf.readInt32BE(offset);
    const isdst = buf[offset + 4];
    const abbrIndex = buf[offset + 5];
    types.push({ gmtoff, isdst, abbrIndex });
    offset += 6;
  }

  // Read abbreviation characters
  const abbrChars = buf.slice(offset, offset + charcnt);
  offset += charcnt;

  // Parse abbreviations (NUL-terminated)
  const abbrs: string[] = [];
  let pos = 0;
  while (pos < charcnt) {
    if (abbrChars[pos] === 0) {
      abbrs.push('');
      pos++;
    } else {
      let end = pos;
      while (end < charcnt && abbrChars[end] !== 0) end++;
      abbrs.push(abbrChars.slice(pos, end).toString('ascii'));
      pos = end + 1;
    }
  }

  // Skip leap seconds, isstd, isut
  offset += leapcnt * 12 + isstdcnt + isutcnt;

  // Read footer
  if (offset < buf.length && buf[offset] === 0x0a) offset++;
  let footerEnd = buf.indexOf(0x0a, offset);
  if (footerEnd === -1) footerEnd = buf.length;
  const footer = buf.toString('ascii', offset, footerEnd);

  return { transitions, typeIndices, types, abbrs, footer };
}

// ============ POSIX TZ String Parsing ============

interface Rule {
  month: number;
  week: number;
  day: number;
  time: number; // seconds from midnight
}

interface PosixTz {
  stdName: string;
  stdOffset: number; // posix offset: add to local to get UTC
  dstName?: string;
  dstOffset?: number;
  startRule?: Rule;
  endRule?: Rule;
}

function parsePosixTz(s: string): PosixTz {
  if (!s || s.length === 0) {
    return { stdName: 'UTC', stdOffset: 0 };
  }

  let pos = 0;

  function parseName(): string {
    if (pos < s.length && s[pos] === '<') {
      const end = s.indexOf('>', pos);
      const name = s.slice(pos + 1, end);
      pos = end + 1;
      return name;
    } else {
      const start = pos;
      while (pos < s.length && /[a-zA-Z]/.test(s[pos])) pos++;
      return s.slice(start, pos);
    }
  }

  function parseOffset(): number {
    let sign = 1;
    if (pos < s.length && s[pos] === '+') { pos++; }
    else if (pos < s.length && s[pos] === '-') { sign = -1; pos++; }

    let numStart = pos;
    while (pos < s.length && s[pos] >= '0' && s[pos] <= '9') pos++;
    const hours = parseInt(s.slice(numStart, pos));

    let minutes = 0, seconds = 0;
    if (pos < s.length && s[pos] === ':') {
      pos++;
      numStart = pos;
      while (pos < s.length && s[pos] >= '0' && s[pos] <= '9') pos++;
      minutes = parseInt(s.slice(numStart, pos));

      if (pos < s.length && s[pos] === ':') {
        pos++;
        numStart = pos;
        while (pos < s.length && s[pos] >= '0' && s[pos] <= '9') pos++;
        seconds = parseInt(s.slice(numStart, pos));
      }
    }

    return sign * (hours * 3600 + minutes * 60 + seconds);
  }

  function parseTime(): number {
    let sign = 1;
    if (pos < s.length && s[pos] === '+') { pos++; }
    else if (pos < s.length && s[pos] === '-') { sign = -1; pos++; }

    let numStart = pos;
    while (pos < s.length && s[pos] >= '0' && s[pos] <= '9') pos++;
    const hours = parseInt(s.slice(numStart, pos));

    let minutes = 0, seconds = 0;
    if (pos < s.length && s[pos] === ':') {
      pos++;
      numStart = pos;
      while (pos < s.length && s[pos] >= '0' && s[pos] <= '9') pos++;
      minutes = parseInt(s.slice(numStart, pos));

      if (pos < s.length && s[pos] === ':') {
        pos++;
        numStart = pos;
        while (pos < s.length && s[pos] >= '0' && s[pos] <= '9') pos++;
        seconds = parseInt(s.slice(numStart, pos));
      }
    }

    return sign * (hours * 3600 + minutes * 60 + seconds);
  }

  function parseMRule(): Rule {
    pos++; // skip 'M'
    let numStart = pos;
    while (pos < s.length && s[pos] >= '0' && s[pos] <= '9') pos++;
    const month = parseInt(s.slice(numStart, pos));
    pos++; // skip '.'
    const week = parseInt(s[pos]); pos++;
    pos++; // skip '.'
    const day = parseInt(s[pos]); pos++;

    let time = 2 * 3600; // default 02:00:00
    if (pos < s.length && s[pos] === '/') {
      pos++; // skip '/'
      time = parseTime();
    }

    return { month, week, day, time };
  }

  const stdName = parseName();
  const stdOffset = parseOffset();

  let dstName: string | undefined;
  let dstOffset: number | undefined;
  let startRule: Rule | undefined;
  let endRule: Rule | undefined;

  if (pos < s.length) {
    dstName = parseName();
    if (pos < s.length && (s[pos] === '+' || s[pos] === '-' || (s[pos] >= '0' && s[pos] <= '9'))) {
      dstOffset = parseOffset();
    } else {
      dstOffset = stdOffset - 3600;
    }

    if (pos < s.length && s[pos] === ',') {
      pos++; // skip ','
      startRule = parseMRule();
      pos++; // skip ','
      endRule = parseMRule();
    }
  }

  return { stdName, stdOffset, dstName, dstOffset, startRule, endRule };
}

// ============ Footer rule transition computation ============

function computeTransitionTime(rule: Rule, year: number, gmtoff: number): number {
  const { month, week, day, time } = rule;
  const dim = daysInMonth(year, month);

  const firstDow = dayOfWeek(year, month, 1);

  let firstOcc: number;
  if (firstDow <= day) {
    firstOcc = 1 + (day - firstDow);
  } else {
    firstOcc = 1 + (7 - firstDow + day);
  }

  let dayOfMonth: number;
  if (week === 5) {
    dayOfMonth = firstOcc + 28;
    if (dayOfMonth > dim) dayOfMonth -= 7;
  } else {
    dayOfMonth = firstOcc + (week - 1) * 7;
  }

  const localSeconds = secondsFromCivil(year, month, dayOfMonth, 0, 0, 0) + time;
  const utcSeconds = localSeconds - gmtoff;
  return utcSeconds;
}

// ============ Type lookup ============

function getFooterType(posix: PosixTz, t: number): { gmtoff: number; abbr: string } {
  if (!posix.dstName || !posix.startRule || !posix.endRule) {
    return { gmtoff: -posix.stdOffset, abbr: posix.stdName };
  }

  const stdGmtoff = -posix.stdOffset;
  const dstGmtoff = -posix.dstOffset!;

  const days = Math.floor(t / 86400);
  const [year] = civilFromDays(days);

  const startUtc = computeTransitionTime(posix.startRule, year, stdGmtoff);
  const endUtc = computeTransitionTime(posix.endRule, year, dstGmtoff);

  let isDst: boolean;
  if (startUtc < endUtc) {
    isDst = t >= startUtc && t < endUtc;
  } else {
    isDst = t >= startUtc || t < endUtc;
  }

  if (isDst) {
    return { gmtoff: dstGmtoff, abbr: posix.dstName };
  } else {
    return { gmtoff: stdGmtoff, abbr: posix.stdName };
  }
}

function getTypeAt(tzif: TzifData, posix: PosixTz, t: number): { gmtoff: number; abbr: string } {
  const { transitions, typeIndices, types, abbrs } = tzif;

  if (transitions.length === 0) {
    if (posix.stdName) {
      return getFooterType(posix, t);
    }
    return { gmtoff: types[0].gmtoff, abbr: abbrs[types[0].abbrIndex] };
  }

  if (t < transitions[0]) {
    return { gmtoff: types[0].gmtoff, abbr: abbrs[types[0].abbrIndex] };
  }

  if (t > transitions[transitions.length - 1]) {
    return getFooterType(posix, t);
  }

  // Binary search for latest transition <= t
  let lo = 0, hi = transitions.length - 1;
  while (lo < hi) {
    const mid = (lo + hi + 1) >> 1;
    if (transitions[mid] <= t) {
      lo = mid;
    } else {
      hi = mid - 1;
    }
  }

  const typeIdx = typeIndices[lo];
  return { gmtoff: types[typeIdx].gmtoff, abbr: abbrs[typeIdx.abbrIndex] };
}

// ============ Gap detection ============

interface GapInfo {
  T: number;
  oBefore: number;
  oAfter: number;
}

function findGapTransition(tzif: TzifData, posix: PosixTz, W: number): GapInfo | null {
  // Check file transitions
  for (let i = 0; i < tzif.transitions.length; i++) {
    const T = tzif.transitions[i];
    const oBefore = i === 0 ? tzif.types[0].gmtoff : tzif.types[tzif.typeIndices[i - 1]].gmtoff;
    const oAfter = tzif.types[tzif.typeIndices[i]].gmtoff;
    if (oAfter > oBefore && W >= T + oBefore && W < T + oAfter) {
      return { T, oBefore, oAfter };
    }
  }

  // Check footer start-of-DST transitions
  if (posix.dstName && posix.startRule && posix.endRule) {
    const stdGmtoff = -posix.stdOffset;
    const dstGmtoff = -posix.dstOffset!;
    if (dstGmtoff > stdGmtoff) {
      const approxT = W - stdGmtoff;
      const days = Math.floor(approxT / 86400);
      const [year] = civilFromDays(days);
      const lastTrans = tzif.transitions.length > 0 ? tzif.transitions[tzif.transitions.length - 1] : -Infinity;

      for (let y = year - 1; y <= year + 1; y++) {
        const startUtc = computeTransitionTime(posix.startRule, y, stdGmtoff);
        if (startUtc <= lastTrans) continue;
        if (W >= startUtc + stdGmtoff && W < startUtc + dstGmtoff) {
          return { T: startUtc, oBefore: stdGmtoff, oAfter: dstGmtoff };
        }
      }
    }
  }

  return null;
}

// ============ Parse date-time string ============

function parseDateTime(s: string): [number, number, number, number, number, number] {
  // YYYY-MM-DDTHH:MM:SS
  const y = parseInt(s.slice(0, 4));
  const mo = parseInt(s.slice(5, 7));
  const d = parseInt(s.slice(8, 10));
  const h = parseInt(s.slice(11, 13));
  const mi = parseInt(s.slice(14, 16));
  const sec = parseInt(s.slice(17, 19));
  return [y, mo, d, h, mi, sec];
}

// ============ Main ============

function main() {
  const dir = process.argv[2];
  const queriesPath = path.join(dir, 'queries.txt');
  const queries = fs.readFileSync(queriesPath, 'utf8').split('\n').filter(l => l.trim() !== '');

  const tzifCache = new Map<string, { tzif: TzifData; posix: PosixTz }>();

  function getTzif(filename: string): { tzif: TzifData; posix: PosixTz } {
    if (!tzifCache.has(filename)) {
      const buf = fs.readFileSync(path.join(dir, filename));
      const tzif = parseTZif(buf);
      const posix = parsePosixTz(tzif.footer);
      tzifCache.set(filename, { tzif, posix });
    }
    return tzifCache.get(filename)!;
  }

  const output: string[] = [];

  for (const line of queries) {
    const parts = line.split(' ');
    const qType = parts[0];
    const filename = parts[1];
    const { tzif, posix } = getTzif(filename);

    if (qType === 'UTC') {
      const t = parseInt(parts[2]);
      const { gmtoff, abbr } = getTypeAt(tzif, posix, t);
      const localT = t + gmtoff;
      const localStr = formatDateTime(localT);
      const offsetStr = formatOffset(gmtoff);
      output.push(`${line} -> ${localStr}${offsetStr} ${abbr}`);
    } else if (qType === 'LOCAL') {
      const timeStr = parts[2];
      const [Y, M, D, H, Min, S] = parseDateTime(timeStr);
      const W = secondsFromCivil(Y, M, D, H, Min, S);

      // Collect distinct gmtoff values
      const gmtoffs = new Set<number>();
      for (const tp of tzif.types) gmtoffs.add(tp.gmtoff);
      gmtoffs.add(-posix.stdOffset);
      if (posix.dstOffset !== undefined) gmtoffs.add(-posix.dstOffset);

      // Find all solutions
      const solutions: { t: number; gmtoff: number; abbr: string }[] = [];
      for (const o of gmtoffs) {
        const t = W - o;
        const { gmtoff: actual, abbr } = getTypeAt(tzif, posix, t);
        if (actual === o) {
          // Check for duplicate t
          if (!solutions.some(s => s.t === t)) {
            solutions.push({ t, gmtoff: o, abbr });
          }
        }
      }

      solutions.sort((a, b) => a.t - b.t);

      if (solutions.length === 1) {
        const { t, gmtoff, abbr } = solutions[0];
        const offsetStr = formatOffset(gmtoff);
        output.push(`${line} -> ${t} ${offsetStr} ${abbr}`);
      } else if (solutions.length >= 2) {
        const partsOut = solutions.map(s => `${s.t} ${formatOffset(s.gmtoff)} ${s.abbr}`);
        output.push(`${line} -> ${partsOut.join(' | ')}`);
      } else {
        // Gap
        const gap = findGapTransition(tzif, posix, W);
        if (gap) {
          const t = W - gap.oBefore;
          const { gmtoff, abbr } = getTypeAt(tzif, posix, t);
          const localT = t + gmtoff;
          const localStr = formatDateTime(localT);
          const offsetStr = formatOffset(gmtoff);
          output.push(`${line} -> GAP ${t} ${localStr}${offsetStr} ${abbr}`);
        }
      }
    }
  }

  console.log(output.join('\n'));
}

main();

import * as fs from 'fs';
import * as path from 'path';

// ============ Date utilities ============

function isLeapYear(y: number): boolean {
  return (y % 4 === 0 && y % 100 !== 0) || y % 400 === 0;
}

function daysInMonth(y: number, m: number): number {
  const days = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
  if (m === 2 && isLeapYear(y)) return 29;
  return days[m - 1];
}

function daysFromCivil(y: number, m: number, d: number): number {
  y -= m <= 2 ? 1 : 0;
  const era = Math.floor(y / 400);
  const yoe = y - era * 400;
  const mp = (m + 9) % 12;
  const doy = Math.floor((153 * mp + 2) / 5) + d - 1;
  const doe = yoe * 365 + Math.floor(yoe / 4) - Math.floor(yoe / 100) + doy;
  return era * 146097 + doe - 719468;
}

function civilFromDays(days: number): [number, number, number] {
  days += 719468;
  const era = Math.floor(days / 146097);
  const doe = days - era * 146097;
  const yoe = Math.floor((doe - Math.floor(doe / 1460) + Math.floor(doe / 36524) - Math.floor(doe / 146096)) / 365);
  const y = yoe + era * 400;
  const doy = doe - (365 * yoe + Math.floor(yoe / 4) - Math.floor(yoe / 100));
  const mp = Math.floor((5 * doy + 2) / 153);
  const d = doy - Math.floor((153 * mp + 2) / 5) + 1;
  const m = mp + (mp < 10 ? 3 : -9);
  return [y + (m <= 2 ? 1 : 0), m, d];
}

function dayOfWeek(y: number, m: number, d: number): number {
  const days = daysFromCivil(y, m, d);
  return ((days + 4) % 7 + 7) % 7; // 0=Sunday
}

function secondsFromCivil(y: number, m: number, d: number, h: number, min: number, s: number): number {
  return daysFromCivil(y, m, d) * 86400 + h * 3600 + min * 60 + s;
}

function pad2(n: number): string {
  return n < 10 ? '0' + n : '' + n;
}

function pad4(n: number): string {
  if (n < 0) return '-' + pad4(-n);
  if (n < 10) return '000' + n;
  if (n < 100) return '00' + n;
  if (n < 1000) return '0' + n;
  return '' + n;
}

function formatDateTime(t: number): string {
  const days = Math.floor(t / 86400);
  const secsOfDay = t - days * 86400;
  const [y, m, d] = civilFromDays(days);
  const h = Math.floor(secsOfDay / 3600);
  const min = Math.floor((secsOfDay % 3600) / 60);
  const s = secsOfDay % 60;
  return `${pad4(y)}-${pad2(m)}-${pad2(d)}T${pad2(h)}:${pad2(min)}:${pad2(s)}`;
}

function formatOffset(gmtoff: number): string {
  const sign = gmtoff >= 0 ? '+' : '-';
  const abs = Math.abs(gmtoff);
  const h = Math.floor(abs / 3600);
  const m = Math.floor((abs % 3600) / 60);
  const s = abs % 60;
  if (s !== 0) {
    return `${sign}${pad2(h)}:${pad2(m)}:${pad2(s)}`;
  }
  return `${sign}${pad2(h)}:${pad2(m)}`;
}

// ============ TZif Parsing ============

interface TypeRecord {
  gmtoff: number;
  isdst: number;
  abbrIndex: number;
}

interface TzifData {
  transitions: number[];
  typeIndices: number[];
  types: TypeRecord[];
  abbrChars: Buffer;
  footer: string;
}

function parseTZif(buf: Buffer): TzifData {
  // First header (44 bytes)
  const isutcnt1 = buf.readInt32BE(20);
  const isstdcnt1 = buf.readInt32BE(24);
  const leapcnt1 = buf.readInt32BE(28);
  const timecnt1 = buf.readInt32BE(32);
  const typecnt1 = buf.readInt32BE(36);
  const charcnt1 = buf.readInt32BE(40);

  const block1Size = timecnt1 * 4 + timecnt1 * 1 + typecnt1 * 6 + charcnt1 + leapcnt1 * 8 + isstdcnt1 + isutcnt1;
  let offset = 44 + block1Size;

  // Second header (44 bytes)
  const isutcnt = buf.readInt32BE(offset + 20);
  const isstdcnt = buf.readInt32BE(offset + 24);
  const leapcnt = buf.readInt32BE(offset + 28);
  const timecnt = buf.readInt32BE(offset + 32);
  const typecnt = buf.readInt32BE(offset + 36);
  const charcnt = buf.readInt32BE(offset + 40);
  offset += 44;

  // Read 64-bit transition times
  const transitions: number[] = [];
  for (let i = 0; i < timecnt; i++) {
    const hi = buf.readInt32BE(offset);
    const lo = buf.readUInt32BE(offset + 4);
    transitions.push(hi * 4294967296 + lo);
    offset += 8;
  }

  // Read type indices
  const typeIndices: number[] = [];
  for (let i = 0; i < timecnt; i++) {
    typeIndices.push(buf[offset++]);
  }

  // Read type records
  const types: TypeRecord[] = [];
  for (let i = 0; i < typecnt; i++) {
    const gmtoff = buf.readInt32BE(offset);
    const isdst = buf[offset + 4];
    const abbrIndex = buf[offset + 5];
    types.push({ gmtoff, isdst, abbrIndex });
    offset += 6;
  }

  // Read abbreviation characters (raw buffer)
  const abbrChars = buf.slice(offset, offset + charcnt);
  offset += charcnt;

  // Skip leap seconds, isstd, isut
  offset += leapcnt * 12 + isstdcnt + isutcnt;

  // Read footer
  if (offset < buf.length && buf[offset] === 0x0a) offset++;
  let footerEnd = buf.indexOf(0x0a, offset);
  if (footerEnd === -1) footerEnd = buf.length;
  const footer = buf.toString('ascii', offset, footerEnd);

  return { transitions, typeIndices, types, abbrChars, footer };
}

function getAbbr(tzif: TzifData, index: number): string {
  let end = index;
  while (end < tzif.abbrChars.length && tzif.abbrChars[end] !== 0) end++;
  return tzif.abbrChars.slice(index, end).toString('ascii');
}

// ============ POSIX TZ String Parsing ============

interface Rule {
  month: number;
  week: number;
  day: number;
  time: number; // seconds from midnight
}

interface PosixTz {
  stdName: string;
  stdOffset: number; // posix offset: add to local to get UTC
  dstName?: string;
  dstOffset?: number;
  startRule?: Rule;
  endRule?: Rule;
}

function parsePosixTz(s: string): PosixTz {
  if (!s || s.length === 0) {
    return { stdName: 'UTC', stdOffset: 0 };
  }

  let pos = 0;

  function parseName(): string {
    if (pos < s.length && s[pos] === '<') {
      const end = s.indexOf('>', pos);
      const name = s.slice(pos + 1, end);
      pos = end + 1;
      return name;
    } else {
      const start = pos;
      while (pos < s.length && /[a-zA-Z]/.test(s[pos])) pos++;
      return s.slice(start, pos);
    }
  }

  function parseOffset(): number {
    let sign = 1;
    if (pos < s.length && s[pos] === '+') { pos++; }
    else if (pos < s.length && s[pos] === '-') { sign = -1; pos++; }

    let numStart = pos;
    while (pos < s.length && s[pos] >= '0' && s[pos] <= '9') pos++;
    const hours = parseInt(s.slice(numStart, pos));

    let minutes = 0, seconds = 0;
    if (pos < s.length && s[pos] === ':') {
      pos++;
      numStart = pos;
      while (pos < s.length && s[pos] >= '0' && s[pos] <= '9') pos++;
      minutes = parseInt(s.slice(numStart, pos));

      if (pos < s.length && s[pos] === ':') {
        pos++;
        numStart = pos;
        while (pos < s.length && s[pos] >= '0' && s[pos] <= '9') pos++;
        seconds = parseInt(s.slice(numStart, pos));
      }
    }

    return sign * (hours * 3600 + minutes * 60 + seconds);
  }

  function parseTime(): number {
    let sign = 1;
    if (pos < s.length && s[pos] === '+') { pos++; }
    else if (pos < s.length && s[pos] === '-') { sign = -1; pos++; }

    let numStart = pos;
    while (pos < s.length && s[pos] >= '0' && s[pos] <= '9') pos++;
    const hours = parseInt(s.slice(numStart, pos));

    let minutes = 0, seconds = 0;
    if (pos < s.length && s[pos] === ':') {
      pos++;
      numStart = pos;
      while (pos < s.length && s[pos] >= '0' && s[pos] <= '9') pos++;
      minutes = parseInt(s.slice(numStart, pos));

      if (pos < s.length && s[pos] === ':') {
        pos++;
        numStart = pos;
        while (pos < s.length && s[pos] >= '0' && s[pos] <= '9') pos++;
        seconds = parseInt(s.slice(numStart, pos));
      }
    }

    return sign * (hours * 3600 + minutes * 60 + seconds);
  }

  function parseMRule(): Rule {
    pos++; // skip 'M'
    let numStart = pos;
    while (pos < s.length && s[pos] >= '0' && s[pos] <= '9') pos++;
    const month = parseInt(s.slice(numStart, pos));
    pos++; // skip '.'
    const week = parseInt(s[pos]); pos++;
    pos++; // skip '.'
    const day = parseInt(s[pos]); pos++;

    let time = 2 * 3600; // default 02:00:00
    if (pos < s.length && s[pos] === '/') {
      pos++; // skip '/'
      time = parseTime();
    }

    return { month, week, day, time };
  }

  const stdName = parseName();
  const stdOffset = parseOffset();

  let dstName: string | undefined;
  let dstOffset: number | undefined;
  let startRule: Rule | undefined;
  let endRule: Rule | undefined;

  if (pos < s.length) {
    dstName = parseName();
    if (pos < s.length && (s[pos] === '+' || s[pos] === '-' || (s[pos] >= '0' && s[pos] <= '9'))) {
      dstOffset = parseOffset();
    } else {
      dstOffset = stdOffset - 3600;
    }

    if (pos < s.length && s[pos] === ',') {
      pos++; // skip ','
      startRule = parseMRule();
      pos++; // skip ','
      endRule = parseMRule();
    }
  }

  return { stdName, stdOffset, dstName, dstOffset, startRule, endRule };
}

// ============ Footer rule transition computation ============

function computeTransitionTime(rule: Rule, year: number, gmtoff: number): number {
  const { month, week, day, time } = rule;
  const dim = daysInMonth(year, month);

  const firstDow = dayOfWeek(year, month, 1);

  let firstOcc: number;
  if (firstDow <= day) {
    firstOcc = 1 + (day - firstDow);
  } else {
    firstOcc = 1 + (7 - firstDow + day);
  }

  let dayOfMonth: number;
  if (week === 5) {
    dayOfMonth = firstOcc + 28;
    if (dayOfMonth > dim) dayOfMonth -= 7;
  } else {
    dayOfMonth = firstOcc + (week - 1) * 7;
  }

  const localSeconds = secondsFromCivil(year, month, dayOfMonth, 0, 0, 0) + time;
  const utcSeconds = localSeconds - gmtoff;
  return utcSeconds;
}

// ============ Type lookup ============

function getFooterType(posix: PosixTz, t: number): { gmtoff: number; abbr: string } {
  if (!posix.dstName || !posix.startRule || !posix.endRule) {
    return { gmtoff: -posix.stdOffset, abbr: posix.stdName };
  }

  const stdGmtoff = -posix.stdOffset;
  const dstGmtoff = -posix.dstOffset!;

  const days = Math.floor(t / 86400);
  const [year] = civilFromDays(days);

  const startUtc = computeTransitionTime(posix.startRule, year, stdGmtoff);
  const endUtc = computeTransitionTime(posix.endRule, year, dstGmtoff);

  let isDst: boolean;
  if (startUtc < endUtc) {
    isDst = t >= startUtc && t < endUtc;
  } else {
    isDst = t >= startUtc || t < endUtc;
  }

  if (isDst) {
    return { gmtoff: dstGmtoff, abbr: posix.dstName };
  } else {
    return { gmtoff: stdGmtoff, abbr: posix.stdName };
  }
}

function getTypeAt(tzif: TzifData, posix: PosixTz, t: number): { gmtoff: number; abbr: string } {
  const { transitions, typeIndices, types, abbrChars } = tzif;

  if (transitions.length === 0) {
    if (posix.stdName) {
      return getFooterType(posix, t);
    }
    return { gmtoff: types[0].gmtoff, abbr: getAbbr(tzif, types[0].abbrIndex) };
  }

  if (t < transitions[0]) {
    return { gmtoff: types[0].gmtoff, abbr: getAbbr(tzif, types[0].abbrIndex) };
  }

  if (t > transitions[transitions.length - 1]) {
    return getFooterType(posix, t);
  }

  // Binary search for latest transition <= t
  let lo = 0, hi = transitions.length - 1;
  while (lo < hi) {
    const mid = (lo + hi + 1) >> 1;
    if (transitions[mid] <= t) {
      lo = mid;
    } else {
      hi = mid - 1;
    }
  }

  const typeIdx = typeIndices[lo];
  return { gmtoff: types[typeIdx].gmtoff, abbr: getAbbr(tzif, types[typeIdx].abbrIndex) };
}

// ============ Gap detection ============

interface GapInfo {
  T: number;
  oBefore: number;
  oAfter: number;
}

function findGapTransition(tzif: TzifData, posix: PosixTz, W: number): GapInfo | null {
  // Check file transitions
  for (let i = 0; i < tzif.transitions.length; i++) {
    const T = tzif.transitions[i];
    const oBefore = i === 0 ? tzif.types[0].gmtoff : tzif.types[tzif.typeIndices[i - 1]].gmtoff;
    const oAfter = tzif.types[tzif.typeIndices[i]].gmtoff;
    if (oAfter > oBefore && W >= T + oBefore && W < T + oAfter) {
      return { T, oBefore, oAfter };
    }
  }

  // Check footer start-of-DST transitions
  if (posix.dstName && posix.startRule && posix.endRule) {
    const stdGmtoff = -posix.stdOffset;
    const dstGmtoff = -posix.dstOffset!;
    if (dstGmtoff > stdGmtoff) {
      const approxT = W - stdGmtoff;
      const days = Math.floor(approxT / 86400);
      const [year] = civilFromDays(days);
      const lastTrans = tzif.transitions.length > 0 ? tzif.transitions[tzif.transitions.length - 1] : -Infinity;

      for (let y = year - 1; y <= year + 1; y++) {
        const startUtc = computeTransitionTime(posix.startRule, y, stdGmtoff);
        if (startUtc <= lastTrans) continue;
        if (W >= startUtc + stdGmtoff && W < startUtc + dstGmtoff) {
          return { T: startUtc, oBefore: stdGmtoff, oAfter: dstGmtoff };
        }
      }
    }
  }

  return null;
}

// ============ Parse date-time string ============

function parseDateTime(s: string): [number, number, number, number, number, number] {
  // YYYY-MM-DDTHH:MM:SS
  const y = parseInt(s.slice(0, 4));
  const mo = parseInt(s.slice(5, 7));
  const d = parseInt(s.slice(8, 10));
  const h = parseInt(s.slice(11, 13));
  const mi = parseInt(s.slice(14, 16));
  const sec = parseInt(s.slice(17, 19));
  return [y, mo, d, h, mi, sec];
}

// ============ Main ============

function main() {
  const dir = process.argv[2];
  const queriesPath = path.join(dir, 'queries.txt');
  const queries = fs.readFileSync(queriesPath, 'utf8').split('\n').filter(l => l.trim() !== '');

  const tzifCache = new Map<string, { tzif: TzifData; posix: PosixTz }>();

  function getTzif(filename: string): { tzif: TzifData; posix: PosixTz } {
    if (!tzifCache.has(filename)) {
      const buf = fs.readFileSync(path.join(dir, filename));
      const tzif = parseTZif(buf);
      const posix = parsePosixTz(tzif.footer);
      tzifCache.set(filename, { tzif, posix });
    }
    return tzifCache.get(filename)!;
  }

  const output: string[] = [];

  for (const line of queries) {
    const parts = line.split(' ');
    const qType = parts[0];
    const filename = parts[1];
    const { tzif, posix } = getTzif(filename);

    if (qType === 'UTC') {
      const t = parseInt(parts[2]);
      const { gmtoff, abbr } = getTypeAt(tzif, posix, t);
      const localT = t + gmtoff;
      const localStr = formatDateTime(localT);
      const offsetStr = formatOffset(gmtoff);
      output.push(`${line} -> ${localStr}${offsetStr} ${abbr}`);
    } else if (qType === 'LOCAL') {
      const timeStr = parts[2];
      const [Y, M, D, H, Min, S] = parseDateTime(timeStr);
      const W = secondsFromCivil(Y, M, D, H, Min, S);

      // Collect distinct gmtoff values
      const gmtoffs = new Set<number>();
      for (const tp of tzif.types) gmtoffs.add(tp.gmtoff);
      gmtoffs.add(-posix.stdOffset);
      if (posix.dstOffset !== undefined) gmtoffs.add(-posix.dstOffset);

      // Find all solutions
      const solutions: { t: number; gmtoff: number; abbr: string }[] = [];
      for (const o of gmtoffs) {
        const t = W - o;
        const { gmtoff: actual, abbr } = getTypeAt(tzif, posix, t);
        if (actual === o) {
          // Check for duplicate t
          if (!solutions.some(s => s.t === t)) {
            solutions.push({ t, gmtoff: o, abbr });
          }
        }
      }

      solutions.sort((a, b) => a.t - b.t);

      if (solutions.length === 1) {
        const { t, gmtoff, abbr } = solutions[0];
        const offsetStr = formatOffset(gmtoff);
        output.push(`${line} -> ${t} ${offsetStr} ${abbr}`);
      } else if (solutions.length >= 2) {
        const partsOut = solutions.map(s => `${s.t} ${formatOffset(s.gmtoff)} ${s.abbr}`);
        output.push(`${line} -> ${partsOut.join(' | ')}`);
      } else {
        // Gap
        const gap = findGapTransition(tzif, posix, W);
        if (gap) {
          const t = W - gap.oBefore;
          const { gmtoff, abbr } = getTypeAt(tzif, posix, t);
          const localT = t + gmtoff;
          const localStr = formatDateTime(localT);
          const offsetStr = formatOffset(gmtoff);
          output.push(`${line} -> GAP ${t} ${localStr}${offsetStr} ${abbr}`);
        }
      }
    }
  }

  console.log(output.join('\n'));
}

main();

import java.io.*;
import java.net.*;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.SecureRandom;
import java.util.Base64;

public class Main {
    static final SecureRandom random = new SecureRandom();

    public static void main(String[] args) throws Exception {
        for (int i = 0; i < args.length; i++) {
            System.out.println("session " + (i + 1));
            handleSession(args[i]);
        }
    }

    static void handleSession(String url) throws Exception {
        String rest = url.substring(5);
        int slashIdx = rest.indexOf('/');
        String hostPort;
        String requestTarget;
        if (slashIdx == -1) {
            hostPort = rest;
            requestTarget = "/";
        } else {
            hostPort = rest.substring(0, slashIdx);
            requestTarget = rest.substring(slashIdx);
        }

        int colonIdx = hostPort.lastIndexOf(':');
        String host = hostPort.substring(0, colonIdx);
        int port = Integer.parseInt(hostPort.substring(colonIdx + 1));

        try (Socket socket = new Socket(host, port)) {
            socket.setTcpNoDelay(true);
            InputStream in = new BufferedInputStream(socket.getInputStream());
            OutputStream out = socket.getOutputStream();

            byte[] keyBytes = new byte[16];
            random.nextBytes(keyBytes);
            String key = Base64.getEncoder().encodeToString(keyBytes);

            String req = "GET " + requestTarget + " HTTP/1.1\r\n"
                    + "Host: " + hostPort + "\r\n"
                    + "Upgrade: websocket\r\n"
                    + "Connection: Upgrade\r\n"
                    + "Sec-WebSocket-Version: 13\r\n"
                    + "Sec-WebSocket-Key: " + key + "\r\n"
                    + "\r\n";
            out.write(req.getBytes(StandardCharsets.US_ASCII));
            out.flush();

            String statusLine = readLine(in);
            if (statusLine == null) return;

            String[] parts = statusLine.split(" ", 3);
            int statusCode = Integer.parseInt(parts[1]);
            String reasonPhrase = parts.length > 2 ? parts[2] : "";

            String acceptHeader = null;
            String line;
            while ((line = readLine(in)) != null && !line.isEmpty()) {
                int ci = line.indexOf(':');
                if (ci >= 0) {
                    String name = line.substring(0, ci).trim();
                    String value = line.substring(ci + 1).trim();
                    if (name.equalsIgnoreCase("Sec-WebSocket-Accept")) {
                        acceptHeader = value;
                    }
                }
            }

            if (statusCode != 101) {
                System.out.println("handshake failed: " + statusCode + " " + reasonPhrase);
                return;
            }

            MessageDigest sha1 = MessageDigest.getInstance("SHA-1");
            byte[] digest = sha1.digest((key + "258EAFA5-E914-47DA-95CA-C5AB0DC85B11").getBytes(StandardCharsets.US_ASCII));
            String expectedAccept = Base64.getEncoder().encodeToString(digest);

            if (acceptHeader == null || !acceptHeader.equals(expectedAccept)) {
                System.out.println("handshake failed: bad Sec-WebSocket-Accept");
                return;
            }

            processFrames(in, out);
        }
    }

    static String readLine(InputStream in) throws IOException {
        StringBuilder sb = new StringBuilder();
        int c;
        while ((c = in.read()) != -1) {
            if (c == '\r') {
                int c2 = in.read();
                if (c2 == '\n') return sb.toString();
                sb.append('\r');
                if (c2 != -1) sb.append((char) c2);
            } else {
                sb.append((char) c);
            }
        }
        return sb.length() > 0 ? sb.toString() : null;
    }

    static void processFrames(InputStream in, OutputStream out) throws Exception {
        boolean closeSent = false;
        try {
            while (true) {
                Message msg = readMessage(in, out);

                if (msg.opcode == 8) {
                    handleClose(msg.payload, out, closeSent);
                    return;
                }

                if (msg.opcode == 1) {
                    String text = new String(msg.payload, StandardCharsets.UTF_8);

                    if (text.equals("BYE")) {
                        sendClose(out, 1000);
                        closeSent = true;
                        while (true) {
                            Message m = readMessage(in, out);
                            if (m.opcode == 8) {
                                handleClose(m.payload, out, closeSent);
                                return;
                            }
                        }
                    } else if (text.equals("SHA1")) {
                        Message next = readMessage(in, out);
                        if (next.opcode == 8) {
                            handleClose(next.payload, out, closeSent);
                            return;
                        }
                        byte[] hash = MessageDigest.getInstance("SHA-1").digest(next.payload);
                        String hex = bytesToHex(hash);
                        sendText(out, hex);
                        System.out.println("SHA1 " + next.payload.length + " -> " + hex);
                    } else if (text.startsWith("ADD ")) {
                        String nums = text.substring(4);
                        int sp = nums.indexOf(' ');
                        long a = Long.parseLong(nums.substring(0, sp));
                        long b = Long.parseLong(nums.substring(sp + 1));
                        long sum = a + b;
                        String reply = Long.toString(sum);
                        sendText(out, reply);
                        System.out.println(text + " -> " + reply);
                    } else if (text.startsWith("REV ")) {
                        String toRev = text.substring(4);
                        String reversed = reverseCodePoints(toRev);
                        sendText(out, reversed);
                        System.out.println(text + " -> " + reversed);
                    }
                }
            }
        } catch (EOFException e) {
            // connection closed unexpectedly
        }
    }

    static void handleClose(byte[] payload, OutputStream out, boolean closeSent) throws IOException {
        int code = 1005;
        String reason = "";
        if (payload.length >= 2) {
            code = ((payload[0] & 0xFF) << 8) | (payload[1] & 0xFF);
            if (payload.length > 2) {
                reason = new String(payload, 2, payload.length - 2, StandardCharsets.UTF_8);
            }
        }
        System.out.println("closed " + code + (reason.isEmpty() ? "" : " " + reason));
        if (!closeSent) {
            try {
                sendClose(out, code);
            } catch (IOException e) {
                // ignore
            }
        }
    }

    static Message readMessage(InputStream in, OutputStream out) throws IOException {
        ByteArrayOutputStream payload = new ByteArrayOutputStream();
        int msgOpcode = -1;

        while (true) {
            int b0 = in.read();
            if (b0 == -1) throw new EOFException();
            int b1 = in.read();
            if (b1 == -1) throw new EOFException();

            boolean fin = (b0 & 0x80) != 0;
            int opcode = b0 & 0x0F;
            boolean masked = (b1 & 0x80) != 0;
            int len = b1 & 0x7F;

            if (len == 126) {
                int hi = in.read();
                int lo = in.read();
                if (hi == -1 || lo == -1) throw new EOFException();
                len = (hi << 8) | lo;
            } else if (len == 127) {
                long longLen = 0;
                for (int i = 0; i < 8; i++) {
                    int b = in.read();
                    if (b == -1) throw new EOFException();
                    longLen = (longLen << 8) | b;
                }
                len = (int) longLen;
            }

            byte[] maskKey = null;
            if (masked) {
                maskKey = new byte[4];
                readFully(in, maskKey);
            }

            byte[] data = new byte[len];
            if (len > 0) readFully(in, data);

            if (masked && maskKey != null) {
                for (int i = 0; i < data.length; i++) {
                    data[i] ^= maskKey[i % 4];
                }
            }

            switch (opcode) {
                case 9:
                    sendPong(out, data);
                    break;
                case 10:
                    break;
                case 8:
                    return new Message(8, data);
                case 0:
                    payload.write(data);
                    if (fin) return new Message(msgOpcode, payload.toByteArray());
                    break;
                case 1:
                case 2:
                    if (msgOpcode == -1) msgOpcode = opcode;
                    payload.write(data);
                    if (fin) return new Message(msgOpcode, payload.toByteArray());
                    break;
                default:
                    break;
            }
        }
    }

    static void sendFrame(OutputStream out, int opcode, byte[] payload) throws IOException {
        int len = payload.length;
        ByteArrayOutputStream buf = new ByteArrayOutputStream();

        buf.write(0x80 | opcode);

        if (len <= 125) {
            buf.write(0x80 | len);
        } else if (len <= 65535) {
            buf.write(0x80 | 126);
            buf.write((len >> 8) & 0xFF);
            buf.write(len & 0xFF);
        } else {
            buf.write(0x80 | 127);
            long longLen = len & 0xFFFFFFFFL;
            for (int i = 7; i >= 0; i--) {
                buf.write((int) ((longLen >>> (8 * i)) & 0xFF));
            }
        }

        byte[] mask = new byte[4];
        do {
            random.nextBytes(mask);
        } while (mask[0] == 0 && mask[1] == 0 && mask[2] == 0 && mask[3] == 0);
        buf.write(mask);

        byte[] masked = new byte[len];
        for (int i = 0; i < len; i++) {
            masked[i] = (byte) (payload[i] ^ mask[i % 4]);
        }
        buf.write(masked);

        out.write(buf.toByteArray());
        out.flush();
    }

    static void sendText(OutputStream out, String text) throws IOException {
        sendFrame(out, 1, text.getBytes(StandardCharsets.UTF_8));
    }

    static void sendPong(OutputStream out, byte[] data) throws IOException {
        sendFrame(out, 10, data);
    }

    static void sendClose(OutputStream out, int code) throws IOException {
        byte[] payload = new byte[2];
        payload[0] = (byte) ((code >> 8) & 0xFF);
        payload[1] = (byte) (code & 0xFF);
        sendFrame(out, 8, payload);
    }

    static void readFully(InputStream in, byte[] buf) throws IOException {
        int offset = 0;
        while (offset < buf.length) {
            int n = in.read(buf, offset, buf.length - offset);
            if (n == -1) throw new EOFException();
            offset += n;
        }
    }

    static String reverseCodePoints(String s) {
        int[] cps = s.codePoints().toArray();
        for (int i = 0, j = cps.length - 1; i < j; i++, j--) {
            int tmp = cps[i];
            cps[i] = cps[j];
            cps[j] = tmp;
        }
        return new String(cps, 0, cps.length);
    }

    static String bytesToHex(byte[] bytes) {
        StringBuilder sb = new StringBuilder();
        for (byte b : bytes) {
            sb.append(String.format("%02x", b & 0xFF));
        }
        return sb.toString();
    }

    static class Message {
        int opcode;
        byte[] payload;
        Message(int opcode, byte[] payload) {
            this.opcode = opcode;
            this.payload = payload;
        }
    }
}

import * as net from 'net';
import * as crypto from 'crypto';

class BufferedReader {
  private buffer: Buffer = Buffer.alloc(0);
  private offset = 0;
  private ended = false;
  private error: Error | null = null;
  private waitingResolve: (() => void) | null = null;

  constructor(private socket: net.Socket) {
    this.socket.on('data', (chunk: Buffer) => {
      if (this.offset > 0) {
        this.buffer = Buffer.concat([this.buffer.subarray(this.offset), chunk]);
        this.offset = 0;
      } else {
        this.buffer = Buffer.concat([this.buffer, chunk]);
      }
      this.wake();
    });
    this.socket.on('end', () => { this.ended = true; this.wake(); });
    this.socket.on('close', () => { this.ended = true; this.wake(); });
    this.socket.on('error', (err) => { this.error = err; this.ended = true; this.wake(); });
  }

  private wake() {
    if (this.waitingResolve) {
      const r = this.waitingResolve;
      this.waitingResolve = null;
      r();
    }
  }

  private available(): number {
    return this.buffer.length - this.offset;
  }

  async readExactly(n: number): Promise<Buffer> {
    if (n === 0) return Buffer.alloc(0);
    while (this.available() < n) {
      if (this.ended || this.error) throw new Error('Connection closed');
      await new Promise<void>(resolve => { this.waitingResolve = resolve; });
    }
    const result = this.buffer.subarray(this.offset, this.offset + n);
    this.offset += n;
    return result;
  }

  async readHttpHeaders(): Promise<string> {
    while (true) {
      const data = this.buffer.subarray(this.offset);
      const idx = data.indexOf('\r\n\r\n');
      if (idx !== -1) {
        const headerBlock = data.subarray(0, idx + 4).toString('utf-8');
        this.offset += idx + 4;
        return headerBlock;
      }
      if (this.ended || this.error) throw new Error('Connection closed before headers complete');
      await new Promise<void>(resolve => { this.waitingResolve = resolve; });
    }
  }
}

function parseWsUrl(url: string): { host: string; port: number; path: string } {
  const rest = url.slice(5); // remove "ws://"
  const slashIdx = rest.indexOf('/');
  const hostPort = slashIdx === -1 ? rest : rest.slice(0, slashIdx);
  const path = slashIdx === -1 ? '/' : rest.slice(slashIdx);
  const colonIdx = hostPort.lastIndexOf(':');
  return { host: hostPort.slice(0, colonIdx), port: parseInt(hostPort.slice(colonIdx + 1)), path };
}

function encodeFrame(opcode: number, payload: Buffer): Buffer {
  const fin = 0x80;
  let header: Buffer;
  if (payload.length <= 125) {
    header = Buffer.alloc(2);
    header[0] = fin | opcode;
    header[1] = 0x80 | payload.length;
  } else if (payload.length <= 65535) {
    header = Buffer.alloc(4);
    header[0] = fin | opcode;
    header[1] = 0x80 | 126;
    header.writeUInt16BE(payload.length, 2);
  } else {
    header = Buffer.alloc(10);
    header[0] = fin | opcode;
    header[1] = 0x80 | 127;
    header.writeBigUInt64BE(BigInt(payload.length), 2);
  }
  let maskKey: Buffer;
  do { maskKey = crypto.randomBytes(4); } while (maskKey[0] === 0 && maskKey[1] === 0 && maskKey[2] === 0 && maskKey[3] === 0);
  const masked = Buffer.alloc(payload.length);
  for (let i = 0; i < payload.length; i++) masked[i] = payload[i] ^ maskKey[i & 3];
  return Buffer.concat([header, maskKey, masked]);
}

async function readFrame(reader: BufferedReader): Promise<{ fin: boolean; opcode: number; payload: Buffer }> {
  const h = await reader.readExactly(2);
  const fin = (h[0] & 0x80) !== 0;
  const opcode = h[0] & 0x0F;
  const masked = (h[1] & 0x80) !== 0;
  let payloadLen = h[1] & 0x7F;
  if (payloadLen === 126) {
    payloadLen = (await reader.readExactly(2)).readUInt16BE(0);
  } else if (payloadLen === 127) {
    payloadLen = Number((await reader.readExactly(8)).readBigUInt64BE(0));
  }
  let maskKey: Buffer | null = null;
  if (masked) maskKey = await reader.readExactly(4);
  let payload = await reader.readExactly(payloadLen);
  if (maskKey) {
    const unmasked = Buffer.alloc(payload.length);
    for (let i = 0; i < payload.length; i++) unmasked[i] = payload[i] ^ maskKey[i & 3];
    payload = unmasked;
  }
  return { fin, opcode, payload };
}

function connect(host: string, port: number): Promise<net.Socket> {
  return new Promise((resolve, reject) => {
    const s = net.createConnection({ host, port }, () => resolve(s));
    s.on('error', reject);
  });
}

async function processSession(url: string, sessionNum: number): Promise<void> {
  console.log(`session ${sessionNum}`);
  const { host, port, path } = parseWsUrl(url);

  let socket: net.Socket;
  try { socket = await connect(host, port); } catch { return; }

  const reader = new BufferedReader(socket);
  const key = crypto.randomBytes(16).toString('base64');

  socket.write(
    `GET ${path} HTTP/1.1\r\n` +
    `Host: ${host}:${port}\r\n` +
    `Upgrade: websocket\r\n` +
    `Connection: Upgrade\r\n` +
    `Sec-WebSocket-Version: 13\r\n` +
    `Sec-WebSocket-Key: ${key}\r\n` +
    `\r\n`
  );

  let headerBlock: string;
  try { headerBlock = await reader.readHttpHeaders(); } catch { socket.destroy(); return; }

  const lines = headerBlock.split('\r\n');
  const statusLine = lines[0];
  const sp1 = statusLine.indexOf(' ');
  const sp2 = statusLine.indexOf(' ', sp1 + 1);
  const statusCode = parseInt(statusLine.slice(sp1 + 1, sp2));
  const reasonPhrase = statusLine.slice(sp2 + 1);

  if (statusCode !== 101) {
    console.log(`handshake failed: ${statusCode} ${reasonPhrase}`);
    socket.destroy();
    return;
  }

  const expectedAccept = crypto.createHash('sha1')
    .update(key + "258EAFA5-E914-47DA-95CA-C5AB0DC85B11")
    .digest('base64');

  let acceptValue: string | undefined;
  for (let i = 1; i < lines.length; i++) {
    const ci = lines[i].indexOf(':');
    if (ci !== -1 && lines[i].slice(0, ci).trim().toLowerCase() === 'sec-websocket-accept') {
      acceptValue = lines[i].slice(ci + 1).trim();
      break;
    }
  }

  if (acceptValue !== expectedAccept) {
    console.log('handshake failed: bad Sec-WebSocket-Accept');
    socket.destroy();
    return;
  }

  let sentClose = false;
  let currentMessage: { opcode: number; fragments: Buffer[] } | null = null;
  let pendingSHA1 = false;

  function sendFrame(opcode: number, payload: Buffer) {
    socket.write(encodeFrame(opcode, payload));
  }

  function sendClose(code: number) {
    const p = Buffer.alloc(2);
    p.writeUInt16BE(code, 0);
    sendFrame(8, p);
    sentClose = true;
  }

  function handleClose(payload: Buffer) {
    let code: number, reason: string;
    if (payload.length >= 2) {
      code = payload.readUInt16BE(0);
      reason = payload.subarray(2).toString('utf-8');
    } else {
      code = 1005;
      reason = '';
    }
    console.log(reason.length > 0 ? `closed ${code} ${reason}` : `closed ${code}`);
    if (!sentClose) sendClose(code);
    socket.destroy();
  }

  function handleText(text: string) {
    if (text === 'SHA1') { pendingSHA1 = true; return; }
    if (text === 'BYE') { sendClose(1000); return; }
    if (text.startsWith('ADD ')) {
      const parts = text.slice(4).split(' ');
      const sum = parseInt(parts[0]) + parseInt(parts[1]);
      const reply = String(sum);
      sendFrame(1, Buffer.from(reply, 'utf-8'));
      console.log(`${text} -> ${reply}`);
      return;
    }
    if (text.startsWith('REV ')) {
      const t = text.slice(4);
      const reversed = Array.from(t).reverse().join('');
      sendFrame(1, Buffer.from(reversed, 'utf-8'));
      console.log(`${text} -> ${reversed}`);
      return;
    }
  }

  function handleBinary(payload: Buffer) {
    if (pendingSHA1) {
      const hash = crypto.createHash('sha1').update(payload).digest('hex');
      sendFrame(1, Buffer.from(hash, 'utf-8'));
      console.log(`SHA1 ${payload.length} -> ${hash}`);
      pendingSHA1 = false;
    }
  }

  function completeMessage(msg: { opcode: number; fragments: Buffer[] }) {
    const payload = Buffer.concat(msg.fragments);
    if (msg.opcode === 1) handleText(payload.toString('utf-8'));
    else if (msg.opcode === 2) handleBinary(payload);
  }

  try {
    while (true) {
      const frame = await readFrame(reader);
      if (frame.opcode === 9) { sendFrame(10, frame.payload); continue; }
      if (frame.opcode === 10) { continue; }
      if (frame.opcode === 8) { handleClose(frame.payload); return; }
      if (frame.opcode === 0) {
        if (currentMessage) {
          currentMessage.fragments.push(frame.payload);
          if (frame.fin) { completeMessage(currentMessage); currentMessage = null; }
        }
      } else {
        currentMessage = { opcode: frame.opcode, fragments: [frame.payload] };
        if (frame.fin) { completeMessage(currentMessage); currentMessage = null; }
      }
    }
  } catch {
    socket.destroy();
  }
}

async function main() {
  const urls = process.argv.slice(2);
  for (let i = 0; i < urls.length; i++) {
    await processSession(urls[i], i + 1);
  }
}

main().catch(() => {});

use std::io::{Read, Write};
use std::net::TcpStream;

// ============ SHA-1 ============
fn sha1(data: &[u8]) -> [u8; 20] {
    let mut h: [u32; 5] = [0x67452301, 0xEFCDAB89, 0x98BADCFE, 0x10325476, 0xC3D2E1F0];
    let ml = data.len() as u64 * 8;
    let mut msg = data.to_vec();
    msg.push(0x80);
    while msg.len() % 64 != 56 {
        msg.push(0);
    }
    msg.extend_from_slice(&ml.to_be_bytes());
    for chunk in msg.chunks(64) {
        let mut w = [0u32; 80];
        for i in 0..16 {
            w[i] = u32::from_be_bytes([chunk[i*4], chunk[i*4+1], chunk[i*4+2], chunk[i*4+3]]);
        }
        for i in 16..80 {
            w[i] = (w[i-3] ^ w[i-8] ^ w[i-14] ^ w[i-16]).rotate_left(1);
        }
        let mut a = h[0]; let mut b = h[1]; let mut c = h[2]; let mut d = h[3]; let mut e = h[4];
        for i in 0..80 {
            let (f, k) = if i < 20 {
                ((b & c) | ((!b) & d), 0x5A827999u32)
            } else if i < 40 {
                (b ^ c ^ d, 0x6ED9EBA1u32)
            } else if i < 60 {
                ((b & c) | (b & d) | (c & d), 0x8F1BBCDCu32)
            } else {
                (b ^ c ^ d, 0xCA62C1D6u32)
            };
            let tmp = a.rotate_left(5).wrapping_add(f).wrapping_add(e).wrapping_add(k).wrapping_add(w[i]);
            e = d; d = c; c = b.rotate_left(30); b = a; a = tmp;
        }
        h[0] = h[0].wrapping_add(a);
        h[1] = h[1].wrapping_add(b);
        h[2] = h[2].wrapping_add(c);
        h[3] = h[3].wrapping_add(d);
        h[4] = h[4].wrapping_add(e);
    }
    let mut out = [0u8; 20];
    for i in 0..5 { out[i*4..i*4+4].copy_from_slice(&h[i].to_be_bytes()); }
    out
}

fn sha1_hex(data: &[u8]) -> String {
    sha1(data).iter().map(|b| format!("{:02x}", b)).collect()
}

// ============ Base64 ============
fn base64_encode(data: &[u8]) -> String {
    const C: &[u8] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
    let mut r = String::new();
    for ch in data.chunks(3) {
        let b0 = ch[0] as u32;
        let b1 = if ch.len() > 1 { ch[1] as u32 } else { 0 };
        let b2 = if ch.len() > 2 { ch[2] as u32 } else { 0 };
        let n = (b0 << 16) | (b1 << 8) | b2;
        r.push(C[((n >> 18) & 63) as usize] as char);
        r.push(C[((n >> 12) & 63) as usize] as char);
        if ch.len() > 1 { r.push(C[((n >> 6) & 63) as usize] as char); } else { r.push('='); }
        if ch.len() > 2 { r.push(C[(n & 63) as usize] as char); } else { r.push('='); }
    }
    r
}

// ============ Random ============
fn random_bytes(n: usize) -> Vec<u8> {
    let mut f = std::fs::File::open("/dev/urandom").unwrap();
    let mut buf = vec![0u8; n];
    f.read_exact(&mut buf).unwrap();
    buf
}

// ============ WebSocket ============
struct Frame {
    fin: bool,
    opcode: u8,
    payload: Vec<u8>,
}

struct WsConn {
    stream: TcpStream,
    buf: Vec<u8>,
    pos: usize,
    sent_close: bool,
}

impl WsConn {
    fn fill(&mut self) {
        if self.pos >= self.buf.len() {
            self.buf.clear();
            self.pos = 0;
        }
        if self.buf.is_empty() {
            let mut tmp = vec![0u8; 65536];
            if let Ok(n) = self.stream.read(&mut tmp) {
                if n > 0 {
                    self.buf = tmp[..n].to_vec();
                    self.pos = 0;
                }
            }
        }
    }

    fn read_byte(&mut self) -> Option<u8> {
        self.fill();
        if self.pos < self.buf.len() {
            let b = self.buf[self.pos];
            self.pos += 1;
            Some(b)
        } else {
            None
        }
    }

    fn read_exact(&mut self, n: usize) -> Option<Vec<u8>> {
        let mut v = Vec::with_capacity(n);
        for _ in 0..n {
            match self.read_byte() {
                Some(b) => v.push(b),
                None => return None,
            }
        }
        Some(v)
    }

    fn read_frame(&mut self) -> Option<Frame> {
        let b0 = self.read_byte()?;
        let b1 = self.read_byte()?;
        let fin = (b0 & 0x80) != 0;
        let opcode = b0 & 0x0F;
        let masked = (b1 & 0x80) != 0;
        let mut plen = (b1 & 0x7F) as u64;
        if plen == 126 {
            let b = self.read_exact(2)?;
            plen = u16::from_be_bytes([b[0], b[1]]) as u64;
        } else if plen == 127 {
            let b = self.read_exact(8)?;
            plen = u64::from_be_bytes([b[0],b[1],b[2],b[3],b[4],b[5],b[6],b[7]]);
        }
        let mut mask = [0u8; 4];
        if masked {
            let m = self.read_exact(4)?;
            mask = [m[0], m[1], m[2], m[3]];
        }
        let mut payload = self.read_exact(plen as usize)?;
        if masked {
            for i in 0..payload.len() {
                payload[i] ^= mask[i % 4];
            }
        }
        Some(Frame { fin, opcode, payload })
    }

    fn write_frame(&mut self, opcode: u8, payload: &[u8]) {
        let mut frame = Vec::new();
        frame.push(0x80 | opcode);
        let mk = {
            let mut k = random_bytes(4);
            if k[0] == 0 && k[1] == 0 && k[2] == 0 && k[3] == 0 { k[0] = 1; }
            [k[0], k[1], k[2], k[3]]
        };
        let len = payload.len();
        if len <= 125 {
            frame.push(0x80 | len as u8);
        } else if len <= 65535 {
            frame.push(0x80 | 126);
            frame.extend_from_slice(&(len as u16).to_be_bytes());
        } else {
            frame.push(0x80 | 127);
            frame.extend_from_slice(&(len as u64).to_be_bytes());
        }
        frame.extend_from_slice(&mk);
        for (i, &b) in payload.iter().enumerate() {
            frame.push(b ^ mk[i % 4]);
        }
        self.stream.write_all(&frame).unwrap();
        self.stream.flush().unwrap();
    }

    fn send_close(&mut self, code: u16, reason: &str) {
        let mut p = code.to_be_bytes().to_vec();
        p.extend_from_slice(reason.as_bytes());
        self.write_frame(8, &p);
        self.sent_close = true;
    }

    /// Read a complete message (reassembling fragments, handling ping/pong).
    /// Returns the assembled message, or a close frame, or None on disconnect.
    fn read_message(&mut self) -> Option<Frame> {
        let mut msg_op = 0u8;
        let mut msg_data: Vec<u8> = Vec::new();
        loop {
            let f = self.read_frame()?;
            match f.opcode {
                8 => return Some(f),
                9 => { self.write_frame(10, &f.payload); }
                10 => {}
                0 => {
                    msg_data.extend_from_slice(&f.payload);
                    if f.fin {
                        return Some(Frame { fin: true, opcode: msg_op, payload: msg_data });
                    }
                }
                1 | 2 => {
                    msg_op = f.opcode;
                    msg_data.extend_from_slice(&f.payload);
                    if f.fin {
                        return Some(Frame { fin: true, opcode: msg_op, payload: msg_data });
                    }
                }
                _ => {
                    if f.fin { return Some(f); }
                }
            }
        }
    }
}

// ============ URL parsing ============
fn parse_url(url: &str) -> (String, u16, String) {
    let rest = url.strip_prefix("ws://").unwrap();
    let slash = rest.find('/').unwrap_or(rest.len());
    let hp = &rest[..slash];
    let path = if slash < rest.len() { &rest[slash..] } else { "/" };
    let colon = hp.rfind(':').unwrap();
    let host = hp[..colon].to_string();
    let port: u16 = hp[colon + 1..].parse().unwrap();
    (host, port, path.to_string())
}

// ============ Header reading ============
fn read_headers(conn: &mut WsConn) -> String {
    let mut buf: Vec<u8> = Vec::new();
    let mut tail = [0u8; 4];
    loop {
        match conn.read_byte() {
            Some(b) => {
                buf.push(b);
                tail[0] = tail[1]; tail[1] = tail[2]; tail[2] = tail[3]; tail[3] = b;
                if tail == [13, 10, 13, 10] { break; }
            }
            None => break,
        }
    }
    let hdr = if buf.len() >= 4 { &buf[..buf.len() - 4] } else { &buf[..] };
    String::from_utf8_lossy(hdr).to_string()
}

// ============ Close handling ============
fn handle_close(conn: &mut WsConn, payload: &[u8]) {
    if payload.len() >= 2 {
        let code = u16::from_be_bytes([payload[0], payload[1]]);
        let reason = String::from_utf8_lossy(&payload[2..]).to_string();
        if reason.is_empty() {
            println!("closed {}", code);
        } else {
            println!("closed {} {}", code, reason);
        }
        if !conn.sent_close {
            conn.send_close(code, "");
        }
    } else {
        if !conn.sent_close {
            conn.send_close(1005, "");
        }
    }
}

// ============ Session processing ============
fn process_messages(conn: &mut WsConn) {
    loop {
        let msg = match conn.read_message() {
            Some(m) => m,
            None => break,
        };
        match msg.opcode {
            8 => {
                handle_close(conn, &msg.payload);
                break;
            }
            1 => {
                let text = String::from_utf8_lossy(&msg.payload).to_string();
                if text == "BYE" {
                    conn.send_close(1000, "");
                    loop {
                        let m2 = match conn.read_message() {
                            Some(m) => m,
                            None => break,
                        };
                        if m2.opcode == 8 {
                            handle_close(conn, &m2.payload);
                            break;
                        }
                    }
                    break;
                } else if text.starts_with("ADD ") {
                    let rest = &text[4..];
                    let sp = rest.find(' ').unwrap_or(rest.len());
                    let a: i64 = rest[..sp].parse().unwrap_or(0);
                    let b: i64 = rest[sp + 1..].parse().unwrap_or(0);
                    let sum = a + b;
                    let reply = sum.to_string();
                    conn.write_frame(1, reply.as_bytes());
                    println!("{} -> {}", text, reply);
                } else if text.starts_with("REV ") {
                    let txt = &text[4..];
                    let rev: String = txt.chars().rev().collect();
                    conn.write_frame(1, rev.as_bytes());
                    println!("{} -> {}", text, rev);
                } else if text == "SHA1" {
                    let bin = match conn.read_message() {
                        Some(m) => m,
                        None => break,
                    };
                    if bin.opcode == 8 {
                        handle_close(conn, &bin.payload);
                        break;
                    }
                    let hex = sha1_hex(&bin.payload);
                    let len = bin.payload.len();
                    conn.write_frame(1, hex.as_bytes());
                    println!("SHA1 {} -> {}", len, hex);
                }
            }
            2 => {
                // unexpected binary outside SHA1 context; ignore
            }
            _ => {}
        }
    }
}

// ============ Session ============
fn process_session(url: &str) {
    let (host, port, path) = parse_url(url);
    let stream = match TcpStream::connect(format!("{}:{}", host, port)) {
        Ok(s) => s,
        Err(_) => return,
    };
    let key_bytes = random_bytes(16);
    let key = base64_encode(&key_bytes);
    let req = format!(
        "GET {} HTTP/1.1\r\nHost: {}:{}\r\nUpgrade: websocket\r\nConnection: Upgrade\r\nSec-WebSocket-Version: 13\r\nSec-WebSocket-Key: {}\r\n\r\n",
        path, host, port, key
    );
    let mut conn = WsConn { stream, buf: Vec::new(), pos: 0, sent_close: false };
    conn.stream.write_all(req.as_bytes()).unwrap();
    conn.stream.flush().unwrap();

    let hdr_block = read_headers(&mut conn);
    let first_line = hdr_block.lines().next().unwrap_or("");
    let parts: Vec<&str> = first_line.splitn(3, ' ').collect();
    if parts.len() < 2 {
        println!("handshake failed: unknown");
        return;
    }
    let status: u16 = parts[1].parse().unwrap_or(0);
    let reason = if parts.len() > 2 { parts[2] } else { "" };
    if status != 101 {
        println!("handshake failed: {} {}", status, reason);
        return;
    }

    // Verify Sec-WebSocket-Accept
    let expected = {
        let mut s = key.clone();
        s.push_str("258EAFA5-E914-47DA-95CA-C5AB0DC85B11");
        base64_encode(&sha1(s.as_bytes()))
    };
    let mut ok = false;
    for line in hdr_block.lines().skip(1) {
        if let Some(colon) = line.find(':') {
            if line[..colon].trim().eq_ignore_ascii_case("sec-websocket-accept") {
                if line[colon + 1..].trim() == expected {
                    ok = true;
                }
                break;
            }
        }
    }
    if !ok {
        println!("handshake failed: bad Sec-WebSocket-Accept");
        return;
    }

    process_messages(&mut conn);
}

// ============ Main ============
fn main() {
    let args: Vec<String> = std::env::args().skip(1).collect();
    for (i, url) in args.iter().enumerate() {
        println!("session {}", i + 1);
        process_session(url);
    }
}

use std::collections::HashMap;
use std::env;
use std::fs;
use std::io::{self, BufRead, Write};

#[derive(Clone, Debug)]
struct TypeRecord {
    utoff: i64,
    #[allow(dead_code)]
    isdst: bool,
    abbr: String,
}

#[derive(Clone, Debug)]
struct FooterRule {
    std_abbr: String,
    std_utoff: i64,
    dst_abbr: String,
    dst_utoff: i64,
    dst_start: Option<Rule>,
    dst_end: Option<Rule>,
    has_dst: bool,
}

#[derive(Clone, Debug)]
struct Rule {
    month: u32,
    week: u32,
    day: u32,
    time: i64,
}

struct TzData {
    transitions: Vec<(i64, usize)>,
    types: Vec<TypeRecord>,
    footer: Option<FooterRule>,
}

fn main() {
    let args: Vec<String> = env::args().collect();
    let dir = &args[1];
    let content = fs::read_to_string(format!("{}/queries.txt", dir)).unwrap();
    let mut tz_cache: HashMap<String, TzData> = HashMap::new();
    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());

    for line in content.lines() {
        if line.trim().is_empty() {
            continue;
        }
        let parts: Vec<&str> = line.split_whitespace().collect();
        let file_name = parts[1];
        let tz = tz_cache
            .entry(file_name.to_string())
            .or_insert_with(|| parse_tzif(&format!("{}/{}", dir, file_name)));

        if parts[0] == "UTC" {
            let t: i64 = parts[2].parse().unwrap();
            let (offset, abbr) = tz.get_local_info(t);
            writeln!(
                out,
                "{} -> {}{} {}",
                line,
                format_datetime(epoch_to_local(t, offset)),
                format_offset(offset),
                abbr
            )
            .unwrap();
        } else {
            let (y, mo, d, h, mi, s) = parse_datetime(parts[2]);
            let w_epoch = datetime_to_epoch(y, mo, d, h, mi, s);
            let solutions = tz.find_local_times(w_epoch);
            if solutions.len() == 1 {
                let (t, o, a) = solutions[0];
                writeln!(out, "{} -> {} {} {}", line, t, format_offset(o), a).unwrap();
            } else if solutions.len() >= 2 {
                let (t1, o1, a1) = solutions[0];
                let (t2, o2, a2) = solutions[1];
                writeln!(
                    out,
                    "{} -> {} {} {} | {} {} {}",
                    line,
                    t1,
                    format_offset(o1),
                    a1,
                    t2,
                    format_offset(o2),
                    a2
                )
                .unwrap();
            } else {
                let (t, o, a) = tz.find_gap(w_epoch);
                writeln!(
                    out,
                    "{} -> GAP {} {}{} {}",
                    line,
                    t,
                    format_datetime(epoch_to_local(t, o)),
                    format_offset(o),
                    a
                )
                .unwrap();
            }
        }
    }
    out.flush().unwrap();
}

fn read_be32(d: &[u8], p: usize) -> i32 {
    i32::from_be_bytes([d[p], d[p + 1], d[p + 2], d[p + 3]])
}
fn read_be64(d: &[u8], p: usize) -> i64 {
    i64::from_be_bytes([
        d[p], d[p + 1], d[p + 2], d[p + 3], d[p + 4], d[p + 5], d[p + 6], d[p + 7],
    ])
}

fn parse_tzif(path: &str) -> TzData {
    let data = fs::read(path).unwrap();
    let mut pos: usize = 0;
    assert_eq!(&data[0..4], b"TZif");
    pos = 20;
    let isutcnt1 = read_be32(&data, pos) as usize;
    pos += 4;
    let isstdcnt1 = read_be32(&data, pos) as usize;
    pos += 4;
    let leapcnt1 = read_be32(&data, pos) as usize;
    pos += 4;
    let timecnt1 = read_be32(&data, pos) as usize;
    pos += 4;
    let typecnt1 = read_be32(&data, pos) as usize;
    pos += 4;
    let charcnt1 = read_be32(&data, pos) as usize;
    pos += 4;
    pos += timecnt1 * 4 + timecnt1 + typecnt1 * 6 + charcnt1 + leapcnt1 * 8 + isstdcnt1 + isutcnt1;

    assert_eq!(&data[pos..pos + 4], b"TZif");
    pos += 20;
    let isutcnt = read_be32(&data, pos) as usize;
    pos += 4;
    let isstdcnt = read_be32(&data, pos) as usize;
    pos += 4;
    let leapcnt = read_be32(&data, pos) as usize;
    pos += 4;
    let timecnt = read_be32(&data, pos) as usize;
    pos += 4;
    let typecnt = read_be32(&data, pos) as usize;
    pos += 4;
    let charcnt = read_be32(&data, pos) as usize;
    pos += 4;

    let mut trans_times = Vec::with_capacity(timecnt);
    for _ in 0..timecnt {
        trans_times.push(read_be64(&data, pos));
        pos += 8;
    }
    let mut trans_types = Vec::with_capacity(timecnt);
    for _ in 0..timecnt {
        trans_types.push(data[pos] as usize);
        pos += 1;
    }
    let mut raw_types = Vec::with_capacity(typecnt);
    for _ in 0..typecnt {
        let utoff = read_be32(&data, pos) as i64;
        let isdst = data[pos + 4] != 0;
        let abbr_idx = data[pos + 5] as usize;
        raw_types.push((utoff, isdst, abbr_idx));
        pos += 6;
    }
    let chars = &data[pos..pos + charcnt];
    let mut types = Vec::with_capacity(typecnt);
    for &(utoff, isdst, abbr_idx) in &raw_types {
        let end = chars[abbr_idx..]
            .iter()
            .position(|&b| b == 0)
            .unwrap_or(chars.len() - abbr_idx);
        let abbr = String::from_utf8_lossy(&chars[abbr_idx..abbr_idx + end]).to_string();
        types.push(TypeRecord {
            utoff,
            isdst,
            abbr,
        });
    }
    pos += charcnt;
    pos += leapcnt * 12 + isstdcnt + isutcnt;

    assert_eq!(data[pos], b'\n');
    pos += 1;
    let footer_end = data[pos..].iter().position(|&b| b == b'\n').unwrap() + pos;
    let footer_str = std::str::from_utf8(&data[pos..footer_end]).unwrap();
    let footer = if footer_str.is_empty() {
        None
    } else {
        Some(parse_posix_tz(footer_str))
    };

    let transitions: Vec<(i64, usize)> = trans_times.into_iter().zip(trans_types).collect();
    TzData {
        transitions,
        types,
        footer,
    }
}

fn parse_posix_tz(s: &str) -> FooterRule {
    let b = s.as_bytes();
    let mut p = 0usize;
    let std_abbr = parse_tz_name(b, &mut p);
    let std_posix_off = parse_tz_offset(b, &mut p);
    let std_utoff = -std_posix_off;

    if p >= b.len() {
        return FooterRule {
            std_abbr,
            std_utoff,
            dst_abbr: String::new(),
            dst_utoff: std_utoff,
            dst_start: None,
            dst_end: None,
            has_dst: false,
        };
    }
    let dst_abbr = parse_tz_name(b, &mut p);
    let dst_utoff = if p < b.len() && (b[p] == b'+' || b[p] == b'-' || b[p].is_ascii_digit()) {
        let dst_posix_off = parse_tz_offset(b, &mut p);
        -dst_posix_off
    } else {
        std_utoff + 3600
    };
    let (dst_start, dst_end) = if p < b.len() && b[p] == b',' {
        p += 1;
        let start = parse_rule(b, &mut p);
        p += 1;
        let end = parse_rule(b, &mut p);
        (Some(start), Some(end))
    } else {
        (None, None)
    };
    FooterRule {
        std_abbr,
        std_utoff,
        dst_abbr,
        dst_utoff,
        dst_start,
        dst_end,
        has_dst: true,
    }
}

fn parse_tz_name(b: &[u8], p: &mut usize) -> String {
    if b[*p] == b'<' {
        *p += 1;
        let start = *p;
        while *p < b.len() && b[*p] != b'>' {
            *p += 1;
        }
        let name = String::from_utf8_lossy(&b[start..*p]).to_string();
        *p += 1;
        name
    } else {
        let start = *p;
        while *p < b.len() && b[*p].is_ascii_alphabetic() {
            *p += 1;
        }
        String::from_utf8_lossy(&b[start..*p]).to_string()
    }
}

fn parse_tz_offset(b: &[u8], p: &mut usize) -> i64 {
    let mut sign: i64 = 1;
    if *p < b.len() && (b[*p] == b'+' || b[*p] == b'-') {
        if b[*p] == b'-' {
            sign = -1;
        }
        *p += 1;
    }
    let h = parse_number(b, p);
    let mut total = h * 3600;
    if *p < b.len() && b[*p] == b':' {
        *p += 1;
        let m = parse_number(b, p);
        total += m * 60;
        if *p < b.len() && b[*p] == b':' {
            *p += 1;
            let s = parse_number(b, p);
            total += s;
        }
    }
    sign * total
}

fn parse_number(b: &[u8], p: &mut usize) -> i64 {
    let start = *p;
    while *p < b.len() && b[*p].is_ascii_digit() {
        *p += 1;
    }
    std::str::from_utf8(&b[start..*p]).unwrap().parse().unwrap()
}

fn parse_rule(b: &[u8], p: &mut usize) -> Rule {
    assert_eq!(b[*p], b'M');
    *p += 1;
    let month = parse_number(b, p) as u32;
    assert_eq!(b[*p], b'.');
    *p += 1;
    let week = parse_number(b, p) as u32;
    assert_eq!(b[*p], b'.');
    *p += 1;
    let day = parse_number(b, p) as u32;
    let mut time = 2 * 3600;
    if *p < b.len() && b[*p] == b'/' {
        *p += 1;
        time = parse_tz_offset(b, p);
    }
    Rule {
        month,
        week,
        day,
        time,
    }
}

fn days_from_civil(y: i64, m: u32, d: u32) -> i64 {
    let y = if m <= 2 { y - 1 } else { y };
    let era = if y >= 0 { y } else { y - 399 } / 400;
    let yoe = y - era * 400;
    let mp = if m > 2 { m - 3 } else { m + 9 } as i64;
    let doy = (153 * mp + 2) / 5 + d as i64 - 1;
    let doe = yoe * 365 + yoe / 4 - yoe / 100 + doy;
    era * 146097 + doe - 719468
}

fn civil_from_days(z: i64) -> (i64, u32, u32) {
    let z = z + 719468;
    let era = if z >= 0 { z } else { z - 146096 } / 146097;
    let doe = z - era * 146097;
    let yoe = (doe - doe / 1460 + doe / 36524 - doe / 146096) / 365;
    let y = yoe + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let d = (doy - (153 * mp + 2) / 5 + 1) as u32;
    let m = if mp < 10 { mp + 3 } else { mp - 9 } as u32;
    (if m <= 2 { y + 1 } else { y }, m, d)
}

fn epoch_to_datetime(t: i64) -> (i64, u32, u32, u32, u32, u32) {
    let days = t.div_euclid(86400);
    let secs = t.rem_euclid(86400) as u32;
    let (year, month, day) = civil_from_days(days);
    (
        year,
        month,
        day,
        secs / 3600,
        (secs % 3600) / 60,
        secs % 60,
    )
}

fn epoch_to_local(t: i64, offset: i64) -> (i64, u32, u32, u32, u32, u32) {
    epoch_to_datetime(t + offset)
}

fn datetime_to_epoch(y: i64, mo: u32, d: u32, h: u32, mi: u32, s: u32) -> i64 {
    days_from_civil(y, mo, d) * 86400 + h as i64 * 3600 + mi as i64 * 60 + s as i64
}

fn parse_datetime(s: &str) -> (i64, u32, u32, u32, u32, u32) {
    (
        s[0..4].parse().unwrap(),
        s[5..7].parse().unwrap(),
        s[8..10].parse().unwrap(),
        s[11..13].parse().unwrap(),
        s[14..16].parse().unwrap(),
        s[17..19].parse().unwrap(),
    )
}

fn format_datetime(dt: (i64, u32, u32, u32, u32, u32)) -> String {
    let (y, mo, d, h, mi, s) = dt;
    format!("{:04}-{:02}-{:02}T{:02}:{:02}:{:02}", y, mo, d, h, mi, s)
}

fn format_offset(offset: i64) -> String {
    let sign = if offset >= 0 { '+' } else { '-' };
    let abs = offset.abs();
    let h = abs / 3600;
    let m = (abs % 3600) / 60;
    let s = abs % 60;
    if s != 0 {
        format!("{}{:02}:{:02}:{:02}", sign, h, m, s)
    } else {
        format!("{}{:02}:{:02}", sign, h, m)
    }
}

fn is_leap(y: i64) -> bool {
    (y % 4 == 0 && y % 100 != 0) || (y % 400 == 0)
}

fn days_in_month(y: i64, m: u32) -> u32 {
    match m {
        1 | 3 | 5 | 7 | 8 | 10 | 12 => 31,
        4 | 6 | 9 | 11 => 30,
        2 => {
            if is_leap(y) {
                29
            } else {
                28
            }
        }
        _ => unreachable!(),
    }
}

fn day_of_week(y: i64, m: u32, d: u32) -> u32 {
    ((days_from_civil(y, m, d) + 4).rem_euclid(7)) as u32
}

fn find_rule_day(month: u32, week: u32, dow: u32, year: i64) -> u32 {
    if week == 5 {
        let last_day = days_in_month(year, month);
        let last_dow = day_of_week(year, month, last_day);
        let diff = (last_dow as i64 - dow as i64 + 7) % 7;
        last_day - diff as u32
    } else {
        let first_dow = day_of_week(year, month, 1);
        let diff = (dow as i64 - first_dow as i64 + 7) % 7;
        1 + diff as u32 + (week - 1) * 7
    }
}

fn rule_to_utc(rule: &Rule, year: i64, utoff: i64) -> i64 {
    let day = find_rule_day(rule.month, rule.week, rule.day, year);
    let local_secs = days_from_civil(year, rule.month, day) * 86400 + rule.time;
    local_secs - utoff
}

impl TzData {
    fn get_local_info(&self, t: i64) -> (i64, String) {
        if self.transitions.is_empty() {
            if let Some(ref f) = self.footer {
                return self.footer_info(t, f);
            }
            let tr = &self.types[0];
            return (tr.utoff, tr.abbr.clone());
        }
        let first_t = self.transitions[0].0;
        let last_t = self.transitions.last().unwrap().0;
        if t < first_t {
            let tr = &self.types[0];
            return (tr.utoff, tr.abbr.clone());
        }
        if t > last_t {
            if let Some(ref f) = self.footer {
                return self.footer_info(t, f);
            }
            let tr = &self.types[self.transitions.last().unwrap().1];
            return (tr.utoff, tr.abbr.clone());
        }
        let idx = self.transitions.partition_point(|&(time, _)| time <= t) - 1;
        let tr = &self.types[self.transitions[idx].1];
        (tr.utoff, tr.abbr.clone())
    }

    fn footer_info(&self, t: i64, f: &FooterRule) -> (i64, String) {
        if !f.has_dst || f.dst_start.is_none() || f.dst_end.is_none() {
            if f.has_dst {
                return (f.dst_utoff, f.dst_abbr.clone());
            }
            return (f.std_utoff, f.std_abbr.clone());
        }
        let (year, _, _, _, _, _) = epoch_to_datetime(t);
        let dst_start_utc = rule_to_utc(f.dst_start.as_ref().unwrap(), year, f.std_utoff);
        let dst_end_utc = rule_to_utc(f.dst_end.as_ref().unwrap(), year, f.dst_utoff);
        let in_dst = if dst_start_utc < dst_end_utc {
            t >= dst_start_utc && t < dst_end_utc
        } else {
            t >= dst_start_utc || t < dst_end_utc
        };
        if in_dst {
            (f.dst_utoff, f.dst_abbr.clone())
        } else {
            (f.std_utoff, f.std_abbr.clone())
        }
    }

    fn all_offsets(&self) -> Vec<i64> {
        let mut offs: Vec<i64> = self.types.iter().map(|t| t.utoff).collect();
        if let Some(ref f) = self.footer {
            offs.push(f.std_utoff);
            if f.has_dst {
                offs.push(f.dst_utoff);
            }
        }
        offs.sort();
        offs.dedup();
        offs
    }

    fn find_local_times(&self, w_epoch: i64) -> Vec<(i64, i64, String)> {
        let offsets = self.all_offsets();
        let mut solutions = Vec::new();
        for &o in &offsets {
            let t = w_epoch - o;
            let (actual_offset, abbr) = self.get_local_info(t);
            if actual_offset == o {
                solutions.push((t, actual_offset, abbr));
            }
        }
        solutions.sort_by_key(|s| s.0);
        solutions.dedup_by_key(|s| s.0);
        solutions
    }

    fn find_gap(&self, w_epoch: i64) -> (i64, i64, String) {
        let mut candidates: Vec<(i64, i64, i64)> = Vec::new();
        let last_t = if self.transitions.is_empty() {
            i64::MIN
        } else {
            self.transitions.last().unwrap().0
        };

        // Table transitions (spring-forward only)
        for i in 0..self.transitions.len() {
            let (t, type_idx) = self.transitions[i];
            let o_new = self.types[type_idx].utoff;
            let o_old = if i > 0 {
                self.types[self.transitions[i - 1].1].utoff
            } else {
                self.types[0].utoff
            };
            if o_new > o_old {
                candidates.push((t, o_old, o_new));
            }
        }

        // Footer rule transitions
        if let Some(ref f) = self.footer {
            if f.has_dst && f.dst_start.is_some() && f.dst_end.is_some() {
                let (year, _, _, _, _, _) = epoch_to_datetime(w_epoch);
                for y in [year - 1, year, year + 1] {
                    let dst_start_utc = rule_to_utc(f.dst_start.as_ref().unwrap(), y, f.std_utoff);
                    let dst_end_utc = rule_to_utc(f.dst_end.as_ref().unwrap(), y, f.dst_utoff);
                    if dst_start_utc > last_t && f.dst_utoff > f.std_utoff {
                        candidates.push((dst_start_utc, f.std_utoff, f.dst_utoff));
                    }
                    if dst_end_utc > last_t && f.std_utoff > f.dst_utoff {
                        candidates.push((dst_end_utc, f.dst_utoff, f.std_utoff));
                    }
                }
            }
        }

        // Table-to-footer boundary
        if !self.transitions.is_empty() {
            if let Some(ref f) = self.footer {
                let boundary_t = last_t + 1;
                let o_old = self.types[self.transitions.last().unwrap().1].utoff;
                let (o_new, _) = self.footer_info(boundary_t, f);
                if o_new > o_old {
                    candidates.push((boundary_t, o_old, o_new));
                }
            }
        }

        for &(t, o_old, o_new) in &candidates {
            if t + o_old <= w_epoch && w_epoch < t + o_new {
                let result_t = w_epoch - o_old;
                let (offset, abbr) = self.get_local_info(result_t);
                return (result_t, offset, abbr);
            }
        }

        panic!("No gap transition found for w_epoch = {}", w_epoch);
    }
}

use std::collections::HashMap;
use std::env;
use std::fs;
use std::io::{self, Write};

#[derive(Clone, Debug)]
struct TypeRecord {
    utoff: i64,
    #[allow(dead_code)]
    isdst: bool,
    abbr: String,
}

#[derive(Clone, Debug)]
struct FooterRule {
    std_abbr: String,
    std_utoff: i64,
    dst_abbr: String,
    dst_utoff: i64,
    dst_start: Option<Rule>,
    dst_end: Option<Rule>,
    has_dst: bool,
}

#[derive(Clone, Debug)]
struct Rule {
    month: u32,
    week: u32,
    day: u32,
    time: i64,
}

struct TzData {
    transitions: Vec<(i64, usize)>,
    types: Vec<TypeRecord>,
    footer: Option<FooterRule>,
}

fn main() {
    let args: Vec<String> = env::args().collect();
    let dir = &args[1];
    let content = fs::read_to_string(format!("{}/queries.txt", dir)).unwrap();
    let mut tz_cache: HashMap<String, TzData> = HashMap::new();
    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());

    for line in content.lines() {
        if line.trim().is_empty() {
            continue;
        }
        let parts: Vec<&str> = line.split_whitespace().collect();
        let file_name = parts[1];
        let tz = tz_cache
            .entry(file_name.to_string())
            .or_insert_with(|| parse_tzif(&format!("{}/{}", dir, file_name)));

        if parts[0] == "UTC" {
            let t: i64 = parts[2].parse().unwrap();
            let (offset, ref abbr) = tz.get_local_info(t);
            writeln!(
                out,
                "{} -> {}{} {}",
                line,
                format_datetime(epoch_to_local(t, offset)),
                format_offset(offset),
                abbr
            )
            .unwrap();
        } else {
            let (y, mo, d, h, mi, s) = parse_datetime(parts[2]);
            let w_epoch = datetime_to_epoch(y, mo, d, h, mi, s);
            let solutions = tz.find_local_times(w_epoch);
            if solutions.len() == 1 {
                let (t, o, ref a) = solutions[0];
                writeln!(out, "{} -> {} {} {}", line, t, format_offset(o), a).unwrap();
            } else if solutions.len() >= 2 {
                let (t1, o1, ref a1) = solutions[0];
                let (t2, o2, ref a2) = solutions[1];
                writeln!(
                    out,
                    "{} -> {} {} {} | {} {} {}",
                    line,
                    t1,
                    format_offset(o1),
                    a1,
                    t2,
                    format_offset(o2),
                    a2
                )
                .unwrap();
            } else {
                let (t, o, ref a) = tz.find_gap(w_epoch);
                writeln!(
                    out,
                    "{} -> GAP {} {}{} {}",
                    line,
                    t,
                    format_datetime(epoch_to_local(t, o)),
                    format_offset(o),
                    a
                )
                .unwrap();
            }
        }
    }
    out.flush().unwrap();
}

fn read_be32(d: &[u8], p: usize) -> i32 {
    i32::from_be_bytes([d[p], d[p + 1], d[p + 2], d[p + 3]])
}
fn read_be64(d: &[u8], p: usize) -> i64 {
    i64::from_be_bytes([
        d[p], d[p + 1], d[p + 2], d[p + 3], d[p + 4], d[p + 5], d[p + 6], d[p + 7],
    ])
}

fn parse_tzif(path: &str) -> TzData {
    let data = fs::read(path).unwrap();
    let mut pos: usize = 0;
    assert_eq!(&data[0..4], b"TZif");
    pos = 20;
    let isutcnt1 = read_be32(&data, pos) as usize;
    pos += 4;
    let isstdcnt1 = read_be32(&data, pos) as usize;
    pos += 4;
    let leapcnt1 = read_be32(&data, pos) as usize;
    pos += 4;
    let timecnt1 = read_be32(&data, pos) as usize;
    pos += 4;
    let typecnt1 = read_be32(&data, pos) as usize;
    pos += 4;
    let charcnt1 = read_be32(&data, pos) as usize;
    pos += 4;
    pos += timecnt1 * 4 + timecnt1 + typecnt1 * 6 + charcnt1 + leapcnt1 * 8 + isstdcnt1 + isutcnt1;

    assert_eq!(&data[pos..pos + 4], b"TZif");
    pos += 20;
    let isutcnt = read_be32(&data, pos) as usize;
    pos += 4;
    let isstdcnt = read_be32(&data, pos) as usize;
    pos += 4;
    let leapcnt = read_be32(&data, pos) as usize;
    pos += 4;
    let timecnt = read_be32(&data, pos) as usize;
    pos += 4;
    let typecnt = read_be32(&data, pos) as usize;
    pos += 4;
    let charcnt = read_be32(&data, pos) as usize;
    pos += 4;

    let mut trans_times = Vec::with_capacity(timecnt);
    for _ in 0..timecnt {
        trans_times.push(read_be64(&data, pos));
        pos += 8;
    }
    let mut trans_types = Vec::with_capacity(timecnt);
    for _ in 0..timecnt {
        trans_types.push(data[pos] as usize);
        pos += 1;
    }
    let mut raw_types = Vec::with_capacity(typecnt);
    for _ in 0..typecnt {
        let utoff = read_be32(&data, pos) as i64;
        let isdst = data[pos + 4] != 0;
        let abbr_idx = data[pos + 5] as usize;
        raw_types.push((utoff, isdst, abbr_idx));
        pos += 6;
    }
    let chars = &data[pos..pos + charcnt];
    let mut types = Vec::with_capacity(typecnt);
    for &(utoff, isdst, abbr_idx) in &raw_types {
        let end = chars[abbr_idx..]
            .iter()
            .position(|&b| b == 0)
            .unwrap_or(chars.len() - abbr_idx);
        let abbr = String::from_utf8_lossy(&chars[abbr_idx..abbr_idx + end]).to_string();
        types.push(TypeRecord {
            utoff,
            isdst,
            abbr,
        });
    }
    pos += charcnt;
    pos += leapcnt * 12 + isstdcnt + isutcnt;

    assert_eq!(data[pos], b'\n');
    pos += 1;
    let footer_end = data[pos..].iter().position(|&b| b == b'\n').unwrap() + pos;
    let footer_str = std::str::from_utf8(&data[pos..footer_end]).unwrap();
    let footer = if footer_str.is_empty() {
        None
    } else {
        Some(parse_posix_tz(footer_str))
    };

    let transitions: Vec<(i64, usize)> = trans_times.into_iter().zip(trans_types).collect();
    TzData {
        transitions,
        types,
        footer,
    }
}

fn parse_posix_tz(s: &str) -> FooterRule {
    let b = s.as_bytes();
    let mut p = 0usize;
    let std_abbr = parse_tz_name(b, &mut p);
    let std_posix_off = parse_tz_offset(b, &mut p);
    let std_utoff = -std_posix_off;

    if p >= b.len() {
        return FooterRule {
            std_abbr,
            std_utoff,
            dst_abbr: String::new(),
            dst_utoff: std_utoff,
            dst_start: None,
            dst_end: None,
            has_dst: false,
        };
    }
    let dst_abbr = parse_tz_name(b, &mut p);
    let dst_utoff = if p < b.len() && (b[p] == b'+' || b[p] == b'-' || b[p].is_ascii_digit()) {
        let dst_posix_off = parse_tz_offset(b, &mut p);
        -dst_posix_off
    } else {
        std_utoff + 3600
    };
    let (dst_start, dst_end) = if p < b.len() && b[p] == b',' {
        p += 1;
        let start = parse_rule(b, &mut p);
        p += 1;
        let end = parse_rule(b, &mut p);
        (Some(start), Some(end))
    } else {
        (None, None)
    };
    FooterRule {
        std_abbr,
        std_utoff,
        dst_abbr,
        dst_utoff,
        dst_start,
        dst_end,
        has_dst: true,
    }
}

fn parse_tz_name(b: &[u8], p: &mut usize) -> String {
    if b[*p] == b'<' {
        *p += 1;
        let start = *p;
        while *p < b.len() && b[*p] != b'>' {
            *p += 1;
        }
        let name = String::from_utf8_lossy(&b[start..*p]).to_string();
        *p += 1;
        name
    } else {
        let start = *p;
        while *p < b.len() && b[*p].is_ascii_alphabetic() {
            *p += 1;
        }
        String::from_utf8_lossy(&b[start..*p]).to_string()
    }
}

fn parse_tz_offset(b: &[u8], p: &mut usize) -> i64 {
    let mut sign: i64 = 1;
    if *p < b.len() && (b[*p] == b'+' || b[*p] == b'-') {
        if b[*p] == b'-' {
            sign = -1;
        }
        *p += 1;
    }
    let h = parse_number(b, p);
    let mut total = h * 3600;
    if *p < b.len() && b[*p] == b':' {
        *p += 1;
        let m = parse_number(b, p);
        total += m * 60;
        if *p < b.len() && b[*p] == b':' {
            *p += 1;
            let s = parse_number(b, p);
            total += s;
        }
    }
    sign * total
}

fn parse_number(b: &[u8], p: &mut usize) -> i64 {
    let start = *p;
    while *p < b.len() && b[*p].is_ascii_digit() {
        *p += 1;
    }
    std::str::from_utf8(&b[start..*p]).unwrap().parse().unwrap()
}

fn parse_rule(b: &[u8], p: &mut usize) -> Rule {
    assert_eq!(b[*p], b'M');
    *p += 1;
    let month = parse_number(b, p) as u32;
    assert_eq!(b[*p], b'.');
    *p += 1;
    let week = parse_number(b, p) as u32;
    assert_eq!(b[*p], b'.');
    *p += 1;
    let day = parse_number(b, p) as u32;
    let mut time = 2 * 3600;
    if *p < b.len() && b[*p] == b'/' {
        *p += 1;
        time = parse_tz_offset(b, p);
    }
    Rule {
        month,
        week,
        day,
        time,
    }
}

fn days_from_civil(y: i64, m: u32, d: u32) -> i64 {
    let y = if m <= 2 { y - 1 } else { y };
    let era = if y >= 0 { y } else { y - 399 } / 400;
    let yoe = y - era * 400;
    let mp = if m > 2 { m - 3 } else { m + 9 } as i64;
    let doy = (153 * mp + 2) / 5 + d as i64 - 1;
    let doe = yoe * 365 + yoe / 4 - yoe / 100 + doy;
    era * 146097 + doe - 719468
}

fn civil_from_days(z: i64) -> (i64, u32, u32) {
    let z = z + 719468;
    let era = if z >= 0 { z } else { z - 146096 } / 146097;
    let doe = z - era * 146097;
    let yoe = (doe - doe / 1460 + doe / 36524 - doe / 146096) / 365;
    let y = yoe + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let d = (doy - (153 * mp + 2) / 5 + 1) as u32;
    let m = if mp < 10 { mp + 3 } else { mp - 9 } as u32;
    (if m <= 2 { y + 1 } else { y }, m, d)
}

fn epoch_to_datetime(t: i64) -> (i64, u32, u32, u32, u32, u32) {
    let days = t.div_euclid(86400);
    let secs = t.rem_euclid(86400) as u32;
    let (year, month, day) = civil_from_days(days);
    (
        year,
        month,
        day,
        secs / 3600,
        (secs % 3600) / 60,
        secs % 60,
    )
}

fn epoch_to_local(t: i64, offset: i64) -> (i64, u32, u32, u32, u32, u32) {
    epoch_to_datetime(t + offset)
}

fn datetime_to_epoch(y: i64, mo: u32, d: u32, h: u32, mi: u32, s: u32) -> i64 {
    days_from_civil(y, mo, d) * 86400 + h as i64 * 3600 + mi as i64 * 60 + s as i64
}

fn parse_datetime(s: &str) -> (i64, u32, u32, u32, u32, u32) {
    (
        s[0..4].parse().unwrap(),
        s[5..7].parse().unwrap(),
        s[8..10].parse().unwrap(),
        s[11..13].parse().unwrap(),
        s[14..16].parse().unwrap(),
        s[17..19].parse().unwrap(),
    )
}

fn format_datetime(dt: (i64, u32, u32, u32, u32, u32)) -> String {
    let (y, mo, d, h, mi, s) = dt;
    format!("{:04}-{:02}-{:02}T{:02}:{:02}:{:02}", y, mo, d, h, mi, s)
}

fn format_offset(offset: i64) -> String {
    let sign = if offset >= 0 { '+' } else { '-' };
    let abs = offset.abs();
    let h = abs / 3600;
    let m = (abs % 3600) / 60;
    let s = abs % 60;
    if s != 0 {
        format!("{}{:02}:{:02}:{:02}", sign, h, m, s)
    } else {
        format!("{}{:02}:{:02}", sign, h, m)
    }
}

fn is_leap(y: i64) -> bool {
    (y % 4 == 0 && y % 100 != 0) || (y % 400 == 0)
}

fn days_in_month(y: i64, m: u32) -> u32 {
    match m {
        1 | 3 | 5 | 7 | 8 | 10 | 12 => 31,
        4 | 6 | 9 | 11 => 30,
        2 => {
            if is_leap(y) {
                29
            } else {
                28
            }
        }
        _ => unreachable!(),
    }
}

fn day_of_week(y: i64, m: u32, d: u32) -> u32 {
    ((days_from_civil(y, m, d) + 4).rem_euclid(7)) as u32
}

fn find_rule_day(month: u32, week: u32, dow: u32, year: i64) -> u32 {
    if week == 5 {
        let last_day = days_in_month(year, month);
        let last_dow = day_of_week(year, month, last_day);
        let diff = (last_dow as i64 - dow as i64 + 7) % 7;
        last_day - diff as u32
    } else {
        let first_dow = day_of_week(year, month, 1);
        let diff = (dow as i64 - first_dow as i64 + 7) % 7;
        1 + diff as u32 + (week - 1) * 7
    }
}

fn rule_to_utc(rule: &Rule, year: i64, utoff: i64) -> i64 {
    let day = find_rule_day(rule.month, rule.week, rule.day, year);
    let local_secs = days_from_civil(year, rule.month, day) * 86400 + rule.time;
    local_secs - utoff
}

impl TzData {
    fn get_local_info(&self, t: i64) -> (i64, String) {
        if self.transitions.is_empty() {
            if let Some(ref f) = self.footer {
                return self.footer_info(t, f);
            }
            let tr = &self.types[0];
            return (tr.utoff, tr.abbr.clone());
        }
        let first_t = self.transitions[0].0;
        let last_t = self.transitions.last().unwrap().0;
        if t < first_t {
            let tr = &self.types[0];
            return (tr.utoff, tr.abbr.clone());
        }
        if t > last_t {
            if let Some(ref f) = self.footer {
                return self.footer_info(t, f);
            }
            let tr = &self.types[self.transitions.last().unwrap().1];
            return (tr.utoff, tr.abbr.clone());
        }
        let idx = self.transitions.partition_point(|&(time, _)| time <= t) - 1;
        let tr = &self.types[self.transitions[idx].1];
        (tr.utoff, tr.abbr.clone())
    }

    fn footer_info(&self, t: i64, f: &FooterRule) -> (i64, String) {
        if !f.has_dst || f.dst_start.is_none() || f.dst_end.is_none() {
            if f.has_dst {
                return (f.dst_utoff, f.dst_abbr.clone());
            }
            return (f.std_utoff, f.std_abbr.clone());
        }
        let (year, _, _, _, _, _) = epoch_to_datetime(t);
        let dst_start_utc = rule_to_utc(f.dst_start.as_ref().unwrap(), year, f.std_utoff);
        let dst_end_utc = rule_to_utc(f.dst_end.as_ref().unwrap(), year, f.dst_utoff);
        let in_dst = if dst_start_utc < dst_end_utc {
            t >= dst_start_utc && t < dst_end_utc
        } else {
            t >= dst_start_utc || t < dst_end_utc
        };
        if in_dst {
            (f.dst_utoff, f.dst_abbr.clone())
        } else {
            (f.std_utoff, f.std_abbr.clone())
        }
    }

    fn all_offsets(&self) -> Vec<i64> {
        let mut offs: Vec<i64> = self.types.iter().map(|t| t.utoff).collect();
        if let Some(ref f) = self.footer {
            offs.push(f.std_utoff);
            if f.has_dst {
                offs.push(f.dst_utoff);
            }
        }
        offs.sort();
        offs.dedup();
        offs
    }

    fn find_local_times(&self, w_epoch: i64) -> Vec<(i64, i64, String)> {
        let offsets = self.all_offsets();
        let mut solutions = Vec::new();
        for &o in &offsets {
            let t = w_epoch - o;
            let (actual_offset, abbr) = self.get_local_info(t);
            if actual_offset == o {
                solutions.push((t, actual_offset, abbr));
            }
        }
        solutions.sort_by_key(|s| s.0);
        solutions.dedup_by_key(|s| s.0);
        solutions
    }

    fn find_gap(&self, w_epoch: i64) -> (i64, i64, String) {
        let mut candidates: Vec<(i64, i64, i64)> = Vec::new();
        let last_t = if self.transitions.is_empty() {
            i64::MIN
        } else {
            self.transitions.last().unwrap().0
        };

        // Table transitions (spring-forward only)
        for i in 0..self.transitions.len() {
            let (t, type_idx) = self.transitions[i];
            let o_new = self.types[type_idx].utoff;
            let o_old = if i > 0 {
                self.types[self.transitions[i - 1].1].utoff
            } else {
                self.types[0].utoff
            };
            if o_new > o_old {
                candidates.push((t, o_old, o_new));
            }
        }

        // Footer rule transitions
        if let Some(ref f) = self.footer {
            if f.has_dst && f.dst_start.is_some() && f.dst_end.is_some() {
                let (year, _, _, _, _, _) = epoch_to_datetime(w_epoch);
                for y in [year - 1, year, year + 1] {
                    let dst_start_utc = rule_to_utc(f.dst_start.as_ref().unwrap(), y, f.std_utoff);
                    let dst_end_utc = rule_to_utc(f.dst_end.as_ref().unwrap(), y, f.dst_utoff);
                    if dst_start_utc > last_t && f.dst_utoff > f.std_utoff {
                        candidates.push((dst_start_utc, f.std_utoff, f.dst_utoff));
                    }
                    if dst_end_utc > last_t && f.std_utoff > f.dst_utoff {
                        candidates.push((dst_end_utc, f.dst_utoff, f.std_utoff));
                    }
                }
            }
        }

        // Table-to-footer boundary
        if !self.transitions.is_empty() {
            if let Some(ref f) = self.footer {
                let boundary_t = last_t + 1;
                let o_old = self.types[self.transitions.last().unwrap().1].utoff;
                let (o_new, _) = self.footer_info(boundary_t, f);
                if o_new > o_old {
                    candidates.push((boundary_t, o_old, o_new));
                }
            }
        }

        for &(t, o_old, o_new) in &candidates {
            if t + o_old <= w_epoch && w_epoch < t + o_new {
                let result_t = w_epoch - o_old;
                let (offset, abbr) = self.get_local_info(result_t);
                return (result_t, offset, abbr);
            }
        }

        panic!("No gap transition found for w_epoch = {}", w_epoch);
    }
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <ctype.h>

static int32_t read_be32(const uint8_t *p) {
    return (int32_t)(((uint32_t)p[0]<<24)|((uint32_t)p[1]<<16)|((uint32_t)p[2]<<8)|p[3]);
}
static int64_t read_be64(const uint8_t *p) {
    return ((int64_t)read_be32(p) << 32) | (uint32_t)read_be32(p+4);
}

static int64_t days_from_civil(int y, unsigned m, unsigned d) {
    y -= m <= 2;
    int era = (y >= 0 ? y : y - 399) / 400;
    unsigned yoe = (unsigned)(y - era * 400);
    unsigned doy = (153*(m + (m > 2 ? (unsigned)-3 : (unsigned)9)) + 2)/5 + d - 1;
    unsigned doe = yoe * 365 + yoe/4 - yoe/100 + doy;
    return (int64_t)era * 146097 + (int64_t)doe - 719468;
}

static void civil_from_days(int64_t z, int *y, unsigned *m, unsigned *d) {
    z += 719468;
    int era = (int)((z >= 0 ? z : z - 146096) / 146097);
    unsigned doe = (unsigned)(z - (int64_t)era * 146097);
    unsigned yoe = (doe - doe/1460 + doe/36524 - doe/146096) / 365;
    int yy = (int)yoe + era * 400;
    unsigned doy = doe - (365*yoe + yoe/4 - yoe/100);
    unsigned mp = (5*doy + 2)/153;
    *d = doy - (153*mp+2)/5 + 1;
    *m = mp + (mp < 10 ? 3 : (unsigned)-9);
    *y = yy + (*m <= 2 ? 1 : 0);
}

static int day_of_week(int64_t days) {
    int dow = (int)(((days % 7) + 7 + 4) % 7);
    return dow;
}

static unsigned days_in_month(int y, unsigned m) {
    static const int dm[] = {31,28,31,30,31,30,31,31,30,31,30,31};
    if (m == 2) {
        if ((y%4==0 && y%100!=0) || y%400==0) return 29;
        return 28;
    }
    return dm[m-1];
}

static int64_t local_to_unix(int y, unsigned m, unsigned d, unsigned hh, unsigned mm, unsigned ss) {
    return days_from_civil(y, m, d) * 86400 + (int64_t)hh*3600 + (int64_t)mm*60 + ss;
}

static unsigned find_mwd_day(int y, int m, int w, int d) {
    int64_t first_day = days_from_civil(y, (unsigned)m, 1);
    int first_dow = day_of_week(first_day);
    int diff = (d - first_dow + 7) % 7;
    unsigned first_occ = 1 + (unsigned)diff;
    if (w == 5) {
        unsigned last_day = days_in_month(y, (unsigned)m);
        int64_t last_dow = day_of_week(days_from_civil(y, (unsigned)m, last_day));
        int diff2 = ((int)last_dow - d + 7) % 7;
        return last_day - (unsigned)diff2;
    }
    return first_occ + (unsigned)(w - 1) * 7;
}

static void parse_name(const char *s, char *out, const char **end) {
    if (*s == '<') {
        s++;
        int i = 0;
        while (*s && *s != '>') out[i++] = *s++;
        out[i] = 0;
        if (*s == '>') s++;
        *end = s;
    } else {
        int i = 0;
        while (isalpha((unsigned char)*s)) out[i++] = *s++;
        out[i] = 0;
        *end = s;
    }
}

static int32_t parse_offset(const char *s, const char **end) {
    int sign = 1;
    if (*s == '+') { s++; }
    else if (*s == '-') { sign = -1; s++; }
    int h = 0, m = 0, sec = 0;
    h = atoi(s); while (isdigit((unsigned char)*s)) s++;
    if (*s == ':') { s++; m = atoi(s); while (isdigit((unsigned char)*s)) s++; }
    if (*s == ':') { s++; sec = atoi(s); while (isdigit((unsigned char)*s)) s++; }
    *end = s;
    return sign * (h*3600 + m*60 + sec);
}

static void parse_mwd(const char *s, int *m, int *w, int *d, const char **end) {
    s++; /* skip 'M' */
    *m = atoi(s); while (isdigit((unsigned char)*s)) s++;
    s++; /* skip '.' */
    *w = atoi(s); while (isdigit((unsigned char)*s)) s++;
    s++; /* skip '.' */
    *d = atoi(s); while (isdigit((unsigned char)*s)) s++;
    *end = s;
}

static int parse_time(const char *s, const char **end) {
    int sign = 1;
    if (*s == '/') s++;
    if (*s == '+') s++;
    else if (*s == '-') { sign = -1; s++; }
    int h = atoi(s); while (isdigit((unsigned char)*s)) s++;
    int m = 0, sec = 0;
    if (*s == ':') { s++; m = atoi(s); while (isdigit((unsigned char)*s)) s++; }
    if (*s == ':') { s++; sec = atoi(s); while (isdigit((unsigned char)*s)) s++; }
    *end = s;
    return sign * (h*3600 + m*60 + sec);
}

typedef struct { int64_t time; int type_idx; } Transition;
typedef struct { int32_t gmtoff; uint8_t isdst; uint8_t abbridx; } LmtType;
typedef struct {
    char std_name[256];
    int32_t std_gmtoff;
    char dst_name[256];
    int32_t dst_gmtoff;
    int has_dst;
    int dst_start_m, dst_start_w, dst_start_d, dst_start_time;
    int dst_end_m, dst_end_w, dst_end_d, dst_end_time;
    int has_rule;
} Footer;

typedef struct {
    int ntrans;
    Transition *trans;
    int ntypes;
    LmtType *types;
    char *abbrs;
    Footer footer;
    int has_footer;
} TzFile;

static TzFile *parse_tzif(const char *path) {
    FILE *f = fopen(path, "rb");
    if (!f) { fprintf(stderr, "Cannot open %s\n", path); exit(1); }
    fseek(f, 0, SEEK_END);
    long fsize = ftell(f);
    fseek(f, 0, SEEK_SET);
    uint8_t *data = (uint8_t*)malloc(fsize);
    fread(data, 1, fsize, f);
    fclose(f);

    TzFile *tz = (TzFile*)calloc(1, sizeof(TzFile));

    int32_t isutcnt, isstdcnt, leapcnt, timecnt, typecnt, charcnt;
    /* Skip first header+block */
    isutcnt  = read_be32(data + 20);
    isstdcnt = read_be32(data + 24);
    leapcnt  = read_be32(data + 28);
    timecnt  = read_be32(data + 32);
    typecnt  = read_be32(data + 36);
    charcnt  = read_be32(data + 40);
    int block1_size = timecnt*4 + timecnt*1 + typecnt*6 + charcnt + leapcnt*8 + isstdcnt + isutcnt;
    int off = 44 + block1_size;

    /* Second header */
    isutcnt  = read_be32(data + off + 20);
    isstdcnt = read_be32(data + off + 24);
    leapcnt  = read_be32(data + off + 28);
    timecnt  = read_be32(data + off + 32);
    typecnt  = read_be32(data + off + 36);
    charcnt  = read_be32(data + off + 40);
    off += 44;

    /* Second data block */
    tz->ntrans = timecnt;
    tz->trans = (Transition*)malloc(timecnt * sizeof(Transition));
    for (int i = 0; i < timecnt; i++) {
        tz->trans[i].time = read_be64(data + off);
        off += 8;
    }
    for (int i = 0; i < timecnt; i++) {
        tz->trans[i].type_idx = data[off++];
    }
    tz->ntypes = typecnt;
    tz->types = (LmtType*)malloc(typecnt * sizeof(LmtType));
    for (int i = 0; i < typecnt; i++) {
        tz->types[i].gmtoff = read_be32(data + off);
        tz->types[i].isdst = data[off + 4];
        tz->types[i].abbridx = data[off + 5];
        off += 6;
    }
    tz->abbrs = (char*)malloc(charcnt + 1);
    memcpy(tz->abbrs, data + off, charcnt);
    tz->abbrs[charcnt] = 0;
    off += charcnt;
    off += leapcnt * 12 + isstdcnt + isutcnt;

    /* Footer */
    if (off < fsize && data[off] == '\n') {
        off++;
        int start = off;
        while (off < fsize && data[off] != '\n') off++;
        int len = off - start;
        char *tzstr = (char*)malloc(len + 1);
        memcpy(tzstr, data + start, len);
        tzstr[len] = 0;

        const char *p = tzstr;
        parse_name(p, tz->footer.std_name, &p);
        int32_t std_off = parse_offset(p, &p);
        tz->footer.std_gmtoff = -std_off;

        if (*p && *p != ',') {
            parse_name(p, tz->footer.dst_name, &p);
            if (*p && *p != ',') {
                int32_t dst_off = parse_offset(p, &p);
                tz->footer.dst_gmtoff = -dst_off;
            } else {
                tz->footer.dst_gmtoff = tz->footer.std_gmtoff + 3600;
            }
            tz->footer.has_dst = 1;
        }

        if (*p == ',') {
            p++;
            parse_mwd(p, &tz->footer.dst_start_m, &tz->footer.dst_start_w, &tz->footer.dst_start_d, &p);
            if (*p == '/') {
                tz->footer.dst_start_time = parse_time(p, &p);
            } else {
                tz->footer.dst_start_time = 2*3600;
            }
            if (*p == ',') p++;
            parse_mwd(p, &tz->footer.dst_end_m, &tz->footer.dst_end_w, &tz->footer.dst_end_d, &p);
            if (*p == '/') {
                tz->footer.dst_end_time = parse_time(p, &p);
            } else {
                tz->footer.dst_end_time = 2*3600;
            }
            tz->footer.has_rule = 1;
        }

        tz->has_footer = 1;
        free(tzstr);
    }

    free(data);
    return tz;
}

static int64_t footer_start_utc(Footer *f, int y) {
    unsigned day = find_mwd_day(y, f->dst_start_m, f->dst_start_w, f->dst_start_d);
    int64_t local_sec = days_from_civil(y, (unsigned)f->dst_start_m, day) * 86400 + f->dst_start_time;
    return local_sec - f->std_gmtoff;
}

static int64_t footer_end_utc(Footer *f, int y) {
    unsigned day = find_mwd_day(y, f->dst_end_m, f->dst_end_w, f->dst_end_d);
    int64_t local_sec = days_from_civil(y, (unsigned)f->dst_end_m, day) * 86400 + f->dst_end_time;
    return local_sec - f->dst_gmtoff;
}

static int footer_is_dst(Footer *f, int64_t t) {
    if (!f->has_dst) return 0;
    if (!f->has_rule) return 1;

    int64_t days = t / 86400;
    if (t < 0 && t % 86400 != 0) days--;
    int y; unsigned m, d;
    civil_from_days(days, &y, &m, &d);

    for (int yy = y - 1; yy <= y + 1; yy++) {
        int64_t start = footer_start_utc(f, yy);
        int64_t end = footer_end_utc(f, yy);
        if (start < end) {
            if (t >= start && t < end) return 1;
        } else {
            int64_t end_next = footer_end_utc(f, yy + 1);
            if (t >= start && t < end_next) return 1;
        }
    }
    return 0;
}

typedef struct { int32_t gmtoff; const char *abbr; } TzInfo;

static TzInfo get_tz_info(TzFile *tz, int64_t t) {
    TzInfo info;
    if (tz->ntrans == 0) {
        if (tz->has_footer) {
            if (footer_is_dst(&tz->footer, t)) {
                info.gmtoff = tz->footer.dst_gmtoff;
                info.abbr = tz->footer.dst_name;
            } else {
                info.gmtoff = tz->footer.std_gmtoff;
                info.abbr = tz->footer.std_name;
            }
        } else {
            info.gmtoff = tz->types[0].gmtoff;
            info.abbr = tz->abbrs + tz->types[0].abbridx;
        }
        return info;
    }
    if (t < tz->trans[0].time) {
        info.gmtoff = tz->types[0].gmtoff;
        info.abbr = tz->abbrs + tz->types[0].abbridx;
        return info;
    }
    if (t > tz->trans[tz->ntrans - 1].time) {
        if (tz->has_footer) {
            if (footer_is_dst(&tz->footer, t)) {
                info.gmtoff = tz->footer.dst_gmtoff;
                info.abbr = tz->footer.dst_name;
            } else {
                info.gmtoff = tz->footer.std_gmtoff;
                info.abbr = tz->footer.std_name;
            }
        } else {
            int ti = tz->trans[tz->ntrans - 1].type_idx;
            info.gmtoff = tz->types[ti].gmtoff;
            info.abbr = tz->abbrs + tz->types[ti].abbridx;
        }
        return info;
    }
    /* t >= trans[0].time && t <= trans[ntrans-1].time */
    int lo = 0, hi = tz->ntrans - 1;
    while (lo < hi) {
        int mid = (lo + hi + 1) / 2;
        if (tz->trans[mid].time <= t) lo = mid;
        else hi = mid - 1;
    }
    int ti = tz->trans[lo].type_idx;
    info.gmtoff = tz->types[ti].gmtoff;
    info.abbr = tz->abbrs + tz->types[ti].abbridx;
    return info;
}

static void format_offset(int32_t off, char *buf) {
    char sign = (off >= 0) ? '+' : '-';
    int aoff = (off >= 0) ? off : -off;
    int h = aoff / 3600;
    int m = (aoff % 3600) / 60;
    int s = aoff % 60;
    if (s != 0)
        sprintf(buf, "%c%02d:%02d:%02d", sign, h, m, s);
    else
        sprintf(buf, "%c%02d:%02d", sign, h, m);
}

static void format_local(int64_t t, int32_t gmtoff, char *buf) {
    int64_t local = t + gmtoff;
    int64_t days = local / 86400;
    if (local < 0 && local % 86400 != 0) days--;
    int rem = (int)(local - days * 86400);
    int y; unsigned m, d;
    civil_from_days(days, &y, &m, &d);
    int hh = rem / 3600;
    int mm = (rem % 3600) / 60;
    int ss = rem % 60;
    sprintf(buf, "%04d-%02u-%02uT%02d:%02d:%02d", y, m, d, hh, mm, ss);
}

static void collect_offsets(TzFile *tz, int32_t *offsets, int *noffsets) {
    *noffsets = 0;
    for (int i = 0; i < tz->ntypes; i++) {
        int32_t o = tz->types[i].gmtoff;
        int found = 0;
        for (int j = 0; j < *noffsets; j++)
            if (offsets[j] == o) { found = 1; break; }
        if (!found) offsets[(*noffsets)++] = o;
    }
    if (tz->has_footer) {
        int32_t o1 = tz->footer.std_gmtoff;
        int found = 0;
        for (int j = 0; j < *noffsets; j++)
            if (offsets[j] == o1) { found = 1; break; }
        if (!found) offsets[(*noffsets)++] = o1;
        if (tz->footer.has_dst) {
            int32_t o2 = tz->footer.dst_gmtoff;
            found = 0;
            for (int j = 0; j < *noffsets; j++)
                if (offsets[j] == o2) { found = 1; break; }
            if (!found) offsets[(*noffsets)++] = o2;
        }
    }
}

int main(int argc, char *argv[]) {
    if (argc < 2) { fprintf(stderr, "Usage: %s <dir>\n", argv[0]); return 1; }
    char *dir = argv[1];

    char qpath[4096];
    snprintf(qpath, sizeof(qpath), "%s/queries.txt", dir);
    FILE *qf = fopen(qpath, "r");
    if (!qf) { fprintf(stderr, "Cannot open %s\n", qpath); return 1; }

    char line[4096];
    while (fgets(line, sizeof(line), qf)) {
        int len = (int)strlen(line);
        while (len > 0 && (line[len-1] == '\n' || line[len-1] == '\r')) line[--len] = 0;
        if (len == 0) continue;

        char qtype[16], file[256];
        sscanf(line, "%15s %255s", qtype, file);

        char fpath[4096];
        snprintf(fpath, sizeof(fpath), "%s/%s", dir, file);
        TzFile *tz = parse_tzif(fpath);

        if (strcmp(qtype, "UTC") == 0) {
            char *p = line + strlen(qtype) + 1 + strlen(file) + 1;
            int64_t t = strtoll(p, NULL, 10);
            TzInfo info = get_tz_info(tz, t);
            char local_str[64], off_str[32];
            format_local(t, info.gmtoff, local_str);
            format_offset(info.gmtoff, off_str);
            printf("%s -> %s%s %s\n", line, local_str, off_str, info.abbr);

        } else if (strcmp(qtype, "LOCAL") == 0) {
            char wallclock[64];
            sscanf(line, "%*s %*s %63s", wallclock);
            int y, hh, mm, ss;
            unsigned m, d;
            sscanf(wallclock, "%d-%u-%uT%d:%d:%d", &y, &m, &d, &hh, &mm, &ss);
            int64_t W = local_to_unix(y, m, d, (unsigned)hh, (unsigned)mm, (unsigned)ss);

            int32_t offsets[128];
            int noffsets;
            collect_offsets(tz, offsets, &noffsets);

            int64_t sol_t[4];
            int32_t sol_off[4];
            const char *sol_abbr[4];
            int nsol = 0;

            for (int i = 0; i < noffsets; i++) {
                int64_t t = W - (int64_t)offsets[i];
                TzInfo info = get_tz_info(tz, t);
                if (info.gmtoff == offsets[i]) {
                    if (nsol < 4) {
                        sol_t[nsol] = t;
                        sol_off[nsol] = info.gmtoff;
                        sol_abbr[nsol] = info.abbr;
                        nsol++;
                    }
                }
            }

            if (nsol >= 2) {
                /* Sort first two by time */
                if (sol_t[1] < sol_t[0]) {
                    int64_t tmp = sol_t[0]; sol_t[0] = sol_t[1]; sol_t[1] = tmp;
                    int32_t tmpo = sol_off[0]; sol_off[0] = sol_off[1]; sol_off[1] = tmpo;
                    const char *tmpa = sol_abbr[0]; sol_abbr[0] = sol_abbr[1]; sol_abbr[1] = tmpa;
                }
                char off1[32], off2[32];
                format_offset(sol_off[0], off1);
                format_offset(sol_off[1], off2);
                printf("%s -> %lld %s %s | %lld %s %s\n", line,
                       (long long)sol_t[0], off1, sol_abbr[0],
                       (long long)sol_t[1], off2, sol_abbr[1]);
            } else if (nsol == 1) {
                char off_str[32];
                format_offset(sol_off[0], off_str);
                printf("%s -> %lld %s %s\n", line, (long long)sol_t[0], off_str, sol_abbr[0]);
            } else {
                /* GAP: find the transition that caused it */
                int32_t gap_before_offset = 0;
                int found_gap = 0;

                /* Check explicit transitions */
                for (int i = 0; i < tz->ntrans && !found_gap; i++) {
                    int64_t T = tz->trans[i].time;
                    int32_t O_after = tz->types[tz->trans[i].type_idx].gmtoff;
                    int32_t O_before;
                    if (i == 0) O_before = tz->types[0].gmtoff;
                    else O_before = tz->types[tz->trans[i-1].type_idx].gmtoff;
                    if (O_after > O_before && T + O_before <= W && W < T + O_after) {
                        gap_before_offset = O_before;
                        found_gap = 1;
                    }
                }

                /* Check footer DST start transitions */
                if (!found_gap && tz->has_footer && tz->footer.has_dst && tz->footer.has_rule) {
                    int32_t O_before = tz->footer.std_gmtoff;
                    int32_t O_after = tz->footer.dst_gmtoff;
                    if (O_after > O_before) {
                        int64_t days = W / 86400;
                        if (W < 0 && W % 86400 != 0) days--;
                        int yy0; unsigned mm0, dd0;
                        civil_from_days(days, &yy0, &mm0, &dd0);
                        for (int yy = yy0 - 2; yy <= yy0 + 2 && !found_gap; yy++) {
                            int64_t T = footer_start_utc(&tz->footer, yy);
                            if (tz->ntrans > 0 && T <= tz->trans[tz->ntrans-1].time) continue;
                            if (T + O_before <= W && W < T + O_after) {
                                gap_before_offset = O_before;
                                found_gap = 1;
                            }
                        }
                    }
                }

                /* Fallback: find offset where offset(W-O) > O */
                if (!found_gap) {
                    int32_t best = -999999;
                    for (int i = 0; i < noffsets; i++) {
                        int64_t t = W - (int64_t)offsets[i];
                        TzInfo info = get_tz_info(tz, t);
                        if (info.gmtoff > offsets[i] && offsets[i] > best) {
                            best = offsets[i];
                        }
                    }
                    if (best > -999999) {
                        gap_before_offset = best;
                        found_gap = 1;
                    }
                }

                int64_t t = W - (int64_t)gap_before_offset;
                TzInfo info = get_tz_info(tz, t);
                char local_str[64], off_str[32];
                format_local(t, info.gmtoff, local_str);
                format_offset(info.gmtoff, off_str);
                printf("%s -> GAP %lld %s%s %s\n", line, (long long)t, local_str, off_str, info.abbr);
            }
        }

        free(tz->trans);
        free(tz->types);
        free(tz->abbrs);
        free(tz);
    }

    fclose(qf);
    return 0;
}

import Foundation
import Darwin
import CommonCrypto

// MARK: - SHA-1
func sha1Digest(_ data: [UInt8]) -> [UInt8] {
    var digest = [UInt8](repeating: 0, count: Int(CC_SHA1_DIGEST_LENGTH))
    if data.isEmpty {
        _ = CC_SHA1(nil, 0, &digest)
    } else {
        data.withUnsafeBytes { (ptr: UnsafeRawBufferPointer) in
            _ = CC_SHA1(ptr.baseAddress, CC_LONG(data.count), &digest)
        }
    }
    return digest
}

func sha1Hex(_ data: [UInt8]) -> String {
    return sha1Digest(data).map { String(format: "%02x", $0) }.joined()
}

// MARK: - Socket helpers
func createSocket(host: String, port: UInt16) throws -> Int32 {
    let fd = socket(AF_INET, SOCK_STREAM, 0)
    guard fd >= 0 else { throw NSError(domain: "socket", code: Int(errno)) }
    var addr = sockaddr_in()
    addr.sin_family = sa_family_t(AF_INET)
    addr.sin_port = port.bigEndian
    inet_pton(AF_INET, host, &addr.sin_addr)
    let result = withUnsafePointer(to: &addr) { ptr in
        ptr.withMemoryRebound(to: sockaddr.self, capacity: 1) { sockPtr in
            connect(fd, sockPtr, socklen_t(MemoryLayout<sockaddr_in>.size))
        }
    }
    guard result == 0 else {
        Darwin.close(fd)
        throw NSError(domain: "connect", code: Int(errno))
    }
    return fd
}

func writeAll(_ fd: Int32, _ data: [UInt8]) throws {
    if data.isEmpty { return }
    try data.withUnsafeBytes { (ptr: UnsafeRawBufferPointer) in
        var written = 0
        while written < data.count {
            let n = Darwin.write(fd, ptr.baseAddress! + written, data.count - written)
            if n <= 0 { throw NSError(domain: "write", code: Int(errno)) }
            written += n
        }
    }
}

// MARK: - Buffered reader
final class BufferedReader {
    let fd: Int32
    var buf: [UInt8] = []
    var pos: Int = 0

    init(fd: Int32) { self.fd = fd }

    func ensure(_ n: Int) throws {
        if pos > 65536 {
            buf.removeFirst(pos)
            pos = 0
        }
        while buf.count - pos < n {
            let toRead = max(4096, n - (buf.count - pos))
            var tmp = [UInt8](repeating: 0, count: toRead)
            let n = Darwin.read(fd, &tmp, toRead)
            if n <= 0 { throw NSError(domain: "read", code: n == 0 ? -1 : Int(errno)) }
            buf.append(contentsOf: tmp[0..<n])
        }
    }

    func readByte() throws -> UInt8 {
        try ensure(1)
        let b = buf[pos]; pos += 1; return b
    }

    func readBytes(_ n: Int) throws -> [UInt8] {
        if n == 0 { return [] }
        try ensure(n)
        let r = Array(buf[pos..<pos+n]); pos += n; return r
    }

    func readLine() throws -> String {
        var line: [UInt8] = []
        while true {
            try ensure(1)
            let b = buf[pos]; pos += 1
            if b == 13 {
                try ensure(1)
                let b2 = buf[pos]; pos += 1
                if b2 == 10 { return String(decoding: line, as: UTF8.self) }
                line.append(b); line.append(b2)
            } else {
                line.append(b)
            }
        }
    }
}

// MARK: - WebSocket frame
struct WSFrame {
    let fin: Bool
    let opcode: UInt8
    let payload: [UInt8]
}

func readFrame(_ reader: BufferedReader) throws -> WSFrame {
    let b0 = try reader.readByte()
    let fin = (b0 & 0x80) != 0
    let opcode = b0 & 0x0F
    let b1 = try reader.readByte()
    let masked = (b1 & 0x80) != 0
    var payloadLen = Int(b1 & 0x7F)
    if payloadLen == 126 {
        let b = try reader.readBytes(2)
        payloadLen = Int(b[0]) << 8 | Int(b[1])
    } else if payloadLen == 127 {
        let b = try reader.readBytes(8)
        payloadLen = 0
        for v in b { payloadLen = payloadLen << 8 | Int(v) }
    }
    var maskKey: [UInt8] = []
    if masked { maskKey = try reader.readBytes(4) }
    var payload = try reader.readBytes(payloadLen)
    if masked {
        for i in 0..<payload.count { payload[i] ^= maskKey[i & 3] }
    }
    return WSFrame(fin: fin, opcode: opcode, payload: payload)
}

func sendFrame(fd: Int32, opcode: UInt8, payload: [UInt8]) throws {
    var frame: [UInt8] = []
    frame.append(0x80 | opcode)
    let len = payload.count
    if len <= 125 {
        frame.append(0x80 | UInt8(len))
    } else if len <= 65535 {
        frame.append(0x80 | 126)
        frame.append(UInt8(len >> 8))
        frame.append(UInt8(len & 0xFF))
    } else {
        frame.append(0x80 | 127)
        for i in stride(from: 7, through: 0, by: -1) {
            frame.append(UInt8((len >> (i * 8)) & 0xFF))
        }
    }
    var maskKey: [UInt8]
    repeat {
        maskKey = [UInt8(truncatingIfNeeded: arc4random()),
                   UInt8(truncatingIfNeeded: arc4random()),
                   UInt8(truncatingIfNeeded: arc4random()),
                   UInt8(truncatingIfNeeded: arc4random())]
    } while maskKey[0] == 0 && maskKey[1] == 0 && maskKey[2] == 0 && maskKey[3] == 0
    frame.append(contentsOf: maskKey)
    for i in 0..<payload.count {
        frame.append(payload[i] ^ maskKey[i & 3])
    }
    try writeAll(fd, frame)
}

func sendText(fd: Int32, _ text: String) throws {
    try sendFrame(fd: fd, opcode: 1, payload: Array(text.utf8))
}

func sendCloseFrame(fd: Int32, code: UInt16) throws {
    try sendFrame(fd: fd, opcode: 8, payload: [UInt8(code >> 8), UInt8(code & 0xFF)])
}

// MARK: - URL parsing
struct WSUrl {
    let host: String
    let port: UInt16
    let requestTarget: String
}

func parseWSUrl(_ s: String) -> WSUrl? {
    guard s.hasPrefix("ws://") else { return nil }
    let rest = String(s.dropFirst(5))
    guard let slash = rest.firstIndex(of: "/") else { return nil }
    let hostPort = String(rest[..<slash])
    let target = String(rest[slash...])
    let host: String
    let port: UInt16
    if let ci = hostPort.lastIndex(of: ":") {
        host = String(hostPort[..<ci])
        port = UInt16(String(hostPort[hostPort.index(after: ci)...])) ?? 80
    } else {
        host = hostPort; port = 80
    }
    return WSUrl(host: host, port: port, requestTarget: target)
}

// MARK: - Reverse by code point
func reverseByCodePoints(_ s: String) -> String {
    var r = ""
    for sc in s.unicodeScalars.reversed() { r.unicodeScalars.append(sc) }
    return r
}

// MARK: - Command processing
func processTextCommand(_ text: String, fd: Int32,
                        expectingSHA1: inout Bool, sentClose: inout Bool) throws {
    expectingSHA1 = false

    if text == "BYE" {
        try sendCloseFrame(fd: fd, code: 1000)
        sentClose = true
        return
    }
    if text == "SHA1" {
        expectingSHA1 = true
        return
    }
    if text.hasPrefix("ADD ") {
        let parts = text.split(separator: " ")
        if parts.count >= 3 {
            let a = Int(parts[1]) ?? 0
            let b = Int(parts[2]) ?? 0
            let sum = a + b
            let reply = String(sum)
            try sendText(fd: fd, reply)
            print("\(text) -> \(reply)")
        }
        return
    }
    if text.hasPrefix("REV ") {
        let txt = String(text.dropFirst(4))
        let rev = reverseByCodePoints(txt)
        try sendText(fd: fd, rev)
        print("REV \(txt) -> \(rev)")
        return
    }
}

// MARK: - Session handler
func handleSession(url: WSUrl) {
    let fd: Int32
    do { fd = try createSocket(host: url.host, port: url.port) }
    catch { return }
    defer { Darwin.close(fd) }

    let reader = BufferedReader(fd: fd)

    // Sec-WebSocket-Key
    var keyBytes = [UInt8](repeating: 0, count: 16)
    for i in 0..<16 { keyBytes[i] = UInt8(truncatingIfNeeded: arc4random()) }
    let key = Data(keyBytes).base64EncodedString()

    // HTTP upgrade request
    var req = "GET \(url.requestTarget) HTTP/1.1\r\n"
    req += "Host: \(url.host):\(url.port)\r\n"
    req += "Upgrade: websocket\r\n"
    req += "Connection: Upgrade\r\n"
    req += "Sec-WebSocket-Version: 13\r\n"
    req += "Sec-WebSocket-Key: \(key)\r\n"
    req += "\r\n"
    do { try writeAll(fd, Array(req.utf8)) } catch { return }

    // Read status line
    let statusLine: String
    do { statusLine = try reader.readLine() } catch { return }

    let firstSp = statusLine.firstIndex(of: " ")
    guard let fs = firstSp else {
        print("handshake failed: \(statusLine)")
        return
    }
    let afterV = statusLine[statusLine.index(after: fs)...]
    let secondSp = afterV.firstIndex(of: " ")
    let codeStr: String
    let reasonPhrase: String
    if let ss = secondSp {
        codeStr = String(afterV[..<ss])
        reasonPhrase = String(afterV[afterV.index(after: ss)...])
    } else {
        codeStr = String(afterV)
        reasonPhrase = ""
    }
    let statusCode = Int(codeStr) ?? 0

    // Read headers
    var headers: [(String, String)] = []
    do {
        while true {
            let line = try reader.readLine()
            if line.isEmpty { break }
            if let ci = line.firstIndex(of: ":") {
                let name = String(line[line.startIndex..<ci]).lowercased()
                let val = String(line[line.index(after: ci)...]).trimmingCharacters(in: .whitespaces)
                headers.append((name, val))
            }
        }
    } catch { return }

    if statusCode != 101 {
        print("handshake failed: \(codeStr) \(reasonPhrase)")
        return
    }

    // Validate Sec-WebSocket-Accept
    let acceptInput = key + "258EAFA5-E914-47DA-95CA-C5AB0DC85B11"
    let expectedAccept = Data(sha1Digest(Array(acceptInput.utf8))).base64EncodedString()
    var actualAccept: String?
    for (n, v) in headers {
        if n == "sec-websocket-accept" { actualAccept = v; break }
    }
    if actualAccept != expectedAccept {
        print("handshake failed: bad Sec-WebSocket-Accept")
        return
    }

    // Frame loop
    var sentClose = false
    var inFragment = false
    var fragOpcode: UInt8 = 0
    var fragPayload: [UInt8] = []
    var expectingSHA1 = false

    do {
        while true {
            let frame = try readFrame(reader)

            switch frame.opcode {
            case 9: // Ping
                try sendFrame(fd: fd, opcode: 10, payload: frame.payload)

            case 10: // Pong – ignore
                break

            case 8: // Close
                var code = 1005
                var reason = ""
                if frame.payload.count >= 2 {
                    code = Int(frame.payload[0]) << 8 | Int(frame.payload[1])
                    if frame.payload.count > 2 {
                        reason = String(decoding: frame.payload[2...], as: UTF8.self)
                    }
                }
                if reason.isEmpty {
                    print("closed \(code)")
                } else {
                    print("closed \(code) \(reason)")
                }
                if !sentClose {
                    try sendCloseFrame(fd: fd, code: UInt16(code))
                }
                return

            case 1, 2: // Text / Binary
                if frame.fin {
                    if frame.opcode == 1 {
                        let txt = String(decoding: frame.payload, as: UTF8.self)
                        try processTextCommand(txt, fd: fd,
                                               expectingSHA1: &expectingSHA1,
                                               sentClose: &sentClose)
                    } else {
                        if expectingSHA1 {
                            let hex = sha1Hex(frame.payload)
                            try sendText(fd: fd, hex)
                            print("SHA1 \(frame.payload.count) -> \(hex)")
                            expectingSHA1 = false
                        }
                    }
                } else {
                    inFragment = true
                    fragOpcode = frame.opcode
                    fragPayload = frame.payload
                }

            case 0: // Continuation
                if inFragment {
                    fragPayload.append(contentsOf: frame.payload)
                    if frame.fin {
                        if fragOpcode == 1 {
                            let txt = String(decoding: fragPayload, as: UTF8.self)
                            try processTextCommand(txt, fd: fd,
                                                   expectingSHA1: &expectingSHA1,
                                                   sentClose: &sentClose)
                        } else if fragOpcode == 2 {
                            if expectingSHA1 {
                                let hex = sha1Hex(fragPayload)
                                try sendText(fd: fd, hex)
                                print("SHA1 \(fragPayload.count) -> \(hex)")
                                expectingSHA1 = false
                            }
                        }
                        inFragment = false
                        fragPayload = []
                    }
                }

            default:
                break
            }
        }
    } catch {
        // connection error – move on
    }
}

// MARK: - Main
let args = CommandLine.arguments
for (i, arg) in args.dropFirst().enumerated() {
    print("session \(i + 1)")
    guard let url = parseWSUrl(arg) else { continue }
    handleSession(url: url)
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <strings.h>
#include <stdint.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <CommonCrypto/CommonDigest.h>

/* ─── Base64 ─── */
static const char B64[] = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";

static void b64_encode(const uint8_t *data, size_t len, char *out) {
    size_t i, j;
    for (i = 0, j = 0; i < len; i += 3) {
        uint32_t n = (uint32_t)data[i] << 16;
        if (i + 1 < len) n |= (uint32_t)data[i + 1] << 8;
        if (i + 2 < len) n |= (uint32_t)data[i + 2];
        out[j++] = B64[(n >> 18) & 0x3F];
        out[j++] = B64[(n >> 12) & 0x3F];
        out[j++] = (i + 1 < len) ? B64[(n >> 6) & 0x3F] : '=';
        out[j++] = (i + 2 < len) ? B64[n & 0x3F] : '=';
    }
    out[j] = '\0';
}

/* ─── Buffered connection ─── */
typedef struct {
    int fd;
    uint8_t *buf;
    size_t buf_len, buf_pos, buf_cap;
} Conn;

static void conn_init(Conn *c, int fd) {
    c->fd = fd;
    c->buf_cap = 65536;
    c->buf = malloc(c->buf_cap);
    c->buf_len = c->buf_pos = 0;
}

static int ensure(Conn *c, size_t n) {
    while (c->buf_len - c->buf_pos < n) {
        if (c->buf_pos > 0) {
            memmove(c->buf, c->buf + c->buf_pos, c->buf_len - c->buf_pos);
            c->buf_len -= c->buf_pos;
            c->buf_pos = 0;
        }
        if (c->buf_len + n > c->buf_cap) {
            while (c->buf_cap < c->buf_len + n) c->buf_cap *= 2;
            c->buf = realloc(c->buf, c->buf_cap);
        }
        ssize_t r = read(c->fd, c->buf + c->buf_len, c->buf_cap - c->buf_len);
        if (r <= 0) return -1;
        c->buf_len += (size_t)r;
    }
    return 0;
}

static int write_all(int fd, const void *buf, size_t len) {
    const uint8_t *p = buf;
    while (len > 0) {
        ssize_t w = write(fd, p, len);
        if (w <= 0) return -1;
        p += w;
        len -= (size_t)w;
    }
    return 0;
}

/* ─── Send masked WebSocket frame ─── */
static void send_frame(Conn *c, int opcode, const uint8_t *payload, size_t len) {
    uint8_t hdr[14];
    size_t hlen = 0;
    hdr[hlen++] = (uint8_t)(0x80 | (opcode & 0x0F));
    if (len <= 125) {
        hdr[hlen++] = (uint8_t)(0x80 | len);
    } else if (len <= 65535) {
        hdr[hlen++] = 0x80 | 126;
        hdr[hlen++] = (uint8_t)((len >> 8) & 0xFF);
        hdr[hlen++] = (uint8_t)(len & 0xFF);
    } else {
        hdr[hlen++] = 0x80 | 127;
        for (int i = 7; i >= 0; i--)
            hdr[hlen++] = (uint8_t)(((uint64_t)len >> (i * 8)) & 0xFF);
    }
    uint8_t mask[4];
    do { arc4random_buf(mask, 4); } while (!mask[0] && !mask[1] && !mask[2] && !mask[3]);
    memcpy(hdr + hlen, mask, 4);
    hlen += 4;

    uint8_t *masked = malloc(len ? len : 1);
    for (size_t i = 0; i < len; i++)
        masked[i] = payload[i] ^ mask[i & 3];

    write_all(c->fd, hdr, hlen);
    if (len > 0) write_all(c->fd, masked, len);
    free(masked);
}

static void send_text(Conn *c, const char *text) {
    send_frame(c, 1, (const uint8_t *)text, strlen(text));
}

static void send_close(Conn *c, uint16_t code, const uint8_t *reason, size_t rlen) {
    uint8_t *p = malloc(2 + rlen);
    p[0] = (uint8_t)(code >> 8);
    p[1] = (uint8_t)(code & 0xFF);
    if (rlen) memcpy(p + 2, reason, rlen);
    send_frame(c, 8, p, 2 + rlen);
    free(p);
}

/* ─── Read a complete message (handles fragmentation, ping/pong) ─── */
/* Returns opcode (1=text,2=binary) or -1 on close/error.
   On close: *closed=1, *payload/*plen set. */
static int read_message(Conn *c, uint8_t **payload, size_t *plen, int *closed) {
    *closed = 0;
    *payload = NULL;
    *plen = 0;

    uint8_t *msg = NULL;
    size_t msg_len = 0, msg_cap = 0;
    int msg_opcode = -1;

    for (;;) {
        if (ensure(c, 2) < 0) return -1;
        uint8_t b0 = c->buf[c->buf_pos++];
        uint8_t b1 = c->buf[c->buf_pos++];
        int fin = (b0 >> 7) & 1;
        int opcode = b0 & 0x0F;
        int masked = (b1 >> 7) & 1;
        uint64_t len = b1 & 0x7F;

        if (len == 126) {
            if (ensure(c, 2) < 0) return -1;
            len = ((uint64_t)c->buf[c->buf_pos] << 8) | c->buf[c->buf_pos + 1];
            c->buf_pos += 2;
        } else if (len == 127) {
            if (ensure(c, 8) < 0) return -1;
            len = 0;
            for (int i = 0; i < 8; i++)
                len = (len << 8) | c->buf[c->buf_pos++];
        }

        if (masked) c->buf_pos += 4; /* skip mask key */

        if (len > 0 && ensure(c, (size_t)len) < 0) return -1;

        uint8_t *fp = c->buf + c->buf_pos;
        c->buf_pos += (size_t)len;
        size_t flen = (size_t)len;

        if (opcode == 9) { /* ping → pong */
            send_frame(c, 10, fp, flen);
            continue;
        }
        if (opcode == 10) continue; /* unsolicited pong */

        if (opcode == 8) { /* close */
            *closed = 1;
            *payload = malloc(flen + 1);
            memcpy(*payload, fp, flen);
            (*payload)[flen] = '\0';
            *plen = flen;
            free(msg);
            return -1;
        }

        if (opcode == 0) { /* continuation */
            if (msg_opcode < 0) continue;
            if (msg_len + flen > msg_cap) {
                msg_cap = (msg_len + flen) * 2 + 1;
                msg = realloc(msg, msg_cap);
            }
            memcpy(msg + msg_len, fp, flen);
            msg_len += flen;
            if (fin) {
                msg = realloc(msg, msg_len + 1);
                msg[msg_len] = '\0';
                *payload = msg;
                *plen = msg_len;
                return msg_opcode;
            }
        } else if (opcode == 1 || opcode == 2) {
            if (fin) {
                *payload = malloc(flen + 1);
                memcpy(*payload, fp, flen);
                (*payload)[flen] = '\0';
                *plen = flen;
                return opcode;
            } else {
                msg_opcode = opcode;
                msg_len = flen;
                msg_cap = flen * 2 + 1;
                msg = malloc(msg_cap);
                memcpy(msg, fp, flen);
            }
        }
    }
}

/* ─── UTF-8 decode / encode ─── */
static size_t utf8_decode(const uint8_t *in, size_t inlen, uint32_t **out) {
    size_t count = 0, cap = 16;
    uint32_t *arr = malloc(cap * sizeof(uint32_t));
    size_t i = 0;
    while (i < inlen) {
        uint32_t cp;
        int nb;
        if ((in[i] & 0x80) == 0)      { cp = in[i] & 0x7F; nb = 1; }
        else if ((in[i] & 0xE0) == 0xC0) { cp = in[i] & 0x1F; nb = 2; }
        else if ((in[i] & 0xF0) == 0xE0) { cp = in[i] & 0x0F; nb = 3; }
        else if ((in[i] & 0xF8) == 0xF0) { cp = in[i] & 0x07; nb = 4; }
        else { cp = in[i]; nb = 1; }
        for (int j = 1; j < nb && i + (size_t)j < inlen; j++)
            cp = (cp << 6) | (in[i + (size_t)j] & 0x3F);
        if (count >= cap) { cap *= 2; arr = realloc(arr, cap * sizeof(uint32_t)); }
        arr[count++] = cp;
        i += (size_t)nb;
    }
    *out = arr;
    return count;
}

static uint8_t *utf8_encode(const uint32_t *cps, size_t count, size_t *outlen) {
    size_t cap = count * 4 + 1, pos = 0;
    uint8_t *out = malloc(cap);
    for (size_t i = 0; i < count; i++) {
        uint32_t cp = cps[i];
        if (cp <= 0x7F) {
            out[pos++] = (uint8_t)cp;
        } else if (cp <= 0x7FF) {
            out[pos++] = (uint8_t)(0xC0 | (cp >> 6));
            out[pos++] = (uint8_t)(0x80 | (cp & 0x3F));
        } else if (cp <= 0xFFFF) {
            out[pos++] = (uint8_t)(0xE0 | (cp >> 12));
            out[pos++] = (uint8_t)(0x80 | ((cp >> 6) & 0x3F));
            out[pos++] = (uint8_t)(0x80 | (cp & 0x3F));
        } else {
            out[pos++] = (uint8_t)(0xF0 | (cp >> 18));
            out[pos++] = (uint8_t)(0x80 | ((cp >> 12) & 0x3F));
            out[pos++] = (uint8_t)(0x80 | ((cp >> 6) & 0x3F));
            out[pos++] = (uint8_t)(0x80 | (cp & 0x3F));
        }
    }
    out[pos] = '\0';
    *outlen = pos;
    return out;
}

/* ─── URL parsing ─── */
static void parse_url(const char *url, char *host, int *port, char *path) {
    const char *p = url + 5; /* skip "ws://" */
    const char *slash = strchr(p, '/');
    const char *colon = strchr(p, ':');

    if (colon && (!slash || colon < slash)) {
        size_t hl = (size_t)(colon - p);
        memcpy(host, p, hl);
        host[hl] = '\0';
        *port = atoi(colon + 1);
    } else {
        size_t hl = slash ? (size_t)(slash - p) : strlen(p);
        memcpy(host, p, hl);
        host[hl] = '\0';
        *port = 80;
    }
    if (slash) strcpy(path, slash);
    else       strcpy(path, "/");
}

/* ─── Main ─── */
int main(int argc, char *argv[]) {
    for (int sess = 1; sess < argc; sess++) {
        printf("session %d\n", sess);

        char host[256], path[4096];
        int port;
        parse_url(argv[sess], host, &port, path);

        struct sockaddr_in addr;
        memset(&addr, 0, sizeof(addr));
        addr.sin_family = AF_INET;
        addr.sin_port = htons((uint16_t)port);
        inet_pton(AF_INET, host, &addr.sin_addr);

        int fd = socket(AF_INET, SOCK_STREAM, 0);
        if (connect(fd, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
            close(fd);
            continue;
        }

        Conn c;
        conn_init(&c, fd);

        /* Generate Sec-WebSocket-Key */
        uint8_t key_raw[16];
        arc4random_buf(key_raw, 16);
        char ws_key[24];
        b64_encode(key_raw, 16, ws_key);

        /* Send HTTP upgrade */
        char req[8192];
        int rlen = snprintf(req, sizeof(req),
            "GET %s HTTP/1.1\r\n"
            "Host: %s:%d\r\n"
            "Upgrade: websocket\r\n"
            "Connection: Upgrade\r\n"
            "Sec-WebSocket-Version: 13\r\n"
            "Sec-WebSocket-Key: %s\r\n"
            "\r\n",
            path, host, port, ws_key);
        write_all(fd, req, (size_t)rlen);

        /* Read response header block */
        size_t hdr_end = 0;
        int found = 0;
        while (!found) {
            if (ensure(&c, 1) < 0) break;
            for (size_t i = c.buf_pos; i + 3 < c.buf_len; i++) {
                if (c.buf[i] == '\r' && c.buf[i+1] == '\n' &&
                    c.buf[i+2] == '\r' && c.buf[i+3] == '\n') {
                    hdr_end = i + 4;
                    found = 1;
                    break;
                }
            }
            if (!found) {
                /* need more data */
                if (c.buf_len == c.buf_cap) {
                    c.buf_cap *= 2;
                    c.buf = realloc(c.buf, c.buf_cap);
                }
                ssize_t r = read(c.fd, c.buf + c.buf_len, c.buf_cap - c.buf_len);
                if (r <= 0) break;
                c.buf_len += (size_t)r;
            }
        }

        if (!found) {
            printf("handshake failed: connection closed\n");
            close(fd); free(c.buf);
            continue;
        }

        size_t hlen = hdr_end - c.buf_pos;
        char *hdr_block = malloc(hlen + 1);
        memcpy(hdr_block, c.buf + c.buf_pos, hlen);
        hdr_block[hlen] = '\0';
        c.buf_pos = hdr_end;

        /* Parse status line */
        int status = 0;
        char reason_phrase[256] = "";
        {
            char *sp = strchr(hdr_block, ' ');
            if (sp) {
                status = atoi(sp + 1);
                char *sp2 = strchr(sp + 1, ' ');
                if (sp2) {
                    char *eol = strstr(sp2 + 1, "\r\n");
                    size_t rlen2 = eol ? (size_t)(eol - (sp2 + 1)) : strlen(sp2 + 1);
                    if (rlen2 >= sizeof(reason_phrase)) rlen2 = sizeof(reason_phrase) - 1;
                    memcpy(reason_phrase, sp2 + 1, rlen2);
                    reason_phrase[rlen2] = '\0';
                }
            }
        }

        if (status != 101) {
            printf("handshake failed: %d %s\n", status, reason_phrase);
            close(fd); free(c.buf); free(hdr_block);
            continue;
        }

        /* Validate Sec-WebSocket-Accept */
        char accept_input[256];
        snprintf(accept_input, sizeof(accept_input),
                 "%s258EAFA5-E914-47DA-95CA-C5AB0DC85B11", ws_key);
        uint8_t sha[20];
        CC_SHA1((const uint8_t *)accept_input, (CC_LONG)strlen(accept_input), sha);
        char expected_accept[32];
        b64_encode(sha, 20, expected_accept);

        char *accept_hdr = NULL;
        {
            char *line = hdr_block;
            /* skip status line */
            char *eol = strstr(line, "\r\n");
            if (eol) line = eol + 2;
            while (line && *line) {
                eol = strstr(line, "\r\n");
                if (!eol) break;
                size_t llen = (size_t)(eol - line);
                if (llen > 21 && strncasecmp(line, "Sec-WebSocket-Accept:", 21) == 0) {
                    accept_hdr = line + 21;
                    while (*accept_hdr == ' ') accept_hdr++;
                    char *end = line + llen;
                    while (end > accept_hdr && end[-1] == ' ') end--;
                    *end = '\0';
                    break;
                }
                line = eol + 2;
            }
        }

        if (!accept_hdr || strcmp(accept_hdr, expected_accept) != 0) {
            printf("handshake failed: bad Sec-WebSocket-Accept\n");
            close(fd); free(c.buf); free(hdr_block);
            continue;
        }
        free(hdr_block);

        /* ─── Frame processing loop ─── */
        int close_sent = 0;
        int waiting_sha1 = 0;

        for (;;) {
            uint8_t *payload;
            size_t plen;
            int closed;
            int opcode = read_message(&c, &payload, &plen, &closed);

            if (closed) {
                uint16_t code = 1005;
                if (plen >= 2)
                    code = (uint16_t)((payload[0] << 8) | payload[1]);
                if (plen > 2)
                    printf("closed %u %.*s\n", code, (int)(plen - 2), payload + 2);
                else
                    printf("closed %u\n", code);
                if (!close_sent)
                    send_close(&c, code, NULL, 0);
                free(payload);
                break;
            }

            if (opcode < 0) break; /* connection error */

            if (waiting_sha1) {
                uint8_t hash[20];
                CC_SHA1(payload, (CC_LONG)plen, hash);
                char hex[41];
                for (int i = 0; i < 20; i++)
                    sprintf(hex + i * 2, "%02x", hash[i]);
                hex[40] = '\0';
                send_text(&c, hex);
                printf("SHA1 %zu -> %s\n", plen, hex);
                waiting_sha1 = 0;
                free(payload);
                continue;
            }

            if (opcode == 1) { /* text command */
                if (plen >= 4 && memcmp(payload, "ADD ", 4) == 0) {
                    char *s = (char *)payload + 4;
                    char *sp = strchr(s, ' ');
                    long long a = strtoll(s, NULL, 10);
                    long long b = sp ? strtoll(sp + 1, NULL, 10) : 0;
                    long long sum = a + b;
                    char reply[64];
                    snprintf(reply, sizeof(reply), "%lld", sum);
                    send_text(&c, reply);
                    printf("ADD %.*s -> %s\n", (int)(plen - 4), (char *)payload + 4, reply);
                } else if (plen >= 4 && memcmp(payload, "REV ", 4) == 0) {
                    uint8_t *text = payload + 4;
                    size_t tlen = plen - 4;
                    uint32_t *cps;
                    size_t ncp = utf8_decode(text, tlen, &cps);
                    for (size_t i = 0; i < ncp / 2; i++) {
                        uint32_t tmp = cps[i];
                        cps[i] = cps[ncp - 1 - i];
                        cps[ncp - 1 - i] = tmp;
                    }
                    size_t revlen;
                    uint8_t *rev = utf8_encode(cps, ncp, &revlen);
                    send_frame(&c, 1, rev, revlen);
                    printf("REV %.*s -> %.*s\n", (int)tlen, (char *)text, (int)revlen, (char *)rev);
                    free(cps);
                    free(rev);
                } else if (plen == 4 && memcmp(payload, "SHA1", 4) == 0) {
                    waiting_sha1 = 1;
                } else if (plen == 3 && memcmp(payload, "BYE", 3) == 0) {
                    send_close(&c, 1000, NULL, 0);
                    close_sent = 1;
                }
            }

            free(payload);
        }

        close(fd);
        free(c.buf);
    }
    return 0;
}
